! climate.c:153
recursive function climate_readParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp), target :: x_l(0:5)
   real(dp), target :: y_l
   real(dp), target :: aDate
   integer(int8), target :: fname(0:259)
   integer(int64) :: dum1_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   x_l = 0.0_dp
   y_l = 0.0_dp
   aDate = 0.0_dp
   fname = 0_int8
   k_l = findmatch(tok_l(0), TempKeyWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(0))
      return
   end if
   select case (k_l)
   case (0)
      if (ntoks < 2) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = project_findObject(TSERIES_c, tok_l(1))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      Temp%dataSource = TSERIES_TEMP
      Temp%tSeries = i_l
      Tseries(i_l)%refersTo = TSERIES_TEMP
   case (1)
      if (ntoks < 2) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      Temp%dataSource = FILE_TEMP
      Fclimate%mode = USE_FILE
      dum1_ = sstrncpy(cview(fname), tok_l(1), 259_int64)
      dum1_ = sstrncpy(cview(Fclimate%name), addAbsolutePath(cview(fname)), 259_int64)
      Temp%fileStartDate = -693594.0_dp
      if (ntoks > 2) then
         if (cget(tok_l(2), 0) /= 42) then
            if (.not. (datetime_strToDate(tok_l(2), aDate) /= 0)) then
               res_ = error_setInpError(ERR_DATETIME, tok_l(2))
               return
            end if
            Temp%fileStartDate = aDate
         end if
      end if
      FileTempUnits = DEG_F
      if (UnitSystem == SI) then
         FileTempUnits = DEG_C
      end if
      if (ntoks > 3) then
         i_l = findmatch(tok_l(3), TempUnitsWords)
         if (i_l < 0) then
            res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
            return
         end if
         FileTempUnits = i_l
      end if
   case (2)
      if (strcomp(tok_l(1), lit_1) /= 0) then
         Wind%type = FILE_WIND
      else
         if (ntoks < 14) then
            res_ = error_setInpError(ERR_ITEMS, lit_0)
            return
         end if
         Wind%type = MONTHLY_WIND
         i_l = 0
         do while (i_l < 12)
            if (.not. (getDouble(tok_l(i_l + 2), y_l) /= 0)) then
               res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 2))
               return
            end if
            Wind%aws(i_l) = y_l
            i_l = i_l + 1
         end do
      end if
   case (3)
      if (ntoks < 7) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 1
      do while (i_l < 7)
         if (.not. (getDouble(tok_l(i_l), x_l(i_l - 1)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         i_l = i_l + 1
      end do
      if (UnitSystem == SI) then
         x_l(0) = ((9.0_dp / 5.0_dp) * x_l(0)) + 32.0_dp
      end if
      Snow%snotmp = x_l(0)
      Snow%tipm = x_l(1)
      Snow%rnm = x_l(2)
      Temp%elev = x_l(3) / UCF(LENGTH)
      Temp%anglat = x_l(4)
      Temp%dtlong = x_l(5) / 60.0_dp
   case (4)
      if (ntoks < 12) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (match(tok_l(1), lit_2) /= 0) then
         i_l = 0
      else if (match(tok_l(1), lit_3) /= 0) then
         i_l = 1
      else
         res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
         return
      end if
      j_l = 0
      do while (j_l < 10)
         if (((.not. (getDouble(tok_l(j_l + 2), y_l) /= 0)) .or. (y_l < 0.0_dp)) .or. (y_l > 1.0_dp)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(j_l + 2))
            return
         end if
         Snow%adc(j_l, i_l) = y_l
         j_l = j_l + 1
      end do
   end select
   res_ = 0
   return
end function climate_readParams

