recursive function climate_readEvapParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: k_l
   real(dp), target :: x_l
   res_ = 0
   i_l = 0
   k_l = 0
   x_l = 0.0_dp
   k_l = findmatch(tok_l(0), EvapTypeWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(0))
      return
   end if
   if (k_l == RECOVERY) then
      if (ntoks < 2) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = project_findObject(TIMEPATTERN, tok_l(1))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      Evap%recoveryPattern = i_l
      res_ = 0
      return
   end if
   if (k_l == DRYONLY) then
      if (ntoks < 2) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (strcomp(tok_l(1), lit_4) /= 0) then
         Evap%dryOnly = 0
      else if (strcomp(tok_l(1), lit_5) /= 0) then
         Evap%dryOnly = 1
      else
         res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
         return
      end if
      res_ = 0
      return
   end if
   Evap%type = k_l
   if ((k_l /= TEMPERATURE_EVAP) .and. (ntoks < 2)) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   select case (k_l)
   case (0)
      if (.not. (getDouble(tok_l(1), x_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(1))
         return
      end if
      i_l = 0
      do while (i_l < 12)
         Evap%monthlyEvap(i_l) = x_l
         i_l = i_l + 1
      end do
   case (1)
      if (ntoks < 13) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 0
      do while (i_l < 12)
         if (.not. (getDouble(tok_l(i_l + 1), Evap%monthlyEvap(i_l)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 1))
            return
         end if
         i_l = i_l + 1
      end do
   case (2)
      i_l = project_findObject(TSERIES_c, tok_l(1))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      Evap%tSeries = i_l
      Tseries(i_l)%refersTo = TIMESERIES_EVAP
   case (4)
      if (ntoks > 1) then
         if (ntoks < 13) then
            res_ = error_setInpError(ERR_ITEMS, lit_0)
            return
         end if
         i_l = 0
         do while (i_l < 12)
            if (.not. (getDouble(tok_l(i_l + 1), Evap%panCoeff(i_l)) /= 0)) then
               res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 1))
               return
            end if
            i_l = i_l + 1
         end do
      end if
   end select
   res_ = 0
   return
end function climate_readEvapParams

! climate.c:377
recursive function climate_readAdjustments(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
