   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   res_ = 0
   i_l = 0
   j_l = 0
   if (ntoks == 1) then
      res_ = 0
      return
   end if
   if (match(tok_l(0), lit_6) /= 0) then
      if (ntoks < 13) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 1
      do while (i_l < 13)
         if (.not. (getDouble(tok_l(i_l), Adjust%temp(i_l - 1)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
