         return
      end if
      i_l = 1
      do while (i_l < 13)
         if (.not. (getDouble(tok_l(i_l), Adjust%evap(i_l - 1)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         i_l = i_l + 1
      end do
      res_ = 0
