   end if
   if (match(tok_l(0), lit_8) /= 0) then
      if (ntoks < 13) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 1
      do while (i_l < 13)
         if (.not. (getDouble(tok_l(i_l), Adjust%rain(i_l - 1)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         i_l = i_l + 1
      end do
      res_ = 0
      return
   end if
   if (match(tok_l(0), lit_9) /= 0) then
      if (ntoks < 13) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 1
      do while (i_l < 13)
         if (.not. (getDouble(tok_l(i_l), Adjust%hydcon(i_l - 1)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         if (Adjust%hydcon(i_l - 1) <= 0.0_dp) then
            Adjust%hydcon(i_l - 1) = 1.0_dp
         end if
         i_l = i_l + 1
      end do
      res_ = 0
      return
   end if
   if (match(tok_l(0), lit_10) /= 0) then
      if (ntoks < 3) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = project_findObject(SUBCATCH_c, tok_l(1))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      j_l = project_findObject(TIMEPATTERN, tok_l(2))
      if (j_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
      Subcatch(i_l)%nPervPattern = j_l
      res_ = 0
      return
   end if
   if (match(tok_l(0), lit_11) /= 0) then
      if (ntoks < 3) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = project_findObject(SUBCATCH_c, tok_l(1))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      j_l = project_findObject(TIMEPATTERN, tok_l(2))
      if (j_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
      Subcatch(i_l)%dStorePattern = j_l
      res_ = 0
      return
   end if
   if (match(tok_l(0), lit_12) /= 0) then
      if (ntoks < 3) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = project_findObject(SUBCATCH_c, tok_l(1))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      j_l = project_findObject(TIMEPATTERN, tok_l(2))
      if (j_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
      Subcatch(i_l)%infilPattern = j_l
      res_ = 0
      return
   end if
   res_ = error_setInpError(ERR_KEYWORD, tok_l(0))
   return
end function climate_readAdjustments

! climate.c:480
recursive subroutine climate_validate()
   integer(int32) :: i_l
   real(dp) :: a_l
   real(dp) :: z_l
   real(dp) :: pa
   i_l = 0
   a_l = 0.0_dp
   z_l = 0.0_dp
   pa = 0.0_dp
   if (((Wind%type == FILE_WIND) .or. (Evap%type == FILE_EVAP)) .or. (Evap%type == TEMPERATURE_EVAP)) then
      if (Fclimate%mode == NO_FILE) then
         call report_writeErrorMsg(ERR_NO_CLIMATE_FILE, lit_0)
      end if
   end if
   if (Fclimate%mode == USE_FILE) then
      call climate_openFile()
   end if
   if ((((Snow%tipm < 0.0_dp) .or. (Snow%tipm > 1.0_dp)) .or. (Snow%rnm < 0.0_dp)) .or. (Snow%rnm > 1.0_dp)) then
      call report_writeErrorMsg(ERR_SNOWMELT_PARAMS, lit_0)
   end if
   a_l = Temp%anglat
   if ((a_l <= (-89.99_dp)) .or. (a_l >= 89.99_dp)) then
      call report_writeErrorMsg(ERR_SNOWMELT_PARAMS, lit_0)
   else
      Temp%tanAnglat = tan((a_l * 3.141592654_dp) / 180.0_dp)
   end if
   z_l = Temp%elev / 1000.0_dp
   if (z_l <= 0.0_dp) then
      pa = 29.9_dp
   else
      pa = (29.9_dp - (1.02_dp * z_l)) + (0.0032_dp * (z_l ** 2.4_dp))
   end if
   Temp%gamma = 0.000359_dp * pa
   i_l = 0
   do while (i_l < 12)
      if (UnitSystem == SI) then
         Adjust%temp(i_l) = Adjust%temp(i_l) * (9.0_dp / 5.0_dp)
      end if
      Adjust%evap(i_l) = Adjust%evap(i_l) / UCF(EVAPRATE)
      i_l = i_l + 1
   end do
end subroutine climate_validate

! climate.c:531
recursive subroutine climate_openFile()
   integer(int32) :: i_l
   integer(int32), target :: m_l
   integer(int32), target :: y_l
   integer(int64) :: dum1_
   i_l = 0
   m_l = 0
   y_l = 0
   Fclimate%file => c_fopen(cview(Fclimate%name), lit_13)
   if (.not. associated(Fclimate%file)) then
      call report_writeErrorMsg(ERR_CLIMATE_FILE_OPEN, cview(Fclimate%name))
      return
   end if
   FileValue(TMIN_c) = Temp%ta
   FileValue(TMAX_c) = Temp%ta
   FileValue(EVAP_c) = 0.0_dp
   FileValue(WIND_c) = 0.0_dp
   FileFormat = getFileFormat()
   if (FileFormat == UNKNOWN_FORMAT) then
      call report_writeErrorMsg(ERR_CLIMATE_FILE_READ, cview(Fclimate%name))
      return
   end if
   call c_rewind(Fclimate%file)
   dum1_ = sstrncpy(cview(FileLine), lit_0, 0_int64)
   if (Temp%fileStartDate == (-693594.0_dp)) then
      call datetime_decodeDate(StartDate, FileYear, FileMonth, FileDay)
   else
      call datetime_decodeDate(Temp%fileStartDate, FileYear, FileMonth, FileDay)
   end if
   do while (.not. (c_feof(Fclimate%file) /= 0))
      dum1_ = sstrncpy(cview(FileLine), lit_0, 0_int64)
      call readFileLine(y_l, m_l)
      if ((y_l == FileYear) .and. (m_l == FileMonth)) then
         exit
      end if
   end do
   if (c_feof(Fclimate%file) /= 0) then
      call report_writeErrorMsg(ERR_CLIMATE_END_OF_FILE, cview(Fclimate%name))
      return
   end if
   if (.not. (ErrorCode /= 0)) then
      FileElapsedDays = 0
      FileLastDay = datetime_daysPerMonth(FileYear, FileMonth)
      call readFileValues()
      i_l = TMIN_c
      do while (i_l <= WIND_c)
         if (FileData(FileDay, i_l) == (-10000000000.0_dp)) then
            goto 100
         end if
         FileValue(i_l) = FileData(FileDay, i_l)
         100 continue
         i_l = i_l + 1
      end do
   end if
end subroutine climate_openFile

! climate.c:598
recursive subroutine climate_initState()
   integer(int32) :: dum1_
   LastDay = -693594.0_dp
   Temp%tmax = -10000000000.0_dp
   Snow%removed = 0.0_dp
   NextEvapDate = StartDate
   NextEvapRate = 0.0_dp
   if ((Evap%type == TIMESERIES_EVAP) .and. (Evap%tSeries >= 0)) then
      dum1_ = table_getFirstEntry(Tseries(Evap%tSeries), NextEvapDate, NextEvapRate)
      if (NextEvapDate < StartDate) then
         call setNextEvapDate(StartDate)
      end if
      Evap%rate = NextEvapRate / UCF(EVAPRATE)
      call setNextEvapDate(NextEvapDate)
   end if
   if (Evap%type == TEMPERATURE_EVAP) then
      Tma%maxCount = int(56_int64 / 8_int64, int32)
      Tma%count = 0
      Tma%front = 0
      Tma%tAve = 0.0_dp
      Tma%tRng = 0.0_dp
   end if
end subroutine climate_initState

! climate.c:641
recursive subroutine climate_setState(theDate)
   real(dp), value :: theDate
   if (Fclimate%mode == USE_FILE) then
      call updateFileValues(theDate)
   end if
   if (Temp%dataSource /= NO_TEMP) then
      call setTemp(theDate)
   end if
   call setEvap(theDate)
   call setWind(theDate)
   Adjust%rainFactor = Adjust%rain(datetime_monthOfYear(theDate) - 1)
   Adjust%hydconFactor = Adjust%hydcon(datetime_monthOfYear(theDate) - 1)
   call setNextEvapDate(theDate)
end subroutine climate_setState

! climate.c:659
recursive function climate_getNextEvapDate() result(res_)
   real(dp) :: res_
   res_ = 0.0_dp
   res_ = NextEvapDate
   return
end function climate_getNextEvapDate

! climate.c:671
recursive subroutine setNextEvapDate(theDate)
   real(dp), value :: theDate
   integer(int32), target :: yr
   integer(int32), target :: mon
   integer(int32), target :: day
   integer(int32) :: k_l
   real(dp), target :: d_l
   real(dp), target :: e_l
   yr = 0
   mon = 0
   day = 0
   k_l = 0
   d_l = 0.0_dp
   e_l = 0.0_dp
   if (NextEvapDate > theDate) then
      return
   end if
   select case (Evap%type)
   case (0)
      NextEvapDate = theDate + 365.0_dp
   case (1)
      call datetime_decodeDate(theDate, yr, mon, day)
      if (mon == 12) then
         mon = 1
         yr = yr + 1
      else
         mon = mon + 1
      end if
      NextEvapDate = datetime_encodeDate(yr, mon, 1)
   case (2)
      k_l = Evap%tSeries
      if (k_l >= 0) then
         NextEvapDate = theDate + 365.0_dp
         do while ((table_getNextEntry(Tseries(k_l), d_l, e_l) /= 0) .and. (d_l <= EndDateTime))
            if (d_l >= theDate) then
               NextEvapDate = d_l
               NextEvapRate = e_l
               exit
            end if
         end do
      end if
   case (4)
      NextEvapDate = cfloor(theDate) + 1.0_dp
   case default
      NextEvapDate = theDate + 365.0_dp
   end select
end subroutine setNextEvapDate

! climate.c:734
recursive subroutine updateFileValues(theDate)
   real(dp), value :: theDate
   integer(int32) :: i_l
   integer(int32) :: deltaDays
   i_l = 0
   deltaDays = 0
   deltaDays = d2i(cfloor(theDate) - cfloor(StartDateTime))
   if (deltaDays > FileElapsedDays) then
      FileElapsedDays = FileElapsedDays + 1
      FileDay = FileDay + 1
      if (FileDay > FileLastDay) then
         FileMonth = FileMonth + 1
         if (FileMonth > 12) then
            FileMonth = 1
            FileYear = FileYear + 1
         end if
         call readFileValues()
         FileDay = 1
         FileLastDay = datetime_daysPerMonth(FileYear, FileMonth)
      end if
      i_l = TMIN_c
      do while (i_l <= WIND_c)
         if (FileData(FileDay, i_l) == (-10000000000.0_dp)) then
            goto 100
         end if
         FileValue(i_l) = FileData(FileDay, i_l)
         100 continue
         i_l = i_l + 1
      end do
   end if
end subroutine updateFileValues

! climate.c:782
recursive subroutine setTemp(theDate)
   real(dp), value :: theDate
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: mon
   integer(int32) :: day
   real(dp) :: theDay
   real(dp) :: hour
   real(dp) :: tmp_l
   j_l = 0
   k_l = 0
   mon = 0
   day = 0
   theDay = 0.0_dp
   hour = 0.0_dp
   tmp_l = 0.0_dp
   mon = datetime_monthOfYear(theDate)
   theDay = cfloor(theDate)
   if (theDay > LastDay) then
      day = datetime_dayOfYear(theDate)
      if (Temp%dataSource == FILE_TEMP) then
         Tmin = FileValue(TMIN_c) + Adjust%temp(mon - 1)
         Tmax = FileValue(TMAX_c) + Adjust%temp(mon - 1)
         if (Tmin > Tmax) then
            tmp_l = Tmin
            Tmin = Tmax
            Tmax = tmp_l
         end if
         call updateTempTimes(day)
         if (Evap%type == TEMPERATURE_EVAP) then
            call updateTempMoveAve(Tmin, Tmax)
            FileValue(EVAP_c) = getTempEvap(day, Tma%tAve, Tma%tRng)
         end if
      end if
      Snow%season = sin(0.0172615_dp * (real(day, dp) - 81.0_dp))
      j_l = 0
      do while (j_l < Nobjects(SNOWMELT_c))
         call snow_setMeltCoeffs(j_l, Snow%season)
         j_l = j_l + 1
      end do
      LastDay = theDate
   end if
   if (Temp%dataSource == FILE_TEMP) then
      hour = (theDate - theDay) * 24.0_dp
      if (hour < Hrsr) then
         Temp%ta = Tmin + ((Trng1 / 2.0_dp) * sin((3.141592654_dp / Dydif) * (Hrsr - hour)))
      else if ((hour >= Hrsr) .and. (hour <= Hrss)) then
         Temp%ta = Tave + (Trng * sin((3.141592654_dp / Dhrdy) * (Hrday - hour)))
      else
         Temp%ta = Tmax - (Trng * sin((3.141592654_dp / Dydif) * (hour - Hrss)))
      end if
   end if
   if (Temp%dataSource == TSERIES_TEMP) then
      k_l = Temp%tSeries
      if (k_l >= 0) then
         Temp%ta = table_tseriesLookup(Tseries(k_l), theDate, 1)
         if (UnitSystem == SI) then
            Temp%ta = ((9.0_dp / 5.0_dp) * Temp%ta) + 32.0_dp
         end if
         Temp%ta = Temp%ta + Adjust%temp(mon - 1)
      end if
   end if
   Temp%ea = 8.1175e6_dp * exp((-7701.544_dp) / (Temp%ta + 405.0265_dp))
end subroutine setTemp

! climate.c:872
recursive subroutine setEvap(theDate)
   real(dp), value :: theDate
   integer(int32) :: k_l
   integer(int32) :: mon
   logical :: b1_
   k_l = 0
   mon = datetime_monthOfYear(theDate)
   select case (Evap%type)
   case (0)
      Evap%rate = Evap%monthlyEvap(0) / UCF(EVAPRATE)
   case (1)
      Evap%rate = Evap%monthlyEvap(mon - 1) / UCF(EVAPRATE)
   case (2)
      if (theDate >= NextEvapDate) then
         Evap%rate = NextEvapRate / UCF(EVAPRATE)
      end if
   case (4)
      Evap%rate = FileValue(EVAP_c) / UCF(EVAPRATE)
      Evap%rate = Evap%rate * Evap%panCoeff(mon - 1)
   case (3)
      Evap%rate = FileValue(EVAP_c) / UCF(EVAPRATE)
   case default
      Evap%rate = 0.0_dp
   end select
   Evap%rate = Evap%rate + Adjust%evap(mon - 1)
   Evap%recoveryFactor = 1.0_dp
   k_l = Evap%recoveryPattern
   b1_ = k_l >= 0
   if (b1_) then
      b1_ = Pattern(k_l)%type == MONTHLY_PATTERN
   end if
   if (b1_) then
      Evap%recoveryFactor = Pattern(k_l)%factor(mon - 1)
   end if
end subroutine setEvap

! climate.c:923
recursive subroutine setWind(theDate)
   real(dp), value :: theDate
   integer(int32), target :: yr
   integer(int32), target :: mon
   integer(int32), target :: day
   yr = 0
   mon = 0
   day = 0
   select case (Wind%type)
   case (0)
      call datetime_decodeDate(theDate, yr, mon, day)
      Wind%ws = Wind%aws(mon - 1) / UCF(WINDSPEED)
   case (1)
      Wind%ws = FileValue(WIND_c)
   case default
      Wind%ws = 0.0_dp
   end select
end subroutine setWind

! climate.c:949
recursive subroutine updateTempTimes(day)
   integer(int32), value :: day
   real(dp) :: decl
   real(dp) :: hrang
   real(dp) :: arg
   decl = 0.0_dp
   hrang = 0.0_dp
   arg = 0.0_dp
   decl = 0.40928_dp * cos(0.017202_dp * (172.0_dp - real(day, dp)))
   arg = (-tan(decl)) * Temp%tanAnglat
   if (arg <= (-1.0_dp)) then
      arg = 3.141592654_dp
   else if (arg >= 1.0_dp) then
      arg = 0.0_dp
   else
      arg = acos(arg)
   end if
   hrang = 3.8197_dp * arg
   Hrsr = (12.0_dp - hrang) + Temp%dtlong
   Hrss = ((12.0_dp + hrang) + Temp%dtlong) - 3.0_dp
   Dhrdy = Hrsr - Hrss
   Dydif = (24.0_dp + Hrsr) - Hrss
   Hrday = (Hrsr + Hrss) / 2.0_dp
   Tave = (Tmin + Tmax) / 2.0_dp
   Trng = (Tmax - Tmin) / 2.0_dp
   if (Temp%tmax == (-10000000000.0_dp)) then
      Trng1 = Tmax - Tmin
   else
      Trng1 = Temp%tmax - Tmin
   end if
   Temp%tmax = Tmax
end subroutine updateTempTimes

! climate.c:981
recursive function getTempEvap(day, tave_l, trng_l) result(res_)
   integer(int32), value :: day
   real(dp), value :: tave_l
   real(dp), value :: trng_l
   real(dp) :: res_
   real(dp) :: a_l
   real(dp) :: ta
   real(dp) :: tr
   real(dp) :: lamda
   real(dp) :: dr
   real(dp) :: phi_l
   real(dp) :: del
   real(dp) :: omega_l
   real(dp) :: ra
   real(dp) :: e_l
   res_ = 0.0_dp
   a_l = (2.0_dp * 3.141592654_dp) / 365.0_dp
   ta = ((tave_l - 32.0_dp) * 5.0_dp) / 9.0_dp
   tr = (trng_l * 5.0_dp) / 9.0_dp
   lamda = 2.50_dp - (0.002361_dp * ta)
   dr = 1.0_dp + (0.033_dp * cos(a_l * real(day, dp)))
   phi_l = ((Temp%anglat * 2.0_dp) * 3.141592654_dp) / 360.0_dp
   del = 0.4093_dp * sin(a_l * (284.0_dp + real(day, dp)))
   omega_l = acos((-tan(phi_l)) * tan(del))
   ra = (37.6_dp * dr) * (((omega_l * sin(phi_l)) * sin(del)) + ((cos(phi_l) * cos(del)) * sin(omega_l)))
   e_l = (((0.0023_dp * ra) / lamda) * sqrt(tr)) * (ta + 17.8_dp)
   if (e_l < 0.0_dp) then
      e_l = 0.0_dp
   end if
   if (UnitSystem == US) then
      e_l = e_l / 25.4_dp
   end if
   res_ = e_l
   return
end function getTempEvap

! climate.c:1010
recursive function getFileFormat() result(res_)
   integer(int32) :: res_
   integer(int8), target :: recdType(0:3)
   integer(int8), target :: elemType(0:3)
   integer(int8), target :: filler(0:4)
   integer(int8), target :: staID(0:79)
   integer(int8), target :: s_l(0:79)
   integer(int8), target :: line(0:1023)
   integer(int32), target :: y_l
   integer(int32), target :: m_l
   integer(int32), target :: d_l
   integer(int32) :: n_l
   integer(int64) :: dum1_
   logical :: b2_
   type(CPtr) :: s3_
   type(CPtr) :: s4_
   res_ = 0
   call cinit(recdType, lit_0)
   call cinit(elemType, lit_0)
   call cinit(filler, lit_0)
   staID = 0_int8
   s_l = 0_int8
   line = 0_int8
   y_l = 0
   m_l = 0
   d_l = 0
   n_l = 0
   if (cisnull(c_fgets(cview(line), 1024, Fclimate%file))) then
      res_ = UNKNOWN_FORMAT
      return
   end if
   dum1_ = sstrncpy(cview(recdType), cview(line), 3_int64)
   dum1_ = sstrncpy(cview(filler), cadd(cview(line), 23), 4_int64)
   b2_ = c_strcmp(cview(recdType), lit_14) == 0
   if (b2_) then
      b2_ = c_strcmp(cview(filler), lit_15) == 0
   end if
   if (b2_) then
      res_ = TD3200
      return
   end if
   if (strlen(cview(line)) >= 233_int64) then
      dum1_ = sstrncpy(cview(elemType), cadd(cview(line), 13), 3_int64)
      n_l = c_atoi(cview(elemType))
      if (((n_l == 1) .or. (n_l == 2)) .or. (n_l == 151)) then
         res_ = DLY0204
         return
      end if
   end if
   s3_ = cview(staID)
   s4_ = cview(s_l)
   n_l = c_sscanf(cview(line), lit_16, s3_, y_l, m_l, d_l, s4_)
   if (n_l == 5) then
      res_ = USER_PREPARED
      return
   end if
   if (isGhcndFormat(cview(line)) /= 0) then
      res_ = GHCND
      return
   end if
   res_ = UNKNOWN_FORMAT
   return
end function getFileFormat

! climate.c:1055
recursive subroutine readFileLine(y_l, m_l)
   integer(int32), intent(inout), target :: y_l
   integer(int32), intent(inout), target :: m_l
   do while (strlen(cview(FileLine)) == 0_int64)
      if (cisnull(c_fgets(cview(FileLine), 1024, Fclimate%file))) then
         return
      end if
      if (int(FileLine(0), int32) == 10) then
         FileLine(0) = c8(0)
      end if
   end do
   select case (FileFormat)
   case (1)
      call readUserFileLine(y_l, m_l)
   case (3)
      call readTD3200FileLine(y_l, m_l)
   case (4)
      call readDLY0204FileLine(y_l, m_l)
   case (2)
