! climate.c:1164
recursive subroutine readFileValues()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32), target :: y_l
   integer(int32), target :: m_l
   integer(int64) :: dum1_
   i_l = 0
   j_l = 0
   y_l = 0
   m_l = 0
   i_l = 0
   do while (i_l < MAXCLIMATEVARS)
      j_l = 0
      do while (j_l < MAXDAYSPERMONTH)
         FileData(j_l, i_l) = -10000000000.0_dp
         j_l = j_l + 1
      end do
      i_l = i_l + 1
   end do
   do while (.not. (ErrorCode /= 0))
      if (c_feof(Fclimate%file) /= 0) then
         return
      end if
      call readFileLine(y_l, m_l)
      if ((y_l > FileYear) .or. (m_l > FileMonth)) then
         return
      end if
      select case (FileFormat)
      case (1)
         call parseUserFileLine()
      case (3)
         call parseTD3200FileLine()
      case (4)
         call parseDLY0204FileLine()
      case (2)
         call parseGhcndFileLine()
      end select
      dum1_ = sstrncpy(cview(FileLine), lit_0, 0_int64)
   end do
end subroutine readFileValues

! climate.c:1201
