! climate.c:1271
recursive subroutine setTD3200FileValues(i_l)
   integer(int32), value :: i_l
   integer(int8), target :: valCount(0:3)
   integer(int8), target :: day(0:2)
   integer(int8), target :: sign_l(0:1)
   integer(int8), target :: value_l(0:5)
   integer(int8), target :: flag2(0:1)
   real(dp) :: x_l
   integer(int32) :: nValues
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: d_l
   integer(int64) :: dum1_
   logical :: b2_
   logical :: b3_
   call cinit(valCount, lit_0)
   call cinit(day, lit_0)
   call cinit(sign_l, lit_0)
   call cinit(value_l, lit_0)
   call cinit(flag2, lit_0)
   x_l = 0.0_dp
   nValues = 0
   j_l = 0
   k_l = 0
   d_l = 0
   dum1_ = sstrncpy(cview(valCount), cadd(cview(FileLine), 27), 3_int64)
   nValues = c_atoi(cview(valCount))
   if (int(strlen(cview(FileLine)), int32) >= ((12 * nValues) + 30)) then
      j_l = 0
      do while (j_l < nValues)
         k_l = 30 + (j_l * 12)
         dum1_ = sstrncpy(cview(day), cadd(cview(FileLine), k_l), 2_int64)
         dum1_ = sstrncpy(cview(sign_l), cadd(cview(FileLine), k_l + 4), 1_int64)
         dum1_ = sstrncpy(cview(value_l), cadd(cview(FileLine), k_l + 5), 5_int64)
         dum1_ = sstrncpy(cview(flag2), cadd(cview(FileLine), k_l + 11), 1_int64)
         d_l = c_atoi(cview(day))
         b3_ = c_strcmp(cview(value_l), lit_19) /= 0
         if (b3_) then
            b2_ = int(flag2(0), int32) == 48
            if (.not. b2_) then
               b2_ = int(flag2(0), int32) == 49
            end if
            b3_ = b2_
         end if
         if ((b3_ .and. (d_l > 0)) .and. (d_l <= 31)) then
            x_l = c_atof(cview(value_l))
            if (int(sign_l(0), int32) == 45) then
               x_l = -x_l
            end if
            if (i_l == EVAP_c) then
               x_l = x_l / 100.0_dp
               if (UnitSystem == SI) then
                  x_l = x_l * 25.4_dp
               end if
            end if
            if (i_l == WIND_c) then
               x_l = x_l / 24.0_dp
            end if
            FileData(d_l, i_l) = x_l
         end if
         j_l = j_l + 1
      end do
   end if
end subroutine setTD3200FileValues

! climate.c:1336
recursive subroutine parseDLY0204FileLine()
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   integer(int8), target :: param(0:3)
   integer(int8), target :: sign_l(0:1)
   integer(int8), target :: value_l(0:5)
   integer(int8), target :: code(0:1)
   real(dp) :: x_l
   integer(int64) :: dum1_
   logical :: b2_
   j_l = 0
   k_l = 0
   p_l = 0
   call cinit(param, lit_0)
   call cinit(sign_l, lit_0)
   call cinit(value_l, lit_0)
   call cinit(code, lit_0)
   x_l = 0.0_dp
   dum1_ = sstrncpy(cview(param), cadd(cview(FileLine), 13), 3_int64)
   p_l = c_atoi(cview(param))
   if (p_l == 1) then
      p_l = TMAX_c
   else if (p_l == 2) then
      p_l = TMIN_c
   else if (p_l == 151) then
      p_l = EVAP_c
   else
      return
   end if
   if (strlen(cview(FileLine)) < 233_int64) then
      return
   end if
   k_l = 16
   j_l = 1
   do while (j_l <= 31)
      dum1_ = sstrncpy(cview(sign_l), cadd(cview(FileLine), k_l), 1_int64)
      dum1_ = sstrncpy(cview(value_l), cadd(cview(FileLine), k_l + 1), 5_int64)
      dum1_ = sstrncpy(cview(code), cadd(cview(FileLine), k_l + 6), 1_int64)
      k_l = k_l + 7
      b2_ = c_strcmp(cview(value_l), lit_19) /= 0
      if (b2_) then
         b2_ = c_strcmp(cview(value_l), lit_20) /= 0
      end if
      if (b2_) then
         select case (p_l)
         case (1, 0)
            x_l = c_atof(cview(value_l)) / 10.0_dp
            if (int(sign_l(0), int32) == 45) then
               x_l = -x_l
            end if
            x_l = ((9.0_dp / 5.0_dp) * x_l) + 32.0_dp
         case (2)
            x_l = c_atof(cview(value_l)) / 10.0_dp
            if (UnitSystem == US) then
               x_l = x_l / 25.4_dp
            end if
         case default
            return
         end select
         FileData(j_l, p_l) = x_l
      end if
      j_l = j_l + 1
   end do
end subroutine parseDLY0204FileLine

! climate.c:1401
recursive function isGhcndFormat(line) result(res_)
   type(CPtr), value :: line
   integer(int32) :: res_
   integer(int32) :: i_l
   type(CPtr) :: ptr
   res_ = 0
   i_l = 0
   ptr = cnull()
   ptr = c_strstr(line, lit_21)
   if (cisnull(ptr)) then
      res_ = 0
      return
   end if
   FileDateFieldPos = int(cdiff(ptr, line), int32)
   i_l = TMIN_c
   do while (i_l <= WIND_c)
      FileFieldPos(i_l) = -1
      i_l = i_l + 1
   end do
   ptr = c_strstr(line, lit_22)
   if (.not. cisnull(ptr)) then
      FileFieldPos(TMIN_c) = int(cdiff(ptr, line), int32)
   end if
   ptr = c_strstr(line, lit_23)
   if (.not. cisnull(ptr)) then
      FileFieldPos(TMAX_c) = int(cdiff(ptr, line), int32)
   end if
   ptr = c_strstr(line, lit_7)
   if (.not. cisnull(ptr)) then
      FileFieldPos(EVAP_c) = int(cdiff(ptr, line), int32)
   end if
   FileWindType = WDMV
   ptr = c_strstr(line, lit_24)
   if (cisnull(ptr)) then
      FileWindType = AWND
      ptr = c_strstr(line, lit_25)
   end if
   if (.not. cisnull(ptr)) then
      FileFieldPos(WIND_c) = int(cdiff(ptr, line), int32)
   end if
   i_l = TMIN_c
   do while (i_l <= WIND_c)
      if (FileFieldPos(i_l) >= 0) then
         res_ = 1
         return
      end if
      i_l = i_l + 1
   end do
   res_ = 0
   return
end function isGhcndFormat

! climate.c:1445
recursive subroutine readGhcndFileLine(y_l, m_l)
   integer(int32), intent(inout), target :: y_l
   integer(int32), intent(inout), target :: m_l
   integer(int32) :: n_l
   n_l = c_sscanf(cadd(cview(FileLine), FileDateFieldPos), lit_26, y_l, m_l)
   if (n_l /= 2) then
      y_l = -99999
      m_l = -99999
   end if
end subroutine readGhcndFileLine

! climate.c:1463
recursive subroutine parseGhcndFileLine()
   integer(int32), target :: y_l
   integer(int32), target :: m_l
   integer(int32), target :: d_l
   integer(int32) :: n_l
   integer(int32) :: i_l
   real(dp), target :: v_l
   y_l = 0
   m_l = 0
   d_l = 0
   n_l = 0
   i_l = 0
   v_l = 0.0_dp
   n_l = c_sscanf(cadd(cview(FileLine), FileDateFieldPos), lit_27, y_l, m_l, d_l)
   if (n_l < 3) then
      return
   end if
   if ((d_l < 1) .or. (d_l > 31)) then
      return
   end if
   i_l = TMIN_c
   do while (i_l <= WIND_c)
      if (FileFieldPos(i_l) >= 0) then
         if (c_sscanf(cadd(cview(FileLine), FileFieldPos(i_l)), lit_28, v_l) > 0) then
            if (abs(v_l) < 9999.0_dp) then
               FileData(d_l, i_l) = convertGhcndValue(i_l, v_l)
            end if
         end if
      end if
      i_l = i_l + 1
   end do
end subroutine parseGhcndFileLine

! climate.c:1496
recursive function convertGhcndValue(var, v_l) result(res_)
   integer(int32), value :: var
   real(dp), value :: v_l
   real(dp) :: res_
   res_ = 0.0_dp
   select case (var)
   case (0, 1)
      goto 101
   case (2)
      goto 102
   case (3)
      goto 103
   case default
      goto 104
   end select
   101 continue
   select case (FileTempUnits)
   case (0)
      res_ = (((v_l / 10.0_dp) * 9.0_dp) / 5.0_dp) + 32.0_dp
      return
   case (1)
      res_ = ((v_l * 9.0_dp) / 5.0_dp) + 32.0_dp
      return
   case default
      res_ = v_l
      return
   end select
   102 continue
   select case (FileTempUnits)
   case (0)
      v_l = v_l / 10.0_dp
      if (UnitSystem == US) then
         v_l = v_l / 25.4_dp
      end if
      res_ = v_l
      return
   case (1)
      if (UnitSystem == US) then
         v_l = v_l / 25.4_dp
      end if
      res_ = v_l
      return
   case default
      if (UnitSystem == SI) then
         v_l = v_l * 25.4_dp
      end if
      res_ = v_l
      return
   end select
   103 continue
   select case (FileTempUnits)
   case (0)
      if (FileWindType == WDMV) then
         res_ = (v_l * 0.62137_dp) / 24.0_dp
         return
      else
         res_ = (((v_l / 10.0_dp) / 1000.0_dp) * 0.62137_dp) * 3600.0_dp
         return
      end if
   case (1)
      if (FileWindType == WDMV) then
         res_ = (v_l * 0.62137_dp) / 24.0_dp
         return
      else
         res_ = ((v_l / 1000.0_dp) * 0.62137_dp) * 3600.0_dp
         return
      end if
   case default
      if (FileWindType == WDMV) then
         res_ = v_l / 24.0_dp
         return
      else
         res_ = v_l
         return
      end if
   end select
   104 continue
   res_ = v_l
   return
end function convertGhcndValue

! climate.c:1569
recursive subroutine updateTempMoveAve(tmin_l, tmax_l)
   real(dp), value :: tmin_l
   real(dp), value :: tmax_l
   real(dp) :: ta
   real(dp) :: tr
   integer(int32) :: kount
   real(dp) :: count_l
   ta = 0.0_dp
   tr = 0.0_dp
   kount = Tma%count
   count_l = real(kount, dp)
   ta = (tmin_l + tmax_l) / 2.0_dp
   tr = abs(tmax_l - tmin_l)
   if (kount == Tma%maxCount) then
      Tma%tAve = (((Tma%tAve * count_l) + ta) - Tma%ta(Tma%front)) / count_l
      Tma%tRng = (((Tma%tRng * count_l) + tr) - Tma%tr(Tma%front)) / count_l
      Tma%ta(Tma%front) = ta
      Tma%tr(Tma%front) = tr
      Tma%front = Tma%front + 1
      if (real(Tma%front, dp) == count_l) then
         Tma%front = 0
      end if
   else
      Tma%tAve = ((Tma%tAve * count_l) + ta) / (count_l + 1.0_dp)
      Tma%tRng = ((Tma%tRng * count_l) + tr) / (count_l + 1.0_dp)
      Tma%ta(Tma%front) = ta
      Tma%tr(Tma%front) = tr
      Tma%count = Tma%count + 1
      Tma%front = Tma%front + 1
      if (Tma%count == Tma%maxCount) then
         Tma%front = 0
      end if
   end if
end subroutine updateTempMoveAve

