! controls.c:257
recursive function controls_create(n_l) result(res_)
   integer(int32), value :: n_l
   integer(int32) :: res_
   integer(int32) :: r_l
   res_ = 0
   r_l = 0
   nullify(ActionList)
   InputState = r_PRIORITY
   RuleCount = n_l
   if (RuleCount > 0) then
      allocate(Rules(0:int(RuleCount, int64) - 1))
      if (.not. associated(Rules)) then
         res_ = ERR_MEMORY
         return
      end if
      r_l = 0
      do while (r_l < RuleCount)
         Rules(r_l)%ID = cnull()
         nullify(Rules(r_l)%firstPremise)
         nullify(Rules(r_l)%lastPremise)
         nullify(Rules(r_l)%thenActions)
         nullify(Rules(r_l)%elseActions)
         Rules(r_l)%priority = 0.0_dp
         r_l = r_l + 1
      end do
   end if
   CurrentVariable = -1
   CurrentExpression = -1
   if (VariableCount > 0) then
      allocate(NamedVariable(0:int(VariableCount, int64) - 1))
      if (.not. associated(NamedVariable)) then
         res_ = ERR_MEMORY
         return
      end if
   end if
   if (ExpressionCount > 0) then
      allocate(Expression(0:int(ExpressionCount, int64) - 1))
      if (.not. associated(Expression)) then
         res_ = ERR_MEMORY
         return
      end if
   end if
   res_ = 0
   return
end function controls_create

! controls.c:302
recursive subroutine controls_delete()
   integer(int32) :: i_l
   i_l = 0
   i_l = 0
   do while (i_l < ExpressionCount)
      call mathexpr_delete(Expression(i_l)%expression)
      nullify(Expression(i_l)%expression)
      i_l = i_l + 1
   end do
   if (associated(Expression)) then
      ! 
      nullify(Expression)
   end if
   if (associated(NamedVariable)) then
      ! 
      nullify(NamedVariable)
   end if
   if (RuleCount == 0) then
      return
   end if
   call deleteActionList()
   call deleteRules()
end subroutine controls_delete

! controls.c:326
recursive function controls_addVariable(tok_l, nToks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: nToks
   integer(int32) :: res_
   type(TVariable), target :: v1
   integer(int32), target :: k_l
   integer(int32) :: err_l
   integer(int64) :: dum1_
   res_ = 0
   v1 = zero_TVariable
   k_l = 0
   err_l = 0
   CurrentVariable = CurrentVariable + 1
   if (nToks < 5) then
      res_ = ERR_ITEMS
      return
   end if
   if (findExactMatch(tok_l(1), AttribWords) >= 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   if (.not. (match(tok_l(2), lit_31) /= 0)) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(2))
      return
   end if
   if ((.not. (match(tok_l(3), lit_32) /= 0)) .and. (nToks < 6)) then
      res_ = ERR_ITEMS
      return
   end if
   k_l = 3
   err_l = getPremiseVariable(tok_l, nToks, k_l, v1)
   if (err_l > 0) then
      res_ = err_l
      return
   end if
   k_l = CurrentVariable
   NamedVariable(k_l)%variable = v1
   dum1_ = sstrncpy(cview(NamedVariable(k_l)%name), tok_l(1), 32_int64)
   res_ = 0
   return
end function controls_addVariable

! controls.c:357
recursive function controls_addExpression(tok_l, nToks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: nToks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int8), target :: s_l(0:1024)
   type(MathExpr), pointer :: expr
   integer(int64) :: dum1_
   res_ = 0
   i_l = 0
   k_l = 0
   s_l = 0_int8
   nullify(expr)
   CurrentExpression = CurrentExpression + 1
   if (nToks < 4) then
      res_ = ERR_ITEMS
      return
   end if
   k_l = CurrentExpression
   nullify(Expression(k_l)%expression)
   dum1_ = sstrncpy(cview(Expression(k_l)%name), tok_l(1), 32_int64)
   dum1_ = sstrncpy(cview(s_l), tok_l(3), 1024_int64)
   i_l = 4
   do while (i_l < nToks)
      dum1_ = sstrcat(cview(s_l), lit_33, 1024_int64)
      dum1_ = sstrcat(cview(s_l), tok_l(i_l), 1024_int64)
      i_l = i_l + 1
   end do
   expr => mathexpr_create(cview(s_l), getVariableIndex)
   if (.not. associated(expr)) then
      res_ = error_setInpError(ERR_MATH_EXPR, lit_0)
      return
   end if
   Expression(k_l)%expression => expr
   res_ = 0
