! controls.c:439
recursive function controls_addRuleClause(r_l, keyword, tok_l, nToks) result(res_)
   integer(int32), value :: r_l
   integer(int32), value :: keyword
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: nToks
   integer(int32) :: res_
   res_ = 0
   select case (keyword)
   case (0)
      if (cisnull(Rules(r_l)%ID)) then
         Rules(r_l)%ID = project_findID(CONTROL, tok_l(1))
      end if
      InputState = r_RULE
      if (nToks > 2) then
         res_ = ERR_RULE
         return
      end if
      res_ = 0
      return
   case (1)
      if (InputState /= r_RULE) then
         res_ = ERR_RULE
         return
      end if
      InputState = r_IF
      res_ = addPremise(r_l, r_AND, tok_l, nToks)
      return
   case (2)
      if (InputState == r_IF) then
         res_ = addPremise(r_l, r_AND, tok_l, nToks)
         return
      else if ((InputState == r_THEN) .or. (InputState == r_ELSE)) then
         res_ = addAction(r_l, tok_l, nToks)
         return
      else
         res_ = ERR_RULE
         return
      end if
   case (3)
      if (InputState /= r_IF) then
         res_ = ERR_RULE
         return
      end if
      res_ = addPremise(r_l, r_OR, tok_l, nToks)
      return
   case (4)
      if (InputState /= r_IF) then
         res_ = ERR_RULE
         return
      end if
      InputState = r_THEN
      res_ = addAction(r_l, tok_l, nToks)
      return
   case (5)
      if (InputState /= r_THEN) then
         res_ = ERR_RULE
         return
      end if
      InputState = r_ELSE
      res_ = addAction(r_l, tok_l, nToks)
      return
   case (6)
      if ((InputState /= r_THEN) .and. (InputState /= r_ELSE)) then
         res_ = ERR_RULE
         return
      end if
      InputState = r_PRIORITY
      if (.not. (getDouble(tok_l(1), Rules(r_l)%priority) /= 0)) then
         res_ = ERR_NUMBER
         return
      end if
      if (nToks > 2) then
         res_ = ERR_RULE
         return
      end if
      res_ = 0
      return
   end select
   res_ = 0
   return
end function controls_addRuleClause

! controls.c:495
recursive function controls_evaluate(currentTime_l, elapsedTime_l, tStep) result(res_)
   real(dp), value :: currentTime_l
   real(dp), value :: elapsedTime_l
   real(dp), value :: tStep
   integer(int32) :: res_
   integer(int32) :: r_l
   integer(int32) :: result_l
   type(TPremise), pointer :: p_l
   type(TAction), pointer :: a_l
   res_ = 0
   r_l = 0
   result_l = 0
   nullify(p_l)
   nullify(a_l)
   CurrentDate = cfloor(currentTime_l)
   CurrentTime = currentTime_l - cfloor(currentTime_l)
   ElapsedTime = elapsedTime_l
   if (RuleCount == 0) then
      res_ = 0
      return
   end if
   call clearActionList()
   r_l = 0
   do while (r_l < RuleCount)
      result_l = 1
      p_l => Rules(r_l)%firstPremise
      do while (associated(p_l))
         if (p_l%type == r_OR) then
            if (result_l == 0) then
               result_l = evaluatePremise(p_l, tStep)
            end if
         else
            if (result_l == 0) then
               exit
            end if
            result_l = evaluatePremise(p_l, tStep)
         end if
         p_l => p_l%next
      end do
      if (result_l == 1) then
         a_l => Rules(r_l)%thenActions
      else
         a_l => Rules(r_l)%elseActions
      end if
      do while (associated(a_l))
         call updateActionValue(a_l, currentTime_l, tStep)
         call updateActionList(a_l)
         a_l => a_l%next
      end do
      r_l = r_l + 1
   end do
   if (associated(ActionList)) then
      res_ = executeActionList(currentTime_l)
      return
   else
      res_ = 0
      return
   end if
end function controls_evaluate

! controls.c:556
recursive function addPremise(r_l, type_l, tok_l, nToks) result(res_)
   integer(int32), value :: r_l
   integer(int32), value :: type_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: nToks
   integer(int32) :: res_
   integer(int32) :: relation
   integer(int32), target :: n_l
   integer(int32) :: err_l
   real(dp), target :: value_l
   type(TPremise), pointer :: p_l
   type(TVariable), target :: v1
   type(TVariable), target :: v2
   integer(int32) :: obj
   integer(int32) :: exprIndex
   integer(int32) :: varIndex
   logical :: b1_
   res_ = 0
   relation = 0
   n_l = 0
   err_l = 0
   value_l = -10000000000.0_dp
   nullify(p_l)
   v1 = zero_TVariable
   v2 = zero_TVariable
   obj = 0
   exprIndex = 0
   varIndex = -1
   if (nToks < 4) then
      res_ = ERR_ITEMS
      return
   end if
   v1%attribute = -1
   v1%object = -1
   v1%index = -1
   n_l = 1
   exprIndex = getExpressionIndex(tok_l(1))
   if (exprIndex < 0) then
      varIndex = getVariableIndex(tok_l(n_l))
      if (varIndex >= 0) then
         v1 = NamedVariable(varIndex)%variable
      else
         err_l = getPremiseVariable(tok_l, nToks, n_l, v1)
         if (err_l > 0) then
            res_ = err_l
            return
         end if
      end if
   end if
   n_l = n_l + 1
   if (n_l >= nToks) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   relation = findExactMatch(tok_l(n_l), RelOpWords)
   if (relation < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
      return
   end if
   v2%attribute = -1
   v2%object = -1
   v2%index = -1
   n_l = n_l + 1
   if (n_l >= nToks) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   varIndex = getVariableIndex(tok_l(n_l))
   if (varIndex >= 0) then
      v2 = NamedVariable(varIndex)%variable
   else
      obj = findmatch(tok_l(n_l), ObjectWords)
      if (obj >= 0) then
         err_l = getPremiseVariable(tok_l, nToks, n_l, v2)
         if (err_l > 0) then
            res_ = ERR_RULE
            return
         end if
         if ((exprIndex < 0) .and. (v1%attribute /= v2%attribute)) then
            call report_writeWarningMsg(lit_34, Rules(r_l)%ID)
         end if
      else
         err_l = getPremiseValue(tok_l(n_l), v1%attribute, value_l)
         if (err_l > 0) then
            res_ = err_l
            return
         end if
      end if
   end if
   n_l = n_l + 1
   b1_ = n_l < nToks
   if (b1_) then
      b1_ = findmatch(tok_l(n_l), RuleKeyWords) >= 0
   end if
   if (b1_) then
      res_ = ERR_RULE
      return
   end if
   allocate(p_l)
   if (.not. associated(p_l)) then
      res_ = ERR_MEMORY
      return
   end if
   p_l%type = type_l
   p_l%exprIndex = exprIndex
   p_l%lhsVar = v1
   p_l%rhsVar = v2
   p_l%relation = relation
   p_l%value = value_l
   nullify(p_l%next)
   if (.not. associated(Rules(r_l)%firstPremise)) then
      Rules(r_l)%firstPremise => p_l
   else
      Rules(r_l)%lastPremise%next => p_l
   end if
   Rules(r_l)%lastPremise => p_l
   res_ = 0
   return
end function addPremise

! controls.c:668
recursive function getPremiseVariable(tok_l, nToks, k_l, v_l) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: nToks
   integer(int32), intent(inout), target :: k_l
   type(TVariable), pointer, intent(in) :: v_l
   integer(int32) :: res_
   integer(int32) :: n_l
   integer(int32) :: object
   integer(int32) :: index_l
   integer(int32) :: obj
   integer(int32) :: attrib
   res_ = 0
   n_l = k_l
   object = -1
   index_l = -1
   obj = 0
   attrib = 0
   obj = findmatch(tok_l(n_l), ObjectWords)
   if (obj < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
      return
   end if
   n_l = n_l + 1
   if (n_l >= nToks) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   select case (obj)
   case (0)
      index_l = project_findObject(GAGE_c, tok_l(n_l))
      if (index_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(n_l))
         return
      end if
      object = r_GAGE
   case (1)
      index_l = project_findObject(NODE_c, tok_l(n_l))
      if (index_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(n_l))
         return
      end if
      object = r_NODE
   case (2, 3, 4, 5, 6, 7)
      index_l = project_findObject(LINK_c, tok_l(n_l))
      if (index_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(n_l))
         return
      end if
      object = r_LINK
   case default
      n_l = n_l - 1
   end select
   n_l = n_l + 1
   if (n_l >= nToks) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   if (object == r_GAGE) then
      attrib = getGageAttrib(tok_l(n_l))
   else
      attrib = findmatch(tok_l(n_l), AttribWords)
   end if
   if (attrib < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
      return
   end if
   if (obj == r_GAGE) then
   else if (obj == r_NODE) then
      select case (attrib)
      case (0, 1, 2, 3, 4)
      case default
         res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
         return
      end select
   else if (((object == r_LINK) .and. (index_l >= 0)) .and. ((attrib == r_TIMEOPEN) .or. (attrib == r_TIMECLOSED))) then
   else if ((obj == r_LINK) .or. (obj == r_CONDUIT)) then
      select case (attrib)
      case (8, 0, 6, 7, 5, 10, 11, 12)
      case default
         res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
         return
      end select
   else if (obj == r_PUMP) then
      select case (attrib)
      case (5, 9, 8)
      case default
         res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
         return
      end select
   else if (((obj == r_ORIFICE) .or. (obj == r_WEIR)) .or. (obj == r_OUTLET)) then
      select case (attrib)
      case (5, 9)
      case default
         res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
         return
      end select
   else
      select case (attrib)
      case (15, 16, 17, 19, 20, 18)
      case default
         res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
         return
      end select
   end if
   v_l%object = object
   v_l%index = index_l
   v_l%attribute = attrib
   k_l = n_l
   res_ = 0
   return
end function getPremiseVariable

! controls.c:797
recursive function getGageAttrib(token_l) result(res_)
   type(CPtr), value :: token_l
   integer(int32) :: res_
   integer(int32) :: attrib
   res_ = 0
   attrib = 0
   if (match(token_l, IntensityWord) /= 0) then
      res_ = 0
      return
   end if
   attrib = c_atoi(token_l)
   if ((attrib < 1) .or. (attrib > 48)) then
      res_ = -1
      return
   end if
   res_ = attrib
   return
end function getGageAttrib

! controls.c:824
recursive function getPremiseValue(token_l, attrib, value_l) result(res_)
   type(CPtr), value :: token_l
   integer(int32), value :: attrib
   real(dp), intent(inout), target :: value_l
   integer(int32) :: res_
   integer(int8), target :: strDate(0:24)
   logical :: b1_
   logical :: b2_
   integer(int64) :: dum3_
   logical :: b4_
   logical :: b5_
   logical :: b6_
   logical :: b7_
   res_ = 0
   strDate = 0_int8
   select case (attrib)
   case (8)
      value_l = real(findmatch(token_l, StatusWords), dp)
      if (value_l < 0.0_dp) then
         value_l = real(findmatch(token_l, ConduitWords), dp)
      end if
      if (value_l < 0.0_dp) then
         res_ = error_setInpError(ERR_KEYWORD, token_l)
         return
      end if
   case (15, 17, 13, 14)
      if (.not. (datetime_strToTime(token_l, value_l) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, token_l)
         return
      end if
   case (16)
      if (.not. (datetime_strToDate(token_l, value_l) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, token_l)
         return
      end if
   case (19)
      if (.not. (getDouble(token_l, value_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, token_l)
         return
      end if
      b1_ = value_l < 1.0_dp
      if (.not. b1_) then
         b1_ = value_l > 7.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_DATETIME, token_l)
         return
      end if
   case (20)
      if (.not. (getDouble(token_l, value_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, token_l)
         return
      end if
      b2_ = value_l < 1.0_dp
      if (.not. b2_) then
         b2_ = value_l > 12.0_dp
      end if
      if (b2_) then
         res_ = error_setInpError(ERR_DATETIME, token_l)
         return
      end if
   case (18)
      dum3_ = sstrncpy(cview(strDate), token_l, 6_int64)
      dum3_ = sstrcat(cview(strDate), lit_35, 25_int64)
      if (datetime_strToDate(cview(strDate), value_l) /= 0) then
         value_l = real(datetime_dayOfYear(value_l), dp)
      else
         b6_ = .not. (getDouble(token_l, value_l) /= 0)
         if (.not. b6_) then
            b6_ = value_l < 1.0_dp
         end if
         b7_ = b6_
         if (.not. b7_) then
            b7_ = value_l > 365.0_dp
         end if
         if (b7_) then
            res_ = error_setInpError(ERR_DATETIME, token_l)
            return
         end if
      end if
   case default
      if (.not. (getDouble(token_l, value_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, token_l)
         return
      end if
   end select
   res_ = 0
   return
end function getPremiseValue

! controls.c:889
recursive function addAction(r_l, tok_l, nToks) result(res_)
   integer(int32), value :: r_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: nToks
   integer(int32) :: res_
   integer(int32) :: obj
   integer(int32) :: link_l
   integer(int32), target :: attrib
   integer(int32), target :: curve_l
   integer(int32), target :: tseries_l
   integer(int32) :: n_l
   integer(int32) :: err_l
   real(dp), target :: values(0:2)
   type(TAction), pointer :: a_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0
   obj = 0
   link_l = 0
   attrib = 0
   curve_l = -1
   tseries_l = -1
   n_l = 0
   err_l = 0
   values = 0.0_dp
   values(0:2) = [1.0_dp, 0.0_dp, 0.0_dp]
   nullify(a_l)
   if (nToks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   obj = findmatch(tok_l(1), ObjectWords)
   if ((((((obj /= r_LINK) .and. (obj /= r_CONDUIT)) .and. (obj /= r_PUMP)) .and. (obj /= r_ORIFICE)) .and. (obj /= r_WEIR)) .and. (obj /= r_OUTLET)) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   link_l = project_findObject(LINK_c, tok_l(2))
   if (link_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   select case (obj)
   case (3)
      if (Link(link_l)%type /= CONDUIT_c) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
   case (4)
      if (Link(link_l)%type /= PUMP_c) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
   case (5)
      if (Link(link_l)%type /= ORIFICE_c) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
   case (6)
      if (Link(link_l)%type /= WEIR_c) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
   case (7)
      if (Link(link_l)%type /= OUTLET_c) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
   end select
   attrib = findmatch(tok_l(3), AttribWords)
   if (attrib < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
      return
   end if
   if (obj == r_CONDUIT) then
      if (attrib == r_STATUS) then
         values(0) = real(findmatch(tok_l(5), ConduitWords), dp)
         if (values(0) < 0.0_dp) then
            res_ = error_setInpError(ERR_KEYWORD, tok_l(5))
            return
         end if
      else
         res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
         return
      end if
   else if (obj == r_PUMP) then
      if (attrib == r_STATUS) then
         values(0) = real(findmatch(tok_l(5), StatusWords), dp)
         if (values(0) < 0.0_dp) then
            res_ = error_setInpError(ERR_KEYWORD, tok_l(5))
            return
         end if
      else if (attrib == r_SETTING) then
         err_l = setActionSetting(tok_l, nToks, curve_l, tseries_l, attrib, values)
         if (err_l > 0) then
            res_ = err_l
            return
         end if
      else
         res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
         return
      end if
   else if (((obj == r_ORIFICE) .or. (obj == r_WEIR)) .or. (obj == r_OUTLET)) then
      if (attrib == r_SETTING) then
         err_l = setActionSetting(tok_l, nToks, curve_l, tseries_l, attrib, values)
         if (err_l > 0) then
            res_ = err_l
            return
         end if
         b2_ = attrib == r_SETTING
         if (b2_) then
            b1_ = values(0) < 0.0_dp
            if (.not. b1_) then
               b1_ = values(0) > 1.0_dp
            end if
            b2_ = b1_
         end if
         if (b2_) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(5))
            return
         end if
      else
         res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
         return
      end if
   else
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   n_l = 6
   if ((curve_l >= 0) .or. (tseries_l >= 0)) then
      n_l = 7
   end if
   if (attrib == r_PID) then
      n_l = 9
   end if
   b3_ = n_l < nToks
   if (b3_) then
      b3_ = findmatch(tok_l(n_l), RuleKeyWords) >= 0
   end if
   if (b3_) then
      res_ = ERR_RULE
      return
   end if
   allocate(a_l)
   if (.not. associated(a_l)) then
      res_ = ERR_MEMORY
      return
   end if
   a_l%rule = r_l
   a_l%link = link_l
   a_l%attribute = attrib
   a_l%curve = curve_l
   a_l%tseries = tseries_l
   a_l%value = values(0)
   if (attrib == r_PID) then
      a_l%kp = values(0)
      a_l%ki = values(1)
      a_l%kd = values(2)
      a_l%e1 = 0.0_dp
      a_l%e2 = 0.0_dp
   end if
   if (InputState == r_THEN) then
      a_l%next => Rules(r_l)%thenActions
      Rules(r_l)%thenActions => a_l
   else
      a_l%next => Rules(r_l)%elseActions
      Rules(r_l)%elseActions => a_l
   end if
   res_ = 0
   return
end function addAction

! controls.c:1028
recursive function setActionSetting(tok_l, nToks, curve_l, tseries_l, attrib, values) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: nToks
   integer(int32), intent(inout), target :: curve_l
   integer(int32), intent(inout), target :: tseries_l
   integer(int32), intent(inout), target :: attrib
   real(dp), pointer, intent(in) :: values(:)
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32) :: m_l
   res_ = 0
   k_l = 0
   m_l = 0
   if (nToks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   k_l = findmatch(tok_l(5), SettingTypeWords)
   if ((k_l >= 0) .and. (nToks < 7)) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   select case (k_l)
   case (0)
      m_l = project_findObject(CURVE_c, tok_l(6))
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(6))
         return
      end if
      curve_l = m_l
   case (1)
      m_l = project_findObject(TSERIES_c, tok_l(6))
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(6))
         return
      end if
      tseries_l = m_l
      Tseries(m_l)%refersTo = CONTROL
   case (2)
      if (nToks < 9) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      m_l = 6
      do while (m_l <= 8)
         if (.not. (getDouble(tok_l(m_l), values(m_l - 6)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(m_l))
            return
         end if
         m_l = m_l + 1
      end do
      attrib = r_PID
   case default
      if (.not. (getDouble(tok_l(5), values(0)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
   end select
   res_ = 0
   return
end function setActionSetting

! controls.c:1086
recursive subroutine updateActionValue(a_l, currentTime_l, dt_l)
   type(TAction), pointer, intent(in) :: a_l
   real(dp), value :: currentTime_l
   real(dp), value :: dt_l
   if (a_l%curve >= 0) then
      a_l%value = table_lookup(Curve(a_l%curve), ControlValue)
   else if (a_l%tseries >= 0) then
      a_l%value = table_tseriesLookup(Tseries(a_l%tseries), currentTime_l, 1)
   else if (a_l%attribute == r_PID) then
      a_l%value = getPIDSetting(a_l, dt_l)
   end if
end subroutine updateActionValue

! controls.c:1111
recursive function getPIDSetting(a_l, dt_l) result(res_)
   type(TAction), pointer, intent(in) :: a_l
   real(dp), value :: dt_l
   real(dp) :: res_
   real(dp) :: e0
   real(dp) :: setting
   real(dp) :: p_l
   real(dp) :: i_l
   real(dp) :: d_l
   real(dp) :: update
   real(dp) :: tolerance
   res_ = 0.0_dp
   e0 = 0.0_dp
   setting = 0.0_dp
   p_l = 0.0_dp
   i_l = 0.0_dp
   d_l = 0.0_dp
   update = 0.0_dp
   tolerance = 0.0001_dp
   dt_l = dt_l * 1440.0_dp
   e0 = SetPoint - ControlValue
   if (abs(e0) > 1.0e-06_dp) then
      if (SetPoint /= 0.0_dp) then
         e0 = e0 / SetPoint
      else
         e0 = e0 / ControlValue
      end if
   end if
   if (abs(e0 - a_l%e1) < tolerance) then
      a_l%e2 = 0.0_dp
      a_l%e1 = 0.0_dp
   end if
   p_l = e0 - a_l%e1
   if (a_l%ki == 0.0_dp) then
      i_l = 0.0_dp
   else
      i_l = (e0 * dt_l) / a_l%ki
   end if
   d_l = (a_l%kd * ((e0 - (2.0_dp * a_l%e1)) + a_l%e2)) / dt_l
   update = a_l%kp * ((p_l + i_l) + d_l)
   if (abs(update) < tolerance) then
      update = 0.0_dp
   end if
   setting = Link(a_l%link)%targetSetting + update
   a_l%e2 = a_l%e1
   a_l%e1 = e0
   if (setting < 0.0_dp) then
      setting = 0.0_dp
   end if
   if ((Link(a_l%link)%type /= PUMP_c) .and. (setting > 1.0_dp)) then
      setting = 1.0_dp
   end if
   res_ = setting
   return
end function getPIDSetting

! controls.c:1168
recursive subroutine updateActionList(a_l)
   type(TAction), pointer, intent(in) :: a_l
   type(TActionList), pointer :: listItem
   type(TAction), pointer :: a1
   real(dp) :: priority
   nullify(listItem)
   nullify(a1)
   priority = Rules(a_l%rule)%priority
   listItem => ActionList
   do while (associated(listItem))
      a1 => listItem%action
      if (.not. associated(a1)) then
         exit
      end if
      if (a1%link == a_l%link) then
         if (priority > Rules(a1%rule)%priority) then
            listItem%action => a_l
         end if
         return
      end if
      listItem => listItem%next
   end do
   if (.not. associated(listItem)) then
      allocate(listItem)
      listItem%next => ActionList
      ActionList => listItem
   end if
   listItem%action => a_l
end subroutine updateActionList

! controls.c:1206
recursive function executeActionList(currentTime_l) result(res_)
   real(dp), value :: currentTime_l
   integer(int32) :: res_
   type(TActionList), pointer :: listItem
   type(TActionList), pointer :: nextItem
   type(TAction), pointer :: a1
   integer(int32) :: count_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0
   nullify(listItem)
   nullify(nextItem)
   nullify(a1)
   count_l = 0
   listItem => ActionList
   do while (associated(listItem))
      a1 => listItem%action
      if (.not. associated(a1)) then
         exit
      end if
      if (a1%link >= 0) then
         if (Link(a1%link)%targetSetting /= a1%value) then
            Link(a1%link)%targetSetting = a1%value
            b1_ = RptFlags%controls /= 0
            if (b1_) then
               b1_ = a1%curve < 0
            end if
            b2_ = b1_
            if (b2_) then
               b2_ = a1%tseries < 0
            end if
            b3_ = b2_
            if (b3_) then
               b3_ = a1%attribute /= r_PID
            end if
            if (b3_) then
               call report_writeControlAction(currentTime_l, Link(a1%link)%ID, a1%value, Rules(a1%rule)%ID)
            end if
            count_l = count_l + 1
         end if
      end if
      nextItem => listItem%next
      listItem => nextItem
   end do
   res_ = count_l
   return
end function executeActionList

! controls.c:1243
recursive function evaluatePremise(p_l, tStep) result(res_)
   type(TPremise), pointer, intent(in) :: p_l
   real(dp), value :: tStep
   integer(int32) :: res_
   real(dp) :: lhsValue
   real(dp) :: rhsValue
   integer(int32) :: result_l
   res_ = 0
   lhsValue = 0.0_dp
   rhsValue = 0.0_dp
   result_l = 0
   if (p_l%exprIndex >= 0) then
      lhsValue = mathexpr_eval(Expression(p_l%exprIndex)%expression, getNamedVariableValue)
   else
      lhsValue = getVariableValue(p_l%lhsVar)
   end if
   if (p_l%value == (-10000000000.0_dp)) then
      rhsValue = getVariableValue(p_l%rhsVar)
   else
      rhsValue = p_l%value
   end if
   if ((lhsValue == (-10000000000.0_dp)) .or. (rhsValue == (-10000000000.0_dp))) then
      res_ = 0
      return
   end if
   select case (p_l%lhsVar%attribute)
   case (15, 17)
      res_ = compareTimes(lhsValue, p_l%relation, rhsValue, tStep / 2.0_dp)
      return
   case (13, 14)
      result_l = compareTimes(lhsValue, p_l%relation, rhsValue, tStep / 2.0_dp)
      ControlValue = lhsValue * 24.0_dp
      res_ = result_l
      return
   case default
      res_ = compareValues(lhsValue, p_l%relation, rhsValue)
      return
   end select
end function evaluatePremise

! controls.c:1286
recursive function getVariableValue(v_l) result(res_)
   type(TVariable), value :: v_l
   real(dp) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   res_ = 0.0_dp
   i_l = -1
   j_l = -1
   if (v_l%object == r_GAGE) then
      res_ = getRainValue(v_l)
      return
   end if
   if (v_l%object == r_NODE) then
      i_l = v_l%index
   end if
   if (v_l%object == r_LINK) then
      j_l = v_l%index
   end if
   select case (v_l%attribute)
   case (15)
      goto 101
   case (16)
      goto 102
   case (17)
      goto 103
   case (19)
      goto 104
   case (20)
      goto 105
   case (18)
      goto 106
   case (8)
      goto 107
   case (9)
      goto 108
   case (5)
      goto 109
   case (6, 7, 12, 10, 11)
      goto 110
   case (0)
      goto 111
   case (1)
      goto 112
   case (2)
      goto 113
   case (3)
      goto 114
   case (4)
      goto 115
   case (13)
      goto 116
   case (14)
      goto 117
   case default
      goto 118
   end select
   101 continue
   res_ = ElapsedTime
   return
   102 continue
   res_ = CurrentDate
   return
   103 continue
   res_ = CurrentTime
   return
   104 continue
   res_ = real(datetime_dayOfWeek(CurrentDate), dp)
   return
   105 continue
   res_ = real(datetime_monthOfYear(CurrentDate), dp)
   return
   106 continue
   res_ = real(datetime_dayOfYear(CurrentDate), dp)
   return
   107 continue
   b2_ = j_l < 0
   if (.not. b2_) then
      b1_ = Link(j_l)%type /= CONDUIT_c
      if (b1_) then
         b1_ = Link(j_l)%type /= PUMP_c
      end if
      b2_ = b1_
   end if
   if (b2_) then
      res_ = -10000000000.0_dp
      return
   else
      res_ = Link(j_l)%setting
      return
   end if
   108 continue
   b5_ = j_l < 0
   if (.not. b5_) then
      b3_ = Link(j_l)%type /= PUMP_c
      if (b3_) then
         b3_ = Link(j_l)%type /= ORIFICE_c
      end if
      b4_ = b3_
      if (b4_) then
         b4_ = Link(j_l)%type /= WEIR_c
      end if
      b5_ = b4_
   end if
   if (b5_) then
      res_ = -10000000000.0_dp
      return
   else
      res_ = Link(j_l)%setting
      return
   end if
   109 continue
   if (j_l < 0) then
      res_ = -10000000000.0_dp
      return
   else
      res_ = (real(Link(j_l)%direction, dp) * Link(j_l)%newFlow) * UCF(FLOW)
      return
   end if
   110 continue
   if (j_l < 0) then
      res_ = -10000000000.0_dp
      return
   else if (Link(j_l)%type /= CONDUIT_c) then
      res_ = -10000000000.0_dp
      return
   end if
   select case (v_l%attribute)
   case (6)
      res_ = Link(j_l)%qFull * UCF(FLOW)
      return
   case (7)
      res_ = Link(j_l)%xsect%yFull * UCF(LENGTH)
      return
   case (12)
      res_ = link_getVelocity(j_l, Link(j_l)%newFlow, Link(j_l)%newDepth) * UCF(LENGTH)
      return
   case (10)
      res_ = Conduit(Link(j_l)%subIndex)%length * UCF(LENGTH)
      return
   case (11)
      res_ = Conduit(Link(j_l)%subIndex)%slope
      return
   case default
      res_ = -10000000000.0_dp
      return
   end select
   111 continue
   if (j_l >= 0) then
      res_ = Link(j_l)%newDepth * UCF(LENGTH)
      return
   else if (i_l >= 0) then
      res_ = Node(i_l)%newDepth * UCF(LENGTH)
      return
   else
      res_ = -10000000000.0_dp
      return
   end if
   112 continue
   if (i_l >= 0) then
      res_ = Node(i_l)%fullDepth * UCF(LENGTH)
      return
   else
      res_ = -10000000000.0_dp
      return
   end if
   113 continue
   if (i_l < 0) then
      res_ = -10000000000.0_dp
      return
   end if
   res_ = (Node(i_l)%newDepth + Node(i_l)%invertElev) * UCF(LENGTH)
   return
   114 continue
   if (i_l < 0) then
      res_ = -10000000000.0_dp
      return
   end if
   res_ = Node(i_l)%newVolume * UCF(VOLUME)
   return
   115 continue
   if (i_l < 0) then
      res_ = -10000000000.0_dp
      return
   else
      res_ = Node(i_l)%newLatFlow * UCF(FLOW)
      return
   end if
   116 continue
   if (j_l < 0) then
      res_ = -10000000000.0_dp
      return
   end if
   if (Link(j_l)%setting <= 0.0_dp) then
      res_ = -10000000000.0_dp
      return
   end if
   res_ = (CurrentDate + CurrentTime) - Link(j_l)%timeLastSet
   return
   117 continue
   if (j_l < 0) then
      res_ = -10000000000.0_dp
      return
   end if
   if (Link(j_l)%setting > 0.0_dp) then
      res_ = -10000000000.0_dp
      return
   end if
   res_ = (CurrentDate + CurrentTime) - Link(j_l)%timeLastSet
   return
   118 continue
   res_ = -10000000000.0_dp
   return
end function getVariableValue

! controls.c:1388
recursive function getRainValue(v_l) result(res_)
   type(TVariable), value :: v_l
   real(dp) :: res_
   res_ = 0.0_dp
   if (v_l%index < 0) then
      res_ = -10000000000.0_dp
      return
   else if (Gage(v_l%index)%isUsed == 0) then
      res_ = 0.0_dp
      return
   else if (v_l%attribute == 0) then
      res_ = Gage(v_l%index)%rainfall
      return
   else
      res_ = gage_getPastRain(v_l%index, v_l%attribute)
      return
   end if
end function getRainValue

! controls.c:1405
recursive function compareTimes(lhsValue, relation, rhsValue, halfStep) result(res_)
   real(dp), value :: lhsValue
   integer(int32), value :: relation
   real(dp), value :: rhsValue
   real(dp), value :: halfStep
   integer(int32) :: res_
   res_ = 0
   if (relation == EQ) then
      if ((lhsValue >= (rhsValue - halfStep)) .and. (lhsValue < (rhsValue + halfStep))) then
         res_ = 1
         return
      end if
      res_ = 0
      return
   else if (relation == NE) then
      if ((lhsValue < (rhsValue - halfStep)) .or. (lhsValue >= (rhsValue + halfStep))) then
         res_ = 1
         return
      end if
      res_ = 0
      return
   else
      res_ = compareValues(lhsValue, relation, rhsValue)
      return
   end if
end function compareTimes

! controls.c:1432
recursive function compareValues(lhsValue, relation, rhsValue) result(res_)
   real(dp), value :: lhsValue
   integer(int32), value :: relation
   real(dp), value :: rhsValue
   integer(int32) :: res_
   res_ = 0
   SetPoint = rhsValue
   ControlValue = lhsValue
   select case (relation)
   case (0)
      if (lhsValue == rhsValue) then
         res_ = 1
         return
      end if
   case (1)
      if (lhsValue /= rhsValue) then
         res_ = 1
         return
      end if
   case (2)
      if (lhsValue < rhsValue) then
         res_ = 1
         return
      end if
   case (3)
      if (lhsValue <= rhsValue) then
         res_ = 1
         return
      end if
   case (4)
      if (lhsValue > rhsValue) then
         res_ = 1
         return
      end if
   case (5)
      if (lhsValue >= rhsValue) then
         res_ = 1
         return
      end if
   end select
   res_ = 0
   return
end function compareValues

! controls.c:1455
recursive subroutine clearActionList()
   type(TActionList), pointer :: listItem
   nullify(listItem)
   listItem => ActionList
   do while (associated(listItem))
      nullify(listItem%action)
      listItem => listItem%next
   end do
end subroutine clearActionList

! controls.c:1473
recursive subroutine deleteActionList()
   type(TActionList), pointer :: listItem
   type(TActionList), pointer :: nextItem
   nullify(listItem)
   nullify(nextItem)
   listItem => ActionList
   do while (associated(listItem))
      nextItem => listItem%next
      ! free(listItem)
      listItem => nextItem
   end do
   nullify(ActionList)
end subroutine deleteActionList

! controls.c:1494
recursive subroutine deleteRules()
   type(TPremise), pointer :: p_l
   type(TPremise), pointer :: pnext
   type(TAction), pointer :: a_l
   type(TAction), pointer :: anext
   integer(int32) :: r_l
   nullify(p_l)
   nullify(pnext)
   nullify(a_l)
   nullify(anext)
   r_l = 0
   r_l = 0
   do while (r_l < RuleCount)
      p_l => Rules(r_l)%firstPremise
      do while (associated(p_l))
         pnext => p_l%next
         ! free(p)
         p_l => pnext
      end do
      a_l => Rules(r_l)%thenActions
      do while (associated(a_l))
