      flowDepthMid = 0.5_dp * (flowDepth1 + flowDepth2)
      if (flowDepthMid < 0.0001_dp) then
         flowDepthMid = 0.0001_dp
      end if
      width1 = dwflow_getWidth(xsect_l, flowDepth1)
      width2 = dwflow_getWidth(xsect_l, flowDepth2)
      widthMid = dwflow_getWidth(xsect_l, flowDepthMid)
      surfArea2 = ((widthMid + width2) * length_l) / 4.0_dp
      if (Link(j_l)%offset1 <= 0.0_dp) then
         surfArea1 = ((width1 + widthMid) * length_l) / 4.0_dp
      end if
   case (2)
      flowDepth2 = 0.0001_dp
      flowDepthMid = 0.5_dp * (flowDepth1 + flowDepth2)
      if (flowDepthMid < 0.0001_dp) then
         flowDepthMid = 0.0001_dp
      end if
      width1 = dwflow_getWidth(xsect_l, flowDepth1)
      width2 = dwflow_getWidth(xsect_l, flowDepth2)
      widthMid = dwflow_getWidth(xsect_l, flowDepthMid)
      surfArea1 = ((widthMid + width1) * length_l) / 4.0_dp
      if (Link(j_l)%offset2 <= 0.0_dp) then
         surfArea2 = ((width2 + widthMid) * length_l) / 4.0_dp
      end if
   case (0)
      surfArea1 = (0.0001_dp * length_l) / 2.0_dp
      surfArea2 = surfArea1
   end select
   Link(j_l)%surfArea1 = surfArea1
   Link(j_l)%surfArea2 = surfArea2
   y1 = flowDepth1
   y2 = flowDepth2
end subroutine findSurfArea

! dwflow.c:554
recursive function findLocalLosses(j_l, a1, a2, aMid, q_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: a1
   real(dp), value :: a2
   real(dp), value :: aMid
   real(dp), value :: q_l
   real(dp) :: res_
   real(dp) :: losses
   res_ = 0.0_dp
   losses = 0.0_dp
   q_l = abs(q_l)
   if (a1 > 0.0001_dp) then
      losses = losses + (Link(j_l)%cLossInlet * (q_l / a1))
   end if
   if (a2 > 0.0001_dp) then
      losses = losses + (Link(j_l)%cLossOutlet * (q_l / a2))
   end if
   if (aMid > 0.0001_dp) then
      losses = losses + (Link(j_l)%cLossAvg * (q_l / aMid))
   end if
   res_ = losses
   return
end function findLocalLosses

! dwflow.c:575
recursive function getSlotWidth(xsect_l, y_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: y_l
   real(dp) :: res_
   real(dp) :: yNorm
   logical :: b1_
   res_ = 0.0_dp
   yNorm = y_l / xsect_l%yFull
   b1_ = SurchargeMethod /= SLOT
   if (.not. b1_) then
      b1_ = xsect_isOpen(xsect_l%type) /= 0
   end if
   if (b1_ .or. (yNorm < CrownCutoff)) then
      res_ = 0.0_dp
      return
   end if
   if (yNorm > 1.78_dp) then
      res_ = 0.01_dp * xsect_l%wMax
      return
   end if
   res_ = (xsect_l%wMax * 0.5423_dp) * exp(-(yNorm ** 2.4_dp))
   return
end function getSlotWidth

! dwflow.c:592
recursive function dwflow_getWidth(xsect_l, y_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: y_l
   real(dp) :: res_
   real(dp) :: wSlot
   logical :: b1_
   res_ = 0.0_dp
   wSlot = getSlotWidth(xsect_l, y_l)
   if (wSlot > 0.0_dp) then
      res_ = wSlot
      return
   end if
   b1_ = (y_l / xsect_l%yFull) >= CrownCutoff
   if (b1_) then
      b1_ = .not. (xsect_isOpen(xsect_l%type) /= 0)
   end if
   if (b1_) then
      y_l = CrownCutoff * xsect_l%yFull
   end if
   res_ = xsect_getWofY(xsect_l, y_l)
   return
end function dwflow_getWidth

! dwflow.c:609
recursive function dwflow_getArea(xsect_l, y_l, wSlot) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: y_l
   real(dp), value :: wSlot
   real(dp) :: res_
   res_ = 0.0_dp
   if (y_l >= xsect_l%yFull) then
      res_ = xsect_l%aFull + ((y_l - xsect_l%yFull) * wSlot)
      return
   end if
   res_ = xsect_getAofY(xsect_l, y_l)
   return
end function dwflow_getArea

! dwflow.c:623
recursive function getHydRad(xsect_l, y_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: y_l
   real(dp) :: res_
   res_ = 0.0_dp
   if (y_l >= xsect_l%yFull) then
      res_ = xsect_l%rFull
      return
   end if
   res_ = xsect_getRofY(xsect_l, y_l)
   return
end function getHydRad

! dwflow.c:637
recursive function checkNormalFlow(j_l, q_l, y1, y2, a1, r1) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: q_l
   real(dp), value :: y1
   real(dp), value :: y2
   real(dp), value :: a1
   real(dp), value :: r1
   real(dp) :: res_
   integer(int32) :: check
   integer(int32) :: k_l
   integer(int32) :: n1
   integer(int32) :: n2
   integer(int32) :: hasOutfall
   logical :: b1_
   real(dp) :: qNorm
   real(dp) :: f1
   res_ = 0.0_dp
   check = 0
   k_l = Link(j_l)%subIndex
   n1 = Link(j_l)%node1
   n2 = Link(j_l)%node2
   b1_ = Node(n1)%type == OUTFALL_c
   if (.not. b1_) then
      b1_ = Node(n2)%type == OUTFALL_c
   end if
   hasOutfall = merge(1, 0, b1_)
   qNorm = 0.0_dp
   f1 = 0.0_dp
   if (((NormalFlowLtd == SLOPE) .or. (NormalFlowLtd == BOTH)) .or. (hasOutfall /= 0)) then
      if (y1 < y2) then
         check = 1
      end if
   end if
   if (((.not. (check /= 0)) .and. ((NormalFlowLtd == FROUDE) .or. (NormalFlowLtd == BOTH))) .and. (.not. (hasOutfall /= 0))) then
      if ((y1 > 0.0001_dp) .and. (y2 > 0.0001_dp)) then
         f1 = link_getFroude(j_l, q_l / a1, y1)
         if (f1 >= 1.0_dp) then
            check = 1
         end if
      end if
   end if
   if (check /= 0) then
      qNorm = (Conduit(k_l)%beta * a1) * (r1 ** (2.0_dp / 3.0_dp))
      if (qNorm < q_l) then
         Link(j_l)%normalFlow = 1
         res_ = qNorm
         return
      end if
   end if
   res_ = q_l
   return
end function checkNormalFlow

! dynwave.c:117
recursive subroutine dynwave_init()
   integer(int32) :: i_l
   integer(int32) :: j_l
   real(dp) :: z_l
   real(dp) :: v1_
   real(dp) :: v2_
   i_l = 0
   j_l = 0
   z_l = 0.0_dp
   VariableStep = 0.0_dp
   allocate(Xnode(0:(int(Nobjects(NODE_c), int64)) - 1))
   if (.not. associated(Xnode)) then
      call report_writeErrorMsg(ERR_MEMORY, lit_45)
      return
   end if
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      Xnode(i_l)%newSurfArea = 0.0_dp
      Xnode(i_l)%oldSurfArea = 0.0_dp
      Node(i_l)%crownElev = Node(i_l)%invertElev
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      j_l = Link(i_l)%node1
      z_l = (Node(j_l)%invertElev + Link(i_l)%offset1) + Link(i_l)%xsect%yFull
      if ((Node(j_l)%crownElev) >= (z_l)) then
         v1_ = Node(j_l)%crownElev
      else
         v1_ = z_l
      end if
      Node(j_l)%crownElev = v1_
      j_l = Link(i_l)%node2
      z_l = (Node(j_l)%invertElev + Link(i_l)%offset2) + Link(i_l)%xsect%yFull
      if ((Node(j_l)%crownElev) >= (z_l)) then
         v2_ = Node(j_l)%crownElev
      else
         v2_ = z_l
      end if
      Node(j_l)%crownElev = v2_
      Link(i_l)%flowClass = DRY
      Link(i_l)%dqdh = 0.0_dp
      i_l = i_l + 1
   end do
   if (SurchargeMethod == SLOT) then
      CrownCutoff = SLOT_CROWN_CUTOFF
   else
      CrownCutoff = EXTRAN_CROWN_CUTOFF
   end if
end subroutine dynwave_init

! dynwave.c:165
recursive subroutine dynwave_close()
   if (associated(Xnode)) then
      ! 
      nullify(Xnode)
   end if
end subroutine dynwave_close

! dynwave.c:177
recursive subroutine dynwave_validate()
   if (MinRouteStep > RouteStep) then
      MinRouteStep = RouteStep
   end if
   if (MinRouteStep < MINTIMESTEP) then
      MinRouteStep = MINTIMESTEP
   end if
   if (MinSurfArea == 0.0_dp) then
      MinSurfArea = DEFAULT_SURFAREA
   else
      MinSurfArea = MinSurfArea / (UCF(LENGTH) * UCF(LENGTH))
   end if
   if (HeadTol == 0.0_dp) then
      HeadTol = DEFAULT_HEADTOL
   else
      HeadTol = HeadTol / UCF(LENGTH)
   end if
   if (MaxTrials == 0) then
      MaxTrials = DEFAULT_MAXTRIALS
   end if
end subroutine dynwave_validate

! dynwave.c:195
recursive function dynwave_getRoutingStep(fixedStep) result(res_)
   real(dp), value :: fixedStep
   real(dp) :: res_
   res_ = 0.0_dp
   if (CourantFactor == 0.0_dp) then
      res_ = fixedStep
      return
   end if
   if (fixedStep < MINTIMESTEP) then
      res_ = fixedStep
      return
   end if
   if (VariableStep == 0.0_dp) then
      VariableStep = MinRouteStep
   else
      VariableStep = getVariableStep(fixedStep)
   end if
   VariableStep = cfloor(1000.0_dp * VariableStep) / 1000.0_dp
   res_ = VariableStep
   return
end function dynwave_getRoutingStep

! dynwave.c:224
recursive function dynwave_execute(tStep) result(res_)
   real(dp), value :: tStep
   integer(int32) :: res_
   integer(int32) :: converged
   res_ = 0
   converged = 0
   if (ErrorCode /= 0) then
      res_ = 0
      return
   end if
   Steps = 0
   converged = 0
   Omega = dynwave_OMEGA
   call initRoutingStep()
   do while (Steps < MaxTrials)
      call initNodeStates()
      call findLinkFlows(tStep)
      converged = findNodeDepths(tStep)
      Steps = Steps + 1
      if (Steps > 1) then
         if (converged /= 0) then
            exit
         end if
         call findBypassedLinks()
      end if
   end do
   if (.not. (converged /= 0)) then
      call updateConvergenceStats()
   end if
   call findLimitedLinks()
   res_ = Steps
   return
end function dynwave_execute

! dynwave.c:266
recursive subroutine updateConvergenceStats()
   integer(int32) :: i_l
   i_l = 0
   NonConvergeCount = NonConvergeCount + 1_int64
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      call stats_updateConvergenceStats(i_l, Xnode(i_l)%converged)
      i_l = i_l + 1
   end do
end subroutine updateConvergenceStats

! dynwave.c:276
recursive subroutine initRoutingStep()
   integer(int32) :: i_l
   i_l = 0
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      Xnode(i_l)%converged = 0
      Xnode(i_l)%dYdT = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      Link(i_l)%bypassed = 0
      Link(i_l)%surfArea1 = 0.0_dp
      Link(i_l)%surfArea2 = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nlinks(CONDUIT_c))
      Conduit(i_l)%a2 = Conduit(i_l)%a1
      i_l = i_l + 1
   end do
end subroutine initRoutingStep

! dynwave.c:297
recursive subroutine initNodeStates()
   integer(int32) :: i_l
   i_l = 0
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (AllowPonding /= 0) then
         Xnode(i_l)%newSurfArea = node_getPondedArea(i_l, Node(i_l)%newDepth)
      else
         Xnode(i_l)%newSurfArea = node_getSurfArea(i_l, Node(i_l)%newDepth)
      end if
      Node(i_l)%inflow = 0.0_dp
      Node(i_l)%outflow = Node(i_l)%losses
      if (Node(i_l)%newLatFlow >= 0.0_dp) then
         Node(i_l)%inflow = Node(i_l)%inflow + Node(i_l)%newLatFlow
      else
         Node(i_l)%outflow = Node(i_l)%outflow - Node(i_l)%newLatFlow
      end if
      Xnode(i_l)%sumdqdh = 0.0_dp
      i_l = i_l + 1
   end do
end subroutine initNodeStates

! dynwave.c:335
recursive subroutine findBypassedLinks()
   integer(int32) :: i_l
   logical :: b1_
   i_l = 0
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      b1_ = Xnode(Link(i_l)%node1)%converged /= 0
      if (b1_) then
         b1_ = Xnode(Link(i_l)%node2)%converged /= 0
      end if
      if (b1_) then
         Link(i_l)%bypassed = 1
      else
         Link(i_l)%bypassed = 0
      end if
      i_l = i_l + 1
   end do
end subroutine findBypassedLinks

! dynwave.c:349
recursive subroutine findLimitedLinks()
   integer(int32) :: j_l
   integer(int32) :: n1
   integer(int32) :: n2
   integer(int32) :: k_l
   real(dp) :: h1
   real(dp) :: h2
   j_l = 0
   n1 = 0
   n2 = 0
   k_l = 0
   h1 = 0.0_dp
   h2 = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      if (.not. (isTrueConduit(j_l) /= 0)) then
         goto 100
      end if
      k_l = Link(j_l)%subIndex
      Conduit(k_l)%capacityLimited = 0
      if (Conduit(k_l)%a1 >= Link(j_l)%xsect%aFull) then
         n1 = Link(j_l)%node1
         n2 = Link(j_l)%node2
         h1 = Node(n1)%newDepth + Node(n1)%invertElev
         h2 = Node(n2)%newDepth + Node(n2)%invertElev
         if ((h1 - h2) > (abs(Conduit(k_l)%slope) * Conduit(k_l)%length)) then
            Conduit(k_l)%capacityLimited = 1
         end if
      end if
      100 continue
      j_l = j_l + 1
   end do
end subroutine findLimitedLinks

! dynwave.c:382
recursive subroutine findLinkFlows(dt_l)
   real(dp), value :: dt_l
   integer(int32) :: i_l
   logical :: b1_
   i_l = 0
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      b1_ = isTrueConduit(i_l) /= 0
      if (b1_) then
         b1_ = .not. (Link(i_l)%bypassed /= 0)
      end if
      if (b1_) then
         call dwflow_findConduitFlow(i_l, Steps, Omega, dt_l)
      end if
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (isTrueConduit(i_l) /= 0) then
         call updateNodeFlows(i_l)
      end if
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (.not. (isTrueConduit(i_l) /= 0)) then
         if (.not. (Link(i_l)%bypassed /= 0)) then
            call findNonConduitFlow(i_l, dt_l)
         end if
         call updateNodeFlows(i_l)
      end if
      i_l = i_l + 1
   end do
end subroutine findLinkFlows

! dynwave.c:416
recursive function isTrueConduit(j_l) result(res_)
   integer(int32), value :: j_l
   integer(int32) :: res_
   logical :: b1_
   res_ = 0
   b1_ = Link(j_l)%type == CONDUIT_c
   if (b1_) then
      b1_ = Link(j_l)%xsect%type /= DUMMY
   end if
   res_ = merge(1, 0, b1_)
   return
end function isTrueConduit

! dynwave.c:423
recursive subroutine findNonConduitFlow(i_l, dt_l)
   integer(int32), value :: i_l
   real(dp), value :: dt_l
   real(dp) :: qLast
   real(dp) :: qNew
   logical :: b1_
   qLast = 0.0_dp
   qNew = 0.0_dp
   qLast = Link(i_l)%newFlow
   Link(i_l)%dqdh = 0.0_dp
   qNew = link_getInflow(i_l)
   if (Link(i_l)%type == PUMP_c) then
      qNew = getModPumpFlow(i_l, qNew, dt_l)
   end if
   call findNonConduitSurfArea(i_l)
   b1_ = Steps > 0
   if (b1_) then
      b1_ = Link(i_l)%type /= PUMP_c
   end if
   if (b1_) then
      qNew = ((1.0_dp - Omega) * qLast) + (Omega * qNew)
      if ((qNew * qLast) < 0.0_dp) then
         qNew = 0.001_dp * real(merge(-1, 1, (qNew) < 0.0_dp), dp)
      end if
   end if
   Link(i_l)%newFlow = qNew
end subroutine findNonConduitFlow

! dynwave.c:458
recursive function getModPumpFlow(i_l, q_l, dt_l) result(res_)
   integer(int32), value :: i_l
   real(dp), value :: q_l
   real(dp), value :: dt_l
   real(dp) :: res_
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp) :: newNetInflow
   real(dp) :: netFlowVolume
   real(dp) :: y_l
   res_ = 0.0_dp
   j_l = Link(i_l)%node1
   k_l = Link(i_l)%subIndex
   newNetInflow = 0.0_dp
   netFlowVolume = 0.0_dp
   y_l = 0.0_dp
   if (q_l == 0.0_dp) then
      res_ = q_l
      return
   end if
   if (Node(j_l)%type == STORAGE_c) then
      res_ = node_getMaxOutflow(j_l, q_l, dt_l)
      return
   end if
   select case (Pump(k_l)%type)
   case (0)
      res_ = node_getMaxOutflow(j_l, q_l, dt_l)
      return
   case (1, 3, 2)
      newNetInflow = (Node(j_l)%inflow - Node(j_l)%outflow) - q_l
      netFlowVolume = (0.5_dp * (Node(j_l)%oldNetInflow + newNetInflow)) * dt_l
      y_l = Node(j_l)%oldDepth + (netFlowVolume / Xnode(j_l)%newSurfArea)
      if (y_l <= 0.0_dp) then
         res_ = Node(j_l)%inflow
         return
      end if
   end select
   res_ = q_l
   return
end function getModPumpFlow

! dynwave.c:503
recursive subroutine findNonConduitSurfArea(i_l)
   integer(int32), value :: i_l
   logical :: b1_
   logical :: b2_
   if (Link(i_l)%type == ORIFICE_c) then
      Link(i_l)%surfArea1 = Orifice(Link(i_l)%subIndex)%surfArea / 2.0_dp
   else
      Link(i_l)%surfArea1 = 0.0_dp
   end if
   Link(i_l)%surfArea2 = Link(i_l)%surfArea1
   b1_ = Link(i_l)%flowClass == UP_CRITICAL
   if (.not. b1_) then
      b1_ = Node(Link(i_l)%node1)%type == STORAGE_c
   end if
   if (b1_) then
      Link(i_l)%surfArea1 = 0.0_dp
   end if
   b2_ = Link(i_l)%flowClass == DN_CRITICAL
   if (.not. b2_) then
      b2_ = Node(Link(i_l)%node2)%type == STORAGE_c
   end if
   if (b2_) then
      Link(i_l)%surfArea2 = 0.0_dp
   end if
end subroutine findNonConduitSurfArea

! dynwave.c:528
recursive subroutine updateNodeFlows(i_l)
   integer(int32), value :: i_l
   integer(int32) :: k_l
   integer(int32) :: barrels
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp) :: q_l
   real(dp) :: conduitLossRate
   logical :: b1_
   k_l = 0
   barrels = 1
   n1 = Link(i_l)%node1
   n2 = Link(i_l)%node2
   q_l = Link(i_l)%newFlow
   conduitLossRate = 0.0_dp
   if (q_l >= 0.0_dp) then
      Node(n1)%outflow = Node(n1)%outflow + q_l
      Node(n2)%inflow = Node(n2)%inflow + q_l
   else
      Node(n1)%inflow = Node(n1)%inflow - q_l
      Node(n2)%outflow = Node(n2)%outflow - q_l
   end if
   if (Link(i_l)%type == CONDUIT_c) then
      k_l = Link(i_l)%subIndex
      barrels = Conduit(k_l)%barrels
      conduitLossRate = (Conduit(k_l)%evapLossRate + Conduit(k_l)%seepLossRate) * real(barrels, dp)
      if (conduitLossRate > 0.0_dp) then
         b1_ = Node(n1)%type /= OUTFALL_c
         if (b1_) then
            b1_ = Node(n2)%type /= OUTFALL_c
         end if
         if (b1_) then
            conduitLossRate = conduitLossRate / 2.0_dp
         end if
         if (Node(n1)%type /= OUTFALL_c) then
            Node(n1)%outflow = Node(n1)%outflow + conduitLossRate
         end if
         if (Node(n2)%type /= OUTFALL_c) then
            Node(n2)%outflow = Node(n2)%outflow + conduitLossRate
         end if
      end if
   end if
   Xnode(Link(i_l)%node1)%newSurfArea = Xnode(Link(i_l)%node1)%newSurfArea + (Link(i_l)%surfArea1 * real(barrels, dp))
   Xnode(Link(i_l)%node2)%newSurfArea = Xnode(Link(i_l)%node2)%newSurfArea + (Link(i_l)%surfArea2 * real(barrels, dp))
   Xnode(Link(i_l)%node1)%sumdqdh = Xnode(Link(i_l)%node1)%sumdqdh + Link(i_l)%dqdh
   if (Link(i_l)%type == PUMP_c) then
      k_l = Link(i_l)%subIndex
      if (Pump(k_l)%type /= TYPE4_PUMP) then
         Xnode(n2)%sumdqdh = Xnode(n2)%sumdqdh + Link(i_l)%dqdh
      end if
   else
      Xnode(n2)%sumdqdh = Xnode(n2)%sumdqdh + Link(i_l)%dqdh
   end if
end subroutine updateNodeFlows

! dynwave.c:593
recursive function findNodeDepths(dt_l) result(res_)
   real(dp), value :: dt_l
   integer(int32) :: res_
   integer(int32) :: i_l
   real(dp) :: yOld
   res_ = 0
   i_l = 0
   yOld = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      call link_setOutfallDepth(i_l)
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%type == OUTFALL_c) then
         goto 101
      end if
      yOld = Node(i_l)%newDepth
      call setNodeDepth(i_l, dt_l)
      Xnode(i_l)%converged = 1
      if (abs(yOld - Node(i_l)%newDepth) > HeadTol) then
         Xnode(i_l)%converged = 0
      end if
      101 continue
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%type == OUTFALL_c) then
         goto 102
      end if
      if (Xnode(i_l)%converged == 0) then
         res_ = 0
         return
      end if
      102 continue
      i_l = i_l + 1
   end do
   res_ = 1
   return
end function findNodeDepths

! dynwave.c:636
recursive subroutine setNodeDepth(i_l, dt_l)
   integer(int32), value :: i_l
   real(dp), value :: dt_l
   integer(int32) :: canPond
   integer(int32) :: isPonded
   integer(int32) :: isSurcharged
   real(dp) :: dQ
   real(dp) :: dV_l
   real(dp) :: dy
   real(dp) :: yMax
   real(dp) :: yOld
   real(dp) :: yLast
   real(dp) :: yNew
   real(dp) :: yCrown
   real(dp) :: surfArea
   real(dp) :: denom
   real(dp) :: corr
   real(dp) :: f_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   canPond = 0
   isPonded = 0
   isSurcharged = 0
   dQ = 0.0_dp
   dV_l = 0.0_dp
   dy = 0.0_dp
   yMax = 0.0_dp
   yOld = 0.0_dp
   yLast = 0.0_dp
   yNew = 0.0_dp
   yCrown = 0.0_dp
   surfArea = 0.0_dp
   denom = 0.0_dp
   corr = 0.0_dp
   f_l = 0.0_dp
   b1_ = AllowPonding /= 0
   if (b1_) then
      b1_ = Node(i_l)%pondedArea > 0.0_dp
   end if
   canPond = merge(1, 0, b1_)
   b2_ = canPond /= 0
   if (b2_) then
      b2_ = Node(i_l)%newDepth > Node(i_l)%fullDepth
   end if
   isPonded = merge(1, 0, b2_)
   yCrown = Node(i_l)%crownElev - Node(i_l)%invertElev
   yOld = Node(i_l)%oldDepth
   yLast = Node(i_l)%newDepth
   Node(i_l)%overflow = 0.0_dp
   surfArea = Xnode(i_l)%newSurfArea
   surfArea = merge(surfArea, MinSurfArea, (surfArea) >= (MinSurfArea))
   dQ = Node(i_l)%inflow - Node(i_l)%outflow
   dV_l = (0.5_dp * (Node(i_l)%oldNetInflow + dQ)) * dt_l
   if (SurchargeMethod == EXTRAN) then
      if (isPonded /= 0) then
         isSurcharged = 0
      else if (Node(i_l)%type == STORAGE_c) then
         b3_ = Node(i_l)%surDepth > 0.0_dp
         if (b3_) then
            b3_ = yLast > Node(i_l)%fullDepth
         end if
         isSurcharged = merge(1, 0, b3_)
      else
         isSurcharged = merge(1, 0, (yCrown > 0.0_dp) .and. (yLast > yCrown))
      end if
   end if
   if (.not. (isSurcharged /= 0)) then
      dy = dV_l / surfArea
      yNew = yOld + dy
      if (.not. (isPonded /= 0)) then
         Xnode(i_l)%oldSurfArea = surfArea
      end if
      if (Steps > 0) then
         yNew = ((1.0_dp - Omega) * yLast) + (Omega * yNew)
      end if
      b4_ = isPonded /= 0
      if (b4_) then
         b4_ = yNew < Node(i_l)%fullDepth
      end if
      if (b4_) then
         yNew = Node(i_l)%fullDepth - 0.0001_dp
      end if
   else
      corr = 1.0_dp
      if (Node(i_l)%degree < 0) then
         corr = 0.6_dp
      end if
      denom = Xnode(i_l)%sumdqdh
      if (yLast < (1.25_dp * yCrown)) then
         f_l = (yLast - yCrown) / yCrown
         denom = denom + (((Xnode(i_l)%oldSurfArea / dt_l) - Xnode(i_l)%sumdqdh) * exp((-15.0_dp) * f_l))
      end if
      if (denom == 0.0_dp) then
         dy = 0.0_dp
      else
         dy = (corr * dQ) / denom
      end if
      yNew = yLast + dy
      if (yNew < yCrown) then
         yNew = yCrown - 0.0001_dp
      end if
      b5_ = canPond /= 0
      if (b5_) then
         b5_ = yNew > Node(i_l)%fullDepth
      end if
      if (b5_) then
         yNew = Node(i_l)%fullDepth + 0.0001_dp
      end if
   end if
   if (yNew < 0.0_dp) then
      yNew = 0.0_dp
   end if
   yMax = Node(i_l)%fullDepth
   if (canPond == 0) then
      yMax = yMax + Node(i_l)%surDepth
   end if
   if (yNew > yMax) then
      yNew = getFloodedDepth(i_l, canPond, dV_l, yNew, yMax, dt_l)
   else
      Node(i_l)%newVolume = node_getVolume(i_l, yNew)
   end if
   Xnode(i_l)%dYdT = abs(yNew - yOld) / dt_l
   Node(i_l)%newDepth = yNew
end subroutine setNodeDepth

! dynwave.c:766
recursive function getFloodedDepth(i_l, canPond, dV_l, yNew, yMax, dt_l) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: canPond
   real(dp), value :: dV_l
   real(dp), value :: yNew
   real(dp), value :: yMax
   real(dp), value :: dt_l
   real(dp) :: res_
   real(dp) :: v1_
   real(dp) :: v2_
   res_ = 0.0_dp
   if (canPond == 0) then
      Node(i_l)%overflow = dV_l / dt_l
      Node(i_l)%newVolume = Node(i_l)%fullVolume
      yNew = yMax
   else
      if ((Node(i_l)%oldVolume + dV_l) >= (Node(i_l)%fullVolume)) then
         v1_ = Node(i_l)%oldVolume + dV_l
      else
         v1_ = Node(i_l)%fullVolume
      end if
      Node(i_l)%newVolume = v1_
      if ((Node(i_l)%oldVolume) >= (Node(i_l)%fullVolume)) then
         v2_ = Node(i_l)%oldVolume
      else
         v2_ = Node(i_l)%fullVolume
      end if
      Node(i_l)%overflow = (Node(i_l)%newVolume - (v2_)) / dt_l
   end if
   if (Node(i_l)%overflow < 0.0001_dp) then
      Node(i_l)%overflow = 0.0_dp
   end if
   res_ = yNew
   return
end function getFloodedDepth

! dynwave.c:799
recursive function getVariableStep(maxStep) result(res_)
   real(dp), value :: maxStep
   real(dp) :: res_
   integer(int32), target :: minLink
   integer(int32), target :: minNode
   real(dp) :: tMin_l
   real(dp) :: tMinLink
   real(dp) :: tMinNode
   res_ = 0.0_dp
   minLink = -1
   minNode = -1
   tMin_l = 0.0_dp
   tMinLink = 0.0_dp
   tMinNode = 0.0_dp
   tMin_l = maxStep
   tMinLink = getLinkStep(tMin_l, minLink)
   tMinNode = getNodeStep(tMinLink, minNode)
   tMin_l = tMinLink
   if (tMinNode < tMin_l) then
      tMin_l = tMinNode
      minLink = -1
   end if
   call stats_updateCriticalTimeCount(minNode, minLink)
   if (tMin_l < MinRouteStep) then
      tMin_l = MinRouteStep
   end if
   res_ = tMin_l
   return
end function getVariableStep

! dynwave.c:836
recursive function getLinkStep(tMin_l, minLink) result(res_)
   real(dp), value :: tMin_l
   integer(int32), intent(inout), target :: minLink
   real(dp) :: res_
   integer(int32) :: i_l
   integer(int32) :: k_l
   real(dp) :: q_l
   real(dp) :: t_l
   real(dp) :: tLink_l
   logical :: b1_
   logical :: b2_
   res_ = 0.0_dp
   i_l = 0
   k_l = 0
   q_l = 0.0_dp
   t_l = 0.0_dp
   tLink_l = tMin_l
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (Link(i_l)%type == CONDUIT_c) then
         k_l = Link(i_l)%subIndex
         q_l = abs(Link(i_l)%newFlow) / real(Conduit(k_l)%barrels, dp)
         b1_ = q_l <= 0.0001_dp
         if (.not. b1_) then
            b1_ = Conduit(k_l)%a1 <= 0.0001_dp
         end if
         b2_ = b1_
         if (.not. b2_) then
            b2_ = Link(i_l)%froude <= 0.01_dp
         end if
         if (b2_) then
            goto 100
         end if
         t_l = (Link(i_l)%newVolume / real(Conduit(k_l)%barrels, dp)) / q_l
         t_l = (t_l * Conduit(k_l)%modLength) / link_getLength(i_l)
         t_l = ((t_l * Link(i_l)%froude) / (1.0_dp + Link(i_l)%froude)) * CourantFactor
         if (t_l < tLink_l) then
            tLink_l = t_l
            minLink = i_l
         end if
      end if
      100 continue
      i_l = i_l + 1
   end do
   res_ = tLink_l
   return
end function getLinkStep

! dynwave.c:881
recursive function getNodeStep(tMin_l, minNode) result(res_)
   real(dp), value :: tMin_l
   integer(int32), intent(inout), target :: minNode
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: maxDepth
   real(dp) :: dYdT
   real(dp) :: t1
   real(dp) :: tNode_l
   res_ = 0.0_dp
   i_l = 0
   maxDepth = 0.0_dp
   dYdT = 0.0_dp
   t1 = 0.0_dp
   tNode_l = tMin_l
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%type == OUTFALL_c) then
         goto 100
      end if
      if (Node(i_l)%newDepth <= 0.0001_dp) then
         goto 100
      end if
      if ((Node(i_l)%newDepth + 0.0001_dp) >= (Node(i_l)%crownElev - Node(i_l)%invertElev)) then
         goto 100
      end if
      maxDepth = (Node(i_l)%crownElev - Node(i_l)%invertElev) * 0.25_dp
      if (maxDepth < 0.0001_dp) then
         goto 100
      end if
      dYdT = Xnode(i_l)%dYdT
      if (dYdT < 0.0001_dp) then
         goto 100
      end if
      t1 = maxDepth / dYdT
      if (t1 < tNode_l) then
         tNode_l = t1
         minNode = i_l
      end if
      100 continue
      i_l = i_l + 1
   end do
   res_ = tNode_l
   return
end function getNodeStep

