! exfil.c:34
recursive function exfil_readStorageParams(k_l, tok_l, ntoks, n_l) result(res_)
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32), value :: n_l
   integer(int32) :: res_
   integer(int32) :: i_l
   real(dp), target :: x_l(0:2)
   res_ = 0
   i_l = 0
   x_l = 0.0_dp
   if (ntoks == (n_l + 1)) then
      if (.not. (getDouble(tok_l(n_l), x_l(1)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(n_l))
         return
      end if
      x_l(0) = 0.0_dp
      x_l(2) = 0.0_dp
   else if (ntoks < (n_l + 3)) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   else
      i_l = 0
      do while (i_l < 3)
         if (.not. (getDouble(tok_l(n_l + i_l), x_l(i_l)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(n_l + i_l))
            return
         end if
         i_l = i_l + 1
      end do
   end if
   if (x_l(1) == 0.0_dp) then
      res_ = 0
      return
   end if
   res_ = createStorageExfil(k_l, x_l)
   return
end function exfil_readStorageParams

