recursive subroutine exfil_initState(k_l)
   integer(int32), value :: k_l
   integer(int32) :: i_l
   real(dp), target :: a_l
   real(dp) :: alast
   real(dp), target :: d_l
   type(TTable), pointer :: aCurve
   type(TExfil), pointer :: exfil
   integer(int32) :: dum1_
   i_l = 0
   a_l = 0.0_dp
   alast = 0.0_dp
   d_l = 0.0_dp
   nullify(aCurve)
   exfil => Storage(k_l)%exfil
   if (.not. (.not. associated(exfil))) then
      call grnampt_initState(exfil%btmExfil)
      call grnampt_initState(exfil%bankExfil)
      select case (Storage(k_l)%shape)
      case (0)
         i_l = Storage(k_l)%aCurve
         exfil%btmArea = 0.0_dp
         exfil%bankMinDepth = 0.0_dp
         exfil%bankMaxDepth = 0.0_dp
         exfil%bankMaxArea = 0.0_dp
         if (i_l >= 0) then
            aCurve => Curve(i_l)
            Storage(k_l)%exfil%btmArea = table_lookupEx(aCurve, 0.0_dp)
            dum1_ = table_getFirstEntry(aCurve, d_l, a_l)
            alast = a_l
            do while (table_getNextEntry(aCurve, d_l, a_l) /= 0)
               if (a_l < alast) then
                  exit
               else if (a_l > alast) then
                  exfil%bankMaxArea = a_l
                  exfil%bankMaxDepth = d_l
               else if (exfil%bankMaxArea == 0.0_dp) then
                  exfil%bankMinDepth = d_l
               else
                  exit
               end if
               alast = a_l
            end do
            exfil%btmArea = exfil%btmArea / (UCF(LENGTH) * UCF(LENGTH))
            exfil%bankMaxArea = exfil%bankMaxArea / (UCF(LENGTH) * UCF(LENGTH))
            exfil%bankMinDepth = exfil%bankMinDepth / UCF(LENGTH)
            exfil%bankMaxDepth = exfil%bankMaxDepth / UCF(LENGTH)
         end if
      case (1)
         exfil%btmArea = Storage(k_l)%a0
         if (Storage(k_l)%a2 == 0.0_dp) then
            exfil%btmArea = exfil%btmArea + Storage(k_l)%a1
         end if
         exfil%bankMinDepth = 0.0_dp
         exfil%bankMaxDepth = 10000000000.0_dp
         exfil%bankMaxArea = 10000000000.0_dp
      case (2, 3, 5)
         exfil%btmArea = Storage(k_l)%a0
         exfil%bankMinDepth = 0.0_dp
         exfil%bankMaxDepth = 10000000000.0_dp
         exfil%bankMaxArea = 10000000000.0_dp
      end select
   end if
end subroutine exfil_initState

! exfil.c:158
recursive function exfil_getLoss(exfil, tStep, depth, area_l) result(res_)
   type(TExfil), pointer, intent(in) :: exfil
   real(dp), value :: tStep
   real(dp), value :: depth
   real(dp), value :: area_l
   real(dp) :: res_
   real(dp) :: exfilRate
   real(dp) :: v1_
   res_ = 0.0_dp
   exfilRate = 0.0_dp
   if (exfil%btmExfil%IMDmax == 0.0_dp) then
      exfilRate = exfil%btmExfil%Ks * Adjust%hydconFactor
   else
      exfilRate = grnampt_getInfil(exfil%btmExfil, tStep, 0.0_dp, depth, MOD_GREEN_AMPT)
   end if
   exfilRate = exfilRate * exfil%btmArea
   if (depth > exfil%bankMinDepth) then
      if ((area_l) <= (exfil%bankMaxArea)) then
         v1_ = area_l
      else
         v1_ = exfil%bankMaxArea
      end if
      area_l = (v1_) - exfil%btmArea
      if (area_l > 0.0_dp) then
         if (exfil%btmExfil%IMDmax == 0.0_dp) then
            exfilRate = exfilRate + ((area_l * exfil%btmExfil%Ks) * Adjust%hydconFactor)
         else
            if (depth > exfil%bankMaxDepth) then
               depth = (depth - exfil%bankMaxDepth) + ((exfil%bankMaxDepth - exfil%bankMinDepth) / 2.0_dp)
            else
               depth = (depth - exfil%bankMinDepth) / 2.0_dp
            end if
            exfilRate = exfilRate + (area_l * grnampt_getInfil(exfil%bankExfil, tStep, 0.0_dp, depth, MOD_GREEN_AMPT))
         end if
      end if
   end if
   res_ = exfilRate
   return
end function exfil_getLoss

! exfil.c:218
recursive function createStorageExfil(k_l, x_l) result(res_)
   integer(int32), value :: k_l
   real(dp), pointer, intent(in) :: x_l(:)
   integer(int32) :: res_
   type(TExfil), pointer :: exfil
   integer(int32) :: dum1_
   res_ = 0
   nullify(exfil)
   exfil => Storage(k_l)%exfil
   if (.not. associated(exfil)) then
      allocate(exfil)
      if (.not. associated(exfil)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
      Storage(k_l)%exfil => exfil
      nullify(exfil%btmExfil)
      nullify(exfil%bankExfil)
      allocate(exfil%btmExfil)
      if (.not. associated(exfil%btmExfil)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
