      end if
   end if
   if (.not. (grnampt_setParams(exfil%btmExfil, x_l) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, lit_0)
      return
   end if
   dum1_ = grnampt_setParams(exfil%bankExfil, x_l)
   res_ = 0
   return
end function createStorageExfil

! findroot.c:20
recursive function findroot_Newton(x1, x2, rts, xacc, func, p_l) result(res_)
   real(dp), value :: x1
   real(dp), value :: x2
   real(dp), intent(inout), target :: rts
   real(dp), value :: xacc
   procedure(fp0) :: func
   type(c_ptr), value :: p_l
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: n_l
   real(dp), target :: df
   real(dp) :: dx
   real(dp) :: dxold
   real(dp), target :: f_l
   real(dp) :: x_l
   real(dp) :: temp_l
   real(dp) :: xhi
   real(dp) :: xlo
   res_ = 0
   j_l = 0
   n_l = 0
   df = 0.0_dp
   dx = 0.0_dp
   dxold = 0.0_dp
   f_l = 0.0_dp
   x_l = 0.0_dp
   temp_l = 0.0_dp
   xhi = 0.0_dp
   xlo = 0.0_dp
   x_l = rts
   xlo = x1
   xhi = x2
   dxold = abs(x2 - x1)
   dx = dxold
   call func(x_l, f_l, df, p_l)
   n_l = n_l + 1
   j_l = 1
   do while (j_l <= 60)
      if ((((((x_l - xhi) * df) - f_l) * (((x_l - xlo) * df) - f_l)) >= 0.0_dp) .or. (abs(2.0_dp * f_l) > abs(dxold * df))) then
         dxold = dx
         dx = 0.5_dp * (xhi - xlo)
         x_l = xlo + dx
         if (xlo == x_l) then
            exit
         end if
      else
         dxold = dx
         dx = f_l / df
         temp_l = x_l
         x_l = x_l - dx
         if (temp_l == x_l) then
            exit
         end if
      end if
      if (abs(dx) < xacc) then
         exit
      end if
      call func(x_l, f_l, df, p_l)
      n_l = n_l + 1
      if (f_l < 0.0_dp) then
         xlo = x_l
      else
         xhi = x_l
      end if
      j_l = j_l + 1
   end do
   rts = x_l
   if (n_l <= 60) then
      res_ = n_l
      return
   else
      res_ = 0
      return
   end if
end function findroot_Newton

! findroot.c:91
recursive function findroot_Ridder(x1, x2, xacc, func, p_l) result(res_)
   real(dp), value :: x1
   real(dp), value :: x2
   real(dp), value :: xacc
   procedure(fp1) :: func
   type(c_ptr), value :: p_l
   real(dp) :: res_
   integer(int32) :: j_l
   real(dp) :: ans
   real(dp) :: fhi_l
   real(dp) :: flo_l
   real(dp) :: fm
   real(dp) :: fnew
   real(dp) :: s_l
   real(dp) :: xhi
   real(dp) :: xlo
   real(dp) :: xm
   real(dp) :: xnew
   res_ = 0.0_dp
   j_l = 0
   ans = 0.0_dp
   fhi_l = 0.0_dp
   flo_l = 0.0_dp
   fm = 0.0_dp
   fnew = 0.0_dp
   s_l = 0.0_dp
   xhi = 0.0_dp
   xlo = 0.0_dp
   xm = 0.0_dp
   xnew = 0.0_dp
   flo_l = func(x1, p_l)
   fhi_l = func(x2, p_l)
   if (flo_l == 0.0_dp) then
      res_ = x1
      return
   end if
   if (fhi_l == 0.0_dp) then
      res_ = x2
      return
   end if
   ans = 0.5_dp * (x1 + x2)
   if (((flo_l > 0.0_dp) .and. (fhi_l < 0.0_dp)) .or. ((flo_l < 0.0_dp) .and. (fhi_l > 0.0_dp))) then
      xlo = x1
      xhi = x2
      j_l = 1
      do while (j_l <= 60)
         xm = 0.5_dp * (xlo + xhi)
         fm = func(xm, p_l)
         s_l = sqrt((fm * fm) - (flo_l * fhi_l))
         if (s_l == 0.0_dp) then
            res_ = ans
            return
         end if
         xnew = xm + ((xm - xlo) * (((merge(1.0_dp, -1.0_dp, flo_l >= fhi_l)) * fm) / s_l))
         if (abs(xnew - ans) <= xacc) then
            exit
         end if
         ans = xnew
         fnew = func(ans, p_l)
         if ((merge(abs(fm), -abs(fm), (fnew) >= 0.0_dp)) /= fm) then
            xlo = xm
            flo_l = fm
            xhi = ans
            fhi_l = fnew
         else if ((merge(abs(flo_l), -abs(flo_l), (fnew) >= 0.0_dp)) /= flo_l) then
            xhi = ans
            fhi_l = fnew
         else if ((merge(abs(fhi_l), -abs(fhi_l), (fnew) >= 0.0_dp)) /= fhi_l) then
            xlo = ans
            flo_l = fnew
         else
            res_ = ans
            return
         end if
         if (abs(xhi - xlo) <= xacc) then
            res_ = ans
            return
         end if
         j_l = j_l + 1
      end do
      res_ = ans
      return
   end if
   res_ = -1.0e20_dp
   return
end function findroot_Ridder

! flowrout.c:75
recursive subroutine flowrout_init(routingModel)
   integer(int32), value :: routingModel
   if (routingModel == DW) then
      call validateGeneralLayout()
      call dynwave_init()
      if (Fhotstart1%mode == NO_FILE) then
         call initNodeDepths()
         call initLinkDepths()
      end if
   else
      call validateTreeLayout()
   end if
   call initNodes()
   call initLinks(routingModel)
end subroutine flowrout_init

! flowrout.c:107
recursive subroutine flowrout_close(routingModel)
   integer(int32), value :: routingModel
   if (routingModel == DW) then
      call dynwave_close()
   end if
end subroutine flowrout_close

