! flowrout.c:136
recursive function flowrout_execute(links, routingModel, tStep) result(res_)
   integer(int32), pointer, intent(in) :: links(:)
   integer(int32), value :: routingModel
   real(dp), value :: tStep
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: n1
   real(dp), target :: qin
   real(dp), target :: qout
   real(dp) :: steps_l
   logical :: b1_
   res_ = 0
   i_l = 0
   j_l = 0
   n1 = 0
   qin = 0.0_dp
   qout = 0.0_dp
   steps_l = 0.0_dp
   if (ErrorCode /= 0) then
      res_ = 0
      return
   end if
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      Node(j_l)%updated = 0
      Node(j_l)%overflow = 0.0_dp
      b1_ = Node(j_l)%type /= STORAGE_c
      if (b1_) then
         b1_ = Node(j_l)%newVolume > Node(j_l)%fullVolume
      end if
      if (b1_) then
         Node(j_l)%overflow = (Node(j_l)%newVolume - Node(j_l)%fullVolume) / tStep
      end if
      j_l = j_l + 1
   end do
   if (routingModel == DW) then
      res_ = dynwave_execute(tStep)
      return
   end if
   steps_l = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      j_l = links(i_l)
      n1 = Link(j_l)%node1
      if (Node(n1)%type == STORAGE_c) then
         call updateStorageState(n1, i_l, links, tStep)
      end if
      qin = getLinkInflow(j_l, tStep)
      if (routingModel == SF) then
         steps_l = steps_l + real(steadyflow_execute(j_l, qin, qout, tStep), dp)
      else
         steps_l = steps_l + real(kinwave_execute(j_l, qin, qout, tStep), dp)
      end if
      Link(j_l)%newFlow = qout
      Node(Link(j_l)%node1)%outflow = Node(Link(j_l)%node1)%outflow + qin
      Node(Link(j_l)%node2)%inflow = Node(Link(j_l)%node2)%inflow + qout
      i_l = i_l + 1
   end do
   if (Nobjects(LINK_c) > 0) then
      steps_l = steps_l / real(Nobjects(LINK_c), dp)
   end if
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      call setNewNodeState(j_l, tStep)
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      call setNewLinkState(j_l)
      j_l = j_l + 1
   end do
   res_ = d2i(steps_l + 0.5_dp)
   return
end function flowrout_execute

! flowrout.c:203
recursive subroutine validateTreeLayout()
   integer(int32) :: j_l
   logical :: b1_
   j_l = 0
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      select case (Node(j_l)%type)
      case (3)
         if (Node(j_l)%degree > 2) then
            call report_writeErrorMsg(ERR_DIVIDER, Node(j_l)%ID)
         end if
      case (1)
         if (Node(j_l)%degree > 0) then
            call report_writeErrorMsg(ERR_OUTFALL, Node(j_l)%ID)
         end if
      case (2)
      case default
         if (Node(j_l)%degree > 1) then
            call report_writeErrorMsg(ERR_MULTI_OUTLET, Node(j_l)%ID)
         end if
      end select
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      select case (Link(j_l)%type)
      case (0)
         b1_ = Conduit(Link(j_l)%subIndex)%slope < 0.0_dp
         if (b1_) then
            b1_ = Link(j_l)%xsect%type /= DUMMY
         end if
         if (b1_) then
            call report_writeErrorMsg(ERR_SLOPE, Link(j_l)%ID)
         end if
      case (2, 3, 4)
         if (Node(Link(j_l)%node1)%type /= STORAGE_c) then
            call report_writeErrorMsg(ERR_REGULATOR, Link(j_l)%ID)
         end if
      end select
      j_l = j_l + 1
   end do
end subroutine validateTreeLayout

! flowrout.c:274
recursive subroutine validateGeneralLayout()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: outletCount
   logical :: b1_
   logical :: b2_
   logical :: b3_
   i_l = 0
   j_l = 0
   outletCount = 0
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      Node(i_l)%inflow = 0.0_dp
      i_l = i_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      i_l = Link(j_l)%node1
      if (Node(i_l)%type /= OUTFALL_c) then
         i_l = Link(j_l)%node2
      end if
      Node(i_l)%inflow = Node(i_l)%inflow + 1.0_dp
      b1_ = Link(j_l)%type == CONDUIT_c
      if (b1_) then
         b1_ = Link(j_l)%xsect%type == DUMMY
      end if
      b3_ = b1_
      if (.not. b3_) then
         b2_ = Link(j_l)%type == PUMP_c
         if (b2_) then
            b2_ = Pump(Link(j_l)%subIndex)%type == IDEAL_PUMP
         end if
         b3_ = b2_
      end if
      if (b3_) then
         i_l = Link(j_l)%node1
         if (Link(j_l)%direction < 0) then
            i_l = Link(j_l)%node2
         end if
         if (Node(i_l)%degree > 1) then
            call report_writeErrorMsg(ERR_DUMMY_LINK, Node(i_l)%ID)
         end if
      end if
      j_l = j_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%type == OUTFALL_c) then
         if ((Node(i_l)%degree + d2i(Node(i_l)%inflow)) > 1) then
            call report_writeErrorMsg(ERR_OUTFALL, Node(i_l)%ID)
         else
            outletCount = outletCount + 1
         end if
      end if
      i_l = i_l + 1
   end do
   if (outletCount == 0) then
      call report_writeErrorMsg(ERR_NO_OUTLETS, lit_0)
   end if
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%inflow == 0.0_dp) then
         Node(i_l)%degree = -Node(i_l)%degree
      end if
      Node(i_l)%inflow = 0.0_dp
      i_l = i_l + 1
   end do
end subroutine validateGeneralLayout

! flowrout.c:337
recursive subroutine initNodeDepths()
   integer(int32) :: i_l
   integer(int32) :: n_l
   real(dp) :: y_l
   i_l = 0
   n_l = 0
   y_l = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      Node(i_l)%inflow = 0.0_dp
      Node(i_l)%outflow = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (Link(i_l)%newDepth > 0.0001_dp) then
         y_l = Link(i_l)%newDepth + Link(i_l)%offset1
      else
         y_l = 0.0_dp
      end if
      n_l = Link(i_l)%node1
      Node(n_l)%inflow = Node(n_l)%inflow + y_l
      Node(n_l)%outflow = Node(n_l)%outflow + 1.0_dp
      n_l = Link(i_l)%node2
      Node(n_l)%inflow = Node(n_l)%inflow + y_l
      Node(n_l)%outflow = Node(n_l)%outflow + 1.0_dp
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%type == OUTFALL_c) then
         goto 102
      end if
      if (Node(i_l)%type == STORAGE_c) then
         goto 102
      end if
      if (Node(i_l)%initDepth > 0.0_dp) then
         goto 102
      end if
      if (Node(i_l)%outflow > 0.0_dp) then
         Node(i_l)%newDepth = Node(i_l)%inflow / Node(i_l)%outflow
      end if
      102 continue
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      call link_setOutfallDepth(i_l)
      i_l = i_l + 1
   end do
end subroutine initNodeDepths

! flowrout.c:389
recursive subroutine initLinkDepths()
   integer(int32) :: i_l
   real(dp) :: y_l
   real(dp) :: y1
   real(dp) :: y2
   real(dp) :: v1_
   real(dp) :: v2_
   i_l = 0
   y_l = 0.0_dp
   y1 = 0.0_dp
   y2 = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (Link(i_l)%type == CONDUIT_c) then
         if (Link(i_l)%q0 /= 0.0_dp) then
            goto 100
         end if
         y1 = Node(Link(i_l)%node1)%newDepth - Link(i_l)%offset1
         y1 = merge(y1, 0.0_dp, (y1) >= (0.0_dp))
         if ((y1) <= (Link(i_l)%xsect%yFull)) then
            v1_ = y1
         else
            v1_ = Link(i_l)%xsect%yFull
         end if
         y1 = v1_
         y2 = Node(Link(i_l)%node2)%newDepth - Link(i_l)%offset2
         y2 = merge(y2, 0.0_dp, (y2) >= (0.0_dp))
         if ((y2) <= (Link(i_l)%xsect%yFull)) then
            v2_ = y2
         else
            v2_ = Link(i_l)%xsect%yFull
         end if
         y2 = v2_
         y_l = 0.5_dp * (y1 + y2)
         y_l = merge(y_l, 0.0001_dp, (y_l) >= (0.0001_dp))
         Link(i_l)%newDepth = y_l
      end if
      100 continue
      i_l = i_l + 1
   end do
end subroutine initLinkDepths

! flowrout.c:425
recursive subroutine initNodes()
   integer(int32) :: i_l
   logical :: b1_
   logical :: b2_
   i_l = 0
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      Node(i_l)%inflow = Node(i_l)%newLatFlow
      Node(i_l)%outflow = 0.0_dp
      Node(i_l)%newVolume = 0.0_dp
      b1_ = AllowPonding /= 0
      if (b1_) then
         b1_ = Node(i_l)%pondedArea > 0.0_dp
      end if
      b2_ = b1_
      if (b2_) then
         b2_ = Node(i_l)%newDepth > Node(i_l)%fullDepth
      end if
      if (b2_) then
         Node(i_l)%newVolume = Node(i_l)%fullVolume + ((Node(i_l)%newDepth - Node(i_l)%fullDepth) * Node(i_l)%pondedArea)
      else
         Node(i_l)%newVolume = node_getVolume(i_l, Node(i_l)%newDepth)
      end if
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (Link(i_l)%newFlow >= 0.0_dp) then
         Node(Link(i_l)%node1)%outflow = Node(Link(i_l)%node1)%outflow + Link(i_l)%newFlow
         Node(Link(i_l)%node2)%inflow = Node(Link(i_l)%node2)%inflow + Link(i_l)%newFlow
      else
         Node(Link(i_l)%node1)%inflow = Node(Link(i_l)%node1)%inflow - Link(i_l)%newFlow
         Node(Link(i_l)%node2)%outflow = Node(Link(i_l)%node2)%outflow - Link(i_l)%newFlow
      end if
      i_l = i_l + 1
   end do
end subroutine initNodes

! flowrout.c:472
recursive subroutine initLinks(routingModel)
   integer(int32), value :: routingModel
   integer(int32) :: i_l
   integer(int32) :: k_l
   i_l = 0
   k_l = 0
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (routingModel == SF) then
         Link(i_l)%newFlow = 0.0_dp
      else if (Link(i_l)%type == CONDUIT_c) then
         k_l = Link(i_l)%subIndex
         Conduit(k_l)%q1 = Link(i_l)%newFlow / real(Conduit(k_l)%barrels, dp)
         Conduit(k_l)%q2 = Conduit(k_l)%q1
         Conduit(k_l)%a1 = xsect_getAofY(Link(i_l)%xsect, Link(i_l)%newDepth)
         Conduit(k_l)%a2 = Conduit(k_l)%a1
         Link(i_l)%newVolume = (Conduit(k_l)%a1 * link_getLength(i_l)) * real(Conduit(k_l)%barrels, dp)
         Link(i_l)%oldVolume = Link(i_l)%newVolume
      end if
      i_l = i_l + 1
   end do
end subroutine initLinks

! flowrout.c:511
recursive function getLinkInflow(j_l, dt_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: dt_l
   real(dp) :: res_
   integer(int32) :: n1
   real(dp) :: q_l
   logical :: b1_
   logical :: b2_
   res_ = 0.0_dp
   n1 = Link(j_l)%node1
   q_l = 0.0_dp
   b1_ = Link(j_l)%type == CONDUIT_c
   if (.not. b1_) then
      b1_ = Link(j_l)%type == PUMP_c
   end if
   b2_ = b1_
   if (.not. b2_) then
      b2_ = Node(n1)%type == STORAGE_c
   end if
   if (b2_) then
      q_l = link_getInflow(j_l)
   else
      q_l = 0.0_dp
   end if
   res_ = node_getMaxOutflow(n1, q_l, dt_l)
   return
end function getLinkInflow

! flowrout.c:531
recursive subroutine updateStorageState(i_l, j_l, links, dt_l)
   integer(int32), value :: i_l
   integer(int32), value :: j_l
   integer(int32), pointer, intent(in) :: links(:)
   real(dp), value :: dt_l
   integer(int32) :: iter_l
   integer(int32) :: stopped
   real(dp) :: vFixed
   real(dp) :: v2
   real(dp) :: d1
   real(dp) :: d2
   real(dp) :: v1_
   logical :: b2_
   iter_l = 0
   stopped = 0
   vFixed = 0.0_dp
   v2 = 0.0_dp
   d1 = 0.0_dp
   d2 = 0.0_dp
   if (Node(i_l)%type /= STORAGE_c) then
      return
   end if
   if (Node(i_l)%updated /= 0) then
      return
   end if
   vFixed = Node(i_l)%oldVolume + ((0.5_dp * ((Node(i_l)%oldNetInflow + Node(i_l)%inflow) - Node(i_l)%outflow)) * dt_l)
   d1 = Node(i_l)%newDepth
   iter_l = 1
   stopped = 0
   do while ((iter_l < MAXITER) .and. (.not. (stopped /= 0)))
      v2 = vFixed - ((0.5_dp * getStorageOutflow(i_l, j_l, links, dt_l)) * dt_l)
      v2 = merge(0.0_dp, v2, (0.0_dp) >= (v2))
      Node(i_l)%overflow = 0.0_dp
      if (v2 > Node(i_l)%fullVolume) then
         if ((Node(i_l)%oldVolume) >= (Node(i_l)%fullVolume)) then
            v1_ = Node(i_l)%oldVolume
         else
            v1_ = Node(i_l)%fullVolume
         end if
         Node(i_l)%overflow = (v2 - (v1_)) / dt_l
         if (Node(i_l)%overflow < 0.0001_dp) then
            Node(i_l)%overflow = 0.0_dp
         end if
         b2_ = .not. (AllowPonding /= 0)
         if (.not. b2_) then
            b2_ = Node(i_l)%pondedArea == 0.0_dp
         end if
         if (b2_) then
            v2 = Node(i_l)%fullVolume
         end if
      end if
      Node(i_l)%newVolume = v2
      d2 = node_getDepth(i_l, v2)
      Node(i_l)%newDepth = d2
      d2 = ((1.0_dp - flowrout_OMEGA) * d1) + (flowrout_OMEGA * d2)
      if (abs(d2 - d1) <= STOPTOL) then
         stopped = 1
      end if
      d1 = d2
      iter_l = iter_l + 1
   end do
   Node(i_l)%updated = 1
end subroutine updateStorageState

! flowrout.c:605
recursive function getStorageOutflow(i_l, j_l, links, dt_l) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: j_l
   integer(int32), pointer, intent(in) :: links(:)
   real(dp), value :: dt_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: m_l
   real(dp) :: outflow
   res_ = 0.0_dp
   k_l = 0
   m_l = 0
   outflow = 0.0_dp
   k_l = j_l
   do while (k_l < Nobjects(LINK_c))
      m_l = links(k_l)
      if (Link(m_l)%node1 /= i_l) then
         exit
      end if
      outflow = outflow + getLinkInflow(m_l, dt_l)
      k_l = k_l + 1
   end do
   res_ = outflow
   return
end function getStorageOutflow

! flowrout.c:629
recursive subroutine setNewNodeState(j_l, dt_l)
   integer(int32), value :: j_l
   real(dp), value :: dt_l
   integer(int32) :: canPond
   real(dp) :: newNetInflow
   logical :: b1_
   real(dp) :: v2_
   canPond = 0
   newNetInflow = 0.0_dp
   if (Node(j_l)%type == STORAGE_c) then
      if (Node(j_l)%updated == 0) then
         call updateStorageState(j_l, Nobjects(LINK_c), null(), dt_l)
      end if
      return
   end if
   newNetInflow = (Node(j_l)%inflow - Node(j_l)%outflow) - Node(j_l)%losses
   Node(j_l)%newVolume = Node(j_l)%oldVolume + (newNetInflow * dt_l)
   if (Node(j_l)%newVolume < 0.0001_dp) then
      Node(j_l)%newVolume = 0.0_dp
   end if
   Node(j_l)%overflow = 0.0_dp
   b1_ = AllowPonding /= 0
   if (b1_) then
      b1_ = Node(j_l)%pondedArea > 0.0_dp
   end if
   canPond = merge(1, 0, b1_)
   if (Node(j_l)%newVolume > Node(j_l)%fullVolume) then
      if ((Node(j_l)%oldVolume) >= (Node(j_l)%fullVolume)) then
         v2_ = Node(j_l)%oldVolume
      else
         v2_ = Node(j_l)%fullVolume
      end if
      Node(j_l)%overflow = (Node(j_l)%newVolume - (v2_)) / dt_l
      if (Node(j_l)%overflow < 0.0001_dp) then
         Node(j_l)%overflow = 0.0_dp
      end if
      if (.not. (canPond /= 0)) then
         Node(j_l)%newVolume = Node(j_l)%fullVolume
      end if
   end if
   Node(j_l)%newDepth = node_getDepth(j_l, Node(j_l)%newVolume)
end subroutine setNewNodeState

! flowrout.c:673
recursive subroutine setNewLinkState(j_l)
   integer(int32), value :: j_l
   integer(int32) :: k_l
   real(dp) :: a_l
   real(dp) :: y1
   real(dp) :: y2
   k_l = 0
   a_l = 0.0_dp
   y1 = 0.0_dp
   y2 = 0.0_dp
   Link(j_l)%newDepth = 0.0_dp
   Link(j_l)%newVolume = 0.0_dp
   if (Link(j_l)%type == CONDUIT_c) then
      k_l = Link(j_l)%subIndex
      a_l = 0.5_dp * (Conduit(k_l)%a1 + Conduit(k_l)%a2)
      Link(j_l)%newVolume = (a_l * link_getLength(j_l)) * real(Conduit(k_l)%barrels, dp)
      y1 = xsect_getYofA(Link(j_l)%xsect, Conduit(k_l)%a1)
      y2 = xsect_getYofA(Link(j_l)%xsect, Conduit(k_l)%a2)
      Link(j_l)%newDepth = 0.5_dp * (y1 + y2)
      call updateNodeDepth(Link(j_l)%node1, y1 + Link(j_l)%offset1)
      call updateNodeDepth(Link(j_l)%node2, y2 + Link(j_l)%offset2)
      if (Conduit(k_l)%a1 >= Link(j_l)%xsect%aFull) then
         Conduit(k_l)%capacityLimited = 1
         Conduit(k_l)%fullState = ALL_FULL
      else
         Conduit(k_l)%capacityLimited = 0
         Conduit(k_l)%fullState = 0
      end if
   end if
end subroutine setNewLinkState

! flowrout.c:717
recursive subroutine updateNodeDepth(i_l, y_l)
   integer(int32), value :: i_l
   real(dp), value :: y_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   if (Node(i_l)%type == STORAGE_c) then
      return
   end if
   b1_ = Node(i_l)%type /= OUTFALL_c
   if (b1_) then
      b1_ = Node(i_l)%degree > 0
   end if
   b2_ = b1_
   if (b2_) then
      b2_ = Node(i_l)%overflow > 0.0_dp
   end if
   if (b2_) then
      y_l = Node(i_l)%fullDepth
   end if
   if (Node(i_l)%newDepth < y_l) then
      Node(i_l)%newDepth = y_l
      b3_ = Node(i_l)%fullDepth > 0.0_dp
      if (b3_) then
         b3_ = y_l > Node(i_l)%fullDepth
      end if
      if (b3_) then
         Node(i_l)%newDepth = Node(i_l)%fullDepth
      end if
   end if
end subroutine updateNodeDepth

! flowrout.c:748
recursive function steadyflow_execute(j_l, qin, qout, tStep) result(res_)
   integer(int32), value :: j_l
   real(dp), intent(inout), target :: qin
   real(dp), intent(inout), target :: qout
   real(dp), value :: tStep
   integer(int32) :: res_
   integer(int32) :: k_l
   real(dp) :: s_l
   real(dp) :: q_l
   res_ = 0
   k_l = 0
   s_l = 0.0_dp
   q_l = 0.0_dp
   if (Link(j_l)%type == CONDUIT_c) then
      k_l = Link(j_l)%subIndex
      q_l = (qin) / real(Conduit(k_l)%barrels, dp)
      if (Link(j_l)%xsect%type == DUMMY) then
         Conduit(k_l)%a1 = 0.0_dp
      else
         q_l = q_l - link_getLossRate(j_l, SF, q_l, tStep)
         if (q_l > Link(j_l)%qFull) then
            q_l = Link(j_l)%qFull
            Conduit(k_l)%a1 = Link(j_l)%xsect%aFull
            qin = q_l * real(Conduit(k_l)%barrels, dp)
         else
            s_l = q_l / Conduit(k_l)%beta
            Conduit(k_l)%a1 = xsect_getAofS(Link(j_l)%xsect, s_l)
         end if
      end if
      Conduit(k_l)%a2 = Conduit(k_l)%a1
      Conduit(k_l)%q1Old = Conduit(k_l)%q1
      Conduit(k_l)%q2Old = Conduit(k_l)%q2
      Conduit(k_l)%q1 = q_l
      Conduit(k_l)%q2 = q_l
      qout = q_l * real(Conduit(k_l)%barrels, dp)
   else
      qout = qin
   end if
   res_ = 1
   return
end function steadyflow_execute

! forcmain.c:37
recursive function forcemain_getEquivN(j_l, k_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp) :: res_
   type(TXsect), target :: xsect_l
   real(dp) :: f_l
   real(dp) :: d_l
   res_ = 0.0_dp
   xsect_l = Link(j_l)%xsect
   f_l = 0.0_dp
   d_l = xsect_l%yFull
   select case (ForceMainEqn)
   case (0)
      res_ = (1.067_dp / xsect_l%rBot) * ((d_l / Conduit(k_l)%slope) ** 0.04_dp)
      return
   case (1)
      f_l = forcemain_getFricFactor(xsect_l%rBot, d_l / 4.0_dp, 1.0e12_dp)
      res_ = sqrt(f_l / 185.0_dp) * (d_l ** (1.0_dp / 6.0_dp))
      return
   end select
   res_ = Conduit(k_l)%roughness
   return
end function forcemain_getEquivN

! forcmain.c:64
recursive function forcemain_getRoughFactor(j_l, lengthFactor) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: lengthFactor
   real(dp) :: res_
   type(TXsect), target :: xsect_l
   real(dp) :: r_l
   res_ = 0.0_dp
   xsect_l = Link(j_l)%xsect
   r_l = 0.0_dp
   select case (ForceMainEqn)
   case (0)
      r_l = (1.318_dp * xsect_l%rBot) * (lengthFactor ** 0.54_dp)
      res_ = 32.2_dp / (r_l ** 1.852_dp)
      return
   case (1)
      res_ = (1.0_dp / 8.0_dp) / lengthFactor
      return
   end select
   res_ = 0.0_dp
   return
end function forcemain_getRoughFactor

! forcmain.c:88
recursive function forcemain_getFricSlope(j_l, v_l, hrad) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: v_l
   real(dp), value :: hrad
   real(dp) :: res_
   real(dp) :: re
   real(dp) :: f_l
   type(TXsect), target :: xsect_l
   res_ = 0.0_dp
   re = 0.0_dp
   f_l = 0.0_dp
   xsect_l = Link(j_l)%xsect
   select case (ForceMainEqn)
   case (0)
      res_ = (xsect_l%sBot * (v_l ** 0.852_dp)) / (hrad ** 1.1667_dp)
      return
   case (1)
      re = forcemain_getReynolds(v_l, hrad)
      f_l = forcemain_getFricFactor(xsect_l%rBot, hrad, re)
      res_ = ((f_l * xsect_l%sBot) * v_l) / hrad
      return
   end select
   res_ = 0.0_dp
   return
end function forcemain_getFricSlope

! forcmain.c:117
recursive function forcemain_getReynolds(v_l, hrad) result(res_)
   real(dp), value :: v_l
   real(dp), value :: hrad
   real(dp) :: res_
   res_ = 0.0_dp
   res_ = ((4.0_dp * hrad) * v_l) / VISCOS
   return
end function forcemain_getReynolds

! forcmain.c:130
recursive function forcemain_getFricFactor(e_l, hrad, re) result(res_)
   real(dp), value :: e_l
   real(dp), value :: hrad
   real(dp), value :: re
   real(dp) :: res_
   real(dp) :: f_l
   res_ = 0.0_dp
   f_l = 0.0_dp
   if (re < 10.0_dp) then
      re = 10.0_dp
   end if
   if (re <= 2000.0_dp) then
      f_l = 64.0_dp / re
   else if (re < 4000.0_dp) then
      f_l = forcemain_getFricFactor(e_l, hrad, 4000.0_dp)
      f_l = 0.032_dp + (((f_l - 0.032_dp) * (re - 2000.0_dp)) / 2000.0_dp)
   else
      f_l = (e_l / 3.7_dp) / (4.0_dp * hrad)
      if (re < 1.0e10_dp) then
         f_l = f_l + (5.74_dp / (re ** 0.9_dp))
      end if
      f_l = log10(f_l)
      f_l = (0.25_dp / f_l) / f_l
   end if
   res_ = f_l
   return
end function forcemain_getFricFactor

! gage.c:58
recursive function gage_readParams(j_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32) :: err_l
   type(CPtr) :: id
   integer(int8), target :: fname(0:259)
   integer(int8), target :: staID(0:1024)
   real(dp), target :: x_l(0:6)
   integer(int64) :: dum1_
   res_ = 0
   k_l = 0
   err_l = 0
   id = cnull()
   fname = 0_int8
   staID = 0_int8
   x_l = 0.0_dp
   if (ntoks < 2) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(GAGE_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   x_l(0) = -1.0_dp
   x_l(1) = 1.0_dp
   x_l(2) = 3600.0_dp
   x_l(3) = 1.0_dp
   x_l(4) = -693594.0_dp
   x_l(5) = -693594.0_dp
   x_l(6) = 0.0_dp
   fname(0) = c8(0)
   staID(0) = c8(0)
   if (ntoks < 5) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   k_l = findmatch(tok_l(4), GageDataWords)
   if (k_l == RAIN_TSERIES) then
      err_l = readGageSeriesFormat(tok_l, ntoks, x_l)
   else if (k_l == RAIN_FILE) then
      if (ntoks < 8) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      dum1_ = sstrncpy(cview(fname), tok_l(5), 259_int64)
      dum1_ = sstrncpy(cview(staID), tok_l(6), 1024_int64)
      err_l = readGageFileFormat(tok_l, ntoks, x_l)
   else
      res_ = error_setInpError(ERR_KEYWORD, tok_l(4))
      return
   end if
   if (err_l > 0) then
      res_ = err_l
      return
   end if
   Gage(j_l)%ID = id
   Gage(j_l)%tSeries = d2i(x_l(0))
   Gage(j_l)%rainType = d2i(x_l(1))
   Gage(j_l)%rainInterval = d2i(x_l(2))
   Gage(j_l)%snowFactor = x_l(3)
   Gage(j_l)%rainUnits = d2i(x_l(6))
   if (Gage(j_l)%tSeries >= 0) then
      Gage(j_l)%dataSource = RAIN_TSERIES
   else
      Gage(j_l)%dataSource = RAIN_FILE
   end if
   if (Gage(j_l)%dataSource == RAIN_FILE) then
      dum1_ = sstrncpy(cview(Gage(j_l)%fname), addAbsolutePath(cview(fname)), 259_int64)
      dum1_ = sstrncpy(cview(Gage(j_l)%staID), cview(staID), 1024_int64)
      Gage(j_l)%startFileDate = x_l(4)
      Gage(j_l)%endFileDate = x_l(5)
   end if
   Gage(j_l)%unitsFactor = 1.0_dp
   Gage(j_l)%coGage = -1
   Gage(j_l)%isUsed = 0
   res_ = 0
   return
end function gage_readParams

! gage.c:133
recursive function readGageSeriesFormat(tok_l, ntoks, x_l) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   real(dp), pointer, intent(in) :: x_l(:)
   integer(int32) :: res_
   integer(int32) :: m_l
   integer(int32) :: ts
   real(dp), target :: aTime
   integer(int64) :: dum1_
   res_ = 0
   m_l = 0
   ts = 0
   aTime = 0.0_dp
   if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   m_l = findmatch(tok_l(1), RainTypeWords)
   if (m_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   x_l(1) = real(m_l, dp)
   if (getDouble(tok_l(2), x_l(2)) /= 0) then
      x_l(2) = cfloor((x_l(2) * 3600.0_dp) + 0.5_dp)
   else if (datetime_strToTime(tok_l(2), aTime) /= 0) then
      x_l(2) = cfloor((aTime * 86400.0_dp) + 0.5_dp)
   else
      res_ = error_setInpError(ERR_DATETIME, tok_l(2))
      return
   end if
   if (x_l(2) <= 0.0_dp) then
      res_ = error_setInpError(ERR_DATETIME, tok_l(2))
      return
   end if
   if (.not. (getDouble(tok_l(3), x_l(3)) /= 0)) then
      res_ = error_setInpError(ERR_DATETIME, tok_l(3))
      return
   end if
   ts = project_findObject(TSERIES_c, tok_l(5))
   if (ts < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(5))
      return
   end if
   x_l(0) = real(ts, dp)
   dum1_ = sstrncpy(tok_l(2), lit_0, 0_int64)
   res_ = 0
   return
end function readGageSeriesFormat

! gage.c:168
recursive function readGageFileFormat(tok_l, ntoks, x_l) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   real(dp), pointer, intent(in) :: x_l(:)
   integer(int32) :: res_
   integer(int32) :: m_l
   integer(int32) :: u_l
   real(dp), target :: aDate
   real(dp), target :: aTime
   logical :: b1_
   res_ = 0
   m_l = 0
   u_l = 0
   aDate = 0.0_dp
   aTime = 0.0_dp
   m_l = findmatch(tok_l(1), RainTypeWords)
   if (m_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   x_l(1) = real(m_l, dp)
   if (getDouble(tok_l(2), x_l(2)) /= 0) then
      x_l(2) = x_l(2) * 3600.0_dp
   else if (datetime_strToTime(tok_l(2), aTime) /= 0) then
      x_l(2) = cfloor((aTime * 86400.0_dp) + 0.5_dp)
   else
      res_ = error_setInpError(ERR_DATETIME, tok_l(2))
      return
   end if
   if (x_l(2) <= 0.0_dp) then
      res_ = error_setInpError(ERR_DATETIME, tok_l(2))
      return
   end if
   if (.not. (getDouble(tok_l(3), x_l(3)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(3))
      return
   end if
   u_l = findmatch(tok_l(7), RainUnitsWords)
   if (u_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(7))
      return
   end if
   x_l(6) = real(u_l, dp)
   b1_ = ntoks > 8
   if (b1_) then
      b1_ = cget(tok_l(8), 0) /= 42
   end if
   if (b1_) then
      if (.not. (datetime_strToDate(tok_l(8), aDate) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, tok_l(8))
         return
      end if
      x_l(4) = real(real(aDate, sp), dp)
   end if
   res_ = 0
   return
end function readGageFileFormat

! gage.c:209
recursive subroutine gage_validate(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: gageInterval
   logical :: b1_
   logical :: b2_
   logical :: b3_
   i_l = 0
   k_l = 0
   gageInterval = 0
   if (Gage(j_l)%dataSource == RAIN_TSERIES) then
      if (.not. (Gage(j_l)%isUsed /= 0)) then
         return
      end if
      k_l = Gage(j_l)%tSeries
      i_l = 0
      do while (i_l < j_l)
         b1_ = Gage(i_l)%dataSource == RAIN_TSERIES
         if (b1_) then
            b1_ = Gage(i_l)%tSeries == k_l
         end if
         b2_ = b1_
         if (b2_) then
            b2_ = Gage(i_l)%isUsed /= 0
         end if
         if (b2_) then
            Gage(j_l)%coGage = i_l
            if (Gage(j_l)%rainType /= Gage(i_l)%rainType) then
               call report_writeErrorMsg(ERR_RAIN_GAGE_FORMAT, Gage(j_l)%ID)
            end if
            return
         end if
         i_l = i_l + 1
      end do
      if (Tseries(k_l)%refersTo >= 0) then
         call report_writeErrorMsg(ERR_RAIN_GAGE_TSERIES, Gage(j_l)%ID)
      end if
      gageInterval = d2i(cfloor((Tseries(k_l)%dxMin * 86400.0_dp) + 0.5_dp))
      b3_ = gageInterval > 0
      if (b3_) then
         b3_ = Gage(j_l)%rainInterval > gageInterval
      end if
      if (b3_) then
         call report_writeErrorMsg(ERR_RAIN_GAGE_INTERVAL, Gage(j_l)%ID)
      end if
      if (Gage(j_l)%rainInterval < gageInterval) then
         call report_writeWarningMsg(lit_156, Gage(j_l)%ID)
      end if
      if (Gage(j_l)%rainInterval < WetStep) then
         call report_writeWarningMsg(lit_157, Gage(j_l)%ID)
         WetStep = Gage(j_l)%rainInterval
      end if
   end if
end subroutine gage_validate

! gage.c:270
recursive subroutine gage_initState(j_l)
   integer(int32), value :: j_l
   Gage(j_l)%rainfall = 0.0_dp
   Gage(j_l)%apiRainfall = -10000000000.0_dp
   Gage(j_l)%reportRainfall = 0.0_dp
   if (IgnoreRainfall /= 0) then
      return
   end if
   if (Gage(j_l)%dataSource == RAIN_FILE) then
      Gage(j_l)%currentFilePos = Gage(j_l)%startFilePos
      if (UnitSystem == SI) then
         Gage(j_l)%unitsFactor = 25.4_dp
      end if
   end if
   if (getFirstRainfall(j_l) /= 0) then
      Gage(j_l)%endDate = datetime_addSeconds(Gage(j_l)%startDate, real(Gage(j_l)%rainInterval, dp))
      if (Gage(j_l)%startDate > StartDateTime) then
         Gage(j_l)%nextDate = Gage(j_l)%startDate
         Gage(j_l)%nextRainfall = Gage(j_l)%rainfall
         Gage(j_l)%startDate = StartDateTime
         Gage(j_l)%endDate = Gage(j_l)%nextDate
         Gage(j_l)%rainfall = 0.0_dp
      else if (.not. (getNextRainfall(j_l) /= 0)) then
         Gage(j_l)%nextDate = -693594.0_dp
      end if
   else
      Gage(j_l)%startDate = -693594.0_dp
   end if
   call initPastRain(j_l)
end subroutine gage_initState

! gage.c:323
recursive subroutine gage_setState(j_l, t_l)
   integer(int32), value :: j_l
   real(dp), value :: t_l
   if (Gage(j_l)%isUsed == 0) then
      return
   end if
   if (IgnoreRainfall /= 0) then
      Gage(j_l)%rainfall = 0.0_dp
      return
   end if
   if (Gage(j_l)%coGage >= 0) then
      Gage(j_l)%rainfall = Gage(Gage(j_l)%coGage)%rainfall
      return
   end if
   if (Gage(j_l)%apiRainfall /= (-10000000000.0_dp)) then
      Gage(j_l)%rainfall = Gage(j_l)%apiRainfall
      return
   end if
   t_l = t_l + OneSecond
   do
      if (Gage(j_l)%startDate == (-693594.0_dp)) then
         Gage(j_l)%rainfall = 0.0_dp
         return
      end if
      if (t_l < Gage(j_l)%startDate) then
         Gage(j_l)%rainfall = 0.0_dp
         return
      end if
      if (t_l < Gage(j_l)%endDate) then
         return
      end if
      if (Gage(j_l)%nextDate == (-693594.0_dp)) then
         Gage(j_l)%rainfall = 0.0_dp
         return
      end if
      if (t_l < Gage(j_l)%nextDate) then
         Gage(j_l)%rainfall = 0.0_dp
         return
      end if
      Gage(j_l)%startDate = Gage(j_l)%nextDate
      Gage(j_l)%endDate = datetime_addSeconds(Gage(j_l)%startDate, real(Gage(j_l)%rainInterval, dp))
      Gage(j_l)%rainfall = Gage(j_l)%nextRainfall
      if (.not. (getNextRainfall(j_l) /= 0)) then
         Gage(j_l)%nextDate = -693594.0_dp
      end if
   end do
end subroutine gage_setState

! gage.c:406
recursive subroutine initPastRain(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   i_l = 0
   i_l = 0
   do while (i_l <= 48)
      Gage(j_l)%pastRain(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   Gage(j_l)%pastInterval = 0
end subroutine initPastRain

! gage.c:417
recursive subroutine gage_updatePastRain(j_l, tStep)
   integer(int32), value :: j_l
   integer(int32), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: t_l
   real(dp) :: r_l
   i_l = 0
   t_l = 0
   r_l = 0.0_dp
   r_l = Gage(j_l)%rainfall / 3600.0_dp
   do while (tStep > 0)
      t_l = 3600 - Gage(j_l)%pastInterval
      if (tStep > t_l) then
         Gage(j_l)%pastRain(0) = Gage(j_l)%pastRain(0) + (real(t_l, dp) * r_l)
         i_l = 48
         do while (i_l > 0)
            Gage(j_l)%pastRain(i_l) = Gage(j_l)%pastRain(i_l - 1)
            i_l = i_l - 1
         end do
         Gage(j_l)%pastInterval = 0
         Gage(j_l)%pastRain(0) = 0.0_dp
         tStep = tStep - t_l
      else
         Gage(j_l)%pastRain(0) = Gage(j_l)%pastRain(0) + (real(tStep, dp) * r_l)
         Gage(j_l)%pastInterval = Gage(j_l)%pastInterval + tStep
         tStep = 0
      end if
   end do
end subroutine gage_updatePastRain

! gage.c:468
recursive function gage_getPastRain(j_l, n_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: n_l
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: result_l
   res_ = 0.0_dp
   i_l = 0
   result_l = 0.0_dp
   if ((n_l < 1) .or. (n_l > 48)) then
      res_ = 0.0_dp
      return
   end if
   i_l = 1
   do while (i_l <= n_l)
      result_l = result_l + Gage(j_l)%pastRain(i_l)
      i_l = i_l + 1
   end do
   res_ = result_l
   return
end function gage_getPastRain

! gage.c:486
recursive function gage_getNextRainDate(j_l, aDate) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: aDate
   real(dp) :: res_
   res_ = 0.0_dp
   if (Gage(j_l)%isUsed == 0) then
      res_ = aDate
      return
   end if
   aDate = aDate + OneSecond
   if (aDate < Gage(j_l)%startDate) then
      res_ = Gage(j_l)%startDate
      return
   end if
   if (aDate < Gage(j_l)%endDate) then
      res_ = Gage(j_l)%endDate
      return
   end if
   res_ = Gage(j_l)%nextDate
   return
end function gage_getNextRainDate

! gage.c:503
recursive function gage_getPrecip(j_l, rainfall_l, snowfall) result(res_)
   integer(int32), value :: j_l
   real(dp), intent(inout), target :: rainfall_l
   real(dp), intent(inout), target :: snowfall
   real(dp) :: res_
   res_ = 0.0_dp
   rainfall_l = 0.0_dp
   snowfall = 0.0_dp
   if ((.not. (IgnoreSnowmelt /= 0)) .and. (Temp%ta <= Snow%snotmp)) then
      snowfall = (Gage(j_l)%rainfall * Gage(j_l)%snowFactor) / UCF(RAINFALL)
   else
      rainfall_l = Gage(j_l)%rainfall / UCF(RAINFALL)
   end if
   res_ = (rainfall_l) + (snowfall)
   return
end function gage_getPrecip

! gage.c:524
recursive subroutine gage_setReportRainfall(j_l, reportDate)
   integer(int32), value :: j_l
   real(dp), value :: reportDate
   real(dp) :: result_l
   result_l = 0.0_dp
   if (Gage(j_l)%coGage >= 0) then
      Gage(j_l)%reportRainfall = Gage(Gage(j_l)%coGage)%reportRainfall
      return
   end if
   if (Gage(j_l)%apiRainfall /= (-10000000000.0_dp)) then
      Gage(j_l)%reportRainfall = Gage(j_l)%apiRainfall
      return
   end if
   reportDate = reportDate + OneSecond
   if (reportDate < Gage(j_l)%endDate) then
      result_l = Gage(j_l)%rainfall
   else if (reportDate < Gage(j_l)%nextDate) then
      result_l = 0.0_dp
   else
      result_l = Gage(j_l)%nextRainfall
   end if
   Gage(j_l)%reportRainfall = result_l
end subroutine gage_setReportRainfall

! gage.c:567
recursive function getFirstRainfall(j_l) result(res_)
   integer(int32), value :: j_l
   integer(int32) :: res_
   integer(int32) :: k_l
   real(sp), target :: vFirst
   real(dp), target :: rFirst
   logical :: b1_
   integer(int32) :: dum2_
   integer(int64) :: dum3_
   res_ = 0
   k_l = 0
   vFirst = 0.0_sp
   rFirst = 0.0_dp
   Gage(j_l)%startDate = -693594.0_dp
   Gage(j_l)%rainfall = 0.0_dp
   Gage(j_l)%rainAccum = 0.0_dp
   if (Gage(j_l)%dataSource == RAIN_FILE) then
      b1_ = associated(Frain%file)
      if (b1_) then
         b1_ = Gage(j_l)%endFilePos > Gage(j_l)%startFilePos
      end if
      if (b1_) then
         dum2_ = c_fseek(Frain%file, Gage(j_l)%startFilePos, 0)
         dum3_ = c_fread_r8(Gage(j_l)%startDate, Frain%file)
         dum3_ = c_fread_r4(vFirst, Frain%file)
         Gage(j_l)%currentFilePos = c_ftell(Frain%file)
         Gage(j_l)%rainfall = convertRainfall(j_l, real(vFirst, dp))
         res_ = 1
         return
      end if
      res_ = 0
      return
   else
      k_l = Gage(j_l)%tSeries
      if (k_l >= 0) then
         if (table_getFirstEntry(Tseries(k_l), Gage(j_l)%startDate, rFirst) /= 0) then
            Gage(j_l)%rainfall = convertRainfall(j_l, rFirst)
            res_ = 1
            return
         end if
      end if
      res_ = 0
      return
   end if
end function getFirstRainfall

! gage.c:624
recursive function getNextRainfall(j_l) result(res_)
   integer(int32), value :: j_l
   integer(int32) :: res_
   integer(int32) :: k_l
   real(sp), target :: vNext
   real(dp), target :: rNext
   logical :: b1_
   integer(int32) :: dum2_
   integer(int64) :: dum3_
   res_ = 0
   k_l = 0
   vNext = 0.0_sp
   rNext = 0.0_dp
   Gage(j_l)%nextRainfall = 0.0_dp
   do
      if (Gage(j_l)%dataSource == RAIN_FILE) then
         b1_ = associated(Frain%file)
         if (b1_) then
            b1_ = Gage(j_l)%currentFilePos < Gage(j_l)%endFilePos
         end if
         if (b1_) then
            dum2_ = c_fseek(Frain%file, Gage(j_l)%currentFilePos, 0)
            dum3_ = c_fread_r8(Gage(j_l)%nextDate, Frain%file)
            dum3_ = c_fread_r4(vNext, Frain%file)
            Gage(j_l)%currentFilePos = c_ftell(Frain%file)
            rNext = convertRainfall(j_l, real(vNext, dp))
         else
            res_ = 0
            return
         end if
      else
         k_l = Gage(j_l)%tSeries
         if (k_l >= 0) then
            if (.not. (table_getNextEntry(Tseries(k_l), Gage(j_l)%nextDate, rNext) /= 0)) then
               res_ = 0
               return
            end if
            rNext = convertRainfall(j_l, rNext)
         else
            res_ = 0
            return
         end if
      end if
      if (.not. (rNext == 0.0_dp)) exit
   end do
   Gage(j_l)%nextRainfall = rNext
   res_ = 1
   return
end function getNextRainfall

! gage.c:674
recursive function convertRainfall(j_l, r_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: r_l
   real(dp) :: res_
   real(dp) :: r1
   res_ = 0.0_dp
   r1 = 0.0_dp
   select case (Gage(j_l)%rainType)
   case (0)
      r1 = r_l
   case (1)
      r1 = (r_l / real(Gage(j_l)%rainInterval, dp)) * 3600.0_dp
   case (2)
      if (r_l < Gage(j_l)%rainAccum) then
         r1 = (r_l / real(Gage(j_l)%rainInterval, dp)) * 3600.0_dp
      else
         r1 = ((r_l - Gage(j_l)%rainAccum) / real(Gage(j_l)%rainInterval, dp)) * 3600.0_dp
      end if
      Gage(j_l)%rainAccum = r_l
   case default
      r1 = r_l
   end select
   res_ = (r1 * Gage(j_l)%unitsFactor) * Adjust%rainFactor
   return
end function convertRainfall

! gwater.c:119
recursive function gwater_readAquiferParams(j_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: p_l
   real(dp), target :: x_l(0:11)
   type(CPtr) :: id
   res_ = 0
   i_l = 0
   p_l = 0
   x_l = 0.0_dp
   id = cnull()
   if (ntoks < 13) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(AQUIFER_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   i_l = 0
   do while (i_l < 11)
      x_l(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 1
   do while (i_l < 13)
      if (.not. (getDouble(tok_l(i_l), x_l(i_l - 1)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   p_l = -1
   if (ntoks > 13) then
      p_l = project_findObject(TIMEPATTERN, tok_l(13))
      if (p_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(13))
         return
      end if
   end if
   Aquifer(j_l)%ID = id
   Aquifer(j_l)%porosity = x_l(0)
   Aquifer(j_l)%wiltingPoint = x_l(1)
   Aquifer(j_l)%fieldCapacity = x_l(2)
   Aquifer(j_l)%conductivity = x_l(3) / UCF(RAINFALL)
   Aquifer(j_l)%conductSlope = x_l(4)
   Aquifer(j_l)%tensionSlope = x_l(5) / UCF(LENGTH)
   Aquifer(j_l)%upperEvapFrac = x_l(6)
   Aquifer(j_l)%lowerEvapDepth = x_l(7) / UCF(LENGTH)
   Aquifer(j_l)%lowerLossCoeff = x_l(8) / UCF(RAINFALL)
   Aquifer(j_l)%bottomElev = x_l(9) / UCF(LENGTH)
   Aquifer(j_l)%waterTableElev = x_l(10) / UCF(LENGTH)
   Aquifer(j_l)%upperMoisture = x_l(11)
   Aquifer(j_l)%upperEvapPat = p_l
   res_ = 0
   return
end function gwater_readAquiferParams

! gwater.c:179
recursive function gwater_readGroundwaterParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   integer(int32) :: n_l
   real(dp), target :: x_l(0:10)
   type(TGroundwater), pointer :: gw_l
   logical :: b1_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   m_l = 0
   n_l = 0
   x_l = 0.0_dp
   nullify(gw_l)
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(SUBCATCH_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   if (ntoks < 11) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   k_l = project_findObject(AQUIFER_c, tok_l(1))
   if (k_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   n_l = project_findObject(NODE_c, tok_l(2))
   if (n_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   i_l = 0
   do while (i_l < 7)
      if (.not. (getDouble(tok_l(i_l + 3), x_l(i_l)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 3))
         return
      end if
      i_l = i_l + 1
   end do
   i_l = 7
   do while (i_l < 11)
      x_l(i_l) = -10000000000.0_dp
      m_l = i_l + 3
      b1_ = ntoks > m_l
      if (b1_) then
         b1_ = cget(tok_l(m_l), 0) /= 42
      end if
      if (b1_) then
         if (.not. (getDouble(tok_l(m_l), x_l(i_l)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(m_l))
            return
         end if
         if (i_l < 10) then
            x_l(i_l) = x_l(i_l) / UCF(LENGTH)
         end if
      end if
      i_l = i_l + 1
   end do
   if (.not. associated(Subcatch(j_l)%groundwater)) then
      allocate(gw_l)
      if (.not. associated(gw_l)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
      Subcatch(j_l)%groundwater => gw_l
   else
      gw_l => Subcatch(j_l)%groundwater
   end if
   gw_l%aquifer = k_l
   gw_l%node = n_l
   gw_l%surfElev = x_l(0) / UCF(LENGTH)
   gw_l%a1 = x_l(1)
   gw_l%b1 = x_l(2)
   gw_l%a2 = x_l(3)
   gw_l%b2 = x_l(4)
   gw_l%a3 = x_l(5)
   gw_l%fixedDepth = x_l(6) / UCF(LENGTH)
   gw_l%nodeElev = x_l(7)
   gw_l%bottomElev = x_l(8)
   gw_l%waterTableElev = x_l(9)
   gw_l%upperMoisture = x_l(10)
   res_ = 0
   return
end function gwater_readGroundwaterParams

! gwater.c:258
recursive function gwater_readFlowExpression(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int8), target :: exprStr(0:1024)
   type(MathExpr), pointer :: expr
   integer(int64) :: dum1_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   exprStr = 0_int8
   nullify(expr)
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(SUBCATCH_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   k_l = 1
   if (match(tok_l(1), lit_158) /= 0) then
      k_l = 1
   else if (match(tok_l(1), lit_159) /= 0) then
      k_l = 2
   else
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   dum1_ = sstrncpy(cview(exprStr), tok_l(2), 1024_int64)
   i_l = 3
   do while (i_l < ntoks)
      dum1_ = sstrcat(cview(exprStr), lit_33, int(1024 + 1, int64))
      dum1_ = sstrcat(cview(exprStr), tok_l(i_l), int(1024 + 1, int64))
      i_l = i_l + 1
   end do
   if (k_l == 1) then
      call mathexpr_delete(Subcatch(j_l)%gwLatFlowExpr)
   else
      call mathexpr_delete(Subcatch(j_l)%gwDeepFlowExpr)
   end if
   expr => mathexpr_create(cview(exprStr), gwater_getVariableIndex)
   if (.not. associated(expr)) then
      res_ = error_setInpError(ERR_MATH_EXPR, lit_0)
      return
   end if
   if (k_l == 1) then
      Subcatch(j_l)%gwLatFlowExpr => expr
   else
      Subcatch(j_l)%gwDeepFlowExpr => expr
   end if
   res_ = 0
   return
end function gwater_readFlowExpression

! gwater.c:315
recursive subroutine gwater_deleteFlowExpression(j_l)
   integer(int32), value :: j_l
   call mathexpr_delete(Subcatch(j_l)%gwLatFlowExpr)
   call mathexpr_delete(Subcatch(j_l)%gwDeepFlowExpr)
end subroutine gwater_deleteFlowExpression

! gwater.c:328
recursive subroutine gwater_validateAquifer(j_l)
   integer(int32), value :: j_l
   integer(int32) :: p_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   logical :: b6_
   logical :: b7_
   logical :: b8_
   logical :: b9_
   logical :: b10_
   logical :: b11_
   p_l = 0
   b1_ = Aquifer(j_l)%porosity <= 0.0_dp
   if (.not. b1_) then
      b1_ = Aquifer(j_l)%fieldCapacity >= Aquifer(j_l)%porosity
   end if
   b2_ = b1_
   if (.not. b2_) then
      b2_ = Aquifer(j_l)%wiltingPoint >= Aquifer(j_l)%fieldCapacity
   end if
   b3_ = b2_
   if (.not. b3_) then
      b3_ = Aquifer(j_l)%conductivity <= 0.0_dp
   end if
   b4_ = b3_
   if (.not. b4_) then
      b4_ = Aquifer(j_l)%conductSlope < 0.0_dp
   end if
   b5_ = b4_
   if (.not. b5_) then
      b5_ = Aquifer(j_l)%tensionSlope < 0.0_dp
   end if
   b6_ = b5_
   if (.not. b6_) then
      b6_ = Aquifer(j_l)%upperEvapFrac < 0.0_dp
   end if
   b7_ = b6_
   if (.not. b7_) then
      b7_ = Aquifer(j_l)%lowerEvapDepth < 0.0_dp
   end if
   b8_ = b7_
   if (.not. b8_) then
      b8_ = Aquifer(j_l)%waterTableElev < Aquifer(j_l)%bottomElev
   end if
   b9_ = b8_
   if (.not. b9_) then
      b9_ = Aquifer(j_l)%upperMoisture > Aquifer(j_l)%porosity
   end if
   b10_ = b9_
   if (.not. b10_) then
      b10_ = Aquifer(j_l)%upperMoisture < Aquifer(j_l)%wiltingPoint
   end if
   if (b10_) then
      call report_writeErrorMsg(ERR_AQUIFER_PARAMS, Aquifer(j_l)%ID)
   end if
   p_l = Aquifer(j_l)%upperEvapPat
   b11_ = p_l >= 0
   if (b11_) then
      b11_ = Pattern(p_l)%type /= MONTHLY_PATTERN
   end if
   if (b11_) then
      call report_writeErrorMsg(ERR_AQUIFER_PARAMS, Aquifer(j_l)%ID)
   end if
end subroutine gwater_validateAquifer

! gwater.c:359
recursive subroutine gwater_validate(j_l)
   integer(int32), value :: j_l
   type(TAquifer), target :: a_l
   type(TGroundwater), pointer :: gw_l
   a_l = zero_TAquifer
   nullify(gw_l)
   gw_l => Subcatch(j_l)%groundwater
   if (associated(gw_l)) then
      a_l = Aquifer(gw_l%aquifer)
      if (gw_l%bottomElev == (-10000000000.0_dp)) then
         gw_l%bottomElev = a_l%bottomElev
      end if
      if (gw_l%waterTableElev == (-10000000000.0_dp)) then
         gw_l%waterTableElev = a_l%waterTableElev
      end if
      if (gw_l%upperMoisture == (-10000000000.0_dp)) then
         gw_l%upperMoisture = a_l%upperMoisture
      end if
      if (gw_l%surfElev < gw_l%waterTableElev) then
         call report_writeErrorMsg(ERR_GROUND_ELEV, Subcatch(j_l)%ID)
      end if
   end if
end subroutine gwater_validate

! gwater.c:382
recursive subroutine gwater_initState(j_l)
   integer(int32), value :: j_l
   type(TAquifer), target :: a_l
   type(TGroundwater), pointer :: gw_l
   a_l = zero_TAquifer
   nullify(gw_l)
   gw_l => Subcatch(j_l)%groundwater
   if (associated(gw_l)) then
      a_l = Aquifer(gw_l%aquifer)
      gw_l%theta = gw_l%upperMoisture
      if (gw_l%theta >= a_l%porosity) then
         gw_l%theta = a_l%porosity - XTOL
      end if
      gw_l%lowerDepth = gw_l%waterTableElev - gw_l%bottomElev
      if (gw_l%lowerDepth >= (gw_l%surfElev - gw_l%bottomElev)) then
         gw_l%lowerDepth = (gw_l%surfElev - gw_l%bottomElev) - XTOL
      end if
      gw_l%oldFlow = 0.0_dp
      gw_l%newFlow = 0.0_dp
      gw_l%evapLoss = 0.0_dp
      gw_l%maxInfilVol = ((gw_l%surfElev - gw_l%waterTableElev) * (a_l%porosity - gw_l%theta)) / subcatch_getFracPerv(j_l)
   end if
end subroutine gwater_initState

! gwater.c:425
recursive subroutine gwater_getState(j_l, x_l)
   integer(int32), value :: j_l
   real(dp), pointer, intent(in) :: x_l(:)
   type(TGroundwater), pointer :: gw_l
   gw_l => Subcatch(j_l)%groundwater
   x_l(0) = gw_l%theta
   x_l(1) = gw_l%bottomElev + gw_l%lowerDepth
   x_l(2) = gw_l%newFlow
   x_l(3) = gw_l%maxInfilVol
end subroutine gwater_getState

! gwater.c:441
recursive subroutine gwater_setState(j_l, x_l)
   integer(int32), value :: j_l
   real(dp), pointer, intent(in) :: x_l(:)
   type(TGroundwater), pointer :: gw_l
   gw_l => Subcatch(j_l)%groundwater
   if (.not. associated(gw_l)) then
      return
   end if
   gw_l%theta = x_l(0)
   gw_l%lowerDepth = x_l(1) - gw_l%bottomElev
   gw_l%oldFlow = x_l(2)
   if (x_l(3) /= (-10000000000.0_dp)) then
      gw_l%maxInfilVol = x_l(3)
   end if
end subroutine gwater_setState

! gwater.c:458
recursive function gwater_getVolume(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   type(TAquifer), target :: a_l
   type(TGroundwater), pointer :: gw_l
   real(dp) :: upperDepth
   res_ = 0.0_dp
   a_l = zero_TAquifer
   nullify(gw_l)
   upperDepth = 0.0_dp
   gw_l => Subcatch(j_l)%groundwater
   if (.not. associated(gw_l)) then
      res_ = 0.0_dp
      return
   end if
   a_l = Aquifer(gw_l%aquifer)
   upperDepth = (gw_l%surfElev - gw_l%bottomElev) - gw_l%lowerDepth
   res_ = (upperDepth * gw_l%theta) + (gw_l%lowerDepth * a_l%porosity)
   return
end function gwater_getVolume

! gwater.c:477
recursive subroutine gwater_getGroundwater(j_l, evap_l, infil_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: evap_l
   real(dp), value :: infil_l
   real(dp), value :: tStep
   integer(int32) :: n_l
   real(dp), target :: x_l(0:1)
   real(dp) :: vUpper
   real(dp) :: nodeFlow
   integer(int32) :: dum1_
   real(dp) :: v2_
   real(dp) :: v3_
   n_l = 0
   x_l = 0.0_dp
   vUpper = 0.0_dp
   nodeFlow = 0.0_dp
   GW => Subcatch(j_l)%groundwater
   if (.not. associated(GW)) then
      return
   end if
   LatFlowExpr => Subcatch(j_l)%gwLatFlowExpr
   DeepFlowExpr => Subcatch(j_l)%gwDeepFlowExpr
   A_c = Aquifer(GW%aquifer)
   FracPerv = subcatch_getFracPerv(j_l)
   if (FracPerv <= 0.0_dp) then
      return
   end if
   Area = Subcatch(j_l)%area
   infil_l = (infil_l / Area) / tStep
   gwater_Infil = infil_l
   gwater_Tstep = tStep
   evap_l = (evap_l / Area) / tStep
   MaxEvap = Evap%rate * FracPerv
   AvailEvap = merge(MaxEvap - evap_l, 0.0_dp, (MaxEvap - evap_l) >= (0.0_dp))
   TotalDepth = GW%surfElev - GW%bottomElev
   if (TotalDepth <= 0.0_dp) then
      return
   end if
   n_l = GW%node
   if (GW%nodeElev /= (-10000000000.0_dp)) then
      Hstar = GW%nodeElev - GW%bottomElev
   else
      Hstar = Node(n_l)%invertElev - GW%bottomElev
   end if
   if (GW%fixedDepth > 0.0_dp) then
      Hsw = (GW%fixedDepth + Node(n_l)%invertElev) - GW%bottomElev
   else
      Hsw = (Node(n_l)%newDepth + Node(n_l)%invertElev) - GW%bottomElev
   end if
   x_l(THETA_c) = GW%theta
   x_l(LOWERDEPTH) = GW%lowerDepth
   vUpper = (TotalDepth - x_l(LOWERDEPTH)) * (x_l(THETA_c) - A_c%fieldCapacity)
   vUpper = merge(0.0_dp, vUpper, (0.0_dp) >= (vUpper))
   MaxUpperPerc = vUpper / tStep
   MaxGWFlowPos = (x_l(LOWERDEPTH) * A_c%porosity) / tStep
   MaxGWFlowNeg = ((TotalDepth - x_l(LOWERDEPTH)) * (A_c%porosity - x_l(THETA_c))) / tStep
   nodeFlow = (Node(n_l)%inflow + (Node(n_l)%newVolume / tStep)) / Area
   MaxGWFlowNeg = -(merge(MaxGWFlowNeg, nodeFlow, (MaxGWFlowNeg) <= (nodeFlow)))
   dum1_ = odesolve_integrate(x_l, 2, 0.0_dp, tStep, GWTOL, tStep, getDxDt)
   if ((x_l(THETA_c)) >= (A_c%wiltingPoint)) then
      v2_ = x_l(THETA_c)
   else
      v2_ = A_c%wiltingPoint
   end if
   x_l(THETA_c) = v2_
   if (x_l(THETA_c) >= A_c%porosity) then
      x_l(THETA_c) = A_c%porosity - XTOL
      x_l(LOWERDEPTH) = TotalDepth - XTOL
   end if
   if ((x_l(LOWERDEPTH)) >= (0.0_dp)) then
      v3_ = x_l(LOWERDEPTH)
   else
      v3_ = 0.0_dp
   end if
   x_l(LOWERDEPTH) = v3_
   if (x_l(LOWERDEPTH) >= TotalDepth) then
      x_l(LOWERDEPTH) = TotalDepth - XTOL
   end if
   GW%theta = x_l(THETA_c)
   GW%lowerDepth = x_l(LOWERDEPTH)
   call getFluxes(GW%theta, GW%lowerDepth)
   GW%oldFlow = GW%newFlow
   GW%newFlow = GWFlow
   GW%evapLoss = UpperEvap + LowerEvap
   GW%maxInfilVol = ((TotalDepth - x_l(LOWERDEPTH)) * (A_c%porosity - x_l(THETA_c))) / FracPerv
   call updateMassBal(Area, tStep)
   call stats_updateGwaterStats(j_l, infil_l, GW%evapLoss, GWFlow, LowerLoss, GW%theta, GW%lowerDepth + GW%bottomElev, tStep)
end subroutine gwater_getGroundwater

! gwater.c:605
recursive subroutine updateMassBal(area_l, tStep)
   real(dp), value :: area_l
   real(dp), value :: tStep
   real(dp) :: vInfil_l
   real(dp) :: vUpperEvap
   real(dp) :: vLowerEvap
   real(dp) :: vLowerPerc
   real(dp) :: vGwater
   real(dp) :: ft2sec
   vInfil_l = 0.0_dp
   vUpperEvap = 0.0_dp
   vLowerEvap = 0.0_dp
   vLowerPerc = 0.0_dp
   vGwater = 0.0_dp
   ft2sec = area_l * tStep
   vInfil_l = gwater_Infil * ft2sec
   vUpperEvap = UpperEvap * ft2sec
   vLowerEvap = LowerEvap * ft2sec
   vLowerPerc = LowerLoss * ft2sec
   vGwater = (0.5_dp * (GW%oldFlow + GW%newFlow)) * ft2sec
   call massbal_updateGwaterTotals(vInfil_l, vUpperEvap, vLowerEvap, vLowerPerc, vGwater)
end subroutine updateMassBal

! gwater.c:631
recursive subroutine getFluxes(theta_l, lowerDepth_l)
   real(dp), value :: theta_l
   real(dp), value :: lowerDepth_l
   real(dp) :: upperDepth
   upperDepth = 0.0_dp
   lowerDepth_l = merge(lowerDepth_l, 0.0_dp, (lowerDepth_l) >= (0.0_dp))
   lowerDepth_l = merge(lowerDepth_l, TotalDepth, (lowerDepth_l) <= (TotalDepth))
   upperDepth = TotalDepth - lowerDepth_l
   Hgw = lowerDepth_l
   Theta = theta_l
   call gwater_getEvapRates(theta_l, upperDepth)
   UpperPerc = getUpperPerc(theta_l, upperDepth)
   UpperPerc = merge(UpperPerc, MaxUpperPerc, (UpperPerc) <= (MaxUpperPerc))
   if (.not. (.not. associated(DeepFlowExpr))) then
      LowerLoss = mathexpr_eval(DeepFlowExpr, gwater_getVariableValue) / UCF(RAINFALL)
   else
      LowerLoss = (A_c%lowerLossCoeff * lowerDepth_l) / TotalDepth
   end if
   LowerLoss = merge(LowerLoss, lowerDepth_l / gwater_Tstep, (LowerLoss) <= (lowerDepth_l / gwater_Tstep))
   GWFlow = getGWFlow(lowerDepth_l)
   if (.not. (.not. associated(LatFlowExpr))) then
      GWFlow = GWFlow + (mathexpr_eval(LatFlowExpr, gwater_getVariableValue) / UCF(GWFLOW_c))
   end if
   if (GWFlow >= 0.0_dp) then
      GWFlow = merge(GWFlow, MaxGWFlowPos, (GWFlow) <= (MaxGWFlowPos))
   else
      GWFlow = merge(GWFlow, MaxGWFlowNeg, (GWFlow) >= (MaxGWFlowNeg))
   end if
end subroutine getFluxes

! gwater.c:677
recursive subroutine getDxDt(t_l, x_l, dxdt)
   real(dp), value :: t_l
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: dxdt(:)
   real(dp) :: qUpper
   real(dp) :: qLower
   real(dp) :: denom
   qUpper = 0.0_dp
   qLower = 0.0_dp
   denom = 0.0_dp
   call getFluxes(x_l(THETA_c), x_l(LOWERDEPTH))
   qUpper = (gwater_Infil - UpperEvap) - UpperPerc
   qLower = ((UpperPerc - LowerLoss) - LowerEvap) - GWFlow
   denom = TotalDepth - x_l(LOWERDEPTH)
   if (denom > 0.0_dp) then
      dxdt(THETA_c) = qUpper / denom
   else
      dxdt(THETA_c) = 0.0_dp
   end if
   denom = A_c%porosity - x_l(THETA_c)
   if (denom > 0.0_dp) then
      dxdt(LOWERDEPTH) = qLower / denom
   else
      dxdt(LOWERDEPTH) = 0.0_dp
   end if
end subroutine getDxDt

! gwater.c:713
recursive subroutine gwater_getEvapRates(theta_l, upperDepth)
   real(dp), value :: theta_l
   real(dp), value :: upperDepth
   integer(int32) :: p_l
   integer(int32) :: month
   real(dp) :: f_l
   real(dp) :: lowerFrac
   real(dp) :: upperFrac
   p_l = 0
   month = 0
   f_l = 0.0_dp
   lowerFrac = 0.0_dp
   upperFrac = 0.0_dp
   UpperEvap = 0.0_dp
   LowerEvap = 0.0_dp
   if (gwater_Infil > 0.0_dp) then
      return
   end if
   upperFrac = A_c%upperEvapFrac
   f_l = 1.0_dp
   p_l = A_c%upperEvapPat
   if (p_l >= 0) then
      month = datetime_monthOfYear(getDateTime(NewRunoffTime))
      f_l = Pattern(p_l)%factor(month - 1)
   end if
   upperFrac = upperFrac * f_l
   if (theta_l > A_c%wiltingPoint) then
      UpperEvap = upperFrac * MaxEvap
      UpperEvap = merge(UpperEvap, AvailEvap, (UpperEvap) <= (AvailEvap))
   end if
   if (A_c%lowerEvapDepth > 0.0_dp) then
      lowerFrac = (A_c%lowerEvapDepth - upperDepth) / A_c%lowerEvapDepth
      lowerFrac = merge(0.0_dp, lowerFrac, (0.0_dp) >= (lowerFrac))
      lowerFrac = merge(lowerFrac, 1.0_dp, (lowerFrac) <= (1.0_dp))
      LowerEvap = (lowerFrac * (1.0_dp - upperFrac)) * MaxEvap
      LowerEvap = merge(LowerEvap, AvailEvap - UpperEvap, (LowerEvap) <= (AvailEvap - UpperEvap))
   end if
end subroutine gwater_getEvapRates

! gwater.c:769
recursive function getUpperPerc(theta_l, upperDepth) result(res_)
   real(dp), value :: theta_l
   real(dp), value :: upperDepth
   real(dp) :: res_
   real(dp) :: delta
   real(dp) :: dhdz
   real(dp) :: hydcon_l
   res_ = 0.0_dp
   delta = 0.0_dp
   dhdz = 0.0_dp
   hydcon_l = 0.0_dp
   if ((upperDepth <= 0.0_dp) .or. (theta_l <= A_c%fieldCapacity)) then
      res_ = 0.0_dp
      return
   end if
   delta = theta_l - A_c%porosity
   hydcon_l = A_c%conductivity * exp(delta * A_c%conductSlope)
   delta = theta_l - A_c%fieldCapacity
   dhdz = 1.0_dp + (((A_c%tensionSlope * 2.0_dp) * delta) / upperDepth)
   HydCon = hydcon_l
   res_ = hydcon_l * dhdz
   return
end function getUpperPerc

! gwater.c:799
recursive function getGWFlow(lowerDepth_l) result(res_)
   real(dp), value :: lowerDepth_l
   real(dp) :: res_
   real(dp) :: q_l
   real(dp) :: t1
   real(dp) :: t2
   real(dp) :: t3
   logical :: b1_
   res_ = 0.0_dp
   q_l = 0.0_dp
   t1 = 0.0_dp
   t2 = 0.0_dp
   t3 = 0.0_dp
   if (lowerDepth_l <= Hstar) then
      res_ = 0.0_dp
      return
   end if
   if (GW%b1 == 0.0_dp) then
      t1 = GW%a1
   else
      t1 = GW%a1 * (((lowerDepth_l - Hstar) * UCF(LENGTH)) ** GW%b1)
   end if
   if (GW%b2 == 0.0_dp) then
      t2 = GW%a2
   else if (Hsw > Hstar) then
      t2 = GW%a2 * (((Hsw - Hstar) * UCF(LENGTH)) ** GW%b2)
   else
      t2 = 0.0_dp
   end if
   t3 = (((GW%a3 * lowerDepth_l) * Hsw) * UCF(LENGTH)) * UCF(LENGTH)
   q_l = ((t1 - t2) + t3) / UCF(GWFLOW_c)
   b1_ = q_l < 0.0_dp
   if (b1_) then
      b1_ = GW%a3 /= 0.0_dp
   end if
   if (b1_) then
      q_l = 0.0_dp
   end if
   res_ = q_l
   return
end function getGWFlow

! gwater.c:834
recursive function gwater_getVariableIndex(s_l) result(res_)
   type(CPtr), value :: s_l
   integer(int32) :: res_
   integer(int32) :: k_l
   res_ = 0
   k_l = 0
   k_l = findmatch(s_l, GWVarWords)
   if (k_l >= 0) then
      res_ = k_l
      return
   end if
   res_ = -1
   return
end function gwater_getVariableIndex

! gwater.c:850
recursive function gwater_getVariableValue(varIndex) result(res_)
   integer(int32), value :: varIndex
   real(dp) :: res_
   res_ = 0.0_dp
   select case (varIndex)
   case (0)
      res_ = Hgw * UCF(LENGTH)
      return
   case (1)
      res_ = Hsw * UCF(LENGTH)
      return
   case (2)
      res_ = Hstar * UCF(LENGTH)
      return
   case (3)
      res_ = TotalDepth * UCF(LENGTH)
      return
   case (4)
      res_ = A_c%conductivity * UCF(RAINFALL)
      return
   case (5)
      res_ = HydCon * UCF(RAINFALL)
      return
   case (6)
      res_ = Theta
      return
   case (7)
      res_ = A_c%porosity
      return
   case (8)
      res_ = gwater_Infil * UCF(RAINFALL)
      return
   case (9)
      res_ = UpperPerc * UCF(RAINFALL)
      return
   case (10)
      res_ = Area * UCF(LANDAREA)
      return
   case default
      res_ = 0.0_dp
      return
   end select
end function gwater_getVariableValue

! hash.c:24
recursive function samestr(s1, s2) result(res_)
   type(CPtr), value :: s1
   type(CPtr), value :: s2
   integer(int32) :: res_
   integer(int32) :: i_l
   logical :: b1_
   integer(int32) :: v2_
   logical :: b3_
   integer(int32) :: v4_
   logical :: b5_
   res_ = 0
   i_l = 0
   i_l = 0
   do
      b1_ = (cget(s1, i_l)) >= 97
      if (b1_) then
         b1_ = (cget(s1, i_l)) <= 122
      end if
      if (b1_) then
         v2_ = iand(cget(s1, i_l), not(32))
      else
         v2_ = cget(s1, i_l)
      end if
      b3_ = (cget(s2, i_l)) >= 97
      if (b3_) then
         b3_ = (cget(s2, i_l)) <= 122
      end if
      if (b3_) then
         v4_ = iand(cget(s2, i_l), not(32))
      else
         v4_ = cget(s2, i_l)
      end if
      if (.not. ((v2_) == (v4_))) exit
      b5_ = .not. (cget(s1, i_l + 1) /= 0)
      if (b5_) then
         b5_ = .not. (cget(s2, i_l + 1) /= 0)
      end if
      if (b5_) then
         res_ = 1
         return
      end if
      i_l = i_l + 1
   end do
   res_ = 0
   return
end function samestr

! hash.c:33
recursive function hash(str) result(res_)
   type(CPtr), value :: str
   integer(int64) :: res_
   integer(int64) :: sum1
   integer(int64) :: check1
   integer(int64) :: sum2
   logical :: b1_
   integer(int32) :: v2_
   res_ = 0_int64
   sum1 = 0_int64
   check1 = 0_int64
   sum2 = 0_int64
   do while (0 /= cget(str, 0))
      b1_ = (cget(str, 0)) >= 97
      if (b1_) then
         b1_ = (cget(str, 0)) <= 122
      end if
      if (b1_) then
         v2_ = iand(cget(str, 0), not(32))
      else
         v2_ = cget(str, 0)
      end if
      sum1 = iand((sum1 + i2u(int(v2_, int64))), MASK32)
      str%o = str%o + 1
      if (255_int64 <= sum1) then
         sum1 = iand((sum1 - 255_int64), MASK32)
      end if
      sum2 = sum2 + sum1
   end do
   check1 = i2u(int(sum2, int64))
   check1 = mod(check1, 255_int64)
   check1 = iand((255_int64 - mod(iand((sum1 + check1), MASK32), 255_int64)), MASK32)
   sum1 = iand((255_int64 - mod(iand((sum1 + check1), MASK32), 255_int64)), MASK32)
   res_ = mod(ior(iand(ishft(check1, 8), MASK32), sum1), 1999_int64)
   return
end function hash

! hash.c:51
recursive function HTcreate() result(res_)
   type(HTentry_ptr), pointer :: res_(:)
   integer(int32) :: i_l
   type(HTentry_ptr), pointer :: ht(:)
   nullify(res_)
   i_l = 0
   allocate(ht(0:1999_int64 - 1))
   if (.not. (.not. associated(ht))) then
      i_l = 0
      do while (i_l < 1999)
         nullify(ht(i_l)%p)
         i_l = i_l + 1
      end do
   end if
   res_ => ht
   return
end function HTcreate

! hash.c:59
recursive function HTinsert(ht, key, data_l) result(res_)
   type(HTentry_ptr), pointer, intent(in) :: ht(:)
   type(CPtr), value :: key
   integer(int32), value :: data_l
   integer(int32) :: res_
   integer(int64) :: i_l
   type(HTentry), pointer :: entry_l
   res_ = 0
   i_l = hash(key)
   nullify(entry_l)
   if (i_l >= 1999_int64) then
      res_ = 0
      return
   end if
   allocate(entry_l)
   if (.not. associated(entry_l)) then
      res_ = 0
      return
   end if
   entry_l%key = key
   entry_l%data = data_l
   entry_l%next => ht(i_l)%p
   ht(i_l)%p => entry_l
   res_ = 1
   return
end function HTinsert

! hash.c:73
recursive function HTfind(ht, key) result(res_)
   type(HTentry_ptr), pointer, intent(in) :: ht(:)
   type(CPtr), value :: key
   integer(int32) :: res_
   integer(int64) :: i_l
   type(HTentry), pointer :: entry_l
   res_ = 0
   i_l = hash(key)
   nullify(entry_l)
   if (i_l >= 1999_int64) then
      res_ = -1
      return
   end if
   entry_l => ht(i_l)%p
   do while (.not. (.not. associated(entry_l)))
      if (samestr(entry_l%key, key) /= 0) then
         res_ = entry_l%data
         return
      end if
      entry_l => entry_l%next
   end do
   res_ = -1
   return
end function HTfind

! hash.c:87
