! hash.c:101
recursive subroutine HTfree(ht)
   type(HTentry_ptr), pointer, intent(in) :: ht(:)
   type(HTentry), pointer :: entry_l
   type(HTentry), pointer :: nextentry
   integer(int32) :: i_l
   nullify(entry_l)
   nullify(nextentry)
   i_l = 0
   i_l = 0
   do while (i_l < 1999)
