! hotstart.c:94
recursive function openHotstartFile1() result(res_)
   integer(int32) :: res_
   integer(int32), target :: nSubcatch
   integer(int32), target :: nNodes_l
   integer(int32), target :: nLinks_l
   integer(int32), target :: nPollut
   integer(int32), target :: nLandUses
