   integer(int8), target :: fStampx(0:15)
   integer(int8), target :: fileStamp2(0:15)
   integer(int8), target :: fileStamp3(0:15)
   integer(int8), target :: fileStamp4(0:15)
   integer(int64) :: dum1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   integer(int32) :: dum6_
   res_ = 0
   nSubcatch = 0
   nNodes_l = 0
   nLinks_l = 0
   nPollut = 0
   nLandUses = 0
   flowUnits_l = 0
   call cinit(fStamp, lit_160)
   call cinit(fileStamp_l, lit_160)
   call cinit(fStampx, lit_161)
   call cinit(fileStamp2, lit_162)
   call cinit(fileStamp3, lit_163)
   call cinit(fileStamp4, lit_164)
   if (Fhotstart1%mode /= USE_FILE) then
      res_ = 1
      return
   end if
   Fhotstart1%file => c_fopen(cview(Fhotstart1%name), lit_165)
   if (.not. associated(Fhotstart1%file)) then
      call report_writeErrorMsg(ERR_HOTSTART_FILE_OPEN, cview(Fhotstart1%name))
      res_ = 0
      return
   end if
   dum1_ = c_fread_c(cview(fStampx), int(1_int64 * (strlen(cview(fileStamp2))), int64), Fhotstart1%file)
   if (c_strcmp(cview(fStampx), cview(fileStamp4)) == 0) then
      fileVersion = 4
   else if (c_strcmp(cview(fStampx), cview(fileStamp3)) == 0) then
      fileVersion = 3
   else if (c_strcmp(cview(fStampx), cview(fileStamp2)) == 0) then
      fileVersion = 2
   else
      call c_rewind(Fhotstart1%file)
      dum1_ = c_fread_c(cview(fStamp), int(1_int64 * (strlen(cview(fileStamp_l))), int64), Fhotstart1%file)
      if (c_strcmp(cview(fStamp), cview(fileStamp_l)) /= 0) then
         call report_writeErrorMsg(ERR_HOTSTART_FILE_FORMAT, lit_0)
         res_ = 0
         return
      end if
      fileVersion = 1
   end if
   nSubcatch = -1
   nNodes_l = -1
   nLinks_l = -1
   nPollut = -1
   nLandUses = -1
   flowUnits_l = -1
   if (fileVersion >= 2) then
      dum1_ = c_fread_i4(nSubcatch, Fhotstart1%file)
   else
      nSubcatch = Nobjects(SUBCATCH_c)
   end if
   if (fileVersion >= 3) then
      dum1_ = c_fread_i4(nLandUses, Fhotstart1%file)
   else
      nLandUses = Nobjects(LANDUSE_c)
   end if
   dum1_ = c_fread_i4(nNodes_l, Fhotstart1%file)
   dum1_ = c_fread_i4(nLinks_l, Fhotstart1%file)
   dum1_ = c_fread_i4(nPollut, Fhotstart1%file)
   dum1_ = c_fread_i4(flowUnits_l, Fhotstart1%file)
   b2_ = nSubcatch /= Nobjects(SUBCATCH_c)
   if (.not. b2_) then
      b2_ = nLandUses /= Nobjects(LANDUSE_c)
   end if
   b3_ = b2_
   if (.not. b3_) then
      b3_ = nNodes_l /= Nobjects(NODE_c)
   end if
   b4_ = b3_
   if (.not. b4_) then
      b4_ = nLinks_l /= Nobjects(LINK_c)
   end if
   b5_ = b4_
   if (.not. b5_) then
      b5_ = nPollut /= Nobjects(POLLUT_c)
   end if
   if (b5_ .or. (flowUnits_l /= FlowUnits)) then
      call report_writeErrorMsg(ERR_HOTSTART_FILE_FORMAT, lit_0)
      res_ = 0
      return
   end if
   if (fileVersion >= 3) then
      call readRunoff()
   end if
   call readRouting()
   dum6_ = c_fclose(Fhotstart1%file)
   if (ErrorCode /= 0) then
      res_ = 0
      return
   else
      res_ = 1
      return
   end if
end function openHotstartFile1

! hotstart.c:180
recursive function openHotstartFile2() result(res_)
   integer(int32) :: res_
