! hotstart.c:222
recursive subroutine saveRouting()
   integer(int32) :: i_l
   integer(int32) :: j_l
   real(sp), target :: x_l(0:2)
   integer(int64) :: dum1_
   i_l = 0
   j_l = 0
   x_l = 0.0_sp
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      x_l(0) = real(Node(i_l)%newDepth, sp)
      x_l(1) = real(Node(i_l)%newLatFlow, sp)
      dum1_ = c_fwrite_r4a(x_l, 0, int(2_int64, int32), Fhotstart2%file)
      if (Node(i_l)%type == STORAGE_c) then
         j_l = Node(i_l)%subIndex
         x_l(0) = real(Storage(j_l)%hrt, sp)
         dum1_ = c_fwrite_r4a(x_l, 0, int(1_int64, int32), Fhotstart2%file)
      end if
      j_l = 0
      do while (j_l < Nobjects(POLLUT_c))
         x_l(0) = real(Node(i_l)%newQual(j_l), sp)
         dum1_ = c_fwrite_r4a(x_l, 0, int(1_int64, int32), Fhotstart2%file)
         j_l = j_l + 1
      end do
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      x_l(0) = real(Link(i_l)%newFlow, sp)
      x_l(1) = real(Link(i_l)%newDepth, sp)
      x_l(2) = real(Link(i_l)%setting, sp)
      dum1_ = c_fwrite_r4a(x_l, 0, int(3_int64, int32), Fhotstart2%file)
      j_l = 0
      do while (j_l < Nobjects(POLLUT_c))
         x_l(0) = real(Link(i_l)%newQual(j_l), sp)
         dum1_ = c_fwrite_r4a(x_l, 0, int(1_int64, int32), Fhotstart2%file)
         j_l = j_l + 1
      end do
      i_l = i_l + 1
   end do
end subroutine saveRouting

! hotstart.c:267
recursive subroutine readRouting()
   integer(int32) :: i_l
   integer(int32) :: j_l
   real(sp), target :: x_l
   real(dp), target :: xgw(0:3)
   type(CFile), pointer :: f_l
   logical :: b1_
   i_l = 0
   j_l = 0
   x_l = 0.0_sp
   xgw = 0.0_dp
   f_l => Fhotstart1%file
   if (fileVersion == 2) then
      xgw(2) = 0.0_dp
      xgw(3) = -10000000000.0_dp
      i_l = 0
      do while (i_l < Nobjects(SUBCATCH_c))
         if (.not. (readFloat(x_l, f_l) /= 0)) then
            return
         end if
         xgw(0) = real(x_l, dp)
         if (.not. (readFloat(x_l, f_l) /= 0)) then
            return
         end if
         xgw(1) = real(x_l, dp)
         if (.not. (.not. associated(Subcatch(i_l)%groundwater))) then
            call gwater_setState(i_l, xgw)
         end if
         i_l = i_l + 1
      end do
   end if
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (.not. (readFloat(x_l, f_l) /= 0)) then
         return
      end if
      Node(i_l)%newDepth = real(x_l, dp)
      if (.not. (readFloat(x_l, f_l) /= 0)) then
         return
      end if
      Node(i_l)%newLatFlow = real(x_l, dp)
      b1_ = fileVersion >= 4
      if (b1_) then
         b1_ = Node(i_l)%type == STORAGE_c
      end if
      if (b1_) then
         if (.not. (readFloat(x_l, f_l) /= 0)) then
            return
         end if
         j_l = Node(i_l)%subIndex
         Storage(j_l)%hrt = real(x_l, dp)
      end if
      j_l = 0
      do while (j_l < Nobjects(POLLUT_c))
         if (.not. (readFloat(x_l, f_l) /= 0)) then
            return
         end if
         Node(i_l)%newQual(j_l) = real(x_l, dp)
         j_l = j_l + 1
      end do
      if (fileVersion <= 2) then
         j_l = 0
         do while (j_l < Nobjects(POLLUT_c))
            if (.not. (readFloat(x_l, f_l) /= 0)) then
               return
            end if
            j_l = j_l + 1
         end do
      end if
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (.not. (readFloat(x_l, f_l) /= 0)) then
         return
      end if
      Link(i_l)%newFlow = real(x_l, dp)
      if (.not. (readFloat(x_l, f_l) /= 0)) then
         return
      end if
      Link(i_l)%newDepth = real(x_l, dp)
      if (.not. (readFloat(x_l, f_l) /= 0)) then
         return
      end if
      Link(i_l)%setting = real(x_l, dp)
      Link(i_l)%targetSetting = real(x_l, dp)
      call link_setTargetSetting(i_l)
      call link_setSetting(i_l, 0.0_dp)
      j_l = 0
      do while (j_l < Nobjects(POLLUT_c))
         if (.not. (readFloat(x_l, f_l) /= 0)) then
            return
         end if
         Link(i_l)%newQual(j_l) = real(x_l, dp)
         j_l = j_l + 1
      end do
      i_l = i_l + 1
   end do
end subroutine readRouting

! hotstart.c:356
recursive subroutine saveRunoff()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp), target :: x_l(0:5)
   type(CFile), pointer :: f_l
   integer(int64) :: dum1_
   i_l = 0
   j_l = 0
   k_l = 0
   x_l = 0.0_dp
   f_l => Fhotstart2%file
   i_l = 0
   do while (i_l < Nobjects(SUBCATCH_c))
      j_l = 0
      do while (j_l < 3)
         x_l(j_l) = Subcatch(i_l)%subArea(j_l)%depth
         j_l = j_l + 1
      end do
      x_l(3) = Subcatch(i_l)%newRunoff
      dum1_ = c_fwrite_r8a(x_l, 0, int(4_int64, int32), f_l)
      j_l = 0
      do while (j_l < 6)
         x_l(j_l) = 0.0_dp
         j_l = j_l + 1
      end do
      call infil_getState(i_l, x_l)
      dum1_ = c_fwrite_r8a(x_l, 0, int(6_int64, int32), f_l)
      if (.not. (.not. associated(Subcatch(i_l)%groundwater))) then
         call gwater_getState(i_l, x_l)
         dum1_ = c_fwrite_r8a(x_l, 0, int(4_int64, int32), f_l)
      end if
      if (.not. (.not. associated(Subcatch(i_l)%snowpack))) then
         j_l = 0
         do while (j_l < 3)
            call snow_getState(i_l, j_l, x_l)
            dum1_ = c_fwrite_r8a(x_l, 0, int(5_int64, int32), f_l)
            j_l = j_l + 1
         end do
      end if
      if (Nobjects(POLLUT_c) > 0) then
         j_l = 0
         do while (j_l < Nobjects(POLLUT_c))
            x_l(0) = Subcatch(i_l)%newQual(j_l)
            dum1_ = c_fwrite_r8a(x_l, 0, int(1_int64, int32), f_l)
            j_l = j_l + 1
         end do
         j_l = 0
         do while (j_l < Nobjects(POLLUT_c))
            x_l(0) = Subcatch(i_l)%pondedQual(j_l)
            dum1_ = c_fwrite_r8a(x_l, 0, int(1_int64, int32), f_l)
            j_l = j_l + 1
         end do
         k_l = 0
         do while (k_l < Nobjects(LANDUSE_c))
            j_l = 0
            do while (j_l < Nobjects(POLLUT_c))
               x_l(0) = Subcatch(i_l)%landFactor(k_l)%buildup(j_l)
               dum1_ = c_fwrite_r8a(x_l, 0, int(int(Nobjects(POLLUT_c), int64), int32), f_l)
               j_l = j_l + 1
            end do
            x_l(0) = Subcatch(i_l)%landFactor(k_l)%lastSwept
            dum1_ = c_fwrite_r8a(x_l, 0, int(1_int64, int32), f_l)
            k_l = k_l + 1
         end do
      end if
      i_l = i_l + 1
   end do
end subroutine saveRunoff

! hotstart.c:430
recursive subroutine readRunoff()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp), target :: x_l(0:5)
   type(CFile), pointer :: f_l
   i_l = 0
   j_l = 0
   k_l = 0
   x_l = 0.0_dp
   f_l => Fhotstart1%file
   i_l = 0
   do while (i_l < Nobjects(SUBCATCH_c))
      j_l = 0
      do while (j_l < 3)
         if (.not. (readDouble(Subcatch(i_l)%subArea(j_l)%depth, f_l) /= 0)) then
            return
         end if
         j_l = j_l + 1
      end do
      if (.not. (readDouble(Subcatch(i_l)%newRunoff, f_l) /= 0)) then
         return
      end if
      j_l = 0
      do while (j_l < 6)
         if (.not. (readDouble(x_l(j_l), f_l) /= 0)) then
            return
         end if
         j_l = j_l + 1
      end do
      call infil_setState(i_l, x_l)
      if (.not. (.not. associated(Subcatch(i_l)%groundwater))) then
         j_l = 0
         do while (j_l < 4)
            if (.not. (readDouble(x_l(j_l), f_l) /= 0)) then
               return
            end if
            j_l = j_l + 1
         end do
         call gwater_setState(i_l, x_l)
      end if
      if (.not. (.not. associated(Subcatch(i_l)%snowpack))) then
         j_l = 0
         do while (j_l < 3)
            k_l = 0
            do while (k_l < 5)
               if (.not. (readDouble(x_l(k_l), f_l) /= 0)) then
                  return
               end if
               k_l = k_l + 1
            end do
            call snow_setState(i_l, j_l, x_l)
            j_l = j_l + 1
         end do
      end if
      if (Nobjects(POLLUT_c) > 0) then
         j_l = 0
         do while (j_l < Nobjects(POLLUT_c))
            if (.not. (readDouble(Subcatch(i_l)%newQual(j_l), f_l) /= 0)) then
               return
            end if
            j_l = j_l + 1
         end do
         j_l = 0
