! iface.c:66
recursive function iface_readFileParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32) :: j_l
   integer(int8), target :: fname(0:259)
   integer(int64) :: dum1_
   res_ = 0
   k_l = 0
   j_l = 0
   fname = 0_int8
   if (ntoks < 2) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   k_l = findmatch(tok_l(0), FileModeWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(0))
      return
   end if
   j_l = findmatch(tok_l(1), FileTypeWords)
   if (j_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   if (ntoks < 3) then
      res_ = 0
      return
   end if
   dum1_ = sstrncpy(cview(fname), tok_l(2), 259_int64)
   select case (j_l)
   case (0)
      Frain%mode = k_l
      dum1_ = sstrncpy(cview(Frain%name), addAbsolutePath(cview(fname)), 259_int64)
   case (1)
      Frunoff%mode = k_l
      dum1_ = sstrncpy(cview(Frunoff%name), addAbsolutePath(cview(fname)), 259_int64)
   case (2)
      if (k_l == USE_FILE) then
         Fhotstart1%mode = k_l
         dum1_ = sstrncpy(cview(Fhotstart1%name), addAbsolutePath(cview(fname)), 259_int64)
      else if (k_l == SAVE_FILE) then
         Fhotstart2%mode = k_l
         dum1_ = sstrncpy(cview(Fhotstart2%name), addAbsolutePath(cview(fname)), 259_int64)
      end if
   case (3)
      Frdii%mode = k_l
      dum1_ = sstrncpy(cview(Frdii%name), cview(fname), 259_int64)
   case (4)
      if (k_l /= USE_FILE) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      Finflows%mode = k_l
      dum1_ = sstrncpy(cview(Finflows%name), addAbsolutePath(cview(fname)), 259_int64)
   case (5)
      if (k_l /= SAVE_FILE) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      Foutflows%mode = k_l
      dum1_ = sstrncpy(cview(Foutflows%name), addAbsolutePath(cview(fname)), 259_int64)
   end select
   res_ = 0
   return
end function iface_readFileParams

