! iface.c:187
recursive function iface_getNumIfaceNodes(currentDate_l) result(res_)
   real(dp), value :: currentDate_l
   integer(int32) :: res_
   res_ = 0
   if (OldIfaceDate > currentDate_l) then
      res_ = 0
      return
   end if
   do while ((NewIfaceDate < currentDate_l) .and. (NewIfaceDate /= (-693594.0_dp)))
      call setOldIfaceValues()
      call readNewIfaceValues()
   end do
   if (NewIfaceDate == (-693594.0_dp)) then
      res_ = 0
      return
   end if
   IfaceFrac = (currentDate_l - OldIfaceDate) / (NewIfaceDate - OldIfaceDate)
   IfaceFrac = merge(0.0_dp, IfaceFrac, (0.0_dp) >= (IfaceFrac))
   IfaceFrac = merge(IfaceFrac, 1.0_dp, (IfaceFrac) <= (1.0_dp))
   res_ = NumIfaceNodes
   return
end function iface_getNumIfaceNodes

! iface.c:219
recursive function iface_getIfaceNode(index_l) result(res_)
   integer(int32), value :: index_l
   integer(int32) :: res_
   res_ = 0
   if ((index_l >= 0) .and. (index_l < NumIfaceNodes)) then
      res_ = IfaceNodes(index_l)
      return
   else
      res_ = -1
      return
   end if
end function iface_getIfaceNode

! iface.c:232
recursive function iface_getIfaceFlow(index_l) result(res_)
   integer(int32), value :: index_l
   real(dp) :: res_
   real(dp) :: q1
   real(dp) :: q2
   res_ = 0.0_dp
   q1 = 0.0_dp
   q2 = 0.0_dp
   if ((index_l >= 0) .and. (index_l < NumIfaceNodes)) then
      q1 = OldIfaceValues(index_l)%p(0)
      q2 = NewIfaceValues(index_l)%p(0)
      res_ = ((1.0_dp - IfaceFrac) * q1) + (IfaceFrac * q2)
      return
   else
      res_ = 0.0_dp
      return
   end if
end function iface_getIfaceFlow

! iface.c:253
recursive function iface_getIfaceQual(index_l, pollut_l) result(res_)
   integer(int32), value :: index_l
   integer(int32), value :: pollut_l
   real(dp) :: res_
   integer(int32) :: j_l
