   real(dp) :: c2_l
   res_ = 0.0_dp
   j_l = 0
   c1_l = 0.0_dp
   c2_l = 0.0_dp
   if ((index_l >= 0) .and. (index_l < NumIfaceNodes)) then
      j_l = IfacePolluts(pollut_l)
      if (j_l < 0) then
         res_ = 0.0_dp
         return
      end if
      c1_l = OldIfaceValues(index_l)%p(j_l + 1)
      c2_l = NewIfaceValues(index_l)%p(j_l + 1)
      res_ = ((1.0_dp - IfaceFrac) * c1_l) + (IfaceFrac * c2_l)
      return
   else
      res_ = 0.0_dp
      return
   end if
end function iface_getIfaceQual

