! iface.c:313
recursive subroutine openFileForOutput()
   integer(int32) :: i_l
   integer(int32) :: n_l
   i_l = 0
   n_l = 0
   Foutflows%file => c_fopen(cview(Foutflows%name), lit_171)
   if (.not. associated(Foutflows%file)) then
      call report_writeErrorMsg(ERR_ROUTING_FILE_OPEN, cview(Foutflows%name))
      return
   end if
