   call c_fprintf(Foutflows%file, lit_173, cview(Title(:, 0)))
   call c_fprintf(Foutflows%file, lit_174, ReportStep)
   call c_fprintf(Foutflows%file, lit_175, Nobjects(POLLUT_c) + 1)
   call c_fprintf(Foutflows%file, lit_176, FlowUnitWords(FlowUnits))
   i_l = 0
   do while (i_l < Nobjects(POLLUT_c))
      call c_fprintf(Foutflows%file, lit_177, Pollut(i_l)%ID, QualUnitsWords(Pollut(i_l)%units))
      i_l = i_l + 1
   end do
   n_l = 0
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (isOutletNode(i_l) /= 0) then
         n_l = n_l + 1
      end if
      i_l = i_l + 1
   end do
   call c_fprintf(Foutflows%file, lit_178, n_l)
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (isOutletNode(i_l) /= 0) then
         call c_fprintf(Foutflows%file, lit_173, Node(i_l)%ID)
      end if
      i_l = i_l + 1
   end do
   call c_fprintf(Foutflows%file, lit_179)
   i_l = 0
   do while (i_l < Nobjects(POLLUT_c))
      call c_fprintf(Foutflows%file, lit_180, Pollut(i_l)%ID)
      i_l = i_l + 1
   end do
   if (ReportStart == StartDateTime) then
      call iface_saveOutletResults(ReportStart, Foutflows%file)
   end if
end subroutine openFileForOutput

! iface.c:377
recursive subroutine openFileForInput()
   integer(int32) :: err_l
   integer(int8), target :: line(0:1024)
   integer(int8), target :: s_l(0:1024)
   type(CPtr) :: dum1_
   type(CPtr) :: s2_
   logical :: b3_
   err_l = 0
   line = 0_int8
   s_l = 0_int8
   Finflows%file => c_fopen(cview(Finflows%name), lit_13)
   if (.not. associated(Finflows%file)) then
      call report_writeErrorMsg(ERR_ROUTING_FILE_OPEN, cview(Finflows%name))
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Finflows%file)
   s2_ = cview(s_l)
   b3_ = .not. (c_sscanf(cview(line), lit_169, s2_) /= 0)
   if (.not. b3_) then
      b3_ = .not. (strcomp(cview(s_l), lit_181) /= 0)
   end if
   if (b3_) then
      call report_writeErrorMsg(ERR_ROUTING_FILE_FORMAT, cview(Finflows%name))
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Finflows%file)
   IfaceStep = 0
   dum1_ = c_fgets(cview(line), 1024, Finflows%file)
   if ((.not. (c_sscanf(cview(line), lit_182, IfaceStep) /= 0)) .or. (IfaceStep <= 0)) then
      call report_writeErrorMsg(ERR_ROUTING_FILE_FORMAT, cview(Finflows%name))
      return
   end if
   err_l = getIfaceFilePolluts()
   if (err_l > 0) then
      call report_writeErrorMsg(err_l, cview(Finflows%name))
      return
   end if
   err_l = getIfaceFileNodes()
   if (err_l > 0) then
      call report_writeErrorMsg(err_l, cview(Finflows%name))
      return
   end if
   OldIfaceValues => project_createMatrix(NumIfaceNodes, 1 + NumIfacePolluts)
   NewIfaceValues => project_createMatrix(NumIfaceNodes, 1 + NumIfacePolluts)
   if ((.not. associated(OldIfaceValues)) .or. (.not. associated(NewIfaceValues))) then
      call report_writeErrorMsg(ERR_MEMORY, lit_0)
      return
   end if
   call readNewIfaceValues()
   OldIfaceDate = NewIfaceDate
end subroutine openFileForInput

! iface.c:450
recursive function getIfaceFilePolluts() result(res_)
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int8), target :: line(0:1024)
   integer(int8), target :: s1(0:1024)
   integer(int8), target :: s2(0:1024)
   type(CPtr) :: dum1_
   type(CPtr) :: s2_
   type(CPtr) :: s3_
   logical :: b4_
   type(CPtr) :: s5_
   type(CPtr) :: s6_
   res_ = 0
   i_l = 0
   j_l = 0
   line = 0_int8
   s1 = 0_int8
   s2 = 0_int8
   dum1_ = c_fgets(cview(line), 1024, Finflows%file)
   NumIfacePolluts = -1
   if (c_sscanf(cview(line), lit_182, NumIfacePolluts) /= 0) then
      NumIfacePolluts = NumIfacePolluts - 1
   end if
   if (NumIfacePolluts < 0) then
      res_ = ERR_ROUTING_FILE_FORMAT
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Finflows%file)
   s2_ = cview(s1)
   s3_ = cview(s2)
   if (c_sscanf(cview(line), lit_44, s2_, s3_) < 2) then
      res_ = ERR_ROUTING_FILE_FORMAT
      return
   end if
   if (.not. (strcomp(cview(s1), lit_183) /= 0)) then
      res_ = ERR_ROUTING_FILE_FORMAT
      return
   end if
   IfaceFlowUnits = findmatch(cview(s2), FlowUnitWords)
   if (IfaceFlowUnits < 0) then
      res_ = ERR_ROUTING_FILE_FORMAT
      return
   end if
   if (Nobjects(POLLUT_c) > 0) then
      allocate(IfacePolluts(0:(int(Nobjects(POLLUT_c), int64)) - 1))
      IfacePolluts = 0
      if (.not. associated(IfacePolluts)) then
         res_ = ERR_MEMORY
         return
      end if
      i_l = 0
      do while (i_l < Nobjects(POLLUT_c))
         IfacePolluts(i_l) = -1
         i_l = i_l + 1
      end do
   end if
   b4_ = NumIfacePolluts > 0
   if (b4_) then
      b4_ = Nobjects(POLLUT_c) > 0
   end if
   if (b4_) then
      i_l = 0
      do while (i_l < NumIfacePolluts)
         if (c_feof(Finflows%file) /= 0) then
            res_ = ERR_ROUTING_FILE_FORMAT
            return
         end if
         dum1_ = c_fgets(cview(line), 1024, Finflows%file)
         s5_ = cview(s1)
         s6_ = cview(s2)
         if (c_sscanf(cview(line), lit_44, s5_, s6_) < 2) then
            res_ = ERR_ROUTING_FILE_FORMAT
            return
         end if
         j_l = project_findObject(POLLUT_c, cview(s1))
         if (j_l < 0) then
            goto 101
         end if
         if (.not. (strcomp(cview(s2), QualUnitsWords(Pollut(j_l)%units)) /= 0)) then
            res_ = ERR_ROUTING_FILE_NOMATCH
            return
         end if
         IfacePolluts(j_l) = i_l
         101 continue
         i_l = i_l + 1
      end do
   end if
   res_ = 0
   return
end function getIfaceFilePolluts

! iface.c:510
recursive function getIfaceFileNodes() result(res_)
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int8), target :: line(0:1024)
   integer(int8), target :: s_l(0:1024)
   type(CPtr) :: dum1_
   type(CPtr) :: s2_
   res_ = 0
   i_l = 0
   line = 0_int8
   s_l = 0_int8
   dum1_ = c_fgets(cview(line), 1024, Finflows%file)
   if ((.not. (c_sscanf(cview(line), lit_182, NumIfaceNodes) /= 0)) .or. (NumIfaceNodes <= 0)) then
      res_ = ERR_ROUTING_FILE_FORMAT
      return
   end if
   allocate(IfaceNodes(0:int(NumIfaceNodes, int64) - 1))
   IfaceNodes = 0
   if (.not. associated(IfaceNodes)) then
      res_ = ERR_MEMORY
      return
   end if
   i_l = 0
   do while (i_l < NumIfaceNodes)
      if (c_feof(Finflows%file) /= 0) then
         res_ = ERR_ROUTING_FILE_FORMAT
         return
      end if
      IfaceNodes(i_l) = 0
      dum1_ = c_fgets(cview(line), 1024, Finflows%file)
      s2_ = cview(s_l)
      if (.not. (c_sscanf(cview(line), lit_169, s2_) /= 0)) then
         res_ = ERR_ROUTING_FILE_FORMAT
         return
      end if
      IfaceNodes(i_l) = project_findObject(NODE_c, cview(s_l))
      i_l = i_l + 1
   end do
   if (c_feof(Finflows%file) /= 0) then
      res_ = ERR_ROUTING_FILE_FORMAT
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Finflows%file)
   res_ = 0
   return
end function getIfaceFileNodes

! iface.c:550
recursive subroutine readNewIfaceValues()
   integer(int32) :: i_l
   integer(int32) :: j_l
   type(CPtr) :: s_l
   integer(int32) :: yr
   integer(int32) :: mon
   integer(int32) :: day
   integer(int32) :: hr
   integer(int32) :: min_l
   integer(int32) :: sec
   integer(int8), target :: line(0:1024)
   type(CPtr) :: dum1_
   i_l = 0
   j_l = 0
   s_l = cnull()
   yr = 0
   mon = 0
   day = 0
   hr = 0
   min_l = 0
   sec = 0
   line = 0_int8
   NewIfaceDate = -693594.0_dp
   i_l = 0
   do while (i_l < NumIfaceNodes)
      if (c_feof(Finflows%file) /= 0) then
         return
      end if
      dum1_ = c_fgets(cview(line), 1024, Finflows%file)
      if (cisnull(c_strtok(cview(line), lit_184))) then
         return
      end if
      s_l = c_strtok(cnull(), lit_184)
      if (cisnull(s_l)) then
         return
      end if
      yr = c_atoi(s_l)
      s_l = c_strtok(cnull(), lit_184)
      if (cisnull(s_l)) then
         return
      end if
      mon = c_atoi(s_l)
      s_l = c_strtok(cnull(), lit_184)
      if (cisnull(s_l)) then
         return
      end if
      day = c_atoi(s_l)
      s_l = c_strtok(cnull(), lit_184)
      if (cisnull(s_l)) then
         return
      end if
      hr = c_atoi(s_l)
      s_l = c_strtok(cnull(), lit_184)
      if (cisnull(s_l)) then
         return
      end if
      min_l = c_atoi(s_l)
      s_l = c_strtok(cnull(), lit_184)
      if (cisnull(s_l)) then
         return
      end if
      sec = c_atoi(s_l)
      s_l = c_strtok(cnull(), lit_184)
      if (cisnull(s_l)) then
         return
      end if
      NewIfaceValues(i_l)%p(0) = c_atof(s_l) / Qcf(IfaceFlowUnits)
      j_l = 1
      do while (j_l <= NumIfacePolluts)
         s_l = c_strtok(cnull(), lit_184)
         if (cisnull(s_l)) then
            return
         end if
         NewIfaceValues(i_l)%p(j_l) = c_atof(s_l)
         j_l = j_l + 1
      end do
      i_l = i_l + 1
   end do
   NewIfaceDate = datetime_encodeDate(yr, mon, day) + datetime_encodeTime(hr, min_l, sec)
end subroutine readNewIfaceValues

! iface.c:613
recursive subroutine setOldIfaceValues()
   integer(int32) :: i_l
   integer(int32) :: j_l
   i_l = 0
   j_l = 0
   OldIfaceDate = NewIfaceDate
   i_l = 0
   do while (i_l < NumIfaceNodes)
      j_l = 0
      do while (j_l < (NumIfacePolluts + 1))
         OldIfaceValues(i_l)%p(j_l) = NewIfaceValues(i_l)%p(j_l)
         j_l = j_l + 1
      end do
      i_l = i_l + 1
   end do
end subroutine setOldIfaceValues

