! infil.c:128
recursive function infil_readParams(m_l, tok_l, ntoks) result(res_)
   integer(int32), value :: m_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: n_l
   integer(int32) :: status
   real(dp), target :: x_l(0:4)
   res_ = 0
   i_l = 0
   j_l = 0
   n_l = 0
   status = 0
   x_l = 0.0_dp
   j_l = project_findObject(SUBCATCH_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   i_l = findmatch(tok_l(ntoks - 1), InfilModelWords)
   if (i_l >= 0) then
      m_l = i_l
      ntoks = ntoks - 1
   end if
   if (m_l == HORTON) then
      n_l = 5
   else if (m_l == MOD_HORTON) then
      n_l = 5
   else if (m_l == GREEN_AMPT) then
      n_l = 4
   else if (m_l == MOD_GREEN_AMPT) then
      n_l = 4
   else if (m_l == CURVE_NUMBER) then
      n_l = 4
   else
      res_ = 0
      return
   end if
   if (ntoks < n_l) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   i_l = 0
   do while (i_l < 5)
      x_l(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 1
   do while (i_l < n_l)
      if (.not. (getDouble(tok_l(i_l), x_l(i_l - 1)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   if (((m_l == HORTON) .or. (m_l == MOD_HORTON)) .and. (ntoks > n_l)) then
      if (.not. (getDouble(tok_l(n_l), x_l(n_l - 1)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(n_l))
         return
      end if
   end if
   Subcatch(j_l)%infil = j_l
   Subcatch(j_l)%infilModel = m_l
   select case (m_l)
   case (0, 1)
      status = horton_setParams(Infil(j_l)%horton, x_l)
   case (2, 3)
      status = grnampt_setParams(Infil(j_l)%grnAmpt, x_l)
   case (4)
      status = curvenum_setParams(Infil(j_l)%curveNum, x_l)
   case default
      status = 1
   end select
   if (.not. (status /= 0)) then
      res_ = error_setInpError(ERR_INFIL_PARAMS, lit_0)
      return
   end if
   res_ = 0
   return
end function infil_readParams

