! infil.c:262
recursive subroutine infil_setInfilFactor(j_l)
   integer(int32), value :: j_l
   integer(int32) :: m_l
   integer(int32) :: p_l
   logical :: b1_
   m_l = 0
   p_l = 0
   InfilFactor = Adjust%hydconFactor
   if (j_l >= 0) then
      p_l = Subcatch(j_l)%infilPattern
      b1_ = p_l >= 0
      if (b1_) then
         b1_ = Pattern(p_l)%type == MONTHLY_PATTERN
      end if
      if (b1_) then
         m_l = datetime_monthOfYear(getDateTime(OldRunoffTime)) - 1
         InfilFactor = Pattern(p_l)%factor(m_l)
