! infil.c:288
recursive function infil_getInfil(j_l, tstep, rainfall_l, runon, depth) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: tstep
   real(dp), value :: rainfall_l
   real(dp), value :: runon
   real(dp), value :: depth
   real(dp) :: res_
   res_ = 0.0_dp
   select case (Subcatch(j_l)%infilModel)
   case (0)
      res_ = horton_getInfil(Infil(j_l)%horton, tstep, rainfall_l + runon, depth)
      return
   case (1)
      res_ = modHorton_getInfil(Infil(j_l)%horton, tstep, rainfall_l + runon, depth)
      return
   case (2, 3)
      res_ = grnampt_getInfil(Infil(j_l)%grnAmpt, tstep, rainfall_l + runon, depth, Subcatch(j_l)%infilModel)
      return
   case (4)
      depth = depth + (runon * tstep)
      res_ = curvenum_getInfil(Infil(j_l)%curveNum, tstep, rainfall_l, depth)
      return
   case default
      res_ = 0.0_dp
      return
   end select
end function infil_getInfil

! infil.c:325
recursive function horton_setParams(infil_l, p_l) result(res_)
   type(THorton), pointer, intent(in) :: infil_l
   real(dp), pointer, intent(in) :: p_l(:)
   integer(int32) :: res_
   integer(int32) :: k_l
   res_ = 0
   k_l = 0
   k_l = 0
   do while (k_l < 5)
      if (p_l(k_l) < 0.0_dp) then
         res_ = 0
         return
      end if
      k_l = k_l + 1
   end do
   infil_l%f0 = p_l(0) / UCF(RAINFALL)
   infil_l%fmin = p_l(1) / UCF(RAINFALL)
   infil_l%decay = p_l(2) / 3600.0_dp
   if (p_l(3) == 0.0_dp) then
      p_l(3) = 1.0e-06_dp
   end if
   infil_l%regen = ((-log(1.0_dp - 0.98_dp)) / p_l(3)) / 86400.0_dp
   infil_l%Fmax = p_l(4) / UCF(RAINDEPTH)
   if (infil_l%f0 < infil_l%fmin) then
      res_ = 0
      return
   end if
   res_ = 1
   return
end function horton_setParams

