! infil.c:384
recursive function horton_getInfil(infil_l, tstep, irate, depth) result(res_)
   type(THorton), pointer, intent(in) :: infil_l
   real(dp), value :: tstep
   real(dp), value :: irate
   real(dp), value :: depth
   real(dp) :: res_
   integer(int32) :: iter_l
   real(dp) :: fa
   real(dp) :: fp_l
   real(dp) :: Fp_2
   real(dp) :: F1
   real(dp) :: t1
   real(dp) :: tlim
   real(dp) :: ex_l
   real(dp) :: kt
   real(dp) :: FF
   real(dp) :: FF1
   real(dp) :: r_l
   real(dp) :: f0
   real(dp) :: fmin
   real(dp) :: Fmax
   real(dp) :: tp
   real(dp) :: df
   real(dp) :: kd
   real(dp) :: kr
   res_ = 0.0_dp
   iter_l = 0
   fa = 0.0_dp
   fp_l = 0.0_dp
   Fp_2 = 0.0_dp
   F1 = 0.0_dp
   t1 = 0.0_dp
   tlim = 0.0_dp
   ex_l = 0.0_dp
   kt = 0.0_dp
   FF = 0.0_dp
   FF1 = 0.0_dp
   r_l = 0.0_dp
   f0 = infil_l%f0 * InfilFactor
   fmin = infil_l%fmin * InfilFactor
   Fmax = infil_l%Fmax
   tp = infil_l%tp
   df = f0 - fmin
   kd = infil_l%decay
   kr = infil_l%regen * Evap%recoveryFactor
   if (((df < 0.0_dp) .or. (kd < 0.0_dp)) .or. (kr < 0.0_dp)) then
      res_ = 0.0_dp
      return
   end if
   if ((df == 0.0_dp) .or. (kd == 0.0_dp)) then
      fp_l = f0
      fa = irate + (depth / tstep)
      if (fp_l > fa) then
         fp_l = fa
      end if
      res_ = merge(0.0_dp, fp_l, (0.0_dp) >= (fp_l))
      return
   end if
   fa = irate + (depth / tstep)
   if (fa > 1.0e-10_dp) then
      t1 = tp + tstep
      tlim = 16.0_dp / kd
      if (tp >= tlim) then
         Fp_2 = (fmin * tp) + (df / kd)
         F1 = Fp_2 + (fmin * tstep)
      else
         Fp_2 = (fmin * tp) + ((df / kd) * (1.0_dp - exp((-kd) * tp)))
         F1 = (fmin * t1) + ((df / kd) * (1.0_dp - exp((-kd) * t1)))
      end if
      fp_l = (F1 - Fp_2) / tstep
      fp_l = merge(fp_l, fmin, (fp_l) >= (fmin))
      if (fp_l > fa) then
         fp_l = fa
      end if
      if (t1 > tlim) then
         tp = t1
      else if (fp_l < fa) then
         tp = t1
      else
         F1 = Fp_2 + (fp_l * tstep)
         tp = tp + (tstep / 2.0_dp)
         iter_l = 1
         do while (iter_l <= 20)
            kt = merge(60.0_dp, kd * tp, (60.0_dp) <= (kd * tp))
            ex_l = exp(-kt)
            FF = ((fmin * tp) + ((df / kd) * (1.0_dp - ex_l))) - F1
            FF1 = fmin + (df * ex_l)
            r_l = FF / FF1
            tp = tp - r_l
            if (abs(r_l) <= (0.001_dp * tstep)) then
               exit
            end if
            iter_l = iter_l + 1
         end do
      end if
      if (Fmax > 0.0_dp) then
         if ((infil_l%Fe + (fp_l * tstep)) > Fmax) then
            fp_l = (Fmax - infil_l%Fe) / tstep
         end if
         fp_l = merge(fp_l, 0.0_dp, (fp_l) >= (0.0_dp))
         infil_l%Fe = infil_l%Fe + (fp_l * tstep)
      end if
   else if (kr > 0.0_dp) then
      r_l = exp((-kr) * tstep)
      tp = 1.0_dp - exp((-kd) * tp)
      tp = (-log(1.0_dp - (r_l * tp))) / kd
      if (Fmax > 0.0_dp) then
         infil_l%Fe = (fmin * tp) + ((df / kd) * (1.0_dp - exp((-kd) * tp)))
      end if
   end if
   infil_l%tp = tp
   res_ = fp_l
   return
end function horton_getInfil

! infil.c:496
recursive function modHorton_getInfil(infil_l, tstep, irate, depth) result(res_)
   type(THorton), pointer, intent(in) :: infil_l
   real(dp), value :: tstep
   real(dp), value :: irate
   real(dp), value :: depth
   real(dp) :: res_
   real(dp) :: f_l
   real(dp) :: fp_l
   real(dp) :: fa
   real(dp) :: f0
   real(dp) :: fmin
   real(dp) :: df
   real(dp) :: kd
   real(dp) :: kr
   logical :: b1_
   real(dp) :: v2_
   real(dp) :: v3_
   res_ = 0.0_dp
   f_l = 0.0_dp
   fp_l = 0.0_dp
   fa = 0.0_dp
   f0 = infil_l%f0 * InfilFactor
   fmin = infil_l%fmin * InfilFactor
   df = f0 - fmin
   kd = infil_l%decay
   kr = infil_l%regen * Evap%recoveryFactor
   if (((df < 0.0_dp) .or. (kd < 0.0_dp)) .or. (kr < 0.0_dp)) then
      res_ = 0.0_dp
      return
   end if
   if ((df == 0.0_dp) .or. (kd == 0.0_dp)) then
      fp_l = f0
      fa = irate + (depth / tstep)
      if (fp_l > fa) then
         fp_l = fa
      end if
      res_ = merge(0.0_dp, fp_l, (0.0_dp) >= (fp_l))
      return
   end if
   fa = irate + (depth / tstep)
   if (fa > 1.0e-10_dp) then
      b1_ = infil_l%Fmax > 0.0_dp
      if (b1_) then
         b1_ = infil_l%Fe >= infil_l%Fmax
      end if
      if (b1_) then
         res_ = 0.0_dp
         return
      end if
      fp_l = f0 - (kd * infil_l%Fe)
      fp_l = merge(fp_l, fmin, (fp_l) >= (fmin))
      f_l = merge(fa, fp_l, (fa) <= (fp_l))
      infil_l%Fe = infil_l%Fe + ((merge(f_l - fmin, 0.0_dp, (f_l - fmin) >= (0.0_dp))) * tstep)
      if (infil_l%Fmax > 0.0_dp) then
         if ((infil_l%Fe) >= (infil_l%Fmax)) then
            v2_ = infil_l%Fe
         else
            v2_ = infil_l%Fmax
         end if
         infil_l%Fe = v2_
      end if
   else if (kr > 0.0_dp) then
      infil_l%Fe = infil_l%Fe * exp((-kr) * tstep)
      if ((infil_l%Fe) >= (0.0_dp)) then
         v3_ = infil_l%Fe
      else
         v3_ = 0.0_dp
      end if
      infil_l%Fe = v3_
   end if
   res_ = f_l
   return
end function modHorton_getInfil

! infil.c:559
recursive subroutine grnampt_getParams(j_l, p_l)
   integer(int32), value :: j_l
   real(dp), pointer, intent(in) :: p_l(:)
   p_l(0) = Infil(j_l)%grnAmpt%S * UCF(RAINDEPTH)
   p_l(1) = Infil(j_l)%grnAmpt%Ks * UCF(RAINFALL)
   p_l(2) = Infil(j_l)%grnAmpt%IMDmax
end subroutine grnampt_getParams

! infil.c:574
recursive function grnampt_setParams(infil_l, p_l) result(res_)
   type(TGrnAmpt), pointer, intent(in) :: infil_l
   real(dp), pointer, intent(in) :: p_l(:)
   integer(int32) :: res_
   real(dp) :: ksat
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0
   ksat = 0.0_dp
   b1_ = p_l(0) < 0.0_dp
   if (.not. b1_) then
      b1_ = p_l(1) <= 0.0_dp
   end if
   b2_ = b1_
   if (.not. b2_) then
      b2_ = p_l(2) < 0.0_dp
   end if
   b3_ = b2_
   if (.not. b3_) then
      b3_ = p_l(2) > 1.0_dp
   end if
   if (b3_) then
      res_ = 0
      return
   end if
   infil_l%S = p_l(0) / UCF(RAINDEPTH)
   infil_l%Ks = p_l(1) / UCF(RAINFALL)
   infil_l%IMDmax = p_l(2)
   ksat = (infil_l%Ks * 12.0_dp) * 3600.0_dp
   infil_l%Lu = (4.0_dp * sqrt(ksat)) / 12.0_dp
   res_ = 1
   return
end function grnampt_setParams

! infil.c:597
recursive subroutine grnampt_initState(infil_l)
   type(TGrnAmpt), pointer, intent(in) :: infil_l
   if (.not. associated(infil_l)) then
      return
   end if
   infil_l%IMD = infil_l%IMDmax
   infil_l%Fu = 0.0_dp
   infil_l%F = 0.0_dp
   infil_l%Sat = 0
   infil_l%T = 0.0_dp
end subroutine grnampt_initState

! infil.c:612
recursive subroutine grnampt_getState(infil_l, x_l)
   type(TGrnAmpt), pointer, intent(in) :: infil_l
   real(dp), pointer, intent(in) :: x_l(:)
   x_l(0) = infil_l%IMD
   x_l(1) = infil_l%F
   x_l(2) = infil_l%Fu
   x_l(3) = real(infil_l%Sat, dp)
   x_l(4) = infil_l%T
end subroutine grnampt_getState

! infil.c:621
recursive subroutine grnampt_setState(infil_l, x_l)
   type(TGrnAmpt), pointer, intent(in) :: infil_l
   real(dp), pointer, intent(in) :: x_l(:)
   infil_l%IMD = x_l(0)
   infil_l%F = x_l(1)
   infil_l%Fu = x_l(2)
   infil_l%Sat = d2i(x_l(3))
   infil_l%T = x_l(4)
end subroutine grnampt_setState

! infil.c:632
recursive function grnampt_getInfil(infil_l, tstep, irate, depth, modelType) result(res_)
   type(TGrnAmpt), pointer, intent(in) :: infil_l
   real(dp), value :: tstep
   real(dp), value :: irate
   real(dp), value :: depth
   integer(int32), value :: modelType
   real(dp) :: res_
   res_ = 0.0_dp
   Fumax = (infil_l%IMDmax * infil_l%Lu) * sqrt(InfilFactor)
   infil_l%T = infil_l%T - tstep
   if (infil_l%Sat /= 0) then
      res_ = grnampt_getSatInfil(infil_l, tstep, irate, depth)
      return
   else
      res_ = grnampt_getUnsatInfil(infil_l, tstep, irate, depth, modelType)
      return
   end if
end function grnampt_getInfil

! infil.c:660
recursive function grnampt_getUnsatInfil(infil_l, tstep, irate, depth, modelType) result(res_)
   type(TGrnAmpt), pointer, intent(in) :: infil_l
   real(dp), value :: tstep
   real(dp), value :: irate
   real(dp), value :: depth
   integer(int32), value :: modelType
   real(dp) :: res_
   real(dp) :: ia
   real(dp) :: c1_l
   real(dp) :: F2
   real(dp) :: dF
   real(dp) :: Fs
   real(dp) :: kr
   real(dp) :: ts
   real(dp) :: ks
   real(dp) :: lu
   real(dp) :: v1_
   logical :: b2_
   real(dp) :: v3_
   real(dp) :: v4_
   res_ = 0.0_dp
   ia = 0.0_dp
   c1_l = 0.0_dp
   F2 = 0.0_dp
   dF = 0.0_dp
   Fs = 0.0_dp
   kr = 0.0_dp
   ts = 0.0_dp
   ks = infil_l%Ks * InfilFactor
   lu = infil_l%Lu * sqrt(InfilFactor)
   ia = irate + (depth / tstep)
   if (ia < 1.0e-10_dp) then
      ia = 0.0_dp
   end if
   if (ia == 0.0_dp) then
      if (infil_l%Fu <= 0.0_dp) then
         res_ = 0.0_dp
         return
      end if
      kr = (lu / 90000.0_dp) * Evap%recoveryFactor
      dF = (kr * Fumax) * tstep
      infil_l%F = infil_l%F - dF
      infil_l%Fu = infil_l%Fu - dF
      if (infil_l%Fu <= 0.0_dp) then
         infil_l%Fu = 0.0_dp
         infil_l%F = 0.0_dp
         infil_l%IMD = infil_l%IMDmax
         res_ = 0.0_dp
         return
      end if
      if (infil_l%T <= 0.0_dp) then
         infil_l%IMD = (Fumax - infil_l%Fu) / lu
         infil_l%F = 0.0_dp
      end if
      res_ = 0.0_dp
      return
   end if
   if (ia <= ks) then
      dF = ia * tstep
      infil_l%F = infil_l%F + dF
      infil_l%Fu = infil_l%Fu + dF
      if ((infil_l%Fu) <= (Fumax)) then
         v1_ = infil_l%Fu
      else
         v1_ = Fumax
      end if
      infil_l%Fu = v1_
      b2_ = modelType == GREEN_AMPT
      if (b2_) then
         b2_ = infil_l%T <= 0.0_dp
      end if
      if (b2_) then
         infil_l%IMD = (Fumax - infil_l%Fu) / lu
         infil_l%F = 0.0_dp
      end if
      res_ = ia
      return
   end if
   infil_l%T = (5400.0_dp / lu) / Evap%recoveryFactor
   Fs = ((ks * (infil_l%S + depth)) * infil_l%IMD) / (ia - ks)
   if (infil_l%F > Fs) then
      infil_l%Sat = 1
      res_ = grnampt_getSatInfil(infil_l, tstep, irate, depth)
      return
   end if
   if ((infil_l%F + (ia * tstep)) < Fs) then
      dF = ia * tstep
      infil_l%F = infil_l%F + dF
      infil_l%Fu = infil_l%Fu + dF
      if ((infil_l%Fu) <= (Fumax)) then
         v3_ = infil_l%Fu
      else
         v3_ = Fumax
      end if
      infil_l%Fu = v3_
      res_ = ia
      return
   end if
   ts = tstep - ((Fs - infil_l%F) / ia)
   if (ts <= 0.0_dp) then
      ts = 0.0_dp
   end if
   c1_l = (infil_l%S + depth) * infil_l%IMD
   F2 = grnampt_getF2(Fs, c1_l, ks, ts)
   if (F2 > (Fs + (ia * ts))) then
      F2 = Fs + (ia * ts)
   end if
   dF = F2 - infil_l%F
   infil_l%F = F2
   infil_l%Fu = infil_l%Fu + dF
   if ((infil_l%Fu) <= (Fumax)) then
      v4_ = infil_l%Fu
   else
      v4_ = Fumax
   end if
   infil_l%Fu = v4_
   infil_l%Sat = 1
   res_ = dF / tstep
   return
end function grnampt_getUnsatInfil

! infil.c:767
recursive function grnampt_getSatInfil(infil_l, tstep, irate, depth) result(res_)
   type(TGrnAmpt), pointer, intent(in) :: infil_l
   real(dp), value :: tstep
   real(dp), value :: irate
   real(dp), value :: depth
   real(dp) :: res_
   real(dp) :: ia
   real(dp) :: c1_l
   real(dp) :: dF
   real(dp) :: F2
   real(dp) :: ks
   real(dp) :: lu
   real(dp) :: v1_
   res_ = 0.0_dp
   ia = 0.0_dp
   c1_l = 0.0_dp
   dF = 0.0_dp
   F2 = 0.0_dp
   ks = infil_l%Ks * InfilFactor
   lu = infil_l%Lu * sqrt(InfilFactor)
   ia = irate + (depth / tstep)
   if (ia < 1.0e-10_dp) then
      res_ = 0.0_dp
      return
   end if
   infil_l%T = (5400.0_dp / lu) / Evap%recoveryFactor
   c1_l = (infil_l%S + depth) * infil_l%IMD
   F2 = grnampt_getF2(infil_l%F, c1_l, ks, tstep)
   dF = F2 - infil_l%F
   if (dF > (ia * tstep)) then
      dF = ia * tstep
      infil_l%Sat = 0
   end if
   infil_l%F = infil_l%F + dF
   infil_l%Fu = infil_l%Fu + dF
   if ((infil_l%Fu) <= (Fumax)) then
      v1_ = infil_l%Fu
   else
      v1_ = Fumax
   end if
   infil_l%Fu = v1_
   res_ = dF / tstep
   return
end function grnampt_getSatInfil

! infil.c:813
recursive function grnampt_getF2(f1, c1_l, ks, ts) result(res_)
   real(dp), value :: f1
   real(dp), value :: c1_l
   real(dp), value :: ks
   real(dp), value :: ts
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: f2
   real(dp) :: f2min
   real(dp) :: df2
   real(dp) :: c2_l
   res_ = 0.0_dp
   i_l = 0
   f2 = f1
   f2min = 0.0_dp
   df2 = 0.0_dp
   c2_l = 0.0_dp
   f2min = f1 + (ks * ts)
   if (c1_l == 0.0_dp) then
      res_ = f2min
      return
   end if
   if ((ts < 10.0_dp) .and. (f1 > (0.01_dp * c1_l))) then
      f2 = f1 + ((ks * (1.0_dp + (c1_l / f1))) * ts)
      res_ = merge(f2, f2min, (f2) >= (f2min))
      return
   end if
   c2_l = (c1_l * log(f1 + c1_l)) - (ks * ts)
   i_l = 1
   do while (i_l <= 20)
      df2 = (((f2 - f1) - (c1_l * log(f2 + c1_l))) + c2_l) / (1.0_dp - (c1_l / (f2 + c1_l)))
      if (abs(df2) < 0.00001_dp) then
         res_ = merge(f2, f2min, (f2) >= (f2min))
         return
      end if
      f2 = f2 - df2
      i_l = i_l + 1
   end do
   res_ = f2min
   return
end function grnampt_getF2

! infil.c:861
recursive function curvenum_setParams(infil_l, p_l) result(res_)
   type(TCurveNum), pointer, intent(in) :: infil_l
   real(dp), pointer, intent(in) :: p_l(:)
   integer(int32) :: res_
   res_ = 0
   if (p_l(0) < 10.0_dp) then
      p_l(0) = 10.0_dp
   end if
   if (p_l(0) > 99.0_dp) then
      p_l(0) = 99.0_dp
   end if
   infil_l%Smax = ((1000.0_dp / p_l(0)) - 10.0_dp) / 12.0_dp
   if (infil_l%Smax < 0.0_dp) then
      res_ = 0
      return
   end if
   if (p_l(2) > 0.0_dp) then
      infil_l%regen = 1.0_dp / (p_l(2) * 86400.0_dp)
   else
      res_ = 0
      return
   end if
   infil_l%Tmax = 0.06_dp / infil_l%regen
   res_ = 1
   return
end function curvenum_setParams

