! infil.c:925
recursive function curvenum_getInfil(infil_l, tstep, irate, depth) result(res_)
   type(TCurveNum), pointer, intent(in) :: infil_l
   real(dp), value :: tstep
   real(dp), value :: irate
   real(dp), value :: depth
   real(dp) :: res_
   real(dp) :: F1
   real(dp) :: f1_l
   real(dp) :: fa
   logical :: b1_
   logical :: b2_
   res_ = 0.0_dp
   F1 = 0.0_dp
   f1_l = 0.0_dp
   fa = irate + (depth / tstep)
   if (irate > 1.0e-10_dp) then
      if (infil_l%T >= infil_l%Tmax) then
         infil_l%P = 0.0_dp
         infil_l%F = 0.0_dp
         infil_l%f_2 = 0.0_dp
         infil_l%Se = infil_l%S
      end if
      infil_l%T = 0.0_dp
      infil_l%P = infil_l%P + (irate * tstep)
      F1 = infil_l%P * (1.0_dp - (infil_l%P / (infil_l%P + infil_l%Se)))
      f1_l = (F1 - infil_l%F) / tstep
      b1_ = f1_l < 0.0_dp
      if (.not. b1_) then
         b1_ = infil_l%S <= 0.0_dp
      end if
      if (b1_) then
         f1_l = 0.0_dp
      end if
   else
      b2_ = depth > 0.004167_dp
      if (b2_) then
         b2_ = infil_l%S > 0.0_dp
      end if
      if (b2_) then
         f1_l = infil_l%f_2
         if ((f1_l * tstep) > infil_l%S) then
            f1_l = infil_l%S / tstep
         end if
      else
         infil_l%T = infil_l%T + tstep
      end if
   end if
   if (f1_l > 0.0_dp) then
      f1_l = merge(f1_l, fa, (f1_l) <= (fa))
      f1_l = merge(f1_l, 0.0_dp, (f1_l) >= (0.0_dp))
      infil_l%F = infil_l%F + (f1_l * tstep)
      if (infil_l%regen > 0.0_dp) then
         infil_l%S = infil_l%S - (f1_l * tstep)
         if (infil_l%S < 0.0_dp) then
            infil_l%S = 0.0_dp
         end if
      end if
   else
      infil_l%S = infil_l%S + (((infil_l%regen * infil_l%Smax) * tstep) * Evap%recoveryFactor)
      if (infil_l%S > infil_l%Smax) then
         infil_l%S = infil_l%Smax
      end if
   end if
   infil_l%f_2 = f1_l
   res_ = f1_l
   return
end function curvenum_getInfil

! inflow.c:41
recursive function inflow_readExtInflow(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: param
   integer(int32) :: type_l
   integer(int32) :: tseries_l
   integer(int32) :: basePat
   real(dp), target :: cf
   real(dp), target :: sf_l
   real(dp), target :: baseline
   res_ = 0
   j_l = 0
   param = 0
   type_l = CONCEN_INFLOW
   tseries_l = -1
   basePat = -1
   cf = 1.0_dp
   sf_l = 1.0_dp
   baseline = 0.0_dp
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(NODE_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   param = project_findObject(POLLUT_c, tok_l(1))
   if (param < 0) then
      if (match(tok_l(1), lit_183) /= 0) then
         param = -1
      else
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
   end if
   if (strlen(tok_l(2)) > 0_int64) then
      tseries_l = project_findObject(TSERIES_c, tok_l(2))
      if (tseries_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
      Tseries(tseries_l)%refersTo = EXTERNAL_INFLOW
   end if
   if (param == (-1)) then
      type_l = FLOW_INFLOW
      cf = 1.0_dp / UCF(FLOW)
   end if
   if ((ntoks >= 4) .and. (param > (-1))) then
      if (match(tok_l(3), lit_185) /= 0) then
         type_l = CONCEN_INFLOW
      else if (match(tok_l(3), lit_186) /= 0) then
         type_l = MASS_INFLOW
      else
         res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
         return
      end if
      if ((ntoks >= 5) .and. (type_l == MASS_INFLOW)) then
         if (.not. (getDouble(tok_l(4), cf) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(4))
            return
         end if
         if (cf <= 0.0_dp) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(4))
            return
         end if
      end if
   end if
   if (ntoks >= 6) then
      if (.not. (getDouble(tok_l(5), sf_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
   end if
   if (ntoks >= 7) then
      if (.not. (getDouble(tok_l(6), baseline) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(6))
         return
      end if
   end if
   if (ntoks >= 8) then
      basePat = project_findObject(TIMEPATTERN, tok_l(7))
      if (basePat < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(7))
         return
      end if
   end if
   if (type_l == MASS_INFLOW) then
      cf = cf / 28.317_dp
   end if
   res_ = inflow_setExtInflow(j_l, param, type_l, tseries_l, basePat, cf, baseline, sf_l)
   return
end function inflow_readExtInflow

! inflow.c:138
recursive function inflow_setExtInflow(j_l, param, type_l, tseries_l, basePat, cf, baseline, sf_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: param
   integer(int32), value :: type_l
   integer(int32), value :: tseries_l
   integer(int32), value :: basePat
   real(dp), value :: cf
   real(dp), value :: baseline
   real(dp), value :: sf_l
   integer(int32) :: res_
   type(TExtInflow), pointer :: inflow
   res_ = 0
   nullify(inflow)
   inflow => Node(j_l)%extInflow
   do while (associated(inflow))
      if (inflow%param == param) then
         exit
      end if
      inflow => inflow%next
   end do
   if (.not. associated(inflow)) then
      allocate(inflow)
      if (.not. associated(inflow)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
      inflow%next => Node(j_l)%extInflow
      Node(j_l)%extInflow => inflow
   end if
   inflow%param = param
   inflow%type = type_l
   inflow%tSeries = tseries_l
   inflow%cFactor = cf
   inflow%sFactor = sf_l
   inflow%baseline = baseline
   inflow%basePat = basePat
   res_ = 0
   return
end function inflow_setExtInflow

! inflow.c:187
recursive subroutine inflow_deleteExtInflows(j_l)
   integer(int32), value :: j_l
   type(TExtInflow), pointer :: inflow1
   type(TExtInflow), pointer :: inflow2
   nullify(inflow1)
   nullify(inflow2)
   inflow1 => Node(j_l)%extInflow
   do while (associated(inflow1))
      inflow2 => inflow1%next
