! inflow.c:207
recursive function inflow_getExtInflow(inflow, aDate) result(res_)
   type(TExtInflow), pointer, intent(in) :: inflow
   real(dp), value :: aDate
   real(dp) :: res_
   integer(int32) :: month
   integer(int32) :: day
   integer(int32) :: hour
   integer(int32) :: p_l
   integer(int32) :: k_l
   real(dp) :: cf
   real(dp) :: sf_l
   real(dp) :: blv
   real(dp) :: tsv
   res_ = 0.0_dp
   month = 0
   day = 0
   hour = 0
   p_l = inflow%basePat
   k_l = inflow%tSeries
   cf = inflow%cFactor
   sf_l = inflow%sFactor
   blv = inflow%baseline
   tsv = 0.0_dp
   if (p_l >= 0) then
      month = datetime_monthOfYear(aDate) - 1
      day = datetime_dayOfWeek(aDate) - 1
      hour = datetime_hourOfDay(aDate)
      blv = blv * getPatternFactor(p_l, month, day, hour)
   end if
   if (k_l >= 0) then
      tsv = table_tseriesLookup(Tseries(k_l), aDate, 0) * sf_l
   end if
   res_ = cf * (tsv + blv)
   return
end function inflow_getExtInflow

! inflow.c:237
recursive function inflow_readDwfInflow(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   integer(int32), target :: pats(0:3)
   real(dp), target :: x_l
   type(TDwfInflow), pointer :: inflow
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   m_l = 0
   pats = 0
   x_l = 0.0_dp
   nullify(inflow)
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(NODE_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   k_l = project_findObject(POLLUT_c, tok_l(1))
   if (k_l < 0) then
      if (match(tok_l(1), lit_183) /= 0) then
         k_l = -1
      else
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
   end if
   if (.not. (getDouble(tok_l(2), x_l) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(2))
      return
   end if
   if (k_l == (-1)) then
      x_l = x_l / UCF(FLOW)
   end if
   i_l = 0
   do while (i_l < 4)
      pats(i_l) = -1
      i_l = i_l + 1
   end do
   i_l = 3
   do while (i_l < 7)
      if (i_l >= ntoks) then
         exit
      end if
      if (strlen(tok_l(i_l)) == 0_int64) then
         goto 101
      end if
      m_l = project_findObject(TIMEPATTERN, tok_l(i_l))
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(i_l))
         return
      end if
      pats(i_l - 3) = m_l
      101 continue
      i_l = i_l + 1
   end do
   inflow => Node(j_l)%dwfInflow
   do while (associated(inflow))
      if (inflow%param == k_l) then
         exit
      end if
      inflow => inflow%next
   end do
   if (.not. associated(inflow)) then
      allocate(inflow)
      if (.not. associated(inflow)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
      inflow%next => Node(j_l)%dwfInflow
      Node(j_l)%dwfInflow => inflow
   end if
   inflow%param = k_l
   inflow%avgValue = x_l
   i_l = 0
   do while (i_l < 4)
      inflow%patterns(i_l) = pats(i_l)
      i_l = i_l + 1
   end do
   res_ = 0
   return
end function inflow_readDwfInflow

