   integer(int32) :: p_l
   integer(int32), target :: tmpPattern(0:3)
   i_l = 0
   p_l = 0
   tmpPattern = 0
   i_l = 0
   do while (i_l < 4)
      tmpPattern(i_l) = -1
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < 4)
      p_l = inflow%patterns(i_l)
      if (p_l >= 0) then
         tmpPattern(Pattern(p_l)%type) = p_l
