! inflow.c:361
recursive function inflow_getDwfInflow(inflow, month, day, hour) result(res_)
   type(TDwfInflow), pointer, intent(in) :: inflow
   integer(int32), value :: month
   integer(int32), value :: day
   integer(int32), value :: hour
   real(dp) :: res_
   integer(int32) :: p1
   integer(int32) :: p2
   real(dp) :: f_l
   res_ = 0.0_dp
   p1 = 0
   p2 = 0
   f_l = 1.0_dp
   p1 = inflow%patterns(MONTHLY_PATTERN)
   if (p1 >= 0) then
      f_l = f_l * getPatternFactor(p1, month, day, hour)
   end if
   p1 = inflow%patterns(DAILY_PATTERN)
   if (p1 >= 0) then
      f_l = f_l * getPatternFactor(p1, month, day, hour)
   end if
   p1 = inflow%patterns(HOURLY_PATTERN)
   p2 = inflow%patterns(WEEKEND_PATTERN)
   if (p2 >= 0) then
      if ((day == 0) .or. (day == 6)) then
         f_l = f_l * getPatternFactor(p2, month, day, hour)
      else if (p1 >= 0) then
         f_l = f_l * getPatternFactor(p1, month, day, hour)
      end if
   else if (p1 >= 0) then
      f_l = f_l * getPatternFactor(p1, month, day, hour)
   end if
   res_ = f_l * inflow%avgValue
   return
end function inflow_getDwfInflow

