   if (ntoks < 2) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(TIMEPATTERN, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   if (cisnull(Pattern(j_l)%ID)) then
      Pattern(j_l)%ID = project_findID(TIMEPATTERN, tok_l(0))
      k_l = findmatch(tok_l(1), PatternTypeWords)
      if (k_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
         return
      end if
      Pattern(j_l)%type = k_l
      n_l = 2
   end if
   do
      b1_ = ntoks > n_l
      if (b1_) then
         b1_ = Pattern(j_l)%count < 24
      end if
      if (.not. b1_) exit
      i_l = Pattern(j_l)%count
      if (.not. (getDouble(tok_l(n_l), Pattern(j_l)%factor(i_l)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(n_l))
         return
      end if
      Pattern(j_l)%count = Pattern(j_l)%count + 1
      n_l = n_l + 1
   end do
   res_ = 0
   return
end function inflow_readDwfPattern

! inflow.c:456
recursive function getPatternFactor(p_l, month, day, hour) result(res_)
   integer(int32), value :: p_l
   integer(int32), value :: month
   integer(int32), value :: day
   integer(int32), value :: hour
   real(dp) :: res_
   res_ = 0.0_dp
   select case (Pattern(p_l)%type)
   case (0)
      if ((month >= 0) .and. (month < 12)) then
         res_ = Pattern(p_l)%factor(month)
         return
      end if
   case (1)
      if ((day >= 0) .and. (day < 7)) then
         res_ = Pattern(p_l)%factor(day)
         return
      end if
   case (2)
      if ((hour >= 0) .and. (hour < 24)) then
         res_ = Pattern(p_l)%factor(hour)
         return
      end if
   case (3)
      if ((day == 0) .or. (day == 6)) then
         if ((hour >= 0) .and. (hour < 24)) then
            res_ = Pattern(p_l)%factor(hour)
            return
         end if
      end if
   end select
   res_ = 1.0_dp
   return
end function getPatternFactor

