recursive function inlet_create(numInlets) result(res_)
   integer(int32), value :: numInlets
   integer(int32) :: res_
   integer(int32) :: i_l
   res_ = 0
   i_l = 0
   nullify(InletDesigns)
   nullify(InletFlow)
   InletDesignCount = 0
   UsesInlets = 0
   nullify(FirstInlet)
   allocate(InletDesigns(0:int(numInlets, int64) - 1))
   if (.not. associated(InletDesigns)) then
      res_ = ERR_MEMORY
      return
   end if
   InletDesignCount = numInlets
   allocate(InletFlow(0:(int(Nobjects(NODE_c), int64)) - 1))
   InletFlow = 0.0_dp
   if (.not. associated(InletFlow)) then
      res_ = ERR_MEMORY
      return
   end if
   i_l = 0
   do while (i_l < InletDesignCount)
      InletDesigns(i_l)%customCurve = -1
      InletDesigns(i_l)%curbInlet%length = 0.0_dp
      InletDesigns(i_l)%grateInlet%length = 0.0_dp
      InletDesigns(i_l)%slottedInlet%length = 0.0_dp
      InletDesigns(i_l)%type = CUSTOM_INLET
      i_l = i_l + 1
   end do
   res_ = 0
   return
end function inlet_create

