! inlet.c:362
recursive function inlet_readUsageParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: linkIndex
   integer(int32) :: designIndex
   integer(int32) :: nodeIndex
   integer(int32), target :: numInlets
   integer(int32) :: placement
   real(dp), target :: flowLimit
   real(dp), target :: pctClogged
   real(dp), target :: aLocal
   real(dp), target :: wLocal
   type(TInlet), pointer :: inlet_l
   res_ = 0
   linkIndex = 0
   designIndex = 0
   nodeIndex = 0
   numInlets = 1
   placement = AUTOMATIC
   flowLimit = 0.0_dp
   pctClogged = 0.0_dp
   aLocal = 0.0_dp
   wLocal = 0.0_dp
   nullify(inlet_l)
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   linkIndex = project_findObject(LINK_c, tok_l(0))
   if (linkIndex < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   designIndex = project_findObject(INLET, tok_l(1))
   if (designIndex < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   nodeIndex = project_findObject(NODE_c, tok_l(2))
   if (nodeIndex < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   if (ntoks > 3) then
      if ((.not. (getInt(tok_l(3), numInlets) /= 0)) .or. (numInlets < 1)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(3))
         return
      end if
   end if
   if (ntoks > 4) then
      if (((.not. (getDouble(tok_l(4), pctClogged) /= 0)) .or. (pctClogged < 0.0_dp)) .or. (pctClogged > 99.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(4))
         return
      end if
   end if
   if (ntoks > 5) then
      if ((.not. (getDouble(tok_l(5), flowLimit) /= 0)) .or. (flowLimit < 0.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
   end if
   if (ntoks > 6) then
      if ((.not. (getDouble(tok_l(6), aLocal) /= 0)) .or. (aLocal < 0.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(6))
         return
      end if
   end if
   if (ntoks > 7) then
      if ((.not. (getDouble(tok_l(7), wLocal) /= 0)) .or. (wLocal < 0.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(7))
         return
      end if
   end if
   if (ntoks > 8) then
      placement = findmatch(tok_l(8), PlacementTypeWords)
      if (placement < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(8))
         return
      end if
   end if
   inlet_l => Link(linkIndex)%inlet
   if (.not. associated(inlet_l)) then
      allocate(inlet_l)
      if (.not. associated(inlet_l)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
      Link(linkIndex)%inlet => inlet_l
      inlet_l%nextInlet => FirstInlet
      FirstInlet => inlet_l
   end if
   inlet_l%linkIndex = linkIndex
   inlet_l%designIndex = designIndex
   inlet_l%nodeIndex = nodeIndex
   inlet_l%numInlets = numInlets
   inlet_l%placement = placement
   inlet_l%clogFactor = 1.0_dp - (pctClogged / 100.0_dp)
   inlet_l%flowLimit = flowLimit / UCF(FLOW)
   inlet_l%localDepress = aLocal / UCF(LENGTH)
   inlet_l%localWidth = wLocal / UCF(LENGTH)
   inlet_l%flowFactor = 0.0_dp
   inlet_l%backflowRatio = 0.0_dp
   call initInletStats(inlet_l)
   UsesInlets = 1
   res_ = 0
   return
end function inlet_readUsageParams

! inlet.c:464
recursive subroutine inlet_validate()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: inletType
   integer(int32) :: inletValid
   type(TInlet), pointer :: inlet_l
   type(TInlet), pointer :: prevInlet
   logical :: b1_
   logical :: b2_
   logical :: b3_
   i_l = 0
   j_l = 0
   inletType = 0
   inletValid = 0
   nullify(inlet_l)
   nullify(prevInlet)
   if (.not. (UsesInlets /= 0)) then
      return
   end if
   prevInlet => FirstInlet
   inlet_l => FirstInlet
   do while (associated(inlet_l))
      inletValid = 0
      i_l = inlet_l%linkIndex
      xsect => Link(i_l)%xsect
      inletType = InletDesigns(inlet_l%designIndex)%type
      if (inletType == CUSTOM_INLET) then
         j_l = InletDesigns(inlet_l%designIndex)%customCurve
         if (j_l >= 0) then
            b1_ = Curve(j_l)%curveType == DIVERSION_CURVE
            if (.not. b1_) then
               b1_ = Curve(j_l)%curveType == RATING_CURVE
            end if
            if (b1_) then
               inletValid = 1
            end if
         end if
      else
         b3_ = xsect%type == TRAPEZOIDAL
         if (.not. b3_) then
            b3_ = xsect%type == RECT_OPEN
         end if
         if ((b3_) .and. ((inletType == DROP_GRATE_INLET) .or. (inletType == DROP_CURB_INLET))) then
            inletValid = 1
         else if (((xsect%type == STREET_XSECT) .and. (inletType /= DROP_GRATE_INLET)) .and. (inletType /= DROP_CURB_INLET)) then
            inletValid = 1
         end if
      end if
      if (inletValid /= 0) then
         Node(Link(i_l)%node2)%inlet = BYPASS
         Node(inlet_l%nodeIndex)%inlet = CAPTURE
         inlet_l%backflow = 0.0_dp
         call getConduitGeometry(inlet_l)
         inlet_l%flowFactor = ((0.56_dp / n_c) * (SL ** 0.5_dp)) * (Sx ** 1.67_dp)
         prevInlet => inlet_l
         inlet_l => inlet_l%nextInlet
      else
         call report_writeWarningMsg(lit_187, Link(i_l)%ID)
         if (associated(inlet_l, FirstInlet) .or. (.not. associated(inlet_l) .and. .not. associated(FirstInlet))) then
            FirstInlet => inlet_l%nextInlet
            prevInlet => FirstInlet
            ! free(inlet)
            inlet_l => FirstInlet
         else
            prevInlet%nextInlet => inlet_l%nextInlet
            ! free(inlet)
            inlet_l => prevInlet%nextInlet
         end if
         nullify(Link(i_l)%inlet)
      end if
   end do
   call getBackflowRatios()
end subroutine inlet_validate

! inlet.c:555
recursive subroutine inlet_findCapturedFlows(tStep)
   real(dp), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: m_l
   integer(int32) :: placement
   real(dp) :: q_l
   type(TInlet), pointer :: inlet_l
   real(dp) :: v1_
   real(dp) :: v2_
   logical :: b3_
   real(dp) :: v4_
   i_l = 0
   j_l = 0
   m_l = 0
   placement = 0
   q_l = 0.0_dp
   nullify(inlet_l)
   if (.not. (UsesInlets /= 0)) then
      return
   end if
   InletFlow(0:int((int(Nobjects(NODE_c), int64) * 8_int64) / 8) - 1) = 0.0_dp
   if (RouteModel /= DW) then
      j_l = 0
      do while (j_l < Nobjects(NODE_c))
         if ((0.0_dp) >= (Node(j_l)%newLatFlow)) then
            v1_ = 0.0_dp
         else
            v1_ = Node(j_l)%newLatFlow
         end if
         Node(j_l)%inflow = v1_
         j_l = j_l + 1
      end do
      i_l = 0
      do while (i_l < Nobjects(LINK_c))
         if ((0.0_dp) >= (Link(i_l)%newFlow)) then
            v2_ = 0.0_dp
         else
            v2_ = Link(i_l)%newFlow
         end if
         Node(Link(i_l)%node2)%inflow = Node(Link(i_l)%node2)%inflow + (v2_)
         i_l = i_l + 1
      end do
   end if
   inlet_l => FirstInlet
   do while (.not. (.not. associated(inlet_l)))
      i_l = inlet_l%linkIndex
      j_l = Link(i_l)%node2
      m_l = inlet_l%nodeIndex
      placement = getInletPlacement(inlet_l, j_l)
      if (InletDesigns(inlet_l%designIndex)%type == CUSTOM_INLET) then
         q_l = abs(Link(i_l)%newFlow)
         inlet_l%flowCapture = getCustomCapturedFlow(inlet_l, q_l, Node(j_l)%newDepth)
      else if (placement == ON_GRADE) then
         q_l = abs(Link(i_l)%newFlow)
         inlet_l%flowCapture = getOnGradeCapturedFlow(inlet_l, q_l, Node(j_l)%newDepth)
      else
         q_l = Node(j_l)%inflow
         inlet_l%flowCapture = getOnSagCapturedFlow(inlet_l, q_l, Node(j_l)%newDepth)
      end if
      if (abs(inlet_l%flowCapture) < 0.0001_dp) then
         inlet_l%flowCapture = 0.0_dp
      end if
      InletFlow(j_l) = InletFlow(j_l) + inlet_l%flowCapture
      inlet_l%backflow = Node(m_l)%overflow * inlet_l%backflowRatio
      if (abs(inlet_l%backflow) < 0.0001_dp) then
         inlet_l%backflow = 0.0_dp
      end if
      inlet_l => inlet_l%nextInlet
   end do
   inlet_l => FirstInlet
   do while (.not. (.not. associated(inlet_l)))
      i_l = inlet_l%linkIndex
      j_l = Link(i_l)%node2
      m_l = inlet_l%nodeIndex
      b3_ = RouteModel /= DW
      if (b3_) then
         b3_ = getInletPlacement(inlet_l, j_l) == ON_SAG
      end if
      if (b3_) then
         q_l = Node(j_l)%newVolume / tStep
         if ((Node(j_l)%inflow) >= (0.0_dp)) then
            v4_ = Node(j_l)%inflow
         else
            v4_ = 0.0_dp
         end if
         q_l = q_l + (v4_)
         if (InletFlow(j_l) > q_l) then
            inlet_l%flowCapture = inlet_l%flowCapture * (q_l / InletFlow(j_l))
         end if
      end if
      Node(j_l)%newLatFlow = Node(j_l)%newLatFlow - (inlet_l%flowCapture - inlet_l%backflow)
      Node(m_l)%newLatFlow = Node(m_l)%newLatFlow + inlet_l%flowCapture
      if (getDateTime(NewRoutingTime) > ReportStart) then
         call updateInletStats(inlet_l, abs(Link(i_l)%newFlow))
      end if
      inlet_l => inlet_l%nextInlet
   end do
end subroutine inlet_findCapturedFlows

! inlet.c:655
recursive subroutine inlet_adjustQualInflows()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: m_l
   integer(int32) :: p_l
   real(dp) :: qNet
   type(TInlet), pointer :: inlet_l
   logical :: b1_
   i_l = 0
   j_l = 0
   m_l = 0
   p_l = 0
   qNet = 0.0_dp
   nullify(inlet_l)
   if (.not. (UsesInlets /= 0)) then
      return
   end if
   b1_ = IgnoreQuality /= 0
   if (.not. b1_) then
      b1_ = Nobjects(POLLUT_c) == 0
   end if
   if (b1_) then
      return
   end if
   inlet_l => FirstInlet
   do while (.not. (.not. associated(inlet_l)))
      i_l = inlet_l%linkIndex
      j_l = Link(i_l)%node2
      m_l = inlet_l%nodeIndex
      qNet = inlet_l%flowCapture - inlet_l%backflow
      if (qNet > 0.0_dp) then
         Node(m_l)%qualInflow = Node(m_l)%qualInflow + qNet
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            Node(m_l)%newQual(p_l) = Node(m_l)%newQual(p_l) + (qNet * Node(j_l)%oldQual(p_l))
            p_l = p_l + 1
         end do
      else
         qNet = -qNet
         Node(j_l)%qualInflow = Node(j_l)%qualInflow + qNet
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + (qNet * Node(m_l)%oldQual(p_l))
            p_l = p_l + 1
         end do
      end if
      inlet_l => inlet_l%nextInlet
   end do
end subroutine inlet_adjustQualInflows

! inlet.c:706
recursive subroutine inlet_adjustQualOutflows()
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: w_l
   type(TInlet), pointer :: inlet_l
   logical :: b1_
   logical :: b2_
   j_l = 0
   p_l = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   nullify(inlet_l)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      if (Node(j_l)%inlet == CAPTURE) then
         q_l = Node(j_l)%overflow
         if (q_l > 0.0_dp) then
            StepFlowTotals%flooding = StepFlowTotals%flooding - q_l
            if (.not. (IgnoreQuality /= 0)) then
               p_l = 0
               do while (p_l < Nobjects(POLLUT_c))
                  w_l = q_l * Node(j_l)%newQual(p_l)
                  StepQualTotals(p_l)%flooding = StepQualTotals(p_l)%flooding - w_l
                  p_l = p_l + 1
               end do
            end if
         end if
      end if
      j_l = j_l + 1
   end do
   b1_ = .not. (IgnoreQuality /= 0)
   if (b1_) then
      b1_ = Nobjects(POLLUT_c) > 0
   end if
   if (b1_) then
      inlet_l => FirstInlet
      do while (.not. (.not. associated(inlet_l)))
         j_l = Link(inlet_l%linkIndex)%node2
         q_l = inlet_l%flowCapture - inlet_l%backflow
         b2_ = q_l > 0.0_dp
         if (b2_) then
            b2_ = Node(j_l)%newLatFlow < 0.0_dp
         end if
         if (b2_) then
            p_l = 0
            do while (p_l < Nobjects(POLLUT_c))
               w_l = q_l * Node(j_l)%newQual(p_l)
               StepQualTotals(p_l)%outflow = StepQualTotals(p_l)%outflow - w_l
               p_l = p_l + 1
            end do
         end if
         inlet_l => inlet_l%nextInlet
      end do
   end if
end subroutine inlet_adjustQualOutflows

! inlet.c:774
recursive subroutine inlet_writeStatsReport()
