! inlet.c:814
recursive function readGrateInletParams(i_l, tok_l, ntoks) result(res_)
   integer(int32), value :: i_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: grateType
   real(dp), target :: width_l
   real(dp), target :: length_l
   real(dp), target :: areaRatio
   real(dp), target :: vSplash
   logical :: b1_
   res_ = 0
   grateType = 0
   width_l = 0.0_dp
   length_l = 0.0_dp
   areaRatio = 0.0_dp
   vSplash = 0.0_dp
   if (ntoks < 5) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   if ((.not. (getDouble(tok_l(2), length_l) /= 0)) .or. (length_l <= 0.0_dp)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(2))
      return
   end if
   if ((.not. (getDouble(tok_l(3), width_l) /= 0)) .or. (width_l <= 0.0_dp)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(3))
      return
   end if
   grateType = findmatch(tok_l(4), GrateTypeWords)
   if (grateType < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(4))
      return
   end if
   if (grateType == GENERIC) then
      if (ntoks < 6) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (((.not. (getDouble(tok_l(5), areaRatio) /= 0)) .or. (areaRatio <= 0.0_dp)) .or. (areaRatio > 1.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
      if (ntoks > 6) then
         if ((.not. (getDouble(tok_l(6), vSplash) /= 0)) .or. (vSplash < 0.0_dp)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(6))
            return
         end if
      end if
   end if
   InletDesigns(i_l)%grateInlet%length = length_l / UCF(LENGTH)
   InletDesigns(i_l)%grateInlet%width = width_l / UCF(LENGTH)
   InletDesigns(i_l)%grateInlet%type = grateType
   InletDesigns(i_l)%grateInlet%fracOpenArea = areaRatio
   InletDesigns(i_l)%grateInlet%splashVeloc = vSplash / UCF(LENGTH)
   b1_ = InletDesigns(i_l)%type == GRATE_INLET
   if (b1_) then
      b1_ = InletDesigns(i_l)%curbInlet%length > 0.0_dp
   end if
   if (b1_) then
      InletDesigns(i_l)%type = COMBO_INLET
   end if
   res_ = 0
   return
end function readGrateInletParams

! inlet.c:868
recursive function readCurbInletParams(i_l, tok_l, ntoks) result(res_)
   integer(int32), value :: i_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
