! inlet.c:962
recursive subroutine initInletStats(inlet_l)
   type(TInlet), pointer, intent(in) :: inlet_l
   if (associated(inlet_l)) then
      inlet_l%flowCapture = 0.0_dp
      inlet_l%backflow = 0.0_dp
      inlet_l%stats%flowPeriods = 0
      inlet_l%stats%capturePeriods = 0
      inlet_l%stats%backflowPeriods = 0
      inlet_l%stats%peakFlow = 0.0_dp
      inlet_l%stats%peakFlowCapture = 0.0_dp
      inlet_l%stats%avgFlowCapture = 0.0_dp
      inlet_l%stats%bypassFreq = 0.0_dp
   end if
end subroutine initInletStats

! inlet.c:985
recursive subroutine updateInletStats(inlet_l, q_l)
   type(TInlet), pointer, intent(in) :: inlet_l
   real(dp), value :: q_l
   real(dp) :: qCapture
   real(dp) :: qBackflow
   real(dp) :: qNet
   real(dp) :: qBypass
   real(dp) :: fCapture
   qCapture = inlet_l%flowCapture
   qBackflow = inlet_l%backflow
   qNet = qCapture - qBackflow
   qBypass = q_l - qNet
   fCapture = 0.0_dp
   if ((q_l < 0.001_dp) .and. (qBackflow <= 0.0_dp)) then
      return
   end if
   inlet_l%stats%flowPeriods = inlet_l%stats%flowPeriods + 1
   if (qNet > 0.0_dp) then
      inlet_l%stats%capturePeriods = inlet_l%stats%capturePeriods + 1
      fCapture = qNet / q_l
      fCapture = merge(fCapture, 1.0_dp, (fCapture) <= (1.0_dp))
      inlet_l%stats%avgFlowCapture = inlet_l%stats%avgFlowCapture + fCapture
      if (qBypass > 0.001_dp) then
         inlet_l%stats%bypassFreq = inlet_l%stats%bypassFreq + 1.0_dp
      end if
   else
      inlet_l%stats%backflowPeriods = inlet_l%stats%backflowPeriods + 1
   end if
   if (q_l > inlet_l%stats%peakFlow) then
      inlet_l%stats%peakFlow = q_l
      inlet_l%stats%peakFlowCapture = fCapture * 100.0_dp
   end if
end subroutine updateInletStats

