end subroutine writeStreetStatsHeader

! inlet.c:1055
recursive subroutine writeStreetStats(link_l)
   integer(int32), value :: link_l
   integer(int32) :: k_l
   integer(int32) :: t_l
   integer(int32) :: placement
   real(dp) :: maxSpread
   real(dp) :: maxDepth
   real(dp) :: maxFlow
   real(dp) :: fp_l
   real(dp) :: cp
   real(dp) :: afc
   real(dp) :: bpf
   type(TInlet), pointer :: inlet_l
   real(dp) :: v1_
   k_l = 0
   t_l = 0
   placement = 0
   maxSpread = 0.0_dp
   maxDepth = 0.0_dp
   maxFlow = 0.0_dp
   fp_l = 0.0_dp
   cp = 0.0_dp
   afc = 0.0_dp
   bpf = 0.0_dp
   nullify(inlet_l)
   k_l = Link(link_l)%subIndex
   t_l = Link(link_l)%xsect%transect
   inlet_l => Link(link_l)%inlet
   maxFlow = LinkStats(link_l)%maxFlow
   maxDepth = LinkStats(link_l)%maxDepth
   maxSpread = xsect_getWofY(Link(link_l)%xsect, maxDepth) / real(Street(t_l)%sides, dp)
   if ((maxSpread) <= (Street(t_l)%width)) then
      v1_ = maxSpread
   else
      v1_ = Street(t_l)%width
   end if
   maxSpread = v1_
   call c_fprintf(Frpt%file, lit_194, Link(link_l)%ID)
   call c_fprintf(Frpt%file, lit_195, maxFlow * UCF(FLOW))
   call c_fprintf(Frpt%file, lit_195, maxSpread * UCF(LENGTH))
   call c_fprintf(Frpt%file, lit_195, maxDepth * UCF(LENGTH))
   if (associated(inlet_l)) then
      call c_fprintf(Frpt%file, lit_196, InletDesigns(inlet_l%designIndex)%ID)
      placement = getInletPlacement(inlet_l, Link(inlet_l%linkIndex)%node2)
      if (placement == ON_GRADE) then
         call c_fprintf(Frpt%file, lit_197)
      else
         call c_fprintf(Frpt%file, lit_198)
      end if
      call c_fprintf(Frpt%file, lit_199, inlet_l%numInlets)
      fp_l = real(inlet_l%stats%flowPeriods, dp) / 100.0_dp
      if (fp_l > 0.0_dp) then
         cp = real(inlet_l%stats%capturePeriods, dp) / 100.0_dp
         call c_fprintf(Frpt%file, lit_200, inlet_l%stats%peakFlowCapture)
         if (cp > 0.0_dp) then
            afc = inlet_l%stats%avgFlowCapture / cp
            bpf = inlet_l%stats%bypassFreq / cp
         end if
         call c_fprintf(Frpt%file, lit_200, afc)
         call c_fprintf(Frpt%file, lit_200, bpf)
         call c_fprintf(Frpt%file, lit_200, real(inlet_l%stats%backflowPeriods, dp) / fp_l)
         call c_fprintf(Frpt%file, lit_200, ((((maxFlow / real(Street(t_l)%sides, dp)) * UCF(FLOW)) * 0.01_dp) * inlet_l%stats%peakFlowCapture) / real(inlet_l%numInlets, dp))
         call c_fprintf(Frpt%file, lit_200, ((maxFlow * UCF(FLOW)) * 0.01_dp) * (100.0_dp - inlet_l%stats%peakFlowCapture))
      end if
   end if
end subroutine writeStreetStats

! inlet.c:1129
recursive function getInletPlacement(inlet_l, j_l) result(res_)
   type(TInlet), pointer, intent(in) :: inlet_l
   integer(int32), value :: j_l
   integer(int32) :: res_
   res_ = 0
   if (inlet_l%placement == AUTOMATIC) then
      if (Node(j_l)%degree > 0) then
         res_ = ON_GRADE
         return
      else
         res_ = ON_SAG
         return
      end if
   else
      res_ = inlet_l%placement
      return
   end if
end function getInletPlacement

! inlet.c:1147
recursive subroutine getConduitGeometry(inlet_l)
   type(TInlet), pointer, intent(in) :: inlet_l
   integer(int32) :: linkIndex
   integer(int32) :: t_l
   integer(int32) :: k_l
   logical :: b1_
   linkIndex = inlet_l%linkIndex
   t_l = 0
   k_l = Link(linkIndex)%subIndex
   SL = Conduit(k_l)%slope
   Beta = Conduit(k_l)%beta
   xsect => Link(linkIndex)%xsect
   if (xsect%type == STREET_XSECT) then
      t_l = xsect%transect
      Sx = Street(t_l)%slope
      a_2 = Street(t_l)%gutterDepression
      W_c = Street(t_l)%gutterWidth
      n_c = Street(t_l)%roughness
      Nsides = Street(t_l)%sides
      Tcrown = Street(t_l)%width
      Qfactor = inlet_l%flowFactor
      b1_ = associated(inlet_l)
      if (b1_) then
         b1_ = (inlet_l%localDepress * inlet_l%localWidth) > 0.0_dp
      end if
      if (b1_) then
         a_2 = a_2 + inlet_l%localDepress
         W_c = inlet_l%localWidth
      end if
      if ((W_c * a_2) > 0.0_dp) then
         Sw = Sx + (a_2 / W_c)
      else
         Sw = Sx
      end if
   else
      a_2 = 0.0_dp
      W_c = 0.0_dp
      n_c = Conduit(k_l)%roughness
      Nsides = 1
      Sx = 0.01_dp
      Sw = Sx
   end if
end subroutine getConduitGeometry

! inlet.c:1200
recursive function getFlowSpread(Q_l) result(res_)
   real(dp), value :: Q_l
   real(dp) :: res_
   integer(int32) :: iter_l
   real(dp) :: f_l
   real(dp) :: f1
   real(dp) :: Sr
   real(dp) :: Ts1
   real(dp) :: Ts2
   real(dp) :: Tw_l
   real(dp) :: Qs
   real(dp) :: Eo
   res_ = 0.0_dp
   iter_l = 0
   f_l = 0.0_dp
   f1 = 0.0_dp
   Sr = 0.0_dp
   Ts1 = 0.0_dp
   Ts2 = 0.0_dp
   Tw_l = 0.0_dp
   Qs = 0.0_dp
   Eo = 0.0_dp
   f_l = Qfactor
   if (a_2 == 0.0_dp) then
      Ts1 = (Q_l / f_l) ** 0.375_dp
   else
      f1 = f_l * (((a_2 / W_c) / Sx) ** 1.67_dp)
      Tw_l = (Q_l / f1) ** 0.375_dp
      if (Tw_l <= W_c) then
         Ts1 = Tw_l
      else
         Sr = (Sx + (a_2 / W_c)) / Sx
         iter_l = 1
         Ts1 = ((Q_l / f_l) ** 0.375_dp) - W_c
         if (Ts1 <= 0.0_dp) then
            Ts1 = Tw_l - W_c
         end if
         do while (iter_l < 11)
            Eo = getEo(Sr, Ts1, W_c)
            Qs = (1.0_dp - Eo) * Q_l
            Ts2 = (Qs / f_l) ** 0.375_dp
            if (abs(Ts2 - Ts1) < 0.01_dp) then
               exit
            end if
            Ts1 = Ts2
            iter_l = iter_l + 1
         end do
         Ts1 = Ts2 + W_c
      end if
   end if
   res_ = merge(Ts1, Tcrown, (Ts1) <= (Tcrown))
   return
end function getFlowSpread

! inlet.c:1248
recursive function getEo(Sr, Ts, w_l) result(res_)
   real(dp), value :: Sr
   real(dp), value :: Ts
   real(dp), value :: w_l
   real(dp) :: res_
   real(dp) :: x_l
   res_ = 0.0_dp
   x_l = 0.0_dp
   x_l = Sr / (Ts / w_l)
   x_l = ((1.0_dp + x_l) ** 2.67_dp) - 1.0_dp
   x_l = 1.0_dp + (Sr / x_l)
   res_ = 1.0_dp / x_l
   return
end function getEo

! inlet.c:1267
recursive function getOnGradeCapturedFlow(inlet_l, q_l, d_l) result(res_)
   type(TInlet), pointer, intent(in) :: inlet_l
   real(dp), value :: q_l
   real(dp), value :: d_l
   real(dp) :: res_
   integer(int32) :: i_l
   integer(int32) :: linkIndex
   real(dp) :: qApproach
   real(dp) :: qc
   real(dp) :: qCaptured
   real(dp) :: qBypassed
   real(dp) :: qMax
   res_ = 0.0_dp
   i_l = 0
   linkIndex = 0
   qApproach = 0.0_dp
   qc = 0.0_dp
   qCaptured = 0.0_dp
   qBypassed = 0.0_dp
   qMax = 0.0_dp
   if (inlet_l%numInlets == 0) then
      res_ = 0.0_dp
      return
   end if
   linkIndex = inlet_l%linkIndex
   qApproach = q_l
   if (qApproach < 0.001_dp) then
      res_ = 0.0_dp
      return
   end if
   call getConduitGeometry(inlet_l)
   qApproach = qApproach / real(Nsides, dp)
   qBypassed = qApproach
   qCaptured = 0.0_dp
   qMax = 10000000000.0_dp
   if (inlet_l%flowLimit > 0.0_dp) then
      qMax = inlet_l%flowLimit
   end if
   i_l = 1
   do while (i_l <= inlet_l%numInlets)
      qc = getOnGradeInletCapture(inlet_l%designIndex, qBypassed, d_l) * inlet_l%clogFactor
      qc = merge(qc, qMax, (qc) <= (qMax))
      qc = merge(qc, qBypassed, (qc) <= (qBypassed))
      qCaptured = qCaptured + qc
      qBypassed = qBypassed - qc
      if (qBypassed < 0.001_dp) then
         exit
      end if
      i_l = i_l + 1
   end do
   qCaptured = qCaptured * real(Nsides, dp)
   res_ = qCaptured
   return
end function getOnGradeCapturedFlow

! inlet.c:1325
recursive function getOnGradeInletCapture(i_l, Q_l, d_l) result(res_)
   integer(int32), value :: i_l
   real(dp), value :: Q_l
   real(dp), value :: d_l
   real(dp) :: res_
   real(dp) :: Q1
   real(dp) :: Qc
   real(dp) :: Lsweep
   real(dp) :: Lcurb
   real(dp) :: Lgrate
   res_ = 0.0_dp
   Q1 = Q_l
   Qc = 0.0_dp
   Lsweep = 0.0_dp
   Lcurb = 0.0_dp
   Lgrate = 0.0_dp
   if (InletDesigns(i_l)%type == DROP_CURB_INLET) then
      Qc = getOnSagInletCapture(i_l, d_l)
      res_ = merge(Qc, Q_l, (Qc) <= (Q_l))
      return
   end if
   if (InletDesigns(i_l)%type == DROP_GRATE_INLET) then
      Qc = getGrateInletCapture(i_l, Q_l)
      res_ = merge(Qc, Q_l, (Qc) <= (Q_l))
      return
   end if
   T_c = getFlowSpread(Q_l)
   if (InletDesigns(i_l)%type == SLOTTED_INLET) then
      Qc = getCurbInletCapture(Q_l, InletDesigns(i_l)%slottedInlet%length)
      res_ = merge(Qc, Q_l, (Qc) <= (Q_l))
      return
   end if
   Lcurb = InletDesigns(i_l)%curbInlet%length
   Lgrate = InletDesigns(i_l)%grateInlet%length
   if (Lcurb > 0.0_dp) then
      Lsweep = Lcurb - Lgrate
      if (Lsweep > 0.0_dp) then
         Qc = getCurbInletCapture(Q1, Lsweep)
         Q1 = Q1 - Qc
      end if
   end if
   if ((Lgrate > 0.0_dp) .and. (Q1 > 0.0_dp)) then
      if (Q1 /= Q_l) then
         T_c = getFlowSpread(Q1)
      end if
      Qc = Qc + getGrateInletCapture(i_l, Q1)
   end if
   res_ = Qc
   return
end function getOnGradeInletCapture

! inlet.c:1387
recursive function getGrateInletCapture(i_l, Q_l) result(res_)
   integer(int32), value :: i_l
   real(dp), value :: Q_l
   real(dp) :: res_
   integer(int32) :: grateType
   real(dp) :: Lg
   real(dp) :: Wg
   real(dp) :: A_l
   real(dp) :: Y_l
   real(dp) :: Eo
   real(dp) :: V_l
   real(dp) :: Vo
   real(dp) :: Qo
   real(dp) :: Rf
   real(dp) :: Rs
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0.0_dp
   grateType = 0
   Lg = 0.0_dp
   Wg = 0.0_dp
   A_l = 0.0_dp
   Y_l = 0.0_dp
   Eo = 0.0_dp
   V_l = 0.0_dp
   Vo = 0.0_dp
   Qo = Q_l
   Rf = 1.0_dp
   Rs = 0.0_dp
   Lg = InletDesigns(i_l)%grateInlet%length
   Wg = InletDesigns(i_l)%grateInlet%width
   b1_ = xsect%type == TRAPEZOIDAL
   if (.not. b1_) then
      b1_ = xsect%type == RECT_OPEN
   end if
   if (b1_) then
      A_l = xsect_getAofS(xsect, Q_l / Beta)
      Y_l = xsect_getYofA(xsect, A_l)
      T_c = xsect_getWofY(xsect, Y_l)
      Eo = ((Beta * ((Y_l * Wg) ** 1.67_dp)) / ((Wg + (2.0_dp * Y_l)) ** 0.67_dp)) / Q_l
      b2_ = Wg > (0.99_dp * xsect%yBot)
      if (b2_) then
         b2_ = xsect%type == TRAPEZOIDAL
      end if
      b3_ = b2_
      if (b3_) then
         b3_ = xsect%sBot > 0.0_dp
      end if
      if (b3_) then
         Wg = xsect%yBot
         Sx = 1.0_dp / xsect%sBot
      end if
   else if (a_2 == 0.0_dp) then
      A_l = ((T_c * T_c) * Sx) / 2.0_dp
      Eo = getGutterFlowRatio(Wg)
      if (T_c >= Tcrown) then
         Qo = Qfactor * (Tcrown ** 2.67_dp)
      end if
   else
      if (T_c <= W_c) then
         A_l = ((T_c * T_c) * Sw) / 2.0_dp
      else
         A_l = (((T_c * T_c) * Sx) + (a_2 * W_c)) / 2.0_dp
      end if
      Eo = getGutterFlowRatio(W_c)
      if (Eo < 1.0_dp) then
         if (T_c >= Tcrown) then
            Qo = (Qfactor * (Tcrown ** 2.67_dp)) / (1.0_dp - Eo)
         end if
         Eo = Eo * getGutterAreaRatio(Wg, A_l)
      end if
   end if
   V_l = Qo / A_l
   grateType = InletDesigns(i_l)%grateInlet%type
   if ((grateType < 0) .or. (grateType == GENERIC)) then
      Vo = InletDesigns(i_l)%grateInlet%splashVeloc
   else
      Vo = getSplashOverVelocity(grateType, Lg)
   end if
   if (V_l > Vo) then
      Rf = 1.0_dp - (0.09_dp * (V_l - Vo))
   end if
   if (Eo < 1.0_dp) then
      Rs = 1.0_dp / (1.0_dp + (((0.15_dp * (V_l ** 1.8_dp)) / Sx) / (Lg ** 2.3_dp)))
   end if
   res_ = Q_l * ((Rf * Eo) + (Rs * (1.0_dp - Eo)))
   return
end function getGrateInletCapture

! inlet.c:1477
recursive function getCurbInletCapture(Q_l, L_l) result(res_)
   real(dp), value :: Q_l
   real(dp), value :: L_l
   real(dp) :: res_
   real(dp) :: Se
   real(dp) :: Lt_l
   real(dp) :: Sr
   real(dp) :: Eo
   real(dp) :: E_l
   res_ = 0.0_dp
   Se = Sx
   Lt_l = 0.0_dp
   Sr = 0.0_dp
   Eo = 0.0_dp
   E_l = 1.0_dp
   if (a_2 > 0.0_dp) then
      Sr = Sw / Sx
      Eo = getEo(Sr, T_c - W_c, W_c)
      Se = Sx + ((a_2 / W_c) * Eo)
   end if
   Lt_l = ((0.6_dp * (Q_l ** 0.42_dp)) * (SL ** 0.3_dp)) * ((1.0_dp / (n_c * Se)) ** 0.6_dp)
   if (L_l < Lt_l) then
      E_l = 1.0_dp - (L_l / Lt_l)
      E_l = 1.0_dp - (E_l ** 1.8_dp)
   end if
   E_l = merge(E_l, 1.0_dp, (E_l) <= (1.0_dp))
   E_l = merge(E_l, 0.0_dp, (E_l) >= (0.0_dp))
   res_ = E_l * Q_l
   return
end function getCurbInletCapture

! inlet.c:1518
recursive function getGutterFlowRatio(w_l) result(res_)
   real(dp), value :: w_l
   real(dp) :: res_
   res_ = 0.0_dp
   if (T_c <= w_l) then
      res_ = 1.0_dp
      return
   else if (a_2 > 0.0_dp) then
      res_ = getEo(Sw / Sx, T_c - w_l, w_l)
      return
   else
      res_ = 1.0_dp - ((1.0_dp - (w_l / T_c)) ** 2.67_dp)
      return
   end if
end function getGutterFlowRatio

! inlet.c:1535
recursive function getGutterAreaRatio(Wg, A_l) result(res_)
   real(dp), value :: Wg
   real(dp), value :: A_l
   real(dp) :: res_
   real(dp) :: As
   real(dp) :: Ag
   res_ = 0.0_dp
   As = 0.0_dp
   Ag = 0.0_dp
   if (Wg >= W_c) then
      res_ = 1.0_dp
      return
   end if
   if (T_c <= Wg) then
      res_ = 1.0_dp
      return
   end if
   if (T_c <= W_c) then
      res_ = Wg / T_c
      return
   end if
   As = (0.5_dp * ((T_c - W_c) * (T_c - W_c))) * Sx
   Ag = Wg * (((T_c * Sx) + a_2) - ((Wg * Sw) / 2.0_dp))
   res_ = Ag / (A_l - As)
   return
end function getGutterAreaRatio

! inlet.c:1557
recursive function getSplashOverVelocity(grateType, L_l) result(res_)
   integer(int32), value :: grateType
   real(dp), value :: L_l
   real(dp) :: res_
   res_ = 0.0_dp
   res_ = ((SplashCoeffs(0, grateType) + (SplashCoeffs(1, grateType) * L_l)) - ((SplashCoeffs(2, grateType) * L_l) * L_l)) + (((SplashCoeffs(3, grateType) * L_l) * L_l) * L_l)
   return
end function getSplashOverVelocity

! inlet.c:1574
recursive function getOnSagCapturedFlow(inlet_l, q_l, d_l) result(res_)
   type(TInlet), pointer, intent(in) :: inlet_l
   real(dp), value :: q_l
   real(dp), value :: d_l
   real(dp) :: res_
   integer(int32) :: linkIndex
   integer(int32) :: designIndex
   integer(int32) :: totalInlets
   real(dp) :: qCaptured
   real(dp) :: qMax
   res_ = 0.0_dp
   linkIndex = 0
   designIndex = 0
   totalInlets = 0
   qCaptured = 0.0_dp
   qMax = 10000000000.0_dp
   if (inlet_l%numInlets == 0) then
      res_ = 0.0_dp
      return
   end if
   totalInlets = Nsides * inlet_l%numInlets
   linkIndex = inlet_l%linkIndex
   designIndex = inlet_l%designIndex
   call getConduitGeometry(inlet_l)
   if (inlet_l%flowLimit > 0.0_dp) then
      qMax = inlet_l%flowLimit
   end if
   qCaptured = getOnSagInletCapture(designIndex, abs(d_l))
   qCaptured = qCaptured * inlet_l%clogFactor
   qCaptured = merge(qCaptured, qMax, (qCaptured) <= (qMax))
   qCaptured = qCaptured * real(totalInlets, dp)
   res_ = qCaptured
   return
end function getOnSagCapturedFlow

! inlet.c:1610
recursive function getOnSagInletCapture(i_l, d_l) result(res_)
   integer(int32), value :: i_l
   real(dp), value :: d_l
   real(dp) :: res_
   real(dp) :: Lsweep
   real(dp) :: Lcurb
   real(dp) :: Lgrate
   real(dp), target :: Qsw
   real(dp), target :: Qso
   real(dp), target :: Qgw
   real(dp), target :: Qgo
   real(dp), target :: Qcw
   real(dp), target :: Qco
   res_ = 0.0_dp
   Lsweep = 0.0_dp
   Lcurb = 0.0_dp
   Lgrate = 0.0_dp
   Qsw = 0.0_dp
   Qso = 0.0_dp
   Qgw = 0.0_dp
   Qgo = 0.0_dp
   Qcw = 0.0_dp
   Qco = 0.0_dp
   if (InletDesigns(i_l)%slottedInlet%length > 0.0_dp) then
      res_ = getOnSagSlottedFlow(i_l, d_l)
      return
   end if
   Lgrate = InletDesigns(i_l)%grateInlet%length
   if (Lgrate > 0.0_dp) then
      call findOnSagGrateFlows(i_l, d_l, Qgw, Qgo)
   end if
   Lcurb = InletDesigns(i_l)%curbInlet%length
   if (Lcurb > 0.0_dp) then
      Lsweep = Lcurb - Lgrate
      if (Lsweep > 0.0_dp) then
         call findOnSagCurbFlows(i_l, d_l, Lsweep, Qsw, Qso)
      end if
      if (Qgo > 0.0_dp) then
         call findOnSagCurbFlows(i_l, d_l, Lgrate, Qcw, Qco)
      end if
   end if
   res_ = (((Qgw + Qgo) + Qsw) + Qso) + Qco
   return
end function getOnSagInletCapture

! inlet.c:1644
recursive subroutine findOnSagGrateFlows(i_l, d_l, Qw, Qo)
   integer(int32), value :: i_l
   real(dp), value :: d_l
   real(dp), intent(inout), target :: Qw
   real(dp), intent(inout), target :: Qo
   integer(int32) :: grateType
   real(dp) :: Lg
   real(dp) :: Wg
   real(dp) :: P_l
   real(dp) :: Ao
   real(dp) :: di
   grateType = InletDesigns(i_l)%grateInlet%type
   Lg = InletDesigns(i_l)%grateInlet%length
   Wg = InletDesigns(i_l)%grateInlet%width
   P_l = 0.0_dp
   Ao = 0.0_dp
   di = 0.0_dp
   if (InletDesigns(i_l)%type == DROP_GRATE_INLET) then
      di = d_l
      P_l = 2.0_dp * (Lg + Wg)
   else
      if (d_l <= (Wg * Sw)) then
         Wg = d_l / Sw
      end if
      di = d_l - ((Wg / 2.0_dp) * Sw)
      P_l = Lg + (2.0_dp * Wg)
   end if
   if (grateType == GENERIC) then
      Ao = (Lg * Wg) * InletDesigns(i_l)%grateInlet%fracOpenArea
   else
      Ao = (Lg * Wg) * GrateOpeningRatios(grateType)
   end if
   if (d_l <= ((1.79_dp * Ao) / P_l)) then
      Qw = (3.0_dp * P_l) * (di ** 1.5_dp)
   else
      Qo = (0.67_dp * Ao) * sqrt((2.0_dp * 32.16_dp) * di)
   end if
end subroutine findOnSagGrateFlows

! inlet.c:1703
recursive subroutine findOnSagCurbFlows(i_l, d_l, L_l, Qw, Qo)
   integer(int32), value :: i_l
   real(dp), value :: d_l
   real(dp), value :: L_l
   real(dp), intent(inout), target :: Qw
   real(dp), intent(inout), target :: Qo
   integer(int32) :: throatAngle
   real(dp) :: h_l
   real(dp) :: Qweir
   real(dp) :: Qorif
   real(dp) :: P_l
   real(dp) :: dweir
   real(dp) :: dorif
   real(dp) :: r_l
   throatAngle = InletDesigns(i_l)%curbInlet%throatAngle
   h_l = InletDesigns(i_l)%curbInlet%height
   Qweir = 0.0_dp
   Qorif = 0.0_dp
   P_l = 0.0_dp
   dweir = 0.0_dp
   dorif = 0.0_dp
   r_l = 0.0_dp
   if (L_l <= 0.0_dp) then
      return
   end if
   if (InletDesigns(i_l)%type == DROP_CURB_INLET) then
      L_l = L_l * 4.0_dp
   end if
   dorif = 1.4_dp * h_l
   if (d_l > dorif) then
      Qo = getCurbOrificeFlow(d_l, h_l, L_l, throatAngle)
      return
   end if
   if ((a_2 == 0.0_dp) .or. (L_l > 12.0_dp)) then
      dweir = h_l
      if (d_l < dweir) then
         Qw = (3.0_dp * L_l) * (d_l ** 1.5_dp)
         return
      else
         Qweir = (3.0_dp * L_l) * (dweir ** 1.5_dp)
      end if
   else
      P_l = L_l + (1.8_dp * W_c)
      dweir = h_l + a_2
      if (d_l < dweir) then
         Qw = (2.3_dp * P_l) * (d_l ** 1.5_dp)
         return
      else
         Qweir = (2.3_dp * P_l) * (dweir ** 1.5_dp)
      end if
   end if
   Qorif = getCurbOrificeFlow(dorif, h_l, L_l, throatAngle)
   r_l = (d_l - dweir) / (dorif - dweir)
   Qw = (1.0_dp - r_l) * Qweir
   Qo = r_l * Qorif
end subroutine findOnSagCurbFlows

! inlet.c:1764
recursive function getCurbOrificeFlow(di, h_l, L_l, throatAngle) result(res_)
   real(dp), value :: di
   real(dp), value :: h_l
   real(dp), value :: L_l
   integer(int32), value :: throatAngle
   real(dp) :: res_
   real(dp) :: d_l
   res_ = 0.0_dp
   d_l = di
   if (throatAngle == HORIZONTAL_THROAT) then
      d_l = di - (h_l / 2.0_dp)
   else if (throatAngle == INCLINED_THROAT) then
      d_l = di - ((h_l / 2.0_dp) * 0.7071_dp)
   end if
   res_ = ((0.67_dp * h_l) * L_l) * sqrt((2.0_dp * 32.16_dp) * d_l)
   return
end function getCurbOrificeFlow

! inlet.c:1785
recursive function getOnSagSlottedFlow(i_l, d_l) result(res_)
   integer(int32), value :: i_l
   real(dp), value :: d_l
   real(dp) :: res_
   real(dp) :: L_l
   real(dp) :: w_l
   res_ = 0.0_dp
   L_l = InletDesigns(i_l)%slottedInlet%length
   w_l = InletDesigns(i_l)%slottedInlet%width
   if (d_l <= (2.587_dp * w_l)) then
      res_ = (2.48_dp * L_l) * (d_l ** 1.5_dp)
      return
   else
      res_ = ((0.8_dp * L_l) * w_l) * sqrt(64.32_dp * d_l)
      return
   end if
end function getOnSagSlottedFlow

! inlet.c:1805
recursive subroutine getBackflowRatios()
   type(TInlet), pointer :: inlet_l
   real(dp) :: area_l
   real(dp) :: f_l
   integer(int32) :: n_l
   type(TInletNode), pointer :: inletNodes(:)
   nullify(inlet_l)
   area_l = 0.0_dp
   f_l = 0.0_dp
   n_l = 0
   allocate(inletNodes(0:(int(Nobjects(NODE_c), int64)) - 1))
   if (.not. associated(inletNodes)) then
      return
   end if
   inlet_l => FirstInlet
   do while (.not. (.not. associated(inlet_l)))
      n_l = inlet_l%nodeIndex
      inletNodes(n_l)%numInletLinks = inletNodes(n_l)%numInletLinks + 1
      area_l = getInletArea(inlet_l)
      if (area_l > 0.0_dp) then
         inletNodes(n_l)%numStdInletLinks = inletNodes(n_l)%numStdInletLinks + 1
         inletNodes(n_l)%totalInletArea = inletNodes(n_l)%totalInletArea + area_l
      else
         inletNodes(n_l)%numCustomInlets = inletNodes(n_l)%numCustomInlets + inlet_l%numInlets
      end if
      inlet_l => inlet_l%nextInlet
   end do
   inlet_l => FirstInlet
   do while (.not. (.not. associated(inlet_l)))
      n_l = inlet_l%nodeIndex
      f_l = real(inletNodes(n_l)%numStdInletLinks, dp) / real(inletNodes(n_l)%numInletLinks, dp)
      area_l = getInletArea(inlet_l)
      if (area_l == 0.0_dp) then
         inlet_l%backflowRatio = (real(inlet_l%numInlets, dp) / real(inletNodes(n_l)%numCustomInlets, dp)) * (1.0_dp - f_l)
      else
         inlet_l%backflowRatio = (area_l / inletNodes(n_l)%totalInletArea) * f_l
      end if
      inlet_l => inlet_l%nextInlet
   end do
   ! free(inletNodes)
end subroutine getBackflowRatios

! inlet.c:1870
recursive function getInletArea(inlet_l) result(res_)
   type(TInlet), pointer, intent(in) :: inlet_l
   real(dp) :: res_
   real(dp) :: area_l
   real(dp) :: curbLength
   integer(int32) :: i_l
   integer(int32) :: grateType
   res_ = 0.0_dp
   area_l = 0.0_dp
   curbLength = 0.0_dp
   i_l = inlet_l%designIndex
   grateType = InletDesigns(i_l)%grateInlet%type
   if (InletDesigns(i_l)%grateInlet%length > 0.0_dp) then
      area_l = InletDesigns(i_l)%grateInlet%length * InletDesigns(i_l)%grateInlet%width
      if (grateType == GENERIC) then
         area_l = area_l * InletDesigns(i_l)%grateInlet%fracOpenArea
      else
         area_l = area_l * GrateOpeningRatios(grateType)
      end if
   end if
   curbLength = InletDesigns(i_l)%curbInlet%length - InletDesigns(i_l)%grateInlet%length
   if (curbLength > 0.0_dp) then
      area_l = area_l + (curbLength * InletDesigns(i_l)%curbInlet%height)
   end if
   if (InletDesigns(i_l)%slottedInlet%length > 0.0_dp) then
      area_l = InletDesigns(i_l)%slottedInlet%length * InletDesigns(i_l)%slottedInlet%width
   end if
   res_ = (area_l * real(inlet_l%numInlets, dp)) * inlet_l%clogFactor
   return
end function getInletArea

! inlet.c:1902
recursive function getCustomCapturedFlow(inlet_l, q_l, d_l) result(res_)
   type(TInlet), pointer, intent(in) :: inlet_l
   real(dp), value :: q_l
   real(dp), value :: d_l
   real(dp) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: sides
   integer(int32) :: c_l
   real(dp) :: qApproach
   real(dp) :: qBypassed
   real(dp) :: qCaptured
   real(dp) :: qIncrement
   real(dp) :: qMax
   res_ = 0.0_dp
   i_l = inlet_l%designIndex
   j_l = 0
   sides = 1
   c_l = 0
   qApproach = 0.0_dp
   qBypassed = 0.0_dp
   qCaptured = 0.0_dp
   qIncrement = 0.0_dp
   qMax = 10000000000.0_dp
   if (inlet_l%numInlets == 0) then
      res_ = 0.0_dp
      return
   end if
   qMax = 10000000000.0_dp
   if (inlet_l%flowLimit > 0.0_dp) then
      qMax = inlet_l%flowLimit
   end if
   xsect => Link(inlet_l%linkIndex)%xsect
   if (xsect%type == STREET_XSECT) then
      sides = Street(xsect%transect)%sides
   end if
   qApproach = q_l / real(sides, dp)
   qBypassed = qApproach
   qCaptured = 0.0_dp
   c_l = InletDesigns(i_l)%customCurve
   if (c_l >= 0) then
      if (Curve(c_l)%curveType == DIVERSION_CURVE) then
         j_l = 1
         do while (j_l <= inlet_l%numInlets)
            qIncrement = (inlet_l%clogFactor * table_lookupEx(Curve(c_l), qBypassed * UCF(FLOW))) / UCF(FLOW)
            qIncrement = merge(qIncrement, qMax, (qIncrement) <= (qMax))
            qIncrement = merge(qIncrement, qBypassed, (qIncrement) <= (qBypassed))
            qCaptured = qCaptured + qIncrement
            qBypassed = qBypassed - qIncrement
            if (qBypassed < 0.001_dp) then
               exit
            end if
            j_l = j_l + 1
         end do
      else if (Curve(c_l)%curveType == RATING_CURVE) then
         qCaptured = ((real(inlet_l%numInlets, dp) * inlet_l%clogFactor) * table_lookupEx(Curve(c_l), d_l * UCF(LENGTH))) / UCF(FLOW)
      end if
      qCaptured = qCaptured * real(sides, dp)
   end if
   res_ = qCaptured
   return
end function getCustomCapturedFlow

! input.c:69
recursive function input_countObjects() result(res_)
   integer(int32) :: res_
   integer(int8), target :: line(0:1024)
   integer(int8), target :: wLine(0:1024)
   type(CPtr) :: tok_l
   integer(int32) :: sect
   integer(int32) :: newsect
   integer(int32) :: errcode_l
   integer(int32) :: errsum
   integer(int32) :: i_l
   integer(int64) :: lineCount
   integer(int32) :: dum1_
   integer(int64) :: dum2_
   res_ = 0
   line = 0_int8
   wLine = 0_int8
   tok_l = cnull()
   sect = -1
   newsect = 0
   errcode_l = 0
   errsum = 0
   i_l = 0
   lineCount = 0_int64
   if (ErrorCode /= 0) then
      res_ = ErrorCode
      return
   end if
   dum1_ = error_setInpError(0, lit_0)
   i_l = 0
   do while (i_l < MAX_OBJ_TYPES)
      Nobjects(i_l) = 0
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < 5)
      Nnodes(i_l) = 0
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < 5)
      Nlinks(i_l) = 0
      i_l = i_l + 1
   end do
   call controls_init()
   do while (.not. cisnull(c_fgets(cview(line), 1024, Finp%file)))
      lineCount = lineCount + 1_int64
      dum2_ = sstrncpy(cview(wLine), cview(line), 1024_int64)
      tok_l = c_strtok(cview(wLine), lit_184)
      if (cisnull(tok_l)) then
         cycle
      end if
      if (cget(tok_l, 0) == 59) then
         cycle
      end if
      if (cget(tok_l, 0) == 91) then
         newsect = findmatch(tok_l, SectWords)
         if (newsect >= 0) then
            sect = newsect
            cycle
         else
            sect = -1
            errcode_l = ERR_KEYWORD
         end if
      end if
      if (sect == s_OPTION) then
         errcode_l = readOption(cview(line))
      else if (sect >= 0) then
         errcode_l = addObject(sect, tok_l)
      end if
      if (errcode_l /= 0) then
         call report_writeInputErrorMsg(errcode_l, sect, cview(line), lineCount)
         errsum = errsum + 1
         if (errsum >= MAXERRS) then
            exit
         end if
      end if
   end do
   if (errsum > 0) then
      ErrorCode = ERR_INPUT
   end if
   res_ = ErrorCode
   return
end function input_countObjects

! input.c:141
recursive function input_readData() result(res_)
   integer(int32) :: res_
   integer(int8), target :: line(0:1024)
   integer(int8), target :: wLine(0:1024)
   type(CPtr) :: comment
   integer(int32) :: sect
   integer(int32) :: newsect
   integer(int32) :: inperr
   integer(int32) :: errsum
   integer(int32) :: lineLength
   integer(int32) :: i_l
   integer(int64) :: lineCount
   integer(int32) :: dum1_
   integer(int64) :: dum2_
   res_ = 0
   line = 0_int8
   wLine = 0_int8
   comment = cnull()
   sect = 0
   newsect = 0
   inperr = 0
   errsum = 0
   lineLength = 0
   i_l = 0
   lineCount = 0_int64
   if (ErrorCode /= 0) then
      res_ = ErrorCode
      return
   end if
   dum1_ = error_setInpError(0, lit_0)
   i_l = 0
   do while (i_l < MAX_OBJ_TYPES)
      Mobjects(i_l) = 0
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < 5)
      Mnodes(i_l) = 0
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < 5)
      Mlinks(i_l) = 0
      i_l = i_l + 1
   end do
   Mevents = 0
   i_l = 0
   do while (i_l < Nobjects(TSERIES_c))
      Tseries(i_l)%lastDate = StartDate + StartTime
      i_l = i_l + 1
   end do
   sect = 0
   errsum = 0
   call c_rewind(Finp%file)
   do while (.not. cisnull(c_fgets(cview(line), 1024, Finp%file)))
      lineCount = lineCount + 1_int64
      dum2_ = sstrncpy(cview(wLine), cview(line), 1024_int64)
      Ntokens = getTokens(cview(wLine))
      if (Ntokens == 0) then
         cycle
      end if
      if (cget(Tok(0), 0) == 59) then
         cycle
      end if
      lineLength = int(strlen(cview(line)), int32)
      if (lineLength >= 1024) then
         comment = c_strchr(cview(line), 59)
         if (.not. cisnull(comment)) then
            lineLength = int(cdiff(comment, cview(line)), int32)
         end if
         if (lineLength >= 1024) then
            inperr = ERR_LINE_LENGTH
            call report_writeInputErrorMsg(inperr, sect, cview(line), lineCount)
            errsum = errsum + 1
         end if
      end if
      if (cget(Tok(0), 0) == 91) then
         newsect = findmatch(Tok(0), SectWords)
         if (newsect >= 0) then
            if (sect == s_TRANSECT) then
               call transect_validate(Nobjects(TRANSECT_c) - 1)
            end if
            sect = newsect
            cycle
         else
            inperr = error_setInpError(ERR_KEYWORD, Tok(0))
            call report_writeInputErrorMsg(inperr, sect, cview(line), lineCount)
            errsum = errsum + 1
            exit
         end if
      else
         inperr = parseLine(sect, cview(line))
         if (inperr > 0) then
            errsum = errsum + 1
            if (errsum > MAXERRS) then
               call report_writeLine(lit_201)
            else
               call report_writeInputErrorMsg(inperr, sect, cview(line), lineCount)
            end if
         end if
      end if
      if (errsum > MAXERRS) then
         exit
      end if
   end do
   if (errsum > 0) then
      ErrorCode = ERR_INPUT
   end if
   res_ = ErrorCode
   return
end function input_readData

