! input.c:637
recursive function readControl(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: index_l
   integer(int32) :: keyword
   res_ = 0
   index_l = 0
   keyword = 0
   if (ntoks < 2) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   if (match(tok_l(0), lit_29) /= 0) then
      res_ = controls_addVariable(tok_l, ntoks)
      return
   end if
   if (match(tok_l(0), lit_30) /= 0) then
      res_ = controls_addExpression(tok_l, ntoks)
      return
   end if
   keyword = findmatch(tok_l(0), RuleKeyWords)
   if (keyword < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(0))
      return
   end if
   if (keyword == 0) then
      if (.not. (project_addObject(CONTROL, tok_l(1), Mobjects(CONTROL)) /= 0)) then
         res_ = error_setInpError(ERR_DUP_NAME, Tok(1))
         return
      end if
      Mobjects(CONTROL) = Mobjects(CONTROL) + 1
   end if
   index_l = Mobjects(CONTROL) - 1
   if (index_l < 0) then
      res_ = error_setInpError(ERR_RULE, lit_0)
      return
   end if
   res_ = controls_addRuleClause(index_l, keyword, Tok, Ntokens)
   return
end function readControl

