recursive function readTitle(line) result(res_)
   type(CPtr), value :: line
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: n_l
   integer(int64) :: dum1_
   res_ = 0
   i_l = 0
   n_l = 0
   i_l = 0
   do while (i_l < 3)
      if (strlen(cview(Title(:, i_l))) == 0_int64) then
         n_l = int(strlen(line), int32)
         if (cget(line, n_l - 1) == 10) then
            call cset(line, n_l - 1, 32)
         end if
         dum1_ = sstrncpy(cview(Title(:, i_l)), line, 1024_int64)
         exit
      end if
      i_l = i_l + 1
   end do
   res_ = 0
   return
end function readTitle

