! input.c:755
recursive function readEvent(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   real(dp), target :: x_l(0:3)
   res_ = 0
   x_l = 0.0_dp
   if (ntoks < 4) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   if (.not. (datetime_strToDate(tok_l(0), x_l(0)) /= 0)) then
      res_ = error_setInpError(ERR_DATETIME, tok_l(0))
      return
   end if
   if (.not. (datetime_strToTime(tok_l(1), x_l(1)) /= 0)) then
      res_ = error_setInpError(ERR_DATETIME, tok_l(1))
      return
   end if
   if (.not. (datetime_strToDate(tok_l(2), x_l(2)) /= 0)) then
      res_ = error_setInpError(ERR_DATETIME, tok_l(2))
      return
   end if
   if (.not. (datetime_strToTime(tok_l(3), x_l(3)) /= 0)) then
      res_ = error_setInpError(ERR_DATETIME, tok_l(3))
      return
   end if
   Event(Mevents)%start = x_l(0) + x_l(1)
   Event(Mevents)%end = x_l(2) + x_l(3)
   if (Event(Mevents)%start >= Event(Mevents)%end) then
      res_ = error_setInpError(ERR_DATETIME, lit_204)
      return
   end if
   Mevents = Mevents + 1
   res_ = 0
   return
end function readEvent

