recursive function findmatch(s_l, keyword) result(res_)
   type(CPtr), value :: s_l
   type(CPtr), pointer, intent(in) :: keyword(:)
   integer(int32) :: res_
   integer(int32) :: i_l
   res_ = 0
   i_l = 0
   do while (.not. cisnull(keyword(i_l)))
      if (match(s_l, keyword(i_l)) /= 0) then
         res_ = i_l
         return
      end if
      i_l = i_l + 1
   end do
   res_ = -1
   return
end function findmatch

! input.c:798
recursive function match(str, substr) result(res_)
   type(CPtr), value :: str
   type(CPtr), value :: substr
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   logical :: b1_
   integer(int32) :: v2_
   logical :: b3_
   integer(int32) :: v4_
   logical :: b5_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   if (.not. (cget(substr, 0) /= 0)) then
      res_ = 0
      return
   end if
   k_l = 0
   do while (cget(str, k_l) /= 0)
      if (cget(str, k_l) /= 32) then
         exit
      end if
      k_l = k_l + 1
   end do
   i_l = k_l
   j_l = 0
   do while (cget(substr, j_l) /= 0)
      b5_ = .not. (cget(str, i_l) /= 0)
      if (.not. b5_) then
         b1_ = (cget(str, i_l)) >= 97
         if (b1_) then
            b1_ = (cget(str, i_l)) <= 122
         end if
         if (b1_) then
            v2_ = iand(cget(str, i_l), not(32))
         else
            v2_ = cget(str, i_l)
         end if
         b3_ = (cget(substr, j_l)) >= 97
         if (b3_) then
            b3_ = (cget(substr, j_l)) <= 122
         end if
         if (b3_) then
            v4_ = iand(cget(substr, j_l), not(32))
         else
            v4_ = cget(substr, j_l)
         end if
         b5_ = (v2_) /= (v4_)
      end if
      if (b5_) then
         res_ = 0
         return
      end if
      i_l = i_l + 1
      j_l = j_l + 1
   end do
   res_ = 1
   return
end function match

