   if (getDouble(s_l, x_l) /= 0) then
      if (x_l < 0.0_dp) then
         x_l = x_l - 0.01_dp
      else
         x_l = x_l + 0.01_dp
      end if
      y_l = d2i(x_l)
      res_ = 1
      return
   end if
   y_l = 0
   res_ = 0
   return
end function getInt

