! input.c:882
recursive function getTokens(s_l) result(res_)
   type(CPtr), value :: s_l
   integer(int32) :: res_
   integer(int32) :: len_l
   integer(int32) :: n_l
   integer(int32) :: m_l
   type(CPtr) :: c_l
   res_ = 0
   len_l = 0
   n_l = 0
   m_l = 0
   c_l = cnull()
   n_l = 0
   do while (n_l < 40)
      Tok(n_l) = cnull()
      n_l = n_l + 1
   end do
   n_l = 0
   c_l = c_strchr(s_l, 59)
   if (.not. cisnull(c_l)) then
      call cset(c_l, 0, 0)
   end if
   len_l = int(strlen(s_l), int32)
   do while ((len_l > 0) .and. (n_l < 40))
      m_l = int(c_strcspn(s_l, lit_184), int32)
      if (m_l == 0) then
