! kinwave.c:57
recursive function kinwave_execute(j_l, qinflow, qoutflow, tStep) result(res_)
   integer(int32), value :: j_l
   real(dp), intent(inout), target :: qinflow
   real(dp), intent(inout), target :: qoutflow
   real(dp), value :: tStep
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32) :: result_l
   real(dp) :: dxdt
   real(dp) :: dq
   real(dp) :: ain
   real(dp), target :: aout
   real(dp) :: qin
   real(dp) :: qout
   real(dp) :: a1
   real(dp) :: a2
   real(dp) :: q1
   real(dp) :: q2
   real(dp) :: q3
   res_ = 0
   k_l = 0
   result_l = 1
   dxdt = 0.0_dp
   dq = 0.0_dp
   ain = 0.0_dp
   aout = 0.0_dp
   qin = 0.0_dp
   qout = 0.0_dp
   a1 = 0.0_dp
   a2 = 0.0_dp
   q1 = 0.0_dp
   q2 = 0.0_dp
   q3 = 0.0_dp
   qoutflow = qinflow
   if (Link(j_l)%type /= CONDUIT_c) then
      res_ = result_l
      return
   end if
   if (Link(j_l)%xsect%type == DUMMY) then
      res_ = result_l
      return
   end if
   pXsect => Link(j_l)%xsect
   Qfull = Link(j_l)%qFull
   Afull = Link(j_l)%xsect%aFull
   k_l = Link(j_l)%subIndex
   Beta1 = Conduit(k_l)%beta / Qfull
   q1 = Conduit(k_l)%q1 / Qfull
   q2 = Conduit(k_l)%q2 / Qfull
   qin = ((qinflow) / real(Conduit(k_l)%barrels, dp)) / Qfull
   q3 = link_getLossRate(j_l, KW, qin * Qfull, tStep) / Qfull
   a1 = Conduit(k_l)%a1 / Afull
   a2 = Conduit(k_l)%a2 / Afull
   if (qin >= 1.0_dp) then
      ain = 1.0_dp
   else
      ain = xsect_getAofS(pXsect, qin / Beta1) / Afull
   end if
   if ((qin <= 1.0e-06_dp) .and. (q2 <= 1.0e-06_dp)) then
      qout = 0.0_dp
      aout = 0.0_dp
   else
      dxdt = ((link_getLength(j_l) / tStep) * Afull) / Qfull
      dq = q2 - q1
      C1 = (dxdt * WT) / WX
      C2 = (1.0_dp - WT) * (ain - a1)
      C2 = C2 - (WT * a2)
      C2 = (C2 * dxdt) / WX
      C2 = (C2 + (((1.0_dp - WX) / WX) * dq)) - qin
      C2 = C2 + (q3 / WX)
      aout = a2
      result_l = solveContinuity(qin, ain, aout)
      if (result_l == (-1)) then
         call report_writeErrorMsg(ERR_KINWAVE, Link(j_l)%ID)
         res_ = 1
         return
      end if
      if (result_l <= 0) then
         result_l = 1
      end if
      qout = Beta1 * xsect_getSofA(pXsect, aout * Afull)
      if (qin > 1.0_dp) then
         qin = 1.0_dp
      end if
   end if
   Conduit(k_l)%q1 = qin * Qfull
   Conduit(k_l)%a1 = ain * Afull
   Conduit(k_l)%q2 = qout * Qfull
   Conduit(k_l)%a2 = aout * Afull
   Conduit(k_l)%fullState = link_getFullState(Conduit(k_l)%a1, Conduit(k_l)%a2, Afull)
   qinflow = Conduit(k_l)%q1 * real(Conduit(k_l)%barrels, dp)
   qoutflow = Conduit(k_l)%q2 * real(Conduit(k_l)%barrels, dp)
   res_ = result_l
   return
end function kinwave_execute

! kinwave.c:170
recursive function solveContinuity(qin, ain, aout) result(res_)
   real(dp), value :: qin
   real(dp), value :: ain
   real(dp), intent(inout), target :: aout
   integer(int32) :: res_
   integer(int32) :: n_l
   real(dp) :: aLo
   real(dp) :: aHi
   real(dp) :: aTmp
   real(dp) :: fLo_l
   real(dp) :: fHi_l
   real(dp) :: tol
   logical :: b1_
   res_ = 0
   n_l = 0
   aLo = 0.0_dp
   aHi = 0.0_dp
   aTmp = 0.0_dp
   fLo_l = 0.0_dp
   fHi_l = 0.0_dp
   tol = EPSIL
   aHi = 1.0_dp
   fHi_l = (1.0_dp + C1) + C2
   aLo = xsect_getAmax(pXsect) / Afull
   if (aLo < aHi) then
      fLo_l = ((Beta1 * pXsect%sMax) + (C1 * aLo)) + C2
   else
      fLo_l = fHi_l
   end if
   if ((fHi_l * fLo_l) > 0.0_dp) then
      aHi = aLo
      fHi_l = fLo_l
      aLo = 0.0_dp
      fLo_l = C2
   end if
   if ((fHi_l * fLo_l) <= 0.0_dp) then
      b1_ = aout < aLo
      if (.not. b1_) then
         b1_ = aout > aHi
      end if
      if (b1_) then
         aout = 0.5_dp * (aLo + aHi)
      end if
      if (fLo_l > fHi_l) then
         aTmp = aLo
         aLo = aHi
         aHi = aTmp
      end if
      n_l = findroot_Newton(aLo, aHi, aout, tol, evalContinuity, c_null_ptr)
      if (n_l <= 0) then
         n_l = -1
      end if
   else if (fLo_l < 0.0_dp) then
      if (qin > 1.0_dp) then
         aout = ain
      else
         aout = 1.0_dp
      end if
      n_l = -2
   else if (fLo_l > 0.0_dp) then
      aout = 0.0_dp
      n_l = -3
   else
      n_l = -1
   end if
   res_ = n_l
   return
end function solveContinuity

! kinwave.c:261
recursive subroutine evalContinuity(a_l, f_l, df, p_l)
   real(dp), value :: a_l
   real(dp), intent(inout), target :: f_l
   real(dp), intent(inout), target :: df
   type(c_ptr), value :: p_l
   f_l = ((Beta1 * xsect_getSofA(pXsect, a_l * Afull)) + (C1 * a_l)) + C2
   df = ((Beta1 * Afull) * xsect_getdSdA(pXsect, a_l * Afull)) + C1
end subroutine evalContinuity

! landuse.c:51
recursive function landuse_readParams(j_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   type(CPtr) :: id
   logical :: b1_
   res_ = 0
   id = cnull()
   if (ntoks < 1) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(LANDUSE_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   Landuse(j_l)%ID = id
   if (ntoks > 1) then
      if (ntoks < 4) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (.not. (getDouble(tok_l(1), Landuse(j_l)%sweepInterval) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(1))
         return
      end if
      if (.not. (getDouble(tok_l(2), Landuse(j_l)%sweepRemoval) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(2))
         return
      end if
      if (.not. (getDouble(tok_l(3), Landuse(j_l)%sweepDays0) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(3))
         return
      end if
   else
      Landuse(j_l)%sweepInterval = 0.0_dp
      Landuse(j_l)%sweepRemoval = 0.0_dp
      Landuse(j_l)%sweepDays0 = 0.0_dp
   end if
   b1_ = Landuse(j_l)%sweepRemoval < 0.0_dp
   if (.not. b1_) then
      b1_ = Landuse(j_l)%sweepRemoval > 1.0_dp
   end if
   if (b1_) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(2))
      return
   end if
   res_ = 0
   return
end function landuse_readParams

! landuse.c:92
recursive function landuse_readPollutParams(j_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: coPollut
   integer(int32) :: snowFlag
   real(dp), target :: x_l(0:3)
   real(dp), target :: coFrac
   real(dp), target :: cDWF
   real(dp), target :: cInit_l
   type(CPtr) :: id
   logical :: b1_
   res_ = 0
   i_l = 0
   k_l = 0
   coPollut = 0
   snowFlag = 0
   x_l = 0.0_dp
   coFrac = 0.0_dp
   cDWF = 0.0_dp
   cInit_l = 0.0_dp
   id = cnull()
   if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(POLLUT_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   k_l = findmatch(tok_l(1), QualUnitsWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   i_l = 2
   do while (i_l <= 4)
      b1_ = .not. (getDouble(tok_l(i_l), x_l(i_l - 2)) /= 0)
      if (.not. b1_) then
         b1_ = x_l(i_l - 2) < 0.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   if (.not. (getDouble(tok_l(5), x_l(3)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(5))
      return
   end if
   snowFlag = 0
   coPollut = -1
   coFrac = 0.0_dp
   cDWF = 0.0_dp
   cInit_l = 0.0_dp
   if (ntoks >= 7) then
      snowFlag = findmatch(tok_l(6), NoYesWords)
      if (snowFlag < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(6))
         return
      end if
   end if
   if (ntoks >= 9) then
      if (.not. (strcomp(tok_l(7), lit_275) /= 0)) then
         coPollut = project_findObject(POLLUT_c, tok_l(7))
         if (coPollut < 0) then
            res_ = error_setInpError(ERR_NAME, tok_l(7))
            return
         end if
         if ((.not. (getDouble(tok_l(8), coFrac) /= 0)) .or. (coFrac < 0.0_dp)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(8))
            return
         end if
      end if
   end if
   if (ntoks >= 10) then
      if ((.not. (getDouble(tok_l(9), cDWF) /= 0)) .or. (cDWF < 0.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(9))
         return
      end if
   end if
   if (ntoks >= 11) then
      if ((.not. (getDouble(tok_l(10), cInit_l) /= 0)) .or. (cInit_l < 0.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(9))
         return
      end if
   end if
   Pollut(j_l)%ID = id
   Pollut(j_l)%units = k_l
   if (Pollut(j_l)%units == MG) then
      Pollut(j_l)%mcf = UCF(MASS)
   else if (Pollut(j_l)%units == UG) then
      Pollut(j_l)%mcf = UCF(MASS) / 1000.0_dp
   else
      Pollut(j_l)%mcf = 1.0_dp
   end if
   Pollut(j_l)%pptConcen = x_l(0)
   Pollut(j_l)%gwConcen = x_l(1)
   Pollut(j_l)%rdiiConcen = x_l(2)
   Pollut(j_l)%kDecay = x_l(3) / 86400.0_dp
   Pollut(j_l)%snowOnly = snowFlag
   Pollut(j_l)%coPollut = coPollut
   Pollut(j_l)%coFraction = coFrac
   Pollut(j_l)%dwfConcen = cDWF
   Pollut(j_l)%initConcen = cInit_l
   res_ = 0
   return
end function landuse_readPollutParams

! landuse.c:190
recursive function landuse_readBuildupParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: n_l
   integer(int32) :: p_l
   real(dp), target :: c_l(0:2)
   real(dp) :: tmax_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   n_l = 0
   p_l = 0
   c_l = 0.0_dp
   c_l(0:2) = [0.0_dp, 0.0_dp, 0.0_dp]
   tmax_l = 0.0_dp
   if (ntoks < 3) then
      res_ = 0
      return
   end if
   j_l = project_findObject(LANDUSE_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   p_l = project_findObject(POLLUT_c, tok_l(1))
   if (p_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   k_l = findmatch(tok_l(2), BuildupTypeWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(2))
      return
   end if
   Landuse(j_l)%buildupFunc(p_l)%funcType = k_l
   if (k_l > NO_BUILDUP) then
      if (ntoks < 7) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (k_l /= EXTERNAL_BUILDUP) then
         i_l = 0
         do while (i_l < 3)
            b1_ = .not. (getDouble(tok_l(i_l + 3), c_l(i_l)) /= 0)
            if (.not. b1_) then
               b1_ = c_l(i_l) < 0.0_dp
            end if
            if (b1_) then
               res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 3))
               return
            end if
            i_l = i_l + 1
         end do
      end if
      n_l = findmatch(tok_l(6), NormalizerWords)
      if (n_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(6))
         return
      end if
      Landuse(j_l)%buildupFunc(p_l)%normalizer = n_l
   end if
   select case (Landuse(j_l)%buildupFunc(p_l)%funcType)
   case (1)
      b3_ = c_l(2) > 0.0_dp
      if (b3_) then
         b2_ = c_l(2) < 0.01_dp
         if (.not. b2_) then
            b2_ = c_l(2) > 10.0_dp
         end if
         b3_ = b2_
      end if
      if (b3_) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(5))
         return
      end if
      if ((c_l(1) * c_l(2)) == 0.0_dp) then
         tmax_l = 0.0_dp
      else if ((log10(c_l(0)) / c_l(2)) > 3.5_dp) then
         tmax_l = 3650.0_dp
      else
         tmax_l = (c_l(0) / c_l(1)) ** (1.0_dp / c_l(2))
      end if
   case (2)
      if (c_l(1) == 0.0_dp) then
         tmax_l = 0.0_dp
      else
         tmax_l = (-log(0.001_dp)) / c_l(1)
      end if
   case (3)
      tmax_l = 1000.0_dp * c_l(2)
   case (4)
      b4_ = .not. (getDouble(tok_l(3), c_l(0)) /= 0)
      if (.not. b4_) then
         b4_ = c_l(0) < 0.0_dp
      end if
      if (b4_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(3))
         return
      end if
      b5_ = .not. (getDouble(tok_l(4), c_l(1)) /= 0)
      if (.not. b5_) then
         b5_ = c_l(1) < 0.0_dp
      end if
      if (b5_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(3))
         return
      end if
      n_l = project_findObject(TSERIES_c, tok_l(5))
      if (n_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(4))
         return
      end if
      Tseries(n_l)%refersTo = EXTERNAL_BUILDUP
      c_l(2) = real(n_l, dp)
      tmax_l = 0.0_dp
   case default
      tmax_l = 0.0_dp
   end select
   Landuse(j_l)%buildupFunc(p_l)%coeff(0) = c_l(0)
   Landuse(j_l)%buildupFunc(p_l)%coeff(1) = c_l(1)
   Landuse(j_l)%buildupFunc(p_l)%coeff(2) = c_l(2)
   Landuse(j_l)%buildupFunc(p_l)%maxDays = tmax_l
   res_ = 0
   return
end function landuse_readBuildupParams

! landuse.c:281
recursive function landuse_readWashoffParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: p_l
   integer(int32) :: func
   real(dp), target :: x_l(0:3)
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0
   i_l = 0
   j_l = 0
   p_l = 0
   func = 0
   x_l = 0.0_dp
   if (ntoks < 3) then
      res_ = 0
      return
   end if
   i_l = 0
   do while (i_l < 4)
      x_l(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   func = NO_WASHOFF
   j_l = project_findObject(LANDUSE_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   p_l = project_findObject(POLLUT_c, tok_l(1))
   if (p_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   if (ntoks > 2) then
      func = findmatch(tok_l(2), WashoffTypeWords)
      if (func < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(2))
         return
      end if
      if (func /= NO_WASHOFF) then
         if (ntoks < 5) then
            res_ = error_setInpError(ERR_ITEMS, lit_0)
            return
         end if
         if (.not. (getDouble(tok_l(3), x_l(0)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(3))
            return
         end if
         if (.not. (getDouble(tok_l(4), x_l(1)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(4))
            return
         end if
         if (ntoks >= 6) then
            if (.not. (getDouble(tok_l(5), x_l(2)) /= 0)) then
               res_ = error_setInpError(ERR_NUMBER, tok_l(5))
               return
            end if
         end if
         if (ntoks >= 7) then
            if (.not. (getDouble(tok_l(6), x_l(3)) /= 0)) then
               res_ = error_setInpError(ERR_NUMBER, tok_l(6))
               return
            end if
         end if
      end if
   end if
   if (x_l(0) < 0.0_dp) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(3))
      return
   end if
   b1_ = x_l(1) < (-10.0_dp)
   if (.not. b1_) then
      b1_ = x_l(1) > 10.0_dp
   end if
   if (b1_) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(4))
      return
   end if
   b2_ = x_l(2) < 0.0_dp
   if (.not. b2_) then
      b2_ = x_l(2) > 100.0_dp
   end if
   if (b2_) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(5))
      return
   end if
   b3_ = x_l(3) < 0.0_dp
   if (.not. b3_) then
      b3_ = x_l(3) > 100.0_dp
   end if
   if (b3_) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(6))
      return
   end if
   if (func == EXPON_WASHOFF) then
      x_l(0) = x_l(0) / 3600.0_dp
   end if
   if (func == RATING_WASHOFF) then
      x_l(0) = x_l(0) * (UCF(FLOW) ** x_l(1))
   end if
   if (func == EMC_WASHOFF) then
      x_l(0) = x_l(0) * 28.317_dp
   end if
   Landuse(j_l)%washoffFunc(p_l)%funcType = func
   Landuse(j_l)%washoffFunc(p_l)%coeff = x_l(0)
   Landuse(j_l)%washoffFunc(p_l)%expon = x_l(1)
   Landuse(j_l)%washoffFunc(p_l)%sweepEffic = x_l(2) / 100.0_dp
   Landuse(j_l)%washoffFunc(p_l)%bmpEffic = x_l(3) / 100.0_dp
   res_ = 0
   return
end function landuse_readWashoffParams

! landuse.c:355
recursive subroutine landuse_getInitBuildup(landFactor, initBuildup, area_l, curb)
   type(TLandFactor), pointer, intent(in) :: landFactor(:)
   real(dp), pointer, intent(in) :: initBuildup(:)
   real(dp), value :: area_l
   real(dp), value :: curb
   integer(int32) :: i_l
   integer(int32) :: p_l
   real(dp) :: startDrySeconds
   real(dp) :: f_l
   real(dp) :: fArea
   real(dp) :: fCurb
   real(dp) :: buildup
   i_l = 0
   p_l = 0
   startDrySeconds = 0.0_dp
   f_l = 0.0_dp
   fArea = 0.0_dp
   fCurb = 0.0_dp
   buildup = 0.0_dp
   startDrySeconds = StartDryDays * 86400.0_dp
   i_l = 0
   do while (i_l < Nobjects(LANDUSE_c))
      landFactor(i_l)%lastSwept = StartDateTime - Landuse(i_l)%sweepDays0
      f_l = landFactor(i_l)%fraction
      fArea = (f_l * area_l) * UCF(LANDAREA)
      fCurb = f_l * curb
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         buildup = 0.0_dp
         if (initBuildup(p_l) > 0.0_dp) then
            buildup = initBuildup(p_l) * fArea
         else
            buildup = landuse_getBuildup(i_l, p_l, fArea, fCurb, buildup, startDrySeconds)
         end if
         landFactor(i_l)%buildup(p_l) = buildup
         p_l = p_l + 1
      end do
      i_l = i_l + 1
   end do
end subroutine landuse_getInitBuildup

! landuse.c:411
recursive function landuse_getBuildup(i_l, p_l, area_l, curb, buildup, tStep) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: p_l
   real(dp), value :: area_l
   real(dp), value :: curb
   real(dp), value :: buildup
   real(dp), value :: tStep
   real(dp) :: res_
   integer(int32) :: n_l
   real(dp) :: days_l
   real(dp) :: perUnit
   res_ = 0.0_dp
   n_l = 0
   days_l = 0.0_dp
   perUnit = 0.0_dp
   if ((Landuse(i_l)%buildupFunc(p_l)%funcType == NO_BUILDUP) .or. (tStep == 0.0_dp)) then
      res_ = buildup
      return
   end if
   n_l = Landuse(i_l)%buildupFunc(p_l)%normalizer
   perUnit = 1.0_dp
   if (n_l == PER_AREA) then
      perUnit = area_l
   end if
   if (n_l == PER_CURB) then
      perUnit = curb
   end if
   if (perUnit == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (Landuse(i_l)%buildupFunc(p_l)%funcType == EXTERNAL_BUILDUP) then
      res_ = landuse_getExternalBuildup(i_l, p_l, buildup / perUnit, tStep) * perUnit
      return
   end if
   days_l = landuse_getBuildupDays(i_l, p_l, buildup / perUnit)
   days_l = days_l + (tStep / 86400.0_dp)
   res_ = landuse_getBuildupMass(i_l, p_l, days_l) * perUnit
   return
end function landuse_getBuildup

! landuse.c:458
recursive function landuse_getBuildupDays(i_l, p_l, buildup) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: p_l
   real(dp), value :: buildup
   real(dp) :: res_
   real(dp) :: c0
   real(dp) :: c1_l
   real(dp) :: c2_l
   res_ = 0.0_dp
   c0 = Landuse(i_l)%buildupFunc(p_l)%coeff(0)
   c1_l = Landuse(i_l)%buildupFunc(p_l)%coeff(1)
   c2_l = Landuse(i_l)%buildupFunc(p_l)%coeff(2)
   if (buildup == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (buildup >= c0) then
      res_ = Landuse(i_l)%buildupFunc(p_l)%maxDays
      return
   end if
   select case (Landuse(i_l)%buildupFunc(p_l)%funcType)
   case (1)
      if ((c1_l * c2_l) == 0.0_dp) then
         res_ = 0.0_dp
         return
      else
         res_ = (buildup / c1_l) ** (1.0_dp / c2_l)
         return
      end if
   case (2)
      if ((c0 * c1_l) == 0.0_dp) then
         res_ = 0.0_dp
         return
      else
         res_ = (-log(1.0_dp - (buildup / c0))) / c1_l
         return
      end if
   case (3)
      if (c0 == 0.0_dp) then
         res_ = 0.0_dp
         return
      else
         res_ = (buildup * c2_l) / (c0 - buildup)
         return
      end if
   case default
      res_ = 0.0_dp
      return
   end select
end function landuse_getBuildupDays

! landuse.c:494
recursive function landuse_getBuildupMass(i_l, p_l, days_l) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: p_l
   real(dp), value :: days_l
   real(dp) :: res_
   real(dp) :: b_l
   real(dp) :: c0
   real(dp) :: c1_l
   real(dp) :: c2_l
   res_ = 0.0_dp
   b_l = 0.0_dp
   c0 = Landuse(i_l)%buildupFunc(p_l)%coeff(0)
   c1_l = Landuse(i_l)%buildupFunc(p_l)%coeff(1)
   c2_l = Landuse(i_l)%buildupFunc(p_l)%coeff(2)
   if (days_l == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (days_l >= Landuse(i_l)%buildupFunc(p_l)%maxDays) then
      res_ = c0
      return
   end if
   select case (Landuse(i_l)%buildupFunc(p_l)%funcType)
   case (1)
      b_l = c1_l * (days_l ** c2_l)
      if (b_l > c0) then
         b_l = c0
      end if
   case (2)
      b_l = c0 * (1.0_dp - exp((-days_l) * c1_l))
   case (3)
      b_l = (days_l * c0) / (c2_l + days_l)
   case default
      b_l = 0.0_dp
   end select
   res_ = b_l
   return
end function landuse_getBuildupMass

! landuse.c:532
recursive function landuse_getAvgBmpEffic(j_l, p_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: p_l
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: r_l
   res_ = 0.0_dp
   i_l = 0
   r_l = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(LANDUSE_c))
      r_l = r_l + (Subcatch(j_l)%landFactor(i_l)%fraction * Landuse(i_l)%washoffFunc(p_l)%bmpEffic)
      i_l = i_l + 1
   end do
   res_ = r_l
   return
end function landuse_getAvgBmpEffic

! landuse.c:553
recursive function landuse_getWashoffLoad(i_l, p_l, area_l, landFactor, runoff, vOutflow_l) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: p_l
   real(dp), value :: area_l
   type(TLandFactor), pointer, intent(in) :: landFactor(:)
   real(dp), value :: runoff
   real(dp), value :: vOutflow_l
   real(dp) :: res_
   real(dp) :: landuseArea
   real(dp) :: buildup
   real(dp) :: washoffQual
   real(dp) :: washoffLoad
   real(dp) :: bmpRemoval
   res_ = 0.0_dp
   landuseArea = 0.0_dp
   buildup = 0.0_dp
   washoffQual = 0.0_dp
   washoffLoad = 0.0_dp
   bmpRemoval = 0.0_dp
   buildup = landFactor(i_l)%buildup(p_l)
   landuseArea = landFactor(i_l)%fraction * area_l
   washoffQual = landuse_getWashoffQual(i_l, p_l, buildup, runoff, landuseArea)
   washoffLoad = (((washoffQual * vOutflow_l) * landuseArea) / area_l) * Pollut(p_l)%mcf
   if ((Landuse(i_l)%buildupFunc(p_l)%funcType /= NO_BUILDUP) .or. (buildup > washoffLoad)) then
      washoffLoad = merge(washoffLoad, buildup, (washoffLoad) <= (buildup))
      buildup = buildup - washoffLoad
      landFactor(i_l)%buildup(p_l) = buildup
   else
      call massbal_updateLoadingTotals(BUILDUP_LOAD, p_l, washoffLoad)
      landFactor(i_l)%buildup(p_l) = 0.0_dp
   end if
   bmpRemoval = Landuse(i_l)%washoffFunc(p_l)%bmpEffic * washoffLoad
   if (bmpRemoval > 0.0_dp) then
      call massbal_updateLoadingTotals(BMP_REMOVAL_LOAD, p_l, bmpRemoval)
      washoffLoad = washoffLoad - bmpRemoval
   end if
   res_ = washoffLoad / Pollut(p_l)%mcf
   return
end function landuse_getWashoffLoad

! landuse.c:612
recursive function landuse_getWashoffQual(i_l, p_l, buildup, runoff, area_l) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: p_l
   real(dp), value :: buildup
   real(dp), value :: runoff
   real(dp), value :: area_l
   real(dp) :: res_
   real(dp) :: cWashoff
   real(dp) :: coeff
   real(dp) :: expon
   integer(int32) :: func
   res_ = 0.0_dp
   cWashoff = 0.0_dp
   coeff = Landuse(i_l)%washoffFunc(p_l)%coeff
   expon = Landuse(i_l)%washoffFunc(p_l)%expon
   func = Landuse(i_l)%washoffFunc(p_l)%funcType
   if ((func == NO_WASHOFF) .or. (runoff == 0.0_dp)) then
      res_ = 0.0_dp
      return
   end if
   if ((Landuse(i_l)%buildupFunc(p_l)%funcType /= NO_BUILDUP) .and. (buildup == 0.0_dp)) then
      res_ = 0.0_dp
      return
   end if
   if (func == EXPON_WASHOFF) then
      cWashoff = ((coeff * ((runoff * UCF(RAINFALL)) ** expon)) * buildup) / Pollut(p_l)%mcf
      cWashoff = cWashoff / (runoff * area_l)
   else if (func == RATING_WASHOFF) then
      cWashoff = coeff * ((runoff * area_l) ** (expon - 1.0_dp))
   else if (func == EMC_WASHOFF) then
      cWashoff = coeff
   end if
   res_ = cWashoff
   return
end function landuse_getWashoffQual

! landuse.c:665
recursive function landuse_getCoPollutLoad(p_l, washoff) result(res_)
   integer(int32), value :: p_l
   real(dp), pointer, intent(in) :: washoff(:)
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: w_l
   res_ = 0.0_dp
   k_l = 0
   w_l = 0.0_dp
   k_l = Pollut(p_l)%coPollut
   if (k_l >= 0) then
      w_l = Pollut(p_l)%coFraction * washoff(k_l)
      call massbal_updateLoadingTotals(BUILDUP_LOAD, p_l, w_l * Pollut(p_l)%mcf)
      res_ = w_l
      return
   end if
   res_ = 0.0_dp
   return
end function landuse_getCoPollutLoad

! landuse.c:693
recursive function landuse_getExternalBuildup(i_l, p_l, buildup, tStep) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: p_l
   real(dp), value :: buildup
   real(dp), value :: tStep
   real(dp) :: res_
   real(dp) :: maxBuildup
   real(dp) :: sf_l
   integer(int32) :: ts
   real(dp) :: rate
   res_ = 0.0_dp
   maxBuildup = Landuse(i_l)%buildupFunc(p_l)%coeff(0)
   sf_l = Landuse(i_l)%buildupFunc(p_l)%coeff(1)
   ts = d2i(cfloor(Landuse(i_l)%buildupFunc(p_l)%coeff(2)))
   rate = 0.0_dp
   if (NewRunoffTime == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (ts >= 0) then
      rate = sf_l * table_tseriesLookup(Tseries(ts), getDateTime(NewRunoffTime), 0)
   end if
   buildup = buildup + ((rate * tStep) / 86400.0_dp)
   buildup = merge(buildup, maxBuildup, (buildup) <= (maxBuildup))
   res_ = buildup
   return
end function landuse_getExternalBuildup

! lid.c:237
recursive subroutine lid_create(lidCount_l, subcatchCount)
   integer(int32), value :: lidCount_l
   integer(int32), value :: subcatchCount
   integer(int32) :: j_l
   j_l = 0
   nullify(LidProcs)
   nullify(LidGroups)
   LidCount = lidCount_l
   GroupCount = subcatchCount
   if (GroupCount > 0) then
      allocate(LidGroups(0:int(GroupCount, int64) - 1))
      if (.not. associated(LidGroups)) then
         ErrorCode = ERR_MEMORY
         return
      end if
   end if
   j_l = 0
   do while (j_l < GroupCount)
      nullify(LidGroups(j_l)%p)
      j_l = j_l + 1
   end do
   if (LidCount == 0) then
      return
   end if
   allocate(LidProcs(0:int(LidCount, int64) - 1))
   if (.not. associated(LidProcs)) then
      ErrorCode = ERR_MEMORY
      return
   end if
   j_l = 0
   do while (j_l < LidCount)
      LidProcs(j_l)%lidType = -1
      LidProcs(j_l)%surface%thickness = 0.0_dp
      LidProcs(j_l)%surface%voidFrac = 1.0_dp
      LidProcs(j_l)%surface%roughness = 0.0_dp
      LidProcs(j_l)%surface%surfSlope = 0.0_dp
      LidProcs(j_l)%pavement%thickness = 0.0_dp
      LidProcs(j_l)%soil%thickness = 0.0_dp
      LidProcs(j_l)%storage%thickness = 0.0_dp
      LidProcs(j_l)%storage%kSat = 0.0_dp
      LidProcs(j_l)%drain%coeff = 0.0_dp
      LidProcs(j_l)%drain%offset = 0.0_dp
      LidProcs(j_l)%drainMat%thickness = 0.0_dp
      LidProcs(j_l)%drainMat%roughness = 0.0_dp
      nullify(LidProcs(j_l)%drainRmvl)
      allocate(LidProcs(j_l)%drainRmvl(0:(int(Nobjects(POLLUT_c), int64)) - 1))
      LidProcs(j_l)%drainRmvl = 0.0_dp
      if (.not. associated(LidProcs(j_l)%drainRmvl)) then
         ErrorCode = ERR_MEMORY
         return
      end if
      j_l = j_l + 1
   end do
end subroutine lid_create

! lid.c:304
recursive subroutine lid_delete()
   integer(int32) :: j_l
   j_l = 0
   j_l = 0
   do while (j_l < GroupCount)
      call freeLidGroup(j_l)
      j_l = j_l + 1
   end do
   if (associated(LidGroups)) then
      ! 
      nullify(LidGroups)
   end if
   j_l = 0
   do while (j_l < LidCount)
      if (associated(LidProcs(j_l)%drainRmvl)) then
         ! 
         nullify(LidProcs(j_l)%drainRmvl)
      end if
      j_l = j_l + 1
   end do
   if (associated(LidProcs)) then
      ! 
      nullify(LidProcs)
   end if
   GroupCount = 0
   LidCount = 0
end subroutine lid_delete

! lid.c:322
recursive subroutine freeLidGroup(j_l)
   integer(int32), value :: j_l
   type(LidGroup), pointer :: lidGroup_l
   type(TLidList), pointer :: lidList
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: nextLidUnit
   integer(int32) :: dum1_
   lidGroup_l => LidGroups(j_l)%p
   nullify(lidList)
   nullify(lidUnit)
   nullify(nextLidUnit)
   if (.not. associated(lidGroup_l)) then
      return
   end if
   lidList => lidGroup_l%lidList
   do while (associated(lidList))
      lidUnit => lidList%lidUnit
      if (associated(lidUnit%rptFile)) then
         if (associated(lidUnit%rptFile%file)) then
            dum1_ = c_fclose(lidUnit%rptFile%file)
         end if
         ! free(lidUnit -> rptFile)
      end if
      nextLidUnit => lidList%nextLidUnit
      ! free(lidUnit)
      ! free(lidList)
      lidList => nextLidUnit
   end do
   ! free(lidGroup)
   nullify(LidGroups(j_l)%p)
end subroutine freeLidGroup

! lid.c:355
recursive function lid_readProcParams(toks, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: toks(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: m_l
   res_ = 0
   j_l = 0
   m_l = 0
   if (ntoks < 2) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(LID, toks(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, toks(0))
      return
   end if
   if (cisnull(LidProcs(j_l)%ID)) then
      LidProcs(j_l)%ID = project_findID(LID, toks(0))
   end if
   m_l = findmatch(toks(1), LidTypeWords)
   if (m_l >= 0) then
      LidProcs(j_l)%lidType = m_l
      res_ = 0
      return
   else
      m_l = findmatch(toks(1), LidLayerWords)
   end if
   select case (m_l)
   case (0)
      res_ = readSurfaceData(j_l, toks, ntoks)
      return
   case (1)
      res_ = readSoilData(j_l, toks, ntoks)
      return
   case (2)
      res_ = readStorageData(j_l, toks, ntoks)
      return
   case (3)
      res_ = readPavementData(j_l, toks, ntoks)
      return
   case (5)
      res_ = readDrainData(j_l, toks, ntoks)
      return
   case (4)
      res_ = readDrainMatData(j_l, toks, ntoks)
      return
   case (6)
      res_ = readRemovalsData(j_l, toks, ntoks)
      return
   end select
   res_ = error_setInpError(ERR_KEYWORD, toks(1))
   return
end function lid_readProcParams

! lid.c:415
recursive function lid_readGroupParams(toks, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: toks(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: n_l
   real(dp), target :: x_l(0:5)
   type(CPtr) :: fname
   integer(int32) :: drainSubcatch
   integer(int32) :: drainNode
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   n_l = 0
   x_l = 0.0_dp
   fname = cnull()
   drainSubcatch = -1
   drainNode = -1
   if (ntoks < 8) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(SUBCATCH_c, toks(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, toks(0))
      return
   end if
   k_l = project_findObject(LID, toks(1))
   if (k_l < 0) then
      res_ = error_setInpError(ERR_NAME, toks(1))
      return
   end if
   n_l = c_atoi(toks(2))
   if (n_l < 0) then
      res_ = error_setInpError(ERR_NUMBER, toks(2))
      return
   end if
   if (n_l == 0) then
      res_ = 0
      return
   end if
   i_l = 3
   do while (i_l <= 7)
      b1_ = .not. (getDouble(toks(i_l), x_l(i_l - 3)) /= 0)
      if (.not. b1_) then
         b1_ = x_l(i_l - 3) < 0.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_NUMBER, toks(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   i_l = 2
   do while (i_l <= 3)
      if (x_l(i_l) > 100.0_dp) then
         res_ = error_setInpError(ERR_NUMBER, toks(i_l + 3))
         return
      end if
      i_l = i_l + 1
   end do
   b2_ = ntoks >= 9
   if (b2_) then
      b2_ = c_strcmp(toks(8), lit_275) /= 0
   end if
   if (b2_) then
      fname = toks(8)
   end if
   b3_ = ntoks >= 10
   if (b3_) then
      b3_ = c_strcmp(toks(9), lit_275) /= 0
   end if
   if (b3_) then
      drainSubcatch = project_findObject(SUBCATCH_c, toks(9))
      if (drainSubcatch < 0) then
         drainNode = project_findObject(NODE_c, toks(9))
         if (drainNode < 0) then
            res_ = error_setInpError(ERR_NAME, toks(9))
            return
         end if
      end if
   end if
   x_l(5) = 0.0_dp
   if (ntoks >= 11) then
      b4_ = .not. (getDouble(toks(10), x_l(5)) /= 0)
      if (.not. b4_) then
         b4_ = x_l(5) < 0.0_dp
      end if
      b5_ = b4_
      if (.not. b5_) then
         b5_ = x_l(5) > 100.0_dp
      end if
      if (b5_) then
         res_ = error_setInpError(ERR_NUMBER, toks(10))
         return
      end if
   end if
   res_ = addLidUnit(j_l, k_l, n_l, x_l, fname, drainSubcatch, drainNode)
   return
end function lid_readGroupParams

! lid.c:499
recursive function addLidUnit(j_l, k_l, n_l, x_l, fname, drainSubcatch, drainNode) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   integer(int32), value :: n_l
   real(dp), pointer, intent(in) :: x_l(:)
   type(CPtr), value :: fname
   integer(int32), value :: drainSubcatch
   integer(int32), value :: drainNode
   integer(int32) :: res_
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   res_ = 0
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   lidGroup_l => LidGroups(j_l)%p
   if (.not. associated(lidGroup_l)) then
      allocate(lidGroup_l)
      if (.not. associated(lidGroup_l)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
      nullify(lidGroup_l%lidList)
      LidGroups(j_l)%p => lidGroup_l
   end if
   allocate(lidUnit)
   if (.not. associated(lidUnit)) then
      res_ = error_setInpError(ERR_MEMORY, lit_0)
      return
   end if
   nullify(lidUnit%rptFile)
   allocate(lidList)
   if (.not. associated(lidList)) then
      ! free(lidUnit)
      res_ = error_setInpError(ERR_MEMORY, lit_0)
      return
   end if
   lidList%lidUnit => lidUnit
   lidList%nextLidUnit => lidGroup_l%lidList
   lidGroup_l%lidList => lidList
   lidUnit%lidIndex = k_l
   lidUnit%number = n_l
   lidUnit%area = x_l(0) / ((UCF(LENGTH)) * (UCF(LENGTH)))
   lidUnit%fullWidth = x_l(1) / UCF(LENGTH)
   lidUnit%initSat = x_l(2) / 100.0_dp
   lidUnit%fromImperv = x_l(3) / 100.0_dp
   lidUnit%toPerv = merge(1, 0, x_l(4) > 0.0_dp)
   lidUnit%fromPerv = x_l(5) / 100.0_dp
   lidUnit%drainSubcatch = drainSubcatch
   lidUnit%drainNode = drainNode
   if (.not. cisnull(fname)) then
      if (.not. (createLidRptFile(lidUnit, fname) /= 0)) then
         res_ = error_setInpError(ERR_RPT_FILE, fname)
         return
      end if
   end if
   res_ = 0
   return
end function addLidUnit

! lid.c:567
recursive function createLidRptFile(lidUnit, fname) result(res_)
   type(TLidUnit), pointer, intent(in) :: lidUnit
   type(CPtr), value :: fname
   integer(int32) :: res_
   type(TLidRptFile), pointer :: rptFile
   res_ = 0
   nullify(rptFile)
   allocate(rptFile)
   if (.not. associated(rptFile)) then
      res_ = 0
      return
   end if
   lidUnit%rptFile => rptFile
   rptFile%file => c_fopen(fname, lit_171)
   if (.not. associated(rptFile%file)) then
      res_ = 0
      return
   end if
   res_ = 1
   return
end function createLidRptFile

! lid.c:581
recursive function readSurfaceData(j_l, toks, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: toks(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   real(dp), target :: x_l(0:4)
   logical :: b1_
   res_ = 0
   i_l = 0
   x_l = 0.0_dp
   if (ntoks < 7) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   i_l = 2
   do while (i_l < 7)
      b1_ = .not. (getDouble(toks(i_l), x_l(i_l - 2)) /= 0)
      if (.not. b1_) then
         b1_ = x_l(i_l - 2) < 0.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_NUMBER, toks(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   if (x_l(1) >= 1.0_dp) then
      res_ = error_setInpError(ERR_NUMBER, toks(3))
      return
   end if
   if (x_l(0) == 0.0_dp) then
      x_l(1) = 0.0_dp
   end if
   LidProcs(j_l)%surface%thickness = x_l(0) / UCF(RAINDEPTH)
   LidProcs(j_l)%surface%voidFrac = 1.0_dp - x_l(1)
   LidProcs(j_l)%surface%roughness = x_l(2)
   LidProcs(j_l)%surface%surfSlope = x_l(3) / 100.0_dp
   LidProcs(j_l)%surface%sideSlope = x_l(4)
   res_ = 0
   return
end function readSurfaceData

