      end if
      i_l = i_l + 1
   end do
   x_l(5) = 0.0_dp
   if (ntoks > 7) then
      b2_ = .not. (getDouble(toks(7), x_l(5)) /= 0)
      if (.not. b2_) then
         b2_ = x_l(5) < 0.0_dp
      end if
      if (b2_) then
         res_ = error_setInpError(ERR_NUMBER, toks(7))
