! lid.c:703
recursive function readStorageData(j_l, toks, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: toks(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: covered
   real(dp), target :: x_l(0:5)
   logical :: b1_
   res_ = 0
   i_l = 0
   covered = 0
   x_l = 0.0_dp
   if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   i_l = 2
   do while (i_l < 6)
      b1_ = .not. (getDouble(toks(i_l), x_l(i_l - 2)) /= 0)
      if (.not. b1_) then
         b1_ = x_l(i_l - 2) < 0.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_NUMBER, toks(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   if (ntoks > 6) then
      if (match(toks(6), lit_5) /= 0) then
         covered = 1
      end if
   end if
   x_l(1) = x_l(1) / (x_l(1) + 1.0_dp)
   LidProcs(j_l)%storage%thickness = x_l(0) / UCF(RAINDEPTH)
   LidProcs(j_l)%storage%voidFrac = x_l(1)
   LidProcs(j_l)%storage%kSat = x_l(2) / UCF(RAINFALL)
   LidProcs(j_l)%storage%clogFactor = x_l(3)
   LidProcs(j_l)%storage%covered = covered
   res_ = 0
   return
end function readStorageData

! lid.c:749
recursive function readDrainData(j_l, toks, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: toks(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   real(dp), target :: x_l(0:5)
   logical :: b1_
   logical :: b2_
   res_ = 0
   i_l = 0
   x_l = 0.0_dp
   if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   i_l = 0
   do while (i_l < 6)
      x_l(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 2
   do while (i_l < 8)
      b2_ = ntoks > i_l
      if (b2_) then
         b1_ = .not. (getDouble(toks(i_l), x_l(i_l - 2)) /= 0)
         if (.not. b1_) then
            b1_ = x_l(i_l - 2) < 0.0_dp
         end if
         b2_ = b1_
      end if
      if (b2_) then
         res_ = error_setInpError(ERR_NUMBER, toks(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   i_l = -1
   if (ntoks >= 9) then
      i_l = project_findObject(CURVE_c, toks(8))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, toks(8))
         return
      end if
   end if
   LidProcs(j_l)%drain%coeff = x_l(0)
   LidProcs(j_l)%drain%expon = x_l(1)
   LidProcs(j_l)%drain%offset = x_l(2) / UCF(RAINDEPTH)
   LidProcs(j_l)%drain%delay = x_l(3) * 3600.0_dp
   LidProcs(j_l)%drain%hOpen = x_l(4) / UCF(RAINDEPTH)
   LidProcs(j_l)%drain%hClose = x_l(5) / UCF(RAINDEPTH)
   LidProcs(j_l)%drain%qCurve = i_l
   res_ = 0
   return
end function readDrainData

! lid.c:794
recursive function readDrainMatData(j_l, toks, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: toks(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   real(dp), target :: x_l(0:2)
   logical :: b1_
   res_ = 0
   i_l = 0
   x_l = 0.0_dp
   if (ntoks < 5) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   if (LidProcs(j_l)%lidType /= GREEN_ROOF) then
      res_ = 0
      return
   end if
   i_l = 2
   do while (i_l < 5)
      b1_ = .not. (getDouble(toks(i_l), x_l(i_l - 2)) /= 0)
      if (.not. b1_) then
         b1_ = x_l(i_l - 2) < 0.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_NUMBER, toks(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   LidProcs(j_l)%drainMat%thickness = x_l(0) / UCF(RAINDEPTH)
   LidProcs(j_l)%drainMat%voidFrac = x_l(1)
   LidProcs(j_l)%drainMat%roughness = x_l(2)
   res_ = 0
   return
end function readDrainMatData

! lid.c:828
recursive function readRemovalsData(j_l, toks, ntoks) result(res_)
   integer(int32), value :: j_l
   type(CPtr), pointer, intent(in) :: toks(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: p_l
   real(dp), target :: rmvl
   res_ = 0
   i_l = 2
   p_l = 0
   rmvl = 0.0_dp
   if (ntoks < 4) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   do while (ntoks > i_l)
      p_l = project_findObject(POLLUT_c, toks(i_l))
      if (p_l < 0) then
         res_ = error_setInpError(ERR_NAME, toks(i_l))
         return
      end if
      i_l = i_l + 1
      if (ntoks == i_l) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (((.not. (getDouble(toks(i_l), rmvl) /= 0)) .or. (rmvl < 0.0_dp)) .or. (rmvl > 100.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, toks(i_l))
         return
      end if
      LidProcs(j_l)%drainRmvl(p_l) = rmvl / 100.0_dp
      i_l = i_l + 1
   end do
   res_ = 0
   return
end function readRemovalsData

! lid.c:869
recursive subroutine lid_writeSummary()
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp) :: pctArea
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   j_l = 0
   k_l = 0
   pctArea = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   call c_fprintf(Frpt%file, lit_276)
   call c_fprintf(Frpt%file, lit_276)
   call c_fprintf(Frpt%file, lit_277)
   call c_fprintf(Frpt%file, lit_278)
   call c_fprintf(Frpt%file, lit_277)
   call c_fprintf(Frpt%file, lit_279)
   call c_fprintf(Frpt%file, lit_280)
   call c_fprintf(Frpt%file, lit_281)
   j_l = 0
   do while (j_l < GroupCount)
      lidGroup_l => LidGroups(j_l)%p
      if (.not. associated(lidGroup_l)) then
         goto 100
      end if
      lidList => lidGroup_l%lidList
      do while (associated(lidList))
         lidUnit => lidList%lidUnit
         k_l = lidUnit%lidIndex
         pctArea = ((lidUnit%area * real(lidUnit%number, dp)) / Subcatch(j_l)%area) * 100.0_dp
         call c_fprintf(Frpt%file, lit_282, Subcatch(j_l)%ID, LidProcs(k_l)%ID)
         call c_fprintf(Frpt%file, lit_283, lidUnit%number, lidUnit%area * ((UCF(LENGTH)) * (UCF(LENGTH))), lidUnit%fullWidth * UCF(LENGTH), pctArea, lidUnit%fromImperv * 100.0_dp, lidUnit%fromPerv * 100.0_dp)
         lidList => lidList%nextLidUnit
      end do
      100 continue
      j_l = j_l + 1
   end do
end subroutine lid_writeSummary

! lid.c:918
recursive subroutine lid_validate()
   integer(int32) :: j_l
   j_l = 0
   j_l = 0
   do while (j_l < LidCount)
      call validateLidProc(j_l)
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < GroupCount)
      call validateLidGroup(j_l)
      j_l = j_l + 1
   end do
end subroutine lid_validate

! lid.c:932
recursive subroutine validateLidProc(j_l)
   integer(int32), value :: j_l
   integer(int32) :: layerMissing
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   integer(int64) :: dum5_
   logical :: b6_
   logical :: b7_
   logical :: b8_
   logical :: b9_
   logical :: b10_
   logical :: b11_
   logical :: b12_
   layerMissing = 0
   if (LidProcs(j_l)%lidType < 0) then
      call report_writeErrorMsg(ERR_LID_TYPE, LidProcs(j_l)%ID)
      return
   end if
   select case (LidProcs(j_l)%lidType)
   case (0, 1)
      if (LidProcs(j_l)%soil%thickness <= 0.0_dp) then
         layerMissing = 1
      end if
   case (2)
      if (LidProcs(j_l)%soil%thickness <= 0.0_dp) then
         layerMissing = 1
      end if
      if (LidProcs(j_l)%drainMat%thickness <= 0.0_dp) then
         layerMissing = 1
      end if
   case (4)
      if (LidProcs(j_l)%pavement%thickness <= 0.0_dp) then
         layerMissing = 1
      end if
   case (3)
      if (LidProcs(j_l)%storage%thickness <= 0.0_dp) then
         layerMissing = 1
      end if
   end select
   if (layerMissing /= 0) then
      call report_writeErrorMsg(ERR_LID_LAYER, LidProcs(j_l)%ID)
      return
   end if
   if (LidProcs(j_l)%lidType == POROUS_PAVEMENT) then
      b1_ = LidProcs(j_l)%pavement%thickness <= 0.0_dp
      if (.not. b1_) then
         b1_ = LidProcs(j_l)%pavement%kSat <= 0.0_dp
      end if
      b2_ = b1_
      if (.not. b2_) then
         b2_ = LidProcs(j_l)%pavement%voidFrac <= 0.0_dp
      end if
      b3_ = b2_
      if (.not. b3_) then
         b3_ = LidProcs(j_l)%pavement%voidFrac > 1.0_dp
      end if
      b4_ = b3_
      if (.not. b4_) then
         b4_ = LidProcs(j_l)%pavement%impervFrac > 1.0_dp
      end if
      if (b4_) then
         dum5_ = sstrncpy(cview(Msg), LidProcs(j_l)%ID, 1024_int64)
         dum5_ = sstrcat(cview(Msg), lit_284, 1024_int64)
         call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
      end if
   end if
   if (LidProcs(j_l)%soil%thickness > 0.0_dp) then
      b6_ = LidProcs(j_l)%soil%porosity <= 0.0_dp
      if (.not. b6_) then
         b6_ = LidProcs(j_l)%soil%fieldCap >= LidProcs(j_l)%soil%porosity
      end if
      b7_ = b6_
      if (.not. b7_) then
         b7_ = LidProcs(j_l)%soil%wiltPoint >= LidProcs(j_l)%soil%fieldCap
      end if
      b8_ = b7_
      if (.not. b8_) then
         b8_ = LidProcs(j_l)%soil%kSat <= 0.0_dp
      end if
      b9_ = b8_
      if (.not. b9_) then
         b9_ = LidProcs(j_l)%soil%kSlope < 0.0_dp
      end if
      if (b9_) then
         dum5_ = sstrncpy(cview(Msg), LidProcs(j_l)%ID, 1024_int64)
         dum5_ = sstrcat(cview(Msg), lit_285, 1024_int64)
         call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
      end if
   end if
   if (LidProcs(j_l)%storage%thickness > 0.0_dp) then
      b10_ = LidProcs(j_l)%storage%voidFrac <= 0.0_dp
      if (.not. b10_) then
         b10_ = LidProcs(j_l)%storage%voidFrac > 1.0_dp
      end if
      if (b10_) then
         dum5_ = sstrncpy(cview(Msg), LidProcs(j_l)%ID, 1024_int64)
         dum5_ = sstrcat(cview(Msg), lit_286, 1024_int64)
         call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
      end if
   else
      LidProcs(j_l)%storage%voidFrac = 1.0_dp
      LidProcs(j_l)%drain%offset = 0.0_dp
   end if
   b11_ = LidProcs(j_l)%drain%hOpen > 0.0_dp
   if (b11_) then
      b11_ = LidProcs(j_l)%drain%hOpen <= LidProcs(j_l)%drain%hClose
   end if
   if (b11_) then
      dum5_ = sstrncpy(cview(Msg), LidProcs(j_l)%ID, 1024_int64)
      dum5_ = sstrcat(cview(Msg), lit_287, 1024_int64)
      call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
   end if
   if (LidProcs(j_l)%lidType == VEG_SWALE) then
      b12_ = (LidProcs(j_l)%surface%roughness * LidProcs(j_l)%surface%surfSlope) <= 0.0_dp
      if (.not. b12_) then
         b12_ = LidProcs(j_l)%surface%thickness == 0.0_dp
      end if
      if (b12_) then
         dum5_ = sstrncpy(cview(Msg), LidProcs(j_l)%ID, 1024_int64)
         dum5_ = sstrcat(cview(Msg), lit_288, 1024_int64)
         call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
      else
         LidProcs(j_l)%surface%alpha = (1.49_dp * sqrt(LidProcs(j_l)%surface%surfSlope)) / LidProcs(j_l)%surface%roughness
      end if
   else
      if (LidProcs(j_l)%surface%roughness > 0.0_dp) then
         LidProcs(j_l)%surface%alpha = (1.49_dp / LidProcs(j_l)%surface%roughness) * sqrt(LidProcs(j_l)%surface%surfSlope)
      else
         LidProcs(j_l)%surface%alpha = 0.0_dp
      end if
   end if
   if (LidProcs(j_l)%drainMat%roughness > 0.0_dp) then
      LidProcs(j_l)%drainMat%alpha = (1.49_dp / LidProcs(j_l)%drainMat%roughness) * sqrt(LidProcs(j_l)%surface%surfSlope)
   else
      LidProcs(j_l)%drainMat%alpha = 0.0_dp
   end if
   if (LidProcs(j_l)%pavement%thickness > 0.0_dp) then
      LidProcs(j_l)%pavement%clogFactor = LidProcs(j_l)%pavement%clogFactor * ((LidProcs(j_l)%pavement%thickness * LidProcs(j_l)%pavement%voidFrac) * (1.0_dp - LidProcs(j_l)%pavement%impervFrac))
   end if
   if (LidProcs(j_l)%storage%thickness > 0.0_dp) then
      LidProcs(j_l)%storage%clogFactor = LidProcs(j_l)%storage%clogFactor * (LidProcs(j_l)%storage%thickness * LidProcs(j_l)%storage%voidFrac)
   else
      LidProcs(j_l)%storage%clogFactor = 0.0_dp
   end if
   LidProcs(j_l)%surface%canOverflow = 1
   select case (LidProcs(j_l)%lidType)
   case (7)
      LidProcs(j_l)%surface%canOverflow = 0
   case (3, 4, 0, 1, 2)
      if (LidProcs(j_l)%surface%alpha > 0.0_dp) then
         LidProcs(j_l)%surface%canOverflow = 0
      end if
   end select
   if (LidProcs(j_l)%lidType == RAIN_BARREL) then
      LidProcs(j_l)%storage%voidFrac = 1.0_dp
      LidProcs(j_l)%storage%kSat = 0.0_dp
   end if
   if (LidProcs(j_l)%lidType == GREEN_ROOF) then
      LidProcs(j_l)%storage%thickness = LidProcs(j_l)%drainMat%thickness
      LidProcs(j_l)%storage%voidFrac = LidProcs(j_l)%drainMat%voidFrac
      LidProcs(j_l)%storage%clogFactor = 0.0_dp
      LidProcs(j_l)%storage%kSat = 0.0_dp
   end if
end subroutine validateLidProc

! lid.c:1113
recursive subroutine validateLidGroup(j_l)
   integer(int32), value :: j_l
   integer(int32) :: k_l
   real(dp), target :: p_l(0:2)
   real(dp) :: totalArea_l
   real(dp) :: totalLidArea
   real(dp) :: fromImperv
   real(dp) :: fromPerv
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   integer(int64) :: dum1_
   logical :: b2_
   logical :: b3_
   k_l = 0
   p_l = 0.0_dp
   totalArea_l = Subcatch(j_l)%area
   totalLidArea = 0.0_dp
   fromImperv = 0.0_dp
   fromPerv = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   lidGroup_l => LidGroups(j_l)%p
   if (.not. associated(lidGroup_l)) then
      return
   end if
   lidList => lidGroup_l%lidList
   do while (associated(lidList))
      lidUnit => lidList%lidUnit
      k_l = lidUnit%lidIndex
      totalLidArea = totalLidArea + (lidUnit%area * real(lidUnit%number, dp))
      fromImperv = fromImperv + lidUnit%fromImperv
      fromPerv = fromPerv + lidUnit%fromPerv
      lidUnit%soilInfil%Ks = 0.0_dp
      if (LidProcs(k_l)%soil%thickness > 0.0_dp) then
         p_l(0) = LidProcs(k_l)%soil%suction * UCF(RAINDEPTH)
         p_l(1) = LidProcs(k_l)%soil%kSat * UCF(RAINFALL)
         p_l(2) = (LidProcs(k_l)%soil%porosity - LidProcs(k_l)%soil%wiltPoint) * (1.0_dp - lidUnit%initSat)
         if (grnampt_setParams(lidUnit%soilInfil, p_l) == 0) then
            dum1_ = sstrncpy(cview(Msg), LidProcs(k_l)%ID, 1024_int64)
            dum1_ = sstrcat(cview(Msg), lit_285, 1024_int64)
            call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
         end if
      end if
      if (LidProcs(k_l)%lidType == VEG_SWALE) then
         b2_ = Subcatch(j_l)%infilModel == GREEN_AMPT
         if (.not. b2_) then
            b2_ = Subcatch(j_l)%infilModel == MOD_GREEN_AMPT
         end if
         if (b2_) then
            call grnampt_getParams(j_l, p_l)
            if (grnampt_setParams(lidUnit%soilInfil, p_l) == 0) then
               dum1_ = sstrncpy(cview(Msg), LidProcs(k_l)%ID, 1024_int64)
               dum1_ = sstrcat(cview(Msg), lit_289, 1024_int64)
               call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
            end if
         end if
         if (lidUnit%fullWidth <= 0.0_dp) then
            dum1_ = sstrncpy(cview(Msg), LidProcs(k_l)%ID, 1024_int64)
            dum1_ = sstrcat(cview(Msg), lit_290, 1024_int64)
            call report_writeErrorMsg(ERR_LID_PARAMS, cview(Msg))
         end if
      end if
      if (Subcatch(j_l)%fracImperv >= 0.999_dp) then
         lidUnit%toPerv = 0
      end if
      b3_ = lidUnit%drainNode == (-1)
      if (b3_) then
         b3_ = lidUnit%drainSubcatch == (-1)
      end if
      if (b3_) then
         lidUnit%drainNode = Subcatch(j_l)%outNode
         lidUnit%drainSubcatch = Subcatch(j_l)%outSubcatch
      end if
      lidList => lidList%nextLidUnit
   end do
   if (totalLidArea > (1.001_dp * totalArea_l)) then
      call report_writeErrorMsg(ERR_LID_AREAS, Subcatch(j_l)%ID)
   end if
   if ((fromImperv > 1.001_dp) .or. (fromPerv > 1.001_dp)) then
      call report_writeErrorMsg(ERR_LID_CAPTURE_AREA, Subcatch(j_l)%ID)
   end if
   if (totalLidArea > (0.999_dp * totalArea_l)) then
      totalLidArea = totalArea_l
   end if
   Subcatch(j_l)%lidArea = totalLidArea
end subroutine validateLidGroup

! lid.c:1211
recursive subroutine lid_initState()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   real(dp) :: initVol
   real(dp) :: initDryTime
   i_l = 0
   j_l = 0
   k_l = 0
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   initVol = 0.0_dp
   initDryTime = StartDryDays * 86400.0_dp
   HasWetLids = 0
   j_l = 0
   do while (j_l < GroupCount)
      lidGroup_l => LidGroups(j_l)%p
      if (.not. associated(lidGroup_l)) then
         goto 100
      end if
      lidGroup_l%pervArea = 0.0_dp
      lidGroup_l%flowToPerv = 0.0_dp
      lidGroup_l%oldDrainFlow = 0.0_dp
      lidGroup_l%newDrainFlow = 0.0_dp
      lidList => lidGroup_l%lidList
      do while (associated(lidList))
         lidUnit => lidList%lidUnit
         k_l = lidUnit%lidIndex
         lidUnit%surfaceDepth = 0.0_dp
         lidUnit%storageDepth = 0.0_dp
         lidUnit%soilMoisture = 0.0_dp
         lidUnit%paveDepth = 0.0_dp
         lidUnit%dryTime = initDryTime
         lidUnit%volTreated = 0.0_dp
         lidUnit%nextRegenDay = LidProcs(k_l)%pavement%regenDays
         initVol = 0.0_dp
         if (LidProcs(k_l)%soil%thickness > 0.0_dp) then
            lidUnit%soilMoisture = LidProcs(k_l)%soil%wiltPoint + (lidUnit%initSat * (LidProcs(k_l)%soil%porosity - LidProcs(k_l)%soil%wiltPoint))
            initVol = initVol + (lidUnit%soilMoisture * LidProcs(k_l)%soil%thickness)
         end if
         if (LidProcs(k_l)%storage%thickness > 0.0_dp) then
            lidUnit%storageDepth = lidUnit%initSat * LidProcs(k_l)%storage%thickness
            initVol = initVol + (lidUnit%storageDepth * LidProcs(k_l)%storage%voidFrac)
         end if
         if (lidUnit%initSat > 0.0_dp) then
            HasWetLids = 1
         end if
         call lidproc_initWaterBalance(lidUnit, initVol)
         lidUnit%volTreated = 0.0_dp
         if (associated(lidUnit%rptFile)) then
            call initLidRptFile(cview(Title(:, 0)), LidProcs(k_l)%ID, Subcatch(j_l)%ID, lidUnit)
         end if
         lidUnit%oldDrainFlow = 0.0_dp
         lidUnit%newDrainFlow = 0.0_dp
         i_l = 0
         do while (i_l < 4)
            lidUnit%oldFluxRates(i_l) = 0.0_dp
            i_l = i_l + 1
         end do
         if (lidUnit%soilInfil%Ks > 0.0_dp) then
            call grnampt_initState(lidUnit%soilInfil)
         end if
         if (isLidPervious(lidUnit%lidIndex) /= 0) then
            lidGroup_l%pervArea = lidGroup_l%pervArea + (lidUnit%area * real(lidUnit%number, dp))
         end if
         lidList => lidList%nextLidUnit
      end do
      100 continue
      j_l = j_l + 1
   end do
end subroutine lid_initState

! lid.c:1302
recursive subroutine lid_setOldGroupState(j_l)
   integer(int32), value :: j_l
   type(TLidList), pointer :: lidList
   nullify(lidList)
   if (.not. (.not. associated(LidGroups(j_l)%p))) then
      LidGroups(j_l)%p%oldDrainFlow = LidGroups(j_l)%p%newDrainFlow
      LidGroups(j_l)%p%newDrainFlow = 0.0_dp
      lidList => LidGroups(j_l)%p%lidList
      do while (associated(lidList))
         lidList%lidUnit%oldDrainFlow = lidList%lidUnit%newDrainFlow
         lidList%lidUnit%newDrainFlow = 0.0_dp
         lidList => lidList%nextLidUnit
      end do
   end if
end subroutine lid_setOldGroupState

! lid.c:1326
recursive function isLidPervious(k_l) result(res_)
   integer(int32), value :: k_l
   integer(int32) :: res_
   logical :: b1_
   res_ = 0
   b1_ = LidProcs(k_l)%storage%thickness == 0.0_dp
   if (.not. b1_) then
      b1_ = LidProcs(k_l)%storage%kSat > 0.0_dp
   end if
   res_ = merge(1, 0, b1_)
   return
end function isLidPervious

! lid.c:1339
recursive function getSurfaceDepth(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: depth
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   res_ = 0.0_dp
   k_l = 0
   depth = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   lidGroup_l => LidGroups(j_l)%p
   if (.not. associated(lidGroup_l)) then
      res_ = 0.0_dp
      return
   end if
   if (Subcatch(j_l)%lidArea == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   lidList => lidGroup_l%lidList
   do while (associated(lidList))
      lidUnit => lidList%lidUnit
      k_l = lidUnit%lidIndex
      depth = depth + (((lidUnit%surfaceDepth * LidProcs(k_l)%surface%voidFrac) * lidUnit%area) * real(lidUnit%number, dp))
      lidList => lidList%nextLidUnit
   end do
   res_ = depth / Subcatch(j_l)%lidArea
   return
end function getSurfaceDepth

