! lid.c:1397
recursive function lid_getStoredVolume(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   real(dp) :: total
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
