   res_ = 0.0_dp
   total = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   lidGroup_l => LidGroups(j_l)%p
   b1_ = .not. associated(lidGroup_l)
   if (.not. b1_) then
      b1_ = Subcatch(j_l)%lidArea == 0.0_dp
   end if
   if (b1_) then
      res_ = 0.0_dp
      return
   end if
   lidList => lidGroup_l%lidList
   do while (associated(lidList))
      lidUnit => lidList%lidUnit
      total = total + ((lidUnit%waterBalance%finalVol * lidUnit%area) * real(lidUnit%number, dp))
