end function lid_getStoredVolume

! lid.c:1424
recursive function lid_getDrainFlow(j_l, timePeriod) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: timePeriod
   real(dp) :: res_
   res_ = 0.0_dp
   if (.not. (.not. associated(LidGroups(j_l)%p))) then
      if (timePeriod == PREVIOUS) then
         res_ = LidGroups(j_l)%p%oldDrainFlow
         return
      else
         res_ = LidGroups(j_l)%p%newDrainFlow
