! lid.c:1442
recursive subroutine lid_addDrainLoads(j_l, c_l, tStep)
   integer(int32), value :: j_l
   real(dp), pointer, intent(in) :: c_l(:)
   real(dp), value :: tStep
   integer(int32) :: isRunoffLoad
   integer(int32) :: p_l
   real(dp) :: r_l
   real(dp) :: w_l
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   logical :: b1_
   isRunoffLoad = 0
   p_l = 0
   r_l = 0.0_dp
   w_l = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   lidGroup_l => LidGroups(j_l)%p
   if (.not. (.not. associated(lidGroup_l))) then
      lidList => lidGroup_l%lidList
      do while (associated(lidList))
         lidUnit => lidList%lidUnit
         b1_ = lidUnit%drainNode >= 0
         if (.not. b1_) then
            b1_ = lidUnit%drainSubcatch == j_l
         end if
         isRunoffLoad = merge(1, 0, b1_)
         if (.not. (lidUnit%toPerv /= 0)) then
            p_l = 0
            do while (p_l < Nobjects(POLLUT_c))
               w_l = (((lidUnit%newDrainFlow * c_l(p_l)) * tStep) * 28.317_dp) * Pollut(p_l)%mcf
               r_l = LidProcs(lidUnit%lidIndex)%drainRmvl(p_l)
               call massbal_updateLoadingTotals(BMP_REMOVAL_LOAD, p_l, r_l * w_l)
               if (isRunoffLoad /= 0) then
                  call massbal_updateLoadingTotals(RUNOFF_LOAD, p_l, w_l * (1.0_dp - r_l))
               end if
               p_l = p_l + 1
            end do
         end if
         lidList => lidList%nextLidUnit
      end do
   end if
end subroutine lid_addDrainLoads

! lid.c:1497
recursive subroutine lid_addDrainRunon(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: w_l
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   i_l = 0
   k_l = 0
   p_l = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   lidGroup_l => LidGroups(j_l)%p
   if (.not. (.not. associated(lidGroup_l))) then
      lidList => lidGroup_l%lidList
      do while (associated(lidList))
         lidUnit => lidList%lidUnit
         i_l = lidUnit%lidIndex
         k_l = lidUnit%drainSubcatch
         if ((k_l >= 0) .and. (k_l /= j_l)) then
            q_l = lidUnit%oldDrainFlow
            call subcatch_addRunonFlow(k_l, q_l)
            p_l = 0
            do while (p_l < Nobjects(POLLUT_c))
               w_l = (q_l * Subcatch(j_l)%oldQual(p_l)) * 28.317_dp
               w_l = w_l * (1.0_dp - LidProcs(i_l)%drainRmvl(p_l))
               Subcatch(k_l)%newQual(p_l) = Subcatch(k_l)%newQual(p_l) + w_l
               p_l = p_l + 1
            end do
         end if
         lidList => lidList%nextLidUnit
      end do
   end if
end subroutine lid_addDrainRunon

! lid.c:1549
recursive subroutine lid_addDrainInflow(j_l, f_l)
   integer(int32), value :: j_l
   real(dp), value :: f_l
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: w_l
   real(dp) :: w1
   real(dp) :: w2
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   i_l = 0
   k_l = 0
   p_l = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   w1 = 0.0_dp
   w2 = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   lidGroup_l => LidGroups(j_l)%p
   if (.not. (.not. associated(lidGroup_l))) then
      lidList => lidGroup_l%lidList
      do while (associated(lidList))
         lidUnit => lidList%lidUnit
         i_l = lidUnit%lidIndex
         k_l = lidUnit%drainNode
         if (k_l >= 0) then
            q_l = ((1.0_dp - f_l) * lidUnit%oldDrainFlow) + (f_l * lidUnit%newDrainFlow)
            Node(k_l)%newLatFlow = Node(k_l)%newLatFlow + q_l
            call massbal_addInflowFlow(WET_WEATHER_INFLOW, q_l)
            p_l = 0
            do while (p_l < Nobjects(POLLUT_c))
               w1 = lidUnit%oldDrainFlow * Subcatch(j_l)%oldQual(p_l)
               w2 = lidUnit%newDrainFlow * Subcatch(j_l)%newQual(p_l)
               w_l = ((1.0_dp - f_l) * w1) + (f_l * w2)
               w_l = w_l * (1.0_dp - LidProcs(i_l)%drainRmvl(p_l))
               Node(k_l)%newQual(p_l) = Node(k_l)%newQual(p_l) + w_l
               call massbal_addInflowQual(WET_WEATHER_INFLOW, p_l, w_l)
               p_l = p_l + 1
            end do
         end if
         lidList => lidList%nextLidUnit
      end do
   end if
end subroutine lid_addDrainInflow

! lid.c:1609
recursive subroutine lid_getRunoff(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   type(LidGroup), pointer :: theLidGroup
   type(TLidList), pointer :: lidList
   type(TLidUnit), pointer :: lidUnit
   real(dp) :: lidArea
   real(dp) :: qImperv
   real(dp) :: qPerv
   real(dp) :: lidInflow
   real(dp), target :: qRunoff
   real(dp), target :: qDrain
   real(dp), target :: qReturn
   logical :: b1_
   nullify(theLidGroup)
   nullify(lidList)
   nullify(lidUnit)
   lidArea = 0.0_dp
   qImperv = 0.0_dp
   qPerv = 0.0_dp
   lidInflow = 0.0_dp
   qRunoff = 0.0_dp
   qDrain = 0.0_dp
   qReturn = 0.0_dp
   theLidGroup => LidGroups(j_l)%p
   if (.not. associated(theLidGroup)) then
      return
   end if
   lidList => theLidGroup%lidList
   if (.not. associated(lidList)) then
      return
   end if
   lid_EvapRate = Evap%rate
   b1_ = Evap%dryOnly /= 0
   if (b1_) then
      b1_ = Subcatch(j_l)%rainfall > 0.0_dp
   end if
   if (b1_) then
      lid_EvapRate = 0.0_dp
   end if
   call findNativeInfil(j_l, tStep)
   if (Subcatch(j_l)%area > Subcatch(j_l)%lidArea) then
      qImperv = getImpervAreaRunoff(j_l)
      qPerv = getPervAreaRunoff(j_l)
   end if
   do while (associated(lidList))
      lidUnit => lidList%lidUnit
      lidArea = lidUnit%area * real(lidUnit%number, dp)
      if (lidArea > 0.0_dp) then
         lidInflow = ((qImperv * lidUnit%fromImperv) + (qPerv * lidUnit%fromPerv)) / lidArea
         VlidIn = VlidIn + ((lidInflow * lidArea) * tStep)
         lidInflow = lidInflow + getRainInflow(j_l, lidUnit)
         if (Subcatch(j_l)%area == Subcatch(j_l)%lidArea) then
            lidInflow = lidInflow + Subcatch(j_l)%runon
         end if
         call evalLidUnit(j_l, lidUnit, lidArea, lidInflow, tStep, qRunoff, qDrain, qReturn)
      end if
      lidList => lidList%nextLidUnit
   end do
   theLidGroup%newDrainFlow = qDrain
   theLidGroup%flowToPerv = qReturn
   VlidOut = qRunoff * tStep
   VlidDrain = qDrain * tStep
   VlidReturn = qReturn * tStep
end subroutine lid_getRunoff

! lid.c:1697
recursive subroutine findNativeInfil(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   real(dp) :: nonLidArea
   logical :: b1_
   logical :: b2_
   nonLidArea = 0.0_dp
   nonLidArea = Subcatch(j_l)%area - Subcatch(j_l)%lidArea
   b1_ = nonLidArea > 0.0_dp
   if (b1_) then
      b1_ = Subcatch(j_l)%fracImperv < 1.0_dp
   end if
   if (b1_) then
      NativeInfil = (Vinfil / nonLidArea) / tStep
   else
      NativeInfil = infil_getInfil(j_l, tStep, Subcatch(j_l)%rainfall, Subcatch(j_l)%runon, getSurfaceDepth(j_l))
   end if
   b2_ = .not. (IgnoreGwater /= 0)
   if (b2_) then
      b2_ = associated(Subcatch(j_l)%groundwater)
   end if
   if (b2_) then
      lid_MaxNativeInfil = Subcatch(j_l)%groundwater%maxInfilVol / tStep
   else
      lid_MaxNativeInfil = 10000000000.0_dp
   end if
end subroutine findNativeInfil

! lid.c:1734
recursive function getRainInflow(j_l, lidUnit) result(res_)
   integer(int32), value :: j_l
   type(TLidUnit), pointer, intent(in) :: lidUnit
   real(dp) :: res_
   type(TLidProc), pointer :: lidProc
   logical :: b1_
   res_ = 0.0_dp
   lidProc => LidProcs(lidUnit%lidIndex)
   b1_ = lidProc%lidType == RAIN_BARREL
   if (b1_) then
      b1_ = lidProc%storage%covered == 1
   end if
   if (b1_) then
      res_ = 0.0_dp
      return
   end if
   res_ = Subcatch(j_l)%rainfall
   return
end function getRainInflow

! lid.c:1751
recursive function getImpervAreaRunoff(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: q_l
   real(dp) :: nonLidArea
   logical :: b1_
   res_ = 0.0_dp
   i_l = 0
   q_l = 0.0_dp
   nonLidArea = 0.0_dp
   i_l = IMPERV0
   do while (i_l <= IMPERV1)
      q_l = q_l + (Subcatch(j_l)%subArea(i_l)%runoff * Subcatch(j_l)%subArea(i_l)%fArea)
      i_l = i_l + 1
   end do
   b1_ = Subcatch(j_l)%subArea(IMPERV0)%routeTo == TO_PERV
   if (b1_) then
      b1_ = Subcatch(j_l)%fracImperv < 1.0_dp
   end if
   if (b1_) then
      q_l = q_l * Subcatch(j_l)%subArea(IMPERV0)%fOutlet
   end if
   nonLidArea = Subcatch(j_l)%area - Subcatch(j_l)%lidArea
   res_ = q_l * nonLidArea
   return
end function getImpervAreaRunoff

! lid.c:1781
recursive function getPervAreaRunoff(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   real(dp) :: q_l
   real(dp) :: nonLidArea
   logical :: b1_
   res_ = 0.0_dp
   q_l = 0.0_dp
   nonLidArea = 0.0_dp
   q_l = Subcatch(j_l)%subArea(PERV)%runoff * Subcatch(j_l)%subArea(PERV)%fArea
   b1_ = Subcatch(j_l)%subArea(PERV)%routeTo == TO_IMPERV
   if (b1_) then
      b1_ = Subcatch(j_l)%fracImperv > 0.0_dp
   end if
   if (b1_) then
      q_l = q_l * Subcatch(j_l)%subArea(PERV)%fOutlet
   end if
   nonLidArea = Subcatch(j_l)%area - Subcatch(j_l)%lidArea
   res_ = q_l * nonLidArea
   return
end function getPervAreaRunoff

! lid.c:1807
recursive subroutine evalLidUnit(j_l, lidUnit, lidArea, lidInflow, tStep, qRunoff, qDrain, qReturn)
   integer(int32), value :: j_l
   type(TLidUnit), pointer, intent(in) :: lidUnit
   real(dp), value :: lidArea
   real(dp), value :: lidInflow
   real(dp), value :: tStep
   real(dp), intent(inout), target :: qRunoff
   real(dp), intent(inout), target :: qDrain
   real(dp), intent(inout), target :: qReturn
   type(TLidProc), pointer :: lidProc
   real(dp) :: lidRunoff
   real(dp), target :: lidEvap
   real(dp), target :: lidInfil
   real(dp), target :: lidDrain
   logical :: b1_
   logical :: b2_
   nullify(lidProc)
   lidRunoff = 0.0_dp
   lidEvap = 0.0_dp
   lidInfil = 0.0_dp
   lidDrain = 0.0_dp
   lidProc => LidProcs(lidUnit%lidIndex)
   lidEvap = 0.0_dp
   lidInfil = 0.0_dp
   lidRunoff = lidproc_getOutflow(lidUnit, lidProc, lidInflow, lid_EvapRate, NativeInfil, lid_MaxNativeInfil, tStep, lidEvap, lidInfil, lidDrain) * lidArea
   lidDrain = lidDrain * lidArea
   b1_ = lidUnit%toPerv /= 0
   if (b1_) then
      b1_ = Subcatch(j_l)%area > Subcatch(j_l)%lidArea
   end if
   if (b1_) then
      qReturn = qReturn + lidRunoff
      lidRunoff = 0.0_dp
      b2_ = lidUnit%drainNode == Subcatch(j_l)%outNode
      if (b2_) then
         b2_ = lidUnit%drainSubcatch == Subcatch(j_l)%outSubcatch
      end if
      if (b2_) then
         qReturn = qReturn + lidDrain
         lidDrain = 0.0_dp
      end if
   end if
   if (lidUnit%drainNode >= 0) then
      call massbal_updateRunoffTotals(RUNOFF_DRAINS, lidDrain * tStep)
   end if
   lidUnit%newDrainFlow = lidDrain
   Vevap = Vevap + ((lidEvap * tStep) * lidArea)
   VlidInfil = VlidInfil + ((lidInfil * tStep) * lidArea)
   if (isLidPervious(lidUnit%lidIndex) /= 0) then
      Vpevap = Vpevap + ((lidEvap * tStep) * lidArea)
   end if
   if (Subcatch(j_l)%rainfall > 2.31481e-08_dp) then
      lidUnit%dryTime = 0.0_dp
   else
      lidUnit%dryTime = lidUnit%dryTime + tStep
   end if
   call lidproc_saveResults(lidUnit, UCF(RAINFALL), UCF(RAINDEPTH))
   qRunoff = qRunoff + lidRunoff
   qDrain = qDrain + lidDrain
end subroutine evalLidUnit

! lid.c:1890
recursive subroutine lid_writeWaterBalance()
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp) :: ucf_l
   real(dp) :: inflow
   real(dp) :: outflow
   real(dp) :: err_l
   type(TLidUnit), pointer :: lidUnit
   type(TLidList), pointer :: lidList
   type(LidGroup), pointer :: lidGroup_l
   logical :: b1_
   j_l = 0
   k_l = 0
   ucf_l = UCF(RAINDEPTH)
   inflow = 0.0_dp
   outflow = 0.0_dp
   err_l = 0.0_dp
   nullify(lidUnit)
   nullify(lidList)
   nullify(lidGroup_l)
   j_l = 0
   do while (j_l < GroupCount)
      if (associated(LidGroups(j_l)%p)) then
         k_l = k_l + 1
      end if
      j_l = j_l + 1
   end do
   if (k_l == 0) then
      return
   end if
   call c_fprintf(Frpt%file, lit_291)
   call c_fprintf(Frpt%file, lit_292)
   if (UnitSystem == US) then
      call c_fprintf(Frpt%file, lit_293)
   else
      call c_fprintf(Frpt%file, lit_294)
   end if
   call c_fprintf(Frpt%file, lit_295)
   j_l = 0
   do while (j_l < GroupCount)
      lidGroup_l => LidGroups(j_l)%p
      b1_ = .not. associated(lidGroup_l)
      if (.not. b1_) then
         b1_ = Subcatch(j_l)%lidArea == 0.0_dp
      end if
      if (b1_) then
         goto 101
      end if
      lidList => lidGroup_l%lidList
      do while (associated(lidList))
         lidUnit => lidList%lidUnit
         k_l = lidUnit%lidIndex
         call c_fprintf(Frpt%file, lit_296, Subcatch(j_l)%ID, LidProcs(k_l)%ID)
         call c_fprintf(Frpt%file, lit_297, lidUnit%waterBalance%inflow * ucf_l, lidUnit%waterBalance%evap * ucf_l, lidUnit%waterBalance%infil * ucf_l, lidUnit%waterBalance%surfFlow * ucf_l, lidUnit%waterBalance%drainFlow * ucf_l, lidUnit%waterBalance%initVol * ucf_l, lidUnit%waterBalance%finalVol * ucf_l)
         inflow = lidUnit%waterBalance%initVol + lidUnit%waterBalance%inflow
         outflow = (((lidUnit%waterBalance%finalVol + lidUnit%waterBalance%evap) + lidUnit%waterBalance%infil) + lidUnit%waterBalance%surfFlow) + lidUnit%waterBalance%drainFlow
         if (inflow > 0.0_dp) then
            err_l = (inflow - outflow) / inflow
         else
            err_l = 1.0_dp
         end if
         call c_fprintf(Frpt%file, lit_298, err_l * 100.0_dp)
         lidList => lidList%nextLidUnit
      end do
      101 continue
      j_l = j_l + 1
   end do
end subroutine lid_writeWaterBalance

