! lidproc.c:197
recursive function lidproc_getOutflow(lidUnit, lidProc, inflow, evap_l, infil_l, maxInfil, tStep, lidEvap, lidInfil, lidDrain) result(res_)
   type(TLidUnit), pointer, intent(in) :: lidUnit
   type(TLidProc), pointer, intent(in) :: lidProc
   real(dp), value :: inflow
   real(dp), value :: evap_l
   real(dp), value :: infil_l
   real(dp), value :: maxInfil
   real(dp), value :: tStep
   real(dp), intent(inout), target :: lidEvap
   real(dp), intent(inout), target :: lidInfil
   real(dp), intent(inout), target :: lidDrain
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp), target :: x_l(0:3)
   real(dp), target :: xOld_l(0:3)
   real(dp), target :: xPrev(0:3)
   real(dp), target :: xMin(0:3)
   real(dp), target :: xMax(0:3)
   real(dp), target :: fOld(0:3)
   real(dp), target :: f_l(0:3)
   real(dp), target :: xTol_l(0:3)
   real(dp) :: omega_l
   procedure(fp2), pointer :: fluxRates
   logical :: b1_
   res_ = 0.0_dp
   i_l = 0
   x_l = 0.0_dp
   xOld_l = 0.0_dp
   xPrev = 0.0_dp
   xMin = 0.0_dp
   xMax = 0.0_dp
   fOld = 0.0_dp
   f_l = 0.0_dp
   xTol_l = 0.0_dp
   xTol_l(0:3) = [0.00328_dp, 0.00328_dp, 0.00328_dp, 0.00328_dp]
   omega_l = 0.0_dp
   nullify(fluxRates)
   theLidProc => lidProc
   theLidUnit => lidUnit
   lidproc_EvapRate = evap_l
   lidproc_MaxNativeInfil = maxInfil
   lidproc_Tstep = tStep
   x_l(SURF) = theLidUnit%surfaceDepth
   x_l(SOIL) = theLidUnit%soilMoisture
   x_l(STOR) = theLidUnit%storageDepth
   x_l(PAVE) = theLidUnit%paveDepth
   SurfaceVolume = 0.0_dp
   PaveVolume = 0.0_dp
   SoilVolume = 0.0_dp
   StorageVolume = 0.0_dp
   SurfaceInflow = inflow
   SurfaceInfil = 0.0_dp
   SurfaceEvap = 0.0_dp
   SurfaceOutflow = 0.0_dp
   PaveEvap = 0.0_dp
   PavePerc = 0.0_dp
   SoilEvap = 0.0_dp
   SoilPerc = 0.0_dp
   StorageInflow = 0.0_dp
   StorageExfil = 0.0_dp
   StorageEvap = 0.0_dp
   StorageDrain = 0.0_dp
   i_l = 0
   do while (i_l < 4)
      f_l(i_l) = 0.0_dp
      fOld(i_l) = theLidUnit%oldFluxRates(i_l)
      xMin(i_l) = 0.0_dp
      xMax(i_l) = 10000000000.0_dp
      Xold(i_l) = x_l(i_l)
      i_l = i_l + 1
   end do
   if (theLidProc%lidType == POROUS_PAVEMENT) then
      SurfaceInfil = 0.0_dp
   else if (theLidUnit%soilInfil%Ks > 0.0_dp) then
      SurfaceInfil = grnampt_getInfil(theLidUnit%soilInfil, lidproc_Tstep, SurfaceInflow, theLidUnit%surfaceDepth, MOD_GREEN_AMPT)
   else
      SurfaceInfil = infil_l
   end if
   if (theLidProc%soil%thickness > 0.0_dp) then
      xMin(SOIL) = theLidProc%soil%wiltPoint
      xMax(SOIL) = theLidProc%soil%porosity
   end if
   if (theLidProc%pavement%thickness > 0.0_dp) then
      xMax(PAVE) = theLidProc%pavement%thickness
   end if
   if (theLidProc%storage%thickness > 0.0_dp) then
      xMax(STOR) = theLidProc%storage%thickness
   end if
   if (theLidProc%lidType == GREEN_ROOF) then
      xMax(STOR) = theLidProc%drainMat%thickness
   end if
   select case (theLidProc%lidType)
   case (0, 1)
      fluxRates => biocellFluxRates
   case (2)
      fluxRates => greenRoofFluxRates
   case (3)
      fluxRates => trenchFluxRates
   case (4)
      fluxRates => pavementFluxRates
   case (5)
      fluxRates => barrelFluxRates
   case (7)
      fluxRates => roofFluxRates
   case (6)
      fluxRates => swaleFluxRates
      omega_l = 0.5_dp
   case default
      res_ = 0.0_dp
      return
   end select
   i_l = modpuls_solve(4, x_l, xOld_l, xPrev, xMin, xMax, xTol_l, fOld, f_l, tStep, omega_l, fluxRates)
   b1_ = theLidProc%surface%canOverflow /= 0
   if (.not. b1_) then
      b1_ = theLidUnit%fullWidth == 0.0_dp
   end if
   if (b1_) then
      SurfaceOutflow = SurfaceOutflow + getSurfaceOverflowRate(x_l(SURF))
   end if
   theLidUnit%surfaceDepth = x_l(SURF)
   theLidUnit%paveDepth = x_l(PAVE)
   theLidUnit%soilMoisture = x_l(SOIL)
   theLidUnit%storageDepth = x_l(STOR)
   i_l = 0
   do while (i_l < 4)
      theLidUnit%oldFluxRates(i_l) = f_l(i_l)
      i_l = i_l + 1
   end do
   lidEvap = ((SurfaceEvap + PaveEvap) + SoilEvap) + StorageEvap
   lidInfil = StorageExfil
   lidDrain = StorageDrain
   res_ = SurfaceOutflow
   return
end function lidproc_getOutflow

! lidproc.c:360
recursive subroutine lidproc_saveResults(lidUnit, ucfRainfall, ucfRainDepth)
   type(TLidUnit), pointer, intent(in) :: lidUnit
   real(dp), value :: ucfRainfall
   real(dp), value :: ucfRainDepth
   real(dp) :: ucf_l
   real(dp) :: totalEvap
   real(dp) :: totalVolume
   real(dp), target :: rptVars(0:11)
   integer(int32) :: isDry
   integer(int8), target :: timeStamp(0:21)
   real(dp) :: elapsedHrs
   logical :: b1_
   integer(int32) :: dum2_
   ucf_l = 0.0_dp
   totalEvap = 0.0_dp
   totalVolume = 0.0_dp
   rptVars = 0.0_dp
   isDry = 0
   timeStamp = 0_int8
   elapsedHrs = 0.0_dp
   totalEvap = ((SurfaceEvap + PaveEvap) + SoilEvap) + StorageEvap
   totalVolume = ((SurfaceVolume + PaveVolume) + SoilVolume) + StorageVolume
   call updateWaterBalance(theLidUnit, SurfaceInflow, totalEvap, StorageExfil, SurfaceOutflow, StorageDrain, totalVolume)
   if (((((SurfaceInflow < 2.3e-08_dp) .and. (SurfaceOutflow < 2.3e-08_dp)) .and. (StorageDrain < 2.3e-08_dp)) .and. (StorageExfil < 2.3e-08_dp)) .and. (totalEvap < 2.3e-08_dp)) then
      isDry = 1
   end if
   if (.not. (isDry /= 0)) then
      HasWetLids = 1
   end if
   if (associated(lidUnit%rptFile)) then
      ucf_l = ucfRainfall
      rptVars(SURF_INFLOW) = SurfaceInflow * ucf_l
      rptVars(TOTAL_EVAP) = totalEvap * ucf_l
      rptVars(SURF_INFIL) = SurfaceInfil * ucf_l
      rptVars(PAVE_PERC) = PavePerc * ucf_l
      rptVars(SOIL_PERC) = SoilPerc * ucf_l
      rptVars(STOR_EXFIL) = StorageExfil * ucf_l
      rptVars(SURF_OUTFLOW) = SurfaceOutflow * ucf_l
      rptVars(STOR_DRAIN) = StorageDrain * ucf_l
      ucf_l = ucfRainDepth
      rptVars(SURF_DEPTH) = theLidUnit%surfaceDepth * ucf_l
      rptVars(PAVE_DEPTH) = theLidUnit%paveDepth * ucf_l
      rptVars(SOIL_MOIST) = theLidUnit%soilMoisture
      rptVars(STOR_DEPTH) = theLidUnit%storageDepth * ucf_l
      b1_ = .not. (isDry /= 0)
      if (b1_) then
         b1_ = theLidUnit%rptFile%wasDry > 1
      end if
      if (b1_) then
         call c_fprintf(theLidUnit%rptFile%file, lit_169, cview(theLidUnit%rptFile%results))
      end if
      elapsedHrs = (NewRunoffTime / 1000.0_dp) / 3600.0_dp
      call datetime_getTimeStamp(1, getDateTime(NewRunoffTime), 21, cview(timeStamp))
      dum2_ = c_snprintf(cview(theLidUnit%rptFile%results), 256_int64, lit_304, cview(timeStamp), elapsedHrs, rptVars(0), rptVars(1), rptVars(2), rptVars(3), rptVars(4), rptVars(5), rptVars(6), rptVars(7), rptVars(8), rptVars(9), rptVars(10), rptVars(11))
      if (isDry /= 0) then
         if (theLidUnit%rptFile%wasDry == 0) then
            call c_fprintf(theLidUnit%rptFile%file, lit_169, cview(theLidUnit%rptFile%results))
         end if
         theLidUnit%rptFile%wasDry = theLidUnit%rptFile%wasDry + 1
      else
         call c_fprintf(theLidUnit%rptFile%file, lit_169, cview(theLidUnit%rptFile%results))
         theLidUnit%rptFile%wasDry = 0
      end if
   end if
end subroutine lidproc_saveResults

! lidproc.c:469
recursive subroutine roofFluxRates(x_l, f_l)
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: f_l(:)
   real(dp), target :: surfaceDepth
   real(dp) :: dum1_
   real(dp) :: v2_
   surfaceDepth = x_l(SURF)
   call lidproc_getEvapRates(surfaceDepth, 0.0_dp, 0.0_dp, 0.0_dp, 1.0_dp)
   SurfaceVolume = surfaceDepth
   SurfaceInfil = 0.0_dp
   if (theLidProc%surface%alpha > 0.0_dp) then
      SurfaceOutflow = getSurfaceOutflowRate(surfaceDepth)
   else
      dum1_ = getSurfaceOverflowRate(surfaceDepth)
   end if
   if ((theLidProc%drain%coeff / UCF(RAINFALL)) <= (SurfaceOutflow)) then
      v2_ = theLidProc%drain%coeff / UCF(RAINFALL)
   else
      v2_ = SurfaceOutflow
   end if
   StorageDrain = v2_
   SurfaceOutflow = SurfaceOutflow - StorageDrain
   f_l(SURF) = ((SurfaceInflow - SurfaceEvap) - StorageDrain) - SurfaceOutflow
end subroutine roofFluxRates

! lidproc.c:491
recursive subroutine greenRoofFluxRates(x_l, f_l)
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: f_l(:)
   real(dp) :: surfaceDepth
   real(dp) :: soilTheta
   real(dp) :: storageDepth
   real(dp) :: availVolume
   real(dp) :: maxRate
   real(dp) :: soilThickness
   real(dp) :: storageThickness
   real(dp) :: soilPorosity
   real(dp) :: storageVoidFrac
   real(dp) :: soilFieldCap
   real(dp) :: soilWiltPoint
   surfaceDepth = 0.0_dp
   soilTheta = 0.0_dp
   storageDepth = 0.0_dp
   availVolume = 0.0_dp
   maxRate = 0.0_dp
   soilThickness = theLidProc%soil%thickness
   storageThickness = theLidProc%storage%thickness
   soilPorosity = theLidProc%soil%porosity
   storageVoidFrac = theLidProc%storage%voidFrac
   soilFieldCap = theLidProc%soil%fieldCap
   soilWiltPoint = theLidProc%soil%wiltPoint
   surfaceDepth = x_l(SURF)
   soilTheta = x_l(SOIL)
   storageDepth = x_l(STOR)
   SurfaceVolume = surfaceDepth * theLidProc%surface%voidFrac
   SoilVolume = soilTheta * soilThickness
   StorageVolume = storageDepth * storageVoidFrac
   availVolume = SoilVolume - (soilWiltPoint * soilThickness)
   call lidproc_getEvapRates(SurfaceVolume, 0.0_dp, availVolume, StorageVolume, 1.0_dp)
   if (soilTheta >= soilPorosity) then
      StorageEvap = 0.0_dp
   end if
   SoilPerc = getSoilPercRate(soilTheta)
   availVolume = (soilTheta - soilFieldCap) * soilThickness
   maxRate = ((merge(availVolume, 0.0_dp, (availVolume) >= (0.0_dp))) / lidproc_Tstep) - SoilEvap
   SoilPerc = merge(SoilPerc, maxRate, (SoilPerc) <= (maxRate))
   SoilPerc = merge(SoilPerc, 0.0_dp, (SoilPerc) >= (0.0_dp))
   StorageExfil = 0.0_dp
   StorageDrain = getDrainMatOutflow(storageDepth)
   if ((soilTheta >= soilPorosity) .and. (storageDepth >= storageThickness)) then
      maxRate = merge(SoilPerc, StorageDrain, (SoilPerc) <= (StorageDrain))
      SoilPerc = maxRate
      StorageDrain = maxRate
      SurfaceInfil = merge(SurfaceInfil, maxRate, (SurfaceInfil) <= (maxRate))
   else
      maxRate = ((storageDepth * storageVoidFrac) / lidproc_Tstep) - StorageEvap
      if (storageDepth >= storageThickness) then
         maxRate = maxRate + SoilPerc
      end if
      maxRate = merge(maxRate, 0.0_dp, (maxRate) >= (0.0_dp))
      StorageDrain = merge(StorageDrain, maxRate, (StorageDrain) <= (maxRate))
      maxRate = ((((storageThickness - storageDepth) * storageVoidFrac) / lidproc_Tstep) + StorageDrain) + StorageEvap
      SoilPerc = merge(SoilPerc, maxRate, (SoilPerc) <= (maxRate))
      maxRate = ((((soilPorosity - soilTheta) * soilThickness) / lidproc_Tstep) + SoilPerc) + SoilEvap
      SurfaceInfil = merge(SurfaceInfil, maxRate, (SurfaceInfil) <= (maxRate))
   end if
   SurfaceOutflow = getSurfaceOutflowRate(surfaceDepth)
   f_l(SURF) = (((SurfaceInflow - SurfaceEvap) - SurfaceInfil) - SurfaceOutflow) / theLidProc%surface%voidFrac
   f_l(SOIL) = ((SurfaceInfil - SoilEvap) - SoilPerc) / theLidProc%soil%thickness
   f_l(STOR) = ((SoilPerc - StorageEvap) - StorageDrain) / theLidProc%storage%voidFrac
end subroutine greenRoofFluxRates

! lidproc.c:589
recursive subroutine biocellFluxRates(x_l, f_l)
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: f_l(:)
   real(dp) :: surfaceDepth
   real(dp) :: soilTheta
   real(dp) :: storageDepth
   real(dp) :: availVolume
   real(dp) :: maxRate
   real(dp) :: soilThickness
   real(dp) :: soilPorosity
   real(dp) :: soilFieldCap
   real(dp) :: soilWiltPoint
   real(dp) :: storageThickness
   real(dp) :: storageVoidFrac
   surfaceDepth = 0.0_dp
   soilTheta = 0.0_dp
   storageDepth = 0.0_dp
   availVolume = 0.0_dp
   maxRate = 0.0_dp
   soilThickness = theLidProc%soil%thickness
   soilPorosity = theLidProc%soil%porosity
   soilFieldCap = theLidProc%soil%fieldCap
   soilWiltPoint = theLidProc%soil%wiltPoint
   storageThickness = theLidProc%storage%thickness
   storageVoidFrac = theLidProc%storage%voidFrac
   surfaceDepth = x_l(SURF)
   soilTheta = x_l(SOIL)
   storageDepth = x_l(STOR)
   SurfaceVolume = surfaceDepth * theLidProc%surface%voidFrac
   SoilVolume = soilTheta * soilThickness
   StorageVolume = storageDepth * storageVoidFrac
   availVolume = SoilVolume - (soilWiltPoint * soilThickness)
   call lidproc_getEvapRates(SurfaceVolume, 0.0_dp, availVolume, StorageVolume, 1.0_dp)
   if (soilTheta >= soilPorosity) then
      StorageEvap = 0.0_dp
   end if
   SoilPerc = getSoilPercRate(soilTheta)
   availVolume = (soilTheta - soilFieldCap) * soilThickness
   maxRate = ((merge(availVolume, 0.0_dp, (availVolume) >= (0.0_dp))) / lidproc_Tstep) - SoilEvap
   SoilPerc = merge(SoilPerc, maxRate, (SoilPerc) <= (maxRate))
   SoilPerc = merge(SoilPerc, 0.0_dp, (SoilPerc) >= (0.0_dp))
   StorageExfil = getStorageExfilRate()
   StorageDrain = 0.0_dp
   if (theLidProc%drain%coeff > 0.0_dp) then
      StorageDrain = getStorageDrainRate(storageDepth, soilTheta, 0.0_dp, surfaceDepth)
   end if
   if (storageThickness == 0.0_dp) then
      StorageEvap = 0.0_dp
      maxRate = merge(SoilPerc, StorageExfil, (SoilPerc) <= (StorageExfil))
      SoilPerc = maxRate
      StorageExfil = maxRate
      maxRate = ((((soilPorosity - soilTheta) * soilThickness) / lidproc_Tstep) + SoilPerc) + SoilEvap
      SurfaceInfil = merge(SurfaceInfil, maxRate, (SurfaceInfil) <= (maxRate))
   else
      if ((soilTheta >= soilPorosity) .and. (storageDepth >= storageThickness)) then
         maxRate = StorageExfil + StorageDrain
         if (SoilPerc < maxRate) then
            maxRate = SoilPerc
            if (maxRate > StorageExfil) then
               StorageDrain = maxRate - StorageExfil
            else
               StorageExfil = maxRate
               StorageDrain = 0.0_dp
            end if
         else
            SoilPerc = maxRate
         end if
         SurfaceInfil = merge(SurfaceInfil, maxRate, (SurfaceInfil) <= (maxRate))
      else
         maxRate = (SoilPerc - StorageEvap) + ((storageDepth * storageVoidFrac) / lidproc_Tstep)
         StorageExfil = merge(StorageExfil, maxRate, (StorageExfil) <= (maxRate))
         StorageExfil = merge(StorageExfil, 0.0_dp, (StorageExfil) >= (0.0_dp))
         if (StorageDrain > 0.0_dp) then
            maxRate = (-StorageExfil) - StorageEvap
            if (storageDepth >= storageThickness) then
               maxRate = maxRate + SoilPerc
            end if
            if (theLidProc%drain%offset <= storageDepth) then
               maxRate = maxRate + (((storageDepth - theLidProc%drain%offset) * storageVoidFrac) / lidproc_Tstep)
            end if
            maxRate = merge(maxRate, 0.0_dp, (maxRate) >= (0.0_dp))
            StorageDrain = merge(StorageDrain, maxRate, (StorageDrain) <= (maxRate))
         end if
         maxRate = ((StorageExfil + StorageDrain) + StorageEvap) + (((storageThickness - storageDepth) * storageVoidFrac) / lidproc_Tstep)
         SoilPerc = merge(SoilPerc, maxRate, (SoilPerc) <= (maxRate))
         maxRate = ((((soilPorosity - soilTheta) * soilThickness) / lidproc_Tstep) + SoilPerc) + SoilEvap
         SurfaceInfil = merge(SurfaceInfil, maxRate, (SurfaceInfil) <= (maxRate))
      end if
   end if
   SurfaceOutflow = getSurfaceOutflowRate(surfaceDepth)
   f_l(SURF) = (((SurfaceInflow - SurfaceEvap) - SurfaceInfil) - SurfaceOutflow) / theLidProc%surface%voidFrac
   f_l(SOIL) = ((SurfaceInfil - SoilEvap) - SoilPerc) / theLidProc%soil%thickness
   if (storageThickness == 0.0_dp) then
      f_l(STOR) = 0.0_dp
   else
      f_l(STOR) = (((SoilPerc - StorageEvap) - StorageExfil) - StorageDrain) / theLidProc%storage%voidFrac
   end if
end subroutine biocellFluxRates

! lidproc.c:735
recursive subroutine trenchFluxRates(x_l, f_l)
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: f_l(:)
   real(dp) :: surfaceDepth
   real(dp) :: storageDepth
   real(dp) :: availVolume
   real(dp) :: maxRate
   real(dp) :: storageThickness
   real(dp) :: storageVoidFrac
   surfaceDepth = 0.0_dp
   storageDepth = 0.0_dp
   availVolume = 0.0_dp
   maxRate = 0.0_dp
   storageThickness = theLidProc%storage%thickness
   storageVoidFrac = theLidProc%storage%voidFrac
   surfaceDepth = x_l(SURF)
   storageDepth = x_l(STOR)
   SurfaceVolume = surfaceDepth * theLidProc%surface%voidFrac
   SoilVolume = 0.0_dp
   StorageVolume = storageDepth * storageVoidFrac
   availVolume = (storageThickness - storageDepth) * storageVoidFrac
   call lidproc_getEvapRates(SurfaceVolume, 0.0_dp, 0.0_dp, StorageVolume, 1.0_dp)
   if (surfaceDepth > 0.0_dp) then
      StorageEvap = 0.0_dp
   end if
   StorageInflow = SurfaceInflow + (SurfaceVolume / lidproc_Tstep)
   StorageExfil = getStorageExfilRate()
   StorageDrain = 0.0_dp
   if (theLidProc%drain%coeff > 0.0_dp) then
      StorageDrain = getStorageDrainRate(storageDepth, 0.0_dp, 0.0_dp, surfaceDepth)
   end if
   maxRate = (StorageInflow - StorageEvap) + ((storageDepth * storageVoidFrac) / lidproc_Tstep)
   StorageExfil = merge(StorageExfil, maxRate, (StorageExfil) <= (maxRate))
   StorageExfil = merge(StorageExfil, 0.0_dp, (StorageExfil) >= (0.0_dp))
   if (StorageDrain > 0.0_dp) then
      maxRate = (-StorageExfil) - StorageEvap
      if (storageDepth >= storageThickness) then
         maxRate = maxRate + StorageInflow
      end if
      if (theLidProc%drain%offset <= storageDepth) then
         maxRate = maxRate + (((storageDepth - theLidProc%drain%offset) * storageVoidFrac) / lidproc_Tstep)
      end if
      maxRate = merge(maxRate, 0.0_dp, (maxRate) >= (0.0_dp))
      StorageDrain = merge(StorageDrain, maxRate, (StorageDrain) <= (maxRate))
   end if
   maxRate = (((((storageThickness - storageDepth) * storageVoidFrac) / lidproc_Tstep) + StorageExfil) + StorageEvap) + StorageDrain
   StorageInflow = merge(StorageInflow, maxRate, (StorageInflow) <= (maxRate))
   SurfaceInfil = StorageInflow
   SurfaceOutflow = getSurfaceOutflowRate(surfaceDepth)
   f_l(SURF) = (((SurfaceInflow - SurfaceEvap) - StorageInflow) - SurfaceOutflow) / theLidProc%surface%voidFrac
   f_l(STOR) = (((StorageInflow - StorageEvap) - StorageExfil) - StorageDrain) / theLidProc%storage%voidFrac
   f_l(SOIL) = 0.0_dp
end subroutine trenchFluxRates

! lidproc.c:823
recursive subroutine pavementFluxRates(x_l, f_l)
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: f_l(:)
   real(dp) :: surfaceDepth
   real(dp) :: paveDepth
   real(dp) :: soilTheta
   real(dp) :: storageDepth
   real(dp) :: pervFrac
   real(dp) :: storageInflow_l
   real(dp) :: availVolume
   real(dp) :: maxRate
   real(dp) :: paveVoidFrac
   real(dp) :: paveThickness
   real(dp) :: soilThickness
   real(dp) :: soilPorosity
   real(dp) :: soilFieldCap
   real(dp) :: soilWiltPoint
   real(dp) :: storageThickness
   real(dp) :: storageVoidFrac
   surfaceDepth = 0.0_dp
   paveDepth = 0.0_dp
   soilTheta = 0.0_dp
   storageDepth = 0.0_dp
   pervFrac = 1.0_dp - theLidProc%pavement%impervFrac
   storageInflow_l = 0.0_dp
   availVolume = 0.0_dp
   maxRate = 0.0_dp
   paveVoidFrac = theLidProc%pavement%voidFrac * pervFrac
   paveThickness = theLidProc%pavement%thickness
   soilThickness = theLidProc%soil%thickness
   soilPorosity = theLidProc%soil%porosity
   soilFieldCap = theLidProc%soil%fieldCap
   soilWiltPoint = theLidProc%soil%wiltPoint
   storageThickness = theLidProc%storage%thickness
   storageVoidFrac = theLidProc%storage%voidFrac
   surfaceDepth = x_l(SURF)
   paveDepth = x_l(PAVE)
   soilTheta = x_l(SOIL)
   storageDepth = x_l(STOR)
   SurfaceVolume = surfaceDepth * theLidProc%surface%voidFrac
   PaveVolume = paveDepth * paveVoidFrac
   SoilVolume = soilTheta * soilThickness
   StorageVolume = storageDepth * storageVoidFrac
   availVolume = SoilVolume - (soilWiltPoint * soilThickness)
   call lidproc_getEvapRates(SurfaceVolume, PaveVolume, availVolume, StorageVolume, pervFrac)
   if ((paveDepth >= paveThickness) .or. ((soilThickness > 0.0_dp) .and. (soilTheta >= soilPorosity))) then
      StorageEvap = 0.0_dp
   end if
   SurfaceInfil = SurfaceInflow + (SurfaceVolume / lidproc_Tstep)
   PavePerc = getPavementPermRate() * pervFrac
   SurfaceInfil = merge(SurfaceInfil, PavePerc, (SurfaceInfil) <= (PavePerc))
   maxRate = ((PaveVolume / lidproc_Tstep) + SurfaceInfil) - PaveEvap
   maxRate = merge(maxRate, 0.0_dp, (maxRate) >= (0.0_dp))
   PavePerc = merge(PavePerc, maxRate, (PavePerc) <= (maxRate))
   if (soilThickness > 0.0_dp) then
      SoilPerc = getSoilPercRate(soilTheta)
      availVolume = (soilTheta - soilFieldCap) * soilThickness
      maxRate = ((merge(availVolume, 0.0_dp, (availVolume) >= (0.0_dp))) / lidproc_Tstep) - SoilEvap
      SoilPerc = merge(SoilPerc, maxRate, (SoilPerc) <= (maxRate))
      SoilPerc = merge(SoilPerc, 0.0_dp, (SoilPerc) >= (0.0_dp))
   else
      SoilPerc = PavePerc
   end if
   StorageExfil = getStorageExfilRate()
   StorageDrain = 0.0_dp
   if (theLidProc%drain%coeff > 0.0_dp) then
      StorageDrain = getStorageDrainRate(storageDepth, soilTheta, paveDepth, surfaceDepth)
   end if
   if (((soilThickness == 0.0_dp) .and. (storageDepth >= storageThickness)) .and. (paveDepth >= paveThickness)) then
      maxRate = (StorageEvap + StorageDrain) + StorageExfil
      if (PavePerc > maxRate) then
         PavePerc = maxRate
      else
         StorageExfil = merge(StorageExfil, PavePerc, (StorageExfil) <= (PavePerc))
         StorageDrain = PavePerc - StorageExfil
      end if
      SoilPerc = PavePerc
      SurfaceInfil = merge(SurfaceInfil, PavePerc, (SurfaceInfil) <= (PavePerc))
   else if ((((soilThickness > 0.0_dp) .and. (storageDepth >= storageThickness)) .and. (soilTheta >= soilPorosity)) .and. (paveDepth >= paveThickness)) then
      maxRate = StorageExfil + StorageDrain
      if (SoilPerc < maxRate) then
         maxRate = SoilPerc
      else
         maxRate = merge(maxRate, PavePerc, (maxRate) <= (PavePerc))
      end if
      if (maxRate > StorageExfil) then
         StorageDrain = maxRate - StorageExfil
      else
         StorageExfil = maxRate
         StorageDrain = 0.0_dp
      end if
      SoilPerc = maxRate
      PavePerc = maxRate
      SurfaceInfil = merge(SurfaceInfil, PavePerc, (SurfaceInfil) <= (PavePerc))
   else if (((soilThickness > 0.0_dp) .and. (storageDepth >= storageThickness)) .and. (soilTheta >= soilPorosity)) then
      maxRate = StorageDrain + StorageExfil
      if (SoilPerc > maxRate) then
         SoilPerc = maxRate
      else
         StorageExfil = merge(StorageExfil, SoilPerc, (StorageExfil) <= (SoilPerc))
         StorageDrain = SoilPerc - StorageExfil
      end if
      PavePerc = merge(PavePerc, SoilPerc, (PavePerc) <= (SoilPerc))
      availVolume = (paveThickness - paveDepth) * paveVoidFrac
      maxRate = ((availVolume / lidproc_Tstep) + PavePerc) + PaveEvap
      SurfaceInfil = merge(SurfaceInfil, maxRate, (SurfaceInfil) <= (maxRate))
   else if (((soilThickness > 0.0_dp) .and. (paveDepth >= paveThickness)) .and. (soilTheta >= soilPorosity)) then
      PavePerc = merge(PavePerc, SoilPerc, (PavePerc) <= (SoilPerc))
      SoilPerc = PavePerc
      SurfaceInfil = merge(SurfaceInfil, PavePerc, (SurfaceInfil) <= (PavePerc))
      maxRate = merge(((StorageVolume / lidproc_Tstep) + SoilPerc) - StorageEvap, 0.0_dp, (((StorageVolume / lidproc_Tstep) + SoilPerc) - StorageEvap) >= (0.0_dp))
      StorageExfil = merge(StorageExfil, maxRate, (StorageExfil) <= (maxRate))
   else
      maxRate = (SoilPerc - StorageEvap) + (StorageVolume / lidproc_Tstep)
      maxRate = merge(0.0_dp, maxRate, (0.0_dp) >= (maxRate))
      StorageExfil = merge(StorageExfil, maxRate, (StorageExfil) <= (maxRate))
      if (StorageDrain > 0.0_dp) then
         maxRate = (-StorageExfil) - StorageEvap
         if (storageDepth >= storageThickness) then
            maxRate = maxRate + SoilPerc
         end if
         if (theLidProc%drain%offset <= storageDepth) then
            maxRate = maxRate + (((storageDepth - theLidProc%drain%offset) * storageVoidFrac) / lidproc_Tstep)
         end if
         maxRate = merge(maxRate, 0.0_dp, (maxRate) >= (0.0_dp))
         StorageDrain = merge(StorageDrain, maxRate, (StorageDrain) <= (maxRate))
      end if
      availVolume = (storageThickness - storageDepth) * storageVoidFrac
      maxRate = (((availVolume / lidproc_Tstep) + StorageEvap) + StorageDrain) + StorageExfil
      maxRate = merge(maxRate, 0.0_dp, (maxRate) >= (0.0_dp))
      if (soilThickness > 0.0_dp) then
         SoilPerc = merge(SoilPerc, maxRate, (SoilPerc) <= (maxRate))
         maxRate = (((soilPorosity - soilTheta) * soilThickness) / lidproc_Tstep) + SoilPerc
      end if
      PavePerc = merge(PavePerc, maxRate, (PavePerc) <= (maxRate))
      availVolume = (paveThickness - paveDepth) * paveVoidFrac
      maxRate = ((availVolume / lidproc_Tstep) + PavePerc) + PaveEvap
      SurfaceInfil = merge(SurfaceInfil, maxRate, (SurfaceInfil) <= (maxRate))
   end if
   SurfaceOutflow = getSurfaceOutflowRate(surfaceDepth)
   f_l(SURF) = ((SurfaceInflow - SurfaceEvap) - SurfaceInfil) - SurfaceOutflow
   f_l(PAVE) = ((SurfaceInfil - PaveEvap) - PavePerc) / paveVoidFrac
   if (theLidProc%soil%thickness > 0.0_dp) then
      f_l(SOIL) = ((PavePerc - SoilEvap) - SoilPerc) / soilThickness
      storageInflow_l = SoilPerc
   else
      f_l(SOIL) = 0.0_dp
      storageInflow_l = PavePerc
      SoilPerc = 0.0_dp
   end if
   f_l(STOR) = (((storageInflow_l - StorageEvap) - StorageExfil) - StorageDrain) / storageVoidFrac
end subroutine pavementFluxRates

! lidproc.c:1061
recursive subroutine swaleFluxRates(x_l, f_l)
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: f_l(:)
   real(dp) :: depth
   real(dp) :: topWidth
   real(dp) :: botWidth
   real(dp) :: length_l
   real(dp) :: surfInflow
   real(dp) :: surfWidth
   real(dp) :: surfArea
   real(dp) :: flowArea
   real(dp) :: lidArea
   real(dp) :: hydRadius
   real(dp) :: slope_l
   real(dp) :: volume_l
   real(dp) :: dVdT
   real(dp) :: dStore_l
   real(dp) :: xDepth
   real(dp) :: v1_
   depth = 0.0_dp
   topWidth = 0.0_dp
   botWidth = 0.0_dp
   length_l = 0.0_dp
   surfInflow = 0.0_dp
   surfWidth = 0.0_dp
   surfArea = 0.0_dp
   flowArea = 0.0_dp
   lidArea = 0.0_dp
   hydRadius = 0.0_dp
   slope_l = 0.0_dp
   volume_l = 0.0_dp
   dVdT = 0.0_dp
   dStore_l = 0.0_dp
   xDepth = 0.0_dp
   depth = x_l(SURF)
   if ((depth) <= (theLidProc%surface%thickness)) then
      v1_ = depth
   else
      v1_ = theLidProc%surface%thickness
   end if
   depth = v1_
   dStore_l = 0.0_dp
   slope_l = theLidProc%surface%sideSlope
   topWidth = theLidUnit%fullWidth
   topWidth = merge(topWidth, 0.5_dp, (topWidth) >= (0.5_dp))
   botWidth = topWidth - ((2.0_dp * slope_l) * theLidProc%surface%thickness)
   if (botWidth < 0.5_dp) then
      botWidth = 0.5_dp
      slope_l = (0.5_dp * (topWidth - 0.5_dp)) / theLidProc%surface%thickness
   end if
   lidArea = theLidUnit%area
   length_l = lidArea / topWidth
   surfWidth = botWidth + ((2.0_dp * slope_l) * depth)
   surfArea = length_l * surfWidth
   flowArea = (depth * (botWidth + (slope_l * depth))) * theLidProc%surface%voidFrac
   volume_l = length_l * flowArea
   surfInflow = SurfaceInflow * lidArea
   SurfaceEvap = lidproc_EvapRate * surfArea
   SurfaceEvap = merge(SurfaceEvap, volume_l / lidproc_Tstep, (SurfaceEvap) <= (volume_l / lidproc_Tstep))
   StorageExfil = SurfaceInfil * surfArea
   xDepth = depth - dStore_l
   if (xDepth <= 1.0e-10_dp) then
      SurfaceOutflow = 0.0_dp
   else
      flowArea = flowArea - ((dStore_l * (botWidth + (slope_l * dStore_l))) * theLidProc%surface%voidFrac)
      if (flowArea < 1.0e-10_dp) then
         SurfaceOutflow = 0.0_dp
      else
         botWidth = botWidth + ((2.0_dp * dStore_l) * slope_l)
         hydRadius = botWidth + ((2.0_dp * xDepth) * sqrt(1.0_dp + (slope_l * slope_l)))
         hydRadius = flowArea / hydRadius
         SurfaceOutflow = (theLidProc%surface%alpha * flowArea) * (hydRadius ** (2.0_dp / 3.0_dp))
      end if
   end if
   dVdT = ((surfInflow - SurfaceEvap) - StorageExfil) - SurfaceOutflow
   if ((depth == theLidProc%surface%thickness) .and. (dVdT > 0.0_dp)) then
      SurfaceOutflow = SurfaceOutflow + dVdT
      dVdT = 0.0_dp
   end if
   SurfaceEvap = SurfaceEvap / lidArea
   StorageExfil = StorageExfil / lidArea
   SurfaceOutflow = SurfaceOutflow / lidArea
   f_l(SURF) = dVdT / surfArea
   f_l(SOIL) = 0.0_dp
   f_l(STOR) = 0.0_dp
   SurfaceVolume = volume_l / lidArea
   SoilVolume = 0.0_dp
   StorageVolume = 0.0_dp
end subroutine swaleFluxRates

! lidproc.c:1176
recursive subroutine barrelFluxRates(x_l, f_l)
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: f_l(:)
   real(dp) :: storageDepth
   real(dp) :: head
   real(dp) :: maxValue
   logical :: b1_
   storageDepth = x_l(STOR)
   head = 0.0_dp
   maxValue = 0.0_dp
   SurfaceVolume = 0.0_dp
   SoilVolume = 0.0_dp
   StorageVolume = storageDepth
   SurfaceInfil = 0.0_dp
   SurfaceOutflow = 0.0_dp
   StorageDrain = 0.0_dp
   b1_ = theLidProc%drain%delay == 0.0_dp
   if (.not. b1_) then
      b1_ = theLidUnit%dryTime >= theLidProc%drain%delay
   end if
   if (b1_) then
      head = storageDepth - theLidProc%drain%offset
      if (head > 0.0_dp) then
         StorageDrain = getStorageDrainRate(storageDepth, 0.0_dp, 0.0_dp, 0.0_dp)
         maxValue = head / lidproc_Tstep
         StorageDrain = merge(StorageDrain, maxValue, (StorageDrain) <= (maxValue))
      end if
   end if
   StorageInflow = SurfaceInflow
   maxValue = ((theLidProc%storage%thickness - storageDepth) / lidproc_Tstep) + StorageDrain
   StorageInflow = merge(StorageInflow, maxValue, (StorageInflow) <= (maxValue))
   SurfaceInfil = StorageInflow
   f_l(SURF) = SurfaceInflow - StorageInflow
   f_l(STOR) = StorageInflow - StorageDrain
   f_l(SOIL) = 0.0_dp
end subroutine barrelFluxRates

! lidproc.c:1226
recursive function getSurfaceOutflowRate(depth) result(res_)
   real(dp), value :: depth
   real(dp) :: res_
   real(dp) :: delta
   real(dp) :: outflow
   res_ = 0.0_dp
   delta = 0.0_dp
   outflow = 0.0_dp
   delta = depth - theLidProc%surface%thickness
   if (delta < 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   outflow = ((theLidProc%surface%alpha * (delta ** (5.0_dp / 3.0_dp))) * theLidUnit%fullWidth) / theLidUnit%area
   outflow = merge(outflow, delta / lidproc_Tstep, (outflow) <= (delta / lidproc_Tstep))
   res_ = outflow
   return
end function getSurfaceOutflowRate

! lidproc.c:1251
recursive function getPavementPermRate() result(res_)
   real(dp) :: res_
   real(dp) :: permReduction
   real(dp) :: clogFactor
   real(dp) :: regenDays
   res_ = 0.0_dp
   permReduction = 0.0_dp
   clogFactor = theLidProc%pavement%clogFactor
   regenDays = theLidProc%pavement%regenDays
   if (clogFactor > 0.0_dp) then
      if (regenDays > 0.0_dp) then
         if (((OldRunoffTime / 1000.0_dp) / 86400.0_dp) >= theLidUnit%nextRegenDay) then
            theLidUnit%volTreated = theLidUnit%volTreated * (1.0_dp - theLidProc%pavement%regenDegree)
            theLidUnit%nextRegenDay = theLidUnit%nextRegenDay + regenDays
         end if
      end if
      permReduction = theLidUnit%volTreated / clogFactor
      permReduction = merge(permReduction, 1.0_dp, (permReduction) <= (1.0_dp))
   end if
   res_ = theLidProc%pavement%kSat * (1.0_dp - permReduction)
   return
end function getPavementPermRate

! lidproc.c:1293
recursive function getSoilPercRate(theta_l) result(res_)
   real(dp), value :: theta_l
   real(dp) :: res_
   real(dp) :: delta
   res_ = 0.0_dp
   delta = 0.0_dp
   if (theta_l <= theLidProc%soil%fieldCap) then
      res_ = 0.0_dp
      return
   end if
   delta = theLidProc%soil%porosity - theta_l
   res_ = theLidProc%soil%kSat * exp((-delta) * theLidProc%soil%kSlope)
   return
end function getSoilPercRate

! lidproc.c:1313
recursive function getStorageExfilRate() result(res_)
   real(dp) :: res_
   real(dp) :: infil_l
   real(dp) :: clogFactor
   res_ = 0.0_dp
   infil_l = 0.0_dp
   clogFactor = 0.0_dp
   if (theLidProc%storage%kSat == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (lidproc_MaxNativeInfil == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   clogFactor = theLidProc%storage%clogFactor
   if (clogFactor > 0.0_dp) then
      clogFactor = theLidUnit%waterBalance%inflow / clogFactor
      clogFactor = merge(clogFactor, 1.0_dp, (clogFactor) <= (1.0_dp))
   end if
   infil_l = theLidProc%storage%kSat * (1.0_dp - clogFactor)
   res_ = merge(infil_l, lidproc_MaxNativeInfil, (infil_l) <= (lidproc_MaxNativeInfil))
   return
end function getStorageExfilRate

! lidproc.c:1344
recursive function getStorageDrainRate(storageDepth, soilTheta, paveDepth, surfaceDepth) result(res_)
   real(dp), value :: storageDepth
   real(dp), value :: soilTheta
   real(dp), value :: paveDepth
   real(dp), value :: surfaceDepth
   real(dp) :: res_
   integer(int32) :: curve_l
   real(dp) :: head
   real(dp) :: outflow
   real(dp) :: paveThickness
   real(dp) :: soilThickness
   real(dp) :: soilPorosity
   real(dp) :: soilFieldCap
   real(dp) :: storageThickness
   logical :: b1_
   logical :: b2_
   res_ = 0.0_dp
   curve_l = theLidProc%drain%qCurve
   head = storageDepth
   outflow = 0.0_dp
   paveThickness = theLidProc%pavement%thickness
   soilThickness = theLidProc%soil%thickness
   soilPorosity = theLidProc%soil%porosity
   soilFieldCap = theLidProc%soil%fieldCap
   storageThickness = theLidProc%storage%thickness
   if (storageDepth >= storageThickness) then
      if (soilThickness > 0.0_dp) then
         if (soilTheta > soilFieldCap) then
            head = head + (((soilTheta - soilFieldCap) / (soilPorosity - soilFieldCap)) * soilThickness)
            if (soilTheta >= soilPorosity) then
               if (paveThickness > 0.0_dp) then
                  head = head + paveDepth
                  if (paveDepth >= paveThickness) then
                     head = head + surfaceDepth
                  end if
               else
                  head = head + surfaceDepth
               end if
            end if
         end if
      else if (paveThickness > 0.0_dp) then
         head = head + paveDepth
         if (paveDepth >= paveThickness) then
            head = head + surfaceDepth
         end if
      end if
   end if
   b1_ = theLidUnit%oldDrainFlow == 0.0_dp
   if (b1_) then
      b1_ = head <= theLidProc%drain%hOpen
   end if
   if (b1_) then
      res_ = 0.0_dp
      return
   end if
   b2_ = theLidUnit%oldDrainFlow > 0.0_dp
   if (b2_) then
      b2_ = head <= theLidProc%drain%hClose
   end if
   if (b2_) then
      res_ = 0.0_dp
      return
   end if
   head = head - theLidProc%drain%offset
   if (head > 1.0e-10_dp) then
      head = head * UCF(RAINDEPTH)
      outflow = theLidProc%drain%coeff * (head ** theLidProc%drain%expon)
      if (curve_l >= 0) then
         outflow = outflow * table_lookup(Curve(curve_l), head)
      end if
      outflow = outflow / UCF(RAINFALL)
   end if
   res_ = outflow
   return
end function getStorageDrainRate

! lidproc.c:1436
recursive function getDrainMatOutflow(depth) result(res_)
   real(dp), value :: depth
   real(dp) :: res_
   real(dp) :: result_l
   res_ = 0.0_dp
   result_l = SoilPerc
   if (theLidProc%drainMat%alpha > 0.0_dp) then
      result_l = (((theLidProc%drainMat%alpha * (depth ** (5.0_dp / 3.0_dp))) * theLidUnit%fullWidth) / theLidUnit%area) * theLidProc%drainMat%voidFrac
   end if
   res_ = result_l
   return
end function getDrainMatOutflow

! lidproc.c:1458
recursive subroutine lidproc_getEvapRates(surfaceVol, paveVol, soilVol, storageVol, pervFrac)
   real(dp), value :: surfaceVol
   real(dp), value :: paveVol
   real(dp), value :: soilVol
   real(dp), value :: storageVol
   real(dp), value :: pervFrac
   real(dp) :: availEvap_l
   availEvap_l = 0.0_dp
   availEvap_l = lidproc_EvapRate
   SurfaceEvap = merge(availEvap_l, surfaceVol / lidproc_Tstep, (availEvap_l) <= (surfaceVol / lidproc_Tstep))
   SurfaceEvap = merge(0.0_dp, SurfaceEvap, (0.0_dp) >= (SurfaceEvap))
   availEvap_l = merge(0.0_dp, availEvap_l - SurfaceEvap, (0.0_dp) >= (availEvap_l - SurfaceEvap))
   availEvap_l = availEvap_l * pervFrac
   if (SurfaceInfil > 0.0_dp) then
      PaveEvap = 0.0_dp
      SoilEvap = 0.0_dp
      StorageEvap = 0.0_dp
   else
      PaveEvap = merge(availEvap_l, paveVol / lidproc_Tstep, (availEvap_l) <= (paveVol / lidproc_Tstep))
      availEvap_l = merge(0.0_dp, availEvap_l - PaveEvap, (0.0_dp) >= (availEvap_l - PaveEvap))
      SoilEvap = merge(availEvap_l, soilVol / lidproc_Tstep, (availEvap_l) <= (soilVol / lidproc_Tstep))
      availEvap_l = merge(0.0_dp, availEvap_l - SoilEvap, (0.0_dp) >= (availEvap_l - SoilEvap))
      StorageEvap = merge(availEvap_l, storageVol / lidproc_Tstep, (availEvap_l) <= (storageVol / lidproc_Tstep))
   end if
end subroutine lidproc_getEvapRates

! lidproc.c:1503
recursive function getSurfaceOverflowRate(surfaceDepth) result(res_)
   real(dp), intent(inout), target :: surfaceDepth
   real(dp) :: res_
   real(dp) :: delta
   res_ = 0.0_dp
   delta = surfaceDepth - theLidProc%surface%thickness
   if (delta <= 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   surfaceDepth = theLidProc%surface%thickness
   res_ = (delta * theLidProc%surface%voidFrac) / lidproc_Tstep
   return
end function getSurfaceOverflowRate

! lidproc.c:1518
recursive subroutine updateWaterBalance(lidUnit, inflow, evap_l, infil_l, surfFlow, drainFlow, storage_l)
   type(TLidUnit), pointer, intent(in) :: lidUnit
   real(dp), value :: inflow
   real(dp), value :: evap_l
   real(dp), value :: infil_l
   real(dp), value :: surfFlow
   real(dp), value :: drainFlow
   real(dp), value :: storage_l
   lidUnit%volTreated = lidUnit%volTreated + (inflow * lidproc_Tstep)
   lidUnit%waterBalance%inflow = lidUnit%waterBalance%inflow + (inflow * lidproc_Tstep)
   lidUnit%waterBalance%evap = lidUnit%waterBalance%evap + (evap_l * lidproc_Tstep)
   lidUnit%waterBalance%infil = lidUnit%waterBalance%infil + (infil_l * lidproc_Tstep)
   lidUnit%waterBalance%surfFlow = lidUnit%waterBalance%surfFlow + (surfFlow * lidproc_Tstep)
   lidUnit%waterBalance%drainFlow = lidUnit%waterBalance%drainFlow + (drainFlow * lidproc_Tstep)
   lidUnit%waterBalance%finalVol = storage_l
end subroutine updateWaterBalance

! lidproc.c:1544
recursive function modpuls_solve(n_l, x_l, xOld_l, xPrev, xMin, xMax, xTol_l, qOld, q_l, dt_l, omega_l, derivs) result(res_)
   integer(int32), value :: n_l
   real(dp), pointer, intent(in) :: x_l(:)
   real(dp), pointer, intent(in) :: xOld_l(:)
   real(dp), pointer, intent(in) :: xPrev(:)
   real(dp), pointer, intent(in) :: xMin(:)
   real(dp), pointer, intent(in) :: xMax(:)
   real(dp), pointer, intent(in) :: xTol_l(:)
   real(dp), pointer, intent(in) :: qOld(:)
   real(dp), pointer, intent(in) :: q_l(:)
   real(dp), value :: dt_l
   real(dp), value :: omega_l
   procedure(fp2) :: derivs
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: canStop
   integer(int32) :: steps_l
   integer(int32) :: maxSteps_l
   real(dp) :: v1_
   real(dp) :: v2_
   logical :: b3_
   res_ = 0
   i_l = 0
   canStop = 0
   steps_l = 1
   maxSteps_l = 20
   i_l = 0
   do while (i_l < n_l)
      xOld_l(i_l) = x_l(i_l)
      xPrev(i_l) = x_l(i_l)
      i_l = i_l + 1
   end do
   do while (steps_l < maxSteps_l)
      canStop = 1
      call derivs(x_l, q_l)
      i_l = 0
      do while (i_l < n_l)
         x_l(i_l) = xOld_l(i_l) + (((omega_l * qOld(i_l)) + ((1.0_dp - omega_l) * q_l(i_l))) * dt_l)
         if ((x_l(i_l)) <= (xMax(i_l))) then
            v1_ = x_l(i_l)
         else
            v1_ = xMax(i_l)
         end if
         x_l(i_l) = v1_
         if ((x_l(i_l)) >= (xMin(i_l))) then
            v2_ = x_l(i_l)
         else
            v2_ = xMin(i_l)
         end if
         x_l(i_l) = v2_
         b3_ = omega_l > 0.0_dp
         if (b3_) then
            b3_ = abs(x_l(i_l) - xPrev(i_l)) > xTol_l(i_l)
         end if
         if (b3_) then
            canStop = 0
         end if
         xPrev(i_l) = x_l(i_l)
         i_l = i_l + 1
      end do
      if (canStop /= 0) then
         res_ = steps_l
         return
      end if
      steps_l = steps_l + 1
   end do
   res_ = 0
   return
end function modpuls_solve

! link.c:137
recursive function link_readParams(j_l, type_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
