   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   res_ = 0
   select case (type_l)
   case (0)
      res_ = conduit_readParams(j_l, k_l, tok_l, ntoks)
      return
   case (1)
      res_ = pump_readParams(j_l, k_l, tok_l, ntoks)
      return
   case (2)
