      return
   case (3)
      res_ = weir_readParams(j_l, k_l, tok_l, ntoks)
      return
   case (4)
      res_ = outlet_readParams(j_l, k_l, tok_l, ntoks)
      return
   case default
      res_ = 0
      return
   end select
end function link_readParams

! link.c:162
recursive function link_readXsectParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp), target :: x_l(0:3)
   logical :: b1_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   x_l = 0.0_dp
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(LINK_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   k_l = findmatch(tok_l(1), XsectTypeWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   if (Link(j_l)%type == CONDUIT_c) then
      Conduit(Link(j_l)%subIndex)%barrels = 1
   end if
   Link(j_l)%xsect%culvertCode = 0
   if (k_l == IRREGULAR) then
      i_l = project_findObject(TRANSECT_c, tok_l(2))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
      Link(j_l)%xsect%type = k_l
      Link(j_l)%xsect%transect = i_l
      res_ = 0
      return
   else if (k_l == STREET_XSECT) then
      i_l = project_findObject(STREET_c, tok_l(2))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
      Link(j_l)%xsect%type = k_l
      Link(j_l)%xsect%transect = i_l
      res_ = 0
      return
   else
      if (ntoks < 6) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (k_l == CUSTOM) then
         b1_ = .not. (getDouble(tok_l(2), x_l(0)) /= 0)
         if (.not. b1_) then
            b1_ = x_l(0) <= 0.0_dp
         end if
         if (b1_) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(2))
            return
         end if
         i_l = project_findObject(CURVE_c, tok_l(3))
         if (i_l < 0) then
            res_ = error_setInpError(ERR_NAME, tok_l(3))
            return
         end if
         Link(j_l)%xsect%type = k_l
         Link(j_l)%xsect%transect = i_l
         Link(j_l)%xsect%yFull = x_l(0) / UCF(LENGTH)
      else
         i_l = 2
         do while (i_l <= 5)
            if (.not. (getDouble(tok_l(i_l), x_l(i_l - 2)) /= 0)) then
               res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
               return
            end if
            i_l = i_l + 1
         end do
      end if
      if ((Link(j_l)%type /= CONDUIT_c) .and. (k_l == RECT_OPEN)) then
         x_l(2) = 0.0_dp
         x_l(3) = 0.0_dp
      end if
      if (.not. (xsect_setParams(Link(j_l)%xsect, k_l, x_l, UCF(LENGTH)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, lit_0)
         return
      end if
      if ((Link(j_l)%type == CONDUIT_c) .and. (ntoks >= 7)) then
         i_l = c_atoi(tok_l(6))
         if (i_l <= 0) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(6))
            return
         else
            Conduit(Link(j_l)%subIndex)%barrels = i_l
         end if
      end if
      if ((Link(j_l)%type == CONDUIT_c) .and. (ntoks >= 8)) then
         i_l = c_atoi(tok_l(7))
         if (i_l < 0) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(7))
            return
         else
            Link(j_l)%xsect%culvertCode = i_l
         end if
      end if
   end if
   res_ = 0
   return
end function link_readXsectParams

! link.c:271
recursive function link_readLossParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp), target :: x_l(0:2)
   real(dp), target :: seepRate
   logical :: b1_
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   x_l = 0.0_dp
   seepRate = 0.0_dp
   if (ntoks < 4) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(LINK_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   i_l = 1
   do while (i_l <= 3)
      b1_ = .not. (getDouble(tok_l(i_l), x_l(i_l - 1)) /= 0)
      if (.not. b1_) then
         b1_ = x_l(i_l - 1) < 0.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   k_l = 0
   if (ntoks >= 5) then
      k_l = findmatch(tok_l(4), NoYesWords)
      if (k_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(4))
         return
      end if
   end if
   if (ntoks >= 6) then
      if (.not. (getDouble(tok_l(5), seepRate) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
   end if
   Link(j_l)%cLossInlet = x_l(0)
   Link(j_l)%cLossOutlet = x_l(1)
   Link(j_l)%cLossAvg = x_l(2)
   Link(j_l)%hasFlapGate = k_l
   Link(j_l)%seepRate = seepRate / UCF(RAINFALL)
   res_ = 0
   return
end function link_readLossParams

! link.c:315
recursive subroutine link_setParams(j_l, type_l, n1, n2, k_l, x_l)
   integer(int32), value :: j_l
   integer(int32), value :: type_l
   integer(int32), value :: n1
   integer(int32), value :: n2
   integer(int32), value :: k_l
   real(dp), pointer, intent(in) :: x_l(:)
   integer(int32) :: dum1_
   Link(j_l)%node1 = n1
   Link(j_l)%node2 = n2
   Link(j_l)%type = type_l
   Link(j_l)%subIndex = k_l
   Link(j_l)%offset1 = 0.0_dp
   Link(j_l)%offset2 = 0.0_dp
   Link(j_l)%q0 = 0.0_dp
   Link(j_l)%qFull = 0.0_dp
   Link(j_l)%setting = 1.0_dp
   Link(j_l)%targetSetting = 1.0_dp
   Link(j_l)%hasFlapGate = 0
   Link(j_l)%qLimit = 0.0_dp
   Link(j_l)%direction = 1
   select case (type_l)
   case (0)
      Conduit(k_l)%length = x_l(0) / UCF(LENGTH)
      Conduit(k_l)%modLength = Conduit(k_l)%length
      Conduit(k_l)%roughness = x_l(1)
      Link(j_l)%offset1 = x_l(2) / UCF(LENGTH)
      Link(j_l)%offset2 = x_l(3) / UCF(LENGTH)
      Link(j_l)%q0 = x_l(4) / UCF(FLOW)
      Link(j_l)%qLimit = x_l(5) / UCF(FLOW)
   case (1)
      Pump(k_l)%pumpCurve = d2i(x_l(0))
      Link(j_l)%hasFlapGate = 0
      Pump(k_l)%initSetting = x_l(1)
      Pump(k_l)%yOn = x_l(2) / UCF(LENGTH)
      Pump(k_l)%yOff = x_l(3) / UCF(LENGTH)
      Pump(k_l)%xMin = 0.0_dp
      Pump(k_l)%xMax = 0.0_dp
   case (2)
      Orifice(k_l)%type = d2i(x_l(0))
      Link(j_l)%offset1 = x_l(1) / UCF(LENGTH)
      Link(j_l)%offset2 = Link(j_l)%offset1
      Orifice(k_l)%cDisch = x_l(2)
      Link(j_l)%hasFlapGate = merge(1, 0, x_l(3) > 0.0_dp)
      Orifice(k_l)%orate = x_l(4) * 3600.0_dp
   case (3)
      Weir(k_l)%type = d2i(x_l(0))
      Link(j_l)%offset1 = x_l(1) / UCF(LENGTH)
      Link(j_l)%offset2 = Link(j_l)%offset1
      Weir(k_l)%cDisch1 = x_l(2)
      Link(j_l)%hasFlapGate = merge(1, 0, x_l(3) > 0.0_dp)
      Weir(k_l)%endCon = x_l(4)
      Weir(k_l)%cDisch2 = x_l(5)
      Weir(k_l)%canSurcharge = d2i(x_l(6))
      Weir(k_l)%roadWidth = x_l(7) / UCF(LENGTH)
      Weir(k_l)%roadSurface = d2i(x_l(8))
      Weir(k_l)%cdCurve = d2i(x_l(9))
   case (4)
      Link(j_l)%offset1 = x_l(0) / UCF(LENGTH)
      Link(j_l)%offset2 = Link(j_l)%offset1
      Outlet(k_l)%qCoeff = x_l(1)
      Outlet(k_l)%qExpon = x_l(2)
      Outlet(k_l)%qCurve = d2i(x_l(3))
      Link(j_l)%hasFlapGate = merge(1, 0, x_l(4) > 0.0_dp)
      Outlet(k_l)%curveType = d2i(x_l(5))
      dum1_ = xsect_setParams(Link(j_l)%xsect, DUMMY, null(), 0.0_dp)
   end select
end subroutine link_setParams

! link.c:403
recursive subroutine link_validate(j_l)
   integer(int32), value :: j_l
   integer(int32) :: n_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   real(dp) :: v4_
   logical :: b5_
   logical :: b6_
   real(dp) :: v7_
   n_l = 0
   if (LinkOffsets == ELEV_OFFSET) then
      call link_convertOffsets(j_l)
   end if
   select case (Link(j_l)%type)
   case (0)
      call conduit_validate(j_l, Link(j_l)%subIndex)
   case (1)
      call pump_validate(j_l, Link(j_l)%subIndex)
   case (2)
      call orifice_validate(j_l, Link(j_l)%subIndex)
   case (3)
      call weir_validate(j_l, Link(j_l)%subIndex)
   end select
   select case (Link(j_l)%type)
   case (2, 3, 4)
      if ((Node(Link(j_l)%node1)%invertElev + Link(j_l)%offset1) < Node(Link(j_l)%node2)%invertElev) then
         if (RouteModel == DW) then
            Link(j_l)%offset1 = Node(Link(j_l)%node2)%invertElev - Node(Link(j_l)%node1)%invertElev
            call report_writeWarningMsg(lit_305, Link(j_l)%ID)
         else
            call report_writeWarningMsg(lit_306, Link(j_l)%ID)
         end if
      end if
   end select
   b2_ = Link(j_l)%type == PUMP_c
   if (.not. b2_) then
      b1_ = Link(j_l)%type == ORIFICE_c
      if (b1_) then
         b1_ = Orifice(Link(j_l)%subIndex)%type == BOTTOM_ORIFICE
      end if
      b2_ = b1_
   end if
   if (b2_) then
      return
   end if
   n_l = Link(j_l)%node1
   b3_ = Node(n_l)%type /= STORAGE_c
   if (.not. b3_) then
      b3_ = Node(n_l)%surDepth > 0.0_dp
   end if
   if (b3_) then
      if ((Node(n_l)%fullDepth) >= (Link(j_l)%offset1 + Link(j_l)%xsect%yFull)) then
         v4_ = Node(n_l)%fullDepth
      else
         v4_ = Link(j_l)%offset1 + Link(j_l)%xsect%yFull
      end if
      Node(n_l)%fullDepth = v4_
   end if
   n_l = Link(j_l)%node2
   b5_ = Node(n_l)%type /= STORAGE_c
   if (.not. b5_) then
      b5_ = Node(n_l)%surDepth > 0.0_dp
   end if
   b6_ = b5_
   if (b6_) then
      b6_ = Link(j_l)%type == CONDUIT_c
   end if
   if (b6_) then
      if ((Node(n_l)%fullDepth) >= (Link(j_l)%offset2 + Link(j_l)%xsect%yFull)) then
         v7_ = Node(n_l)%fullDepth
      else
         v7_ = Link(j_l)%offset2 + Link(j_l)%xsect%yFull
      end if
      Node(n_l)%fullDepth = v7_
   end if
end subroutine link_validate

! link.c:468
recursive subroutine link_convertOffsets(j_l)
   integer(int32), value :: j_l
   real(dp) :: elev_l
   elev_l = 0.0_dp
   elev_l = Node(Link(j_l)%node1)%invertElev
   Link(j_l)%offset1 = link_getOffsetHeight(j_l, Link(j_l)%offset1, elev_l)
   if (Link(j_l)%type == CONDUIT_c) then
      elev_l = Node(Link(j_l)%node2)%invertElev
      Link(j_l)%offset2 = link_getOffsetHeight(j_l, Link(j_l)%offset2, elev_l)
   else
      Link(j_l)%offset2 = Link(j_l)%offset1
   end if
end subroutine link_convertOffsets

! link.c:489
recursive function link_getOffsetHeight(j_l, offset, elev_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: offset
   real(dp), value :: elev_l
   real(dp) :: res_
   logical :: b1_
   res_ = 0.0_dp
   b1_ = offset <= (-10000000000.0_dp)
   if (.not. b1_) then
      b1_ = Link(j_l)%type == PUMP_c
   end if
   if (b1_) then
      res_ = 0.0_dp
      return
   end if
   offset = offset - elev_l
   if (offset >= 0.0_dp) then
      res_ = offset
      return
   end if
   if (offset >= (-MIN_DELTA_Z)) then
      res_ = 0.0_dp
      return
   end if
   call report_writeWarningMsg(lit_307, Link(j_l)%ID)
   res_ = 0.0_dp
   return
end function link_getOffsetHeight

! link.c:508
recursive subroutine link_initState(j_l)
   integer(int32), value :: j_l
   integer(int32) :: p_l
   p_l = 0
   Link(j_l)%oldFlow = Link(j_l)%q0
   Link(j_l)%newFlow = Link(j_l)%q0
   Link(j_l)%oldDepth = 0.0_dp
   Link(j_l)%newDepth = 0.0_dp
   Link(j_l)%oldVolume = 0.0_dp
   Link(j_l)%newVolume = 0.0_dp
   Link(j_l)%setting = 1.0_dp
   Link(j_l)%targetSetting = 1.0_dp
   Link(j_l)%timeLastSet = StartDate
   Link(j_l)%inletControl = 0
   Link(j_l)%normalFlow = 0
   if (Link(j_l)%type == CONDUIT_c) then
      call conduit_initState(j_l, Link(j_l)%subIndex)
   end if
   if (Link(j_l)%type == PUMP_c) then
      call pump_initState(j_l, Link(j_l)%subIndex)
   end if
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      Link(j_l)%oldQual(p_l) = 0.0_dp
      Link(j_l)%newQual(p_l) = 0.0_dp
      Link(j_l)%totalLoad(p_l) = 0.0_dp
      p_l = p_l + 1
   end do
end subroutine link_initState

