! link.c:604
recursive subroutine link_setTargetSetting(j_l)
   integer(int32), value :: j_l
   integer(int32) :: k_l
   integer(int32) :: n1
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   k_l = 0
   n1 = 0
   if (Link(j_l)%type == PUMP_c) then
      k_l = Link(j_l)%subIndex
      n1 = Link(j_l)%node1
      Link(j_l)%targetSetting = Link(j_l)%setting
      b1_ = Pump(k_l)%yOff > 0.0_dp
      if (b1_) then
         b1_ = Link(j_l)%setting > 0.0_dp
      end if
      b2_ = b1_
      if (b2_) then
         b2_ = Node(n1)%newDepth < Pump(k_l)%yOff
      end if
      if (b2_) then
         Link(j_l)%targetSetting = 0.0_dp
      end if
      b3_ = Pump(k_l)%yOn > 0.0_dp
      if (b3_) then
         b3_ = Link(j_l)%setting == 0.0_dp
      end if
      b4_ = b3_
      if (b4_) then
         b4_ = Node(n1)%newDepth > Pump(k_l)%yOn
      end if
      if (b4_) then
         Link(j_l)%targetSetting = 1.0_dp
      end if
   end if
end subroutine link_setTargetSetting

! link.c:628
recursive subroutine link_setSetting(j_l, tstep)
   integer(int32), value :: j_l
   real(dp), value :: tstep
   if (Link(j_l)%type == ORIFICE_c) then
      call orifice_setSetting(j_l, tstep)
   else if (Link(j_l)%type == WEIR_c) then
      call weir_setSetting(j_l)
   else
      Link(j_l)%setting = Link(j_l)%targetSetting
   end if
end subroutine link_setSetting

! link.c:643
recursive function link_setFlapGate(j_l, n1, n2, q_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: n1
   integer(int32), value :: n2
   real(dp), value :: q_l
   integer(int32) :: res_
   integer(int32) :: n_l
   logical :: b1_
   logical :: b2_
   res_ = 0
   n_l = -1
   if (Link(j_l)%hasFlapGate /= 0) then
      if ((q_l * real(Link(j_l)%direction, dp)) < 0.0_dp) then
         res_ = 1
         return
      end if
   end if
   if (q_l < 0.0_dp) then
      n_l = n2
   end if
   if (q_l > 0.0_dp) then
      n_l = n1
   end if
   b1_ = n_l >= 0
   if (b1_) then
      b1_ = Node(n_l)%type == OUTFALL_c
   end if
   b2_ = b1_
   if (b2_) then
      b2_ = Outfall(Node(n_l)%subIndex)%hasFlapGate /= 0
   end if
   if (b2_) then
      res_ = 1
      return
   end if
   res_ = 0
   return
end function link_setFlapGate

! link.c:674
recursive subroutine link_getResults(j_l, f_l, x_l)
   integer(int32), value :: j_l
   real(dp), value :: f_l
   real(sp), pointer, intent(in) :: x_l(:)
   integer(int32) :: p_l
   real(dp) :: y_l
   real(dp) :: q_l
   real(dp) :: u_l
   real(dp) :: v_l
   real(dp) :: c_l
   real(dp) :: f1
   logical :: b1_
   p_l = 0
   y_l = 0.0_dp
   q_l = 0.0_dp
   u_l = 0.0_dp
   v_l = 0.0_dp
   c_l = 0.0_dp
   f1 = 1.0_dp - f_l
   y_l = (f1 * Link(j_l)%oldDepth) + (f_l * Link(j_l)%newDepth)
   q_l = (f1 * Link(j_l)%oldFlow) + (f_l * Link(j_l)%newFlow)
   v_l = (f1 * Link(j_l)%oldVolume) + (f_l * Link(j_l)%newVolume)
   u_l = link_getVelocity(j_l, q_l, y_l)
   c_l = 0.0_dp
   if (Link(j_l)%type == CONDUIT_c) then
      if (Link(j_l)%xsect%type /= DUMMY) then
         c_l = xsect_getAofY(Link(j_l)%xsect, y_l) / Link(j_l)%xsect%aFull
      end if
   else
      c_l = Link(j_l)%setting
   end if
   b1_ = Link(j_l)%type == PUMP_c
   if (b1_) then
      b1_ = (Link(j_l)%oldFlow * Link(j_l)%newFlow) == 0.0_dp
   end if
   if (b1_) then
      if (f_l >= f1) then
         q_l = Link(j_l)%newFlow
      else
         q_l = Link(j_l)%oldFlow
      end if
   end if
   y_l = y_l * UCF(LENGTH)
   v_l = v_l * UCF(VOLUME)
   q_l = q_l * (UCF(FLOW) * real(Link(j_l)%direction, dp))
   u_l = u_l * (UCF(LENGTH) * real(Link(j_l)%direction, dp))
   x_l(LINK_DEPTH) = real(y_l, sp)
   x_l(LINK_FLOW) = real(q_l, sp)
   x_l(LINK_VELOCITY) = real(u_l, sp)
   x_l(LINK_VOLUME) = real(v_l, sp)
   x_l(LINK_CAPACITY) = real(c_l, sp)
   if (.not. (IgnoreQuality /= 0)) then
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         c_l = (f1 * Link(j_l)%oldQual(p_l)) + (f_l * Link(j_l)%newQual(p_l))
         x_l(LINK_QUAL + p_l) = real(c_l, sp)
         p_l = p_l + 1
      end do
   end if
end subroutine link_getResults

! link.c:728
recursive subroutine link_setOutfallDepth(j_l)
   integer(int32), value :: j_l
   integer(int32) :: k_l
   integer(int32) :: n_l
   real(dp) :: z_l
   real(dp) :: q_l
   real(dp) :: yCrit
   real(dp) :: yNorm
   k_l = 0
   n_l = 0
   z_l = 0.0_dp
   q_l = 0.0_dp
   yCrit = 0.0_dp
   yNorm = 0.0_dp
   if (Node(Link(j_l)%node2)%type == OUTFALL_c) then
      n_l = Link(j_l)%node2
      z_l = Link(j_l)%offset2
   else if (Node(Link(j_l)%node1)%type == OUTFALL_c) then
      n_l = Link(j_l)%node1
      z_l = Link(j_l)%offset1
   else
      return
   end if
   if (Link(j_l)%type == CONDUIT_c) then
      k_l = Link(j_l)%subIndex
      q_l = abs(Link(j_l)%newFlow / real(Conduit(k_l)%barrels, dp))
      yNorm = link_getYnorm(j_l, q_l)
      yCrit = link_getYcrit(j_l, q_l)
   end if
   call node_setOutletDepth(n_l, yNorm, yCrit, z_l)
end subroutine link_setOutfallDepth

! link.c:770
recursive function link_getYcrit(j_l, q_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: q_l
   real(dp) :: res_
   res_ = 0.0_dp
   res_ = xsect_getYcrit(Link(j_l)%xsect, q_l)
   return
end function link_getYcrit

! link.c:783
recursive function link_getYnorm(j_l, q_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: q_l
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: s_l
   real(dp) :: a_l
   real(dp) :: y_l
   res_ = 0.0_dp
   k_l = 0
   s_l = 0.0_dp
   a_l = 0.0_dp
   y_l = 0.0_dp
   if (Link(j_l)%type /= CONDUIT_c) then
      res_ = 0.0_dp
      return
   end if
   if (Link(j_l)%xsect%type == DUMMY) then
      res_ = 0.0_dp
      return
   end if
   q_l = abs(q_l)
   k_l = Link(j_l)%subIndex
   if (q_l > Conduit(k_l)%qMax) then
      q_l = Conduit(k_l)%qMax
   end if
   if (q_l <= 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   s_l = q_l / Conduit(k_l)%beta
   a_l = xsect_getAofS(Link(j_l)%xsect, s_l)
   y_l = xsect_getYofA(Link(j_l)%xsect, a_l)
   res_ = y_l
   return
end function link_getYnorm

! link.c:808
recursive function link_getLength(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   res_ = 0.0_dp
   if (Link(j_l)%type == CONDUIT_c) then
      res_ = conduit_getLength(j_l)
      return
   end if
   res_ = 0.0_dp
   return
end function link_getLength

! link.c:821
recursive function link_getVelocity(j_l, flow_l, depth) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: flow_l
   real(dp), value :: depth
   real(dp) :: res_
   real(dp) :: area_l
   real(dp) :: veloc
   integer(int32) :: k_l
   res_ = 0.0_dp
   area_l = 0.0_dp
   veloc = 0.0_dp
   k_l = 0
   if (depth <= 0.01_dp) then
      res_ = 0.0_dp
      return
   end if
   if (Link(j_l)%type == CONDUIT_c) then
      k_l = Link(j_l)%subIndex
      flow_l = flow_l / real(Conduit(k_l)%barrels, dp)
      area_l = xsect_getAofY(Link(j_l)%xsect, depth)
      if (area_l > 0.0001_dp) then
         veloc = flow_l / area_l
      end if
   end if
   res_ = veloc
   return
end function link_getVelocity

! link.c:847
recursive function link_getFroude(j_l, v_l, y_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: v_l
   real(dp), value :: y_l
   real(dp) :: res_
   type(TXsect), pointer :: xsect_l
   logical :: b1_
   res_ = 0.0_dp
   xsect_l => Link(j_l)%xsect
   if (Link(j_l)%type /= CONDUIT_c) then
      res_ = 0.0_dp
      return
   end if
   if (y_l <= 0.0001_dp) then
      res_ = 0.0_dp
      return
   end if
   b1_ = .not. (xsect_isOpen(xsect_l%type) /= 0)
   if (b1_) then
      b1_ = (xsect_l%yFull - y_l) <= 0.0001_dp
   end if
   if (b1_) then
      res_ = 0.0_dp
      return
   end if
   y_l = xsect_getAofY(xsect_l, y_l) / xsect_getWofY(xsect_l, y_l)
   res_ = abs(v_l) / sqrt(32.2_dp * y_l)
   return
end function link_getFroude

! link.c:875
recursive function link_getPower(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp) :: dh
   real(dp) :: q_l
   res_ = 0.0_dp
   n1 = Link(j_l)%node1
   n2 = Link(j_l)%node2
   dh = (Node(n1)%invertElev + Node(n1)%newDepth) - (Node(n2)%invertElev + Node(n2)%newDepth)
   q_l = abs(Link(j_l)%newFlow)
   res_ = ((abs(dh) * q_l) / 8.814_dp) * 0.7457_dp
   return
end function link_getPower

! link.c:893
recursive function link_getLossRate(j_l, routeModel_l, q_l, tstep) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: routeModel_l
   real(dp), value :: q_l
   real(dp), value :: tstep
   real(dp) :: res_
   res_ = 0.0_dp
   if (Link(j_l)%type == CONDUIT_c) then
      res_ = conduit_getLossRate(j_l, routeModel_l, q_l, tstep)
      return
   else
      res_ = 0.0_dp
      return
   end if
end function link_getLossRate

! link.c:911
recursive function link_getFullState(a1, a2, aFull_l) result(res_)
   real(dp), value :: a1
   real(dp), value :: a2
   real(dp), value :: aFull_l
   integer(int32) :: res_
   res_ = 0
   if (a1 >= aFull_l) then
      if (a2 >= aFull_l) then
         res_ = ALL_FULL
         return
      else
         res_ = UP_FULL
         return
      end if
   end if
   if (a2 >= aFull_l) then
      res_ = DN_FULL
      return
   end if
   res_ = 0
   return
end function link_getFullState

! link.c:933
recursive function conduit_readParams(j_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp), target :: x_l(0:5)
   type(CPtr) :: id
   logical :: b1_
   logical :: b2_
   res_ = 0
   n1 = 0
   n2 = 0
   x_l = 0.0_dp
   id = cnull()
   if (ntoks < 7) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(LINK_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   n1 = project_findObject(NODE_c, tok_l(1))
   if (n1 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   n2 = project_findObject(NODE_c, tok_l(2))
   if (n2 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   if (.not. (getDouble(tok_l(3), x_l(0)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(3))
      return
   end if
   if (.not. (getDouble(tok_l(4), x_l(1)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(4))
      return
   end if
   b1_ = LinkOffsets == ELEV_OFFSET
   if (b1_) then
      b1_ = cget(tok_l(5), 0) == 42
   end if
   if (b1_) then
      x_l(2) = -10000000000.0_dp
   else if (.not. (getDouble(tok_l(5), x_l(2)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(5))
      return
   end if
   b2_ = LinkOffsets == ELEV_OFFSET
   if (b2_) then
      b2_ = cget(tok_l(6), 0) == 42
   end if
   if (b2_) then
      x_l(3) = -10000000000.0_dp
   else if (.not. (getDouble(tok_l(6), x_l(3)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(6))
      return
   end if
   x_l(4) = 0.0_dp
   if (ntoks >= 8) then
      if (.not. (getDouble(tok_l(7), x_l(4)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(7))
         return
      end if
   end if
   x_l(5) = 0.0_dp
   if (ntoks >= 9) then
      if (.not. (getDouble(tok_l(8), x_l(5)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(8))
         return
      end if
   end if
   Link(j_l)%ID = id
   call link_setParams(j_l, CONDUIT_c, n1, n2, k_l, x_l)
   res_ = 0
   return
end function conduit_readParams

! link.c:992
recursive subroutine conduit_validate(j_l, k_l)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp) :: aa
   real(dp) :: lengthFactor
   real(dp) :: roughness
   real(dp) :: slope_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   logical :: b6_
   aa = 0.0_dp
   lengthFactor = 0.0_dp
   roughness = 0.0_dp
   slope_l = 0.0_dp
   if ((Link(j_l)%xsect%type == DUMMY) .and. (RouteModel == DW)) then
      if (Node(Link(j_l)%node1)%type == STORAGE_c) then
         call report_writeErrorMsg(ERR_DUMMY_LINK, Node(Link(j_l)%node1)%ID)
         return
      end if
   end if
   if (Link(j_l)%xsect%type == CUSTOM) then
      call xsect_setCustomXsectParams(Link(j_l)%xsect)
   end if
   if (Link(j_l)%xsect%type == IRREGULAR) then
      call xsect_setIrregXsectParams(Link(j_l)%xsect)
      Conduit(k_l)%roughness = Transect(Link(j_l)%xsect%transect)%roughness
   end if
   if (Link(j_l)%xsect%type == STREET_XSECT) then
      call xsect_setStreetXsectParams(Link(j_l)%xsect)
      Conduit(k_l)%roughness = Street(Link(j_l)%xsect%transect)%roughness
   end if
   if (Link(j_l)%xsect%type == FORCE_MAIN) then
      if (ForceMainEqn == D_W) then
         Link(j_l)%xsect%rBot = Link(j_l)%xsect%rBot / UCF(RAINDEPTH)
      end if
      if (Link(j_l)%xsect%rBot <= 0.0_dp) then
         call report_writeErrorMsg(ERR_XSECT, Link(j_l)%ID)
      end if
   end if
   if (Conduit(k_l)%length <= 0.0_dp) then
      call report_writeErrorMsg(ERR_LENGTH, Link(j_l)%ID)
   end if
   if (Conduit(k_l)%roughness <= 0.0_dp) then
      call report_writeErrorMsg(ERR_ROUGHNESS, Link(j_l)%ID)
   end if
   if (Conduit(k_l)%barrels <= 0) then
      call report_writeErrorMsg(ERR_BARRELS, Link(j_l)%ID)
   end if
   if (Link(j_l)%xsect%type /= DUMMY) then
      if (Link(j_l)%xsect%type < 0) then
         call report_writeErrorMsg(ERR_NO_XSECT, Link(j_l)%ID)
      else if (Link(j_l)%xsect%aFull <= 0.0_dp) then
         call report_writeErrorMsg(ERR_XSECT, Link(j_l)%ID)
      end if
   end if
   if (ErrorCode /= 0) then
      return
   end if
   if (Link(j_l)%offset1 < 0.0_dp) then
      call report_writeWarningMsg(lit_307, Link(j_l)%ID)
      Link(j_l)%offset1 = 0.0_dp
   end if
   if (Link(j_l)%offset2 < 0.0_dp) then
      call report_writeWarningMsg(lit_307, Link(j_l)%ID)
      Link(j_l)%offset2 = 0.0_dp
   end if
   if (Link(j_l)%xsect%type == FILLED_CIRCULAR) then
      Link(j_l)%offset1 = Link(j_l)%offset1 + Link(j_l)%xsect%yBot
      Link(j_l)%offset2 = Link(j_l)%offset2 + Link(j_l)%xsect%yBot
   end if
   slope_l = conduit_getSlope(j_l)
   Conduit(k_l)%slope = slope_l
   b1_ = (RouteModel == DW) .and. (slope_l < 0.0_dp)
   if (b1_) then
      b1_ = Link(j_l)%xsect%type /= DUMMY
   end if
   if (b1_) then
      call conduit_reverse(j_l, k_l)
   end if
   roughness = Conduit(k_l)%roughness
   b2_ = RouteModel == DW
   if (b2_) then
      b2_ = Link(j_l)%xsect%type == FORCE_MAIN
   end if
   if (b2_) then
      roughness = forcemain_getEquivN(j_l, k_l)
   end if
   if (Link(j_l)%xsect%type == IRREGULAR) then
      lengthFactor = Transect(Link(j_l)%xsect%transect)%lengthFactor
      roughness = roughness * sqrt(lengthFactor)
   end if
   lengthFactor = 1.0_dp
   b3_ = (RouteModel == DW) .and. (LengtheningStep > 0.0_dp)
   if (b3_) then
      b3_ = Link(j_l)%xsect%type /= DUMMY
   end if
   if (b3_) then
      lengthFactor = conduit_getLengthFactor(j_l, k_l, roughness)
   end if
   if (lengthFactor /= 1.0_dp) then
      Conduit(k_l)%modLength = lengthFactor * conduit_getLength(j_l)
      slope_l = slope_l / lengthFactor
      roughness = roughness / sqrt(lengthFactor)
   end if
   b4_ = RouteModel == DW
   if (b4_) then
      b4_ = Link(j_l)%xsect%type == FORCE_MAIN
   end if
   if (b4_) then
      Link(j_l)%xsect%sBot = forcemain_getRoughFactor(j_l, lengthFactor)
   end if
   Conduit(k_l)%roughFactor = 32.2_dp * ((roughness / 1.486_dp) * (roughness / 1.486_dp))
   if (Link(j_l)%xsect%type == DUMMY) then
      Conduit(k_l)%beta = 0.0_dp
   else
      Conduit(k_l)%beta = (1.486_dp * sqrt(abs(slope_l))) / roughness
   end if
   Link(j_l)%qFull = Link(j_l)%xsect%sFull * Conduit(k_l)%beta
   Conduit(k_l)%qMax = Link(j_l)%xsect%sMax * Conduit(k_l)%beta
   aa = ((Conduit(k_l)%beta / sqrt(32.2_dp)) * ((Link(j_l)%xsect%yFull) ** 0.1666667_dp)) * 0.3_dp
   if (aa >= 1.0_dp) then
      Conduit(k_l)%superCritical = 1
   else
      Conduit(k_l)%superCritical = 0
   end if
   b5_ = Link(j_l)%cLossInlet == 0.0_dp
   if (b5_) then
      b5_ = Link(j_l)%cLossOutlet == 0.0_dp
   end if
   b6_ = b5_
   if (b6_) then
      b6_ = Link(j_l)%cLossAvg == 0.0_dp
   end if
   if (b6_) then
      Conduit(k_l)%hasLosses = 0
   else
      Conduit(k_l)%hasLosses = 1
   end if
end subroutine conduit_validate

! link.c:1158
recursive subroutine conduit_reverse(j_l, k_l)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   integer(int32) :: i_l
   real(dp) :: z_l
   real(dp) :: cLoss
   i_l = 0
   z_l = 0.0_dp
   cLoss = 0.0_dp
   i_l = Link(j_l)%node1
   Link(j_l)%node1 = Link(j_l)%node2
   Link(j_l)%node2 = i_l
   z_l = Link(j_l)%offset1
   Link(j_l)%offset1 = Link(j_l)%offset2
   Link(j_l)%offset2 = z_l
   cLoss = Link(j_l)%cLossInlet
   Link(j_l)%cLossInlet = Link(j_l)%cLossOutlet
   Link(j_l)%cLossOutlet = cLoss
   Conduit(k_l)%slope = -Conduit(k_l)%slope
   Link(j_l)%direction = Link(j_l)%direction * (-1)
   Link(j_l)%q0 = -Link(j_l)%q0
end subroutine conduit_reverse

! link.c:1195
recursive function conduit_getLength(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: t_l
   logical :: b1_
   res_ = 0.0_dp
   k_l = Link(j_l)%subIndex
   t_l = 0
   if (Link(j_l)%xsect%type /= IRREGULAR) then
      res_ = Conduit(k_l)%length
      return
   end if
   t_l = Link(j_l)%xsect%transect
   b1_ = t_l < 0
   if (.not. b1_) then
      b1_ = t_l >= Nobjects(TRANSECT_c)
   end if
   if (b1_) then
      res_ = Conduit(k_l)%length
      return
   end if
   res_ = Conduit(k_l)%length / Transect(t_l)%lengthFactor
   return
end function conduit_getLength

! link.c:1217
recursive function conduit_getLengthFactor(j_l, k_l, roughness) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp), value :: roughness
   real(dp) :: res_
   real(dp) :: ratio
   real(dp) :: yFull
   real(dp) :: vFull
   real(dp) :: tStep
   res_ = 0.0_dp
   ratio = 0.0_dp
   yFull = 0.0_dp
   vFull = 0.0_dp
   tStep = 0.0_dp
   yFull = Link(j_l)%xsect%yFull
   if (xsect_isOpen(Link(j_l)%xsect%type) /= 0) then
      yFull = Link(j_l)%xsect%aFull / xsect_getWofY(Link(j_l)%xsect, yFull)
   end if
   vFull = (((1.486_dp / roughness) * Link(j_l)%xsect%sFull) * sqrt(abs(Conduit(k_l)%slope))) / Link(j_l)%xsect%aFull
   if (LengtheningStep == 0.0_dp) then
      tStep = RouteStep
   else
      tStep = merge(RouteStep, LengtheningStep, (RouteStep) <= (LengtheningStep))
   end if
   ratio = ((sqrt(32.2_dp * yFull) + vFull) * tStep) / conduit_getLength(j_l)
   if (ratio > 1.0_dp) then
      res_ = ratio
      return
   else
      res_ = 1.0_dp
      return
   end if
end function conduit_getLengthFactor

! link.c:1258
recursive function conduit_getSlope(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   real(dp) :: elev1
   real(dp) :: elev2
   real(dp) :: delta
   real(dp) :: slope_l
   real(dp) :: length_l
   res_ = 0.0_dp
   elev1 = 0.0_dp
   elev2 = 0.0_dp
   delta = 0.0_dp
   slope_l = 0.0_dp
   length_l = conduit_getLength(j_l)
   elev1 = Link(j_l)%offset1 + Node(Link(j_l)%node1)%invertElev
   elev2 = Link(j_l)%offset2 + Node(Link(j_l)%node2)%invertElev
   delta = abs(elev1 - elev2)
   if (delta < MIN_DELTA_Z) then
      call report_writeWarningMsg(lit_308, Link(j_l)%ID)
      delta = MIN_DELTA_Z
   end if
   if (delta >= length_l) then
      call report_writeWarningMsg(lit_309, Link(j_l)%ID)
      slope_l = delta / length_l
   else
      slope_l = delta / sqrt(((length_l) * (length_l)) - ((delta) * (delta)))
   end if
   if ((MinSlope > 0.0_dp) .and. (slope_l < MinSlope)) then
      call report_writeWarningMsg(lit_310, Link(j_l)%ID)
      slope_l = MinSlope
      if ((RouteModel == SF) .or. (RouteModel == KW)) then
         res_ = slope_l
         return
      end if
   end if
   if (elev1 < elev2) then
      slope_l = -slope_l
   end if
   res_ = slope_l
   return
end function conduit_getSlope

