   Link(j_l)%newDepth = link_getYnorm(j_l, Link(j_l)%q0 / real(Conduit(k_l)%barrels, dp))
   Link(j_l)%oldDepth = Link(j_l)%newDepth
   Conduit(k_l)%evapLossRate = 0.0_dp
   Conduit(k_l)%seepLossRate = 0.0_dp
end subroutine conduit_initState

! link.c:1320
recursive function conduit_getInflow(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   real(dp) :: qIn
   real(dp) :: v1_
   res_ = 0.0_dp
   qIn = node_getOutflow(Link(j_l)%node1, j_l)
   if (Link(j_l)%qLimit > 0.0_dp) then
      if ((qIn) <= (Link(j_l)%qLimit)) then
         v1_ = qIn
      else
         v1_ = Link(j_l)%qLimit
      end if
      qIn = v1_
   end if
   res_ = qIn
   return
end function conduit_getInflow

! link.c:1334
recursive function conduit_getLossRate(j_l, routeModel_l, q_l, tstep) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: routeModel_l
   real(dp), value :: q_l
   real(dp), value :: tstep
   real(dp) :: res_
   type(TXsect), pointer :: xsect_l
   real(dp) :: depth
   real(dp) :: length_l
   real(dp) :: width_l
   real(dp) :: topWidth
   real(dp) :: evapLossRate
   real(dp) :: seepLossRate
   real(dp) :: totalLossRate
   res_ = 0.0_dp
   nullify(xsect_l)
   depth = 0.5_dp * (Link(j_l)%oldDepth + Link(j_l)%newDepth)
   length_l = 0.0_dp
   width_l = 0.0_dp
   topWidth = 0.0_dp
   evapLossRate = 0.0_dp
   seepLossRate = 0.0_dp
   totalLossRate = 0.0_dp
   if (depth > 0.0001_dp) then
      xsect_l => Link(j_l)%xsect
      length_l = conduit_getLength(j_l)
      if ((xsect_isOpen(xsect_l%type) /= 0) .and. (Evap%rate > 0.0_dp)) then
         topWidth = xsect_getWofY(xsect_l, depth)
         evapLossRate = (topWidth * length_l) * Evap%rate
      end if
      if (Link(j_l)%seepRate > 0.0_dp) then
         if (xsect_l%type == RECT_CLOSED) then
            width_l = xsect_l%wMax
         else
            if (depth >= xsect_l%ywMax) then
               depth = xsect_l%ywMax
            end if
            width_l = xsect_getWofY(xsect_l, depth)
         end if
         seepLossRate = (Link(j_l)%seepRate * width_l) * length_l
         seepLossRate = seepLossRate * Adjust%hydconFactor
      end if
      totalLossRate = evapLossRate + seepLossRate
      if (routeModel_l == DW) then
         q_l = Link(j_l)%newVolume / tstep
      else
         q_l = merge(-(q_l), q_l, (q_l) < 0.0_dp)
      end if
      if (totalLossRate > q_l) then
         evapLossRate = (evapLossRate * q_l) / totalLossRate
         seepLossRate = (seepLossRate * q_l) / totalLossRate
         totalLossRate = q_l
      end if
   end if
   Conduit(Link(j_l)%subIndex)%evapLossRate = evapLossRate
   Conduit(Link(j_l)%subIndex)%seepLossRate = seepLossRate
   res_ = totalLossRate
   return
end function conduit_getLossRate

! link.c:1406
recursive function pump_readParams(j_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: m_l
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp), target :: x_l(0:3)
   type(CPtr) :: id
   logical :: b1_
   logical :: b2_
   res_ = 0
   m_l = 0
   n1 = 0
   n2 = 0
   x_l = 0.0_dp
   id = cnull()
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(LINK_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   n1 = project_findObject(NODE_c, tok_l(1))
   if (n1 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   n2 = project_findObject(NODE_c, tok_l(2))
   if (n2 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   x_l(0) = -1.0_dp
   if (ntoks >= 4) then
      if (.not. (strcomp(tok_l(3), lit_275) /= 0)) then
         m_l = project_findObject(CURVE_c, tok_l(3))
         if (m_l < 0) then
            res_ = error_setInpError(ERR_NAME, tok_l(3))
            return
         end if
         x_l(0) = real(m_l, dp)
      end if
   end if
   x_l(1) = 1.0_dp
   if (ntoks >= 5) then
      m_l = findmatch(tok_l(4), OffOnWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(4))
         return
      end if
      x_l(1) = real(m_l, dp)
   end if
   x_l(2) = 0.0_dp
   if (ntoks >= 6) then
      b1_ = .not. (getDouble(tok_l(5), x_l(2)) /= 0)
      if (.not. b1_) then
         b1_ = x_l(2) < 0.0_dp
      end if
      if (b1_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
   end if
   x_l(3) = 0.0_dp
   if (ntoks >= 7) then
      b2_ = .not. (getDouble(tok_l(6), x_l(3)) /= 0)
      if (.not. b2_) then
         b2_ = x_l(3) < 0.0_dp
      end if
      if (b2_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(6))
         return
      end if
   end if
   Link(j_l)%ID = id
   call link_setParams(j_l, PUMP_c, n1, n2, k_l, x_l)
   res_ = 0
   return
end function pump_readParams

! link.c:1473
recursive subroutine pump_validate(j_l, k_l)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   integer(int32) :: m_l
   integer(int32) :: n1
   real(dp), target :: x_l
   real(dp), target :: y_l
   logical :: b1_
   real(dp) :: v2_
   logical :: b3_
   real(dp) :: v4_
   m_l = 0
   n1 = 0
   x_l = 0.0_dp
   y_l = 0.0_dp
   Link(j_l)%xsect%yFull = 0.0_dp
   m_l = Pump(k_l)%pumpCurve
   if (m_l < 0) then
      Pump(k_l)%type = IDEAL_PUMP
   else
      b1_ = Curve(m_l)%curveType < PUMP1_CURVE
      if (.not. b1_) then
         b1_ = Curve(m_l)%curveType > PUMP5_CURVE
      end if
      if (b1_) then
         call report_writeErrorMsg(ERR_NO_CURVE, Link(j_l)%ID)
      else
         Pump(k_l)%type = Curve(m_l)%curveType - PUMP1_CURVE
         if (table_getFirstEntry(Curve(m_l), x_l, y_l) /= 0) then
            Link(j_l)%qFull = y_l
            Pump(k_l)%xMin = x_l
            Pump(k_l)%xMax = x_l
            do while (table_getNextEntry(Curve(m_l), x_l, y_l) /= 0)
               if ((y_l) >= (Link(j_l)%qFull)) then
                  v2_ = y_l
               else
                  v2_ = Link(j_l)%qFull
               end if
               Link(j_l)%qFull = v2_
               Pump(k_l)%xMax = x_l
            end do
         end if
         Link(j_l)%qFull = Link(j_l)%qFull / UCF(FLOW)
      end if
   end if
   b3_ = Pump(k_l)%yOn > 0.0_dp
   if (b3_) then
      b3_ = Pump(k_l)%yOn <= Pump(k_l)%yOff
   end if
   if (b3_) then
      call report_writeErrorMsg(ERR_PUMP_LIMITS, Link(j_l)%ID)
   end if
   if (Pump(k_l)%type == TYPE1_PUMP) then
      n1 = Link(j_l)%node1
      if (Node(n1)%type /= STORAGE_c) then
         if ((Node(n1)%fullVolume) >= (Pump(k_l)%xMax / UCF(VOLUME))) then
            v4_ = Node(n1)%fullVolume
         else
            v4_ = Pump(k_l)%xMax / UCF(VOLUME)
         end if
         Node(n1)%fullVolume = v4_
      end if
   end if
end subroutine pump_validate

