! link.c:1548
recursive function pump_getInflow(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: m_l
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp) :: vol
   real(dp) :: depth
   real(dp) :: head
   real(dp) :: qIn
   real(dp) :: qIn1
   real(dp) :: dh
   real(dp) :: s_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0.0_dp
   k_l = 0
   m_l = 0
   n1 = 0
   n2 = 0
   vol = 0.0_dp
   depth = 0.0_dp
   head = 0.0_dp
   qIn = 0.0_dp
   qIn1 = 0.0_dp
   dh = 0.001_dp
   s_l = 1.0_dp
   k_l = Link(j_l)%subIndex
   m_l = Pump(k_l)%pumpCurve
   n1 = Link(j_l)%node1
   n2 = Link(j_l)%node2
   Link(j_l)%flowClass = NO
   Link(j_l)%setting = Link(j_l)%targetSetting
   if (Link(j_l)%setting == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (Pump(k_l)%type == IDEAL_PUMP) then
      qIn = Node(n1)%inflow + Node(n1)%overflow
   else
      select case (Curve(m_l)%curveType)
      case (7)
         vol = Node(n1)%newVolume * UCF(VOLUME)
         qIn = table_intervalLookup(Curve(m_l), vol) / UCF(FLOW)
         b1_ = vol < Pump(k_l)%xMin
         if (.not. b1_) then
            b1_ = vol > Pump(k_l)%xMax
         end if
         if (b1_) then
            Link(j_l)%flowClass = YES
         end if
      case (8)
         depth = Node(n1)%newDepth * UCF(LENGTH)
         qIn = table_intervalLookup(Curve(m_l), depth) / UCF(FLOW)
         b2_ = depth < Pump(k_l)%xMin
         if (.not. b2_) then
            b2_ = depth > Pump(k_l)%xMax
         end if
         if (b2_) then
            Link(j_l)%flowClass = YES
         end if
      case (9, 11)
         if (Curve(m_l)%curveType == PUMP5_CURVE) then
            s_l = Link(j_l)%setting
         end if
         head = (((Node(n2)%newDepth + Node(n2)%invertElev) - (Node(n1)%newDepth + Node(n1)%invertElev)) / s_l) / s_l
         head = (merge(head, 0.0_dp, (head) >= (0.0_dp))) * UCF(LENGTH)
         qIn = table_lookup(Curve(m_l), head) / UCF(FLOW)
         Link(j_l)%dqdh = (((-table_getSlope(Curve(m_l), head)) * UCF(LENGTH)) / UCF(FLOW)) / s_l
         b3_ = head < Pump(k_l)%xMin
         if (.not. b3_) then
            b3_ = head > Pump(k_l)%xMax
         end if
         if (b3_) then
            Link(j_l)%flowClass = YES
         end if
      case (10)
         depth = Node(n1)%newDepth
         qIn = table_lookup(Curve(m_l), depth * UCF(LENGTH)) / UCF(FLOW)
         qIn1 = table_lookup(Curve(m_l), (depth + dh) * UCF(LENGTH)) / UCF(FLOW)
         Link(j_l)%dqdh = (qIn1 - qIn) / dh
         depth = depth * UCF(LENGTH)
         if (depth < Pump(k_l)%xMin) then
            Link(j_l)%flowClass = DN_DRY
         end if
         if (depth > Pump(k_l)%xMax) then
            Link(j_l)%flowClass = UP_DRY
         end if
      case default
         qIn = 0.0_dp
      end select
   end if
   if (qIn < 0.0_dp) then
      qIn = 0.0_dp
   end if
   res_ = qIn * Link(j_l)%setting
   return
end function pump_getInflow

! link.c:1641
recursive function orifice_readParams(j_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
