      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   n2 = project_findObject(NODE_c, tok_l(2))
   if (n2 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   m_l = findmatch(tok_l(3), OrificeTypeWords)
   if (m_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
      return
   end if
   x_l(0) = real(m_l, dp)
   b1_ = LinkOffsets == ELEV_OFFSET
   if (b1_) then
      b1_ = cget(tok_l(4), 0) == 42
   end if
   if (b1_) then
      x_l(1) = -10000000000.0_dp
   else if (.not. (getDouble(tok_l(4), x_l(1)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(4))
      return
   end if
   b2_ = .not. (getDouble(tok_l(5), x_l(2)) /= 0)
   if (.not. b2_) then
      b2_ = x_l(2) < 0.0_dp
   end if
   if (b2_) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(5))
      return
   end if
   x_l(3) = 0.0_dp
   if (ntoks >= 7) then
      m_l = findmatch(tok_l(6), NoYesWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(6))
         return
      end if
      x_l(3) = real(m_l, dp)
   end if
   x_l(4) = 0.0_dp
   if (ntoks >= 8) then
      b3_ = .not. (getDouble(tok_l(7), x_l(4)) /= 0)
      if (.not. b3_) then
         b3_ = x_l(4) < 0.0_dp
      end if
      if (b3_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(7))
         return
      end if
   end if
   Link(j_l)%ID = id
   call link_setParams(j_l, ORIFICE_c, n1, n2, k_l, x_l)
   res_ = 0
   return
end function orifice_readParams

! link.c:1696
recursive subroutine orifice_validate(j_l, k_l)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   integer(int32) :: err_l
   logical :: b1_
   real(dp) :: v2_
   err_l = 0
   b1_ = Link(j_l)%xsect%type /= RECT_CLOSED
   if (b1_) then
      b1_ = Link(j_l)%xsect%type /= CIRCULAR
   end if
   if (b1_) then
      err_l = ERR_REGULATOR_SHAPE
   end if
   if (err_l > 0) then
      call report_writeErrorMsg(err_l, Link(j_l)%ID)
      return
   end if
   if (Link(j_l)%offset1 < 0.0_dp) then
      Link(j_l)%offset1 = 0.0_dp
   end if
   call orifice_setSetting(j_l, 0.0_dp)
   Orifice(k_l)%length = (2.0_dp * RouteStep) * sqrt(32.2_dp * Link(j_l)%xsect%yFull)
   if ((200.0_dp) >= (Orifice(k_l)%length)) then
      v2_ = 200.0_dp
   else
      v2_ = Orifice(k_l)%length
   end if
   Orifice(k_l)%length = v2_
   Orifice(k_l)%surfArea = 0.0_dp
end subroutine orifice_validate

! link.c:1729
recursive subroutine orifice_setSetting(j_l, tstep)
   integer(int32), value :: j_l
   real(dp), value :: tstep
   integer(int32) :: k_l
   real(dp) :: delta
   real(dp) :: step
   real(dp) :: h_l
   real(dp) :: f_l
   k_l = Link(j_l)%subIndex
   delta = 0.0_dp
   step = 0.0_dp
   h_l = 0.0_dp
   f_l = 0.0_dp
   if ((Orifice(k_l)%orate == 0.0_dp) .or. (tstep == 0.0_dp)) then
      Link(j_l)%setting = Link(j_l)%targetSetting
   else
      delta = Link(j_l)%targetSetting - Link(j_l)%setting
      step = tstep / Orifice(k_l)%orate
      if ((step + 0.001_dp) >= abs(delta)) then
         Link(j_l)%setting = Link(j_l)%targetSetting
      else
         Link(j_l)%setting = Link(j_l)%setting + (real(merge(-1, 1, (delta) < 0.0_dp), dp) * step)
      end if
   end if
   h_l = Link(j_l)%setting * Link(j_l)%xsect%yFull
   f_l = xsect_getAofY(Link(j_l)%xsect, h_l) * sqrt(2.0_dp * 32.2_dp)
   Orifice(k_l)%cOrif = Orifice(k_l)%cDisch * f_l
   Orifice(k_l)%cWeir = orifice_getWeirCoeff(j_l, k_l, h_l) * f_l
end subroutine orifice_setSetting

! link.c:1766
recursive function orifice_getWeirCoeff(j_l, k_l, h_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp), value :: h_l
   real(dp) :: res_
   real(dp) :: w_l
   real(dp) :: aOverL
   res_ = 0.0_dp
   w_l = 0.0_dp
   aOverL = 0.0_dp
   if (Orifice(k_l)%type == BOTTOM_ORIFICE) then
      if (Link(j_l)%xsect%type == CIRCULAR) then
         aOverL = h_l / 4.0_dp
      else
         w_l = Link(j_l)%xsect%wMax
         aOverL = (h_l * w_l) / (2.0_dp * (h_l + w_l))
      end if
      h_l = (Orifice(k_l)%cDisch / 0.414_dp) * aOverL
      Orifice(k_l)%hCrit = h_l
   else
      Orifice(k_l)%hCrit = h_l
      h_l = h_l / 2.0_dp
   end if
   res_ = Orifice(k_l)%cDisch * sqrt(h_l)
   return
end function orifice_getWeirCoeff

! link.c:1812
recursive function orifice_getInflow(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp) :: head
   real(dp) :: h1
   real(dp) :: h2
   real(dp) :: y1
   real(dp) :: dir
   real(dp) :: f_l
   real(dp) :: hcrest
   real(dp) :: hcrown
   real(dp) :: hmidpt
   real(dp) :: q_l
   real(dp) :: ratio
   logical :: b1_
   res_ = 0.0_dp
   k_l = 0
   n1 = 0
   n2 = 0
   head = 0.0_dp
   h1 = 0.0_dp
   h2 = 0.0_dp
   y1 = 0.0_dp
   dir = 0.0_dp
   f_l = 0.0_dp
   hcrest = 0.0_dp
   hcrown = 0.0_dp
   hmidpt = 0.0_dp
   q_l = 0.0_dp
   ratio = 0.0_dp
   n1 = Link(j_l)%node1
   n2 = Link(j_l)%node2
   k_l = Link(j_l)%subIndex
   if (RouteModel == DW) then
      h1 = Node(n1)%newDepth + Node(n1)%invertElev
      h2 = Node(n2)%newDepth + Node(n2)%invertElev
   else
      h1 = Node(n1)%newDepth + Node(n1)%invertElev
      h2 = Node(n1)%invertElev
   end if
   dir = merge(1.0_dp, -1.0_dp, h1 >= h2)
   y1 = Node(n1)%newDepth
   if (dir < 0.0_dp) then
      head = h1
      h1 = h2
      h2 = head
      y1 = Node(n2)%newDepth
   end if
   if (Orifice(k_l)%type == BOTTOM_ORIFICE) then
      hcrest = Node(n1)%invertElev + Link(j_l)%offset1
      if (h1 < hcrest) then
         head = 0.0_dp
      else if (h2 > hcrest) then
         head = h1 - h2
      else
         head = h1 - hcrest
      end if
      f_l = head / Orifice(k_l)%hCrit
      f_l = merge(f_l, 1.0_dp, (f_l) <= (1.0_dp))
   else
      hcrest = Node(n1)%invertElev + Link(j_l)%offset1
      hcrown = hcrest + (Link(j_l)%xsect%yFull * Link(j_l)%setting)
      hmidpt = (hcrest + hcrown) / 2.0_dp
      if ((h1 < hcrown) .and. (hcrown > hcrest)) then
         f_l = (h1 - hcrest) / (hcrown - hcrest)
      else
         f_l = 1.0_dp
      end if
      if (f_l < 1.0_dp) then
         head = h1 - hcrest
      else if (h2 < hmidpt) then
         head = h1 - hmidpt
      else
         head = h1 - h2
      end if
   end if
   b1_ = (head <= 0.0001_dp) .or. (y1 <= 0.0001_dp)
   if (.not. b1_) then
      b1_ = link_setFlapGate(j_l, n1, n2, dir) /= 0
   end if
   if (b1_) then
      Link(j_l)%newDepth = 0.0_dp
      Link(j_l)%flowClass = DRY
      Orifice(k_l)%surfArea = 0.0001_dp * Orifice(k_l)%length
      Link(j_l)%dqdh = 0.0_dp
      res_ = 0.0_dp
      return
   end if
   Link(j_l)%flowClass = SUBCRITICAL
   if (hcrest > h2) then
      if (dir == 1.0_dp) then
         Link(j_l)%flowClass = DN_CRITICAL
      else
         Link(j_l)%flowClass = UP_CRITICAL
      end if
   end if
   y1 = Link(j_l)%xsect%yFull * Link(j_l)%setting
   if (Orifice(k_l)%type == SIDE_ORIFICE) then
      Link(j_l)%newDepth = y1 * f_l
      Orifice(k_l)%surfArea = xsect_getWofY(Link(j_l)%xsect, Link(j_l)%newDepth) * Orifice(k_l)%length
   else
      Link(j_l)%newDepth = y1
      Orifice(k_l)%surfArea = xsect_getAofY(Link(j_l)%xsect, y1)
   end if
   q_l = dir * orifice_getFlow(j_l, k_l, head, f_l, Link(j_l)%hasFlapGate)
   if ((f_l < 1.0_dp) .and. (h2 > hcrest)) then
      ratio = (h2 - hcrest) / (h1 - hcrest)
      q_l = q_l * ((1.0_dp - (ratio ** 1.5_dp)) ** 0.385_dp)
   end if
   res_ = q_l
   return
end function orifice_getInflow

! link.c:1938
recursive function orifice_getFlow(j_l, k_l, head, f_l, hasFlapGate) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp), value :: head
   real(dp), value :: f_l
   integer(int32), value :: hasFlapGate
   real(dp) :: res_
   real(dp) :: area_l
   real(dp) :: q_l
   real(dp) :: veloc
   real(dp) :: hLoss
   res_ = 0.0_dp
   area_l = 0.0_dp
   q_l = 0.0_dp
   veloc = 0.0_dp
   hLoss = 0.0_dp
   if ((head == 0.0_dp) .or. (f_l <= 0.0_dp)) then
      Link(j_l)%dqdh = 0.0_dp
      res_ = 0.0_dp
      return
   else if (f_l < 1.0_dp) then
      q_l = Orifice(k_l)%cWeir * (f_l ** 1.5_dp)
      Link(j_l)%dqdh = (1.5_dp * q_l) / (f_l * Orifice(k_l)%hCrit)
   else
      q_l = Orifice(k_l)%cOrif * sqrt(head)
      Link(j_l)%dqdh = q_l / (2.0_dp * head)
   end if
   if (hasFlapGate /= 0) then
      area_l = xsect_getAofY(Link(j_l)%xsect, Link(j_l)%setting * Link(j_l)%xsect%yFull)
      veloc = q_l / area_l
      hLoss = (((4.0_dp / 32.2_dp) * veloc) * veloc) * exp(((-1.15_dp) * veloc) / sqrt(head))
      if (f_l < 1.0_dp) then
         f_l = f_l - (hLoss / Orifice(k_l)%hCrit)
         if (f_l < 0.0_dp) then
            f_l = 0.0_dp
         end if
      else
         head = head - hLoss
         if (head < 0.0_dp) then
            head = 0.0_dp
         end if
      end if
      q_l = orifice_getFlow(j_l, k_l, head, f_l, 0)
   end if
   res_ = q_l
   return
end function orifice_getFlow

! link.c:2010
recursive function weir_readParams(j_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: m_l
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp), target :: x_l(0:9)
   type(CPtr) :: id
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   logical :: b6_
   logical :: b7_
   logical :: b8_
   logical :: b9_
   logical :: b10_
   res_ = 0
   m_l = 0
   n1 = 0
   n2 = 0
   x_l = 0.0_dp
   id = cnull()
   if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(LINK_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   n1 = project_findObject(NODE_c, tok_l(1))
   if (n1 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   n2 = project_findObject(NODE_c, tok_l(2))
   if (n2 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   m_l = findmatch(tok_l(3), WeirTypeWords)
   if (m_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
      return
   end if
   x_l(0) = real(m_l, dp)
   b1_ = LinkOffsets == ELEV_OFFSET
   if (b1_) then
      b1_ = cget(tok_l(4), 0) == 42
   end if
   if (b1_) then
      x_l(1) = -10000000000.0_dp
   else if (.not. (getDouble(tok_l(4), x_l(1)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(4))
      return
   end if
   b2_ = .not. (getDouble(tok_l(5), x_l(2)) /= 0)
   if (.not. b2_) then
      b2_ = x_l(2) < 0.0_dp
   end if
   if (b2_) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(5))
      return
   end if
   x_l(3) = 0.0_dp
   x_l(4) = 0.0_dp
   x_l(5) = 0.0_dp
   x_l(6) = 1.0_dp
   x_l(7) = 0.0_dp
   x_l(8) = 0.0_dp
   x_l(9) = -1.0_dp
   b3_ = ntoks >= 7
   if (b3_) then
      b3_ = cget(tok_l(6), 0) /= 42
   end if
   if (b3_) then
      m_l = findmatch(tok_l(6), NoYesWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(6))
         return
      end if
      x_l(3) = real(m_l, dp)
   end if
   b4_ = ntoks >= 8
   if (b4_) then
      b4_ = cget(tok_l(7), 0) /= 42
   end if
   if (b4_) then
      b5_ = .not. (getDouble(tok_l(7), x_l(4)) /= 0)
      if (.not. b5_) then
         b5_ = x_l(4) < 0.0_dp
      end if
      if (b5_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(7))
         return
      end if
   end if
   b6_ = ntoks >= 9
   if (b6_) then
      b6_ = cget(tok_l(8), 0) /= 42
   end if
   if (b6_) then
      b7_ = .not. (getDouble(tok_l(8), x_l(5)) /= 0)
      if (.not. b7_) then
         b7_ = x_l(5) < 0.0_dp
      end if
      if (b7_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(8))
         return
      end if
   end if
   b8_ = ntoks >= 10
   if (b8_) then
      b8_ = cget(tok_l(9), 0) /= 42
   end if
   if (b8_) then
      m_l = findmatch(tok_l(9), NoYesWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(9))
         return
      end if
      x_l(6) = real(m_l, dp)
   end if
   m_l = d2i(x_l(0))
   if ((m_l) == ROADWAY_WEIR) then
      if (ntoks >= 11) then
         b9_ = .not. (getDouble(tok_l(10), x_l(7)) /= 0)
         if (.not. b9_) then
            b9_ = x_l(7) < 0.0_dp
         end if
         if (b9_) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(10))
            return
         end if
      end if
      if (ntoks >= 12) then
         if (strcomp(tok_l(11), lit_311) /= 0) then
            x_l(8) = 1.0_dp
         else if (strcomp(tok_l(11), lit_312) /= 0) then
            x_l(8) = 2.0_dp
         end if
      end if
   end if
   b10_ = ntoks >= 13
   if (b10_) then
      b10_ = cget(tok_l(12), 0) /= 42
   end if
   if (b10_) then
      m_l = project_findObject(CURVE_c, tok_l(12))
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(12))
         return
      end if
      x_l(9) = real(m_l, dp)
   end if
   Link(j_l)%ID = id
   call link_setParams(j_l, WEIR_c, n1, n2, k_l, x_l)
   res_ = 0
   return
end function weir_readParams

! link.c:2103
recursive subroutine weir_validate(j_l, k_l)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   integer(int32) :: err_l
   real(dp) :: q_l
   real(dp), target :: q1
   real(dp), target :: q2
   real(dp) :: head
   real(dp) :: v1_
   err_l = 0
   q_l = 0.0_dp
   q1 = 0.0_dp
   q2 = 0.0_dp
   head = 0.0_dp
   select case (Weir(k_l)%type)
   case (0, 1, 4)
      if (Link(j_l)%xsect%type /= RECT_OPEN) then
         err_l = ERR_REGULATOR_SHAPE
      end if
      Weir(k_l)%slope = 0.0_dp
   case (2)
      if (Link(j_l)%xsect%type /= TRIANGULAR) then
         err_l = ERR_REGULATOR_SHAPE
      else
         Weir(k_l)%slope = Link(j_l)%xsect%sBot
      end if
   case (3)
      if (Link(j_l)%xsect%type /= TRAPEZOIDAL) then
         err_l = ERR_REGULATOR_SHAPE
      else
         Weir(k_l)%slope = Link(j_l)%xsect%sBot
      end if
   end select
   if (err_l > 0) then
      call report_writeErrorMsg(err_l, Link(j_l)%ID)
      return
   end if
   if (Link(j_l)%offset1 < 0.0_dp) then
      Link(j_l)%offset1 = 0.0_dp
   end if
   Weir(k_l)%length = (2.0_dp * RouteStep) * sqrt(32.2_dp * Link(j_l)%xsect%yFull)
   if ((200.0_dp) >= (Weir(k_l)%length)) then
      v1_ = 200.0_dp
   else
      v1_ = Weir(k_l)%length
   end if
   Weir(k_l)%length = v1_
   Weir(k_l)%surfArea = 0.0_dp
   head = Link(j_l)%xsect%yFull
   call weir_getFlow(j_l, k_l, head, 1.0_dp, 0, q1, q2)
   q_l = q1 + q2
   head = head / 2.0_dp
   Weir(k_l)%cSurcharge = q_l / sqrt(head)
end subroutine weir_validate

! link.c:2166
recursive subroutine weir_setSetting(j_l)
   integer(int32), value :: j_l
   integer(int32) :: k_l
   real(dp) :: h_l
   real(dp) :: q_l
   real(dp), target :: q1
   real(dp), target :: q2
   k_l = Link(j_l)%subIndex
   h_l = 0.0_dp
   q_l = 0.0_dp
   q1 = 0.0_dp
   q2 = 0.0_dp
   Link(j_l)%setting = Link(j_l)%targetSetting
   if (.not. (Weir(k_l)%canSurcharge /= 0)) then
      return
   end if
   if (Weir(k_l)%type == ROADWAY_WEIR) then
      return
   end if
   if (Link(j_l)%setting == 0.0_dp) then
      Weir(k_l)%cSurcharge = 0.0_dp
   else
      h_l = Link(j_l)%setting * Link(j_l)%xsect%yFull
      call weir_getFlow(j_l, k_l, h_l, 1.0_dp, 0, q1, q2)
      q_l = q1 + q2
      h_l = h_l / 2.0_dp
      Weir(k_l)%cSurcharge = q_l / sqrt(h_l)
   end if
end subroutine weir_setSetting

! link.c:2198
recursive function weir_getInflow(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: n1
   integer(int32) :: n2
   integer(int32) :: k_l
   real(dp), target :: q1
   real(dp), target :: q2
   real(dp) :: head
   real(dp) :: h1
   real(dp) :: h2
   real(dp) :: hcrest
   real(dp) :: hcrown
   real(dp) :: y_l
   real(dp) :: dir
   real(dp) :: ratio
   real(dp), target :: weirPower(0:3)
   logical :: b1_
   real(dp) :: v2_
   res_ = 0.0_dp
   n1 = 0
   n2 = 0
   k_l = 0
   q1 = 0.0_dp
   q2 = 0.0_dp
   head = 0.0_dp
   h1 = 0.0_dp
   h2 = 0.0_dp
   hcrest = 0.0_dp
   hcrown = 0.0_dp
   y_l = 0.0_dp
   dir = 0.0_dp
   ratio = 0.0_dp
   weirPower = 0.0_dp
   weirPower(0:3) = [1.5_dp, 5.0_dp / 3.0_dp, 2.5_dp, 1.5_dp]
   n1 = Link(j_l)%node1
   n2 = Link(j_l)%node2
   k_l = Link(j_l)%subIndex
   if (RouteModel == DW) then
      h1 = Node(n1)%newDepth + Node(n1)%invertElev
      h2 = Node(n2)%newDepth + Node(n2)%invertElev
   else
      h1 = Node(n1)%newDepth + Node(n1)%invertElev
      h2 = Node(n1)%invertElev
   end if
   dir = merge(1.0_dp, -1.0_dp, h1 > h2)
   if (dir < 0.0_dp) then
      head = h1
      h1 = h2
      h2 = head
   end if
   hcrest = Node(n1)%invertElev + Link(j_l)%offset1
   hcrown = hcrest + Link(j_l)%xsect%yFull
   if (Weir(k_l)%type == ROADWAY_WEIR) then
      res_ = roadway_getInflow(j_l, dir, hcrest, h1, h2)
      return
   end if
   hcrest = hcrest + ((1.0_dp - Link(j_l)%setting) * Link(j_l)%xsect%yFull)
   head = h1 - hcrest
   Link(j_l)%dqdh = 0.0_dp
   b1_ = (head <= 0.0001_dp) .or. (hcrest >= hcrown)
   if (.not. b1_) then
      b1_ = link_setFlapGate(j_l, n1, n2, dir) /= 0
   end if
   if (b1_) then
      Link(j_l)%newDepth = 0.0_dp
      Link(j_l)%flowClass = DRY
      res_ = 0.0_dp
      return
   end if
   Link(j_l)%flowClass = SUBCRITICAL
   if (hcrest > h2) then
      if (dir == 1.0_dp) then
         Link(j_l)%flowClass = DN_CRITICAL
      else
         Link(j_l)%flowClass = UP_CRITICAL
      end if
   end if
   y_l = Link(j_l)%xsect%yFull - (hcrown - (merge(h1, hcrown, (h1) <= (hcrown))))
   Weir(k_l)%surfArea = xsect_getWofY(Link(j_l)%xsect, y_l) * Weir(k_l)%length
   if (h1 >= hcrown) then
      if (Weir(k_l)%canSurcharge /= 0) then
         y_l = (hcrest + hcrown) / 2.0_dp
         if (h2 < y_l) then
            head = h1 - y_l
         else
            head = h1 - h2
         end if
         y_l = hcrown - hcrest
         q1 = weir_getOrificeFlow(j_l, head, y_l, Weir(k_l)%cSurcharge)
         Link(j_l)%newDepth = y_l
         res_ = dir * q1
         return
      else
         head = hcrown - hcrest
      end if
   end if
   call weir_getFlow(j_l, k_l, head, dir, Link(j_l)%hasFlapGate, q1, q2)
   if (h2 > hcrest) then
      ratio = (h2 - hcrest) / (h1 - hcrest)
      q1 = q1 * ((1.0_dp - (ratio ** (weirPower(Weir(k_l)%type)))) ** 0.385_dp)
      if (q2 > 0.0_dp) then
         q2 = q2 * ((1.0_dp - (ratio ** weirPower(VNOTCH_WEIR))) ** 0.385_dp)
      end if
   end if
   if ((h1 - hcrest) <= (Link(j_l)%xsect%yFull)) then
      v2_ = h1 - hcrest
   else
      v2_ = Link(j_l)%xsect%yFull
   end if
   Link(j_l)%newDepth = v2_
   res_ = dir * (q1 + q2)
   return
end function weir_getInflow

! link.c:2321
recursive subroutine weir_getFlow(j_l, k_l, head, dir, hasFlapGate, q1, q2)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp), value :: head
   real(dp), value :: dir
   integer(int32), value :: hasFlapGate
   real(dp), intent(inout), target :: q1
   real(dp), intent(inout), target :: q2
   real(dp) :: length_l
   real(dp) :: h_l
   real(dp) :: y_l
   real(dp) :: hLoss
   real(dp) :: area_l
   real(dp) :: veloc
   integer(int32) :: wType
   integer(int32) :: cdCurve
   real(dp) :: cDisch1
   logical :: b1_
   length_l = 0.0_dp
   h_l = 0.0_dp
   y_l = 0.0_dp
   hLoss = 0.0_dp
   area_l = 0.0_dp
   veloc = 0.0_dp
   wType = 0
   cdCurve = Weir(k_l)%cdCurve
   cDisch1 = Weir(k_l)%cDisch1
   q1 = 0.0_dp
   q2 = 0.0_dp
   Link(j_l)%dqdh = 0.0_dp
   if (head <= 0.0_dp) then
      return
   end if
   length_l = Link(j_l)%xsect%wMax * UCF(LENGTH)
   h_l = head * UCF(LENGTH)
   if (cdCurve >= 0) then
      cDisch1 = table_lookup(Curve(cdCurve), h_l)
   end if
   wType = Weir(k_l)%type
   b1_ = wType == VNOTCH_WEIR
   if (b1_) then
      b1_ = Link(j_l)%setting < 1.0_dp
   end if
   if (b1_) then
      wType = TRAPEZOIDAL_WEIR
   end if
   select case (wType)
   case (0)
      length_l = length_l - ((0.1_dp * Weir(k_l)%endCon) * h_l)
      length_l = merge(length_l, 0.0_dp, (length_l) >= (0.0_dp))
      q1 = (cDisch1 * length_l) * (h_l ** 1.5_dp)
   case (1)
      length_l = length_l - ((0.1_dp * Weir(k_l)%endCon) * h_l)
      length_l = merge(length_l, 0.0_dp, (length_l) >= (0.0_dp))
      if (dir < 0.0_dp) then
         q1 = (cDisch1 * length_l) * (h_l ** 1.5_dp)
      else
         q1 = (cDisch1 * (length_l ** 0.83_dp)) * (h_l ** 1.67_dp)
      end if
   case (2)
      q1 = (cDisch1 * Weir(k_l)%slope) * (h_l ** 2.5_dp)
   case (3)
      y_l = (1.0_dp - Link(j_l)%setting) * Link(j_l)%xsect%yFull
      length_l = xsect_getWofY(Link(j_l)%xsect, y_l) * UCF(LENGTH)
      q1 = (cDisch1 * length_l) * (h_l ** 1.5_dp)
      q2 = (Weir(k_l)%cDisch2 * Weir(k_l)%slope) * (h_l ** 2.5_dp)
   end select
   if (UnitSystem == SI) then
      q1 = q1 / 0.028317_dp
      q2 = q2 / 0.028317_dp
   end if
   if (hasFlapGate /= 0) then
      area_l = weir_getOpenArea(j_l, head)
      if (area_l > 1.0e-06_dp) then
         veloc = (q1 + q2) / area_l
         hLoss = (((4.0_dp / 32.2_dp) * veloc) * veloc) * exp(((-1.15_dp) * veloc) / sqrt(head))
         head = head - hLoss
         if (head < 0.0_dp) then
            head = 0.0_dp
         end if
         call weir_getFlow(j_l, k_l, head, dir, 0, q1, q2)
      end if
   end if
   Link(j_l)%dqdh = weir_getdqdh(k_l, dir, head, q1, q2)
end subroutine weir_getFlow

! link.c:2432
recursive function weir_getOrificeFlow(j_l, head, y_l, cOrif) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: head
   real(dp), value :: y_l
   real(dp), value :: cOrif
   real(dp) :: res_
   real(dp) :: a_l
   real(dp) :: q_l
   real(dp) :: v_l
   real(dp) :: hloss
   res_ = 0.0_dp
   a_l = 0.0_dp
   q_l = 0.0_dp
   v_l = 0.0_dp
   hloss = 0.0_dp
   q_l = cOrif * sqrt(head)
   if (Link(j_l)%hasFlapGate /= 0) then
      a_l = weir_getOpenArea(j_l, y_l)
      if (a_l > 0.0_dp) then
         v_l = q_l / a_l
         hloss = (((4.0_dp / 32.2_dp) * v_l) * v_l) * exp(((-1.15_dp) * v_l) / sqrt(y_l))
         head = head - hloss
         head = merge(head, 0.0_dp, (head) >= (0.0_dp))
         q_l = cOrif * sqrt(head)
      end if
   end if
   if (head > 0.0_dp) then
      Link(j_l)%dqdh = q_l / (2.0_dp * head)
   else
      Link(j_l)%dqdh = 0.0_dp
   end if
   res_ = q_l
   return
end function weir_getOrificeFlow

! link.c:2467
recursive function weir_getOpenArea(j_l, y_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: y_l
   real(dp) :: res_
   real(dp) :: z_l
   real(dp) :: zy
   real(dp) :: v1_
   res_ = 0.0_dp
   z_l = 0.0_dp
   zy = 0.0_dp
   z_l = (1.0_dp - Link(j_l)%setting) * Link(j_l)%xsect%yFull
   zy = z_l + y_l
   if ((zy) <= (Link(j_l)%xsect%yFull)) then
      v1_ = zy
   else
      v1_ = Link(j_l)%xsect%yFull
   end if
   zy = v1_
   res_ = xsect_getAofY(Link(j_l)%xsect, zy) - xsect_getAofY(Link(j_l)%xsect, z_l)
   return
end function weir_getOpenArea

! link.c:2492
recursive function weir_getdqdh(k_l, dir, h_l, q1, q2) result(res_)
   integer(int32), value :: k_l
   real(dp), value :: dir
   real(dp), value :: h_l
   real(dp), value :: q1
   real(dp), value :: q2
   real(dp) :: res_
   real(dp) :: q1h
   real(dp) :: q2h
   res_ = 0.0_dp
   q1h = 0.0_dp
   q2h = 0.0_dp
   if (abs(h_l) < 0.0001_dp) then
      res_ = 0.0_dp
      return
   end if
   q1h = abs(q1 / h_l)
   q2h = abs(q2 / h_l)
   select case (Weir(k_l)%type)
   case (0)
      res_ = 1.5_dp * q1h
      return
   case (1)
      if (dir < 0.0_dp) then
         res_ = 1.5_dp * q1h
         return
      else
         res_ = 1.67_dp * q1h
         return
      end if
   case (2)
      if (q2h == 0.0_dp) then
         res_ = 2.5_dp * q1h
         return
      else
         res_ = (1.5_dp * q1h) + (2.5_dp * q2h)
         return
      end if
   case (3)
      res_ = (1.5_dp * q1h) + (2.5_dp * q2h)
      return
   end select
   res_ = 0.0_dp
   return
end function weir_getdqdh

! link.c:2524
recursive function outlet_readParams(j_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: m_l
   integer(int32) :: n_l
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp), target :: x_l(0:5)
   type(CPtr) :: id
   type(CPtr) :: s_l
   logical :: b1_
   logical :: b2_
   res_ = 0
   i_l = 0
   m_l = 0
   n_l = 0
   n1 = 0
   n2 = 0
   x_l = 0.0_dp
   id = cnull()
   s_l = cnull()
   if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(LINK_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   n1 = project_findObject(NODE_c, tok_l(1))
   if (n1 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   n2 = project_findObject(NODE_c, tok_l(2))
   if (n2 < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(2))
      return
   end if
   b1_ = LinkOffsets == ELEV_OFFSET
   if (b1_) then
      b1_ = cget(tok_l(3), 0) == 42
   end if
   if (b1_) then
      x_l(0) = -10000000000.0_dp
   else
      if (.not. (getDouble(tok_l(3), x_l(0)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(3))
         return
      end if
      b2_ = LinkOffsets == DEPTH_OFFSET
      if (b2_) then
         b2_ = x_l(0) < 0.0_dp
      end if
      if (b2_) then
         x_l(0) = 0.0_dp
      end if
   end if
   m_l = findmatch(tok_l(4), RelationWords)
   if (m_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(4))
      return
   end if
   x_l(1) = 0.0_dp
   x_l(2) = 0.0_dp
   x_l(3) = -1.0_dp
   x_l(4) = 0.0_dp
   x_l(5) = real(NODE_DEPTH, dp)
   s_l = c_strtok(tok_l(4), lit_313)
   s_l = c_strtok(cnull(), lit_313)
   if (strcomp(s_l, lit_314) /= 0) then
      x_l(5) = real(NODE_HEAD, dp)
   end if
   if (m_l == FUNCTIONAL) then
      if (ntoks < 7) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (.not. (getDouble(tok_l(5), x_l(1)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
      if (.not. (getDouble(tok_l(6), x_l(2)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(6))
         return
      end if
      n_l = 7
   else
      i_l = project_findObject(CURVE_c, tok_l(5))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(5))
         return
      end if
      x_l(3) = real(i_l, dp)
      n_l = 6
   end if
   if (ntoks > n_l) then
      i_l = findmatch(tok_l(n_l), NoYesWords)
      if (i_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l))
         return
      end if
      x_l(4) = real(i_l, dp)
   end if
   Link(j_l)%ID = id
   call link_setParams(j_l, OUTLET_c, n1, n2, k_l, x_l)
   res_ = 0
   return
end function outlet_readParams

! link.c:2608
recursive function outlet_getInflow(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: n1
   integer(int32) :: n2
   real(dp) :: head
   real(dp) :: hcrest
   real(dp) :: h1
   real(dp) :: h2
   real(dp) :: y1
   real(dp) :: dir
   logical :: b1_
   res_ = 0.0_dp
   k_l = 0
   n1 = 0
   n2 = 0
   head = 0.0_dp
   hcrest = 0.0_dp
   h1 = 0.0_dp
   h2 = 0.0_dp
   y1 = 0.0_dp
   dir = 0.0_dp
   n1 = Link(j_l)%node1
   n2 = Link(j_l)%node2
   k_l = Link(j_l)%subIndex
   if (RouteModel == DW) then
      h1 = Node(n1)%newDepth + Node(n1)%invertElev
      h2 = Node(n2)%newDepth + Node(n2)%invertElev
   else
      h1 = Node(n1)%newDepth + Node(n1)%invertElev
      h2 = Node(n1)%invertElev
   end if
   dir = merge(1.0_dp, -1.0_dp, h1 >= h2)
   y1 = Node(n1)%newDepth
   if (dir < 0.0_dp) then
      y1 = h1
      h1 = h2
      h2 = y1
      y1 = Node(n2)%newDepth
   end if
   hcrest = Node(n1)%invertElev + Link(j_l)%offset1
   if ((Outlet(k_l)%curveType == NODE_HEAD) .and. (RouteModel == DW)) then
      head = h1 - (merge(h2, hcrest, (h2) >= (hcrest)))
   else
      head = h1 - hcrest
   end if
   b1_ = (head <= 0.0001_dp) .or. (y1 <= 0.0001_dp)
   if (.not. b1_) then
      b1_ = link_setFlapGate(j_l, n1, n2, dir) /= 0
   end if
   if (b1_) then
      Link(j_l)%newDepth = 0.0_dp
      Link(j_l)%flowClass = DRY
      res_ = 0.0_dp
      return
   end if
   Link(j_l)%newDepth = head
   Link(j_l)%flowClass = SUBCRITICAL
   res_ = (dir * Link(j_l)%setting) * outlet_getFlow(k_l, head)
   return
end function outlet_getInflow

! link.c:2672
recursive function outlet_getFlow(k_l, head) result(res_)
   integer(int32), value :: k_l
   real(dp), value :: head
   real(dp) :: res_
   integer(int32) :: m_l
   real(dp) :: h_l
   res_ = 0.0_dp
   m_l = 0
   h_l = 0.0_dp
   h_l = head * UCF(LENGTH)
   m_l = Outlet(k_l)%qCurve
   if (m_l >= 0) then
      res_ = table_lookup(Curve(m_l), h_l) / UCF(FLOW)
      return
   else
      res_ = (Outlet(k_l)%qCoeff * (h_l ** (Outlet(k_l)%qExpon))) / UCF(FLOW)
      return
   end if
end function outlet_getFlow

! massbal.c:100
recursive function massbal_open() result(res_)
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: n_l
   res_ = 0
   j_l = 0
   n_l = 0
   RunoffError = 0.0_dp
   GwaterError = 0.0_dp
   FlowError = 0.0_dp
   QualError = 0.0_dp
   RunoffTotals%rainfall = 0.0_dp
   RunoffTotals%evap = 0.0_dp
   RunoffTotals%infil = 0.0_dp
   RunoffTotals%runoff = 0.0_dp
   RunoffTotals%runon = 0.0_dp
   RunoffTotals%drains = 0.0_dp
   RunoffTotals%snowRemoved = 0.0_dp
   RunoffTotals%initStorage = 0.0_dp
   RunoffTotals%initSnowCover = 0.0_dp
   TotalArea = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      RunoffTotals%initStorage = RunoffTotals%initStorage + subcatch_getStorage(j_l)
      RunoffTotals%initSnowCover = RunoffTotals%initSnowCover + snow_getSnowCover(j_l)
      TotalArea = TotalArea + Subcatch(j_l)%area
      j_l = j_l + 1
   end do
   GwaterTotals%infil = 0.0_dp
   GwaterTotals%upperEvap = 0.0_dp
   GwaterTotals%lowerEvap = 0.0_dp
   GwaterTotals%lowerPerc = 0.0_dp
   GwaterTotals%gwater = 0.0_dp
   GwaterTotals%initStorage = 0.0_dp
   GwaterTotals%finalStorage = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      GwaterTotals%initStorage = GwaterTotals%initStorage + (gwater_getVolume(j_l) * Subcatch(j_l)%area)
      j_l = j_l + 1
   end do
   FlowTotals%dwInflow = 0.0_dp
   FlowTotals%wwInflow = 0.0_dp
   FlowTotals%gwInflow = 0.0_dp
   FlowTotals%iiInflow = 0.0_dp
   FlowTotals%exInflow = 0.0_dp
   FlowTotals%flooding = 0.0_dp
   FlowTotals%outflow = 0.0_dp
   FlowTotals%evapLoss = 0.0_dp
   FlowTotals%seepLoss = 0.0_dp
   FlowTotals%reacted = 0.0_dp
   FlowTotals%initStorage = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      FlowTotals%initStorage = FlowTotals%initStorage + Node(j_l)%newVolume
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      FlowTotals%initStorage = FlowTotals%initStorage + Link(j_l)%newVolume
      j_l = j_l + 1
   end do
   StepFlowTotals = FlowTotals
   nullify(LoadingTotals)
   nullify(QualTotals)
   nullify(StepQualTotals)
   nullify(NodeInflow)
   nullify(NodeOutflow)
   n_l = Nobjects(POLLUT_c)
   if (n_l > 0) then
      allocate(LoadingTotals(0:int(n_l, int64) - 1))
      if (.not. associated(LoadingTotals)) then
         call report_writeErrorMsg(ERR_MEMORY, lit_0)
         res_ = ErrorCode
         return
      end if
      j_l = 0
      do while (j_l < n_l)
         LoadingTotals(j_l)%initLoad = massbal_getBuildup(j_l)
         LoadingTotals(j_l)%buildup = 0.0_dp
         LoadingTotals(j_l)%deposition = 0.0_dp
         LoadingTotals(j_l)%sweeping = 0.0_dp
         LoadingTotals(j_l)%infil = 0.0_dp
         LoadingTotals(j_l)%bmpRemoval = 0.0_dp
         LoadingTotals(j_l)%runoff = 0.0_dp
         LoadingTotals(j_l)%finalLoad = 0.0_dp
         j_l = j_l + 1
      end do
   end if
   if (n_l > 0) then
      allocate(QualTotals(0:int(n_l, int64) - 1))
      allocate(StepQualTotals(0:int(n_l, int64) - 1))
      if ((.not. associated(QualTotals)) .or. (.not. associated(StepQualTotals))) then
         call report_writeErrorMsg(ERR_MEMORY, lit_0)
         res_ = ErrorCode
         return
      end if
   end if
   j_l = 0
   do while (j_l < n_l)
      QualTotals(j_l)%dwInflow = 0.0_dp
      QualTotals(j_l)%wwInflow = 0.0_dp
      QualTotals(j_l)%gwInflow = 0.0_dp
      QualTotals(j_l)%exInflow = 0.0_dp
      QualTotals(j_l)%flooding = 0.0_dp
      QualTotals(j_l)%outflow = 0.0_dp
      QualTotals(j_l)%evapLoss = 0.0_dp
      QualTotals(j_l)%seepLoss = 0.0_dp
      QualTotals(j_l)%reacted = 0.0_dp
      QualTotals(j_l)%initStorage = massbal_getStoredMass(j_l)
      j_l = j_l + 1
   end do
   call massbal_initTimeStepTotals()
   if (Nobjects(NODE_c) > 0) then
      allocate(NodeInflow(0:(int(Nobjects(NODE_c), int64)) - 1))
      NodeInflow = 0.0_dp
      if (.not. associated(NodeInflow)) then
         call report_writeErrorMsg(ERR_MEMORY, lit_0)
         res_ = ErrorCode
         return
      end if
      allocate(NodeOutflow(0:(int(Nobjects(NODE_c), int64)) - 1))
      NodeOutflow = 0.0_dp
      if (.not. associated(NodeOutflow)) then
         call report_writeErrorMsg(ERR_MEMORY, lit_0)
         res_ = ErrorCode
         return
      end if
      j_l = 0
      do while (j_l < Nobjects(NODE_c))
         NodeInflow(j_l) = Node(j_l)%newVolume
         j_l = j_l + 1
      end do
   end if
   res_ = ErrorCode
   return
end function massbal_open

