! massbal.c:262
recursive subroutine massbal_report()
   integer(int32) :: j_l
   real(dp) :: gwArea
   j_l = 0
   gwArea = 0.0_dp
   if (Nobjects(SUBCATCH_c) > 0) then
      if ((massbal_getRunoffError() > MAX_RUNOFF_BALANCE_ERR) .or. (RptFlags%continuity == 1)) then
         call report_writeRunoffError(RunoffTotals, TotalArea)
      end if
      if ((Nobjects(POLLUT_c) > 0) .and. (.not. (IgnoreQuality /= 0))) then
         if ((massbal_getLoadingError() > MAX_RUNOFF_BALANCE_ERR) .or. (RptFlags%continuity == 1)) then
            call report_writeLoadingError(LoadingTotals)
         end if
      end if
   end if
   if ((Nobjects(AQUIFER_c) > 0) .and. (.not. (IgnoreGwater /= 0))) then
      if ((massbal_getGwaterError() > MAX_RUNOFF_BALANCE_ERR) .or. (RptFlags%continuity == 1)) then
         j_l = 0
         do while (j_l < Nobjects(SUBCATCH_c))
            if (associated(Subcatch(j_l)%groundwater)) then
               gwArea = gwArea + Subcatch(j_l)%area
            end if
            j_l = j_l + 1
         end do
         if (gwArea > 0.0_dp) then
            call report_writeGwaterError(GwaterTotals, gwArea)
         end if
      end if
   end if
   if ((Nobjects(NODE_c) > 0) .and. (.not. (IgnoreRouting /= 0))) then
      if ((massbal_getFlowError() > MAX_FLOW_BALANCE_ERR) .or. (RptFlags%continuity == 1)) then
         call report_writeFlowError(FlowTotals)
      end if
      if ((Nobjects(POLLUT_c) > 0) .and. (.not. (IgnoreQuality /= 0))) then
         if ((massbal_getQualError() > MAX_FLOW_BALANCE_ERR) .or. (RptFlags%continuity == 1)) then
            call report_writeQualError(QualTotals)
         end if
      end if
   end if
end subroutine massbal_report

! massbal.c:316
recursive function massbal_getBuildup(p_l) result(res_)
   integer(int32), value :: p_l
   real(dp) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   real(dp) :: load
   res_ = 0.0_dp
   i_l = 0
   j_l = 0
   load = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      i_l = 0
      do while (i_l < Nobjects(LANDUSE_c))
         load = load + Subcatch(j_l)%landFactor(i_l)%buildup(p_l)
         i_l = i_l + 1
      end do
      load = load + (Subcatch(j_l)%pondedQual(p_l) * Pollut(p_l)%mcf)
      j_l = j_l + 1
   end do
   res_ = load
   return
end function massbal_getBuildup

! massbal.c:339
recursive subroutine massbal_updateRunoffTotals(flowType, v_l)
   integer(int32), value :: flowType
   real(dp), value :: v_l
   select case (flowType)
   case (0)
      RunoffTotals%rainfall = RunoffTotals%rainfall + v_l
   case (1)
      RunoffTotals%evap = RunoffTotals%evap + v_l
   case (2)
      RunoffTotals%infil = RunoffTotals%infil + v_l
   case (3)
      RunoffTotals%runoff = RunoffTotals%runoff + v_l
   case (4)
      RunoffTotals%drains = RunoffTotals%drains + v_l
   case (5)
      RunoffTotals%runon = RunoffTotals%runon + v_l
   end select
end subroutine massbal_updateRunoffTotals

! massbal.c:360
recursive subroutine massbal_updateGwaterTotals(vInfil_l, vUpperEvap, vLowerEvap, vLowerPerc, vGwater)
   real(dp), value :: vInfil_l
   real(dp), value :: vUpperEvap
   real(dp), value :: vLowerEvap
   real(dp), value :: vLowerPerc
   real(dp), value :: vGwater
   GwaterTotals%infil = GwaterTotals%infil + vInfil_l
   GwaterTotals%upperEvap = GwaterTotals%upperEvap + vUpperEvap
