! massbal.c:587
recursive subroutine massbal_updateRoutingTotals(tStep)
   real(dp), value :: tStep
   integer(int32) :: j_l
   logical :: b1_
   logical :: b2_
   j_l = 0
   FlowTotals%dwInflow = FlowTotals%dwInflow + (StepFlowTotals%dwInflow * tStep)
   FlowTotals%wwInflow = FlowTotals%wwInflow + (StepFlowTotals%wwInflow * tStep)
   FlowTotals%gwInflow = FlowTotals%gwInflow + (StepFlowTotals%gwInflow * tStep)
   FlowTotals%iiInflow = FlowTotals%iiInflow + (StepFlowTotals%iiInflow * tStep)
   FlowTotals%exInflow = FlowTotals%exInflow + (StepFlowTotals%exInflow * tStep)
   FlowTotals%flooding = FlowTotals%flooding + (StepFlowTotals%flooding * tStep)
   FlowTotals%outflow = FlowTotals%outflow + (StepFlowTotals%outflow * tStep)
   FlowTotals%evapLoss = FlowTotals%evapLoss + (StepFlowTotals%evapLoss * tStep)
   FlowTotals%seepLoss = FlowTotals%seepLoss + (StepFlowTotals%seepLoss * tStep)
   j_l = 0
   do while (j_l < Nobjects(POLLUT_c))
      QualTotals(j_l)%dwInflow = QualTotals(j_l)%dwInflow + (StepQualTotals(j_l)%dwInflow * tStep)
      QualTotals(j_l)%wwInflow = QualTotals(j_l)%wwInflow + (StepQualTotals(j_l)%wwInflow * tStep)
      QualTotals(j_l)%gwInflow = QualTotals(j_l)%gwInflow + (StepQualTotals(j_l)%gwInflow * tStep)
      QualTotals(j_l)%iiInflow = QualTotals(j_l)%iiInflow + (StepQualTotals(j_l)%iiInflow * tStep)
      QualTotals(j_l)%exInflow = QualTotals(j_l)%exInflow + (StepQualTotals(j_l)%exInflow * tStep)
      QualTotals(j_l)%flooding = QualTotals(j_l)%flooding + (StepQualTotals(j_l)%flooding * tStep)
      QualTotals(j_l)%outflow = QualTotals(j_l)%outflow + (StepQualTotals(j_l)%outflow * tStep)
      QualTotals(j_l)%reacted = QualTotals(j_l)%reacted + (StepQualTotals(j_l)%reacted * tStep)
      QualTotals(j_l)%seepLoss = QualTotals(j_l)%seepLoss + (StepQualTotals(j_l)%seepLoss * tStep)
      QualTotals(j_l)%finalStorage = QualTotals(j_l)%finalStorage + StepQualTotals(j_l)%finalStorage
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      NodeInflow(j_l) = NodeInflow(j_l) + (Node(j_l)%inflow * tStep)
      b2_ = Node(j_l)%type == OUTFALL_c
      if (.not. b2_) then
         b1_ = Node(j_l)%degree == 0
         if (b1_) then
            b1_ = Node(j_l)%type /= STORAGE_c
         end if
         b2_ = b1_
      end if
      if (b2_) then
         NodeOutflow(j_l) = NodeOutflow(j_l) + (Node(j_l)%inflow * tStep)
      else
         NodeOutflow(j_l) = NodeOutflow(j_l) + (Node(j_l)%outflow * tStep)
         if (Node(j_l)%newVolume <= Node(j_l)%fullVolume) then
            NodeOutflow(j_l) = NodeOutflow(j_l) + (Node(j_l)%overflow * tStep)
         end if
      end if
      j_l = j_l + 1
   end do
end subroutine massbal_updateRoutingTotals

! massbal.c:638
recursive function massbal_getStorage(isFinalStorage) result(res_)
   integer(int32), value :: isFinalStorage
   real(dp) :: res_
   integer(int32) :: j_l
   real(dp) :: totalStorage
   real(dp) :: nodeStorage
   res_ = 0.0_dp
   j_l = 0
   totalStorage = 0.0_dp
   nodeStorage = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      nodeStorage = Node(j_l)%newVolume
      if (isFinalStorage /= 0) then
         NodeOutflow(j_l) = NodeOutflow(j_l) + nodeStorage
      end if
      totalStorage = totalStorage + nodeStorage
      j_l = j_l + 1
   end do
   if ((isFinalStorage /= 0) .and. (RouteModel == SF)) then
      res_ = totalStorage
      return
   end if
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      totalStorage = totalStorage + Link(j_l)%newVolume
      j_l = j_l + 1
   end do
   res_ = totalStorage
   return
end function massbal_getStorage

! massbal.c:670
recursive subroutine massbal_getSysFlows(f_l, sysFlows)
   real(dp), value :: f_l
   real(dp), pointer, intent(in) :: sysFlows(:)
   real(dp) :: f1
   f1 = 1.0_dp - f_l
   sysFlows(SYS_DWFLOW) = ((f1 * OldStepFlowTotals%dwInflow) + (f_l * StepFlowTotals%dwInflow)) * UCF(FLOW)
   sysFlows(SYS_GWFLOW) = ((f1 * OldStepFlowTotals%gwInflow) + (f_l * StepFlowTotals%gwInflow)) * UCF(FLOW)
   sysFlows(SYS_IIFLOW) = ((f1 * OldStepFlowTotals%iiInflow) + (f_l * StepFlowTotals%iiInflow)) * UCF(FLOW)
   sysFlows(SYS_EXFLOW) = ((f1 * OldStepFlowTotals%exInflow) + (f_l * StepFlowTotals%exInflow)) * UCF(FLOW)
   sysFlows(SYS_FLOODING) = ((f1 * OldStepFlowTotals%flooding) + (f_l * StepFlowTotals%flooding)) * UCF(FLOW)
   sysFlows(SYS_OUTFLOW) = ((f1 * OldStepFlowTotals%outflow) + (f_l * StepFlowTotals%outflow)) * UCF(FLOW)
   sysFlows(SYS_STORAGE) = ((f1 * OldStepFlowTotals%finalStorage) + (f_l * StepFlowTotals%finalStorage)) * UCF(VOLUME)
end subroutine massbal_getSysFlows

! massbal.c:696
recursive function massbal_getRunoffError() result(res_)
   real(dp) :: res_
   integer(int32) :: j_l
   real(dp) :: totalInflow
   real(dp) :: totalOutflow
   res_ = 0.0_dp
   j_l = 0
   totalInflow = 0.0_dp
   totalOutflow = 0.0_dp
   RunoffTotals%finalStorage = 0.0_dp
   RunoffTotals%finalSnowCover = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      RunoffTotals%finalStorage = RunoffTotals%finalStorage + subcatch_getStorage(j_l)
      RunoffTotals%finalSnowCover = RunoffTotals%finalSnowCover + snow_getSnowCover(j_l)
      j_l = j_l + 1
   end do
   RunoffTotals%snowRemoved = Snow%removed
   totalInflow = ((RunoffTotals%rainfall + RunoffTotals%runon) + RunoffTotals%initStorage) + RunoffTotals%initSnowCover
   totalOutflow = (((((RunoffTotals%evap + RunoffTotals%infil) + RunoffTotals%runoff) + RunoffTotals%drains) + RunoffTotals%snowRemoved) + RunoffTotals%finalStorage) + RunoffTotals%finalSnowCover
   RunoffTotals%pctError = 0.0_dp
   if (abs(totalInflow - totalOutflow) < 1.0_dp) then
      RunoffTotals%pctError = 1.0e-06_dp
   else if (totalInflow > 0.0_dp) then
      RunoffTotals%pctError = 100.0_dp * (1.0_dp - (totalOutflow / totalInflow))
   else if (totalOutflow > 0.0_dp) then
      RunoffTotals%pctError = 100.0_dp * ((totalInflow / totalOutflow) - 1.0_dp)
   end if
   RunoffError = RunoffTotals%pctError
   res_ = RunoffTotals%pctError
   return
end function massbal_getRunoffError

! massbal.c:750
recursive function massbal_getLoadingError() result(res_)
   real(dp) :: res_
   integer(int32) :: j_l
   real(dp) :: loadIn
   real(dp) :: loadOut
   real(dp) :: maxError
   real(dp) :: v1_
   real(dp) :: v2_
   real(dp) :: v3_
   real(dp) :: v4_
   real(dp) :: v5_
   real(dp) :: v6_
   real(dp) :: v7_
   real(dp) :: v8_
   real(dp) :: v9_
   res_ = 0.0_dp
   j_l = 0
   loadIn = 0.0_dp
   loadOut = 0.0_dp
   maxError = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(POLLUT_c))
      LoadingTotals(j_l)%finalLoad = LoadingTotals(j_l)%finalLoad + massbal_getBuildup(j_l)
      loadIn = (LoadingTotals(j_l)%initLoad + LoadingTotals(j_l)%buildup) + LoadingTotals(j_l)%deposition
      loadOut = (((LoadingTotals(j_l)%sweeping + LoadingTotals(j_l)%infil) + LoadingTotals(j_l)%bmpRemoval) + LoadingTotals(j_l)%runoff) + LoadingTotals(j_l)%finalLoad
      LoadingTotals(j_l)%pctError = 0.0_dp
      if (abs(loadIn - loadOut) < 0.001_dp) then
         LoadingTotals(j_l)%pctError = 1.0e-06_dp
      else if (loadIn > 0.0_dp) then
         LoadingTotals(j_l)%pctError = 100.0_dp * (1.0_dp - (loadOut / loadIn))
      else if (loadOut > 0.0_dp) then
         LoadingTotals(j_l)%pctError = 100.0_dp * ((loadIn / loadOut) - 1.0_dp)
      end if
      if ((maxError) >= (LoadingTotals(j_l)%pctError)) then
         v1_ = maxError
      else
         v1_ = LoadingTotals(j_l)%pctError
      end if
      maxError = v1_
      if (Pollut(j_l)%units == COUNT_c) then
         if ((LoadingTotals(j_l)%initLoad) > 0.0_dp) then
            v2_ = log10(LoadingTotals(j_l)%initLoad)
         else
            v2_ = LoadingTotals(j_l)%initLoad
         end if
         LoadingTotals(j_l)%initLoad = v2_
         if ((LoadingTotals(j_l)%buildup) > 0.0_dp) then
            v3_ = log10(LoadingTotals(j_l)%buildup)
         else
            v3_ = LoadingTotals(j_l)%buildup
         end if
         LoadingTotals(j_l)%buildup = v3_
         if ((LoadingTotals(j_l)%deposition) > 0.0_dp) then
            v4_ = log10(LoadingTotals(j_l)%deposition)
         else
            v4_ = LoadingTotals(j_l)%deposition
         end if
         LoadingTotals(j_l)%deposition = v4_
         if ((LoadingTotals(j_l)%sweeping) > 0.0_dp) then
            v5_ = log10(LoadingTotals(j_l)%sweeping)
         else
            v5_ = LoadingTotals(j_l)%sweeping
         end if
         LoadingTotals(j_l)%sweeping = v5_
         if ((LoadingTotals(j_l)%infil) > 0.0_dp) then
            v6_ = log10(LoadingTotals(j_l)%infil)
         else
            v6_ = LoadingTotals(j_l)%infil
         end if
         LoadingTotals(j_l)%infil = v6_
         if ((LoadingTotals(j_l)%bmpRemoval) > 0.0_dp) then
            v7_ = log10(LoadingTotals(j_l)%bmpRemoval)
         else
            v7_ = LoadingTotals(j_l)%bmpRemoval
         end if
         LoadingTotals(j_l)%bmpRemoval = v7_
         if ((LoadingTotals(j_l)%runoff) > 0.0_dp) then
            v8_ = log10(LoadingTotals(j_l)%runoff)
         else
            v8_ = LoadingTotals(j_l)%runoff
         end if
         LoadingTotals(j_l)%runoff = v8_
         if ((LoadingTotals(j_l)%finalLoad) > 0.0_dp) then
            v9_ = log10(LoadingTotals(j_l)%finalLoad)
         else
            v9_ = LoadingTotals(j_l)%finalLoad
         end if
         LoadingTotals(j_l)%finalLoad = v9_
      end if
      j_l = j_l + 1
   end do
   res_ = maxError
   return
end function massbal_getLoadingError

