! massbal.c:858
recursive function massbal_getFlowError() result(res_)
   real(dp) :: res_
   real(dp) :: totalInflow
   real(dp) :: totalOutflow
   res_ = 0.0_dp
   totalInflow = 0.0_dp
   totalOutflow = 0.0_dp
   FlowTotals%finalStorage = massbal_getStorage(1)
   totalInflow = (FlowTotals%initStorage + FlowTotals%wwInflow) + FlowTotals%iiInflow
   totalOutflow = (((FlowTotals%finalStorage + FlowTotals%flooding) + FlowTotals%evapLoss) + FlowTotals%seepLoss) + FlowTotals%reacted
   if (FlowTotals%dwInflow >= 0.0_dp) then
      totalInflow = totalInflow + FlowTotals%dwInflow
   else
      totalOutflow = totalOutflow - FlowTotals%dwInflow
   end if
   if (FlowTotals%gwInflow >= 0.0_dp) then
      totalInflow = totalInflow + FlowTotals%gwInflow
   else
      totalOutflow = totalOutflow - FlowTotals%gwInflow
   end if
   if (FlowTotals%exInflow >= 0.0_dp) then
      totalInflow = totalInflow + FlowTotals%exInflow
   else
      totalOutflow = totalOutflow - FlowTotals%exInflow
   end if
   if (FlowTotals%outflow >= 0.0_dp) then
      totalOutflow = totalOutflow + FlowTotals%outflow
   else
      totalInflow = totalInflow - FlowTotals%outflow
   end if
   FlowTotals%pctError = 0.0_dp
   if (abs(totalInflow - totalOutflow) < 1.0_dp) then
      FlowTotals%pctError = 1.0e-06_dp
   else if (abs(totalInflow) > 0.0_dp) then
      FlowTotals%pctError = 100.0_dp * (1.0_dp - (totalOutflow / totalInflow))
   else if (abs(totalOutflow) > 0.0_dp) then
      FlowTotals%pctError = 100.0_dp * ((totalInflow / totalOutflow) - 1.0_dp)
   end if
   FlowError = FlowTotals%pctError
   res_ = FlowTotals%pctError
   return
end function massbal_getFlowError

! massbal.c:906
recursive function massbal_getQualError() result(res_)
   real(dp) :: res_
   integer(int32) :: p_l
   real(dp) :: maxQualError
   real(dp) :: totalInflow
   real(dp) :: totalOutflow
   real(dp) :: cf
