      totalInflow = ((((QualTotals(p_l)%dwInflow + QualTotals(p_l)%wwInflow) + QualTotals(p_l)%gwInflow) + QualTotals(p_l)%iiInflow) + QualTotals(p_l)%exInflow) + QualTotals(p_l)%initStorage
      totalOutflow = (((QualTotals(p_l)%flooding + QualTotals(p_l)%outflow) + QualTotals(p_l)%reacted) + QualTotals(p_l)%seepLoss) + QualTotals(p_l)%finalStorage
      QualTotals(p_l)%pctError = 0.0_dp
