            v2_ = cf * QualTotals(p_l)%wwInflow
         end if
         QualTotals(p_l)%wwInflow = v2_
         if ((cf * QualTotals(p_l)%gwInflow) > 0.0_dp) then
            v3_ = log10(cf * QualTotals(p_l)%gwInflow)
         else
            v3_ = cf * QualTotals(p_l)%gwInflow
