! massbal.c:995
recursive function massbal_getStepFlowError() result(res_)
   real(dp) :: res_
   real(dp) :: totalInflow
   real(dp) :: totalOutflow
   res_ = 0.0_dp
   totalInflow = 0.0_dp
   totalOutflow = 0.0_dp
   totalInflow = (((StepFlowTotals%dwInflow + StepFlowTotals%wwInflow) + StepFlowTotals%gwInflow) + StepFlowTotals%iiInflow) + StepFlowTotals%exInflow
   totalOutflow = (((StepFlowTotals%flooding + StepFlowTotals%outflow) + StepFlowTotals%evapLoss) + StepFlowTotals%seepLoss) + StepFlowTotals%reacted
   if (abs(totalInflow) > 0.0_dp) then
      res_ = 1.0_dp - (totalOutflow / totalInflow)
      return
   else if (abs(totalOutflow) > 0.0_dp) then
      res_ = (totalInflow / totalOutflow) - 1.0_dp
      return
   else
      res_ = 0.0_dp
      return
   end if
end function massbal_getStepFlowError

! massbal.c:1025
recursive function massbal_getStoredMass(p_l) result(res_)
   integer(int32), value :: p_l
   real(dp) :: res_
   integer(int32) :: j_l
   real(dp) :: storedMass
   res_ = 0.0_dp
   j_l = 0
   storedMass = 0.0_dp
