   logical :: b4_
   logical :: b5_
   logical :: b6_
   logical :: b7_
   logical :: b8_
   res_ = 0.0_dp
   call cinit(c_l, lit_33)
   sNumber = 0_int8
   errflag = 0
   decimalCount = 0
   sNumber(0) = c8(0)
   do
      b1_ = Pos_c < Len_c
      if (b1_) then
         b1_ = isDigit(cget(S_c, Pos_c)) /= 0
      end if
      if (.not. b1_) exit
      c_l(0) = c8(cget(S_c, Pos_c))
      dum2_ = c_strcat(cview(sNumber), cview(c_l))
