   end do
   if (Pos_c < Len_c) then
      if (cget(S_c, Pos_c) == 46) then
         decimalCount = decimalCount + 1
         if (decimalCount > 1) then
            Err = 1
         end if
         dum2_ = c_strcat(cview(sNumber), lit_315)
         Pos_c = Pos_c + 1
