         else
            b6_ = cget(S_c, Pos_c) == 45
            if (.not. b6_) then
               b6_ = cget(S_c, Pos_c) == 43
            end if
            if (b6_) then
               c_l(0) = c8(cget(S_c, Pos_c))
               dum2_ = c_strcat(cview(sNumber), cview(c_l))
               Pos_c = Pos_c + 1
            end if
            b7_ = Pos_c >= Len_c
            if (.not. b7_) then
               b7_ = .not. (isDigit(cget(S_c, Pos_c)) /= 0)
            end if
            if (b7_) then
               errflag = 1
            else
               do
                  b8_ = Pos_c < Len_c
                  if (b8_) then
                     b8_ = isDigit(cget(S_c, Pos_c)) /= 0
                  end if
                  if (.not. b8_) exit
                  c_l(0) = c8(cget(S_c, Pos_c))
