! mathexpr.c:252
recursive function getOperand() result(res_)
   integer(int32) :: res_
   integer(int32) :: code
   logical :: b1_
   res_ = 0
   code = 0
   select case (cget(S_c, Pos_c))
   case (40)
      code = 1
   case (41)
      code = 2
   case (43)
      code = 3
   case (45)
      code = 4
      b1_ = Pos_c < (Len_c - 1)
      if (b1_) then
         b1_ = isDigit(cget(S_c, Pos_c + 1)) /= 0
      end if
      if (b1_ .and. ((CurLex <= 6) .or. (CurLex == 31))) then
         Pos_c = Pos_c + 1
         Fvalue = -getNumber()
         code = 7
      end if
   case (42)
      code = 5
   case (47)
      code = 6
   case (94)
      code = 31
   case default
      code = 0
   end select
   res_ = code
   return
end function getOperand

! mathexpr.c:280
recursive function getLex() result(res_)
   integer(int32) :: res_
   integer(int32) :: n_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0
   n_l = 0
   do
      b1_ = Pos_c < Len_c
      if (b1_) then
         b1_ = cget(S_c, Pos_c) == 32
      end if
      if (.not. b1_) exit
      Pos_c = Pos_c + 1
   end do
   if (Pos_c >= Len_c) then
      res_ = 0
      return
   end if
   n_l = getOperand()
   if (n_l == 0) then
      if (isLetter(cget(S_c, Pos_c)) /= 0) then
         call getToken()
         n_l = getMathFunc()
         if (n_l == 0) then
            n_l = getVariable()
         end if
      else
         b3_ = cget(S_c, Pos_c) == 46
         if (.not. b3_) then
            b3_ = isDigit(cget(S_c, Pos_c)) /= 0
         end if
         if (b3_) then
            n_l = 7
            Fvalue = getNumber()
         end if
      end if
   end if
   Pos_c = Pos_c + 1
   PrevLex = CurLex
   CurLex = n_l
   res_ = n_l
   return
end function getLex

! mathexpr.c:314
recursive function newNode() result(res_)
   type(ExprTree), pointer :: res_
   type(ExprTree), pointer :: node_l
   nullify(res_)
   nullify(node_l)
   allocate(node_l)
   if (.not. associated(node_l)) then
      Err = 2
   else
      node_l%opcode = 0
      node_l%ivar = -1
      node_l%fvalue = 0.0_dp
      nullify(node_l%left)
      nullify(node_l%right)
   end if
   res_ => node_l
   return
end function newNode

! mathexpr.c:332
recursive function getSingleOp(lex) result(res_)
   integer(int32), intent(inout), target :: lex
   type(ExprTree), pointer :: res_
   integer(int32) :: opcode
   type(ExprTree), pointer :: left_l
   type(ExprTree), pointer :: node_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   nullify(res_)
   opcode = 0
   nullify(left_l)
   nullify(node_l)
   if (lex == 1) then
      Bc = Bc + 1
      left_l => getTree()
   else
      b1_ = lex < 7
      if (.not. b1_) then
         b1_ = lex == 9
      end if
      b2_ = b1_
      if (.not. b2_) then
         b2_ = lex > 30
      end if
      if (b2_) then
         Err = 1
         nullify(res_)
         return
      end if
      opcode = lex
      b3_ = lex == 7
      if (.not. b3_) then
         b3_ = lex == 8
      end if
      if (b3_) then
         left_l => newNode()
         left_l%opcode = opcode
         if (lex == 7) then
            left_l%fvalue = Fvalue
         end if
         if (lex == 8) then
            left_l%ivar = Ivar
         end if
      else
         lex = getLex()
         if (lex /= 1) then
            Err = 1
            nullify(res_)
            return
         end if
         Bc = Bc + 1
         left_l => newNode()
         left_l%left => getTree()
         left_l%opcode = opcode
      end if
   end if
   lex = getLex()
   if (lex == 31) then
      node_l => newNode()
      node_l%left => left_l
      node_l%opcode = lex
      lex = getLex()
      node_l%right => getSingleOp(lex)
      left_l => node_l
   end if
   res_ => left_l
   return
end function getSingleOp

! mathexpr.c:397
recursive function getOp(lex) result(res_)
   integer(int32), intent(inout), target :: lex
   type(ExprTree), pointer :: res_
   integer(int32) :: opcode
   type(ExprTree), pointer :: left_l
   type(ExprTree), pointer :: right
   type(ExprTree), pointer :: node_l
   integer(int32) :: neg_l
   logical :: b1_
   nullify(res_)
   opcode = 0
   nullify(left_l)
   nullify(right)
   nullify(node_l)
   neg_l = 0
   lex = getLex()
   if ((PrevLex == 0) .or. (PrevLex == 1)) then
      if (lex == 4) then
         neg_l = 1
         lex = getLex()
      else if (lex == 3) then
         lex = getLex()
      end if
   end if
   left_l => getSingleOp(lex)
   do
      b1_ = lex == 5
      if (.not. b1_) then
         b1_ = lex == 6
      end if
      if (.not. b1_) exit
      opcode = lex
      lex = getLex()
      right => getSingleOp(lex)
      node_l => newNode()
      if (Err /= 0) then
         nullify(res_)
         return
      end if
      node_l%left => left_l
      node_l%right => right
      node_l%opcode = opcode
      left_l => node_l
   end do
   if (neg_l /= 0) then
      node_l => newNode()
      if (Err /= 0) then
         nullify(res_)
         return
      end if
      node_l%left => left_l
      nullify(node_l%right)
      node_l%opcode = 9
      left_l => node_l
   end if
   res_ => left_l
   return
end function getOp

! mathexpr.c:442
recursive function getTree() result(res_)
   type(ExprTree), pointer :: res_
   integer(int32), target :: lex
   integer(int32) :: opcode
   type(ExprTree), pointer :: left_l
   type(ExprTree), pointer :: right
   type(ExprTree), pointer :: node_l
   nullify(res_)
   lex = 0
   opcode = 0
   nullify(left_l)
   nullify(right)
   nullify(node_l)
   left_l => getOp(lex)
   do
      if ((lex == 0) .or. (lex == 2)) then
         if (lex == 2) then
            Bc = Bc - 1
         end if
         exit
      end if
      if ((lex /= 3) .and. (lex /= 4)) then
         Err = 1
         exit
      end if
      opcode = lex
      right => getOp(lex)
      node_l => newNode()
      if (Err /= 0) then
         exit
      end if
      node_l%left => left_l
      node_l%right => right
      node_l%opcode = opcode
      left_l => node_l
   end do
   res_ => left_l
   return
end function getTree

! mathexpr.c:479
recursive subroutine traverseTree(tree, expr)
   type(ExprTree), pointer, intent(in) :: tree
   type(MathExpr), pointer :: expr
   type(MathExpr), pointer :: node_l
   nullify(node_l)
   if (.not. associated(tree)) then
      return
   end if
   call traverseTree(tree%left, expr)
   call traverseTree(tree%right, expr)
   allocate(node_l)
   if (associated(node_l)) then
      node_l%fvalue = tree%fvalue
      node_l%opcode = tree%opcode
      node_l%ivar = tree%ivar
      nullify(node_l%next)
      node_l%prev => expr
   end if
   if (associated(expr)) then
      expr%next => node_l
   end if
   expr => node_l
end subroutine traverseTree

! mathexpr.c:501
recursive subroutine deleteTree(tree)
   type(ExprTree), pointer, intent(in) :: tree
   if (associated(tree)) then
      if (associated(tree%left)) then
         call deleteTree(tree%left)
      end if
      if (associated(tree%right)) then
         call deleteTree(tree%right)
      end if
      ! free(tree)
   end if
end subroutine deleteTree

! mathexpr.c:516
recursive function mathexpr_eval(expr, getVariableValue_l) result(res_)
   type(MathExpr), pointer, intent(in) :: expr
   procedure(fp4) :: getVariableValue_l
   real(dp) :: res_
   real(dp), target :: ExprStack(0:1023)
   type(MathExpr), pointer :: node_l
   real(dp) :: r1
   real(dp) :: r2
   integer(int32) :: stackindex
   res_ = 0.0_dp
   ExprStack = 0.0_dp
   node_l => expr
   r1 = 0.0_dp
   r2 = 0.0_dp
   stackindex = 0
   ExprStack(0) = 0.0_dp
   do while ((.not. (.not. associated(node_l))) .and. (stackindex >= 0))
      select case (node_l%opcode)
      case (3)
         r1 = ExprStack(stackindex)
         stackindex = stackindex - 1
         if (stackindex < 0) then
            goto 100
         end if
         r2 = ExprStack(stackindex)
         ExprStack(stackindex) = r2 + r1
      case (4)
         r1 = ExprStack(stackindex)
         stackindex = stackindex - 1
         if (stackindex < 0) then
            goto 100
         end if
         r2 = ExprStack(stackindex)
         ExprStack(stackindex) = r2 - r1
      case (5)
         r1 = ExprStack(stackindex)
         stackindex = stackindex - 1
         if (stackindex < 0) then
            goto 100
         end if
         r2 = ExprStack(stackindex)
         ExprStack(stackindex) = r2 * r1
      case (6)
         r1 = ExprStack(stackindex)
         stackindex = stackindex - 1
         if (stackindex < 0) then
            goto 100
         end if
         r2 = ExprStack(stackindex)
         ExprStack(stackindex) = r2 / r1
      case (7)
         stackindex = stackindex + 1
         if (stackindex >= 1024) then
            goto 100
         end if
         ExprStack(stackindex) = node_l%fvalue
      case (8)
         if (.not. .false.) then
            r1 = getVariableValue_l(node_l%ivar)
         else
            r1 = 0.0_dp
         end if
         stackindex = stackindex + 1
         if (stackindex >= 1024) then
            goto 100
         end if
         ExprStack(stackindex) = r1
      case (9)
         ExprStack(stackindex) = -ExprStack(stackindex)
      case (10)
         r1 = ExprStack(stackindex)
         r2 = cos(r1)
         ExprStack(stackindex) = r2
      case (11)
         r1 = ExprStack(stackindex)
         r2 = sin(r1)
         ExprStack(stackindex) = r2
      case (12)
         r1 = ExprStack(stackindex)
         r2 = tan(r1)
         ExprStack(stackindex) = r2
      case (13)
         r1 = ExprStack(stackindex)
         if (r1 == 0.0_dp) then
            r2 = 0.0_dp
         else
            r2 = 1.0_dp / tan(r1)
         end if
         ExprStack(stackindex) = r2
      case (14)
         r1 = ExprStack(stackindex)
         r2 = abs(r1)
         ExprStack(stackindex) = r2
      case (15)
         r1 = ExprStack(stackindex)
         if (r1 < 0.0_dp) then
            r2 = -1.0_dp
         else if (r1 > 0.0_dp) then
            r2 = 1.0_dp
         else
            r2 = 0.0_dp
         end if
         ExprStack(stackindex) = r2
      case (16)
         r1 = ExprStack(stackindex)
         if (r1 < 0.0_dp) then
            r2 = 0.0_dp
         else
            r2 = sqrt(r1)
         end if
         ExprStack(stackindex) = r2
      case (17)
         r1 = ExprStack(stackindex)
         if (r1 <= 0.0_dp) then
            r2 = 0.0_dp
         else
            r2 = log(r1)
         end if
         ExprStack(stackindex) = r2
      case (18)
         r1 = ExprStack(stackindex)
         r2 = exp(r1)
         ExprStack(stackindex) = r2
      case (19)
         r1 = ExprStack(stackindex)
         r2 = asin(r1)
         ExprStack(stackindex) = r2
      case (20)
         r1 = ExprStack(stackindex)
         r2 = acos(r1)
         ExprStack(stackindex) = r2
      case (21)
         r1 = ExprStack(stackindex)
         r2 = atan(r1)
         ExprStack(stackindex) = r2
      case (22)
         r1 = ExprStack(stackindex)
         r2 = 1.57079632679489661923_dp - atan(r1)
         ExprStack(stackindex) = r2
      case (23)
         r1 = ExprStack(stackindex)
         r2 = (exp(r1) - exp(-r1)) / 2.0_dp
         ExprStack(stackindex) = r2
      case (24)
         r1 = ExprStack(stackindex)
         r2 = (exp(r1) + exp(-r1)) / 2.0_dp
         ExprStack(stackindex) = r2
      case (25)
         r1 = ExprStack(stackindex)
         r2 = (exp(r1) - exp(-r1)) / (exp(r1) + exp(-r1))
         ExprStack(stackindex) = r2
      case (26)
         r1 = ExprStack(stackindex)
         r2 = (exp(r1) + exp(-r1)) / (exp(r1) - exp(-r1))
         ExprStack(stackindex) = r2
      case (27)
         r1 = ExprStack(stackindex)
         if (r1 == 0.0_dp) then
            r2 = 0.0_dp
         else
            r2 = log10(r1)
         end if
         ExprStack(stackindex) = r2
      case (28)
         r1 = ExprStack(stackindex)
         if (r1 <= 0.0_dp) then
            r2 = 0.0_dp
         else
            r2 = 1.0_dp
         end if
         ExprStack(stackindex) = r2
      case (31)
         r1 = ExprStack(stackindex)
         stackindex = stackindex - 1
         if (stackindex < 0) then
            goto 100
         end if
         r2 = ExprStack(stackindex)
         if (r2 <= 0.0_dp) then
            r2 = 0.0_dp
         else
            r2 = r2 ** r1
         end if
         ExprStack(stackindex) = r2
      end select
      100 continue
      node_l => node_l%next
   end do
   if (stackindex >= 0) then
      r1 = ExprStack(stackindex)
   else
      r1 = 0.0_dp
   end if
   if (r1 /= r1) then
      r1 = 0.0_dp
   end if
   res_ = r1
   return
end function mathexpr_eval

! mathexpr.c:735
recursive subroutine mathexpr_delete(expr)
   type(MathExpr), pointer, intent(in) :: expr
   if (associated(expr)) then
      call mathexpr_delete(expr%next)
   end if
   ! free(expr)
end subroutine mathexpr_delete

! mathexpr.c:743
recursive function mathexpr_create(formula, getVar) result(res_)
   type(CPtr), value :: formula
   procedure(fp3) :: getVar
   type(MathExpr), pointer :: res_
   type(ExprTree), pointer :: tree
   type(MathExpr), pointer :: expr
   type(MathExpr), pointer :: result_l
   nullify(res_)
   nullify(tree)
   nullify(expr)
   nullify(result_l)
   mathexpr_getVariableIndex => getVar
   Err = 0
   PrevLex = 0
   CurLex = 0
   S_c = formula
   Len_c = int(strlen(S_c), int32)
   Pos_c = 0
   Bc = 0
   tree => getTree()
   if ((Bc == 0) .and. (Err == 0)) then
      call traverseTree(tree, expr)
      do while (associated(expr))
         result_l => expr
         expr => expr%prev
      end do
   end if
   call deleteTree(tree)
   res_ => result_l
   return
end function mathexpr_create

! node.c:102
recursive function node_readParams(j_l, type_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: type_l
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   res_ = 0
   select case (type_l)
   case (0)
      res_ = junc_readParams(j_l, k_l, tok_l, ntoks)
      return
   case (1)
      res_ = outfall_readParams(j_l, k_l, tok_l, ntoks)
      return
   case (2)
      res_ = storage_readParams(j_l, k_l, tok_l, ntoks)
      return
   case (3)
      res_ = divider_readParams(j_l, k_l, tok_l, ntoks)
      return
   case default
      res_ = 0
      return
   end select
end function node_readParams

! node.c:125
recursive subroutine node_setParams(j_l, type_l, k_l, x_l)
   integer(int32), value :: j_l
   integer(int32), value :: type_l
   integer(int32), value :: k_l
   real(dp), pointer, intent(in) :: x_l(:)
   Node(j_l)%type = type_l
   Node(j_l)%subIndex = k_l
   Node(j_l)%invertElev = x_l(0) / UCF(LENGTH)
   Node(j_l)%crownElev = Node(j_l)%invertElev
   Node(j_l)%initDepth = 0.0_dp
   Node(j_l)%newVolume = 0.0_dp
   Node(j_l)%fullVolume = 0.0_dp
   Node(j_l)%fullDepth = 0.0_dp
   Node(j_l)%surDepth = 0.0_dp
   Node(j_l)%pondedArea = 0.0_dp
   Node(j_l)%degree = 0
   Node(j_l)%inlet = NO_INLET
   select case (type_l)
   case (0)
      Node(j_l)%fullDepth = x_l(1) / UCF(LENGTH)
      Node(j_l)%initDepth = x_l(2) / UCF(LENGTH)
      Node(j_l)%surDepth = x_l(3) / UCF(LENGTH)
      Node(j_l)%pondedArea = x_l(4) / (UCF(LENGTH) * UCF(LENGTH))
   case (1)
      Outfall(k_l)%type = d2i(x_l(1))
      Outfall(k_l)%fixedStage = x_l(2) / UCF(LENGTH)
      Outfall(k_l)%tideCurve = d2i(x_l(3))
      Outfall(k_l)%stageSeries = d2i(x_l(4))
      Outfall(k_l)%hasFlapGate = d2i(x_l(5))
      Outfall(k_l)%routeTo = d2i(x_l(6))
      nullify(Outfall(k_l)%wRouted)
      if (Outfall(k_l)%routeTo >= 0) then
         allocate(Outfall(k_l)%wRouted(0:(int(Nobjects(POLLUT_c), int64)) - 1))
         Outfall(k_l)%wRouted = 0.0_dp
      end if
   case (2)
      Node(j_l)%fullDepth = x_l(1) / UCF(LENGTH)
      Node(j_l)%initDepth = x_l(2) / UCF(LENGTH)
      Storage(k_l)%shape = d2i(x_l(3))
      Storage(k_l)%a1 = x_l(4)
      Storage(k_l)%a2 = x_l(5)
      Storage(k_l)%a0 = x_l(6)
      Storage(k_l)%aCurve = d2i(x_l(7))
      Node(j_l)%surDepth = x_l(8) / UCF(LENGTH)
      Storage(k_l)%fEvap = x_l(9)
   case (3)
      Divider(k_l)%link = d2i(x_l(1))
      Divider(k_l)%type = d2i(x_l(2))
      Divider(k_l)%flowCurve = d2i(x_l(3))
      Divider(k_l)%qMin = x_l(4) / UCF(FLOW)
      Divider(k_l)%dhMax = x_l(5)
      Divider(k_l)%cWeir = x_l(6)
      Node(j_l)%fullDepth = x_l(7) / UCF(LENGTH)
      Node(j_l)%initDepth = x_l(8) / UCF(LENGTH)
      Node(j_l)%surDepth = x_l(9) / UCF(LENGTH)
      Node(j_l)%pondedArea = x_l(10) / (UCF(LENGTH) * UCF(LENGTH))
   end select
end subroutine node_setParams

! node.c:200
recursive subroutine node_validate(j_l)
   integer(int32), value :: j_l
   type(TDwfInflow), pointer :: inflow
   logical :: b1_
   nullify(inflow)
   b1_ = Node(j_l)%fullDepth > Node(j_l)%oldDepth
   if (b1_) then
      b1_ = Node(j_l)%oldDepth > 0.0_dp
   end if
   if (b1_) then
      call report_writeWarningMsg(lit_317, Node(j_l)%ID)
   end if
   if (Node(j_l)%initDepth > (Node(j_l)%fullDepth + Node(j_l)%surDepth)) then
      call report_writeErrorMsg(ERR_NODE_DEPTH, Node(j_l)%ID)
   end if
   if (Node(j_l)%type == STORAGE_c) then
      if (node_getVolume(j_l, Node(j_l)%fullDepth) < 0.0_dp) then
         call report_writeErrorMsg(ERR_STORAGE_VOLUME, Node(j_l)%ID)
      end if
   end if
   if (Node(j_l)%type == DIVIDER_c) then
      call divider_validate(j_l)
   end if
   inflow => Node(j_l)%dwfInflow
   do while (associated(inflow))
      call inflow_initDwfInflow(inflow)
      inflow => inflow%next
   end do
end subroutine node_validate

! node.c:237
recursive subroutine node_initState(j_l)
   integer(int32), value :: j_l
   integer(int32) :: p_l
   integer(int32) :: k_l
   p_l = 0
   k_l = 0
   Node(j_l)%oldDepth = Node(j_l)%initDepth
   Node(j_l)%newDepth = Node(j_l)%oldDepth
   Node(j_l)%crownElev = Node(j_l)%invertElev
   Node(j_l)%fullVolume = node_getVolume(j_l, Node(j_l)%fullDepth)
   Node(j_l)%oldVolume = node_getVolume(j_l, Node(j_l)%oldDepth)
   Node(j_l)%newVolume = Node(j_l)%oldVolume
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      Node(j_l)%oldQual(p_l) = 0.0_dp
      Node(j_l)%newQual(p_l) = 0.0_dp
      p_l = p_l + 1
   end do
   Node(j_l)%oldLatFlow = 0.0_dp
   Node(j_l)%newLatFlow = 0.0_dp
   Node(j_l)%apiExtInflow = 0.0_dp
   Node(j_l)%losses = 0.0_dp
   if (Node(j_l)%type == STORAGE_c) then
      k_l = Node(j_l)%subIndex
      Storage(k_l)%hrt = 0.0_dp
      if (associated(Storage(k_l)%exfil)) then
         call exfil_initState(k_l)
      end if
   end if
   if (Node(j_l)%type == OUTFALL_c) then
      k_l = Node(j_l)%subIndex
      if (Outfall(k_l)%routeTo >= 0) then
         Outfall(k_l)%vRouted = 0.0_dp
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            Outfall(k_l)%wRouted(p_l) = 0.0_dp
            p_l = p_l + 1
         end do
      end if
   end if
end subroutine node_initState

! node.c:293
recursive subroutine node_setOldHydState(j_l)
   integer(int32), value :: j_l
   Node(j_l)%oldDepth = Node(j_l)%newDepth
   Node(j_l)%oldVolume = Node(j_l)%newVolume
   Node(j_l)%oldFlowInflow = Node(j_l)%inflow
   Node(j_l)%oldNetInflow = Node(j_l)%inflow - Node(j_l)%outflow
end subroutine node_setOldHydState

! node.c:308
recursive subroutine node_setOldQualState(j_l)
   integer(int32), value :: j_l
   integer(int32) :: p_l
   p_l = 0
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      Node(j_l)%oldQual(p_l) = Node(j_l)%newQual(p_l)
      Node(j_l)%newQual(p_l) = 0.0_dp
      p_l = p_l + 1
   end do
end subroutine node_setOldQualState

! node.c:325
recursive subroutine node_initFlows(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   Node(j_l)%inflow = Node(j_l)%newLatFlow
   Node(j_l)%outflow = Node(j_l)%losses
   if (Node(j_l)%newVolume > Node(j_l)%fullVolume) then
      Node(j_l)%overflow = (Node(j_l)%newVolume - Node(j_l)%fullVolume) / tStep
   else
      Node(j_l)%overflow = 0.0_dp
   end if
end subroutine node_initFlows

! node.c:345
recursive function node_getDepth(j_l, v_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: v_l
   real(dp) :: res_
   res_ = 0.0_dp
   select case (Node(j_l)%type)
   case (2)
      res_ = storage_getDepth(j_l, v_l)
      return
   case default
      res_ = 0.0_dp
      return
   end select
end function node_getDepth

! node.c:362
recursive function node_getVolume(j_l, d_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: d_l
   real(dp) :: res_
   res_ = 0.0_dp
   select case (Node(j_l)%type)
   case (2)
      res_ = storage_getVolume(j_l, d_l)
      return
   case default
      if (Node(j_l)%fullDepth > 0.0_dp) then
         res_ = Node(j_l)%fullVolume * (d_l / Node(j_l)%fullDepth)
         return
      else
         res_ = 0.0_dp
         return
      end if
   end select
end function node_getVolume

! node.c:383
recursive function node_getSurfArea(j_l, d_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: d_l
   real(dp) :: res_
   res_ = 0.0_dp
   select case (Node(j_l)%type)
   case (2)
      res_ = storage_getSurfArea(j_l, d_l)
      return
   case default
      res_ = 0.0_dp
      return
   end select
end function node_getSurfArea

! node.c:400
recursive function node_getOutflow(j_l, k_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp) :: res_
   res_ = 0.0_dp
   select case (Node(j_l)%type)
   case (3)
      res_ = divider_getOutflow(j_l, k_l)
      return
   case (2)
      res_ = storage_getOutflow(j_l, k_l)
      return
   case default
      res_ = Node(j_l)%inflow + Node(j_l)%overflow
      return
   end select
end function node_getOutflow

! node.c:418
recursive function node_getMaxOutflow(j_l, q_l, tStep) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: q_l
   real(dp), value :: tStep
   real(dp) :: res_
   real(dp) :: qMax
   res_ = 0.0_dp
   qMax = 0.0_dp
   if (Node(j_l)%fullVolume > 0.0_dp) then
      qMax = Node(j_l)%inflow + (Node(j_l)%oldVolume / tStep)
      if (q_l > qMax) then
         q_l = qMax
      end if
   end if
   res_ = merge(0.0_dp, q_l, (0.0_dp) >= (q_l))
   return
end function node_getMaxOutflow

! node.c:438
recursive function node_getSystemOutflow(j_l, isFlooded) result(res_)
   integer(int32), value :: j_l
   integer(int32), intent(inout), target :: isFlooded
   real(dp) :: res_
   real(dp) :: outflow
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   res_ = 0.0_dp
   outflow = 0.0_dp
   isFlooded = 0
   if (Node(j_l)%type == OUTFALL_c) then
      if (Node(j_l)%outflow == 0.0_dp) then
         outflow = Node(j_l)%inflow
      else
         if (Node(j_l)%inflow == 0.0_dp) then
            outflow = -Node(j_l)%outflow
            Node(j_l)%inflow = abs(outflow)
         end if
      end if
      Node(j_l)%overflow = 0.0_dp
      Node(j_l)%newVolume = 0.0_dp
   else
      b3_ = RouteModel /= DW
      if (b3_) then
         b3_ = Node(j_l)%degree == 0
      end if
      b4_ = b3_
      if (b4_) then
         b4_ = Node(j_l)%type /= STORAGE_c
      end if
      if (b4_) then
         if (Node(j_l)%outflow == 0.0_dp) then
            outflow = Node(j_l)%inflow
         end if
         Node(j_l)%overflow = 0.0_dp
         Node(j_l)%newVolume = 0.0_dp
      else
         if (Node(j_l)%newVolume <= Node(j_l)%fullVolume) then
            outflow = Node(j_l)%overflow
         end if
         if (outflow > 0.0_dp) then
            isFlooded = 1
         end if
      end if
   end if
   res_ = outflow
   return
end function node_getSystemOutflow

! node.c:497
recursive subroutine node_getResults(j_l, f_l, x_l)
   integer(int32), value :: j_l
   real(dp), value :: f_l
   real(sp), pointer, intent(in) :: x_l(:)
   integer(int32) :: p_l
   real(dp) :: z_l
   real(dp) :: f1
   p_l = 0
   z_l = 0.0_dp
   f1 = 1.0_dp - f_l
   z_l = ((f1 * Node(j_l)%oldDepth) + (f_l * Node(j_l)%newDepth)) * UCF(LENGTH)
   x_l(NODE_DEPTH) = real(z_l, sp)
   z_l = Node(j_l)%invertElev * UCF(LENGTH)
   x_l(NODE_HEAD) = x_l(NODE_DEPTH) + real(z_l, sp)
   z_l = ((f1 * Node(j_l)%oldVolume) + (f_l * Node(j_l)%newVolume)) * UCF(VOLUME)
   x_l(NODE_VOLUME) = real(z_l, sp)
   z_l = ((f1 * Node(j_l)%oldLatFlow) + (f_l * Node(j_l)%newLatFlow)) * UCF(FLOW)
   x_l(NODE_LATFLOW) = real(z_l, sp)
   z_l = ((f1 * Node(j_l)%oldFlowInflow) + (f_l * Node(j_l)%inflow)) * UCF(FLOW)
   x_l(NODE_INFLOW) = real(z_l, sp)
   z_l = Node(j_l)%overflow * UCF(FLOW)
   x_l(NODE_OVERFLOW) = real(z_l, sp)
   if (.not. (IgnoreQuality /= 0)) then
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         z_l = (f1 * Node(j_l)%oldQual(p_l)) + (f_l * Node(j_l)%newQual(p_l))
         x_l(NODE_QUAL + p_l) = real(z_l, sp)
         p_l = p_l + 1
      end do
   end if
end subroutine node_getResults

! node.c:532
recursive subroutine node_setOutletDepth(j_l, yNorm, yCrit, z_l)
   integer(int32), value :: j_l
   real(dp), value :: yNorm
   real(dp), value :: yCrit
   real(dp), value :: z_l
   select case (Node(j_l)%type)
   case (2)
      return
   case (1)
      call outfall_setOutletDepth(j_l, yNorm, yCrit, z_l)
   case default
      if (z_l > 0.0_dp) then
         Node(j_l)%newDepth = 0.0_dp
      else
         Node(j_l)%newDepth = merge(yNorm, yCrit, (yNorm) <= (yCrit))
      end if
   end select
end subroutine node_setOutletDepth

! node.c:562
recursive function node_getPondedArea(j_l, d_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: d_l
   real(dp) :: res_
   real(dp) :: a_l
   logical :: b1_
   res_ = 0.0_dp
   a_l = 0.0_dp
   b1_ = d_l <= Node(j_l)%fullDepth
   if (.not. b1_) then
      b1_ = Node(j_l)%pondedArea == 0.0_dp
   end if
   if (b1_) then
      res_ = node_getSurfArea(j_l, d_l)
      return
   end if
   d_l = d_l - Node(j_l)%fullDepth
   a_l = Node(j_l)%pondedArea
   if (a_l <= 0.0_dp) then
      a_l = node_getSurfArea(j_l, Node(j_l)%fullDepth)
   end if
   res_ = a_l
   return
end function node_getPondedArea

