! node.c:654
recursive function storage_readParams(j_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: m_l
   integer(int32) :: n_l
   real(dp), target :: x_l(0:9)
   real(dp), target :: y_l(0:2)
   real(dp) :: A_l
   real(dp) :: B_l
   real(dp) :: L_l
   real(dp) :: W_l
   real(dp) :: Z_l
   type(CPtr) :: id
   logical :: b1_
   res_ = 0
   i_l = 0
   m_l = 0
   n_l = 0
   x_l = 0.0_dp
   y_l = 0.0_dp
   A_l = 0.0_dp
   B_l = 0.0_dp
   L_l = 0.0_dp
   W_l = 0.0_dp
   Z_l = 0.0_dp
   id = cnull()
   if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(NODE_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   i_l = 1
   do while (i_l <= 3)
      if (.not. (getDouble(tok_l(i_l), x_l(i_l - 1)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
         return
      end if
      i_l = i_l + 1
   end do
   m_l = findmatch(tok_l(4), RelationWords)
   if (m_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(4))
      return
   end if
   x_l(3) = real(m_l, dp)
   x_l(4) = 0.0_dp
   x_l(5) = 0.0_dp
   x_l(6) = 0.0_dp
   x_l(7) = -1.0_dp
   x_l(8) = 0.0_dp
   x_l(9) = 0.0_dp
   if (m_l == TABULAR) then
      i_l = project_findObject(CURVE_c, tok_l(5))
      if (i_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(5))
         return
      end if
      x_l(7) = real(i_l, dp)
      n_l = 6
   else
      if (ntoks < 8) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 5
      do while (i_l <= 7)
         if (.not. (getDouble(tok_l(i_l), y_l(i_l - 5)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         i_l = i_l + 1
      end do
      n_l = 8
   end if
   select case (m_l)
   case (1)
      if (y_l(2) < 0.0_dp) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(7))
         return
      end if
   case (2, 3, 4, 5)
      if (y_l(0) <= 0.0_dp) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(5))
         return
      end if
      if (y_l(1) <= 0.0_dp) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(6))
         return
      end if
      if (y_l(2) < 0.0_dp) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(7))
         return
      end if
   end select
   b1_ = m_l == PARABOLOID
   if (b1_) then
      b1_ = y_l(2) == 0.0_dp
   end if
   if (b1_) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(7))
      return
   end if
   select case (m_l)
   case (1)
      x_l(4) = y_l(0)
      x_l(5) = y_l(1)
      x_l(6) = y_l(2)
   case (2)
      A_l = y_l(0) / 2.0_dp
      B_l = y_l(1) / 2.0_dp
      x_l(4) = 0.0_dp
      x_l(5) = 0.0_dp
      x_l(6) = (3.141592654_dp * A_l) * B_l
   case (3)
      A_l = y_l(0) / 2.0_dp
      B_l = y_l(1) / 2.0_dp
      Z_l = y_l(2)
      x_l(4) = ((2.0_dp * 3.141592654_dp) * B_l) * Z_l
      x_l(5) = (((3.141592654_dp * B_l) / A_l) * Z_l) * Z_l
      x_l(6) = (3.141592654_dp * A_l) * B_l
   case (4)
      A_l = y_l(0) / 2.0_dp
      B_l = y_l(1) / 2.0_dp
      Z_l = y_l(2)
      x_l(4) = ((3.141592654_dp * A_l) * B_l) / Z_l
      x_l(5) = 0.0_dp
      x_l(6) = 0.0_dp
   case (5)
      L_l = y_l(0)
      W_l = y_l(1)
      Z_l = y_l(2)
      x_l(4) = (2.0_dp * (L_l + W_l)) * Z_l
      x_l(5) = (4.0_dp * Z_l) * Z_l
      x_l(6) = L_l * W_l
   end select
   if (ntoks > n_l) then
      if (.not. (getDouble(tok_l(n_l), x_l(8)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(n_l))
         return
      end if
      n_l = n_l + 1
   end if
   if (ntoks > n_l) then
      if (.not. (getDouble(tok_l(n_l), x_l(9)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(n_l))
         return
      end if
      n_l = n_l + 1
   end if
   Node(j_l)%ID = id
   call node_setParams(j_l, STORAGE_c, k_l, x_l)
   if (ntoks > n_l) then
      res_ = exfil_readStorageParams(k_l, tok_l, ntoks, n_l)
      return
   end if
   res_ = 0
   return
end function storage_readParams

! node.c:813
recursive function storage_getDepth(j_l, v_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: v_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: i_l
   integer(int32) :: shape_l
   real(dp) :: a0
   real(dp) :: a1
   real(dp) :: a2
   real(dp), target :: d_l
   real(dp) :: e_l
   type(TStorageVol), target :: storageVol
   logical :: b1_
   integer(int32) :: dum2_
   res_ = 0.0_dp
   k_l = Node(j_l)%subIndex
   i_l = Storage(k_l)%aCurve
   shape_l = Storage(k_l)%shape
   a0 = Storage(k_l)%a0
   a1 = Storage(k_l)%a1
   a2 = Storage(k_l)%a2
   d_l = 0.0_dp
   e_l = 0.0_dp
   storageVol = zero_TStorageVol
   b1_ = Node(j_l)%fullVolume > 0.0_dp
   if (b1_) then
      b1_ = v_l >= Node(j_l)%fullVolume
   end if
   if (b1_) then
      res_ = Node(j_l)%fullDepth
      return
   end if
   if (v_l == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   v_l = v_l * UCF(VOLUME)
   storageVol%k = k_l
   storageVol%v = v_l
   select case (shape_l)
   case (0)
      i_l = Storage(k_l)%aCurve
      if (i_l >= 0) then
         d_l = table_getStorageDepth(Curve(i_l), v_l)
      else
         d_l = 0.0_dp
      end if
   case (2)
      d_l = v_l / a0
   case (4)
      d_l = sqrt((2.0_dp * v_l) / a1)
   case (1)
      if (a2 == 0.0_dp) then
         d_l = v_l / (a0 + a1)
      else if (a0 == 0.0_dp) then
         e_l = 1.0_dp / (a2 + 1.0_dp)
         d_l = (v_l / (a1 * e_l)) ** e_l
      else if ((a2 == 1.0_dp) .and. (a1 > 0.0_dp)) then
         d_l = (sqrt((a0 * a0) + ((2.0_dp * a1) * v_l)) - a0) / a1
      else
         d_l = v_l / (a0 + a1)
         dum2_ = findroot_Newton(0.0_dp, Node(j_l)%fullDepth * UCF(LENGTH), d_l, 0.001_dp, storage_getVolDiff, c_loc(storageVol))
      end if
   case (3, 5)
      d_l = v_l / a0
      dum2_ = findroot_Newton(0.0_dp, Node(j_l)%fullDepth * UCF(LENGTH), d_l, 0.001_dp, storage_getVolDiff, c_loc(storageVol))
   case default
      d_l = 0.0_dp
   end select
   d_l = d_l / UCF(LENGTH)
   if (d_l > Node(j_l)%fullDepth) then
      d_l = Node(j_l)%fullDepth
   end if
   res_ = d_l
   return
end function storage_getDepth

! node.c:906
recursive subroutine storage_getVolDiff(y_l, f_l, df, p_l)
   real(dp), value :: y_l
   real(dp), intent(inout), target :: f_l
   real(dp), intent(inout), target :: df
   type(c_ptr), value :: p_l
   integer(int32) :: k_l
   type(TStorageVol), pointer :: storageVol
   type(TStorageVol), pointer :: p1_
   k_l = 0
   nullify(storageVol)
   call c_f_pointer(p_l, p1_)
   storageVol => p1_
   k_l = storageVol%k
   f_l = storage_getVolume(k_l, y_l) - storageVol%v
   df = storage_getSurfArea(k_l, y_l)
end subroutine storage_getVolDiff

! node.c:930
recursive function storage_getVolume(j_l, d_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: d_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: i_l
   real(dp) :: n_l
   real(dp) :: v_l
   logical :: b1_
   res_ = 0.0_dp
   k_l = Node(j_l)%subIndex
   i_l = 0
   n_l = 0.0_dp
   v_l = 0.0_dp
   if (d_l == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   b1_ = d_l >= Node(j_l)%fullDepth
   if (b1_) then
      b1_ = Node(j_l)%fullVolume > 0.0_dp
   end if
   if (b1_) then
      res_ = Node(j_l)%fullVolume
      return
   end if
   select case (Storage(k_l)%shape)
   case (0)
      i_l = Storage(k_l)%aCurve
      if (i_l >= 0) then
         res_ = table_getStorageVolume(Curve(i_l), d_l * UCF(LENGTH)) / UCF(VOLUME)
         return
      else
         res_ = 0.0_dp
         return
      end if
   case (1)
      d_l = d_l * UCF(LENGTH)
      n_l = Storage(k_l)%a2 + 1.0_dp
      v_l = (Storage(k_l)%a0 * d_l) + ((Storage(k_l)%a1 / n_l) * (d_l ** n_l))
      res_ = v_l / UCF(VOLUME)
      return
   case (2, 3, 4, 5)
      d_l = d_l * UCF(LENGTH)
      v_l = d_l * (Storage(k_l)%a0 + (d_l * ((Storage(k_l)%a1 / 2.0_dp) + ((d_l * Storage(k_l)%a2) / 3.0_dp))))
      res_ = v_l / UCF(VOLUME)
      return
   case default
      res_ = 0.0_dp
      return
   end select
end function storage_getVolume

! node.c:979
recursive function storage_getSurfArea(j_l, d_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: d_l
   real(dp) :: res_
   real(dp) :: area_l
   integer(int32) :: k_l
   integer(int32) :: i_l
   res_ = 0.0_dp
   area_l = 0.0_dp
   k_l = Node(j_l)%subIndex
   i_l = 0
   select case (Storage(k_l)%shape)
   case (0)
      i_l = Storage(k_l)%aCurve
      if (i_l >= 0) then
         area_l = table_lookupEx(Curve(i_l), d_l * UCF(LENGTH))
      end if
   case (1)
      area_l = Storage(k_l)%a0 + (Storage(k_l)%a1 * ((d_l * UCF(LENGTH)) ** (Storage(k_l)%a2)))
   case (2, 3, 4, 5)
      d_l = d_l * UCF(LENGTH)
      area_l = Storage(k_l)%a0 + (d_l * (Storage(k_l)%a1 + (d_l * Storage(k_l)%a2)))
   case default
      res_ = 0.0_dp
      return
   end select
   res_ = (area_l / UCF(LENGTH)) / UCF(LENGTH)
   return
end function storage_getSurfArea

! node.c:1022
recursive function storage_getOutflow(j_l, i_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: i_l
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: a_l
   real(dp) :: y_l
   res_ = 0.0_dp
   k_l = 0
   a_l = 0.0_dp
   y_l = 0.0_dp
   if (Link(i_l)%type /= CONDUIT_c) then
      res_ = 0.0_dp
      return
   end if
   y_l = Node(j_l)%newDepth - Link(i_l)%offset1
   if (y_l <= 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (y_l >= Link(i_l)%xsect%yFull) then
      res_ = Link(i_l)%qFull
      return
   end if
   k_l = Link(i_l)%subIndex
   a_l = xsect_getAofY(Link(i_l)%xsect, y_l)
   res_ = Conduit(k_l)%beta * xsect_getSofA(Link(i_l)%xsect, a_l)
   return
end function storage_getOutflow

! node.c:1052
recursive function storage_getLosses(j_l, tStep) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: depth
   real(dp) :: area_l
   real(dp) :: evapRate_l
   real(dp) :: exfilRate
   real(dp) :: totalLoss
   real(dp) :: lossRatio
   type(TExfil), pointer :: exfil
   res_ = 0.0_dp
   k_l = 0
   depth = 0.0_dp
   area_l = 0.0_dp
   evapRate_l = 0.0_dp
   exfilRate = 0.0_dp
   totalLoss = 0.0_dp
   lossRatio = 0.0_dp
   nullify(exfil)
   k_l = Node(j_l)%subIndex
   evapRate_l = Evap%rate * Storage(k_l)%fEvap
   exfil => Storage(k_l)%exfil
   if ((evapRate_l > 0.0_dp) .or. (.not. (.not. associated(exfil)))) then
      depth = Node(j_l)%newDepth
      area_l = storage_getSurfArea(j_l, depth)
      if (Node(j_l)%newVolume > 0.0001_dp) then
         evapRate_l = area_l * evapRate_l
      end if
      if (.not. (.not. associated(exfil))) then
         exfilRate = exfil_getLoss(exfil, tStep, depth, area_l)
      end if
      totalLoss = (evapRate_l + exfilRate) * tStep
      if (totalLoss > Node(j_l)%newVolume) then
         lossRatio = Node(j_l)%newVolume / totalLoss
         evapRate_l = evapRate_l * lossRatio
         exfilRate = exfilRate * lossRatio
      end if
   end if
   Storage(Node(j_l)%subIndex)%evapLoss = evapRate_l * tStep
   Storage(Node(j_l)%subIndex)%exfilLoss = exfilRate * tStep
   res_ = evapRate_l + exfilRate
   return
end function storage_getLosses

! node.c:1113
recursive function divider_readParams(j_l, k_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: m_l
   integer(int32) :: m1
   integer(int32) :: m2
   integer(int32) :: n_l
   real(dp), target :: x_l(0:10)
   type(CPtr) :: id
   logical :: b1_
   res_ = 0
   i_l = 0
   m_l = 0
   m1 = 0
   m2 = 0
   n_l = 0
   x_l = 0.0_dp
   id = cnull()
   if (ntoks < 4) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   id = project_findID(NODE_c, tok_l(0))
   if (cisnull(id)) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   if (.not. (getDouble(tok_l(1), x_l(0)) /= 0)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(1))
      return
   end if
   i_l = 1
   do while (i_l < 11)
      x_l(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   b1_ = strlen(tok_l(2)) == 0_int64
   if (.not. b1_) then
      b1_ = c_strcmp(tok_l(2), lit_275) == 0
   end if
   if (b1_) then
      x_l(1) = -1.0_dp
   else
      m1 = project_findObject(LINK_c, tok_l(2))
      if (m1 < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(2))
         return
      end if
      x_l(1) = real(m1, dp)
   end if
   n_l = 4
   m1 = findmatch(tok_l(3), DividerTypeWords)
   if (m1 < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(3))
      return
   end if
   x_l(2) = real(m1, dp)
   x_l(3) = -1.0_dp
   if (m1 == TABULAR_DIVIDER) then
      if (ntoks < 5) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      m2 = project_findObject(CURVE_c, tok_l(4))
      if (m2 < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(4))
         return
      end if
      x_l(3) = real(m2, dp)
      n_l = 5
   end if
   if (m1 == CUTOFF_DIVIDER) then
      if (ntoks < 5) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (.not. (getDouble(tok_l(4), x_l(4)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(4))
         return
      end if
      n_l = 5
   end if
   if (m1 == WEIR_DIVIDER) then
      if (ntoks < 7) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 4
      do while (i_l < 7)
         if (.not. (getDouble(tok_l(i_l), x_l(i_l)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         i_l = i_l + 1
      end do
      n_l = 7
   end if
   if (m1 == OVERFLOW_DIVIDER) then
      n_l = 4
   end if
   m_l = 7
   i_l = n_l
   do while ((i_l < ntoks) .and. (m_l < 11))
      if (.not. (getDouble(tok_l(i_l), x_l(m_l)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
         return
      end if
      m_l = m_l + 1
      i_l = i_l + 1
   end do
   Node(j_l)%ID = id
   call node_setParams(j_l, DIVIDER_c, k_l, x_l)
   res_ = 0
   return
end function divider_readParams

! node.c:1216
recursive subroutine divider_validate(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   integer(int32) :: k_l
