! node.c:1251
recursive function divider_getOutflow(j_l, k_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp) :: res_
   integer(int32) :: i_l
   integer(int32) :: m_l
   real(dp) :: qIn
   real(dp) :: qOut
   real(dp) :: f_l
   res_ = 0.0_dp
   i_l = 0
   m_l = 0
   qIn = 0.0_dp
   qOut = 0.0_dp
   f_l = 0.0_dp
   qIn = Node(j_l)%inflow + Node(j_l)%overflow
   i_l = Node(j_l)%subIndex
   select case (Divider(i_l)%type)
   case (0)
      if (qIn <= Divider(i_l)%qMin) then
         qOut = 0.0_dp
      else
         qOut = qIn - Divider(i_l)%qMin
      end if
   case (3)
      if (k_l /= Divider(i_l)%link) then
         qOut = qIn
      else
         qOut = qIn - Node(j_l)%outflow
      end if
      if (qOut < 1.0e-05_dp) then
         qOut = 0.0_dp
      end if
      res_ = qOut
      return
   case (2)
      if (qIn <= Divider(i_l)%qMin) then
         qOut = 0.0_dp
      else
         f_l = (qIn - Divider(i_l)%qMin) / (Divider(i_l)%qMax - Divider(i_l)%qMin)
         if (f_l > 1.0_dp) then
            qOut = Divider(i_l)%qMax * sqrt(f_l)
         else
            qOut = (Divider(i_l)%cWeir * ((f_l * Divider(i_l)%dhMax) ** 1.5_dp)) / UCF(FLOW)
         end if
      end if
   case (1)
      m_l = Divider(i_l)%flowCurve
      if (m_l >= 0) then
         qOut = table_lookup(Curve(m_l), qIn * UCF(FLOW)) / UCF(FLOW)
      else
         qOut = 0.0_dp
      end if
   case default
      qOut = 0.0_dp
   end select
   if (qOut > qIn) then
      qOut = qIn
   end if
   if (k_l /= Divider(i_l)%link) then
      qOut = qIn - qOut
   end if
   res_ = qOut
   return
end function divider_getOutflow

