   x_l(2) = 0.0_dp
   x_l(3) = -1.0_dp
   x_l(4) = -1.0_dp
   x_l(5) = 0.0_dp
   x_l(6) = -1.0_dp
   n_l = 4
   if (i_l >= FIXED_OUTFALL) then
      if (ntoks < 4) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      n_l = 5
      select case (i_l)
      case (2)
         if (.not. (getDouble(tok_l(3), x_l(2)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(3))
            return
         end if
      case (3)
         m_l = project_findObject(CURVE_c, tok_l(3))
         if (m_l < 0) then
            res_ = error_setInpError(ERR_NAME, tok_l(3))
            return
         end if
         x_l(3) = real(m_l, dp)
      case (4)
         m_l = project_findObject(TSERIES_c, tok_l(3))
         if (m_l < 0) then
            res_ = error_setInpError(ERR_NAME, tok_l(3))
            return
         end if
         x_l(4) = real(m_l, dp)
         Tseries(m_l)%refersTo = TIMESERIES_OUTFALL
      end select
   end if
   if (ntoks == n_l) then
      m_l = findmatch(tok_l(n_l - 1), NoYesWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(n_l - 1))
         return
      end if
      x_l(5) = real(m_l, dp)
   end if
   if (ntoks == (n_l + 1)) then
      m_l = project_findObject(SUBCATCH_c, tok_l(n_l))
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(n_l))
         return
      end if
      x_l(6) = real(m_l, dp)
   end if
   Node(j_l)%ID = id
   call node_setParams(j_l, OUTFALL_c, k_l, x_l)
   res_ = 0
   return
end function outfall_readParams

