recursive subroutine outfall_setOutletDepth(j_l, yNorm, yCrit, z_l)
   integer(int32), value :: j_l
   real(dp), value :: yNorm
   real(dp), value :: yCrit
   real(dp), value :: z_l
   real(dp), target :: x_l
   real(dp), target :: y_l
   real(dp) :: yNew
   real(dp) :: stage
   integer(int32) :: k_l
   integer(int32) :: i_l
   real(dp) :: currentDate_l
   integer(int32) :: dum1_
   real(dp) :: v2_
   x_l = 0.0_dp
   y_l = 0.0_dp
   yNew = 0.0_dp
   stage = 0.0_dp
   k_l = 0
   i_l = Node(j_l)%subIndex
   currentDate_l = 0.0_dp
   select case (Outfall(i_l)%type)
   case (0)
      if (z_l > 0.0_dp) then
         Node(j_l)%newDepth = 0.0_dp
      else
         Node(j_l)%newDepth = merge(yNorm, yCrit, (yNorm) <= (yCrit))
      end if
      return
   case (1)
      if (z_l > 0.0_dp) then
         Node(j_l)%newDepth = 0.0_dp
      else
         Node(j_l)%newDepth = yNorm
      end if
      return
   case (2)
      stage = Outfall(i_l)%fixedStage
   case (3)
      k_l = Outfall(i_l)%tideCurve
      dum1_ = table_getFirstEntry(Curve(k_l), x_l, y_l)
      currentDate_l = NewRoutingTime / 86400000.0_dp
      x_l = x_l + ((currentDate_l - cfloor(currentDate_l)) * 24.0_dp)
      stage = table_lookup(Curve(k_l), x_l) / UCF(LENGTH)
   case (4)
      k_l = Outfall(i_l)%stageSeries
      currentDate_l = StartDateTime + (NewRoutingTime / 86400000.0_dp)
      stage = table_tseriesLookup(Tseries(k_l), currentDate_l, 1) / UCF(LENGTH)
   case default
      stage = Node(j_l)%invertElev
   end select
   yCrit = merge(yCrit, yNorm, (yCrit) <= (yNorm))
   if (((yCrit + z_l) + Node(j_l)%invertElev) < stage) then
      yNew = stage - Node(j_l)%invertElev
   else if (z_l > 0.0_dp) then
      if (stage < (Node(j_l)%invertElev + z_l)) then
         if ((0.0_dp) >= (stage - Node(j_l)%invertElev)) then
            v2_ = 0.0_dp
         else
            v2_ = stage - Node(j_l)%invertElev
         end if
         yNew = v2_
      else
         yNew = z_l + yCrit
      end if
   else
      yNew = yCrit
   end if
   Node(j_l)%newDepth = yNew
end subroutine outfall_setOutletDepth

