! output.c:569
recursive subroutine output_saveSubcatchResults(reportTime_l, file)
   real(dp), value :: reportTime_l
   type(CFile), pointer, intent(in) :: file
   integer(int32) :: j_l
   real(dp) :: f_l
   real(dp) :: area_l
   real(sp) :: totalArea_l
   real(dp) :: reportDate
   integer(int64) :: dum1_
   j_l = 0
   f_l = 0.0_dp
   area_l = 0.0_dp
   totalArea_l = 0.0_sp
   reportDate = getDateTime(reportTime_l)
   j_l = 0
   do while (j_l < Nobjects(GAGE_c))
      call gage_setReportRainfall(j_l, reportDate)
      j_l = j_l + 1
   end do
   f_l = (reportTime_l - OldRunoffTime) / (NewRunoffTime - OldRunoffTime)
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      call subcatch_getResults(j_l, f_l, SubcatchResults)
      if (Subcatch(j_l)%rptFlag /= 0) then
         dum1_ = c_fwrite_r4a(SubcatchResults, 0, int(int(NumSubcatchVars, int64), int32), file)
      end if
      area_l = Subcatch(j_l)%area * UCF(LANDAREA)
      totalArea_l = totalArea_l + real(area_l, sp)
      SysResults(SYS_RAINFALL) = SysResults(SYS_RAINFALL) + real(real(SubcatchResults(SUBCATCH_RAINFALL), dp) * area_l, sp)
      SysResults(SYS_SNOWDEPTH) = SysResults(SYS_SNOWDEPTH) + real(real(SubcatchResults(SUBCATCH_SNOWDEPTH), dp) * area_l, sp)
      SysResults(SYS_EVAP) = SysResults(SYS_EVAP) + real(real(SubcatchResults(SUBCATCH_EVAP), dp) * area_l, sp)
      if (associated(Subcatch(j_l)%groundwater)) then
         SysResults(SYS_EVAP) = SysResults(SYS_EVAP) + real((Subcatch(j_l)%groundwater%evapLoss * UCF(EVAPRATE)) * area_l, sp)
      end if
      SysResults(SYS_INFIL) = SysResults(SYS_INFIL) + real(real(SubcatchResults(SUBCATCH_INFIL), dp) * area_l, sp)
      SysResults(SYS_RUNOFF) = SysResults(SYS_RUNOFF) + SubcatchResults(SUBCATCH_RUNOFF)
      j_l = j_l + 1
   end do
   if (real(totalArea_l, dp) > 0.0_dp) then
      SysResults(SYS_EVAP) = SysResults(SYS_EVAP) / totalArea_l
      SysResults(SYS_RAINFALL) = SysResults(SYS_RAINFALL) / totalArea_l
      SysResults(SYS_SNOWDEPTH) = SysResults(SYS_SNOWDEPTH) / totalArea_l
      SysResults(SYS_INFIL) = SysResults(SYS_INFIL) / totalArea_l
   end if
   if (UnitSystem == SI) then
      f_l = (5.0_dp / 9.0_dp) * (Temp%ta - 32.0_dp)
   else
      f_l = Temp%ta
   end if
   SysResults(SYS_TEMPERATURE) = real(f_l, sp)
   f_l = Evap%rate * UCF(EVAPRATE)
   SysResults(SYS_PET) = real(f_l, sp)
end subroutine output_saveSubcatchResults

