recursive subroutine project_readInput()
   integer(int32) :: dum1_
   call createHashTables()
   dum1_ = input_countObjects()
   call createObjects()
   dum1_ = input_readData()
   if (ErrorCode /= 0) then
      return
   end if
   StartDateTime = StartDate + StartTime
   EndDateTime = EndDate + EndTime
   ReportStart = ReportStartDate + ReportStartTime
   ReportStart = merge(ReportStart, StartDateTime, (ReportStart) >= (StartDateTime))
   if (EndDateTime <= StartDateTime) then
      call report_writeErrorMsg(ERR_START_DATE, lit_0)
   else if (EndDateTime <= ReportStart) then
      call report_writeErrorMsg(ERR_REPORT_DATE, lit_0)
   else
      TotalDuration = cfloor((EndDateTime - StartDateTime) * 86400.0_dp)
      if (real(ReportStep, dp) > TotalDuration) then
         ReportStep = d2i(TotalDuration)
      end if
      if (real(ReportStep, dp) < RouteStep) then
         call report_writeErrorMsg(ERR_REPORT_STEP, lit_0)
      end if
      TotalDuration = TotalDuration * 1000.0_dp
   end if
end subroutine project_readInput

