   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      call node_validate(i_l)
      i_l = i_l + 1
   end do
   if (DryStep < WetStep) then
      call report_writeWarningMsg(lit_319, lit_0)
      DryStep = WetStep
   end if
   if (RouteStep > real(WetStep, dp)) then
      call report_writeWarningMsg(lit_320, lit_0)
      RouteStep = real(WetStep, dp)
   end if
   if (RptFlags%subcatchments == ALL_c) then
      i_l = 0
      do while (i_l < Nobjects(SUBCATCH_c))
         Subcatch(i_l)%rptFlag = 1
         i_l = i_l + 1
      end do
   end if
   if (RptFlags%nodes == ALL_c) then
      i_l = 0
      do while (i_l < Nobjects(NODE_c))
         Node(i_l)%rptFlag = 1
         i_l = i_l + 1
      end do
   end if
   if (RptFlags%links == ALL_c) then
      i_l = 0
      do while (i_l < Nobjects(LINK_c))
         Link(i_l)%rptFlag = 1
         i_l = i_l + 1
      end do
   end if
   if (RouteModel == DW) then
      call dynwave_validate()
   end if
   call inlet_validate()
   if (NumThreads == 0) then
      NumThreads = omp_get_max_threads()
   else
      if ((NumThreads) <= (omp_get_max_threads())) then
         v1_ = NumThreads
      else
         v1_ = omp_get_max_threads()
      end if
      NumThreads = v1_
   end if
   if (Nobjects(LINK_c) < (4 * NumThreads)) then
      NumThreads = 1
   end if
end subroutine project_validate

! project.c:274
recursive subroutine project_close()
   call deleteObjects()
   call deleteHashTables()
end subroutine project_close

! project.c:287
recursive function project_init() result(res_)
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: k_l
   res_ = 0
   j_l = 0
   k_l = 0
   call climate_initState()
   call lid_initState()
   j_l = 0
   do while (j_l < Nobjects(TSERIES_c))
      call table_tseriesInit(Tseries(j_l))
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(GAGE_c))
      call gage_initState(j_l)
      j_l = j_l + 1
   end do
   k_l = 1
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      call subcatch_initState(j_l)
      if (Subcatch(j_l)%rptFlag > 0) then
         Subcatch(j_l)%rptFlag = k_l
         k_l = k_l + 1
      end if
      j_l = j_l + 1
   end do
   k_l = 1
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      call node_initState(j_l)
      if (Node(j_l)%rptFlag > 0) then
         Node(j_l)%rptFlag = k_l
         k_l = k_l + 1
      end if
      j_l = j_l + 1
   end do
   k_l = 1
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      call link_initState(j_l)
      if (Link(j_l)%rptFlag > 0) then
         Link(j_l)%rptFlag = k_l
         k_l = k_l + 1
      end if
      j_l = j_l + 1
   end do
   res_ = ErrorCode
   return
end function project_init

! project.c:334
recursive function project_addObject(type_l, id, n_l) result(res_)
   integer(int32), value :: type_l
   type(CPtr), value :: id
   integer(int32), value :: n_l
   integer(int32) :: res_
   integer(int32) :: result_l
   integer(int64) :: len_l
   type(CPtr) :: newID
   integer(int64) :: dum1_
   res_ = 0
   result_l = 0
   len_l = 0_int64
   newID = cnull()
   if (project_findObject(type_l, id) >= 0) then
      res_ = 0
      return
   end if
   len_l = strlen(id)
   newID = Alloc((len_l + 1_int64) * 1_int64)
   dum1_ = sstrncpy(newID, id, len_l)
   result_l = HTinsert(Htable(type_l)%p, newID, n_l)
   if (result_l == 0) then
      result_l = -1
   end if
   res_ = result_l
   return
end function project_addObject

! project.c:364
recursive function project_findObject(type_l, id) result(res_)
   integer(int32), value :: type_l
   type(CPtr), value :: id
   integer(int32) :: res_
   res_ = 0
   res_ = HTfind(Htable(type_l)%p, id)
   return
end function project_findObject

