recursive function project_findID(type_l, id) result(res_)
   integer(int32), value :: type_l
   type(CPtr), value :: id
   type(CPtr) :: res_
   res_ = cnull()
   res_ = HTfindKey(Htable(type_l)%p, id)
   return
end function project_findID

! project.c:445
recursive function project_readOption(s1, s2) result(res_)
   type(CPtr), value :: s1
   type(CPtr), value :: s2
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32), target :: m_l
   integer(int32), target :: h_l
   integer(int32), target :: s_l
   real(dp), target :: tStep
   integer(int8), target :: strDate(0:24)
   real(dp), target :: aTime
   real(dp), target :: aDate
   integer(int64) :: dum1_
   res_ = 0
   k_l = 0
   m_l = 0
   h_l = 0
   s_l = 0
   tStep = 0.0_dp
   strDate = 0_int8
   aTime = 0.0_dp
   aDate = 0.0_dp
   k_l = findmatch(s1, OptionWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, s1)
      return
   end if
   select case (k_l)
   case (0)
      m_l = findmatch(s2, FlowUnitWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      FlowUnits = m_l
      if (FlowUnits <= MGD) then
         UnitSystem = US
      else
         UnitSystem = SI
      end if
   case (1)
      m_l = findmatch(s2, InfilModelWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      InfilModel = m_l
   case (2)
      m_l = findmatch(s2, RouteModelWords)
      if (m_l < 0) then
         m_l = findmatch(s2, OldRouteModelWords)
      end if
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      if (m_l == NO_ROUTING) then
         IgnoreRouting = 1
      else
         RouteModel = m_l
      end if
      if (RouteModel == EKW) then
         RouteModel = KW
      end if
   case (3)
      if (.not. (datetime_strToDate(s2, StartDate) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
   case (4)
      if (.not. (datetime_strToTime(s2, StartTime) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
   case (5)
      if (.not. (datetime_strToDate(s2, EndDate) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
   case (6)
      if (.not. (datetime_strToTime(s2, EndTime) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
   case (7)
      if (.not. (datetime_strToDate(s2, ReportStartDate) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
   case (8)
      if (.not. (datetime_strToTime(s2, ReportStartTime) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
   case (9, 10)
      dum1_ = sstrncpy(cview(strDate), s2, 24_int64)
      dum1_ = sstrcat(cview(strDate), lit_35, 25_int64)
      if (.not. (datetime_strToDate(cview(strDate), aDate) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
      m_l = datetime_dayOfYear(aDate)
      if (k_l == SWEEP_START) then
         SweepStart = m_l
      else
         SweepEnd = m_l
      end if
   case (11)
      StartDryDays = c_atof(s2)
      if (StartDryDays < 0.0_dp) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
   case (12, 13, 16, 15)
      if (.not. (datetime_strToTime(s2, aTime) /= 0)) then
         res_ = error_setInpError(ERR_DATETIME, s2)
         return
      end if
      call datetime_decodeTime(aTime, h_l, m_l, s_l)
      h_l = h_l + (24 * d2i(aTime))
      s_l = (s_l + (60 * m_l)) + (3600 * h_l)
      if (k_l == RULE_STEP) then
         if (s_l < 0) then
            res_ = error_setInpError(ERR_NUMBER, s2)
            return
         end if
      else if (s_l <= 0) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      select case (k_l)
      case (12)
         WetStep = s_l
      case (13)
         DryStep = s_l
      case (16)
         ReportStep = s_l
      case (15)
         RuleStep = s_l
      end select
   case (18)
      m_l = findmatch(s2, InertDampingWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      else
         InertDamping = m_l
      end if
   case (17, 19, 25, 27, 31, 32, 33, 34, 39)
      m_l = findmatch(s2, NoYesWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      select case (k_l)
      case (17)
         AllowPonding = m_l
      case (19)
         SlopeWeighting = m_l
      case (25)
         SkipSteadyState = m_l
      case (27)
         IgnoreRainfall = m_l
      case (31)
         IgnoreSnowmelt = m_l
      case (32)
         IgnoreGwater = m_l
      case (33)
         IgnoreRouting = m_l
      case (34)
         IgnoreQuality = m_l
      case (39)
         IgnoreRDII = m_l
      end select
   case (21)
      m_l = findmatch(s2, NormalFlowWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      NormalFlowLtd = m_l
   case (28)
      m_l = findmatch(s2, ForceMainEqnWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      ForceMainEqn = m_l
   case (29)
      m_l = findmatch(s2, LinkOffsetWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      LinkOffsets = m_l
   case (24)
      if (strcomp(s2, lit_321) /= 0) then
         Compatibility = SWMM3
      else if (strcomp(s2, lit_322) /= 0) then
         Compatibility = SWMM4
      else if (strcomp(s2, lit_323) /= 0) then
         Compatibility = SWMM5
      else
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
   case (14, 22)
      if (.not. (getDouble(s2, tStep) /= 0)) then
         if (.not. (datetime_strToTime(s2, aTime) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, s2)
            return
         else
            call datetime_decodeTime(aTime, h_l, m_l, s_l)
            h_l = h_l + (24 * d2i(aTime))
            s_l = (s_l + (60 * m_l)) + (3600 * h_l)
            tStep = real(s_l, dp)
         end if
      end if
      if (k_l == ROUTE_STEP) then
         if (tStep <= 0.0_dp) then
            res_ = error_setInpError(ERR_NUMBER, s2)
            return
         end if
         RouteStep = tStep
      else
         LengtheningStep = merge(0.0_dp, tStep, (0.0_dp) >= (tStep))
      end if
   case (40)
      if ((.not. (getDouble(s2, MinRouteStep) /= 0)) .or. (MinRouteStep < 0.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
   case (41)
      m_l = c_atoi(s2)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      NumThreads = m_l
   case (20)
      if (.not. (getDouble(s2, CourantFactor) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      if ((CourantFactor < 0.0_dp) .or. (CourantFactor > 2.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
   case (23)
      if (.not. (getDouble(s2, MinSurfArea) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      if (MinSurfArea < 0.0_dp) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
   case (30)
      if (.not. (getDouble(s2, MinSlope) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      if ((MinSlope < 0.0_dp) .or. (MinSlope >= 100.0_dp)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      MinSlope = MinSlope / 100.0_dp
   case (35)
      m_l = c_atoi(s2)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      MaxTrials = m_l
   case (36)
      if (.not. (getDouble(s2, HeadTol) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
   case (37)
      if (.not. (getDouble(s2, SysFlowTol) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      SysFlowTol = SysFlowTol / 100.0_dp
   case (38)
      if (.not. (getDouble(s2, LatFlowTol) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, s2)
         return
      end if
      LatFlowTol = LatFlowTol / 100.0_dp
   case (42)
      m_l = findmatch(s2, SurchargeWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, s2)
         return
      end if
      SurchargeMethod = m_l
   case (26)
      dum1_ = sstrncpy(cview(TempDir), s2, 259_int64)
   end select
   res_ = 0
   return
end function project_readOption

