! project.c:954
recursive subroutine openFiles(f1, f2, f3)
   type(CPtr), value :: f1
   type(CPtr), value :: f2
   type(CPtr), value :: f3
   integer(int64) :: dum1_
   logical :: b2_
   logical :: b3_
   nullify(Finp%file)
   nullify(Frpt%file)
   nullify(Fout%file)
   dum1_ = sstrncpy(cview(Finp%name), f1, 259_int64)
   dum1_ = sstrncpy(cview(Frpt%name), f2, 259_int64)
   dum1_ = sstrncpy(cview(Fout%name), f3, 259_int64)
   b2_ = strcomp(f1, f2) /= 0
   if (.not. b2_) then
      b2_ = strcomp(f1, f3) /= 0
   end if
   b3_ = b2_
   if (.not. b3_) then
      b3_ = strcomp(f2, f3) /= 0
   end if
   if (b3_) then
      call writecon(lit_324)
      ErrorCode = ERR_FILE_NAME
      return
   end if
   Finp%file => c_fopen(f1, lit_13)
   if (.not. associated(Finp%file)) then
      call writecon(lit_325)
      call writecon(f1)
      ErrorCode = ERR_INP_FILE
      return
   end if
   Frpt%file => c_fopen(f2, lit_171)
   if (.not. associated(Frpt%file)) then
      call writecon(lit_326)
      ErrorCode = ERR_RPT_FILE
      return
   end if
end subroutine openFiles

! project.c:999
recursive subroutine createObjects()
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int64) :: dum1_
   j_l = 0
   k_l = 0
   if (ErrorCode /= 0) then
      return
   end if
   allocate(Gage(0:(int(Nobjects(GAGE_c), int64)) - 1))
   allocate(Subcatch(0:(int(Nobjects(SUBCATCH_c), int64)) - 1))
   allocate(Node(0:(int(Nobjects(NODE_c), int64)) - 1))
   allocate(Outfall(0:(int(Nnodes(OUTFALL_c), int64)) - 1))
   allocate(Divider(0:(int(Nnodes(DIVIDER_c), int64)) - 1))
   allocate(Storage(0:(int(Nnodes(STORAGE_c), int64)) - 1))
   allocate(Link(0:(int(Nobjects(LINK_c), int64)) - 1))
   allocate(Conduit(0:(int(Nlinks(CONDUIT_c), int64)) - 1))
   allocate(Pump(0:(int(Nlinks(PUMP_c), int64)) - 1))
   allocate(Orifice(0:(int(Nlinks(ORIFICE_c), int64)) - 1))
   allocate(Weir(0:(int(Nlinks(WEIR_c), int64)) - 1))
   allocate(Outlet(0:(int(Nlinks(OUTLET_c), int64)) - 1))
   allocate(Pollut(0:(int(Nobjects(POLLUT_c), int64)) - 1))
   allocate(Landuse(0:(int(Nobjects(LANDUSE_c), int64)) - 1))
   allocate(Pattern(0:(int(Nobjects(TIMEPATTERN), int64)) - 1))
   allocate(Curve(0:(int(Nobjects(CURVE_c), int64)) - 1))
   allocate(Tseries(0:(int(Nobjects(TSERIES_c), int64)) - 1))
