! project.c:1304
recursive subroutine createHashTables()
   integer(int32) :: j_l
   j_l = 0
   MemPoolAllocated = 0
   j_l = 0
   do while (j_l < MAX_OBJ_TYPES)
      Htable(j_l)%p => HTcreate()
      if (.not. associated(Htable(j_l)%p)) then
         call report_writeErrorMsg(ERR_MEMORY, lit_0)
      end if
      j_l = j_l + 1
   end do
   if (.not. associated(AllocInit())) then
      call report_writeErrorMsg(ERR_MEMORY, lit_0)
   else
      MemPoolAllocated = 1
   end if
end subroutine createHashTables

! project.c:1325
recursive subroutine deleteHashTables()
   integer(int32) :: j_l
   j_l = 0
   j_l = 0
   do while (j_l < MAX_OBJ_TYPES)
      if (.not. (.not. associated(Htable(j_l)%p))) then
         call HTfree(Htable(j_l)%p)
      end if
      j_l = j_l + 1
   end do
   if (MemPoolAllocated /= 0) then
      call AllocFreePool()
   end if
end subroutine deleteHashTables

! qualrout.c:63
recursive subroutine qualrout_init()
   integer(int32) :: i_l
   integer(int32) :: p_l
   integer(int32) :: isWet
   real(dp) :: c_l
   i_l = 0
   p_l = 0
   isWet = 0
   c_l = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      isWet = merge(1, 0, Node(i_l)%newDepth > ZeroDepth)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         c_l = 0.0_dp
         if (isWet /= 0) then
            c_l = Pollut(p_l)%initConcen
         end if
         Node(i_l)%oldQual(p_l) = c_l
         Node(i_l)%newQual(p_l) = c_l
         p_l = p_l + 1
      end do
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      isWet = merge(1, 0, Link(i_l)%newDepth > ZeroDepth)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         c_l = 0.0_dp
         if (isWet /= 0) then
            c_l = Pollut(p_l)%initConcen
         end if
         Link(i_l)%oldQual(p_l) = c_l
         Link(i_l)%newQual(p_l) = c_l
         p_l = p_l + 1
      end do
      i_l = i_l + 1
   end do
end subroutine qualrout_init

! qualrout.c:100
recursive subroutine qualrout_execute(tStep)
   real(dp), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: j_l
   real(dp) :: qIn
   real(dp) :: vAvg
   logical :: b1_
   i_l = 0
   j_l = 0
   qIn = 0.0_dp
   vAvg = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      call findLinkMassFlow(i_l, tStep)
      i_l = i_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      Node(j_l)%qualInflow = Node(j_l)%inflow
      qIn = Node(j_l)%qualInflow
      vAvg = (Node(j_l)%oldVolume + Node(j_l)%newVolume) / 2.0_dp
      if (associated(Node(j_l)%treatment)) then
         if (qIn < 1.0e-10_dp) then
            qIn = 0.0_dp
         end if
         call treatmnt_setInflow(qIn, Node(j_l)%newQual)
      end if
      b1_ = Node(j_l)%type == STORAGE_c
      if (.not. b1_) then
         b1_ = Node(j_l)%oldVolume > ZeroVolume
      end if
      if (b1_) then
         call findStorageQual(j_l, tStep)
      else
         call findNodeQual(j_l)
      end if
      if (associated(Node(j_l)%treatment)) then
         call treatmnt_treat(j_l, qIn, vAvg, tStep)
      end if
      j_l = j_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      call findLinkQual(i_l, tStep)
      i_l = i_l + 1
   end do
end subroutine qualrout_execute

! qualrout.c:146
recursive function getMixedQual(c_l, v1, wIn, qIn, tStep) result(res_)
   real(dp), value :: c_l
   real(dp), value :: v1
   real(dp), value :: wIn
   real(dp), value :: qIn
   real(dp), value :: tStep
   real(dp) :: res_
   real(dp) :: vIn
   real(dp) :: cIn_l
   real(dp) :: cMax
   res_ = 0.0_dp
   vIn = 0.0_dp
   cIn_l = 0.0_dp
   cMax = 0.0_dp
   if (qIn <= 1.0e-10_dp) then
      res_ = c_l
      return
   end if
   vIn = qIn * tStep
   cIn_l = (wIn * tStep) / vIn
   cMax = merge(c_l, cIn_l, (c_l) >= (cIn_l))
   c_l = ((c_l * v1) + (wIn * tStep)) / (v1 + vIn)
   c_l = merge(c_l, cMax, (c_l) <= (cMax))
   c_l = merge(c_l, 0.0_dp, (c_l) >= (0.0_dp))
   res_ = c_l
   return
end function getMixedQual

! qualrout.c:179
recursive subroutine findLinkMassFlow(i_l, tStep)
   integer(int32), value :: i_l
   real(dp), value :: tStep
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: qLink
   real(dp) :: w_l
   j_l = 0
   p_l = 0
   qLink = 0.0_dp
   w_l = 0.0_dp
   qLink = Link(i_l)%newFlow
   j_l = Link(i_l)%node2
   if (qLink < 0.0_dp) then
      j_l = Link(i_l)%node1
   end if
   qLink = abs(qLink)
   if (RouteModel /= DW) then
      qLink = qLink - inlet_capturedFlow(i_l)
   end if
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      w_l = qLink * Link(i_l)%oldQual(p_l)
      Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + w_l
      Link(i_l)%totalLoad(p_l) = Link(i_l)%totalLoad(p_l) + (w_l * tStep)
      p_l = p_l + 1
   end do
   Node(j_l)%qualInflow = Node(j_l)%qualInflow + qLink
end subroutine findLinkMassFlow

! qualrout.c:221
recursive subroutine findNodeQual(j_l)
   integer(int32), value :: j_l
   integer(int32) :: p_l
   real(dp) :: qNode
   p_l = 0
   qNode = 0.0_dp
   qNode = Node(j_l)%qualInflow
   if (qNode > 1.0e-10_dp) then
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) / qNode
         p_l = p_l + 1
      end do
   else
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         if (Node(j_l)%newDepth > ZeroDepth) then
            Node(j_l)%newQual(p_l) = Node(j_l)%oldQual(p_l)
         else
            Node(j_l)%newQual(p_l) = 0.0_dp
         end if
         p_l = p_l + 1
      end do
   end if
end subroutine findNodeQual

! qualrout.c:253
recursive subroutine findLinkQual(i_l, tStep)
   integer(int32), value :: i_l
   real(dp), value :: tStep
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   real(dp) :: wIn
   real(dp) :: qIn
   real(dp) :: qSeep
   real(dp) :: v1
   real(dp) :: v2
   real(dp) :: c1_l
   real(dp) :: c2_l
   real(dp) :: vEvap_l
   real(dp) :: vLosses
   real(dp) :: fEvap
   real(dp) :: barrels
   logical :: b1_
   logical :: b2_
   j_l = 0
   k_l = 0
   p_l = 0
   wIn = 0.0_dp
   qIn = 0.0_dp
   qSeep = 0.0_dp
   v1 = 0.0_dp
   v2 = 0.0_dp
   c1_l = 0.0_dp
   c2_l = 0.0_dp
   vEvap_l = 0.0_dp
   vLosses = 0.0_dp
   fEvap = 0.0_dp
   barrels = 0.0_dp
   j_l = Link(i_l)%node1
   if (Link(i_l)%newFlow < 0.0_dp) then
      j_l = Link(i_l)%node2
   end if
   b1_ = Link(i_l)%type /= CONDUIT_c
   if (.not. b1_) then
      b1_ = Link(i_l)%xsect%type == DUMMY
   end if
   if (b1_) then
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         Link(i_l)%newQual(p_l) = Node(j_l)%newQual(p_l)
         p_l = p_l + 1
      end do
      return
   end if
   k_l = Link(i_l)%subIndex
   barrels = real(Conduit(k_l)%barrels, dp)
   qIn = abs(Conduit(k_l)%q1) * barrels
   qSeep = Conduit(k_l)%seepLossRate * barrels
   vEvap_l = (Conduit(k_l)%evapLossRate * barrels) * tStep
   v1 = Link(i_l)%oldVolume
   v2 = Link(i_l)%newVolume
   vLosses = (qSeep * tStep) + vEvap_l
   fEvap = 1.0_dp
   if ((vEvap_l > 0.0_dp) .and. (v1 > ZeroVolume)) then
      fEvap = fEvap + (vEvap_l / v1)
   end if
   if (RouteModel == SF) then
      call findSFLinkQual(i_l, qSeep, fEvap, tStep)
      return
   end if
   if (RouteModel == DW) then
      qIn = qIn + (((v2 + vLosses) - v1) / tStep)
      qIn = merge(qIn, 0.0_dp, (qIn) >= (0.0_dp))
   end if
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      c1_l = Link(i_l)%oldQual(p_l)
      call massbal_addSeepageLoss(p_l, qSeep * c1_l)
      c1_l = c1_l * fEvap
      c2_l = getReactedQual(p_l, c1_l, v1, tStep)
      wIn = Node(j_l)%newQual(p_l) * qIn
      c2_l = getMixedQual(c2_l, v1, wIn, qIn, tStep)
      b2_ = v2 < ZeroVolume
      if (.not. b2_) then
         b2_ = Link(i_l)%newDepth <= ZeroDepth
      end if
      if (b2_) then
         call massbal_addToFinalStorage(p_l, c2_l * v2)
         c2_l = 0.0_dp
      end if
      Link(i_l)%newQual(p_l) = c2_l
      p_l = p_l + 1
   end do
end subroutine findLinkQual

! qualrout.c:357
recursive subroutine findSFLinkQual(i_l, qSeep, fEvap, tStep)
   integer(int32), value :: i_l
   real(dp), value :: qSeep
   real(dp), value :: fEvap
   real(dp), value :: tStep
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: c1_l
   real(dp) :: c2_l
   real(dp) :: lossRate
   j_l = Link(i_l)%node1
   p_l = 0
   c1_l = 0.0_dp
   c2_l = 0.0_dp
   lossRate = 0.0_dp
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      c1_l = Node(j_l)%newQual(p_l)
      call massbal_addSeepageLoss(p_l, qSeep * c1_l)
      c1_l = c1_l * fEvap
      c2_l = c1_l
      if (Pollut(p_l)%kDecay > 0.0_dp) then
         c2_l = c1_l * exp((-Pollut(p_l)%kDecay) * tStep)
         c2_l = merge(0.0_dp, c2_l, (0.0_dp) >= (c2_l))
         lossRate = (c1_l - c2_l) * Link(i_l)%newFlow
         call massbal_addReactedMass(p_l, lossRate)
      end if
      Link(i_l)%newQual(p_l) = c2_l
      p_l = p_l + 1
   end do
end subroutine findSFLinkQual

! qualrout.c:398
recursive subroutine findStorageQual(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   integer(int32) :: p_l
   integer(int32) :: k_l
   real(dp) :: qIn
   real(dp) :: wIn
   real(dp) :: v1
   real(dp) :: c1_l
   real(dp) :: c2_l
   real(dp) :: qExfil
   real(dp) :: vEvap_l
   real(dp) :: fEvap
   logical :: b1_
   logical :: b2_
   p_l = 0
   k_l = 0
   qIn = 0.0_dp
   wIn = 0.0_dp
   v1 = 0.0_dp
   c1_l = 0.0_dp
   c2_l = 0.0_dp
   qExfil = 0.0_dp
   vEvap_l = 0.0_dp
   fEvap = 1.0_dp
   qIn = Node(j_l)%qualInflow
   v1 = Node(j_l)%oldVolume
   if (Node(j_l)%type == STORAGE_c) then
      call updateHRT(j_l, Node(j_l)%oldVolume, qIn, tStep)
      k_l = Node(j_l)%subIndex
      qExfil = Storage(k_l)%exfilLoss / tStep
      vEvap_l = Storage(k_l)%evapLoss
      if ((vEvap_l > 0.0_dp) .and. (v1 > ZeroVolume)) then
         fEvap = fEvap + (vEvap_l / v1)
      end if
   end if
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      c1_l = Node(j_l)%oldQual(p_l)
      call massbal_addSeepageLoss(p_l, qExfil * c1_l)
      c1_l = c1_l * fEvap
      b1_ = .not. associated(Node(j_l)%treatment)
      if (.not. b1_) then
         b1_ = .not. associated(Node(j_l)%treatment(p_l)%equation)
      end if
      if (b1_) then
         c1_l = getReactedQual(p_l, c1_l, v1, tStep)
      end if
      wIn = Node(j_l)%newQual(p_l)
      c2_l = getMixedQual(c1_l, v1, wIn, qIn, tStep)
      b2_ = Node(j_l)%newVolume <= ZeroVolume
      if (.not. b2_) then
         b2_ = Node(j_l)%newDepth <= ZeroDepth
      end if
      if ((b2_) .and. (qIn <= 1.0e-10_dp)) then
         call massbal_addToFinalStorage(p_l, c2_l * Node(j_l)%newVolume)
         c2_l = 0.0_dp
      end if
      Node(j_l)%newQual(p_l) = c2_l
      p_l = p_l + 1
   end do
end subroutine findStorageQual

! qualrout.c:478
recursive subroutine updateHRT(j_l, v_l, q_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: v_l
   real(dp), value :: q_l
   real(dp), value :: tStep
   integer(int32) :: k_l
   real(dp) :: hrt
   k_l = Node(j_l)%subIndex
   hrt = Storage(k_l)%hrt
   if (v_l < 1.0e-10_dp) then
      hrt = 0.0_dp
   else
      hrt = ((hrt + tStep) * v_l) / (v_l + (q_l * tStep))
   end if
   Storage(k_l)%hrt = merge(hrt, 0.0_dp, (hrt) >= (0.0_dp))
end subroutine updateHRT

! qualrout.c:498
recursive function getReactedQual(p_l, c_l, v1, tStep) result(res_)
   integer(int32), value :: p_l
   real(dp), value :: c_l
   real(dp), value :: v1
   real(dp), value :: tStep
   real(dp) :: res_
   real(dp) :: c2_l
   real(dp) :: lossRate
   real(dp) :: kDecay
   res_ = 0.0_dp
   c2_l = 0.0_dp
   lossRate = 0.0_dp
   kDecay = Pollut(p_l)%kDecay
   if (kDecay == 0.0_dp) then
      res_ = c_l
      return
   end if
   c2_l = c_l * (1.0_dp - (kDecay * tStep))
   c2_l = merge(0.0_dp, c2_l, (0.0_dp) >= (c2_l))
   lossRate = ((c_l - c2_l) * v1) / tStep
   call massbal_addReactedMass(p_l, lossRate)
   res_ = c2_l
   return
end function getReactedQual

! rain.c:118
recursive subroutine rain_open()
   integer(int32) :: i_l
   integer(int32) :: count_l
   type(CPtr) :: dum1_
   i_l = 0
   count_l = 0
   count_l = 0
   i_l = 0
   do while (i_l < Nobjects(GAGE_c))
      if (Gage(i_l)%dataSource == RAIN_FILE) then
         count_l = count_l + 1
      end if
      i_l = i_l + 1
   end do
   nullify(Frain%file)
   if (count_l == 0) then
      Frain%mode = NO_FILE
   else
      select case (Frain%mode)
      case (1)
         dum1_ = getTempFileName(cview(Frain%name))
         Frain%file => c_fopen(cview(Frain%name), lit_166)
         if (.not. associated(Frain%file)) then
            call report_writeErrorMsg(ERR_RAIN_FILE_SCRATCH, lit_0)
            return
         end if
      case (2)
         Frain%file => c_fopen(cview(Frain%name), lit_165)
         if (.not. associated(Frain%file)) then
            call report_writeErrorMsg(ERR_RAIN_FILE_OPEN, cview(Frain%name))
            return
         end if
      case (3)
         Frain%file => c_fopen(cview(Frain%name), lit_166)
         if (.not. associated(Frain%file)) then
            call report_writeErrorMsg(ERR_RAIN_FILE_OPEN, cview(Frain%name))
            return
         end if
      end select
   end if
   if ((Frain%mode == SCRATCH_FILE) .or. (Frain%mode == SAVE_FILE)) then
      call createRainFile(count_l)
   end if
   if (Frain%mode /= NO_FILE) then
      call initRainFile()
   end if
   call rdii_openRdii()
end subroutine rain_open

! rain.c:184
recursive subroutine rain_close()
   integer(int32) :: dum1_
   if (associated(Frain%file)) then
      dum1_ = c_fclose(Frain%file)
      if (Frain%mode == SCRATCH_FILE) then
         dum1_ = c_remove(cview(Frain%name))
      end if
   end if
   nullify(Frain%file)
   call rdii_closeRdii()
end subroutine rain_close

! rain.c:202
recursive subroutine createRainFile(count_l)
   integer(int32), value :: count_l
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32), target :: kount
   integer(int32) :: filePos1
   integer(int32), target :: filePos2
   integer(int32), target :: filePos3
   integer(int32), target :: interval_l
   integer(int32), target :: dummy_l
   integer(int8), target :: staID(0:1024)
   integer(int8), target :: fileStamp_l(0:10)
   integer(int64) :: dum1_
   type(CPtr) :: dum2_
   logical :: b3_
   integer(int32) :: dum4_
   i_l = 0
   k_l = 0
   kount = count_l
   filePos1 = 0
   filePos2 = 0
   filePos3 = 0
   interval_l = 0
   dummy_l = -1
   staID = 0_int8
   call cinit(fileStamp_l, lit_327)
   if ((ErrorCode /= 0) .or. (.not. associated(Frain%file))) then
      return
   end if
   dum1_ = c_fwrite_c(cview(fileStamp_l), int(1_int64 * (strlen(cview(fileStamp_l))), int64), Frain%file)
   dum1_ = c_fwrite_i4(kount, Frain%file)
   filePos1 = int(c_ftell(Frain%file), int32)
   if (count_l > 0) then
      call report_writeRainStats(-1, RainStats)
   end if
   dum2_ = c_strcpy(cview(staID), lit_33)
   i_l = 0
   do while (i_l < count_l)
      dum1_ = c_fwrite_c(cview(staID), int(1_int64 * int(1024 + 1, int64), int64), Frain%file)
      k_l = 1
      do while (k_l <= 3)
         dum1_ = c_fwrite_i4(dummy_l, Frain%file)
         k_l = k_l + 1
      end do
      i_l = i_l + 1
   end do
   filePos2 = int(c_ftell(Frain%file), int32)
   i_l = 0
   do while (i_l < Nobjects(GAGE_c))
      b3_ = ErrorCode /= 0
      if (.not. b3_) then
         b3_ = Gage(i_l)%dataSource /= RAIN_FILE
      end if
      if (b3_) then
         goto 102
      end if
      if (rainFileConflict(i_l) /= 0) then
         exit
      end if
      dum4_ = c_fseek(Frain%file, int(filePos2, int64), 0)
      if (addGageToRainFile(i_l) /= 0) then
         filePos3 = int(c_ftell(Frain%file), int32)
         dum4_ = c_fseek(Frain%file, int(filePos1, int64), 0)
         dum1_ = sstrncpy(cview(staID), cview(Gage(i_l)%staID), 1024_int64)
         interval_l = Interval
         dum1_ = c_fwrite_c(cview(staID), int(1_int64 * int(1024 + 1, int64), int64), Frain%file)
         dum1_ = c_fwrite_i4(interval_l, Frain%file)
         dum1_ = c_fwrite_i4(filePos2, Frain%file)
         dum1_ = c_fwrite_i4(filePos3, Frain%file)
         filePos1 = int(c_ftell(Frain%file), int32)
         filePos2 = filePos3
         call report_writeRainStats(i_l, RainStats)
      end if
      102 continue
      i_l = i_l + 1
   end do
   if (ErrorCode /= 0) then
      dum4_ = c_fclose(Frain%file)
      nullify(Frain%file)
      dum4_ = c_remove(cview(Frain%name))
   end if
end subroutine createRainFile

! rain.c:278
recursive function rainFileConflict(i_l) result(res_)
   integer(int32), value :: i_l
   integer(int32) :: res_
   integer(int32) :: j_l
   type(CPtr) :: staID
   type(CPtr) :: fname
   logical :: b1_
   res_ = 0
   j_l = 0
   staID = cview(Gage(i_l)%staID)
   fname = cview(Gage(i_l)%fname)
   j_l = 0
   do while (j_l < i_l)
      b1_ = strcomp(cview(Gage(j_l)%staID), staID) /= 0
      if (b1_) then
         b1_ = .not. (strcomp(cview(Gage(j_l)%fname), fname) /= 0)
      end if
      if (b1_) then
         call report_writeErrorMsg(ERR_RAIN_FILE_CONFLICT, Gage(i_l)%ID)
         res_ = 1
         return
      end if
      j_l = j_l + 1
   end do
   res_ = 0
   return
end function rainFileConflict

! rain.c:302
recursive function addGageToRainFile(i_l) result(res_)
   integer(int32), value :: i_l
   integer(int32) :: res_
   type(CFile), pointer :: f_l
   integer(int32) :: fileFormat_l
   integer(int32), target :: hdrLines
   integer(int32) :: dum1_
   res_ = 0
   nullify(f_l)
   fileFormat_l = 0
   hdrLines = 0
   StationID = cnull()
   f_l => c_fopen(cview(Gage(i_l)%fname), lit_13)
   if (.not. associated(f_l)) then
      call report_writeErrorMsg(ERR_RAIN_FILE_DATA, cview(Gage(i_l)%fname))
   else
      fileFormat_l = findFileFormat(f_l, i_l, hdrLines)
      if (fileFormat_l == UNKNOWN_FORMAT) then
         call report_writeErrorMsg(ERR_RAIN_FILE_FORMAT, cview(Gage(i_l)%fname))
      else
         GageIndex = i_l
         call readFile(f_l, fileFormat_l, hdrLines, Gage(i_l)%startFileDate, Gage(i_l)%endFileDate)
      end if
      dum1_ = c_fclose(f_l)
   end if
   if (ErrorCode /= 0) then
      res_ = 0
      return
   else
      res_ = 1
      return
   end if
end function addGageToRainFile

! rain.c:341
recursive subroutine initRainFile()
   integer(int8), target :: fileStamp_l(0:10)
   integer(int8), target :: fStamp(0:10)
   integer(int32) :: i_l
   integer(int32), target :: kount
   integer(int64) :: filePos
   integer(int64) :: dum1_
   logical :: b2_
   integer(int32) :: dum3_
   logical :: b4_
   call cinit(fileStamp_l, lit_327)
   call cinit(fStamp, lit_327)
   i_l = 0
   kount = 0
   filePos = 0_int64
   if ((ErrorCode /= 0) .or. (.not. associated(Frain%file))) then
      return
   end if
   call c_rewind(Frain%file)
   dum1_ = c_fread_c(cview(fStamp), int(1_int64 * (strlen(cview(fileStamp_l))), int64), Frain%file)
   if (c_strcmp(cview(fStamp), cview(fileStamp_l)) /= 0) then
      call report_writeErrorMsg(ERR_RAIN_IFACE_FORMAT, lit_0)
      return
   end if
   dum1_ = c_fread_i4(kount, Frain%file)
   filePos = c_ftell(Frain%file)
   i_l = 0
   do while (i_l < Nobjects(GAGE_c))
      b2_ = ErrorCode /= 0
      if (.not. b2_) then
         b2_ = Gage(i_l)%dataSource /= RAIN_FILE
      end if
      if (b2_) then
         goto 100
      end if
      dum3_ = c_fseek(Frain%file, filePos, 0)
      b4_ = .not. (findGageInFile(i_l, kount) /= 0)
      if (.not. b4_) then
         b4_ = Gage(i_l)%startFilePos == Gage(i_l)%endFilePos
      end if
      if (b4_) then
         call report_writeErrorMsg(ERR_RAIN_FILE_GAGE, Gage(i_l)%ID)
      end if
      100 continue
      i_l = i_l + 1
   end do
end subroutine initRainFile

! rain.c:385
recursive function findGageInFile(i_l, kount) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: kount
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32), target :: interval_l
   integer(int32), target :: filePos1
   integer(int32), target :: filePos2
   integer(int8), target :: staID(0:1024)
   integer(int64) :: dum1_
   res_ = 0
   k_l = 0
   interval_l = 0
   filePos1 = 0
   filePos2 = 0
   call cinit(staID, lit_0)
   k_l = 1
   do while (k_l <= kount)
      dum1_ = c_fread_c(cview(staID), int(1_int64 * int(1024 + 1, int64), int64), Frain%file)
      dum1_ = c_fread_i4(interval_l, Frain%file)
      dum1_ = c_fread_i4(filePos1, Frain%file)
      dum1_ = c_fread_i4(filePos2, Frain%file)
      if (c_strcmp(cview(staID), cview(Gage(i_l)%staID)) == 0) then
         Gage(i_l)%rainType = RAINFALL_VOLUME
         Gage(i_l)%rainInterval = interval_l
         Gage(i_l)%startFilePos = int(filePos1, int64)
         Gage(i_l)%endFilePos = int(filePos2, int64)
         Gage(i_l)%currentFilePos = Gage(i_l)%startFilePos
         res_ = 1
         return
      end if
      k_l = k_l + 1
   end do
   res_ = 0
   return
end function findGageInFile

! rain.c:420
recursive function findFileFormat(f_l, i_l, hdrLines) result(res_)
   type(CFile), pointer, intent(in) :: f_l
   integer(int32), value :: i_l
   integer(int32), intent(inout), target :: hdrLines
   integer(int32) :: res_
   integer(int32) :: fileFormat_l
   integer(int32) :: lineCount
   integer(int32) :: maxCount
   integer(int32) :: n_l
   integer(int32), target :: div
   integer(int64), target :: sn2
   integer(int8), target :: recdType(0:3)
   integer(int8), target :: elemType(0:4)
   integer(int8), target :: coopID(0:5)
   integer(int8), target :: line(0:1023)
   integer(int32), target :: year
   integer(int32), target :: month
   integer(int32), target :: day
   integer(int32), target :: hour
   integer(int32), target :: minute
   integer(int32), target :: elem
   real(sp), target :: x_l
   type(CPtr) :: s1_
   type(CPtr) :: s2_
   type(CPtr) :: s3_
   type(CPtr) :: s4_
   type(CPtr) :: s5_
   type(CPtr) :: s6_
   type(CPtr) :: s7_
   type(CPtr) :: s8_
   type(CPtr) :: s9_
   logical :: b10_
   logical :: b11_
   logical :: b12_
   logical :: b13_
   logical :: b14_
   res_ = 0
   fileFormat_l = 0
   lineCount = 0
   maxCount = 5
   n_l = 0
   div = 0
   sn2 = 0_int64
   recdType = 0_int8
   elemType = 0_int8
   call cinit(coopID, lit_0)
   line = 0_int8
   year = 0
   month = 0
   day = 0
   hour = 0
   minute = 0
   elem = 0
   x_l = 0.0_sp
   fileFormat_l = UNKNOWN_FORMAT
   hasStationName = 0
   UnitsFactor = 1.0_dp
   Interval = 0
   hdrLines = 0
   lineCount = 1
   do while (lineCount <= maxCount)
      if (cisnull(c_fgets(cview(line), 1024, f_l))) then
         res_ = fileFormat_l
         return
      end if
      s1_ = cview(elemType)
      n_l = c_sscanf(cview(line), lit_328, sn2, div, s1_)
      if (n_l == 3) then
         Interval = getNWSInterval(cview(elemType))
         TimeOffset = Interval
         if (Interval > 0) then
            fileFormat_l = NWS_SPACE_DELIMITED
            exit
         end if
      end if
      s2_ = cview(elemType)
      s3_ = cview(recdType)
      n_l = c_sscanf(cadd(cview(line), 37), lit_329, div, s2_, s3_, year)
      if (n_l == 4) then
         Interval = getNWSInterval(cview(elemType))
         TimeOffset = Interval
         if (Interval > 0) then
            fileFormat_l = NWS_SPACE_DELIMITED
            hasStationName = 1
            exit
         end if
      end if
      s4_ = cview(elemType)
      n_l = c_sscanf(cview(line), lit_330, sn2, div, s4_)
      if (n_l == 3) then
         Interval = getNWSInterval(cview(elemType))
         TimeOffset = Interval
         if (Interval > 0) then
            fileFormat_l = NWS_COMMA_DELIMITED
            exit
         end if
      end if
      s5_ = cview(elemType)
      s6_ = cview(recdType)
      n_l = c_sscanf(cadd(cview(line), 37), lit_331, div, s5_, s6_, year)
      if (n_l == 4) then
         Interval = getNWSInterval(cview(elemType))
         TimeOffset = Interval
         if (Interval > 0) then
            fileFormat_l = NWS_COMMA_DELIMITED
            hasStationName = 1
            exit
         end if
      end if
      s7_ = cview(recdType)
      s8_ = cview(elemType)
      n_l = c_sscanf(cview(line), lit_332, s7_, sn2, div, s8_)
      if (n_l == 4) then
         Interval = getNWSInterval(cview(elemType))
         TimeOffset = Interval
         if (Interval > 0) then
            fileFormat_l = NWS_TAPE
            exit
         end if
      end if
      s9_ = cview(coopID)
      n_l = c_sscanf(cview(line), lit_333, s9_, sn2)
      b10_ = n_l == 2
      if (b10_) then
         b10_ = c_strcmp(cview(coopID), lit_334) == 0
      end if
      if (b10_) then
         fileFormat_l = findNWSOnlineFormat(f_l, cview(line))
         exit
      end if
      n_l = c_sscanf(cview(line), lit_335, sn2, year, month, day, elem)
      if (n_l == 5) then
         b11_ = elem == 123
         if (b11_) then
            b11_ = strlen(cview(line)) >= 185_int64
         end if
         if (b11_) then
            fileFormat_l = AES_HLY
            Interval = 3600
            TimeOffset = Interval
            UnitsFactor = 1.0_dp / 25.4_dp
            exit
         end if
      end if
      n_l = c_sscanf(cview(line), lit_336, sn2, year, month, day, elem)
      if (n_l == 5) then
         b12_ = elem == 159
         if (b12_) then
            b12_ = strlen(cview(line)) >= 691_int64
         end if
         if (b12_) then
            fileFormat_l = CMC_FIF
            Interval = 900
         else
            b14_ = elem == 123
            if (b14_) then
               b14_ = strlen(cview(line)) >= 186_int64
            end if
            if (b14_) then
               fileFormat_l = CMC_HLY
               Interval = 3600
            end if
         end if
         if ((fileFormat_l == CMC_FIF) .or. (fileFormat_l == CMC_HLY)) then
            TimeOffset = Interval
            UnitsFactor = 1.0_dp / 25.4_dp
            exit
         end if
      end if
      if (parseStdLine(cview(line), year, month, day, hour, minute, x_l) /= 0) then
         fileFormat_l = STD_SPACE_DELIMITED
         RainType = Gage(i_l)%rainType
         Interval = Gage(i_l)%rainInterval
         if (Gage(i_l)%rainUnits == SI) then
            UnitsFactor = 1.0_dp / 25.4_dp
         end if
         TimeOffset = 0
         StationID = cview(Gage(i_l)%staID)
         exit
      end if
      hdrLines = hdrLines + 1
      lineCount = lineCount + 1
   end do
   if (fileFormat_l /= UNKNOWN_FORMAT) then
      Gage(i_l)%rainInterval = Interval
   end if
   res_ = fileFormat_l
   return
end function findFileFormat

! rain.c:584
recursive function findNWSOnlineFormat(f_l, line) result(res_)
   type(CFile), pointer, intent(in) :: f_l
   type(CPtr), value :: line
   integer(int32) :: res_
   integer(int32) :: n_l
   integer(int32) :: fileFormat_l
   type(CPtr) :: str
   type(CPtr) :: dum1_
   res_ = 0
   n_l = 0
   fileFormat_l = UNKNOWN_FORMAT
   str = cnull()
   call c_rewind(f_l)
   dum1_ = c_fgets(line, 1024, f_l)
   str = c_strstr(line, lit_337)
   if (.not. cisnull(str)) then
      Interval = 3600
      TimeOffset = Interval
      ValueOffset = int(cdiff(str, line), int32)
      fileFormat_l = NWS_ONLINE_60
   else
      str = c_strstr(line, lit_338)
      if (.not. cisnull(str)) then
         Interval = 900
         TimeOffset = Interval
         ValueOffset = int(cdiff(str, line), int32)
         fileFormat_l = NWS_ONLINE_15
      else
         res_ = UNKNOWN_FORMAT
         return
      end if
   end if
   n_l = 1
   do while (n_l <= 5)
      if (cisnull(c_fgets(line, 1024, f_l))) then
         res_ = UNKNOWN_FORMAT
         return
      end if
      if (cisnull(c_strstr(line, lit_334))) then
         goto 100
      end if
      str = c_strrchr(line, 58)
      if (cisnull(str)) then
         res_ = UNKNOWN_FORMAT
         return
      end if
      n_l = int(cdiff(str, line), int32)
      DataOffset = n_l - 11
      res_ = fileFormat_l
      return
      100 continue
      n_l = n_l + 1
   end do
   res_ = UNKNOWN_FORMAT
   return
end function findNWSOnlineFormat

