      flag2 = 0
      v_l = 99999_int64
      hour = 25
      minute = 0
      select case (fileFormat_l)
      case (1)
         n_l = c_sscanf(cadd(line, k_l), lit_343, hour, minute, v_l, flag1, flag2)
         k_l = k_l + 12
      case (2)
         n_l = c_sscanf(cadd(line, k_l), lit_344, hour, minute, v_l, flag1, flag2)
