   integer(int32), target :: flag
   integer(int32) :: isMissing
   real(dp) :: date1
   integer(int64), target :: sn
   integer(int64), target :: v_l
   integer(int32) :: col
   integer(int32) :: j_l
   integer(int32) :: jMax
   integer(int32), target :: elem
   integer(int32), target :: y_l
   integer(int32), target :: m_l
   integer(int32), target :: d_l
   integer(int32) :: hour
   integer(int32) :: minute
   real(sp) :: x_l
   res_ = 0
   flag = 0
   isMissing = 0
   date1 = 0.0_dp
   sn = 0_int64
   v_l = 0_int64
   col = 0
   j_l = 0
   jMax = 0
   elem = 0
   y_l = 0
   m_l = 0
   d_l = 0
   hour = 0
   minute = 0
   x_l = 0.0_sp
   if (fileFormat_l == AES_HLY) then
      if (c_sscanf(line, lit_335, sn, y_l, m_l, d_l, elem) < 5) then
         res_ = 0
         return
      end if
      if (y_l < 100) then
         y_l = y_l + 2000
      else
         y_l = y_l + 1000
      end if
      col = 17
   else
      if (c_sscanf(line, lit_336, sn, y_l, m_l, d_l, elem) < 5) then
         res_ = 0
         return
      end if
      col = 18
   end if
   date1 = datetime_encodeDate(y_l, m_l, d_l)
   if ((day1 /= (-693594.0_dp)) .and. (date1 < day1)) then
      res_ = 0
      return
   end if
   if ((day2 /= (-693594.0_dp)) .and. (date1 > day2)) then
      res_ = -1
      return
   end if
   if ((fileFormat_l == AES_HLY) .and. (elem /= 123)) then
      res_ = 0
      return
   else if ((fileFormat_l == CMC_FIF) .and. (elem /= 159)) then
      res_ = 0
      return
   else if ((fileFormat_l == CMC_HLY) .and. (elem /= 123)) then
      res_ = 0
      return
   end if
   hour = 0
   minute = 0
   jMax = 24
