      col = col + 7
      if (v_l == (-99999_int64)) then
         isMissing = 1
      else
         isMissing = 0
      end if
      x_l = real((real(v_l, dp) / 10.0_dp) / 25.4_dp, sp)
      if ((x_l > 0.0_sp) .or. (isMissing /= 0)) then
         call saveRainfall(date1, hour, minute, x_l, isMissing)
      end if
      if (fileFormat_l == CMC_FIF) then
         minute = minute + 15
         if (minute == 60) then
            minute = 0
            hour = hour + 1
         end if
      else
         hour = hour + 1
      end if
      j_l = j_l + 1
   end do
   res_ = 1
   return
end function readCMCLine

! rain.c:994
recursive function readStdLine(line, day1, day2) result(res_)
   type(CPtr), value :: line
   real(dp), value :: day1
   real(dp), value :: day2
   integer(int32) :: res_
   real(dp) :: date1
   real(dp) :: date2
   integer(int32), target :: year
   integer(int32), target :: month
   integer(int32), target :: day
   integer(int32), target :: hour
   integer(int32), target :: minute
   real(sp), target :: x_l
   res_ = 0
   date1 = 0.0_dp
   date2 = 0.0_dp
   year = 0
   month = 0
   day = 0
   hour = 0
   minute = 0
   x_l = 0.0_sp
   if (.not. (parseStdLine(line, year, month, day, hour, minute, x_l) /= 0)) then
      res_ = 0
      return
   end if
   date1 = datetime_encodeDate(year, month, day)
   if ((day1 /= (-693594.0_dp)) .and. (date1 < day1)) then
      res_ = 0
      return
   end if
   if ((day2 /= (-693594.0_dp)) .and. (date1 > day2)) then
      res_ = -1
      return
   end if
   date2 = date1 + datetime_encodeTime(hour, minute, 0)
   if (date2 <= PreviousDate) then
      call report_writeErrorMsg(ERR_RAIN_FILE_SEQUENCE, cview(Gage(GageIndex)%fname))
      call report_writeLine(line)
      res_ = -1
      return
   end if
   PreviousDate = date2
   select case (RainType)
   case (0)
      x_l = (x_l * real(Interval, sp)) / 3600.0_sp
   case (2)
      if (x_l >= RainAccum) then
         x_l = x_l - RainAccum
         RainAccum = RainAccum + x_l
      else
         RainAccum = x_l
      end if
   end select
   x_l = x_l * real(UnitsFactor, sp)
   call saveRainfall(date1, hour, minute, x_l, 0)
   res_ = 1
   return
end function readStdLine

! rain.c:1052
recursive function parseStdLine(line, year, month, day, hour, minute, value_l) result(res_)
   type(CPtr), value :: line
   integer(int32), intent(inout), target :: year
   integer(int32), intent(inout), target :: month
   integer(int32), intent(inout), target :: day
   integer(int32), intent(inout), target :: hour
   integer(int32), intent(inout), target :: minute
   real(sp), intent(inout), target :: value_l
   integer(int32) :: res_
   integer(int32) :: n_l
   integer(int8), target :: token_l(0:1023)
   type(CPtr) :: s1_
   logical :: b2_
   res_ = 0
   n_l = 0
   token_l = 0_int8
   s1_ = cview(token_l)
   n_l = c_sscanf(line, lit_350, s1_, year, month, day, hour, minute, value_l)
   if (n_l < 7) then
      res_ = 0
      return
   end if
   b2_ = .not. cisnull(StationID)
   if (b2_) then
      b2_ = .not. (strcomp(cview(token_l), StationID) /= 0)
   end if
   if (b2_) then
      res_ = 0
      return
   end if
   res_ = 1
   return
end function parseStdLine

! rain.c:1078
recursive subroutine saveAccumRainfall(date1, hour, minute, v_l)
   real(dp), value :: date1
   integer(int32), value :: hour
   integer(int32), value :: minute
   integer(int64), value :: v_l
   real(dp), target :: date2
   integer(int32) :: n_l
   integer(int32) :: j_l
   real(sp), target :: x_l
   integer(int64) :: dum1_
   date2 = 0.0_dp
   n_l = 0
   j_l = 0
   x_l = 0.0_sp
   if (AccumStartDate == (-693594.0_dp)) then
      return
   end if
   date2 = date1 + datetime_encodeTime(hour, minute, 0)
   n_l = int((datetime_timeDiff(date2, AccumStartDate) / int(Interval, int64)) + 1_int64, int32)
   if (v_l == 99999_int64) then
      RainStats%periodsMissing = RainStats%periodsMissing + int(n_l, int64)
      return
   end if
   RainStats%periodsRain = RainStats%periodsRain + int(n_l, int64)
   x_l = (real(v_l, sp) / real(n_l, sp)) / 100.0_sp
   if (x_l > 0.0_sp) then
      date2 = datetime_addSeconds(AccumStartDate, real(-TimeOffset, dp))
      if (RainStats%startDate == (-693594.0_dp)) then
         RainStats%startDate = date2
      end if
      j_l = 0
      do while (j_l < n_l)
         dum1_ = c_fwrite_r8(date2, Frain%file)
         dum1_ = c_fwrite_r4(x_l, Frain%file)
         date2 = datetime_addSeconds(date2, real(Interval, dp))
         RainStats%endDate = date2
         j_l = j_l + 1
      end do
   end if
   AccumStartDate = -693594.0_dp
end subroutine saveAccumRainfall

! rain.c:1133
recursive subroutine saveRainfall(date1, hour, minute, x_l, isMissing)
   real(dp), value :: date1
   integer(int32), value :: hour
   integer(int32), value :: minute
   real(sp), value, target :: x_l
   integer(int32), value :: isMissing
   real(dp), target :: date2
   integer(int32) :: seconds
   integer(int64) :: dum1_
   date2 = 0.0_dp
   seconds = 0
   if (isMissing /= 0) then
      RainStats%periodsMissing = RainStats%periodsMissing + 1_int64
   else
      RainStats%periodsRain = RainStats%periodsRain + 1_int64
   end if
   if (.not. (isMissing /= 0)) then
      seconds = ((3600 * hour) + (60 * minute)) - TimeOffset
      date2 = datetime_addSeconds(date1, real(seconds, dp))
      dum1_ = c_fwrite_r8(date2, Frain%file)
      dum1_ = c_fwrite_r4(x_l, Frain%file)
      if (RainStats%startDate == (-693594.0_dp)) then
         RainStats%startDate = date2
      end if
      RainStats%endDate = date2
   end if
end subroutine saveRainfall

! rdii.c:152
recursive function rdii_readRdiiInflow(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: k_l
   real(dp), target :: a_l
   type(TRdiiInflow), pointer :: inflow
   res_ = 0
   j_l = 0
   k_l = 0
   a_l = 0.0_dp
   nullify(inflow)
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(NODE_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   k_l = project_findObject(UNITHYD_c, tok_l(1))
   if (k_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   if ((.not. (getDouble(tok_l(2), a_l) /= 0)) .or. (a_l < 0.0_dp)) then
      res_ = error_setInpError(ERR_NUMBER, tok_l(2))
      return
   end if
   inflow => Node(j_l)%rdiiInflow
   if (.not. associated(inflow)) then
      allocate(inflow)
      if (.not. associated(inflow)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
   end if
   inflow%unitHyd = k_l
   inflow%area = a_l / UCF(LANDAREA)
   Node(j_l)%rdiiInflow => inflow
   res_ = 0
   return
end function rdii_readRdiiInflow

! rdii.c:198
recursive subroutine rdii_initUnitHyd(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   integer(int32) :: m_l
   i_l = 0
   m_l = 0
   m_l = 0
   do while (m_l < 12)
