      do while (i_l < 3)
         UnitHyd(j_l)%iaMax(i_l, m_l) = 0.0_dp
         UnitHyd(j_l)%iaRecov(i_l, m_l) = 0.0_dp
         UnitHyd(j_l)%iaInit(i_l, m_l) = 0.0_dp
         UnitHyd(j_l)%r(i_l, m_l) = 0.0_dp
         UnitHyd(j_l)%tPeak(i_l, m_l) = 0_int64
         UnitHyd(j_l)%tBase(i_l, m_l) = 0_int64
         i_l = i_l + 1
      end do
      m_l = m_l + 1
   end do
end subroutine rdii_initUnitHyd

! rdii.c:224
recursive function rdii_readUnitHydParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   integer(int32) :: g_l
   real(dp), target :: x_l(0:5)
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   m_l = 0
   g_l = 0
   x_l = 0.0_dp
   j_l = project_findObject(UNITHYD_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   if (cisnull(UnitHyd(j_l)%ID)) then
      UnitHyd(j_l)%ID = project_findID(UNITHYD_c, tok_l(0))
   end if
   if (ntoks == 2) then
      g_l = project_findObject(GAGE_c, tok_l(1))
      if (g_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      UnitHyd(j_l)%rainGage = g_l
      Gage(g_l)%isUsed = 1
      res_ = 0
      return
   else if (ntoks < 6) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   m_l = datetime_findMonth(tok_l(1))
   if (m_l == 0) then
      if (.not. (match(tok_l(1), lit_351) /= 0)) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
         return
      end if
   end if
   k_l = findmatch(tok_l(2), UHTypeWords)
   if (k_l < 0) then
      res_ = readOldUHFormat(j_l, m_l, tok_l, ntoks)
      return
   end if
   i_l = 0
   do while (i_l < 3)
      if (.not. (getDouble(tok_l(i_l + 3), x_l(i_l)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 3))
         return
      end if
      i_l = i_l + 1
   end do
   i_l = 3
   do while (i_l < 6)
      x_l(i_l) = 0.0_dp
      if (ntoks > (i_l + 3)) then
         if (.not. (getDouble(tok_l(i_l + 3), x_l(i_l)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 2))
            return
         end if
      end if
      i_l = i_l + 1
   end do
   call setUnitHydParams(j_l, k_l, m_l, x_l)
   res_ = 0
   return
end function rdii_readUnitHydParams

! rdii.c:293
recursive function readOldUHFormat(j_l, m_l, tok_l, ntoks) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: m_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: k_l
   real(dp), target :: p_l(0:8)
   real(dp), target :: x_l(0:5)
   res_ = 0
   i_l = 0
   k_l = 0
   p_l = 0.0_dp
   x_l = 0.0_dp
   if (ntoks < 11) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   i_l = 0
   do while (i_l < 9)
      if (.not. (getDouble(tok_l(i_l + 2), p_l(i_l)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 2))
         return
      end if
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < 3)
      x_l(i_l + 3) = 0.0_dp
      if (ntoks > (i_l + 11)) then
         if (.not. (getDouble(tok_l(i_l + 11), x_l(i_l + 3)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 11))
            return
         end if
      end if
      i_l = i_l + 1
   end do
   k_l = 0
   do while (k_l < 3)
      i_l = 0
      do while (i_l < 3)
         x_l(i_l) = p_l((3 * k_l) + i_l)
         call setUnitHydParams(j_l, k_l, m_l, x_l)
         i_l = i_l + 1
      end do
      k_l = k_l + 1
   end do
   res_ = 0
   return
end function readOldUHFormat

! rdii.c:342
recursive subroutine setUnitHydParams(j_l, i_l, m_l, x_l)
   integer(int32), value :: j_l
   integer(int32), value :: i_l
   integer(int32), value :: m_l
   real(dp), pointer, intent(in) :: x_l(:)
   integer(int32) :: m1
   integer(int32) :: m2
   real(dp) :: t_l
   real(dp) :: k_l
   real(dp) :: tBase
   m1 = 0
   m2 = 0
   t_l = 0.0_dp
   k_l = 0.0_dp
   tBase = 0.0_dp
   if (m_l == 0) then
      m1 = 0
      m2 = 11
   else
      m1 = m_l - 1
      m2 = m1
   end if
   m_l = m1
   do while (m_l <= m2)
      UnitHyd(j_l)%r(i_l, m_l) = x_l(0)
      t_l = x_l(1)
      k_l = x_l(2)
      tBase = t_l * (1.0_dp + k_l)
      UnitHyd(j_l)%tPeak(i_l, m_l) = d2l(t_l * 3600.0_dp)
      UnitHyd(j_l)%tBase(i_l, m_l) = d2l(tBase * 3600.0_dp)
      UnitHyd(j_l)%iaMax(i_l, m_l) = x_l(3)
      UnitHyd(j_l)%iaRecov(i_l, m_l) = x_l(4)
      UnitHyd(j_l)%iaInit(i_l, m_l) = x_l(5)
      m_l = m_l + 1
   end do
end subroutine setUnitHydParams

