! rdii.c:408
recursive subroutine rdii_openRdii()
   integer(int8), target :: fStamp(0:10)
   integer(int64) :: dum1_
   integer(int32) :: dum2_
   call cinit(fStamp, lit_352)
   nullify(RdiiNodeIndex)
   nullify(RdiiNodeFlow)
   NumRdiiNodes = 0
   RdiiStartDate = -693594.0_dp
   if (IgnoreRDII /= 0) then
      return
   end if
   if (Frdii%mode /= USE_FILE) then
      call createRdiiFile()
   end if
   if ((Frdii%mode == NO_FILE) .or. (ErrorCode /= 0)) then
      return
   end if
   Frdii%file => c_fopen(cview(Frdii%name), lit_353)
   if (.not. associated(Frdii%file)) then
      if (Frdii%mode == SCRATCH_FILE) then
         call report_writeErrorMsg(ERR_RDII_FILE_SCRATCH, lit_0)
      else
         call report_writeErrorMsg(ERR_RDII_FILE_OPEN, cview(Frdii%name))
      end if
      return
   end if
   dum1_ = c_fread_c(cview(fStamp), int(1_int64 * (strlen(cview(FileStamp))), int64), Frdii%file)
   if (c_strcmp(cview(fStamp), cview(FileStamp)) == 0) then
      RdiiFileType = BINARY
      ErrorCode = readRdiiFileHeader()
   else
      dum2_ = c_fclose(Frdii%file)
      RdiiFileType = TEXT
      call openRdiiTextFile()
   end if
   if (ErrorCode /= 0) then
      call report_writeErrorMsg(ErrorCode, cview(Frdii%name))
   else
      call readRdiiFlows()
   end if
end subroutine rdii_openRdii

! rdii.c:470
recursive subroutine openRdiiTextFile()
   Frdii%file => c_fopen(cview(Frdii%name), lit_13)
   if (.not. associated(Frdii%file)) then
      if (Frdii%mode == SCRATCH_FILE) then
         call report_writeErrorMsg(ERR_RDII_FILE_SCRATCH, lit_0)
      else
         call report_writeErrorMsg(ERR_RDII_FILE_OPEN, cview(Frdii%name))
      end if
      return
   end if
   ErrorCode = readRdiiTextFileHeader()
   if (ErrorCode /= 0) then
      call report_writeErrorMsg(ErrorCode, cview(Frdii%name))
   end if
end subroutine openRdiiTextFile

! rdii.c:497
recursive subroutine rdii_closeRdii()
   integer(int32) :: dum1_
   if (associated(Frdii%file)) then
      dum1_ = c_fclose(Frdii%file)
   end if
   if (Frdii%mode == SCRATCH_FILE) then
      dum1_ = c_remove(cview(Frdii%name))
   end if
   if (associated(RdiiNodeIndex)) then
      ! 
      nullify(RdiiNodeIndex)
   end if
   if (associated(RdiiNodeFlow)) then
      ! 
      nullify(RdiiNodeFlow)
   end if
end subroutine rdii_closeRdii

! rdii.c:512
recursive function rdii_getNumRdiiFlows(aDate) result(res_)
   real(dp), value :: aDate
   integer(int32) :: res_
   res_ = 0
   if (NumRdiiNodes == 0) then
      res_ = 0
      return
   end if
   if (.not. associated(Frdii%file)) then
      res_ = 0
      return
   end if
   do while (.not. (c_feof(Frdii%file) /= 0))
      if (RdiiStartDate == (-693594.0_dp)) then
         res_ = 0
         return
      end if
      if (aDate < RdiiStartDate) then
         res_ = 0
         return
      end if
      if (aDate < RdiiEndDate) then
         res_ = NumRdiiNodes
         return
      else
         call readRdiiFlows()
      end if
   end do
   res_ = 0
   return
end function rdii_getNumRdiiFlows

! rdii.c:542
recursive subroutine rdii_getRdiiFlow(i_l, j_l, q_l)
   integer(int32), value :: i_l
   integer(int32), intent(inout), target :: j_l
   real(dp), intent(inout), target :: q_l
   if ((i_l >= 0) .and. (i_l < NumRdiiNodes)) then
      j_l = RdiiNodeIndex(i_l)
      q_l = real(RdiiNodeFlow(i_l), dp)
   end if
end subroutine rdii_getRdiiFlow

! rdii.c:560
recursive function readRdiiFileHeader() result(res_)
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int64) :: dum1_
   res_ = 0
   i_l = 0
   j_l = 0
   dum1_ = c_fread_i4(RdiiStep, Frdii%file)
   if (RdiiStep <= 0) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   dum1_ = c_fread_i4(NumRdiiNodes, Frdii%file)
   if (NumRdiiNodes <= 0) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   allocate(RdiiNodeIndex(0:int(NumRdiiNodes, int64) - 1))
   RdiiNodeIndex = 0
   if (.not. associated(RdiiNodeIndex)) then
      res_ = ERR_MEMORY
      return
   end if
   allocate(RdiiNodeFlow(0:int(NumRdiiNodes, int64) - 1))
   RdiiNodeFlow = 0.0_sp
   if (.not. associated(RdiiNodeFlow)) then
      res_ = ERR_MEMORY
      return
   end if
   if (c_feof(Frdii%file) /= 0) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   dum1_ = c_fread_i4a(RdiiNodeIndex, 0, int(int(NumRdiiNodes, int64), int32), Frdii%file)
   i_l = 0
   do while (i_l < NumRdiiNodes)
      j_l = RdiiNodeIndex(i_l)
      if (.not. associated(Node(j_l)%rdiiInflow)) then
         res_ = ERR_RDII_FILE_FORMAT
         return
      end if
      i_l = i_l + 1
   end do
   if (c_feof(Frdii%file) /= 0) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   res_ = 0
   return
end function readRdiiFileHeader

! rdii.c:595
recursive function readRdiiTextFileHeader() result(res_)
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int8), target :: line(0:1024)
   integer(int8), target :: s1(0:1024)
   integer(int8), target :: s2(0:1024)
   type(CPtr) :: dum1_
   type(CPtr) :: s2_
   logical :: b3_
   type(CPtr) :: s4_
   type(CPtr) :: s5_
   type(CPtr) :: s6_
   res_ = 0
   i_l = 0
   j_l = 0
   line = 0_int8
   call cinit(s1, lit_0)
   s2 = 0_int8
   dum1_ = c_fgets(cview(line), 1024, Frdii%file)
   s2_ = cview(s1)
   b3_ = .not. (c_sscanf(cview(line), lit_169, s2_) /= 0)
   if (.not. b3_) then
      b3_ = c_strcmp(cview(s1), lit_181) /= 0
   end if
   if (b3_) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Frdii%file)
   RdiiStep = 0
   dum1_ = c_fgets(cview(line), 1024, Frdii%file)
   if ((.not. (c_sscanf(cview(line), lit_182, RdiiStep) /= 0)) .or. (RdiiStep <= 0)) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Frdii%file)
   dum1_ = c_fgets(cview(line), 1024, Frdii%file)
   s4_ = cview(s1)
   s5_ = cview(s2)
   if (c_sscanf(cview(line), lit_44, s4_, s5_) < 2) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   RdiiFlowUnits = findmatch(cview(s2), FlowUnitWords)
   if (RdiiFlowUnits < 0) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Frdii%file)
   if ((c_sscanf(cview(line), lit_182, NumRdiiNodes) < 1) .or. (NumRdiiNodes <= 0)) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   allocate(RdiiNodeIndex(0:int(NumRdiiNodes, int64) - 1))
   RdiiNodeIndex = 0
   if (.not. associated(RdiiNodeIndex)) then
      res_ = ERR_MEMORY
      return
   end if
   allocate(RdiiNodeFlow(0:int(NumRdiiNodes, int64) - 1))
   RdiiNodeFlow = 0.0_sp
   if (.not. associated(RdiiNodeFlow)) then
      res_ = ERR_MEMORY
      return
   end if
   i_l = 0
   do while (i_l < NumRdiiNodes)
      if (c_feof(Frdii%file) /= 0) then
         res_ = ERR_RDII_FILE_FORMAT
         return
      end if
      dum1_ = c_fgets(cview(line), 1024, Frdii%file)
      s6_ = cview(s1)
      if (.not. (c_sscanf(cview(line), lit_169, s6_) /= 0)) then
         res_ = ERR_RDII_FILE_FORMAT
         return
      end if
      j_l = project_findObject(NODE_c, cview(s1))
      if (j_l < 0) then
         res_ = ERR_RDII_FILE_FORMAT
         return
      end if
      RdiiNodeIndex(i_l) = j_l
      i_l = i_l + 1
   end do
   if (c_feof(Frdii%file) /= 0) then
      res_ = ERR_RDII_FILE_FORMAT
      return
   end if
   dum1_ = c_fgets(cview(line), 1024, Frdii%file)
   res_ = 0
   return
end function readRdiiTextFileHeader

! rdii.c:663
recursive subroutine readRdiiFlows()
   integer(int64) :: dum1_
   if (RdiiFileType == TEXT) then
      call readRdiiTextFlows()
   else
      RdiiStartDate = -693594.0_dp
      RdiiEndDate = -693594.0_dp
      if (c_feof(Frdii%file) /= 0) then
         return
      end if
      dum1_ = c_fread_r8(RdiiStartDate, Frdii%file)
      if (RdiiStartDate == (-693594.0_dp)) then
         return
      end if
      if (c_fread_r4a(RdiiNodeFlow, 0, int(int(NumRdiiNodes, int64), int32), Frdii%file) < int(NumRdiiNodes, int64)) then
         RdiiStartDate = -693594.0_dp
      else
         RdiiEndDate = datetime_addSeconds(RdiiStartDate, real(RdiiStep, dp))
      end if
   end if
end subroutine readRdiiFlows

! rdii.c:686
recursive subroutine readRdiiTextFlows()
   integer(int32) :: i_l
   integer(int32) :: n_l
   integer(int32), target :: yr
   integer(int32), target :: mon
   integer(int32), target :: day
   integer(int32), target :: hr
   integer(int32), target :: min_l
   integer(int32), target :: sec
   real(dp), target :: x_l
   integer(int8), target :: line(0:1024)
   integer(int8), target :: s_l(0:1024)
   type(CPtr) :: dum1_
   type(CPtr) :: s2_
   i_l = 0
   n_l = 0
   yr = 0
   mon = 0
   day = 0
   hr = 0
   min_l = 0
   sec = 0
   x_l = 0.0_dp
   line = 0_int8
   s_l = 0_int8
   RdiiStartDate = -693594.0_dp
   i_l = 0
   do while (i_l < NumRdiiNodes)
      if (c_feof(Frdii%file) /= 0) then
         return
      end if
      dum1_ = c_fgets(cview(line), 1024, Frdii%file)
      s2_ = cview(s_l)
      n_l = c_sscanf(cview(line), lit_354, s2_, yr, mon, day, hr, min_l, sec, x_l)
      if (n_l < 8) then
         return
      end if
      RdiiNodeFlow(i_l) = real(x_l / Qcf(RdiiFlowUnits), sp)
      i_l = i_l + 1
   end do
   RdiiStartDate = datetime_encodeDate(yr, mon, day) + datetime_encodeTime(hr, min_l, sec)
   RdiiEndDate = datetime_addSeconds(RdiiStartDate, real(RdiiStep, dp))
end subroutine readRdiiTextFlows

! rdii.c:720
recursive subroutine createRdiiFile()
   integer(int32) :: hasRdii
   real(dp) :: elapsedTime_l
   real(dp) :: duration
   real(dp) :: currentDate_l
   hasRdii = 0
   elapsedTime_l = 0.0_dp
   duration = 0.0_dp
   currentDate_l = 0.0_dp
   RdiiStep = WetStep
   NumRdiiNodes = getNumRdiiNodes()
   if (NumRdiiNodes == 0) then
      Frdii%mode = NO_FILE
      return
   else if (Frdii%mode == NO_FILE) then
      Frdii%mode = SCRATCH_FILE
   end if
   call validateRdii()
   call initGageData()
   if (ErrorCode /= 0) then
      return
   end if
   call openRdiiProcessor()
   if (.not. (ErrorCode /= 0)) then
      call initUnitHydData()
      duration = TotalDuration / 1000.0_dp
      elapsedTime_l = 0.0_dp
      do while ((elapsedTime_l <= duration) .and. (.not. (ErrorCode /= 0)))
         currentDate_l = StartDateTime + (elapsedTime_l / 86400.0_dp)
         call getRainfall(currentDate_l)
         call getUnitHydRdii(currentDate_l)
         hasRdii = getNodeRdii()
         if (hasRdii /= 0) then
            call saveRdiiFlows(currentDate_l)
         end if
         elapsedTime_l = elapsedTime_l + real(RdiiStep, dp)
      end do
   end if
   call closeRdiiProcessor()
end subroutine createRdiiFile

! rdii.c:793
recursive function getNumRdiiNodes() result(res_)
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: n_l
   res_ = 0
   j_l = 0
   n_l = 0
   n_l = 0
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      if (associated(Node(j_l)%rdiiInflow)) then
         n_l = n_l + 1
      end if
      j_l = j_l + 1
   end do
   res_ = n_l
   return
end function getNumRdiiNodes

! rdii.c:813
recursive subroutine validateRdii()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   real(dp) :: rsum
   i_l = 0
   j_l = 0
   k_l = 0
   m_l = 0
   rsum = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(UNITHYD_c))
      m_l = 0
      do while (m_l < 12)
         rsum = 0.0_dp
         k_l = 0
         do while (k_l < 3)
            if (UnitHyd(j_l)%tBase(k_l, m_l) == 0_int64) then
               goto 102
            end if
            if (real(UnitHyd(j_l)%tPeak(k_l, m_l), dp) < 0.0_dp) then
               call report_writeErrorMsg(ERR_UNITHYD_TIMES, UnitHyd(j_l)%ID)
            end if
            if (UnitHyd(j_l)%r(k_l, m_l) < 0.0_dp) then
               call report_writeErrorMsg(ERR_UNITHYD_RATIOS, UnitHyd(j_l)%ID)
            else
               rsum = rsum + UnitHyd(j_l)%r(k_l, m_l)
            end if
            102 continue
            k_l = k_l + 1
         end do
         if (rsum > 1.01_dp) then
            call report_writeErrorMsg(ERR_UNITHYD_RATIOS, UnitHyd(j_l)%ID)
         end if
         m_l = m_l + 1
      end do
      j_l = j_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (associated(Node(i_l)%rdiiInflow)) then
         if (Node(i_l)%rdiiInflow%area < 0.0_dp) then
            call report_writeErrorMsg(ERR_RDII_AREA, Node(i_l)%ID)
         end if
      end if
      i_l = i_l + 1
   end do
end subroutine validateRdii

! rdii.c:877
recursive subroutine openRdiiProcessor()
   integer(int32) :: j_l
   integer(int32) :: n_l
   j_l = 0
   n_l = 0
   nullify(UHGroup)
   nullify(RdiiNodeIndex)
   nullify(RdiiNodeFlow)
   TotalRainVol = 0.0_dp
   TotalRdiiVol = 0.0_dp
   if (.not. (allocRdiiMemory() /= 0)) then
      call report_writeErrorMsg(ERR_MEMORY, lit_0)
      return
   end if
   if (.not. (openNewRdiiFile() /= 0)) then
      call report_writeErrorMsg(ERR_RDII_FILE_SCRATCH, lit_0)
      return
   end if
   n_l = 0
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      if (associated(Node(j_l)%rdiiInflow) .and. (.not. (.not. associated(RdiiNodeIndex)))) then
         RdiiNodeIndex(n_l) = j_l
         n_l = n_l + 1
      end if
      j_l = j_l + 1
   end do
end subroutine openRdiiProcessor

! rdii.c:922
recursive function allocRdiiMemory() result(res_)
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: n_l
   res_ = 0
   i_l = 0
   k_l = 0
   n_l = 0
   allocate(UHGroup(0:(int(Nobjects(UNITHYD_c), int64)) - 1))
   if (.not. associated(UHGroup)) then
      res_ = 0
      return
   end if
   i_l = 0
   do while (i_l < Nobjects(UNITHYD_c))
      UHGroup(i_l)%rainInterval = getRainInterval(i_l)
      k_l = 0
      do while (k_l < 3)
         nullify(UHGroup(i_l)%uh(k_l)%pastRain)
         UHGroup(i_l)%uh(k_l)%pastMonth = cnull()
         UHGroup(i_l)%uh(k_l)%maxPeriods = getMaxPeriods(i_l, k_l)
         n_l = UHGroup(i_l)%uh(k_l)%maxPeriods
         if (n_l > 0) then
            allocate(UHGroup(i_l)%uh(k_l)%pastRain(0:int(n_l, int64) - 1))
            UHGroup(i_l)%uh(k_l)%pastRain = 0.0_dp
            if (.not. associated(UHGroup(i_l)%uh(k_l)%pastRain)) then
               res_ = 0
               return
            end if
            UHGroup(i_l)%uh(k_l)%pastMonth = cbuf(int(n_l, int64))
            if (.not. (.not. cisnull(UHGroup(i_l)%uh(k_l)%pastMonth))) then
               res_ = 0
               return
            end if
         end if
         k_l = k_l + 1
      end do
      i_l = i_l + 1
   end do
   allocate(RdiiNodeIndex(0:int(NumRdiiNodes, int64) - 1))
   RdiiNodeIndex = 0
   if (.not. associated(RdiiNodeIndex)) then
      res_ = 0
      return
   end if
   allocate(RdiiNodeFlow(0:int(NumRdiiNodes, int64) - 1))
   RdiiNodeFlow = 0.0_sp
   if (.not. associated(RdiiNodeFlow)) then
      res_ = 0
      return
   end if
   res_ = 1
   return
end function allocRdiiMemory

! rdii.c:970
recursive function getRainInterval(i_l) result(res_)
   integer(int32), value :: i_l
   integer(int32) :: res_
   integer(int32) :: ri
   integer(int32) :: tLimb
   integer(int32) :: k_l
   integer(int32) :: m_l
   res_ = 0
   ri = 0
   tLimb = 0
   k_l = 0
   m_l = 0
   ri = WetStep
   m_l = 0
   do while (m_l < 12)
      k_l = 0
      do while (k_l < 3)
         if (UnitHyd(i_l)%tPeak(k_l, m_l) > 0_int64) then
            tLimb = int(UnitHyd(i_l)%tPeak(k_l, m_l), int32)
            ri = merge(ri, tLimb, (ri) <= (tLimb))
            tLimb = int(UnitHyd(i_l)%tBase(k_l, m_l) - int(tLimb, int64), int32)
            if (tLimb > 0) then
               ri = merge(ri, tLimb, (ri) <= (tLimb))
            end if
         end if
         k_l = k_l + 1
      end do
      m_l = m_l + 1
   end do
   res_ = ri
   return
end function getRainInterval

! rdii.c:1005
recursive function getMaxPeriods(i_l, k_l) result(res_)
   integer(int32), value :: i_l
   integer(int32), value :: k_l
   integer(int32) :: res_
   integer(int32) :: m_l
   integer(int32) :: n_l
   integer(int32) :: nMax_l
   integer(int32) :: rainInterval
   res_ = 0
   m_l = 0
   n_l = 0
   nMax_l = 0
   rainInterval = 0
   rainInterval = UHGroup(i_l)%rainInterval
   nMax_l = 0
   m_l = 0
   do while (m_l < 12)
      n_l = int((UnitHyd(i_l)%tBase(k_l, m_l) / int(rainInterval, int64)) + 1_int64, int32)
      nMax_l = merge(n_l, nMax_l, (n_l) >= (nMax_l))
      m_l = m_l + 1
   end do
   res_ = nMax_l
   return
end function getMaxPeriods

! rdii.c:1034
recursive subroutine initGageData()
   integer(int32) :: i_l
   integer(int32) :: g_l
   i_l = 0
   g_l = 0
   g_l = 0
   do while (g_l < Nobjects(GAGE_c))
      if (Gage(g_l)%tSeries >= 0) then
         call table_tseriesInit(Tseries(Gage(g_l)%tSeries))
      end if
      call gage_initState(g_l)
      g_l = g_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(UNITHYD_c))
      g_l = UnitHyd(i_l)%rainGage
      if (g_l >= 0) then
         if (Gage(g_l)%coGage >= 0) then
            UnitHyd(i_l)%rainGage = Gage(g_l)%coGage
         end if
      end if
      i_l = i_l + 1
   end do
end subroutine initGageData

! rdii.c:1072
recursive subroutine initUnitHydData()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: n_l
   integer(int32) :: month
   i_l = 0
   j_l = 0
   k_l = 0
   n_l = 0
   month = 0
   month = datetime_monthOfYear(StartDateTime) - 1
   i_l = 0
   do while (i_l < Nobjects(UNITHYD_c))
      k_l = 0
      do while (k_l < 3)
         UHGroup(i_l)%uh(k_l)%drySeconds = int((UHGroup(i_l)%uh(k_l)%maxPeriods * UHGroup(i_l)%rainInterval) + 1, int64)
         UHGroup(i_l)%uh(k_l)%period = UHGroup(i_l)%uh(k_l)%maxPeriods + 1
         UHGroup(i_l)%uh(k_l)%hasPastRain = 0
         UHGroup(i_l)%uh(k_l)%iaUsed = UnitHyd(i_l)%iaInit(k_l, month)
         k_l = k_l + 1
      end do
      UHGroup(i_l)%gageDate = StartDateTime
      UHGroup(i_l)%area = 0.0_dp
      UHGroup(i_l)%rdii = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(UNITHYD_c))
      UHGroup(i_l)%isUsed = 0
      i_l = i_l + 1
   end do
   n_l = 0
   do while (n_l < NumRdiiNodes)
      j_l = RdiiNodeIndex(n_l)
      i_l = Node(j_l)%rdiiInflow%unitHyd
      UHGroup(i_l)%isUsed = 1
      UHGroup(i_l)%lastDate = StartDateTime
      UHGroup(i_l)%area = UHGroup(i_l)%area + Node(j_l)%rdiiInflow%area
      n_l = n_l + 1
   end do
end subroutine initUnitHydData

! rdii.c:1128
recursive function openNewRdiiFile() result(res_)
   integer(int32) :: res_
   integer(int32), target :: j_l
   type(CPtr) :: dum1_
   integer(int64) :: dum2_
   res_ = 0
   j_l = 0
   if (Frdii%mode == SCRATCH_FILE) then
      dum1_ = getTempFileName(cview(Frdii%name))
   end if
   Frdii%file => c_fopen(cview(Frdii%name), lit_166)
   if (.not. associated(Frdii%file)) then
      res_ = 0
      return
   end if
   dum2_ = c_fwrite_c(cview(FileStamp), int(1_int64 * (strlen(cview(FileStamp))), int64), Frdii%file)
   dum2_ = c_fwrite_i4(RdiiStep, Frdii%file)
   dum2_ = c_fwrite_i4(NumRdiiNodes, Frdii%file)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      if (associated(Node(j_l)%rdiiInflow)) then
         dum2_ = c_fwrite_i4(j_l, Frdii%file)
      end if
      j_l = j_l + 1
   end do
   res_ = 1
   return
end function openNewRdiiFile

! rdii.c:1163
recursive subroutine getRainfall(currentDate_l)
   real(dp), value :: currentDate_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: g_l
   integer(int32) :: i_l
   integer(int32) :: month
   integer(int32) :: rainInterval
   real(dp) :: rainDepth_l
   real(dp) :: excessDepth
   real(dp) :: gageDate
   j_l = 0
   k_l = 0
   g_l = 0
   i_l = 0
   month = 0
   rainInterval = 0
   rainDepth_l = 0.0_dp
   excessDepth = 0.0_dp
   gageDate = 0.0_dp
   month = datetime_monthOfYear(currentDate_l) - 1
   g_l = 0
   do while (g_l < Nobjects(GAGE_c))
      Gage(g_l)%isCurrent = 0
      g_l = g_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(UNITHYD_c))
      g_l = UnitHyd(j_l)%rainGage
      rainInterval = UHGroup(j_l)%rainInterval
      do while (UHGroup(j_l)%gageDate < currentDate_l)
         gageDate = UHGroup(j_l)%gageDate
         Adjust%rainFactor = Adjust%rain(datetime_monthOfYear(gageDate) - 1)
         if (.not. (Gage(g_l)%isCurrent /= 0)) then
            call gage_setState(g_l, gageDate)
            Gage(g_l)%isCurrent = 1
         end if
         rainDepth_l = (Gage(g_l)%rainfall * real(rainInterval, dp)) / 3600.0_dp
         TotalRainVol = TotalRainVol + ((rainDepth_l / UCF(RAINDEPTH)) * UHGroup(j_l)%area)
         k_l = 0
         do while (k_l < 3)
            excessDepth = applyIA(j_l, k_l, gageDate, real(rainInterval, dp), rainDepth_l)
            call updateDryPeriod(j_l, k_l, excessDepth, rainInterval)
            i_l = UHGroup(j_l)%uh(k_l)%period
            if (i_l >= UHGroup(j_l)%uh(k_l)%maxPeriods) then
               i_l = 0
            end if
            UHGroup(j_l)%uh(k_l)%pastRain(i_l) = excessDepth
            call cset(UHGroup(j_l)%uh(k_l)%pastMonth, i_l, month)
            UHGroup(j_l)%uh(k_l)%period = i_l + 1
            k_l = k_l + 1
         end do
         UHGroup(j_l)%gageDate = datetime_addSeconds(gageDate, real(rainInterval, dp))
      end do
      j_l = j_l + 1
   end do
end subroutine getRainfall

! rdii.c:1231
recursive function applyIA(j_l, k_l, aDate, dt_l, rainDepth_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp), value :: aDate
   real(dp), value :: dt_l
   real(dp), value :: rainDepth_l
   real(dp) :: res_
   integer(int32) :: m_l
   real(dp) :: ia
   real(dp) :: netRainDepth
   real(dp) :: v1_
   res_ = 0.0_dp
   m_l = 0
   ia = 0.0_dp
   netRainDepth = 0.0_dp
   m_l = datetime_monthOfYear(aDate) - 1
   ia = UnitHyd(j_l)%iaMax(k_l, m_l) - UHGroup(j_l)%uh(k_l)%iaUsed
   ia = merge(ia, 0.0_dp, (ia) >= (0.0_dp))
   if (rainDepth_l > 0.0_dp) then
      netRainDepth = rainDepth_l - ia
      netRainDepth = merge(netRainDepth, 0.0_dp, (netRainDepth) >= (0.0_dp))
      ia = rainDepth_l - netRainDepth
      UHGroup(j_l)%uh(k_l)%iaUsed = UHGroup(j_l)%uh(k_l)%iaUsed + ia
   else
      UHGroup(j_l)%uh(k_l)%iaUsed = UHGroup(j_l)%uh(k_l)%iaUsed - ((dt_l / 86400.0_dp) * UnitHyd(j_l)%iaRecov(k_l, m_l))
      if ((UHGroup(j_l)%uh(k_l)%iaUsed) >= (0.0_dp)) then
         v1_ = UHGroup(j_l)%uh(k_l)%iaUsed
      else
         v1_ = 0.0_dp
      end if
      UHGroup(j_l)%uh(k_l)%iaUsed = v1_
      netRainDepth = 0.0_dp
   end if
   res_ = netRainDepth
   return
end function applyIA

! rdii.c:1276
recursive subroutine updateDryPeriod(j_l, k_l, rainDepth_l, rainInterval)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp), value :: rainDepth_l
   integer(int32), value :: rainInterval
   integer(int32) :: i_l
   i_l = 0
   if (rainDepth_l > 0.0_dp) then
      if (UHGroup(j_l)%uh(k_l)%drySeconds >= int(rainInterval * UHGroup(j_l)%uh(k_l)%maxPeriods, int64)) then
         i_l = 0
         do while (i_l < UHGroup(j_l)%uh(k_l)%maxPeriods)
            UHGroup(j_l)%uh(k_l)%pastRain(i_l) = 0.0_dp
            i_l = i_l + 1
         end do
         UHGroup(j_l)%uh(k_l)%period = 0
      end if
      UHGroup(j_l)%uh(k_l)%drySeconds = 0_int64
      UHGroup(j_l)%uh(k_l)%hasPastRain = 1
   else
      UHGroup(j_l)%uh(k_l)%drySeconds = UHGroup(j_l)%uh(k_l)%drySeconds + int(rainInterval, int64)
      if (UHGroup(j_l)%uh(k_l)%drySeconds >= int(rainInterval * UHGroup(j_l)%uh(k_l)%maxPeriods, int64)) then
         UHGroup(j_l)%uh(k_l)%hasPastRain = 0
      else
         UHGroup(j_l)%uh(k_l)%hasPastRain = 1
      end if
   end if
end subroutine updateDryPeriod

! rdii.c:1321
recursive subroutine getUnitHydRdii(currentDate_l)
   real(dp), value :: currentDate_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: rainInterval
   j_l = 0
   k_l = 0
   rainInterval = 0
   j_l = 0
   do while (j_l < Nobjects(UNITHYD_c))
      if (.not. (UHGroup(j_l)%isUsed /= 0)) then
         goto 100
      end if
      if (currentDate_l < UHGroup(j_l)%lastDate) then
         goto 100
      end if
      UHGroup(j_l)%lastDate = UHGroup(j_l)%gageDate
      rainInterval = UHGroup(j_l)%rainInterval
      UHGroup(j_l)%rdii = 0.0_dp
      k_l = 0
      do while (k_l < 3)
         if (UHGroup(j_l)%uh(k_l)%hasPastRain /= 0) then
            UHGroup(j_l)%rdii = UHGroup(j_l)%rdii + getUnitHydConvol(j_l, k_l, rainInterval)
         end if
         k_l = k_l + 1
      end do
      100 continue
      j_l = j_l + 1
   end do
end subroutine getUnitHydRdii

! rdii.c:1358
recursive function getUnitHydConvol(j_l, k_l, rainInterval) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   integer(int32), value :: rainInterval
   real(dp) :: res_
   integer(int32) :: i_l
   integer(int32) :: m_l
   integer(int32) :: p_l
   integer(int32) :: pMax
   real(dp) :: t_l
   real(dp) :: u_l
   real(dp) :: v_l
   real(dp) :: rdii
   type(TUHData), pointer :: uh
   res_ = 0.0_dp
   i_l = 0
   m_l = 0
   p_l = 0
   pMax = 0
   t_l = 0.0_dp
   u_l = 0.0_dp
   v_l = 0.0_dp
   rdii = 0.0_dp
   nullify(uh)
   rdii = 0.0_dp
   uh => UHGroup(j_l)%uh(k_l)
   i_l = uh%period - 1
   if (i_l < 0) then
      i_l = uh%maxPeriods - 1
   end if
   pMax = uh%maxPeriods
   p_l = 1
   do while (p_l < pMax)
      v_l = uh%pastRain(i_l)
      m_l = cget(uh%pastMonth, i_l)
      if (v_l > 0.0_dp) then
         t_l = (real(p_l, dp) - 0.5_dp) * real(rainInterval, dp)
         u_l = getUnitHydOrd(j_l, m_l, k_l, t_l) * UnitHyd(j_l)%r(k_l, m_l)
         rdii = rdii + (u_l * v_l)
      end if
      p_l = p_l + 1
      i_l = i_l - 1
      if (i_l < 0) then
         i_l = uh%maxPeriods - 1
      end if
   end do
   res_ = rdii
   return
end function getUnitHydConvol

! rdii.c:1411
recursive function getUnitHydOrd(h_l, m_l, k_l, t_l) result(res_)
   integer(int32), value :: h_l
   integer(int32), value :: m_l
   integer(int32), value :: k_l
   real(dp), value :: t_l
   real(dp) :: res_
   real(dp) :: qPeak
   real(dp) :: f_l
   real(dp) :: t1
   real(dp) :: t2
   real(dp) :: tBase
   res_ = 0.0_dp
   qPeak = 0.0_dp
   f_l = 0.0_dp
   t1 = 0.0_dp
   t2 = 0.0_dp
   tBase = 0.0_dp
   tBase = real(UnitHyd(h_l)%tBase(k_l, m_l), dp)
   if (t_l >= tBase) then
      res_ = 0.0_dp
      return
   end if
   qPeak = (2.0_dp / tBase) * 3600.0_dp
   t1 = real(UnitHyd(h_l)%tPeak(k_l, m_l), dp)
   t2 = tBase - t1
   if (t_l <= t1) then
      f_l = t_l / t1
   else
      f_l = 1.0_dp - ((t_l - t1) / t2)
   end if
   res_ = (merge(f_l, 0.0_dp, (f_l) >= (0.0_dp))) * qPeak
   return
end function getUnitHydOrd

! rdii.c:1446
recursive function getNodeRdii() result(res_)
   integer(int32) :: res_
   integer(int32) :: hasRdii
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: n_l
   real(dp) :: rdii
   res_ = 0
   hasRdii = 0
   i_l = 0
   j_l = 0
   n_l = 0
   rdii = 0.0_dp
   n_l = 0
   do while (n_l < NumRdiiNodes)
      j_l = RdiiNodeIndex(n_l)
      i_l = Node(j_l)%rdiiInflow%unitHyd
      rdii = (UHGroup(i_l)%rdii * Node(j_l)%rdiiInflow%area) / UCF(RAINFALL)
      if (rdii < ZERO_RDII) then
         rdii = 0.0_dp
      else
         hasRdii = 1
      end if
      RdiiNodeFlow(n_l) = real(rdii, sp)
      if (rdii > 0.0_dp) then
         TotalRdiiVol = TotalRdiiVol + (rdii * real(RdiiStep, dp))
      end if
      n_l = n_l + 1
   end do
   res_ = hasRdii
   return
end function getNodeRdii

! rdii.c:1483
recursive subroutine saveRdiiFlows(currentDate_l)
   real(dp), value, target :: currentDate_l
   integer(int64) :: dum1_
   dum1_ = c_fwrite_r8(currentDate_l, Frdii%file)
   dum1_ = c_fwrite_r4a(RdiiNodeFlow, 0, int(int(NumRdiiNodes, int64), int32), Frdii%file)
end subroutine saveRdiiFlows

! rdii.c:1496
recursive subroutine closeRdiiProcessor()
   integer(int32) :: dum1_
   if (.not. (ErrorCode /= 0)) then
      call report_writeRdiiStats(TotalRainVol, TotalRdiiVol)
   end if
   call freeRdiiMemory()
   if (associated(Frdii%file)) then
      dum1_ = c_fclose(Frdii%file)
   end if
end subroutine closeRdiiProcessor

! rdii.c:1516
recursive subroutine freeRdiiMemory()
   integer(int32) :: i_l
   integer(int32) :: k_l
   i_l = 0
   k_l = 0
   if (associated(UHGroup)) then
      i_l = 0
      do while (i_l < Nobjects(UNITHYD_c))
         k_l = 0
         do while (k_l < 3)
            if (associated(UHGroup(i_l)%uh(k_l)%pastRain)) then
               ! 
               nullify(UHGroup(i_l)%uh(k_l)%pastRain)
            end if
            if (.not. cisnull(UHGroup(i_l)%uh(k_l)%pastMonth)) then
               ! 
               UHGroup(i_l)%uh(k_l)%pastMonth = cnull()
            end if
            k_l = k_l + 1
         end do
         i_l = i_l + 1
      end do
      if (associated(UHGroup)) then
         ! 
         nullify(UHGroup)
      end if
   end if
   if (associated(RdiiNodeIndex)) then
      ! 
      nullify(RdiiNodeIndex)
   end if
   if (associated(RdiiNodeFlow)) then
      ! 
      nullify(RdiiNodeFlow)
   end if
end subroutine freeRdiiMemory

! report.c:93
recursive function report_readOptions(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32) :: j_l
   integer(int32) :: m_l
   integer(int32) :: t_l
   res_ = 0
   k_l = 0
   j_l = 0
   m_l = 0
   t_l = 0
   if (ntoks < 2) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   k_l = findmatch(tok_l(0), ReportWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(0))
      return
   end if
   if ((k_l < 2) .or. (k_l > 4)) then
      m_l = findmatch(tok_l(1), NoYesWords)
      if ((m_l < NO) .or. (m_l > YES)) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
         return
      end if
      select case (k_l)
      case (0)
         RptFlags%disabled = m_l
         res_ = 0
         return
      case (1)
         RptFlags%input = m_l
         res_ = 0
         return
      case (5)
         RptFlags%continuity = m_l
         res_ = 0
         return
      case (6)
         RptFlags%flowStats = m_l
         res_ = 0
         return
      case (7)
         RptFlags%controls = m_l
         res_ = 0
         return
      case (8)
         RptFlags%averages = m_l
         res_ = 0
         return
      case (9)
         res_ = 0
         return
      case default
         res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
         return
      end select
   else
      select case (k_l)
      case (2)
         m_l = SUBCATCH_c
      case (3)
         m_l = NODE_c
      case (4)
         m_l = LINK_c
      end select
   end if
   if (strcomp(tok_l(1), lit_355) /= 0) then
      k_l = NONE_c
   else if (strcomp(tok_l(1), lit_351) /= 0) then
      k_l = ALL_c
   else
      k_l = SOME
      t_l = 1
      do while (t_l < ntoks)
         j_l = project_findObject(m_l, tok_l(t_l))
         if (j_l < 0) then
            res_ = error_setInpError(ERR_NAME, tok_l(t_l))
            return
         end if
         select case (m_l)
         case (1)
            Subcatch(j_l)%rptFlag = 1
         case (2)
            Node(j_l)%rptFlag = 1
         case (3)
            Link(j_l)%rptFlag = 1
         end select
         t_l = t_l + 1
      end do
   end if
   select case (m_l)
   case (1)
      RptFlags%subcatchments = k_l
   case (2)
      RptFlags%nodes = k_l
   case (3)
      RptFlags%links = k_l
   end select
   res_ = 0
   return
end function report_readOptions

