! report.c:183
recursive subroutine report_writeSysTime()
   integer(int8), target :: theTime(0:8)
   real(dp) :: elapsedTime_l
   integer(int64), target :: endTime_l
   theTime = 0_int8
   elapsedTime_l = 0.0_dp
   endTime_l = 0_int64
   if (associated(Frpt%file)) then
      call c_fprintf(Frpt%file, lit_357, c_ctime(SysTime))
      endTime_l = c_time()
      call c_fprintf(Frpt%file, lit_358, c_ctime(endTime_l))
      elapsedTime_l = real(endTime_l - SysTime, dp)
      call c_fprintf(Frpt%file, lit_359)
      if (elapsedTime_l < 1.0_dp) then
         call c_fprintf(Frpt%file, lit_360)
      else
         elapsedTime_l = elapsedTime_l / 86400.0_dp
         if (elapsedTime_l >= 1.0_dp) then
            call c_fprintf(Frpt%file, lit_361, d2i(cfloor(elapsedTime_l)))
            elapsedTime_l = elapsedTime_l - cfloor(elapsedTime_l)
         end if
         call datetime_timeToStr(elapsedTime_l, cview(theTime))
         call c_fprintf(Frpt%file, lit_169, cview(theTime))
      end if
   end if
end subroutine report_writeSysTime

