! report.c:235
recursive subroutine report_writeTitle()
   integer(int32) :: i_l
   integer(int32) :: lineCount
   i_l = 0
   lineCount = 0
   if (ErrorCode /= 0) then
      return
   end if
   i_l = 0
   do while (i_l < 3)
      if (strlen(cview(Title(:, i_l))) > 0_int64) then
         call report_writeLine(cview(Title(:, i_l)))
         lineCount = lineCount + 1
      end if
      i_l = i_l + 1
   end do
end subroutine report_writeTitle

