recursive subroutine report_writeRainStats(i_l, r_l)
   integer(int32), value :: i_l
   type(TRainStats), pointer, intent(in) :: r_l
   integer(int8), target :: date1(0:11)
   integer(int8), target :: date2(0:11)
   call cinit(date1, lit_391)
   call cinit(date2, lit_391)
   if (RptFlags%disabled /= 0) then
      return
   end if
   if (i_l < 0) then
      call report_writeLine(lit_0)
      call report_writeLine(lit_255)
      call report_writeLine(lit_392)
      call report_writeLine(lit_255)
      call c_fprintf(Frpt%file, lit_393)
      call c_fprintf(Frpt%file, lit_394)
      call c_fprintf(Frpt%file, lit_245)
   else
      if (r_l%startDate /= (-693594.0_dp)) then
         call datetime_dateToStr(r_l%startDate, cview(date1))
      end if
      if (r_l%endDate /= (-693594.0_dp)) then
         call datetime_dateToStr(r_l%endDate, cview(date2))
      end if
      call c_fprintf(Frpt%file, lit_395, cview(Gage(i_l)%staID), cview(date1), cview(date2), Gage(i_l)%rainInterval / 60, r_l%periodsRain, r_l%periodsMissing, r_l%periodsMalfunc)
