! report.c:396
recursive subroutine report_writeRdiiStats(rainVol, rdiiVol)
   real(dp), value :: rainVol
   real(dp), value :: rdiiVol
   real(dp) :: ratio
   real(dp) :: ucf1
   real(dp) :: ucf2
   ratio = 0.0_dp
   ucf1 = 0.0_dp
   ucf2 = 0.0_dp
   if (RptFlags%disabled /= 0) then
      return
   end if
   ucf1 = UCF(LENGTH) * UCF(LANDAREA)
   if (UnitSystem == US) then
      ucf2 = 0.64632_dp / 86400.0_dp
   else
      ucf2 = 2.4466_dp / 86400.0_dp
   end if
   call report_writeLine(lit_0)
   call c_fprintf(Frpt%file, lit_396)
   if (UnitSystem == US) then
      call c_fprintf(Frpt%file, lit_397)
   else
      call c_fprintf(Frpt%file, lit_398)
   end if
   call c_fprintf(Frpt%file, lit_399)
   call c_fprintf(Frpt%file, lit_400, rainVol * ucf1, rainVol * ucf2)
   call c_fprintf(Frpt%file, lit_401, rdiiVol * ucf1, rdiiVol * ucf2)
   if (rainVol == 0.0_dp) then
      ratio = 0.0_dp
   else
      ratio = rdiiVol / rainVol
   end if
   call c_fprintf(Frpt%file, lit_402, ratio)
   call report_writeLine(lit_0)
end subroutine report_writeRdiiStats

