   else
      call c_fprintf(Frpt%file, lit_408)
   end if
   call c_fprintf(Frpt%file, lit_409)
   if (totals%initStorage > 0.0_dp) then
      call c_fprintf(Frpt%file, lit_410, (totals%initStorage * UCF(LENGTH)) * UCF(LANDAREA), (totals%initStorage / totalArea_l) * UCF(RAINDEPTH))
   end if
