   if (totals%runon > 0.0_dp) then
      call c_fprintf(Frpt%file, lit_413, (totals%runon * UCF(LENGTH)) * UCF(LANDAREA), (totals%runon / totalArea_l) * UCF(RAINDEPTH))
   end if
   call c_fprintf(Frpt%file, lit_414, (totals%evap * UCF(LENGTH)) * UCF(LANDAREA), (totals%evap / totalArea_l) * UCF(RAINDEPTH))
   call c_fprintf(Frpt%file, lit_415, (totals%infil * UCF(LENGTH)) * UCF(LANDAREA), (totals%infil / totalArea_l) * UCF(RAINDEPTH))
   call c_fprintf(Frpt%file, lit_416, (totals%runoff * UCF(LENGTH)) * UCF(LANDAREA), (totals%runoff / totalArea_l) * UCF(RAINDEPTH))
   if (totals%drains > 0.0_dp) then
      call c_fprintf(Frpt%file, lit_417, (totals%drains * UCF(LENGTH)) * UCF(LANDAREA), (totals%drains / totalArea_l) * UCF(RAINDEPTH))
   end if
   if (Nobjects(SNOWMELT_c) > 0) then
      call c_fprintf(Frpt%file, lit_418, (totals%snowRemoved * UCF(LENGTH)) * UCF(LANDAREA), (totals%snowRemoved / totalArea_l) * UCF(RAINDEPTH))
      call c_fprintf(Frpt%file, lit_419, (totals%finalSnowCover * UCF(LENGTH)) * UCF(LANDAREA), (totals%finalSnowCover / totalArea_l) * UCF(RAINDEPTH))
   end if
   call c_fprintf(Frpt%file, lit_420, (totals%finalStorage * UCF(LENGTH)) * UCF(LANDAREA), (totals%finalStorage / totalArea_l) * UCF(RAINDEPTH))
   call c_fprintf(Frpt%file, lit_421, totals%pctError)
   call report_writeLine(lit_0)
