recursive subroutine report_writeLoadingError(totals)
   type(TLoadingTotals), pointer, intent(in) :: totals(:)
   integer(int32) :: p1
   integer(int32) :: p2
   integer(int32) :: v1_
   integer(int32) :: v2_
   p1 = 0
   p2 = 0
   p1 = 1
   if ((5) <= (Nobjects(POLLUT_c))) then
      v1_ = 5
   else
      v1_ = Nobjects(POLLUT_c)
   end if
   p2 = v1_
   do while (p1 <= Nobjects(POLLUT_c))
      call report_LoadingErrors(p1 - 1, p2 - 1, totals)
      p1 = p2 + 1
      p2 = p1 + 4
      if ((p2) <= (Nobjects(POLLUT_c))) then
         v2_ = p2
      else
         v2_ = Nobjects(POLLUT_c)
      end if
      p2 = v2_
   end do
