   call c_fprintf(Frpt%file, lit_447)
   call c_fprintf(Frpt%file, lit_448, totals%dwInflow * ucf1, totals%dwInflow * ucf2)
   call c_fprintf(Frpt%file, lit_449, totals%wwInflow * ucf1, totals%wwInflow * ucf2)
   call c_fprintf(Frpt%file, lit_450, totals%gwInflow * ucf1, totals%gwInflow * ucf2)
   call c_fprintf(Frpt%file, lit_451, totals%iiInflow * ucf1, totals%iiInflow * ucf2)
   call c_fprintf(Frpt%file, lit_452, totals%exInflow * ucf1, totals%exInflow * ucf2)
   call c_fprintf(Frpt%file, lit_453, totals%outflow * ucf1, totals%outflow * ucf2)
   call c_fprintf(Frpt%file, lit_454, totals%flooding * ucf1, totals%flooding * ucf2)
   call c_fprintf(Frpt%file, lit_414, totals%evapLoss * ucf1, totals%evapLoss * ucf2)
   call c_fprintf(Frpt%file, lit_455, totals%seepLoss * ucf1, totals%seepLoss * ucf2)
