! report.c:923
recursive subroutine report_writeMaxStats(maxMassBalErrs_l, maxCourantCrit_l, nMaxStats)
   type(TMaxStats), pointer, intent(in) :: maxMassBalErrs_l(:)
   type(TMaxStats), pointer, intent(in) :: maxCourantCrit_l(:)
   integer(int32), value :: nMaxStats
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   logical :: b1_
   i_l = 0
   j_l = 0
   k_l = 0
   b1_ = RouteModel /= DW
   if (.not. b1_) then
      b1_ = Nobjects(LINK_c) == 0
   end if
   if (b1_) then
      return
   end if
   if (nMaxStats <= 0) then
      return
   end if
   if (maxMassBalErrs_l(0)%index >= 0) then
      call report_writeLine(lit_0)
      call report_writeLine(lit_470)
      call report_writeLine(lit_471)
      call report_writeLine(lit_470)
      i_l = 0
      do while (i_l < nMaxStats)
         j_l = maxMassBalErrs_l(i_l)%index
         if (j_l < 0) then
            goto 100
         end if
         call c_fprintf(Frpt%file, lit_472, Node(j_l)%ID, maxMassBalErrs_l(i_l)%value)
         100 continue
         i_l = i_l + 1
      end do
      call report_writeLine(lit_0)
   end if
   if (CourantFactor == 0.0_dp) then
      return
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_473)
   call report_writeLine(lit_474)
   call report_writeLine(lit_473)
   k_l = 0
   i_l = 0
   do while (i_l < nMaxStats)
      j_l = maxCourantCrit_l(i_l)%index
      if (j_l < 0) then
         goto 101
      end if
      k_l = k_l + 1
      if (maxCourantCrit_l(i_l)%objType == NODE_c) then
         call c_fprintf(Frpt%file, lit_475, Node(j_l)%ID)
      else
         call c_fprintf(Frpt%file, lit_476, Link(j_l)%ID)
      end if
      call c_fprintf(Frpt%file, lit_477, maxCourantCrit_l(i_l)%value)
      101 continue
      i_l = i_l + 1
   end do
   if (k_l == 0) then
      call c_fprintf(Frpt%file, lit_478)
   end if
   call report_writeLine(lit_0)
end subroutine report_writeMaxStats

