! report.c:1011
recursive subroutine report_writeNonconvergedStats(maxNonconverged_l, nMaxStats)
   type(TMaxStats), pointer, intent(in) :: maxNonconverged_l(:)
   integer(int32), value :: nMaxStats
   integer(int32) :: i_l
   integer(int32) :: j_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   i_l = 0
   j_l = 0
   if ((Nobjects(NODE_c) == 0) .or. (RouteModel /= DW)) then
      return
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_483)
   call report_writeLine(lit_484)
   call report_writeLine(lit_483)
   b1_ = nMaxStats <= 0
   if (.not. b1_) then
      b1_ = maxNonconverged_l(0)%index <= 0
   end if
   b2_ = b1_
   if (.not. b2_) then
      b2_ = maxNonconverged_l(0)%value < 0.00005_dp
   end if
   if (b2_) then
      call c_fprintf(Frpt%file, lit_485)
   else
      i_l = 0
      do while (i_l < nMaxStats)
         j_l = maxNonconverged_l(i_l)%index
         b3_ = j_l < 0
         if (.not. b3_) then
            b3_ = maxNonconverged_l(i_l)%value <= 0.0_dp
         end if
         if (b3_) then
            goto 100
         end if
         call c_fprintf(Frpt%file, lit_472, Node(j_l)%ID, 100.0_dp * maxNonconverged_l(i_l)%value)
         100 continue
         i_l = i_l + 1
      end do
   end if
   call report_writeLine(lit_0)
end subroutine report_writeNonconvergedStats

! report.c:1037
recursive subroutine report_writeTimeStepStats(timeStepStats_l)
   type(TTimeStepStats), pointer, intent(in) :: timeStepStats_l
   real(dp) :: timeStepCount
   real(dp) :: totalRoutingTime
   real(dp) :: fSteadyState
   logical :: b1_
   timeStepCount = real(timeStepStats_l%timeStepCount, dp)
   totalRoutingTime = 0.0_dp
   fSteadyState = 0.0_dp
   b1_ = Nobjects(LINK_c) == 0
   if (.not. b1_) then
      b1_ = real(timeStepStats_l%timeStepCount, dp) == 0.0_dp
   end if
   if (b1_) then
      return
   end if
   totalRoutingTime = timeStepStats_l%steadyStateTime + timeStepStats_l%routingTime
   if (totalRoutingTime > 0.0_dp) then
      fSteadyState = (100.0_dp * timeStepStats_l%steadyStateTime) / totalRoutingTime
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_470)
   call report_writeLine(lit_486)
   call report_writeLine(lit_470)
   call c_fprintf(Frpt%file, lit_487, timeStepStats_l%minTimeStep)
   call c_fprintf(Frpt%file, lit_488, timeStepStats_l%routingTime / timeStepCount)
   call c_fprintf(Frpt%file, lit_489, timeStepStats_l%maxTimeStep)
   call c_fprintf(Frpt%file, lit_490, merge(fSteadyState, 100.0_dp, (fSteadyState) <= (100.0_dp)))
   call c_fprintf(Frpt%file, lit_491, timeStepStats_l%trialsCount / timeStepCount)
   call c_fprintf(Frpt%file, lit_492, (100.0_dp * real(NonConvergeCount, dp)) / timeStepCount)
   if ((RouteModel == DW) .and. (CourantFactor > 0.0_dp)) then
      call report_RouteStepFreq(timeStepStats_l)
   end if
   call report_writeLine(lit_0)
end subroutine report_writeTimeStepStats

! report.c:1085
recursive subroutine report_RouteStepFreq(timeStepStats_l)
   type(TTimeStepStats), pointer, intent(in) :: timeStepStats_l
   real(dp) :: totalSteps
   integer(int32) :: i_l
   totalSteps = 0.0_dp
   i_l = 0
   i_l = 1
   do while (i_l < 6)
      totalSteps = totalSteps + real(timeStepStats_l%timeStepCounts(i_l), dp)
      i_l = i_l + 1
   end do
   if (totalSteps == 0.0_dp) then
      return
   end if
   call c_fprintf(Frpt%file, lit_493)
   i_l = 1
   do while (i_l < 6)
      call c_fprintf(Frpt%file, lit_494, timeStepStats_l%timeStepIntervals(i_l - 1), timeStepStats_l%timeStepIntervals(i_l), (100.0_dp * real(timeStepStats_l%timeStepCounts(i_l), dp)) / totalSteps)
      i_l = i_l + 1
   end do
end subroutine report_RouteStepFreq

! report.c:1113
recursive subroutine report_writeReport()
   if (ErrorCode /= 0) then
      return
   end if
   if (Nperiods == 0_int64) then
      return
   end if
   if ((RptFlags%subcatchments /= NONE_c) .and. (((IgnoreRainfall == 0) .or. (IgnoreSnowmelt == 0)) .or. (IgnoreGwater == 0))) then
      call report_Subcatchments()
   end if
   if ((IgnoreRouting == 1) .and. (IgnoreQuality == 1)) then
      return
   end if
   if (RptFlags%nodes /= NONE_c) then
      call report_Nodes()
   end if
   if (RptFlags%links /= NONE_c) then
      call report_Links()
   end if
end subroutine report_writeReport

! report.c:1135
recursive subroutine report_Subcatchments()
   integer(int32) :: j_l
   integer(int32) :: p_l
   integer(int32) :: k_l
   integer(int32) :: period
   real(dp), target :: days_l
   integer(int8), target :: theDate(0:11)
   integer(int8), target :: theTime(0:8)
   integer(int32) :: hasSnowmelt
   integer(int32) :: hasGwater
   integer(int32) :: hasQuality
   j_l = 0
   p_l = 0
   k_l = 0
   period = 0
   days_l = 0.0_dp
   theDate = 0_int8
   theTime = 0_int8
   hasSnowmelt = merge(1, 0, (Nobjects(SNOWMELT_c) > 0) .and. (.not. (IgnoreSnowmelt /= 0)))
   hasGwater = merge(1, 0, (Nobjects(AQUIFER_c) > 0) .and. (.not. (IgnoreGwater /= 0)))
   hasQuality = merge(1, 0, (Nobjects(POLLUT_c) > 0) .and. (.not. (IgnoreQuality /= 0)))
   if (Nobjects(SUBCATCH_c) == 0) then
      return
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_479)
   call report_writeLine(lit_495)
   call report_writeLine(lit_479)
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      k_l = Subcatch(j_l)%rptFlag - 1
      if (k_l >= 0) then
         call report_SubcatchHeader(Subcatch(j_l)%ID)
         period = 1
         do while (int(period, int64) <= Nperiods)
            call output_readDateTime(int(period, int64), days_l)
            call datetime_dateToStr(days_l, cview(theDate))
            call datetime_timeToStr(days_l, cview(theTime))
            call output_readSubcatchResults(int(period, int64), k_l)
            call c_fprintf(Frpt%file, lit_496, cview(theDate), cview(theTime), real(SubcatchResults(SUBCATCH_RAINFALL), dp), (real(SubcatchResults(SUBCATCH_EVAP), dp) / 24.0_dp) + real(SubcatchResults(SUBCATCH_INFIL), dp), real(SubcatchResults(SUBCATCH_RUNOFF), dp))
            if (hasSnowmelt /= 0) then
               call c_fprintf(Frpt%file, lit_497, real(SubcatchResults(SUBCATCH_SNOWDEPTH), dp))
            end if
            if (hasGwater /= 0) then
               call c_fprintf(Frpt%file, lit_498, real(SubcatchResults(SUBCATCH_GW_ELEV), dp), real(SubcatchResults(SUBCATCH_GW_FLOW), dp))
            end if
            if (hasQuality /= 0) then
               p_l = 0
               do while (p_l < Nobjects(POLLUT_c))
                  call c_fprintf(Frpt%file, lit_499, real(SubcatchResults(SUBCATCH_WASHOFF + p_l), dp))
                  p_l = p_l + 1
               end do
            end if
            period = period + 1
         end do
         call report_writeLine(lit_0)
      end if
      j_l = j_l + 1
   end do
end subroutine report_Subcatchments

! report.c:1192
recursive subroutine report_SubcatchHeader(id)
   type(CPtr), value :: id
   integer(int32) :: i_l
   integer(int32) :: hasSnowmelt
   integer(int32) :: hasGwater
   integer(int32) :: hasQuality
   i_l = 0
   hasSnowmelt = merge(1, 0, (Nobjects(SNOWMELT_c) > 0) .and. (.not. (IgnoreSnowmelt /= 0)))
   hasGwater = merge(1, 0, (Nobjects(AQUIFER_c) > 0) .and. (.not. (IgnoreGwater /= 0)))
   hasQuality = merge(1, 0, (Nobjects(POLLUT_c) > 0) .and. (.not. (IgnoreQuality /= 0)))
   call report_writeLine(lit_0)
   call c_fprintf(Frpt%file, lit_500, id)
   call report_writeLine(lit_501)
   if (hasSnowmelt > 0) then
      call c_fprintf(Frpt%file, lit_502)
   end if
   if (hasGwater /= 0) then
      call c_fprintf(Frpt%file, lit_503)
      call c_fprintf(Frpt%file, lit_503)
   end if
   if (hasQuality /= 0) then
      i_l = 0
      do while (i_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_503)
         i_l = i_l + 1
      end do
   end if
   call c_fprintf(Frpt%file, lit_504)
   if (hasSnowmelt /= 0) then
      call c_fprintf(Frpt%file, lit_505)
   end if
   if (hasGwater /= 0) then
      call c_fprintf(Frpt%file, lit_506)
   end if
   if (hasQuality /= 0) then
      i_l = 0
      do while (i_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_507, Pollut(i_l)%ID)
         i_l = i_l + 1
      end do
   end if
   if (UnitSystem == US) then
      call c_fprintf(Frpt%file, lit_508, FlowUnitWords(FlowUnits))
   else
      call c_fprintf(Frpt%file, lit_509, FlowUnitWords(FlowUnits))
   end if
   if (hasSnowmelt /= 0) then
      if (UnitSystem == US) then
         call c_fprintf(Frpt%file, lit_510)
      else
         call c_fprintf(Frpt%file, lit_511)
      end if
   end if
   if (hasGwater /= 0) then
      if (UnitSystem == US) then
         call c_fprintf(Frpt%file, lit_512, FlowUnitWords(FlowUnits))
      else
         call c_fprintf(Frpt%file, lit_513, FlowUnitWords(FlowUnits))
      end if
   end if
   if (hasQuality /= 0) then
      i_l = 0
      do while (i_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_507, QualUnitsWords(Pollut(i_l)%units))
         i_l = i_l + 1
      end do
   end if
   call report_writeLine(lit_501)
   if (hasSnowmelt /= 0) then
      call c_fprintf(Frpt%file, lit_502)
   end if
   if (hasGwater /= 0) then
      call c_fprintf(Frpt%file, lit_503)
      call c_fprintf(Frpt%file, lit_503)
   end if
   if (hasQuality /= 0) then
      i_l = 0
      do while (i_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_503)
         i_l = i_l + 1
      end do
   end if
end subroutine report_SubcatchHeader

! report.c:1261
recursive subroutine report_Nodes()
   integer(int32) :: j_l
   integer(int32) :: p_l
   integer(int32) :: k_l
   integer(int32) :: period
   real(dp), target :: days_l
   integer(int8), target :: theDate(0:11)
   integer(int8), target :: theTime(0:8)
   j_l = 0
   p_l = 0
   k_l = 0
   period = 0
   days_l = 0.0_dp
   theDate = 0_int8
   theTime = 0_int8
   if (Nobjects(NODE_c) == 0) then
      return
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_514)
   call report_writeLine(lit_515)
   call report_writeLine(lit_514)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      k_l = Node(j_l)%rptFlag - 1
      if (k_l >= 0) then
         call report_NodeHeader(Node(j_l)%ID)
         period = 1
         do while (int(period, int64) <= Nperiods)
