recursive subroutine report_writeErrorMsg(code, s_l)
   integer(int32), value :: code
   type(CPtr), value :: s_l
   integer(int32) :: dum1_
   if (associated(Frpt%file)) then
      call report_writeLine(lit_0)
      call c_fprintf(Frpt%file, error_getMsg(code, cview(Msg)), s_l)
   end if
   ErrorCode = code
   if ((ErrorCode <= ERR_INPUT) .or. (ErrorCode >= ERR_FILE_NAME)) then
      dum1_ = c_snprintf(cview(ErrorMsg), 1024_int64, error_getMsg(ErrorCode, cview(Msg)), s_l)
   end if
end subroutine report_writeErrorMsg

