recursive subroutine report_writeErrorCode()
   if (associated(Frpt%file)) then
      if ((((ErrorCode >= ERR_MEMORY) .and. (ErrorCode <= ERR_TIMESTEP)) .or. ((ErrorCode >= ERR_FILE_NAME) .and. (ErrorCode <= ERR_OUT_FILE))) .or. (ErrorCode == ERR_SYSTEM)) then
         call c_fprintf(Frpt%file, lit_169, error_getMsg(ErrorCode, cview(Msg)))
      end if
   end if
end subroutine report_writeErrorCode

