! roadway.c:85
recursive function roadway_getInflow(j_l, dir, hRoad, h1, h2) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: dir
   real(dp), value :: hRoad
   real(dp), value :: h1
   real(dp), value :: h2
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: roadSurf
   integer(int32) :: useVariableCd
   real(dp) :: length_l
   real(dp) :: roadWidth
   real(dp) :: hWr
   real(dp) :: ht
   real(dp) :: cD
   real(dp) :: q_l
   real(dp) :: dqdh
   res_ = 0.0_dp
   k_l = 0
   roadSurf = 0
   useVariableCd = 0
   length_l = 0.0_dp
   roadWidth = 0.0_dp
   hWr = 0.0_dp
   ht = 0.0_dp
   cD = 0.0_dp
   q_l = 0.0_dp
   dqdh = 0.0_dp
   if (Link(j_l)%type /= WEIR_c) then
      res_ = 0.0_dp
      return
   end if
   k_l = Link(j_l)%subIndex
   roadWidth = Weir(k_l)%roadWidth
   roadSurf = Weir(k_l)%roadSurface
   cD = Weir(k_l)%cDisch1
   if (UnitSystem == SI) then
      cD = cD / 0.552_dp
   end if
   useVariableCd = 0
   if ((roadWidth > 0.0_dp) .and. (roadSurf >= 1)) then
      useVariableCd = 1
   end if
   hWr = h1 - hRoad
   ht = h2 - hRoad
   if (hWr > 0.0001_dp) then
      if (useVariableCd /= 0) then
         cD = getCd(hWr, ht, roadWidth, roadSurf)
      end if
      length_l = Link(j_l)%xsect%wMax
      q_l = (cD * length_l) * (hWr ** 1.5_dp)
      dqdh = (1.5_dp * q_l) / hWr
   end if
   Link(j_l)%dqdh = dqdh
   Link(j_l)%newDepth = merge(h1 - hRoad, 0.0_dp, (h1 - hRoad) >= (0.0_dp))
   Link(j_l)%flowClass = SUBCRITICAL
   if (hRoad > h2) then
      if (dir == 1.0_dp) then
         Link(j_l)%flowClass = DN_CRITICAL
      else
         Link(j_l)%flowClass = UP_CRITICAL
      end if
   end if
   res_ = dir * q_l
   return
end function roadway_getInflow

! roadway.c:146
recursive function getCd(hWr, ht, roadWidth, roadSurf) result(res_)
   real(dp), value :: hWr
   real(dp), value :: ht
   real(dp), value :: roadWidth
   integer(int32), value :: roadSurf
   real(dp) :: res_
   real(dp) :: kT
   real(dp) :: hL
   real(dp) :: htH
   real(dp) :: cR
   res_ = 0.0_dp
   kT = 1.0_dp
   hL = 0.0_dp
   htH = 0.0_dp
   cR = 0.0_dp
   if (hWr <= 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   hL = hWr / roadWidth
   if (hL <= 0.15_dp) then
      if (roadSurf == PAVED) then
         cR = getY(hWr, Cr_Low_Paved, N_Cr_Low_Paved)
      else
         cR = getY(hWr, Cr_Low_Gravel, N_Cr_Low_Gravel)
      end if
   else
      if (roadSurf == PAVED) then
         cR = getY(hL, Cr_High_Paved, N_Cr_High_Paved)
      else
         cR = getY(hL, Cr_High_Gravel, N_Cr_High_Gravel)
      end if
   end if
   if (ht > 0.0_dp) then
      htH = ht / hWr
      if (roadSurf == PAVED) then
         kT = getY(htH, Kt_Paved, N_Kt_Paved)
      else
         kT = getY(htH, Kt_Gravel, N_Kt_Gravel)
      end if
   end if
   res_ = cR * kT
   return
end function getCd

! roadway.c:176
recursive function getY(x_l, table, n_l) result(res_)
   real(dp), value :: x_l
   real(dp), intent(inout), target :: table(0:, 0:)
   integer(int32), value :: n_l
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: x1
   real(dp) :: y1
   real(dp) :: dx
   real(dp) :: dy
   res_ = 0.0_dp
   i_l = 0
   x1 = 0.0_dp
   y1 = 0.0_dp
   dx = 0.0_dp
   dy = 0.0_dp
   if (x_l <= table(0, 0)) then
      res_ = table(1, 0)
      return
   end if
   if (x_l >= table(0, n_l - 1)) then
      res_ = table(1, n_l - 1)
      return
   end if
   i_l = 1
   do while (i_l < n_l)
      if (x_l <= table(0, i_l)) then
         x1 = table(0, i_l - 1)
         dx = table(0, i_l) - x1
         y1 = table(1, i_l - 1)
         dy = table(1, i_l) - y1
         res_ = y1 + (((x_l - x1) * dy) / dx)
         return
      end if
      i_l = i_l + 1
   end do
   res_ = table(1, n_l - 1)
   return
end function getY

! routing.c:93
recursive function routing_open() result(res_)
   integer(int32) :: res_
   res_ = 0
   if (.not. (treatmnt_open() /= 0)) then
      res_ = ErrorCode
      return
   end if
   nullify(SortedLinks)
   if (Nobjects(LINK_c) > 0) then
      allocate(SortedLinks(0:(int(Nobjects(LINK_c), int64)) - 1))
      SortedLinks = 0
      if (.not. associated(SortedLinks)) then
         call report_writeErrorMsg(ERR_MEMORY, lit_0)
         res_ = ErrorCode
         return
      end if
      call toposort_sortLinks(SortedLinks)
      if (ErrorCode /= 0) then
         res_ = ErrorCode
         return
      end if
   end if
   call iface_openRoutingFiles()
   call flowrout_init(RouteModel)
   if (Fhotstart1%mode == NO_FILE) then
      call qualrout_init()
   end if
   if (NumEvents > 0) then
      call sortEvents()
   end if
   NextEvent = 0
   BetweenEvents = merge(1, 0, NumEvents > 0)
   NewRuleTime = 0.0_dp
   res_ = ErrorCode
   return
end function routing_open

! routing.c:134
recursive subroutine routing_close(routingModel)
   integer(int32), value :: routingModel
   call iface_closeRoutingFiles()
   call flowrout_close(routingModel)
   call treatmnt_close()
   if (associated(SortedLinks)) then
      ! 
      nullify(SortedLinks)
   end if
end subroutine routing_close

! routing.c:152
recursive function routing_getRoutingStep(routingModel, fixedStep) result(res_)
   integer(int32), value :: routingModel
   real(dp), value :: fixedStep
   real(dp) :: res_
   real(dp) :: date1
   real(dp) :: date2
   real(dp) :: nextTime
   real(dp) :: routingStep
   real(dp) :: nextRuleTime
   real(dp) :: nextRoutingTime
   logical :: b1_
   res_ = 0.0_dp
   date1 = 0.0_dp
   date2 = 0.0_dp
   nextTime = 0.0_dp
   routingStep = 0.0_dp
   nextRuleTime = 0.0_dp
   nextRoutingTime = 0.0_dp
   if (Nobjects(LINK_c) == 0) then
      res_ = fixedStep
      return
   end if
   if ((NumEvents > 0) .and. (BetweenEvents /= 0)) then
      nextTime = merge(NewRunoffTime, ReportTime, (NewRunoffTime) <= (ReportTime))
      date1 = getDateTime(NewRoutingTime)
      date2 = getDateTime(nextTime)
      b1_ = date2 > date1
      if (b1_) then
         b1_ = date2 < Event(NextEvent)%start
      end if
      if (b1_) then
         routingStep = (nextTime - NewRoutingTime) / 1000.0_dp
      else
         date1 = getDateTime(NewRoutingTime + (1000.0_dp * fixedStep))
         if (date1 < Event(NextEvent)%start) then
            res_ = fixedStep
            return
         end if
      end if
   end if
   if (routingStep == 0.0_dp) then
      routingStep = flowrout_getRoutingStep(routingModel, fixedStep)
   end if
   if (RuleStep > 0) then
      nextRuleTime = NewRuleTime + (1000.0_dp * real(RuleStep, dp))
      nextRoutingTime = NewRoutingTime + (1000.0_dp * routingStep)
      if (nextRoutingTime >= nextRuleTime) then
         routingStep = (nextRuleTime - NewRoutingTime) / 1000.0_dp
      end if
   end if
   res_ = routingStep
   return
end function routing_getRoutingStep

! routing.c:203
recursive subroutine routing_execute(routingModel, routingStep)
   integer(int32), value :: routingModel
   real(dp), value :: routingStep
   integer(int32) :: trialsCount
   integer(int32) :: actionCount
   integer(int32) :: inSteadyState
   real(dp) :: currentDate_l
   real(dp) :: stepFlowError
   trialsCount = 1
   actionCount = 0
   inSteadyState = 1
   currentDate_l = 0.0_dp
   stepFlowError = 0.0_dp
   if (ErrorCode /= 0) then
      return
   end if
   call massbal_updateRoutingTotals(routingStep / 2.0_dp)
   currentDate_l = getDateTime(NewRoutingTime)
   actionCount = evaluateControlRules(currentDate_l, routingStep)
   stepFlowError = massbal_getStepFlowError()
   call massbal_initTimeStepTotals()
   call initSystemInflows()
   BetweenEvents = isBetweenEvents(currentDate_l)
   if (BetweenEvents == 0) then
      call addSystemInflows(currentDate_l, routingStep)
      call inlet_findCapturedFlows(routingStep)
      inSteadyState = isInSteadyState(actionCount, stepFlowError)
      if (inSteadyState == 0) then
         trialsCount = routeFlow(routingModel, routingStep)
      end if
      if ((Nobjects(POLLUT_c) > 0) .and. (.not. (IgnoreQuality /= 0))) then
         call inlet_adjustQualInflows()
         call qualrout_execute(routingStep)
      end if
      call removeSystemOutflows(routingStep)
      call inlet_adjustQualOutflows()
      if (Nobjects(LINK_c) > 0) then
         call stats_updateFlowStats(routingStep, getDateTime(NewRoutingTime))
         call stats_updateTimeStepStats(routingStep, trialsCount, inSteadyState)
      end if
   end if
   call massbal_updateRoutingTotals(routingStep / 2.0_dp)
end subroutine routing_execute

! routing.c:269
recursive function evaluateControlRules(currentDate_l, routingStep) result(res_)
   real(dp), value :: currentDate_l
   real(dp), value :: routingStep
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: actionCount
   integer(int32) :: dum1_
   res_ = 0
   j_l = 0
   actionCount = 0
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      call link_setTargetSetting(j_l)
      j_l = j_l + 1
   end do
   if ((RuleStep == 0) .or. (abs(NewRoutingTime - NewRuleTime) < 1.0_dp)) then
      dum1_ = controls_evaluate(currentDate_l, currentDate_l - StartDateTime, routingStep / 86400.0_dp)
   end if
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      if (Link(j_l)%targetSetting /= Link(j_l)%setting) then
         if ((Link(j_l)%targetSetting * Link(j_l)%setting) == 0.0_dp) then
            Link(j_l)%timeLastSet = currentDate_l
         end if
         call link_setSetting(j_l, routingStep)
         actionCount = actionCount + 1
      end if
      j_l = j_l + 1
   end do
   OldRoutingTime = NewRoutingTime
   NewRoutingTime = NewRoutingTime + (1000.0_dp * routingStep)
   if (abs(NewRoutingTime - (NewRuleTime + (1000.0_dp * real(RuleStep, dp)))) < 1.0_dp) then
      NewRuleTime = NewRuleTime + (1000.0_dp * real(RuleStep, dp))
   end if
   res_ = actionCount
   return
end function evaluateControlRules

! routing.c:312
recursive subroutine initSystemInflows()
   integer(int32) :: j_l
   j_l = 0
   if (Nobjects(POLLUT_c) > 0) then
      j_l = 0
      do while (j_l < Nobjects(NODE_c))
         call node_setOldQualState(j_l)
         j_l = j_l + 1
      end do
      j_l = 0
      do while (j_l < Nobjects(LINK_c))
         call link_setOldQualState(j_l)
         j_l = j_l + 1
      end do
   end if
   call infil_setInfilFactor(-1)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      Node(j_l)%oldLatFlow = Node(j_l)%newLatFlow
      Node(j_l)%newLatFlow = 0.0_dp
      j_l = j_l + 1
   end do
end subroutine initSystemInflows

! routing.c:337
recursive function isBetweenEvents(currentDate_l) result(res_)
   real(dp), value :: currentDate_l
   integer(int32) :: res_
   res_ = 0
   if (NumEvents == 0) then
      res_ = 0
      return
   end if
   if (currentDate_l > Event(NextEvent)%end) then
      NextEvent = NextEvent + 1
      res_ = 1
      return
   else if (currentDate_l >= Event(NextEvent)%start) then
      res_ = 0
      return
   end if
   res_ = 1
   return
end function isBetweenEvents

! routing.c:359
recursive subroutine addSystemInflows(currentDate_l, routingStep)
   real(dp), value :: currentDate_l
   real(dp), value :: routingStep
   integer(int32) :: j_l
   real(dp) :: v1_
   j_l = 0
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      Node(j_l)%losses = node_getLosses(j_l, routingStep)
      j_l = j_l + 1
   end do
   call addExternalInflows(currentDate_l)
   call addDryWeatherInflows(currentDate_l)
   call addWetWeatherInflows(OldRoutingTime)
   call addGroundwaterInflows(OldRoutingTime)
   call addLidDrainInflows(OldRoutingTime)
   call addRdiiInflows(currentDate_l)
   call addIfaceInflows(currentDate_l)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      if ((0.0_dp) >= (Node(j_l)%newLatFlow)) then
         v1_ = 0.0_dp
      else
         v1_ = Node(j_l)%newLatFlow
      end if
      Node(j_l)%qualInflow = v1_
      j_l = j_l + 1
   end do
end subroutine addSystemInflows

! routing.c:383
recursive function isInSteadyState(actionCount, stepFlowError) result(res_)
   integer(int32), value :: actionCount
   real(dp), value :: stepFlowError
   integer(int32) :: res_
   logical :: b1_
   res_ = 0
   if (SkipSteadyState /= 0) then
      b1_ = ((OldRoutingTime == 0.0_dp) .or. (actionCount > 0)) .or. (abs(stepFlowError) > SysFlowTol)
      if (.not. b1_) then
         b1_ = inflowHasChanged() /= 0
      end if
      if (b1_) then
         res_ = 0
         return
      else
         res_ = 1
         return
      end if
   end if
   res_ = 0
   return
end function isInSteadyState

! routing.c:399
recursive function routeFlow(routingModel, routingStep) result(res_)
   integer(int32), value :: routingModel
   real(dp), value :: routingStep
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: stepCount
   res_ = 0
   j_l = 0
   stepCount = 1
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      call link_setOldHydState(j_l)
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      call node_setOldHydState(j_l)
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      call node_initFlows(j_l, routingStep)
      j_l = j_l + 1
   end do
   if (Nobjects(LINK_c) > 0) then
      stepCount = flowrout_execute(SortedLinks, routingModel, routingStep)
   end if
   res_ = stepCount
   return
end function routeFlow

! routing.c:425
recursive subroutine removeSystemOutflows(routingStep)
   real(dp), value :: routingStep
   call removeStorageLosses(routingStep)
   call removeConduitLosses()
   call removeOutflows(routingStep)
end subroutine removeSystemOutflows

! routing.c:435
recursive subroutine addExternalInflows(currentDate_l)
   real(dp), value :: currentDate_l
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: w_l
   type(TExtInflow), pointer :: inflow
   logical :: b1_
   j_l = 0
   p_l = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   nullify(inflow)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      q_l = Node(j_l)%apiExtInflow
      inflow => Node(j_l)%extInflow
      do while (associated(inflow))
         if (inflow%type == FLOW_INFLOW) then
            q_l = q_l + inflow_getExtInflow(inflow, currentDate_l)
            exit
         else
            inflow => inflow%next
         end if
      end do
      if (abs(q_l) < 1.0e-05_dp) then
         q_l = 0.0_dp
      end if
      Node(j_l)%newLatFlow = Node(j_l)%newLatFlow + q_l
      if (q_l >= 0.0_dp) then
         call massbal_addInflowFlow(EXTERNAL_INFLOW, q_l)
      else
         call massbal_addOutflowFlow(-q_l, 0)
         goto 100
      end if
      b1_ = Node(j_l)%type == OUTFALL_c
      if (b1_) then
         b1_ = Node(j_l)%oldNetInflow < 0.0_dp
      end if
      if (b1_) then
         q_l = q_l - Node(j_l)%oldNetInflow
      end if
      inflow => Node(j_l)%extInflow
      do while (associated(inflow))
         if (inflow%type /= FLOW_INFLOW) then
            p_l = inflow%param
            w_l = inflow_getExtInflow(inflow, currentDate_l)
            if (inflow%type == CONCEN_INFLOW) then
               w_l = w_l * q_l
            end if
            Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + w_l
            call massbal_addInflowQual(EXTERNAL_INFLOW, p_l, w_l)
         end if
         inflow => inflow%next
      end do
      100 continue
      j_l = j_l + 1
   end do
end subroutine addExternalInflows

! routing.c:498
recursive subroutine addDryWeatherInflows(currentDate_l)
   real(dp), value :: currentDate_l
   integer(int32) :: j_l
   integer(int32) :: p_l
   integer(int32) :: month
   integer(int32) :: day
   integer(int32) :: hour
   real(dp) :: q_l
   real(dp) :: w_l
   type(TDwfInflow), pointer :: inflow
   j_l = 0
   p_l = 0
   month = 0
   day = 0
   hour = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   nullify(inflow)
   month = datetime_monthOfYear(currentDate_l) - 1
   day = datetime_dayOfWeek(currentDate_l) - 1
   hour = datetime_hourOfDay(currentDate_l)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      inflow => Node(j_l)%dwfInflow
      if (.not. associated(inflow)) then
         goto 100
      end if
      q_l = 0.0_dp
      do while (associated(inflow))
         if (inflow%param < 0) then
            q_l = inflow_getDwfInflow(inflow, month, day, hour)
            exit
         end if
         inflow => inflow%next
      end do
      if (abs(q_l) < 1.0e-05_dp) then
         q_l = 0.0_dp
      end if
      Node(j_l)%newLatFlow = Node(j_l)%newLatFlow + q_l
      call massbal_addInflowFlow(DRY_WEATHER_INFLOW, q_l)
      if (q_l <= 0.0_dp) then
         goto 100
      end if
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         if (Pollut(p_l)%dwfConcen > 0.0_dp) then
            w_l = q_l * Pollut(p_l)%dwfConcen
            Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + w_l
            call massbal_addInflowQual(DRY_WEATHER_INFLOW, p_l, w_l)
         end if
         p_l = p_l + 1
      end do
      inflow => Node(j_l)%dwfInflow
      do while (associated(inflow))
         if (inflow%param >= 0) then
            p_l = inflow%param
            w_l = q_l * inflow_getDwfInflow(inflow, month, day, hour)
            Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + w_l
            call massbal_addInflowQual(DRY_WEATHER_INFLOW, p_l, w_l)
            if (Pollut(p_l)%dwfConcen > 0.0_dp) then
               w_l = q_l * Pollut(p_l)%dwfConcen
               Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) - w_l
               call massbal_addInflowQual(DRY_WEATHER_INFLOW, p_l, -w_l)
            end if
         end if
         inflow => inflow%next
      end do
      100 continue
      j_l = j_l + 1
   end do
end subroutine addDryWeatherInflows

! routing.c:579
recursive subroutine addWetWeatherInflows(routingTime)
   real(dp), value :: routingTime
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: w_l
   real(dp) :: f_l
   i_l = 0
   j_l = 0
   p_l = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   f_l = 0.0_dp
   if (Nobjects(SUBCATCH_c) == 0) then
      return
   end if
   f_l = (routingTime - OldRunoffTime) / (NewRunoffTime - OldRunoffTime)
   if (f_l < 0.0_dp) then
      f_l = 0.0_dp
   end if
   if (f_l > 1.0_dp) then
      f_l = 1.0_dp
   end if
   i_l = 0
   do while (i_l < Nobjects(SUBCATCH_c))
      j_l = Subcatch(i_l)%outNode
      if (j_l >= 0) then
         q_l = subcatch_getWtdOutflow(i_l, f_l)
         Node(j_l)%newLatFlow = Node(j_l)%newLatFlow + q_l
         call massbal_addInflowFlow(WET_WEATHER_INFLOW, q_l)
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            w_l = surfqual_getWtdWashoff(i_l, p_l, f_l)
            Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + w_l
            call massbal_addInflowQual(WET_WEATHER_INFLOW, p_l, w_l)
            p_l = p_l + 1
         end do
      end if
      i_l = i_l + 1
   end do
end subroutine addWetWeatherInflows

! routing.c:621
recursive subroutine addGroundwaterInflows(routingTime)
   real(dp), value :: routingTime
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: w_l
   real(dp) :: f_l
   type(TGroundwater), pointer :: gw_l
   i_l = 0
   j_l = 0
   p_l = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   f_l = 0.0_dp
   nullify(gw_l)
   if (Nobjects(SUBCATCH_c) == 0) then
      return
   end if
   f_l = (routingTime - OldRunoffTime) / (NewRunoffTime - OldRunoffTime)
   if (f_l < 0.0_dp) then
      f_l = 0.0_dp
   end if
   if (f_l > 1.0_dp) then
      f_l = 1.0_dp
   end if
   i_l = 0
   do while (i_l < Nobjects(SUBCATCH_c))
      gw_l => Subcatch(i_l)%groundwater
      if (associated(gw_l)) then
         j_l = gw_l%node
         if (j_l >= 0) then
            q_l = (((1.0_dp - f_l) * (gw_l%oldFlow)) + (f_l * (gw_l%newFlow))) * Subcatch(i_l)%area
            if (abs(q_l) < 1.0e-05_dp) then
               goto 100
            end if
            Node(j_l)%newLatFlow = Node(j_l)%newLatFlow + q_l
            call massbal_addInflowFlow(GROUNDWATER_INFLOW, q_l)
            if (q_l > 0.0_dp) then
               p_l = 0
               do while (p_l < Nobjects(POLLUT_c))
                  w_l = q_l * Pollut(p_l)%gwConcen
                  Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + w_l
                  call massbal_addInflowQual(GROUNDWATER_INFLOW, p_l, w_l)
                  p_l = p_l + 1
               end do
            end if
         end if
      end if
      100 continue
      i_l = i_l + 1
   end do
end subroutine addGroundwaterInflows

