! routing.c:736
recursive subroutine addIfaceInflows(currentDate_l)
   real(dp), value :: currentDate_l
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: w_l
   integer(int32) :: numIfaceNodes_l
   i_l = 0
   j_l = 0
   p_l = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   numIfaceNodes_l = 0
   if (Finflows%mode /= USE_FILE) then
      return
   end if
   numIfaceNodes_l = iface_getNumIfaceNodes(currentDate_l)
   i_l = 0
   do while (i_l < numIfaceNodes_l)
