      end if
      Node(j_l)%newLatFlow = Node(j_l)%newLatFlow + q_l
      call massbal_addInflowFlow(EXTERNAL_INFLOW, q_l)
      if (q_l > 0.0_dp) then
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            w_l = q_l * iface_getIfaceQual(i_l, p_l)
            Node(j_l)%newQual(p_l) = Node(j_l)%newQual(p_l) + w_l
            call massbal_addInflowQual(EXTERNAL_INFLOW, p_l, w_l)
