! routing.c:776
recursive function inflowHasChanged() result(res_)
   integer(int32) :: res_
   integer(int32) :: j_l
   real(dp) :: diff
   real(dp) :: qOld
   real(dp) :: qNew
   logical :: b1_
   res_ = 0
   j_l = 0
   diff = 0.0_dp
   qOld = 0.0_dp
   qNew = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      qOld = Node(j_l)%oldLatFlow
      qNew = Node(j_l)%newLatFlow
      if (abs(qOld) > 1.0e-06_dp) then
         diff = (qNew / qOld) - 1.0_dp
      else if (abs(qNew) > 1.0e-06_dp) then
         diff = 1.0_dp
      else
         diff = 0.0_dp
      end if
      if (abs(diff) > LatFlowTol) then
         res_ = 1
         return
      end if
      b1_ = Node(j_l)%type == OUTFALL_c
      if (.not. b1_) then
         b1_ = Node(j_l)%degree == 0
      end if
      if (b1_) then
         qOld = Node(j_l)%oldFlowInflow
         qNew = Node(j_l)%inflow
         if (abs(qOld) > 1.0e-06_dp) then
            diff = (qNew / qOld) - 1.0_dp
         else if (abs(qNew) > 1.0e-06_dp) then
            diff = 1.0_dp
         else
            diff = 0.0_dp
         end if
         if (abs(diff) > LatFlowTol) then
            res_ = 1
            return
         end if
      end if
      j_l = j_l + 1
   end do
   res_ = 0
   return
end function inflowHasChanged

! routing.c:812
recursive subroutine removeStorageLosses(tStep)
   real(dp), value :: tStep
   integer(int32) :: i_l
   real(dp) :: evapLoss
   real(dp) :: exfilLoss
   i_l = 0
   evapLoss = 0.0_dp
   exfilLoss = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%type == STORAGE_c) then
         evapLoss = evapLoss + Storage(Node(i_l)%subIndex)%evapLoss
         exfilLoss = exfilLoss + Storage(Node(i_l)%subIndex)%exfilLoss
      end if
      i_l = i_l + 1
   end do
   call massbal_addNodeLosses(evapLoss / tStep, exfilLoss / tStep)
end subroutine removeStorageLosses

! routing.c:841
recursive subroutine removeConduitLosses()
   integer(int32) :: i_l
   integer(int32) :: k_l
   real(dp) :: barrels
   real(dp) :: evapLoss
   real(dp) :: seepLoss
   i_l = 0
   k_l = 0
   barrels = 0.0_dp
   evapLoss = 0.0_dp
   seepLoss = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      if (Link(i_l)%type == CONDUIT_c) then
         k_l = Link(i_l)%subIndex
         barrels = real(Conduit(k_l)%barrels, dp)
         evapLoss = evapLoss + (Conduit(k_l)%evapLossRate * barrels)
         seepLoss = seepLoss + (Conduit(k_l)%seepLossRate * barrels)
      end if
      i_l = i_l + 1
   end do
   call massbal_addLinkLosses(evapLoss, seepLoss)
end subroutine removeConduitLosses

! routing.c:872
recursive subroutine removeOutflows(tStep)
   real(dp), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: p_l
   integer(int32) :: k_l
   integer(int32), target :: isFlooded
   real(dp) :: q_l
   real(dp) :: w_l
   real(dp) :: v_l
   logical :: b1_
   i_l = 0
   p_l = 0
   k_l = 0
   isFlooded = 0
   q_l = 0.0_dp
   w_l = 0.0_dp
   v_l = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      b1_ = Node(i_l)%type == OUTFALL_c
      if (b1_) then
         b1_ = Node(i_l)%inflow > 0.0_dp
      end if
      if (b1_) then
         k_l = Node(i_l)%subIndex
         if (Outfall(k_l)%routeTo >= 0) then
            v_l = Node(i_l)%inflow * tStep
            Outfall(k_l)%vRouted = Outfall(k_l)%vRouted + v_l
            p_l = 0
            do while (p_l < Nobjects(POLLUT_c))
               Outfall(k_l)%wRouted(p_l) = Outfall(k_l)%wRouted(p_l) + (Node(i_l)%newQual(p_l) * v_l)
               p_l = p_l + 1
            end do
         end if
      end if
      q_l = node_getSystemOutflow(i_l, isFlooded)
      if (q_l > 0.0_dp) then
         call massbal_addOutflowFlow(q_l, isFlooded)
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            w_l = q_l * Node(i_l)%newQual(p_l)
            call massbal_addOutflowQual(p_l, w_l, isFlooded)
            p_l = p_l + 1
         end do
      else
         call massbal_addInflowFlow(EXTERNAL_INFLOW, -q_l)
      end if
      q_l = Node(i_l)%newLatFlow
      if (q_l < 0.0_dp) then
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            w_l = (-q_l) * Node(i_l)%newQual(p_l)
            call massbal_addOutflowQual(p_l, w_l, 0)
            p_l = p_l + 1
         end do
      end if
      i_l = i_l + 1
   end do
end subroutine removeOutflows

! routing.c:929
recursive subroutine sortEvents()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: gap
   type(TEvent), target :: temp_l
   logical :: b1_
   i_l = 0
   j_l = 0
   gap = 0
   temp_l = zero_TEvent
   gap = NumEvents / 2
   do while (gap >= 1)
      i_l = gap
      do while (i_l < NumEvents)
         temp_l = Event(i_l)
         j_l = i_l - gap
         do
            b1_ = j_l >= 0
            if (b1_) then
               b1_ = Event(j_l)%start > temp_l%start
            end if
            if (.not. b1_) exit
            Event(j_l + gap) = Event(j_l)
            j_l = j_l - gap
         end do
         if (j_l /= (i_l - gap)) then
            Event(j_l + gap) = temp_l
         end if
         i_l = i_l + gap
      end do
      gap = gap / 2
   end do
   i_l = 0
   do while (i_l < (NumEvents - 1))
      if (Event(i_l)%end > Event(i_l + 1)%start) then
         Event(i_l)%end = Event(i_l + 1)%start
      end if
      i_l = i_l + 1
   end do
end subroutine sortEvents

! runoff.c:82
recursive function runoff_open() result(res_)
   integer(int32) :: res_
   res_ = 0
   IsRaining = 0
   HasRunoff = 0
   HasSnow = 0
   runoff_Nsteps = 0
   if (.not. (odesolve_open(4) /= 0)) then
      call report_writeErrorMsg(ERR_ODE_SOLVER, lit_0)
   end if
   nullify(OutflowLoad)
   if (Nobjects(POLLUT_c) > 0) then
      allocate(OutflowLoad(0:(int(Nobjects(POLLUT_c), int64)) - 1))
      OutflowLoad = 0.0_dp
      if (.not. associated(OutflowLoad)) then
         call report_writeErrorMsg(ERR_MEMORY, lit_0)
      end if
   end if
   select case (Frunoff%mode)
   case (2)
      Frunoff%file => c_fopen(cview(Frunoff%name), lit_165)
      if (.not. associated(Frunoff%file)) then
         call report_writeErrorMsg(ERR_RUNOFF_FILE_OPEN, cview(Frunoff%name))
      else
         call runoff_initFile()
      end if
   case (3)
      Frunoff%file => c_fopen(cview(Frunoff%name), lit_166)
      if (.not. associated(Frunoff%file)) then
         call report_writeErrorMsg(ERR_RUNOFF_FILE_OPEN, cview(Frunoff%name))
      else
         call runoff_initFile()
      end if
   end select
   res_ = ErrorCode
   return
end function runoff_open

! runoff.c:124
recursive subroutine runoff_close()
   integer(int32) :: dum1_
   integer(int64) :: dum2_
   call odesolve_close()
   if (associated(OutflowLoad)) then
      ! 
      nullify(OutflowLoad)
   end if
   if (associated(Frunoff%file)) then
      if (Frunoff%mode == SAVE_FILE) then
         dum1_ = c_fseek(Frunoff%file, MaxStepsPos, 0)
         dum2_ = c_fwrite_i4(runoff_Nsteps, Frunoff%file)
      end if
      dum1_ = c_fclose(Frunoff%file)
   end if
   if (associated(Fclimate%file)) then
      dum1_ = c_fclose(Fclimate%file)
   end if
end subroutine runoff_close

! runoff.c:155
recursive subroutine runoff_execute()
   integer(int32) :: j_l
   integer(int32) :: day
   real(dp) :: runoffStep
   real(dp) :: oldRunoffStep
   real(dp) :: runoff
   real(dp) :: currentDate_l
   integer(int32) :: canSweep
   logical :: b1_
   j_l = 0
   day = 0
   runoffStep = 0.0_dp
   oldRunoffStep = 0.0_dp
   runoff = 0.0_dp
   currentDate_l = 0.0_dp
   canSweep = 0
   if (ErrorCode /= 0) then
      return
   end if
   oldRunoffStep = (NewRunoffTime - OldRunoffTime) / 1000.0_dp
   currentDate_l = getDateTime(NewRunoffTime)
   call climate_setState(currentDate_l)
   if (Nobjects(SUBCATCH_c) == 0) then
      OldRunoffTime = NewRunoffTime
      NewRunoffTime = NewRunoffTime + (real(DryStep, dp) * 1000.0_dp)
      NewRunoffTime = merge(NewRunoffTime, TotalDuration, (NewRunoffTime) <= (TotalDuration))
      return
   end if
   IsRaining = 0
   j_l = 0
   do while (j_l < Nobjects(GAGE_c))
      call gage_setState(j_l, currentDate_l)
      if (Gage(j_l)%rainfall > 0.0_dp) then
         IsRaining = 1
      end if
      j_l = j_l + 1
   end do
   if (Frunoff%mode == USE_FILE) then
      call runoff_readFromFile()
      return
   end if
   day = datetime_dayOfYear(currentDate_l)
   canSweep = 0
   if (SweepStart <= SweepEnd) then
      if ((day >= SweepStart) .and. (day <= SweepEnd)) then
         canSweep = 1
      end if
   else if ((day <= SweepEnd) .or. (day >= SweepStart)) then
      canSweep = 1
   end if
   runoffStep = runoff_getTimeStep(currentDate_l)
   if (runoffStep <= 0.0_dp) then
      ErrorCode = ERR_TIMESTEP
      return
   end if
   OldRunoffTime = NewRunoffTime
   NewRunoffTime = NewRunoffTime + (1000.0_dp * runoffStep)
   if (NewRunoffTime > TotalDuration) then
      runoffStep = (TotalDuration - OldRunoffTime) / 1000.0_dp
      NewRunoffTime = TotalDuration
   end if
   j_l = 0
   do while (j_l < Nobjects(GAGE_c))
      call gage_updatePastRain(j_l, d2i(runoffStep))
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      call subcatch_setOldState(j_l)
      j_l = j_l + 1
   end do
   if (oldRunoffStep > 0.0_dp) then
      call runoff_getOutfallRunon(oldRunoffStep)
   end if
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      if (Subcatch(j_l)%area == 0.0_dp) then
         goto 103
      end if
      call subcatch_getRunon(j_l)
      if (.not. (IgnoreSnowmelt /= 0)) then
         call snow_plowSnow(j_l, runoffStep)
      end if
      103 continue
      j_l = j_l + 1
   end do
   HasSnow = 0
   HasRunoff = 0
   HasWetLids = 0
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      if (Subcatch(j_l)%area == 0.0_dp) then
         goto 104
      end if
      runoff = subcatch_getRunoff(j_l, runoffStep)
      if (runoff > 0.0_dp) then
         HasRunoff = 1
      end if
      if (Subcatch(j_l)%newSnowDepth > 0.0_dp) then
         HasSnow = 1
      end if
      if (IgnoreQuality /= 0) then
         goto 104
      end if
      if (runoff < 2.31481e-08_dp) then
         call surfqual_getBuildup(j_l, runoffStep)
      end if
      b1_ = canSweep /= 0
      if (b1_) then
         b1_ = Subcatch(j_l)%rainfall <= 2.31481e-08_dp
      end if
      if (b1_) then
         call surfqual_sweepBuildup(j_l, currentDate_l)
      end if
      call surfqual_getWashoff(j_l, runoff, runoffStep)
      104 continue
      j_l = j_l + 1
   end do
   call stats_updateMaxRunoff()
   runoff_Nsteps = runoff_Nsteps + 1
   if (Frunoff%mode == SAVE_FILE) then
      call runoff_saveToFile(real(runoffStep, sp))
   end if
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      Subcatch(j_l)%runon = 0.0_dp
      j_l = j_l + 1
   end do
end subroutine runoff_execute

! runoff.c:299
recursive function runoff_getTimeStep(currentDate_l) result(res_)
   real(dp), value :: currentDate_l
   real(dp) :: res_
   integer(int32) :: j_l
   integer(int64) :: timeStep
   integer(int64) :: maxStep
   res_ = 0.0_dp
   j_l = 0
   timeStep = 0_int64
   maxStep = int(DryStep, int64)
   timeStep = datetime_timeDiff(climate_getNextEvapDate(), currentDate_l)
   if ((real(timeStep, dp) > 0.0_dp) .and. (timeStep < maxStep)) then
      maxStep = timeStep
   end if
   j_l = 0
   do while (j_l < Nobjects(GAGE_c))
      timeStep = datetime_timeDiff(gage_getNextRainDate(j_l, currentDate_l), currentDate_l)
      if ((timeStep > 0_int64) .and. (timeStep < maxStep)) then
         maxStep = timeStep
      end if
      j_l = j_l + 1
   end do
   if ((((IsRaining /= 0) .or. (HasSnow /= 0)) .or. (HasRunoff /= 0)) .or. (HasWetLids /= 0)) then
      timeStep = int(WetStep, int64)
   else
      timeStep = int(DryStep, int64)
   end if
   if (timeStep > maxStep) then
      timeStep = maxStep
   end if
   res_ = real(timeStep, dp)
   return
end function runoff_getTimeStep

! runoff.c:335
recursive subroutine runoff_initFile()
   integer(int32), target :: nSubcatch
   integer(int32), target :: nPollut
   integer(int32), target :: flowUnits_l
   integer(int8), target :: fileStamp_l(0:12)
   integer(int8), target :: fStamp(0:12)
   integer(int64) :: dum1_
   logical :: b2_
   nSubcatch = 0
   nPollut = 0
   flowUnits_l = 0
   call cinit(fileStamp_l, lit_533)
   call cinit(fStamp, lit_533)
   MaxSteps = 0
   if (Frunoff%mode == SAVE_FILE) then
      nSubcatch = Nobjects(SUBCATCH_c)
      nPollut = Nobjects(POLLUT_c)
      flowUnits_l = FlowUnits
      dum1_ = c_fwrite_c(cview(fileStamp_l), int(1_int64 * (strlen(cview(fileStamp_l))), int64), Frunoff%file)
      dum1_ = c_fwrite_i4(nSubcatch, Frunoff%file)
      dum1_ = c_fwrite_i4(nPollut, Frunoff%file)
      dum1_ = c_fwrite_i4(flowUnits_l, Frunoff%file)
      MaxStepsPos = c_ftell(Frunoff%file)
      dum1_ = c_fwrite_i4(MaxSteps, Frunoff%file)
   end if
   if (Frunoff%mode == USE_FILE) then
      dum1_ = c_fread_c(cview(fStamp), int(1_int64 * (strlen(cview(fileStamp_l))), int64), Frunoff%file)
      if (c_strcmp(cview(fStamp), cview(fileStamp_l)) /= 0) then
         call report_writeErrorMsg(ERR_RUNOFF_FILE_FORMAT, lit_0)
         return
      end if
      nSubcatch = -1
      nPollut = -1
      flowUnits_l = -1
      dum1_ = c_fread_i4(nSubcatch, Frunoff%file)
      dum1_ = c_fread_i4(nPollut, Frunoff%file)
      dum1_ = c_fread_i4(flowUnits_l, Frunoff%file)
      dum1_ = c_fread_i4(MaxSteps, Frunoff%file)
      b2_ = nSubcatch /= Nobjects(SUBCATCH_c)
      if (.not. b2_) then
         b2_ = nPollut /= Nobjects(POLLUT_c)
      end if
      if ((b2_ .or. (flowUnits_l /= FlowUnits)) .or. (MaxSteps <= 0)) then
         call report_writeErrorMsg(ERR_RUNOFF_FILE_FORMAT, lit_0)
      end if
   end if
end subroutine runoff_initFile

! runoff.c:391
recursive subroutine runoff_saveToFile(tStep)
   real(sp), value, target :: tStep
   integer(int32) :: j_l
   integer(int32) :: n_l
   integer(int64) :: dum1_
   j_l = 0
   n_l = (9 + Nobjects(POLLUT_c)) - 1
   dum1_ = c_fwrite_r4(tStep, Frunoff%file)
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      call subcatch_getResults(j_l, 1.0_dp, SubcatchResults)
      dum1_ = c_fwrite_r4a(SubcatchResults, 0, int(int(n_l, int64), int32), Frunoff%file)
      j_l = j_l + 1
   end do
end subroutine runoff_saveToFile

! runoff.c:412
recursive subroutine runoff_readFromFile()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: nResults
   integer(int32) :: kount
   real(sp), target :: tStep
   type(TGroundwater), pointer :: gw_l
   i_l = 0
   j_l = 0
   nResults = 0
   kount = 0
   tStep = 0.0_sp
   nullify(gw_l)
   if (runoff_Nsteps > MaxSteps) then
      call report_writeErrorMsg(ERR_RUNOFF_FILE_END, lit_0)
      return
   end if
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      call subcatch_setOldState(j_l)
      j_l = j_l + 1
   end do
   kount = 0
   kount = kount + int(c_fread_r4(tStep, Frunoff%file), int32)
   nResults = (9 + Nobjects(POLLUT_c)) - 1
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      kount = kount + int(c_fread_r4a(SubcatchResults, 0, int(int(nResults, int64), int32), Frunoff%file), int32)
      Subcatch(j_l)%newSnowDepth = real(SubcatchResults(SUBCATCH_SNOWDEPTH), dp) / UCF(RAINDEPTH)
      Subcatch(j_l)%evapLoss = real(SubcatchResults(SUBCATCH_EVAP), dp) / UCF(RAINFALL)
      Subcatch(j_l)%infilLoss = real(SubcatchResults(SUBCATCH_INFIL), dp) / UCF(RAINFALL)
      Subcatch(j_l)%newRunoff = real(SubcatchResults(SUBCATCH_RUNOFF), dp) / UCF(FLOW)
      gw_l => Subcatch(j_l)%groundwater
      if (associated(gw_l)) then
         gw_l%newFlow = real(SubcatchResults(SUBCATCH_GW_FLOW), dp) / UCF(FLOW)
         gw_l%lowerDepth = Aquifer(gw_l%aquifer)%bottomElev - (real(SubcatchResults(SUBCATCH_GW_ELEV), dp) / UCF(LENGTH))
         gw_l%theta = real(SubcatchResults(SUBCATCH_SOIL_MOIST), dp)
      end if
      i_l = 0
      do while (i_l < Nobjects(POLLUT_c))
         Subcatch(j_l)%newQual(i_l) = real(SubcatchResults(SUBCATCH_WASHOFF + i_l), dp)
         i_l = i_l + 1
      end do
      j_l = j_l + 1
   end do
   if (kount < (1 + (Nobjects(SUBCATCH_c) * nResults))) then
      call report_writeErrorMsg(ERR_RUNOFF_FILE_READ, lit_0)
      return
   end if
   OldRunoffTime = NewRunoffTime
   NewRunoffTime = OldRunoffTime + (real(tStep, dp) * 1000.0_dp)
   NewRunoffTime = merge(NewRunoffTime, TotalDuration, (NewRunoffTime) <= (TotalDuration))
   runoff_Nsteps = runoff_Nsteps + 1
end subroutine runoff_readFromFile

! runoff.c:491
recursive subroutine runoff_getOutfallRunon(tStep)
   real(dp), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   real(dp) :: w_l
   i_l = 0
   k_l = 0
   p_l = 0
   w_l = 0.0_dp
   i_l = 0
   do while (i_l < Nnodes(OUTFALL_c))
      k_l = Outfall(i_l)%routeTo
      if (k_l < 0) then
         goto 100
      end if
      if (Subcatch(k_l)%area == 0.0_dp) then
         goto 100
      end if
      call subcatch_addRunonFlow(k_l, Outfall(i_l)%vRouted / tStep)
      call massbal_updateRunoffTotals(RUNOFF_RUNON, Outfall(i_l)%vRouted)
      Outfall(i_l)%vRouted = 0.0_dp
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         w_l = Outfall(i_l)%wRouted(p_l) * 28.317_dp
         call massbal_updateLoadingTotals(DEPOSITION_LOAD, p_l, w_l * Pollut(p_l)%mcf)
         Subcatch(k_l)%newQual(p_l) = Subcatch(k_l)%newQual(p_l) + (w_l / tStep)
         Outfall(i_l)%wRouted(p_l) = 0.0_dp
         p_l = p_l + 1
      end do
      100 continue
      i_l = i_l + 1
   end do
end subroutine runoff_getOutfallRunon

! shape.c:42
recursive function shape_validate(shape_l, curve_l) result(res_)
   type(TShape), pointer, intent(in) :: shape_l
   type(TTable), pointer, intent(in) :: curve_l
   integer(int32) :: res_
   res_ = 0
   if (.not. (computeShapeTables(shape_l, curve_l) /= 0)) then
      res_ = 0
      return
   end if
   if (.not. (normalizeShapeTables(shape_l) /= 0)) then
      res_ = 0
      return
   end if
   res_ = 1
   return
end function shape_validate

! shape.c:64
recursive function computeShapeTables(shape_l, curve_l) result(res_)
   type(TShape), pointer, intent(in) :: shape_l
   type(TTable), pointer, intent(in) :: curve_l
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: n_l
   real(dp) :: dy
   real(dp) :: y_l
   real(dp), target :: y1
   real(dp), target :: y2
   real(dp) :: w_l
   real(dp), target :: w1
   real(dp), target :: w2
   real(dp) :: yLast
   real(dp) :: wLast
   real(dp), target :: wMax
   res_ = 0
   i_l = 0
   n_l = 0
   dy = 0.0_dp
   y_l = 0.0_dp
   y1 = 0.0_dp
   y2 = 0.0_dp
   w_l = 0.0_dp
   w1 = 0.0_dp
   w2 = 0.0_dp
   yLast = 0.0_dp
   wLast = 0.0_dp
   wMax = 0.0_dp
   if (.not. (table_getFirstEntry(curve_l, y1, w1) /= 0)) then
      res_ = 0
      return
   end if
   if (((y1 < 0.0_dp) .or. (y1 >= 1.0_dp)) .or. (w1 < 0.0_dp)) then
      res_ = 0
      return
   end if
   wMax = w1
   if (y1 /= 0.0_dp) then
      y2 = y1
      w2 = w1
      y1 = 0.0_dp
      w1 = 0.0_dp
   else
      if (.not. (table_getNextEntry(curve_l, y2, w2) /= 0)) then
         res_ = 0
         return
      end if
      if ((y2 < y1) .or. (w2 < 0.0_dp)) then
         res_ = 0
         return
      end if
      if (y2 > 1.0_dp) then
         y2 = 1.0_dp
      end if
      if (w2 > wMax) then
         wMax = w2
      end if
   end if
   shape_l%nTbl = 51
   n_l = shape_l%nTbl - 1
   dy = 1.0_dp / real(n_l, dp)
   shape_l%areaTbl(0) = 0.0_dp
   shape_l%hradTbl(0) = 0.0_dp
   shape_l%widthTbl(0) = w1
   Ptotal = w1
   Atotal = 0.0_dp
   y_l = 0.0_dp
   w_l = w1
   i_l = 1
   do while (i_l <= n_l)
      yLast = y_l
      wLast = w_l
      y_l = y_l + dy
      if (abs(y_l - 1.0_dp) < 1.0e-06_dp) then
         y_l = 1.0_dp
      end if
      if (y_l > y2) then
         if (.not. (getNextInterval(curve_l, y_l, yLast, wLast, y1, y2, w1, w2, wMax) /= 0)) then
            res_ = 0
            return
         end if
         yLast = y1
         wLast = w1
      end if
      w_l = shape_getWidth(y_l, y1, y2, w1, w2)
      Atotal = Atotal + shape_getArea(y_l, w_l, yLast, wLast)
      Ptotal = Ptotal + getPerim(y_l, w_l, yLast, wLast)
      if (y_l == 1.0_dp) then
         Ptotal = Ptotal + w2
      end if
      shape_l%widthTbl(i_l) = w_l
      shape_l%areaTbl(i_l) = Atotal
      if (Ptotal > 0.0_dp) then
         shape_l%hradTbl(i_l) = Atotal / Ptotal
      else
         shape_l%hradTbl(i_l) = 0.0_dp
      end if
      i_l = i_l + 1
   end do
   shape_l%aFull = shape_l%areaTbl(n_l)
   shape_l%rFull = shape_l%hradTbl(n_l)
   shape_l%wMax = wMax
   call getSmax(shape_l)
   res_ = 1
   return
end function computeShapeTables

! shape.c:189
recursive subroutine getSmax(shape_l)
   type(TShape), pointer, intent(in) :: shape_l
   integer(int32) :: i_l
   integer(int32) :: n_l
   real(dp) :: sf_l
   i_l = 0
   n_l = shape_l%nTbl - 1
   sf_l = 0.0_dp
   shape_l%sMax = 0.0_dp
   shape_l%aMax = 0.0_dp
   i_l = 1
   do while (i_l <= n_l)
      sf_l = shape_l%areaTbl(i_l) * (shape_l%hradTbl(i_l) ** (2.0_dp / 3.0_dp))
      if (sf_l > shape_l%sMax) then
         shape_l%sMax = sf_l
         shape_l%aMax = shape_l%areaTbl(i_l)
      end if
      i_l = i_l + 1
   end do
end subroutine getSmax

! shape.c:216
recursive function normalizeShapeTables(shape_l) result(res_)
   type(TShape), pointer, intent(in) :: shape_l
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: n_l
   real(dp) :: aFull_l
   real(dp) :: rFull
   real(dp) :: wMax
   res_ = 0
   i_l = 0
   n_l = shape_l%nTbl - 1
   aFull_l = shape_l%aFull
   rFull = shape_l%rFull
   wMax = shape_l%wMax
   if (((aFull_l == 0.0_dp) .or. (rFull == 0.0_dp)) .or. (wMax == 0.0_dp)) then
      res_ = 0
      return
   end if
   i_l = 0
   do while (i_l <= n_l)
      shape_l%areaTbl(i_l) = shape_l%areaTbl(i_l) / aFull_l
      shape_l%hradTbl(i_l) = shape_l%hradTbl(i_l) / rFull
      shape_l%widthTbl(i_l) = shape_l%widthTbl(i_l) / wMax
      i_l = i_l + 1
   end do
   res_ = 1
   return
end function normalizeShapeTables

! shape.c:246
recursive function getNextInterval(curve_l, y_l, yLast, wLast, y1, y2, w1, w2, wMax) result(res_)
   type(TTable), pointer, intent(in) :: curve_l
   real(dp), value :: y_l
   real(dp), value :: yLast
   real(dp), value :: wLast
   real(dp), intent(inout), target :: y1
   real(dp), intent(inout), target :: y2
   real(dp), intent(inout), target :: w1
   real(dp), intent(inout), target :: w2
   real(dp), intent(inout), target :: wMax
   integer(int32) :: res_
   logical :: b1_
   res_ = 0
   do while (y_l > y2)
      if (y2 > yLast) then
         Atotal = Atotal + shape_getArea(y2, w2, yLast, wLast)
         Ptotal = Ptotal + getPerim(y2, w2, yLast, wLast)
         yLast = y2
         wLast = w2
      end if
      y1 = y2
      w1 = w2
      if (.not. (table_getNextEntry(curve_l, y2, w2) /= 0)) then
         y2 = 1.0_dp
         res_ = 1
         return
      end if
      if (w2 > wMax) then
         wMax = w2
      end if
      b1_ = y2 < y1
      if (.not. b1_) then
         b1_ = w2 < 0.0_dp
      end if
      if (b1_) then
         res_ = 0
         return
      end if
      if (y2 > 1.0_dp) then
         y2 = 1.0_dp
      end if
   end do
   res_ = 1
   return
end function getNextInterval

! shape.c:307
recursive function shape_getWidth(y_l, y1, y2, w1, w2) result(res_)
   real(dp), value :: y_l
   real(dp), value :: y1
   real(dp), value :: y2
   real(dp), value :: w1
   real(dp), value :: w2
   real(dp) :: res_
   res_ = 0.0_dp
   if (y2 == y1) then
      res_ = w2
      return
   end if
   res_ = w1 + (((y_l - y1) / (y2 - y1)) * (w2 - w1))
   return
end function shape_getWidth

! shape.c:328
recursive function shape_getArea(y_l, w_l, y1, w1) result(res_)
   real(dp), value :: y_l
   real(dp), value :: w_l
   real(dp), value :: y1
   real(dp), value :: w1
   real(dp) :: res_
   real(dp) :: wMin
   real(dp) :: wMax
   res_ = 0.0_dp
   wMin = 0.0_dp
   wMax = 0.0_dp
   if (w_l > w1) then
      wMin = w1
      wMax = w_l
   else
      wMin = w_l
      wMax = w1
   end if
   res_ = (wMin + ((wMax - wMin) / 2.0_dp)) * (y_l - y1)
   return
end function shape_getArea

! shape.c:353
recursive function getPerim(y_l, w_l, y1, w1) result(res_)
   real(dp), value :: y_l
   real(dp), value :: w_l
   real(dp), value :: y1
   real(dp), value :: w1
   real(dp) :: res_
   real(dp) :: dy
   real(dp) :: dw_l
   res_ = 0.0_dp
   dy = y_l - y1
   dw_l = abs(w_l - w1) / 2.0_dp
   res_ = 2.0_dp * sqrt((dy * dy) + (dw_l * dw_l))
   return
end function getPerim

! snow.c:68
recursive function snow_readMeltParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   integer(int32) :: n_l
   real(dp), target :: x_l(0:6)
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   m_l = 0
   n_l = 0
   x_l = 0.0_dp
   if (ntoks < 8) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(SNOWMELT_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   if (cisnull(Snowmelt(j_l)%ID)) then
      Snowmelt(j_l)%ID = project_findID(SNOWMELT_c, tok_l(0))
   end if
   k_l = findmatch(tok_l(1), SnowmeltWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
      return
   end if
   n_l = 7
   if (k_l == SNOW_REMOVAL) then
      n_l = 6
   end if
   if (ntoks < (n_l + 2)) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   i_l = 0
   do while (i_l < 7)
      x_l(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < n_l)
      if (.not. (getDouble(tok_l(i_l + 2), x_l(i_l)) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 2))
         return
      end if
      i_l = i_l + 1
   end do
   if (k_l == SNOW_REMOVAL) then
      x_l(6) = -1.0_dp
      if (ntoks >= 9) then
         m_l = project_findObject(SUBCATCH_c, tok_l(8))
         if (m_l < 0) then
            res_ = error_setInpError(ERR_NAME, tok_l(8))
            return
         end if
         x_l(6) = real(m_l, dp)
      end if
   end if
   call setMeltParams(j_l, k_l, x_l)
   res_ = 0
   return
end function snow_readMeltParams

! snow.c:126
recursive function snow_createSnowpack(j_l, k_l) result(res_)
   integer(int32), value :: j_l
