! snow.c:144
recursive subroutine snow_initSnowpack(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   integer(int32) :: k_l
   real(dp) :: f_l
   real(dp) :: snowDepth
   type(TSnowpack), pointer :: snowpack
   i_l = 0
   k_l = 0
   f_l = 0.0_dp
   snowDepth = 0.0_dp
   nullify(snowpack)
   snowpack => Subcatch(j_l)%snowpack
   if (.not. associated(snowpack)) then
      return
   end if
   k_l = Subcatch(j_l)%snowpack%snowmeltIndex
   f_l = Snowmelt(k_l)%snn
   snowpack%fArea(SNOW_PLOWABLE) = f_l * Subcatch(j_l)%fracImperv
   snowpack%fArea(SNOW_IMPERV) = (1.0_dp - f_l) * Subcatch(j_l)%fracImperv
   snowpack%fArea(SNOW_PERV) = 1.0_dp - Subcatch(j_l)%fracImperv
   i_l = SNOW_PLOWABLE
   do while (i_l <= SNOW_PERV)
      if (snowpack%fArea(i_l) > 0.0_dp) then
         snowpack%wsnow(i_l) = Snowmelt(k_l)%wsnow(i_l)
         snowpack%fw(i_l) = Snowmelt(k_l)%fwnow(i_l)
      else
         snowpack%wsnow(i_l) = 0.0_dp
         snowpack%fw(i_l) = 0.0_dp
      end if
      snowpack%coldc(i_l) = 0.0_dp
      snowpack%ati(i_l) = Snowmelt(k_l)%tbase(i_l)
      snowpack%awe(i_l) = 1.0_dp
      snowDepth = snowDepth + (snowpack%wsnow(i_l) * snowpack%fArea(i_l))
      i_l = i_l + 1
   end do
   Subcatch(j_l)%newSnowDepth = snowDepth
end subroutine snow_initSnowpack

! snow.c:193
recursive subroutine snow_initSnowmelt(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   integer(int32) :: k_l
   i_l = 0
   k_l = 0
   i_l = 0
   do while (i_l < 3)
      Snowmelt(j_l)%snn = 0.0_dp
      Snowmelt(j_l)%si(i_l) = 0.0_dp
      Snowmelt(j_l)%dhmin(i_l) = 0.0_dp
      Snowmelt(j_l)%dhmax(i_l) = 0.0_dp
      Snowmelt(j_l)%tbase(i_l) = 0.0_dp
      Snowmelt(j_l)%fwfrac(i_l) = 0.0_dp
      Snowmelt(j_l)%wsnow(i_l) = 0.0_dp
      Snowmelt(j_l)%fwnow(i_l) = 0.0_dp
      Snowmelt(j_l)%weplow = 1.0e6_dp
      k_l = 0
      do while (k_l < 5)
         Snowmelt(j_l)%sfrac(k_l) = 0.0_dp
         k_l = k_l + 1
      end do
      Snowmelt(j_l)%toSubcatch = -1
      i_l = i_l + 1
   end do
end subroutine snow_initSnowmelt

! snow.c:219
recursive subroutine snow_validateSnowmelt(j_l)
   integer(int32), value :: j_l
   integer(int32) :: k_l
   integer(int32) :: err_l
   real(dp) :: sum_l
   logical :: b1_
   logical :: b2_
   k_l = 0
   err_l = 0
   sum_l = 0.0_dp
   k_l = SNOW_PLOWABLE
   do while (k_l <= SNOW_PERV)
      if (Snowmelt(j_l)%dhmin(k_l) > Snowmelt(j_l)%dhmax(k_l)) then
         err_l = 1
      end if
      b1_ = Snowmelt(j_l)%fwfrac(k_l) < 0.0_dp
      if (.not. b1_) then
         b1_ = Snowmelt(j_l)%fwfrac(k_l) > 1.0_dp
      end if
      if (b1_) then
         err_l = 1
      end if
      k_l = k_l + 1
   end do
   b2_ = Snowmelt(j_l)%snn < 0.0_dp
   if (.not. b2_) then
      b2_ = Snowmelt(j_l)%snn > 1.0_dp
   end if
   if (b2_) then
      err_l = 1
   end if
   k_l = 0
   do while (k_l < 5)
      sum_l = sum_l + Snowmelt(j_l)%sfrac(k_l)
      k_l = k_l + 1
   end do
   if (sum_l > 1.01_dp) then
      err_l = 1
   end if
   if (err_l /= 0) then
      call report_writeErrorMsg(ERR_SNOWPACK_PARAMS, Snowmelt(j_l)%ID)
   end if
end subroutine snow_validateSnowmelt

! snow.c:251
recursive subroutine snow_getState(i_l, j_l, x_l)
   integer(int32), value :: i_l
   integer(int32), value :: j_l
   real(dp), pointer, intent(in) :: x_l(:)
   type(TSnowpack), pointer :: snowpack
   snowpack => Subcatch(i_l)%snowpack
   if (.not. associated(snowpack)) then
      return
   end if
   x_l(0) = snowpack%wsnow(j_l)
   x_l(1) = snowpack%fw(j_l)
   x_l(2) = snowpack%coldc(j_l)
   x_l(3) = snowpack%ati(j_l)
   x_l(4) = snowpack%awe(j_l)
end subroutine snow_getState

! snow.c:270
recursive subroutine snow_setState(i_l, j_l, x_l)
   integer(int32), value :: i_l
   integer(int32), value :: j_l
   real(dp), pointer, intent(in) :: x_l(:)
   type(TSnowpack), pointer :: snowpack
   snowpack => Subcatch(i_l)%snowpack
   if (.not. associated(snowpack)) then
      return
   end if
   snowpack%wsnow(j_l) = x_l(0)
   snowpack%fw(j_l) = x_l(1)
   snowpack%coldc(j_l) = x_l(2)
   snowpack%ati(j_l) = x_l(3)
   snowpack%awe(j_l) = x_l(4)
end subroutine snow_setState

! snow.c:290
recursive subroutine setMeltParams(j_l, k_l, x_l)
   integer(int32), value :: j_l
   integer(int32), value :: k_l
   real(dp), pointer, intent(in) :: x_l(:)
   integer(int32) :: i_l
   real(dp) :: v1_
   i_l = 0
   if ((k_l >= SNOW_PLOWABLE) .and. (k_l <= SNOW_PERV)) then
      Snowmelt(j_l)%dhmin(k_l) = (x_l(0) * UCF(TEMPERATURE)) / UCF(RAINFALL)
      Snowmelt(j_l)%dhmax(k_l) = (x_l(1) * UCF(TEMPERATURE)) / UCF(RAINFALL)
      Snowmelt(j_l)%tbase(k_l) = x_l(2)
      if (UnitSystem == SI) then
         Snowmelt(j_l)%tbase(k_l) = ((9.0_dp / 5.0_dp) * Snowmelt(j_l)%tbase(k_l)) + 32.0_dp
      end if
      Snowmelt(j_l)%fwfrac(k_l) = x_l(3)
      Snowmelt(j_l)%wsnow(k_l) = x_l(4) / UCF(RAINDEPTH)
      if ((x_l(5)) <= (x_l(3) * x_l(4))) then
         v1_ = x_l(5)
      else
         v1_ = x_l(3) * x_l(4)
      end if
      x_l(5) = v1_
      Snowmelt(j_l)%fwnow(k_l) = x_l(5) / UCF(RAINDEPTH)
      if (k_l == SNOW_PLOWABLE) then
         Snowmelt(j_l)%snn = x_l(6)
      else
         Snowmelt(j_l)%si(k_l) = x_l(6) / UCF(RAINDEPTH)
      end if
   else if (k_l == SNOW_REMOVAL) then
      Snowmelt(j_l)%weplow = x_l(0) / UCF(RAINDEPTH)
      i_l = 0
      do while (i_l <= 4)
         Snowmelt(j_l)%sfrac(i_l) = x_l(i_l + 1)
         i_l = i_l + 1
      end do
      if (x_l(6) >= 0.0_dp) then
         Snowmelt(j_l)%toSubcatch = d2i(x_l(6) + 0.01_dp)
      else
         Snowmelt(j_l)%toSubcatch = -1
      end if
   end if
end subroutine setMeltParams

! snow.c:341
recursive subroutine snow_setMeltCoeffs(j_l, s_l)
   integer(int32), value :: j_l
   real(dp), value :: s_l
   integer(int32) :: k_l
   k_l = 0
   k_l = SNOW_PLOWABLE
   do while (k_l <= SNOW_PERV)
      Snowmelt(j_l)%dhm(k_l) = 0.5_dp * ((Snowmelt(j_l)%dhmax(k_l) * (1.0_dp + s_l)) + (Snowmelt(j_l)%dhmin(k_l) * (1.0_dp - s_l)))
      k_l = k_l + 1
   end do
end subroutine snow_setMeltCoeffs

! snow.c:360
recursive subroutine snow_plowSnow(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   real(dp), target :: rainfall_l
   real(dp), target :: snowfall
   real(dp) :: exc
   real(dp) :: f_l
   real(dp) :: sfracTotal
   type(TSnowpack), pointer :: snowpack
   real(dp) :: dum1_
   i_l = 0
   k_l = 0
   m_l = 0
   rainfall_l = 0.0_dp
   snowfall = 0.0_dp
   exc = 0.0_dp
   f_l = 0.0_dp
   sfracTotal = 0.0_dp
   nullify(snowpack)
   snowpack => Subcatch(j_l)%snowpack
   if (.not. associated(snowpack)) then
      return
   end if
   dum1_ = gage_getPrecip(Subcatch(j_l)%gage, rainfall_l, snowfall)
   i_l = SNOW_PLOWABLE
   do while (i_l <= SNOW_PERV)
      if (snowpack%fArea(i_l) > 0.0_dp) then
         snowpack%wsnow(i_l) = snowpack%wsnow(i_l) + (snowfall * tStep)
         snowpack%imelt(i_l) = 0.0_dp
      end if
      i_l = i_l + 1
   end do
   if (snowpack%fArea(SNOW_PLOWABLE) > 0.0_dp) then
      k_l = snowpack%snowmeltIndex
      if (snowpack%wsnow(SNOW_PLOWABLE) >= Snowmelt(k_l)%weplow) then
         exc = snowpack%wsnow(SNOW_PLOWABLE)
         f_l = snowpack%fArea(SNOW_PLOWABLE) * (Subcatch(j_l)%area - Subcatch(j_l)%lidArea)
         Snow%removed = Snow%removed + ((Snowmelt(k_l)%sfrac(0) * exc) * f_l)
         sfracTotal = Snowmelt(k_l)%sfrac(0)
         if (snowpack%fArea(SNOW_IMPERV) > 0.0_dp) then
            f_l = snowpack%fArea(SNOW_PLOWABLE) / snowpack%fArea(SNOW_IMPERV)
            snowpack%wsnow(SNOW_IMPERV) = snowpack%wsnow(SNOW_IMPERV) + ((Snowmelt(k_l)%sfrac(1) * exc) * f_l)
            sfracTotal = sfracTotal + Snowmelt(k_l)%sfrac(1)
         end if
         if (snowpack%fArea(SNOW_PERV) > 0.0_dp) then
            f_l = snowpack%fArea(SNOW_PLOWABLE) / snowpack%fArea(SNOW_PERV)
            snowpack%wsnow(SNOW_PERV) = snowpack%wsnow(SNOW_PERV) + ((Snowmelt(k_l)%sfrac(2) * exc) * f_l)
            sfracTotal = sfracTotal + Snowmelt(k_l)%sfrac(2)
         end if
         snowpack%imelt(SNOW_PLOWABLE) = (Snowmelt(k_l)%sfrac(3) * exc) / tStep
         sfracTotal = sfracTotal + Snowmelt(k_l)%sfrac(3)
         if (Snowmelt(k_l)%sfrac(4) > 0.0_dp) then
            m_l = Snowmelt(k_l)%toSubcatch
            if (associated(Subcatch(m_l)%snowpack)) then
               f_l = Subcatch(m_l)%snowpack%fArea(SNOW_PERV)
            else
               f_l = 0.0_dp
            end if
            if (f_l > 0.0_dp) then
               f_l = snowpack%fArea(SNOW_PLOWABLE) / f_l
               Subcatch(m_l)%snowpack%wsnow(SNOW_PERV) = Subcatch(m_l)%snowpack%wsnow(SNOW_PERV) + ((Snowmelt(k_l)%sfrac(4) * exc) * f_l)
               sfracTotal = sfracTotal + Snowmelt(k_l)%sfrac(4)
            end if
         end if
         sfracTotal = merge(sfracTotal, 1.0_dp, (sfracTotal) <= (1.0_dp))
         snowpack%wsnow(SNOW_PLOWABLE) = exc * (1.0_dp - sfracTotal)
      end if
   end if
end subroutine snow_plowSnow

! snow.c:458
recursive function snow_getSnowMelt(j_l, rainfall_l, snowfall, tStep, netPrecip) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: rainfall_l
   real(dp), value :: snowfall
   real(dp), value :: tStep
   real(dp), pointer, intent(in) :: netPrecip(:)
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: rmelt
   real(dp) :: smelt
   real(dp) :: asc
   real(dp) :: snowDepth
   real(dp) :: impervPrecip
   type(TSnowpack), pointer :: snowpack
   res_ = 0.0_dp
   i_l = 0
   rmelt = 0.0_dp
   smelt = 0.0_dp
   asc = 0.0_dp
   snowDepth = 0.0_dp
   impervPrecip = 0.0_dp
   nullify(snowpack)
   snowpack => Subcatch(j_l)%snowpack
   rmelt = getRainmelt(rainfall_l)
   i_l = SNOW_PLOWABLE
   do while (i_l <= SNOW_PERV)
      if (snowpack%wsnow(i_l) <= (0.001_dp / 12.0_dp)) then
         asc = 0.0_dp
         smelt = 0.0_dp
         snowpack%imelt(i_l) = snowpack%imelt(i_l) + ((snowpack%wsnow(i_l) + snowpack%fw(i_l)) / tStep)
         snowpack%wsnow(i_l) = 0.0_dp
         snowpack%fw(i_l) = 0.0_dp
         snowpack%coldc(i_l) = 0.0_dp
      else
         asc = getArealDepletion(snowpack, i_l, snowfall, tStep)
         smelt = meltSnowpack(snowpack, i_l, rmelt, asc, snowfall, tStep)
         smelt = routeSnowmelt(snowpack, i_l, smelt, asc, rainfall_l, tStep)
      end if
      netPrecip(i_l) = (smelt + snowpack%imelt(i_l)) + (rainfall_l * (1.0_dp - asc))
      snowDepth = snowDepth + (snowpack%wsnow(i_l) * snowpack%fArea(i_l))
      i_l = i_l + 1
   end do
   if (Subcatch(j_l)%fracImperv > 0.0_dp) then
      impervPrecip = ((netPrecip(SNOW_PLOWABLE) * snowpack%fArea(SNOW_PLOWABLE)) + (netPrecip(SNOW_IMPERV) * snowpack%fArea(SNOW_IMPERV))) / Subcatch(j_l)%fracImperv
      netPrecip(IMPERV0) = impervPrecip
      netPrecip(IMPERV1) = impervPrecip
   end if
   res_ = snowDepth
   return
end function snow_getSnowMelt

! snow.c:532
recursive function snow_getSnowCover(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: snowCover
   type(TSnowpack), pointer :: snowpack
   res_ = 0.0_dp
   i_l = 0
   snowCover = 0.0_dp
   nullify(snowpack)
   snowpack => Subcatch(j_l)%snowpack
   if (.not. associated(snowpack)) then
      res_ = 0.0_dp
      return
   end if
   i_l = SNOW_PLOWABLE
   do while (i_l <= SNOW_PERV)
      snowCover = snowCover + ((snowpack%wsnow(i_l) + snowpack%fw(i_l)) * snowpack%fArea(i_l))
      i_l = i_l + 1
   end do
   res_ = snowCover * (Subcatch(j_l)%area - Subcatch(j_l)%lidArea)
   return
end function snow_getSnowCover

! snow.c:555
recursive function getArealDepletion(snowpack, i_l, snowfall, tStep) result(res_)
   type(TSnowpack), pointer, intent(in) :: snowpack
   integer(int32), value :: i_l
   real(dp), value :: snowfall
   real(dp), value :: tStep
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: asc
   real(dp) :: si_l
   real(dp) :: awesi
   real(dp) :: awe
   real(dp) :: sba
   real(dp) :: sbws
   logical :: b1_
   res_ = 0.0_dp
   k_l = 0
   asc = 0.0_dp
   si_l = 0.0_dp
   awesi = 0.0_dp
   awe = 0.0_dp
   sba = 0.0_dp
   sbws = 0.0_dp
   if (i_l == SNOW_PLOWABLE) then
      res_ = 1.0_dp
      return
   end if
   k_l = snowpack%snowmeltIndex
   si_l = Snowmelt(k_l)%si(i_l)
   b1_ = si_l == 0.0_dp
   if (.not. b1_) then
      b1_ = snowpack%wsnow(i_l) >= si_l
   end if
   if (b1_) then
      snowpack%awe(i_l) = 1.0_dp
      res_ = 1.0_dp
      return
   end if
   if (snowpack%wsnow(i_l) == 0.0_dp) then
      snowpack%awe(i_l) = 1.0_dp
      res_ = 0.0_dp
      return
   end if
   if (snowfall > 0.0_dp) then
      awe = (snowpack%wsnow(i_l) - (snowfall * tStep)) / si_l
      awe = merge(awe, 0.0_dp, (awe) >= (0.0_dp))
      sba = getArealSnowCover(i_l, awe)
      sbws = awe + (((0.75_dp * snowfall) * tStep) / si_l)
      sbws = merge(sbws, 1.0_dp, (sbws) <= (1.0_dp))
      snowpack%awe(i_l) = awe
      snowpack%sba(i_l) = sba
      snowpack%sbws(i_l) = sbws
      res_ = 1.0_dp
      return
   else
      awe = snowpack%awe(i_l)
      sba = snowpack%sba(i_l)
      sbws = snowpack%sbws(i_l)
      awesi = snowpack%wsnow(i_l) / si_l
      if (awesi < snowpack%awe(i_l)) then
         snowpack%awe(i_l) = 1.0_dp
         asc = getArealSnowCover(i_l, awesi)
      else if (awesi >= snowpack%sbws(i_l)) then
         asc = 1.0_dp
      else
         asc = sba + (((1.0_dp - sba) / (sbws - awe)) * (awesi - awe))
      end if
      res_ = asc
      return
   end if
end function getArealDepletion

! snow.c:636
recursive function getArealSnowCover(i_l, awesi) result(res_)
   integer(int32), value :: i_l
   real(dp), value :: awesi
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: m_l
   real(dp) :: asc1
   real(dp) :: asc2
   res_ = 0.0_dp
   k_l = 0
   m_l = 0
   asc1 = 0.0_dp
   asc2 = 0.0_dp
   if (i_l == SNOW_IMPERV) then
      k_l = 0
   else if (i_l == SNOW_PERV) then
      k_l = 1
   else
      res_ = 1.0_dp
      return
   end if
   if (awesi <= 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   if (awesi >= 0.9999_dp) then
      res_ = 1.0_dp
      return
   end if
   m_l = d2i((awesi * 10.0_dp) + 0.00001_dp)
   asc1 = Snow%adc(m_l, k_l)
   if (m_l >= 9) then
      asc2 = 1.0_dp
   else
      asc2 = Snow%adc(m_l + 1, k_l)
   end if
   res_ = asc1 + (((asc2 - asc1) / 0.1_dp) * (awesi - (0.1_dp * real(real(m_l, sp), dp))))
   return
end function getArealSnowCover

! snow.c:674
recursive function meltSnowpack(snowpack, i_l, rmelt, asc, snowfall, tStep) result(res_)
   type(TSnowpack), pointer, intent(in) :: snowpack
   integer(int32), value :: i_l
   real(dp), value :: rmelt
   real(dp), value :: asc
   real(dp), value :: snowfall
   real(dp), value :: tStep
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: smelt
   real(dp) :: ccFactor
   res_ = 0.0_dp
   k_l = 0
   smelt = 0.0_dp
   ccFactor = 0.0_dp
   k_l = snowpack%snowmeltIndex
   if (rmelt > 0.0_dp) then
      smelt = rmelt
   else if (Temp%ta >= Snowmelt(k_l)%tbase(i_l)) then
      smelt = Snowmelt(k_l)%dhm(i_l) * (Temp%ta - Snowmelt(k_l)%tbase(i_l))
   else
      call updateColdContent(snowpack, i_l, asc, snowfall, tStep)
      res_ = 0.0_dp
      return
   end if
   smelt = smelt * asc
   ccFactor = (tStep * Snow%rnm) * asc
   smelt = reduceColdContent(snowpack, i_l, smelt, ccFactor)
   snowpack%ati(i_l) = Snowmelt(k_l)%tbase(i_l)
   res_ = smelt
   return
end function meltSnowpack

! snow.c:720
recursive function getRainmelt(rainfall_l) result(res_)
   real(dp), value :: rainfall_l
   real(dp) :: res_
   real(dp) :: uadj
   real(dp) :: t1
   real(dp) :: t2
   real(dp) :: t3
   real(dp) :: smelt
   res_ = 0.0_dp
   uadj = 0.0_dp
   t1 = 0.0_dp
   t2 = 0.0_dp
   t3 = 0.0_dp
   smelt = 0.0_dp
   rainfall_l = rainfall_l * 43200.0_dp
   if (rainfall_l > 0.02_dp) then
      uadj = 0.006_dp * Wind%ws
      t1 = Temp%ta - 32.0_dp
      t2 = (7.5_dp * Temp%gamma) * uadj
      t3 = (8.5_dp * uadj) * (Temp%ea - 0.18_dp)
      smelt = (t1 * ((0.001167_dp + t2) + (0.007_dp * rainfall_l))) + t3
      res_ = smelt / 43200.0_dp
      return
   else
      res_ = 0.0_dp
      return
   end if
end function getRainmelt

! snow.c:746
recursive subroutine updateColdContent(snowpack, i_l, asc, snowfall, tStep)
   type(TSnowpack), pointer, intent(in) :: snowpack
   integer(int32), value :: i_l
   real(dp), value :: asc
   real(dp), value :: snowfall
   real(dp), value :: tStep
   integer(int32) :: k_l
   real(dp) :: ati
   real(dp) :: cc
   real(dp) :: ccMax
   real(dp) :: tipm
   real(dp) :: v1_
   k_l = 0
   ati = 0.0_dp
   cc = 0.0_dp
   ccMax = 0.0_dp
   tipm = 0.0_dp
   ati = snowpack%ati(i_l)
   cc = snowpack%coldc(i_l)
   if ((snowfall * 43200.0_dp) > 0.02_dp) then
      ati = Temp%ta
   else
      tipm = 1.0_dp - ((1.0_dp - Snow%tipm) ** (tStep / (6.0_dp * 3600.0_dp)))
      ati = ati + (tipm * (Temp%ta - ati))
   end if
   k_l = snowpack%snowmeltIndex
   if ((ati) <= (Snowmelt(k_l)%tbase(i_l))) then
      v1_ = ati
   else
      v1_ = Snowmelt(k_l)%tbase(i_l)
   end if
   ati = v1_
   cc = cc + ((((Snow%rnm * Snowmelt(k_l)%dhm(i_l)) * (ati - Temp%ta)) * tStep) * asc)
   cc = merge(cc, 0.0_dp, (cc) >= (0.0_dp))
   ccMax = ((snowpack%wsnow(i_l) * 0.007_dp) / 12.0_dp) * (Snowmelt(k_l)%tbase(i_l) - ati)
   cc = merge(cc, ccMax, (cc) <= (ccMax))
   snowpack%coldc(i_l) = cc
   snowpack%ati(i_l) = ati
end subroutine updateColdContent

! snow.c:799
recursive function reduceColdContent(snowpack, i_l, smelt, ccFactor) result(res_)
   type(TSnowpack), pointer, intent(in) :: snowpack
   integer(int32), value :: i_l
   real(dp), value :: smelt
   real(dp), value :: ccFactor
   real(dp) :: res_
   real(dp) :: cc
   res_ = 0.0_dp
   cc = 0.0_dp
   cc = snowpack%coldc(i_l)
   if ((smelt * ccFactor) > cc) then
      smelt = smelt - (cc / ccFactor)
      cc = 0.0_dp
   else
      cc = cc - (smelt * ccFactor)
      smelt = 0.0_dp
   end if
   snowpack%coldc(i_l) = cc
   res_ = smelt
   return
end function reduceColdContent

! snow.c:828
recursive function routeSnowmelt(snowpack, i_l, smelt, asc, rainfall_l, tStep) result(res_)
   type(TSnowpack), pointer, intent(in) :: snowpack
   integer(int32), value :: i_l
   real(dp), value :: smelt
   real(dp), value :: asc
   real(dp), value :: rainfall_l
   real(dp), value :: tStep
   real(dp) :: res_
   integer(int32) :: k_l
   real(dp) :: vmelt
   real(dp) :: v1_
   res_ = 0.0_dp
   k_l = 0
   vmelt = 0.0_dp
   k_l = snowpack%snowmeltIndex
   vmelt = smelt * tStep
   if ((vmelt) <= (snowpack%wsnow(i_l))) then
      v1_ = vmelt
   else
      v1_ = snowpack%wsnow(i_l)
   end if
   vmelt = v1_
   snowpack%wsnow(i_l) = snowpack%wsnow(i_l) - vmelt
   snowpack%fw(i_l) = snowpack%fw(i_l) + (vmelt + ((rainfall_l * tStep) * asc))
   vmelt = snowpack%fw(i_l) - (Snowmelt(k_l)%fwfrac(i_l) * snowpack%wsnow(i_l))
   vmelt = merge(vmelt, 0.0_dp, (vmelt) >= (0.0_dp))
   snowpack%fw(i_l) = snowpack%fw(i_l) - vmelt
   res_ = vmelt / tStep
   return
end function routeSnowmelt

