! stats.c:342
recursive subroutine stats_report()
   if ((Nobjects(LINK_c) > 0) .and. (RouteModel /= NO_ROUTING)) then
      call stats_findMaxStats()
      if ((.not. (RptFlags%disabled /= 0)) .and. (RptFlags%flowStats /= 0)) then
         call report_writeMaxStats(MaxMassBalErrs, MaxCourantCrit, 5)
         call report_writeMaxFlowTurns(MaxFlowTurns, 5)
         call report_writeNonconvergedStats(MaxNonConverged, 5)
         call report_writeTimeStepStats(TimeStepStats)
      end if
   end if
   if (.not. (RptFlags%disabled /= 0)) then
      call statsrpt_writeReport()
   end if
end subroutine stats_report

! stats.c:369
recursive subroutine stats_updateSubcatchStats(j_l, rainVol, runonVol, evapVol, infilVol, impervVol, pervVol, runoffVol, runoff)
   integer(int32), value :: j_l
   real(dp), value :: rainVol
   real(dp), value :: runonVol
   real(dp), value :: evapVol
   real(dp), value :: infilVol
   real(dp), value :: impervVol
   real(dp), value :: pervVol
   real(dp), value :: runoffVol
   real(dp), value :: runoff
   real(dp) :: v1_
   SubcatchStats(j_l)%precip = SubcatchStats(j_l)%precip + rainVol
   SubcatchStats(j_l)%runon = SubcatchStats(j_l)%runon + runonVol
   SubcatchStats(j_l)%evap = SubcatchStats(j_l)%evap + evapVol
   SubcatchStats(j_l)%infil = SubcatchStats(j_l)%infil + infilVol
   SubcatchStats(j_l)%runoff = SubcatchStats(j_l)%runoff + runoffVol
   if ((SubcatchStats(j_l)%maxFlow) >= (runoff)) then
      v1_ = SubcatchStats(j_l)%maxFlow
   else
      v1_ = runoff
   end if
   SubcatchStats(j_l)%maxFlow = v1_
   SubcatchStats(j_l)%impervRunoff = SubcatchStats(j_l)%impervRunoff + impervVol
   SubcatchStats(j_l)%pervRunoff = SubcatchStats(j_l)%pervRunoff + pervVol
end subroutine stats_updateSubcatchStats

! stats.c:399
recursive subroutine stats_updateGwaterStats(j_l, infil_l, evap_l, latFlow, deepFlow, theta_l, waterTable, tStep)
   integer(int32), value :: j_l
   real(dp), value :: infil_l
   real(dp), value :: evap_l
   real(dp), value :: latFlow
   real(dp), value :: deepFlow
   real(dp), value :: theta_l
   real(dp), value :: waterTable
   real(dp), value :: tStep
   Subcatch(j_l)%groundwater%stats%infil = Subcatch(j_l)%groundwater%stats%infil + (infil_l * tStep)
   Subcatch(j_l)%groundwater%stats%evap = Subcatch(j_l)%groundwater%stats%evap + (evap_l * tStep)
   Subcatch(j_l)%groundwater%stats%latFlow = Subcatch(j_l)%groundwater%stats%latFlow + (latFlow * tStep)
   Subcatch(j_l)%groundwater%stats%deepFlow = Subcatch(j_l)%groundwater%stats%deepFlow + (deepFlow * tStep)
   Subcatch(j_l)%groundwater%stats%avgUpperMoist = Subcatch(j_l)%groundwater%stats%avgUpperMoist + (theta_l * tStep)
   Subcatch(j_l)%groundwater%stats%avgWaterTable = Subcatch(j_l)%groundwater%stats%avgWaterTable + (waterTable * tStep)
   Subcatch(j_l)%groundwater%stats%finalUpperMoist = theta_l
   Subcatch(j_l)%groundwater%stats%finalWaterTable = waterTable
   if (abs(latFlow) > abs(Subcatch(j_l)%groundwater%stats%maxFlow)) then
      Subcatch(j_l)%groundwater%stats%maxFlow = latFlow
   end if
end subroutine stats_updateGwaterStats

! stats.c:419
recursive subroutine stats_updateMaxRunoff()
   integer(int32) :: j_l
   real(dp) :: sysRunoff
   j_l = 0
   sysRunoff = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      sysRunoff = sysRunoff + Subcatch(j_l)%newRunoff
      j_l = j_l + 1
   end do
   MaxRunoffFlow = merge(MaxRunoffFlow, sysRunoff, (MaxRunoffFlow) >= (sysRunoff))
end subroutine stats_updateMaxRunoff

! stats.c:435
recursive subroutine stats_updateMaxNodeDepth(j_l, depth)
   integer(int32), value :: j_l
   real(dp), value :: depth
   real(dp) :: v1_
   if (.not. (.not. associated(NodeStats))) then
      if ((NodeStats(j_l)%maxRptDepth) >= (depth)) then
         v1_ = NodeStats(j_l)%maxRptDepth
      else
         v1_ = depth
      end if
      NodeStats(j_l)%maxRptDepth = v1_
   end if
