! stats.c:449
recursive subroutine stats_updateFlowStats(tStep, aDate)
   real(dp), value :: tStep
   real(dp), value :: aDate
   integer(int32) :: j_l
   j_l = 0
   if (aDate < ReportStart) then
      return
   end if
   SysOutfallFlow = 0.0_dp
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      call stats_updateNodeStats(j_l, tStep, aDate)
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      call stats_updateLinkStats(j_l, tStep, aDate)
      j_l = j_l + 1
   end do
   ReportStepCount = ReportStepCount + 1_int64
   RoutingTimeSpan = RoutingTimeSpan + tStep
   MaxOutfallFlow = merge(MaxOutfallFlow, SysOutfallFlow, (MaxOutfallFlow) >= (SysOutfallFlow))
end subroutine stats_updateFlowStats

! stats.c:484
recursive subroutine stats_updateTimeStepStats(tStep, trialsCount, steadyState)
   real(dp), value :: tStep
   integer(int32), value :: trialsCount
   integer(int32), value :: steadyState
   integer(int32) :: j_l
   j_l = 0
   TimeStepStats%steadyStateTime = TimeStepStats%steadyStateTime + (real(steadyState, dp) * tStep)
   if (steadyState == 0) then
      if (OldRoutingTime > 0.0_dp) then
         TimeStepStats%minTimeStep = merge(TimeStepStats%minTimeStep, tStep, (TimeStepStats%minTimeStep) <= (tStep))
         j_l = 1
         do while (j_l < 6)
            if (tStep >= TimeStepStats%timeStepIntervals(j_l)) then
               TimeStepStats%timeStepCounts(j_l) = TimeStepStats%timeStepCounts(j_l) + 1
               exit
            end if
            j_l = j_l + 1
         end do
      end if
      TimeStepStats%maxTimeStep = merge(TimeStepStats%maxTimeStep, tStep, (TimeStepStats%maxTimeStep) >= (tStep))
      TimeStepStats%routingTime = TimeStepStats%routingTime + tStep
      TimeStepStats%timeStepCount = TimeStepStats%timeStepCount + 1
      TimeStepStats%trialsCount = TimeStepStats%trialsCount + real(trialsCount, dp)
   end if
end subroutine stats_updateTimeStepStats

! stats.c:522
recursive subroutine stats_updateCriticalTimeCount(node_l, link_l)
   integer(int32), value :: node_l
   integer(int32), value :: link_l
   if (node_l >= 0) then
      NodeStats(node_l)%timeCourantCritical = NodeStats(node_l)%timeCourantCritical + 1.0_dp
   else if (link_l >= 0) then
      LinkStats(link_l)%timeCourantCritical = LinkStats(link_l)%timeCourantCritical + 1.0_dp
   end if
end subroutine stats_updateCriticalTimeCount

! stats.c:536
recursive subroutine stats_updateConvergenceStats(node_l, converged)
   integer(int32), value :: node_l
   integer(int32), value :: converged
   if (converged == 0) then
      NodeStats(node_l)%nonConvergedCount = NodeStats(node_l)%nonConvergedCount + 1
   end if
end subroutine stats_updateConvergenceStats

! stats.c:543
recursive subroutine stats_updateNodeStats(j_l, tStep, aDate)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   real(dp), value :: aDate
   integer(int32) :: k_l
   integer(int32) :: p_l
   real(dp) :: newVolume
   real(dp) :: newDepth
   integer(int32) :: canPond
   logical :: b1_
   logical :: b2_
   real(dp) :: v3_
   logical :: b4_
   logical :: b5_
   real(dp) :: v6_
   real(dp) :: v7_
   real(dp) :: v8_
   k_l = 0
   p_l = 0
   newVolume = Node(j_l)%newVolume
   newDepth = Node(j_l)%newDepth
   b1_ = AllowPonding /= 0
   if (b1_) then
      b1_ = Node(j_l)%pondedArea > 0.0_dp
   end if
   canPond = merge(1, 0, b1_)
   NodeStats(j_l)%avgDepth = NodeStats(j_l)%avgDepth + newDepth
   if (newDepth > NodeStats(j_l)%maxDepth) then
      NodeStats(j_l)%maxDepth = newDepth
      NodeStats(j_l)%maxDepthDate = aDate
   end if
   if (Node(j_l)%type /= OUTFALL_c) then
      b2_ = newVolume > Node(j_l)%fullVolume
      if (.not. b2_) then
         b2_ = Node(j_l)%overflow > 0.0_dp
      end if
      if (b2_) then
         NodeStats(j_l)%timeFlooded = NodeStats(j_l)%timeFlooded + tStep
         NodeStats(j_l)%volFlooded = NodeStats(j_l)%volFlooded + (Node(j_l)%overflow * tStep)
         if (canPond /= 0) then
            if ((NodeStats(j_l)%maxPondedVol) >= (newVolume - Node(j_l)%fullVolume)) then
               v3_ = NodeStats(j_l)%maxPondedVol
            else
               v3_ = newVolume - Node(j_l)%fullVolume
            end if
            NodeStats(j_l)%maxPondedVol = v3_
         end if
      end if
      if (RouteModel == DW) then
         b4_ = Node(j_l)%type /= STORAGE_c
         if (.not. b4_) then
            b4_ = Node(j_l)%surDepth > 0.0_dp
         end if
         b5_ = b4_
         if (b5_) then
            b5_ = ((newDepth + Node(j_l)%invertElev) + 0.0001_dp) >= Node(j_l)%crownElev
         end if
         if (b5_) then
            NodeStats(j_l)%timeSurcharged = NodeStats(j_l)%timeSurcharged + tStep
         end if
      end if
   end if
   if (Node(j_l)%type == STORAGE_c) then
      k_l = Node(j_l)%subIndex
      StorageStats(k_l)%avgVol = StorageStats(k_l)%avgVol + newVolume
      StorageStats(k_l)%evapLosses = StorageStats(k_l)%evapLosses + Storage(Node(j_l)%subIndex)%evapLoss
      StorageStats(k_l)%exfilLosses = StorageStats(k_l)%exfilLosses + Storage(Node(j_l)%subIndex)%exfilLoss
      if ((newVolume) <= (Node(j_l)%fullVolume)) then
         v6_ = newVolume
      else
         v6_ = Node(j_l)%fullVolume
      end if
      newVolume = v6_
      if (newVolume > StorageStats(k_l)%maxVol) then
         StorageStats(k_l)%maxVol = newVolume
         StorageStats(k_l)%maxVolDate = aDate
      end if
      if ((StorageStats(k_l)%maxFlow) >= (Node(j_l)%outflow)) then
         v7_ = StorageStats(k_l)%maxFlow
      else
         v7_ = Node(j_l)%outflow
      end if
      StorageStats(k_l)%maxFlow = v7_
   end if
   if (Node(j_l)%type == OUTFALL_c) then
      k_l = Node(j_l)%subIndex
      if (Node(j_l)%inflow >= 0.001_dp) then
         OutfallStats(k_l)%avgFlow = OutfallStats(k_l)%avgFlow + Node(j_l)%inflow
         if ((OutfallStats(k_l)%maxFlow) >= (Node(j_l)%inflow)) then
            v8_ = OutfallStats(k_l)%maxFlow
         else
            v8_ = Node(j_l)%inflow
         end if
         OutfallStats(k_l)%maxFlow = v8_
         OutfallStats(k_l)%totalPeriods = OutfallStats(k_l)%totalPeriods + 1
      end if
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         OutfallStats(k_l)%totalLoad(p_l) = OutfallStats(k_l)%totalLoad(p_l) + ((Node(j_l)%inflow * Node(j_l)%newQual(p_l)) * tStep)
         p_l = p_l + 1
      end do
      SysOutfallFlow = SysOutfallFlow + Node(j_l)%inflow
   end if
   NodeStats(j_l)%totLatFlow = NodeStats(j_l)%totLatFlow + (((Node(j_l)%oldLatFlow + Node(j_l)%newLatFlow) * 0.5_dp) * tStep)
   if (abs(Node(j_l)%newLatFlow) > abs(NodeStats(j_l)%maxLatFlow)) then
      NodeStats(j_l)%maxLatFlow = Node(j_l)%newLatFlow
   end if
   if (Node(j_l)%inflow > NodeStats(j_l)%maxInflow) then
      NodeStats(j_l)%maxInflow = Node(j_l)%inflow
      NodeStats(j_l)%maxInflowDate = aDate
   end if
   if (Node(j_l)%overflow > NodeStats(j_l)%maxOverflow) then
      NodeStats(j_l)%maxOverflow = Node(j_l)%overflow
      NodeStats(j_l)%maxOverflowDate = aDate
   end if
end subroutine stats_updateNodeStats

! stats.c:647
recursive subroutine stats_updateLinkStats(j_l, tStep, aDate)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   real(dp), value :: aDate
   integer(int32) :: k_l
   real(dp) :: q_l
   real(dp) :: v_l
   real(dp) :: dq
   real(dp) :: v1_
   real(dp) :: v2_
   logical :: b3_
   k_l = 0
   q_l = 0.0_dp
   v_l = 0.0_dp
   dq = 0.0_dp
   dq = Link(j_l)%newFlow - Link(j_l)%oldFlow
   q_l = abs(Link(j_l)%newFlow)
   if (q_l > LinkStats(j_l)%maxFlow) then
      LinkStats(j_l)%maxFlow = q_l
      LinkStats(j_l)%maxFlowDate = aDate
   end if
   v_l = link_getVelocity(j_l, q_l, Link(j_l)%newDepth)
   if (v_l > LinkStats(j_l)%maxVeloc) then
      LinkStats(j_l)%maxVeloc = v_l
   end if
   if (Link(j_l)%newDepth > LinkStats(j_l)%maxDepth) then
      LinkStats(j_l)%maxDepth = Link(j_l)%newDepth
   end if
   if (Link(j_l)%type == PUMP_c) then
      if (q_l >= Link(j_l)%qFull) then
         LinkStats(j_l)%timeFullFlow = LinkStats(j_l)%timeFullFlow + tStep
      end if
      if (q_l > 0.001_dp) then
         k_l = Link(j_l)%subIndex
         if ((PumpStats(k_l)%minFlow) <= (q_l)) then
            v1_ = PumpStats(k_l)%minFlow
         else
            v1_ = q_l
         end if
         PumpStats(k_l)%minFlow = v1_
         PumpStats(k_l)%maxFlow = LinkStats(j_l)%maxFlow
         PumpStats(k_l)%avgFlow = PumpStats(k_l)%avgFlow + q_l
         PumpStats(k_l)%volume = PumpStats(k_l)%volume + (q_l * tStep)
         PumpStats(k_l)%utilized = PumpStats(k_l)%utilized + tStep
         PumpStats(k_l)%energy = PumpStats(k_l)%energy + ((link_getPower(j_l) * tStep) / 3600.0_dp)
         if (Link(j_l)%flowClass == DN_DRY) then
            PumpStats(k_l)%offCurveLow = PumpStats(k_l)%offCurveLow + tStep
         end if
         if (Link(j_l)%flowClass == UP_DRY) then
            PumpStats(k_l)%offCurveHigh = PumpStats(k_l)%offCurveHigh + tStep
         end if
         if (Link(j_l)%oldFlow < 0.001_dp) then
            PumpStats(k_l)%startUps = PumpStats(k_l)%startUps + 1
         end if
         PumpStats(k_l)%totalPeriods = PumpStats(k_l)%totalPeriods + 1
         LinkStats(j_l)%timeSurcharged = LinkStats(j_l)%timeSurcharged + tStep
         LinkStats(j_l)%timeFullUpstream = LinkStats(j_l)%timeFullUpstream + tStep
         LinkStats(j_l)%timeFullDnstream = LinkStats(j_l)%timeFullDnstream + tStep
      end if
   else if (Link(j_l)%type == CONDUIT_c) then
      if (Link(j_l)%normalFlow /= 0) then
         LinkStats(j_l)%timeNormalFlow = LinkStats(j_l)%timeNormalFlow + tStep
      end if
      if (Link(j_l)%inletControl /= 0) then
         LinkStats(j_l)%timeInletControl = LinkStats(j_l)%timeInletControl + tStep
      end if
      k_l = Link(j_l)%flowClass
      if ((k_l >= 0) .and. (k_l < MAX_FLOW_CLASSES)) then
         LinkStats(j_l)%timeInFlowClass(k_l) = LinkStats(j_l)%timeInFlowClass(k_l) + tStep
      end if
      k_l = Link(j_l)%subIndex
      if (q_l >= (Link(j_l)%qFull * real(Conduit(k_l)%barrels, dp))) then
         LinkStats(j_l)%timeFullFlow = LinkStats(j_l)%timeFullFlow + tStep
      end if
      if (Conduit(k_l)%capacityLimited /= 0) then
         LinkStats(j_l)%timeCapacityLimited = LinkStats(j_l)%timeCapacityLimited + tStep
      end if
      select case (Conduit(k_l)%fullState)
      case (10)
         LinkStats(j_l)%timeSurcharged = LinkStats(j_l)%timeSurcharged + tStep
         LinkStats(j_l)%timeFullUpstream = LinkStats(j_l)%timeFullUpstream + tStep
         LinkStats(j_l)%timeFullDnstream = LinkStats(j_l)%timeFullDnstream + tStep
      case (8)
         LinkStats(j_l)%timeFullUpstream = LinkStats(j_l)%timeFullUpstream + tStep
      case (9)
         LinkStats(j_l)%timeFullDnstream = LinkStats(j_l)%timeFullDnstream + tStep
      end select
      if (Link(j_l)%xsect%type == STREET_XSECT) then
         if ((LinkStats(j_l)%maxStreetFilled) >= (street_getExtentFilled(j_l))) then
            v2_ = LinkStats(j_l)%maxStreetFilled
         else
            v2_ = street_getExtentFilled(j_l)
         end if
         LinkStats(j_l)%maxStreetFilled = v2_
      end if
   end if
   k_l = LinkStats(j_l)%flowTurnSign
   LinkStats(j_l)%flowTurnSign = merge(-1, 1, (dq) < 0.0_dp)
   b3_ = abs(dq) > 0.001_dp
   if (b3_) then
      b3_ = (k_l * LinkStats(j_l)%flowTurnSign) < 0
   end if
   if (b3_) then
      LinkStats(j_l)%flowTurns = LinkStats(j_l)%flowTurns + 1_int64
   end if
end subroutine stats_updateLinkStats

! stats.c:756
recursive subroutine stats_findMaxStats()
   integer(int32) :: j_l
   real(dp) :: x_l
   real(dp) :: z_l
   real(dp) :: stepCount
   j_l = 0
   x_l = 0.0_dp
   z_l = 0.0_dp
   stepCount = 0.0_dp
   j_l = 0
   do while (j_l < 5)
      MaxMassBalErrs(j_l)%objType = NODE_c
      MaxMassBalErrs(j_l)%index = -1
      MaxMassBalErrs(j_l)%value = -1.0_dp
      MaxCourantCrit(j_l)%index = -1
      MaxCourantCrit(j_l)%value = -1.0_dp
      MaxFlowTurns(j_l)%index = -1
      MaxFlowTurns(j_l)%value = -1.0_dp
      MaxNonConverged(j_l)%index = -1
      MaxNonConverged(j_l)%value = 0.0_dp
      j_l = j_l + 1
   end do
   if (ReportStepCount > 2_int64) then
      stepCount = real(ReportStepCount, dp)
      z_l = 100.0_dp / ((2.0_dp / 3.0_dp) * (stepCount - 2.0_dp))
      j_l = 0
      do while (j_l < Nobjects(LINK_c))
         x_l = real(LinkStats(j_l)%flowTurns, dp) * z_l
         call stats_updateMaxStats(MaxFlowTurns, LINK_c, j_l, x_l)
         j_l = j_l + 1
      end do
   end if
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      if (Node(j_l)%degree <= 0) then
         goto 102
      end if
      if (NodeInflow(j_l) <= 0.1_dp) then
         goto 102
      end if
      if (NodeInflow(j_l) > 0.0_dp) then
         x_l = 1.0_dp - (NodeOutflow(j_l) / NodeInflow(j_l))
      else if (NodeOutflow(j_l) > 0.0_dp) then
         x_l = -1.0_dp
      else
         x_l = 0.0_dp
      end if
      call stats_updateMaxStats(MaxMassBalErrs, NODE_c, j_l, 100.0_dp * x_l)
      102 continue
      j_l = j_l + 1
   end do
   stepCount = real(TimeStepStats%timeStepCount, dp)
   if (RouteModel == DW) then
      j_l = 0
      do while (j_l < Nobjects(NODE_c))
         call stats_updateMaxStats(MaxNonConverged, NODE_c, j_l, real(NodeStats(j_l)%nonConvergedCount, dp) / stepCount)
         j_l = j_l + 1
      end do
   end if
   if ((RouteModel /= DW) .or. (CourantFactor == 0.0_dp)) then
      return
   end if
   if (stepCount == 0.0_dp) then
      return
   end if
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      x_l = NodeStats(j_l)%timeCourantCritical / stepCount
      call stats_updateMaxStats(MaxCourantCrit, NODE_c, j_l, 100.0_dp * x_l)
      j_l = j_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      x_l = LinkStats(j_l)%timeCourantCritical / stepCount
      call stats_updateMaxStats(MaxCourantCrit, LINK_c, j_l, 100.0_dp * x_l)
      j_l = j_l + 1
   end do
end subroutine stats_findMaxStats

! stats.c:841
recursive subroutine stats_updateMaxStats(maxStats, i_l, j_l, x_l)
   type(TMaxStats), pointer, intent(in) :: maxStats(:)
   integer(int32), value :: i_l
   integer(int32), value :: j_l
   real(dp), value :: x_l
   integer(int32) :: k_l
   type(TMaxStats), target :: maxStats1
   type(TMaxStats), target :: maxStats2
   k_l = 0
   maxStats1 = zero_TMaxStats
   maxStats2 = zero_TMaxStats
   maxStats1%objType = i_l
   maxStats1%index = j_l
   maxStats1%value = x_l
   k_l = 0
   do while (k_l < 5)
      if (abs(maxStats1%value) > abs(maxStats(k_l)%value)) then
         maxStats2 = maxStats(k_l)
         maxStats(k_l) = maxStats1
         maxStats1 = maxStats2
      end if
      k_l = k_l + 1
   end do
end subroutine stats_updateMaxStats

! statsrpt.c:84
recursive subroutine statsrpt_writeReport()
   integer(int64) :: dum1_
   logical :: b2_
   logical :: b3_
   if ((FlowUnits == MGD) .or. (FlowUnits == CMS)) then
      dum1_ = sstrncpy(cview(FlowFmt), lit_534, 5_int64)
   else
      dum1_ = sstrncpy(cview(FlowFmt), lit_535, 5_int64)
   end if
   if (UnitSystem == US) then
      Vcf = 7.48_dp / 1.0e6_dp
   else
      Vcf = 28.317_dp / 1.0e6_dp
   end if
   if (Nobjects(SUBCATCH_c) > 0) then
      b2_ = .not. (IgnoreRainfall /= 0)
      if (.not. b2_) then
         b2_ = (Nobjects(SNOWMELT_c) > 0) .and. (.not. (IgnoreSnowmelt /= 0))
      end if
      b3_ = b2_
      if (.not. b3_) then
         b3_ = (Nobjects(AQUIFER_c) > 0) .and. (.not. (IgnoreGwater /= 0))
      end if
      if (b3_) then
         call writeSubcatchRunoff()
         call lid_writeWaterBalance()
         if (.not. (IgnoreGwater /= 0)) then
            call writeGroundwater()
         end if
         if ((Nobjects(POLLUT_c) > 0) .and. (.not. (IgnoreQuality /= 0))) then
            call writeSubcatchLoads()
         end if
      end if
   end if
   if ((Nobjects(LINK_c) > 0) .and. (.not. (IgnoreRouting /= 0))) then
      call writeNodeDepths()
      call writeNodeFlows()
      if (RouteModel == DW) then
         call writeNodeSurcharge()
      end if
      call writeNodeFlooding()
      call writeStorageVolumes()
      call writeOutfallLoads()
      call inlet_writeStatsReport()
      call writeLinkFlows()
      call writeFlowClass()
      call writeLinkSurcharge()
      call writePumpFlows()
      if ((Nobjects(POLLUT_c) > 0) .and. (.not. (IgnoreQuality /= 0))) then
         call writeLinkLoads()
      end if
   end if
end subroutine statsrpt_writeReport

! statsrpt.c:133
recursive subroutine writeSubcatchRunoff()
   integer(int32) :: j_l
   real(dp) :: a_l
   real(dp) :: x_l
   real(dp) :: r_l
   j_l = 0
   a_l = 0.0_dp
   x_l = 0.0_dp
   r_l = 0.0_dp
   if (Nobjects(SUBCATCH_c) == 0) then
      return
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_473)
   call report_writeLine(lit_536)
   call report_writeLine(lit_473)
   call report_writeLine(lit_0)
   call c_fprintf(Frpt%file, lit_537)
   if (UnitSystem == US) then
      call c_fprintf(Frpt%file, lit_538, VolUnitsWords(UnitSystem), FlowUnitWords(FlowUnits))
   else
      call c_fprintf(Frpt%file, lit_539, VolUnitsWords(UnitSystem), FlowUnitWords(FlowUnits))
   end if
   call c_fprintf(Frpt%file, lit_540)
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      a_l = Subcatch(j_l)%area
      if (a_l == 0.0_dp) then
         goto 100
      end if
      call c_fprintf(Frpt%file, lit_541, Subcatch(j_l)%ID)
      x_l = SubcatchStats(j_l)%precip * UCF(RAINDEPTH)
      call c_fprintf(Frpt%file, lit_542, x_l / a_l)
      x_l = SubcatchStats(j_l)%runon * UCF(RAINDEPTH)
      call c_fprintf(Frpt%file, lit_542, x_l / a_l)
      x_l = SubcatchStats(j_l)%evap * UCF(RAINDEPTH)
      call c_fprintf(Frpt%file, lit_542, x_l / a_l)
      x_l = SubcatchStats(j_l)%infil * UCF(RAINDEPTH)
      call c_fprintf(Frpt%file, lit_542, x_l / a_l)
      x_l = SubcatchStats(j_l)%impervRunoff * UCF(RAINDEPTH)
      call c_fprintf(Frpt%file, lit_542, x_l / a_l)
      x_l = SubcatchStats(j_l)%pervRunoff * UCF(RAINDEPTH)
      call c_fprintf(Frpt%file, lit_542, x_l / a_l)
      x_l = SubcatchStats(j_l)%runoff * UCF(RAINDEPTH)
      call c_fprintf(Frpt%file, lit_542, x_l / a_l)
      x_l = SubcatchStats(j_l)%runoff * Vcf
      call c_fprintf(Frpt%file, lit_543, x_l)
      x_l = SubcatchStats(j_l)%maxFlow * UCF(FLOW)
      call c_fprintf(Frpt%file, lit_544, x_l)
      r_l = SubcatchStats(j_l)%precip + SubcatchStats(j_l)%runon
      if (r_l > 0.0_dp) then
         r_l = SubcatchStats(j_l)%runoff / r_l
      end if
      call c_fprintf(Frpt%file, lit_545, r_l)
      100 continue
      j_l = j_l + 1
   end do
   call report_writeLine(lit_0)
end subroutine writeSubcatchRunoff

! statsrpt.c:190
recursive subroutine writeGroundwater()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: count_l
   real(dp) :: totalSeconds
   real(dp), target :: x_l(0:8)
   logical :: b1_
   i_l = 0
   j_l = 0
   count_l = 0
   totalSeconds = NewRunoffTime / 1000.0_dp
   x_l = 0.0_dp
   if (Nobjects(SUBCATCH_c) == 0) then
      return
   end if
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      if (.not. (.not. associated(Subcatch(j_l)%groundwater))) then
         count_l = count_l + 1
      end if
      j_l = j_l + 1
   end do
   if (count_l == 0) then
      return
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_188)
   call report_writeLine(lit_546)
   call report_writeLine(lit_188)
   call report_writeLine(lit_0)
   call c_fprintf(Frpt%file, lit_547)
   if (UnitSystem == US) then
      call c_fprintf(Frpt%file, lit_548, FlowUnitWords(FlowUnits))
   else
      call c_fprintf(Frpt%file, lit_549, FlowUnitWords(FlowUnits))
   end if
   call c_fprintf(Frpt%file, lit_550)
   j_l = 0
   do while (j_l < Nobjects(SUBCATCH_c))
      b1_ = Subcatch(j_l)%area == 0.0_dp
      if (.not. b1_) then
         b1_ = .not. associated(Subcatch(j_l)%groundwater)
      end if
      if (b1_) then
         goto 101
      end if
      call c_fprintf(Frpt%file, lit_541, Subcatch(j_l)%ID)
      x_l(0) = Subcatch(j_l)%groundwater%stats%infil * UCF(RAINDEPTH)
      x_l(1) = Subcatch(j_l)%groundwater%stats%evap * UCF(RAINDEPTH)
      x_l(2) = Subcatch(j_l)%groundwater%stats%deepFlow * UCF(RAINDEPTH)
      x_l(3) = Subcatch(j_l)%groundwater%stats%latFlow * UCF(RAINDEPTH)
      x_l(4) = (Subcatch(j_l)%groundwater%stats%maxFlow * UCF(FLOW)) * Subcatch(j_l)%area
      x_l(5) = Subcatch(j_l)%groundwater%stats%avgUpperMoist / totalSeconds
      x_l(6) = (Subcatch(j_l)%groundwater%stats%avgWaterTable * UCF(LENGTH)) / totalSeconds
      x_l(7) = Subcatch(j_l)%groundwater%stats%finalUpperMoist
      x_l(8) = Subcatch(j_l)%groundwater%stats%finalWaterTable * UCF(LENGTH)
      i_l = 0
      do while (i_l < 9)
         call c_fprintf(Frpt%file, lit_544, x_l(i_l))
         i_l = i_l + 1
      end do
      101 continue
      j_l = j_l + 1
   end do
   call report_writeLine(lit_0)
end subroutine writeGroundwater

! statsrpt.c:245
recursive subroutine writeSubcatchLoads()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: p_l
   real(dp) :: x_l
   real(dp), pointer :: totals(:)
   integer(int8), target :: units(0:14)
   integer(int8), target :: subcatchLine(0:20)
   integer(int8), target :: pollutLine(0:14)
   integer(int64) :: dum1_
   i_l = 0
   j_l = 0
   p_l = 0
   x_l = 0.0_dp
   nullify(totals)
   units = 0_int8
   call cinit(subcatchLine, lit_551)
   call cinit(pollutLine, lit_552)
   allocate(totals(0:(int(Nobjects(POLLUT_c), int64)) - 1))
   totals = 0.0_dp
   if (associated(totals)) then
      call report_writeLine(lit_0)
      call report_writeLine(lit_553)
