! statsrpt.c:403
recursive subroutine writeNodeSurcharge()
   integer(int32) :: j_l
   integer(int32) :: n_l
   real(dp) :: t_l
   real(dp) :: d1
   real(dp) :: d2
   real(dp) :: v1_
   j_l = 0
   n_l = 0
   t_l = 0.0_dp
   d1 = 0.0_dp
   d2 = 0.0_dp
   call report_writeLine(lit_0)
   call report_writeLine(lit_574)
   call report_writeLine(lit_575)
   call report_writeLine(lit_574)
   call report_writeLine(lit_0)
   j_l = 0
   do while (j_l < Nobjects(NODE_c))
      if (Node(j_l)%type == OUTFALL_c) then
         goto 100
      end if
      if (NodeStats(j_l)%timeSurcharged == 0.0_dp) then
         goto 100
      end if
      if ((0.01_dp) >= (NodeStats(j_l)%timeSurcharged / 3600.0_dp)) then
         v1_ = 0.01_dp
      else
         v1_ = NodeStats(j_l)%timeSurcharged / 3600.0_dp
      end if
      t_l = v1_
      if (n_l == 0) then
         call report_writeLine(lit_576)
         call c_fprintf(Frpt%file, lit_577)
         if (UnitSystem == US) then
            call c_fprintf(Frpt%file, lit_578)
         else
            call c_fprintf(Frpt%file, lit_579)
         end if
         call c_fprintf(Frpt%file, lit_580)
         n_l = 1
      end if
      call c_fprintf(Frpt%file, lit_541, Node(j_l)%ID)
      call c_fprintf(Frpt%file, lit_569, NodeTypeWords(Node(j_l)%type))
      d1 = (NodeStats(j_l)%maxDepth + Node(j_l)%invertElev) - Node(j_l)%crownElev
      if (d1 < 0.0_dp) then
         d1 = 0.0_dp
      end if
      d2 = Node(j_l)%fullDepth - NodeStats(j_l)%maxDepth
      if (d2 < 0.0_dp) then
         d2 = 0.0_dp
      end if
      call c_fprintf(Frpt%file, lit_581, t_l, d1 * UCF(LENGTH), d2 * UCF(LENGTH))
      100 continue
      j_l = j_l + 1
   end do
   if (n_l == 0) then
      call report_writeLine(lit_582)
   end if
   call report_writeLine(lit_0)
end subroutine writeNodeSurcharge

