! statsrpt.c:508
recursive subroutine writeStorageVolumes()
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32), target :: days_l
   integer(int32), target :: hrs
   integer(int32), target :: mins
   real(dp) :: avgVol
   real(dp) :: maxVol
   real(dp) :: pctAvgVol
   real(dp) :: pctMaxVol
   real(dp) :: pctEvapLoss
   real(dp) :: pctSeepLoss
   j_l = 0
   k_l = 0
   days_l = 0
   hrs = 0
   mins = 0
   avgVol = 0.0_dp
   maxVol = 0.0_dp
   pctAvgVol = 0.0_dp
   pctMaxVol = 0.0_dp
   pctEvapLoss = 0.0_dp
   pctSeepLoss = 0.0_dp
   if (Nnodes(STORAGE_c) > 0) then
      call report_writeLine(lit_0)
      call report_writeLine(lit_574)
      call report_writeLine(lit_596)
      call report_writeLine(lit_574)
      call report_writeLine(lit_0)
      call c_fprintf(Frpt%file, lit_597)
      if (UnitSystem == US) then
         call c_fprintf(Frpt%file, lit_598)
      else
         call c_fprintf(Frpt%file, lit_599)
      end if
      call c_fprintf(Frpt%file, lit_600, FlowUnitWords(FlowUnits))
      call c_fprintf(Frpt%file, lit_601)
      j_l = 0
      do while (j_l < Nobjects(NODE_c))
         if (Node(j_l)%type /= STORAGE_c) then
            goto 100
         end if
         k_l = Node(j_l)%subIndex
         call c_fprintf(Frpt%file, lit_541, Node(j_l)%ID)
         avgVol = StorageStats(k_l)%avgVol / real(ReportStepCount, dp)
         maxVol = StorageStats(k_l)%maxVol
         pctMaxVol = 0.0_dp
         pctAvgVol = 0.0_dp
         if (Node(j_l)%fullVolume > 0.0_dp) then
            pctAvgVol = (avgVol / Node(j_l)%fullVolume) * 100.0_dp
            pctMaxVol = (maxVol / Node(j_l)%fullVolume) * 100.0_dp
         end if
         pctEvapLoss = 0.0_dp
         pctSeepLoss = 0.0_dp
         if (NodeInflow(j_l) > 0.0_dp) then
            pctEvapLoss = (StorageStats(k_l)%evapLosses / NodeInflow(j_l)) * 100.0_dp
            pctSeepLoss = (StorageStats(k_l)%exfilLosses / NodeInflow(j_l)) * 100.0_dp
         end if
         call c_fprintf(Frpt%file, lit_602, (avgVol * UCF(VOLUME)) / 1000.0_dp, pctAvgVol, pctEvapLoss, pctSeepLoss, (maxVol * UCF(VOLUME)) / 1000.0_dp, pctMaxVol)
         call getElapsedTime(StorageStats(k_l)%maxVolDate, days_l, hrs, mins)
         call c_fprintf(Frpt%file, lit_603, days_l, hrs, mins)
         call c_fprintf(Frpt%file, cview(FlowFmt), StorageStats(k_l)%maxFlow * UCF(FLOW))
         100 continue
         j_l = j_l + 1
      end do
      call report_writeLine(lit_0)
   end if
end subroutine writeStorageVolumes

! statsrpt.c:575
recursive subroutine writeOutfallLoads()
   integer(int8), target :: units(0:14)
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   real(dp) :: x_l
   real(dp) :: outfallCount
   real(dp) :: flowCount
   real(dp) :: flowSum
   real(dp) :: freqSum
   real(dp) :: volSum
   real(dp), pointer :: totals(:)
   integer(int64) :: dum1_
   units = 0_int8
   i_l = 0
   j_l = 0
   k_l = 0
   p_l = 0
   x_l = 0.0_dp
   outfallCount = 0.0_dp
   flowCount = 0.0_dp
   flowSum = 0.0_dp
   freqSum = 0.0_dp
   volSum = 0.0_dp
   nullify(totals)
   if (Nnodes(OUTFALL_c) > 0) then
      allocate(totals(0:(int(Nobjects(POLLUT_c), int64)) - 1))
      totals = 0.0_dp
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         totals(p_l) = 0.0_dp
         p_l = p_l + 1
      end do
      flowSum = 0.0_dp
      freqSum = 0.0_dp
      volSum = 0.0_dp
      call report_writeLine(lit_0)
      call report_writeLine(lit_604)
      call report_writeLine(lit_605)
      call report_writeLine(lit_604)
      call report_writeLine(lit_0)
      call c_fprintf(Frpt%file, lit_606)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_552)
         p_l = p_l + 1
      end do
      call c_fprintf(Frpt%file, lit_607)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_608)
         p_l = p_l + 1
      end do
      call c_fprintf(Frpt%file, lit_609)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_423, Pollut(p_l)%ID)
         p_l = p_l + 1
      end do
      call c_fprintf(Frpt%file, lit_610, FlowUnitWords(FlowUnits), FlowUnitWords(FlowUnits), VolUnitsWords(UnitSystem))
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         i_l = UnitSystem
         if (Pollut(p_l)%units == COUNT_c) then
            i_l = 2
         end if
         dum1_ = sstrncpy(cview(units), LoadUnitsWords(i_l), 14_int64)
         call c_fprintf(Frpt%file, lit_423, cview(units))
         p_l = p_l + 1
      end do
      call c_fprintf(Frpt%file, lit_606)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_552)
         p_l = p_l + 1
      end do
      j_l = 0
      do while (j_l < Nobjects(NODE_c))
         if (Node(j_l)%type /= OUTFALL_c) then
            goto 106
         end if
         k_l = Node(j_l)%subIndex
         flowCount = real(OutfallStats(k_l)%totalPeriods, dp)
         call c_fprintf(Frpt%file, lit_541, Node(j_l)%ID)
         x_l = (100.0_dp * flowCount) / real(ReportStepCount, dp)
         call c_fprintf(Frpt%file, lit_611, x_l)
         freqSum = freqSum + x_l
         if (flowCount > 0.0_dp) then
            x_l = (OutfallStats(k_l)%avgFlow * UCF(FLOW)) / flowCount
         else
            x_l = 0.0_dp
         end if
         flowSum = flowSum + x_l
         call c_fprintf(Frpt%file, lit_33)
         call c_fprintf(Frpt%file, cview(FlowFmt), x_l)
         call c_fprintf(Frpt%file, lit_33)
         call c_fprintf(Frpt%file, cview(FlowFmt), OutfallStats(k_l)%maxFlow * UCF(FLOW))
         call c_fprintf(Frpt%file, lit_573, NodeInflow(j_l) * Vcf)
         volSum = volSum + NodeInflow(j_l)
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            x_l = (OutfallStats(k_l)%totalLoad(p_l) * 28.317_dp) * Pollut(p_l)%mcf
            totals(p_l) = totals(p_l) + x_l
            if (Pollut(p_l)%units == COUNT_c) then
               x_l = merge(log10(x_l), x_l, (x_l) > 0.0_dp)
            end if
            call c_fprintf(Frpt%file, lit_427, x_l)
            p_l = p_l + 1
         end do
         106 continue
         j_l = j_l + 1
      end do
      outfallCount = real(Nnodes(OUTFALL_c), dp)
      call c_fprintf(Frpt%file, lit_606)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         call c_fprintf(Frpt%file, lit_552)
         p_l = p_l + 1
      end do
      call c_fprintf(Frpt%file, lit_612, freqSum / outfallCount)
      call c_fprintf(Frpt%file, cview(FlowFmt), flowSum)
      call c_fprintf(Frpt%file, lit_33)
      call c_fprintf(Frpt%file, cview(FlowFmt), MaxOutfallFlow * UCF(FLOW))
      call c_fprintf(Frpt%file, lit_573, volSum * Vcf)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         x_l = totals(p_l)
         if (Pollut(p_l)%units == COUNT_c) then
            x_l = merge(log10(x_l), x_l, (x_l) > 0.0_dp)
         end if
         call c_fprintf(Frpt%file, lit_427, x_l)
         p_l = p_l + 1
      end do
      call report_writeLine(lit_0)
      ! free(totals)
   end if
end subroutine writeOutfallLoads

! statsrpt.c:691
recursive subroutine writeLinkFlows()
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32), target :: days_l
   integer(int32), target :: hrs
   integer(int32), target :: mins
   real(dp) :: v_l
   real(dp) :: fullDepth
   logical :: b1_
   logical :: b2_
   j_l = 0
   k_l = 0
   days_l = 0
   hrs = 0
   mins = 0
   v_l = 0.0_dp
   fullDepth = 0.0_dp
   if (Nobjects(LINK_c) == 0) then
      return
   end if
   call report_writeLine(lit_0)
   call report_writeLine(lit_235)
   call report_writeLine(lit_613)
   call report_writeLine(lit_235)
   call report_writeLine(lit_0)
   call c_fprintf(Frpt%file, lit_614)
   if (UnitSystem == US) then
      call c_fprintf(Frpt%file, lit_615, FlowUnitWords(FlowUnits))
   else
      call c_fprintf(Frpt%file, lit_616, FlowUnitWords(FlowUnits))
   end if
   call c_fprintf(Frpt%file, lit_617)
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      k_l = Link(j_l)%subIndex
      call c_fprintf(Frpt%file, lit_541, Link(j_l)%ID)
      if (Link(j_l)%xsect%type == DUMMY) then
         call c_fprintf(Frpt%file, lit_618)
      else if (Link(j_l)%xsect%type == IRREGULAR) then
         call c_fprintf(Frpt%file, lit_619)
      else
         call c_fprintf(Frpt%file, lit_620, LinkTypeWords(Link(j_l)%type))
      end if
      call getElapsedTime(LinkStats(j_l)%maxFlowDate, days_l, hrs, mins)
      call c_fprintf(Frpt%file, cview(FlowFmt), LinkStats(j_l)%maxFlow * UCF(FLOW))
      call c_fprintf(Frpt%file, lit_570, days_l, hrs, mins)
      b1_ = Link(j_l)%type == PUMP_c
      if (b1_) then
         b1_ = Link(j_l)%qFull > 0.0_dp
      end if
      if (b1_) then
         call c_fprintf(Frpt%file, lit_621)
         call c_fprintf(Frpt%file, lit_622, LinkStats(j_l)%maxFlow / Link(j_l)%qFull)
         goto 100
      end if
      if (Link(j_l)%xsect%type == DUMMY) then
         goto 100
      end if
      if (Link(j_l)%type == OUTLET_c) then
         goto 100
      end if
      if (Link(j_l)%type == CONDUIT_c) then
         v_l = LinkStats(j_l)%maxVeloc * UCF(LENGTH)
         if (v_l > 50.0_dp) then
