         res_ = error_setInpError(ERR_NUMBER, tok_l(6))
         return
      end if
   end if
   sides = 2
   if (ntoks > 7) then
      if (((.not. (getInt(tok_l(7), sides) /= 0)) .or. (sides < 1)) .or. (sides > 2)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(7))
