         b4_ = x_l(8) < 0.0_dp
      end if
      if (b4_) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(8))
         return
      end if
      if (x_l(8) > 0.0_dp) then
         if (ntoks < 11) then
            res_ = error_setInpError(ERR_ITEMS, lit_0)
            return
         end if
         k_l = 9
         do while (k_l <= 10)
            b5_ = .not. (getDouble(tok_l(k_l), x_l(k_l)) /= 0)
