recursive function street_getExtentFilled(link_l) result(res_)
   integer(int32), value :: link_l
   real(dp) :: res_
   integer(int32) :: k_l
   integer(int32) :: t_l
   real(dp) :: filled
   real(dp) :: v1_
   real(dp) :: v2_
   res_ = 0.0_dp
   k_l = 0
   t_l = 0
   filled = 0.0_dp
   t_l = Link(link_l)%xsect%transect
   if (t_l < 0) then
      res_ = 0.0_dp
      return
   end if
   if (RouteModel == DW) then
      if ((Node(Link(link_l)%node1)%newDepth) >= (Node(Link(link_l)%node2)%newDepth)) then
         v1_ = Node(Link(link_l)%node1)%newDepth
      else
         v1_ = Node(Link(link_l)%node2)%newDepth
      end if
      filled = v1_
   else
      k_l = Link(link_l)%subIndex
      if ((Conduit(k_l)%a1) >= (Conduit(k_l)%a2)) then
         v2_ = Conduit(k_l)%a1
      else
         v2_ = Conduit(k_l)%a2
      end if
      filled = v2_
   end if
   res_ = filled
   return
end function street_getExtentFilled

