   Subcatch(j_l)%subArea(PERV)%dStore = x_l(3) / UCF(RAINDEPTH)
   Subcatch(j_l)%subArea(IMPERV0)%fArea = (Subcatch(j_l)%fracImperv * x_l(4)) / 100.0_dp
   Subcatch(j_l)%subArea(IMPERV1)%fArea = Subcatch(j_l)%fracImperv * (1.0_dp - (x_l(4) / 100.0_dp))
   Subcatch(j_l)%subArea(PERV)%fArea = 1.0_dp - Subcatch(j_l)%fracImperv
   i_l = IMPERV0
   do while (i_l <= PERV)
      Subcatch(j_l)%subArea(i_l)%routeTo = TO_OUTLET
      Subcatch(j_l)%subArea(i_l)%fOutlet = 1.0_dp
      i_l = i_l + 1
   end do
   k_l = d2i(x_l(5))
   b4_ = Subcatch(j_l)%fracImperv == 0.0_dp
   if (.not. b4_) then
      b4_ = Subcatch(j_l)%fracImperv == 1.0_dp
   end if
   if (b4_) then
      k_l = TO_OUTLET
   end if
   b5_ = k_l == TO_IMPERV
   if (b5_) then
      b5_ = Subcatch(j_l)%fracImperv /= 0.0_dp
   end if
   if (b5_) then
      Subcatch(j_l)%subArea(PERV)%routeTo = k_l
      Subcatch(j_l)%subArea(PERV)%fOutlet = 1.0_dp - x_l(6)
   end if
   if (k_l == TO_PERV) then
      Subcatch(j_l)%subArea(IMPERV0)%routeTo = k_l
      Subcatch(j_l)%subArea(IMPERV1)%routeTo = k_l
      Subcatch(j_l)%subArea(IMPERV0)%fOutlet = 1.0_dp - x_l(6)
      Subcatch(j_l)%subArea(IMPERV1)%fOutlet = 1.0_dp - x_l(6)
   end if
   res_ = 0
   return
end function subcatch_readSubareaParams

! subcatch.c:284
recursive function subcatch_readLanduseParams(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   real(dp), target :: f_l
   res_ = 0
   j_l = 0
   k_l = 0
   m_l = 0
   f_l = 0.0_dp
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(SUBCATCH_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   k_l = 2
   do while (k_l <= ntoks)
      m_l = project_findObject(LANDUSE_c, tok_l(k_l - 1))
      if (m_l < 0) then
         res_ = error_setInpError(ERR_NAME, tok_l(k_l - 1))
         return
      end if
      if ((k_l + 1) > ntoks) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (.not. (getDouble(tok_l(k_l), f_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(k_l))
         return
      end if
      Subcatch(j_l)%landFactor(m_l)%fraction = f_l / 100.0_dp
      k_l = k_l + 2
   end do
   res_ = 0
   return
end function subcatch_readLanduseParams

