! subcatch.c:364
recursive subroutine subcatch_validate(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   real(dp) :: area_l
   real(dp) :: nonLidArea
   logical :: b1_
   logical :: b2_
   i_l = 0
   area_l = 0.0_dp
   nonLidArea = Subcatch(j_l)%area
   b1_ = Subcatch(j_l)%outNode >= 0
   if (b1_) then
      b1_ = Subcatch(j_l)%outSubcatch >= 0
   end if
   if (b1_) then
      call report_writeErrorMsg(ERR_SUBCATCH_OUTLET, Subcatch(j_l)%ID)
   end if
   call gwater_validate(j_l)
   nonLidArea = nonLidArea - Subcatch(j_l)%lidArea
   i_l = IMPERV0
   do while (i_l <= PERV)
      if (i_l == PERV) then
         area_l = (1.0_dp - Subcatch(j_l)%fracImperv) * nonLidArea
      else
         area_l = Subcatch(j_l)%fracImperv * nonLidArea
      end if
      Subcatch(j_l)%subArea(i_l)%alpha = 0.0_dp
      b2_ = area_l > 0.0_dp
      if (b2_) then
         b2_ = Subcatch(j_l)%subArea(i_l)%N > 0.0_dp
      end if
      if (b2_) then
         Subcatch(j_l)%subArea(i_l)%alpha = (((MCOEFF * Subcatch(j_l)%width) / area_l) * sqrt(Subcatch(j_l)%slope)) / Subcatch(j_l)%subArea(i_l)%N
      end if
      i_l = i_l + 1
   end do
   i_l = Subcatch(j_l)%gage
   if (i_l >= 0) then
      Gage(i_l)%isUsed = 1
   end if
end subroutine subcatch_validate

! subcatch.c:419
recursive subroutine subcatch_initState(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   i_l = 0
   Subcatch(j_l)%rainfall = 0.0_dp
   Subcatch(j_l)%oldRunoff = 0.0_dp
   Subcatch(j_l)%newRunoff = 0.0_dp
   Subcatch(j_l)%oldSnowDepth = 0.0_dp
   Subcatch(j_l)%newSnowDepth = 0.0_dp
   Subcatch(j_l)%runon = 0.0_dp
   Subcatch(j_l)%evapLoss = 0.0_dp
   Subcatch(j_l)%infilLoss = 0.0_dp
   if (Subcatch(j_l)%infil == j_l) then
      call infil_initState(j_l)
   end if
   if (associated(Subcatch(j_l)%groundwater)) then
      call gwater_initState(j_l)
   end if
   if (associated(Subcatch(j_l)%snowpack)) then
      call snow_initSnowpack(j_l)
   end if
   i_l = IMPERV0
   do while (i_l <= PERV)
      Subcatch(j_l)%subArea(i_l)%depth = 0.0_dp
      Subcatch(j_l)%subArea(i_l)%inflow = 0.0_dp
      Subcatch(j_l)%subArea(i_l)%runoff = 0.0_dp
      i_l = i_l + 1
   end do
   call surfqual_initState(j_l)
end subroutine subcatch_initState

! subcatch.c:457
recursive subroutine subcatch_setOldState(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   i_l = 0
   Subcatch(j_l)%oldRunoff = Subcatch(j_l)%newRunoff
   Subcatch(j_l)%oldSnowDepth = Subcatch(j_l)%newSnowDepth
   i_l = IMPERV0
   do while (i_l <= PERV)
      Subcatch(j_l)%subArea(i_l)%inflow = 0.0_dp
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(POLLUT_c))
      Subcatch(j_l)%oldQual(i_l) = Subcatch(j_l)%newQual(i_l)
      Subcatch(j_l)%newQual(i_l) = 0.0_dp
      i_l = i_l + 1
   end do
   call lid_setOldGroupState(j_l)
end subroutine subcatch_setOldState

! subcatch.c:481
recursive function subcatch_getFracPerv(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   real(dp) :: fracPerv_l
   res_ = 0.0_dp
   fracPerv_l = 1.0_dp - Subcatch(j_l)%fracImperv
   if (Subcatch(j_l)%lidArea > 0.0_dp) then
      fracPerv_l = ((fracPerv_l * (Subcatch(j_l)%area - Subcatch(j_l)%lidArea)) + lid_getPervArea(j_l)) / Subcatch(j_l)%area
      fracPerv_l = merge(fracPerv_l, 1.0_dp, (fracPerv_l) <= (1.0_dp))
   end if
   res_ = fracPerv_l
   return
end function subcatch_getFracPerv

! subcatch.c:502
recursive function subcatch_getStorage(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: v_l
   res_ = 0.0_dp
   i_l = 0
   v_l = 0.0_dp
   i_l = IMPERV0
   do while (i_l <= PERV)
      v_l = v_l + (Subcatch(j_l)%subArea(i_l)%depth * Subcatch(j_l)%subArea(i_l)%fArea)
      i_l = i_l + 1
   end do
   res_ = (v_l * (Subcatch(j_l)%area - Subcatch(j_l)%lidArea)) + lid_getStoredVolume(j_l)
   return
end function subcatch_getStorage

! subcatch.c:523
recursive subroutine subcatch_getRunon(j_l)
   integer(int32), value :: j_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   real(dp) :: q_l
   real(dp) :: q1
   real(dp) :: q2
   real(dp) :: pervArea
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   k_l = 0
   p_l = 0
   q_l = 0.0_dp
   q1 = 0.0_dp
   q2 = 0.0_dp
   pervArea = 0.0_dp
   k_l = Subcatch(j_l)%outSubcatch
   q_l = Subcatch(j_l)%oldRunoff
   if ((k_l >= 0) .and. (k_l /= j_l)) then
      call subcatch_addRunonFlow(k_l, q_l)
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         Subcatch(k_l)%newQual(p_l) = Subcatch(k_l)%newQual(p_l) + ((q_l * Subcatch(j_l)%oldQual(p_l)) * 28.317_dp)
         p_l = p_l + 1
      end do
   end if
   if (Subcatch(j_l)%lidArea > 0.0_dp) then
      call lid_addDrainRunon(j_l)
   end if
   b1_ = Subcatch(j_l)%fracImperv < 1.0_dp
   if (b1_) then
      b1_ = Subcatch(j_l)%subArea(IMPERV0)%routeTo == TO_PERV
   end if
   if (b1_) then
      q1 = Subcatch(j_l)%subArea(IMPERV0)%runoff * Subcatch(j_l)%subArea(IMPERV0)%fArea
      q2 = Subcatch(j_l)%subArea(IMPERV1)%runoff * Subcatch(j_l)%subArea(IMPERV1)%fArea
      q_l = q1 + q2
      Subcatch(j_l)%subArea(PERV)%inflow = Subcatch(j_l)%subArea(PERV)%inflow + ((q_l * (1.0_dp - Subcatch(j_l)%subArea(IMPERV0)%fOutlet)) / Subcatch(j_l)%subArea(PERV)%fArea)
   end if
   b2_ = Subcatch(j_l)%fracImperv > 0.0_dp
   if (b2_) then
      b2_ = Subcatch(j_l)%subArea(PERV)%routeTo == TO_IMPERV
   end if
   b3_ = b2_
   if (b3_) then
      b3_ = Subcatch(j_l)%subArea(IMPERV1)%fArea > 0.0_dp
   end if
   if (b3_) then
      q_l = Subcatch(j_l)%subArea(PERV)%runoff
      Subcatch(j_l)%subArea(IMPERV1)%inflow = Subcatch(j_l)%subArea(IMPERV1)%inflow + (((q_l * (1.0_dp - Subcatch(j_l)%subArea(PERV)%fOutlet)) * Subcatch(j_l)%subArea(PERV)%fArea) / Subcatch(j_l)%subArea(IMPERV1)%fArea)
   end if
   b4_ = Subcatch(j_l)%lidArea > 0.0_dp
   if (b4_) then
      b4_ = Subcatch(j_l)%fracImperv < 1.0_dp
   end if
   if (b4_) then
      pervArea = Subcatch(j_l)%subArea(PERV)%fArea * (Subcatch(j_l)%area - Subcatch(j_l)%lidArea)
      q_l = lid_getFlowToPerv(j_l)
      if (pervArea > 0.0_dp) then
         Subcatch(j_l)%subArea(PERV)%inflow = Subcatch(j_l)%subArea(PERV)%inflow + (q_l / pervArea)
      end if
   end if
end subroutine subcatch_getRunon

! subcatch.c:600
recursive subroutine subcatch_addRunonFlow(k_l, q_l)
   integer(int32), value :: k_l
   real(dp), value :: q_l
   integer(int32) :: i_l
   real(dp) :: nonLidArea
   i_l = 0
   nonLidArea = 0.0_dp
   if (Subcatch(k_l)%area <= 0.0_dp) then
      return
   end if
   nonLidArea = Subcatch(k_l)%area - Subcatch(k_l)%lidArea
   if (nonLidArea > 0.0_dp) then
      q_l = q_l / nonLidArea
   else
      q_l = q_l / Subcatch(k_l)%area
   end if
   Subcatch(k_l)%runon = Subcatch(k_l)%runon + q_l
   i_l = IMPERV0
   do while (i_l <= PERV)
      Subcatch(k_l)%subArea(i_l)%inflow = Subcatch(k_l)%subArea(i_l)%inflow + q_l
      i_l = i_l + 1
   end do
end subroutine subcatch_addRunonFlow

! subcatch.c:629
recursive function subcatch_getRunoff(j_l, tStep) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: nonLidArea
   real(dp) :: area_l
   real(dp), target :: netPrecip(0:2)
   real(dp) :: vRain
   real(dp) :: vRunon
   real(dp) :: vOutflow_l
   real(dp) :: runoff
   real(dp) :: evapRate_l
   real(dp) :: subAreaRunoff
   real(dp) :: vImpervRunoff
   real(dp) :: vPervRunoff
   logical :: b1_
   logical :: b2_
   logical :: b3_
   res_ = 0.0_dp
   i_l = 0
   nonLidArea = 0.0_dp
   area_l = 0.0_dp
   netPrecip = 0.0_dp
   vRain = 0.0_dp
   vRunon = 0.0_dp
   vOutflow_l = 0.0_dp
   runoff = 0.0_dp
   evapRate_l = 0.0_dp
   subAreaRunoff = 0.0_dp
   vImpervRunoff = 0.0_dp
   vPervRunoff = 0.0_dp
   Vevap = 0.0_dp
   Vpevap = 0.0_dp
   Vinfil = 0.0_dp
   Voutflow = 0.0_dp
   VlidIn = 0.0_dp
   VlidInfil = 0.0_dp
   VlidOut = 0.0_dp
   VlidDrain = 0.0_dp
   VlidReturn = 0.0_dp
   nonLidArea = Subcatch(j_l)%area - Subcatch(j_l)%lidArea
   vRunon = (Subcatch(j_l)%runon * tStep) * nonLidArea
   Vinflow = vRunon + (subcatch_getDepth(j_l) * nonLidArea)
   if (nonLidArea == 0.0_dp) then
      vRunon = (Subcatch(j_l)%runon * tStep) * Subcatch(j_l)%area
   end if
   call getNetPrecip(j_l, netPrecip, tStep)
   b1_ = Evap%dryOnly /= 0
   if (b1_) then
      b1_ = Subcatch(j_l)%rainfall > 0.0_dp
   end if
   if (b1_) then
      evapRate_l = 0.0_dp
   else
      evapRate_l = Evap%rate
   end if
   call infil_setInfilFactor(j_l)
   if (nonLidArea > 0.0_dp) then
      i_l = IMPERV0
      do while (i_l <= PERV)
         area_l = nonLidArea * Subcatch(j_l)%subArea(i_l)%fArea
         Subcatch(j_l)%subArea(i_l)%runoff = getSubareaRunoff(j_l, i_l, area_l, netPrecip(i_l), evapRate_l, tStep)
         subAreaRunoff = Subcatch(j_l)%subArea(i_l)%runoff * area_l
         if (i_l == PERV) then
            vPervRunoff = subAreaRunoff * tStep
         else
            vImpervRunoff = vImpervRunoff + (subAreaRunoff * tStep)
         end if
         runoff = runoff + subAreaRunoff
         i_l = i_l + 1
      end do
   end if
   if (Subcatch(j_l)%lidArea > 0.0_dp) then
      call lid_getRunoff(j_l, tStep)
   end if
   b2_ = .not. (IgnoreGwater /= 0)
   if (b2_) then
      b2_ = associated(Subcatch(j_l)%groundwater)
   end if
   if (b2_) then
      call gwater_getGroundwater(j_l, Vpevap, Vinfil + VlidInfil, tStep)
   end if
   area_l = Subcatch(j_l)%area
   Subcatch(j_l)%evapLoss = (Vevap / tStep) / area_l
   Subcatch(j_l)%infilLoss = ((Vinfil + VlidInfil) / tStep) / area_l
   vOutflow_l = (Voutflow - VlidIn) + VlidOut
   Subcatch(j_l)%newRunoff = vOutflow_l / tStep
   vRain = (Subcatch(j_l)%rainfall * tStep) * area_l
   call stats_updateSubcatchStats(j_l, vRain, vRunon, Vevap, Vinfil + VlidInfil, vImpervRunoff, vPervRunoff, vOutflow_l + VlidDrain, Subcatch(j_l)%newRunoff + (VlidDrain / tStep))
   b3_ = Subcatch(j_l)%outNode == (-1)
   if (b3_) then
      b3_ = Subcatch(j_l)%outSubcatch /= j_l
   end if
   if (b3_) then
      vOutflow_l = 0.0_dp
   end if
   call massbal_updateRunoffTotals(RUNOFF_RAINFALL, vRain)
   call massbal_updateRunoffTotals(RUNOFF_EVAP, Vevap)
   call massbal_updateRunoffTotals(RUNOFF_INFIL, Vinfil + VlidInfil)
   call massbal_updateRunoffTotals(RUNOFF_RUNOFF, vOutflow_l)
   res_ = runoff / area_l
   return
end function subcatch_getRunoff

! subcatch.c:758
recursive subroutine getNetPrecip(j_l, netPrecip, tStep)
   integer(int32), value :: j_l
   real(dp), pointer, intent(in) :: netPrecip(:)
   real(dp), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: k_l
   real(dp), target :: rainfall_l
   real(dp), target :: snowfall
   real(dp) :: dum1_
   i_l = 0
   k_l = 0
   rainfall_l = 0.0_dp
   snowfall = 0.0_dp
   k_l = Subcatch(j_l)%gage
   if (k_l >= 0) then
      dum1_ = gage_getPrecip(k_l, rainfall_l, snowfall)
   end if
   Subcatch(j_l)%rainfall = rainfall_l + snowfall
   if (associated(Subcatch(j_l)%snowpack) .and. (.not. (IgnoreSnowmelt /= 0))) then
      Subcatch(j_l)%newSnowDepth = snow_getSnowMelt(j_l, rainfall_l, snowfall, tStep, netPrecip)
   else
      i_l = IMPERV0
      do while (i_l <= PERV)
         netPrecip(i_l) = rainfall_l + snowfall
         i_l = i_l + 1
      end do
   end if
end subroutine getNetPrecip

! subcatch.c:798
recursive function subcatch_getDepth(j_l) result(res_)
   integer(int32), value :: j_l
   real(dp) :: res_
   integer(int32) :: i_l
   real(dp) :: fArea
   real(dp) :: depth
   res_ = 0.0_dp
   i_l = 0
   fArea = 0.0_dp
   depth = 0.0_dp
   i_l = IMPERV0
   do while (i_l <= PERV)
      fArea = Subcatch(j_l)%subArea(i_l)%fArea
      if (fArea > 0.0_dp) then
         depth = depth + (Subcatch(j_l)%subArea(i_l)%depth * fArea)
      end if
      i_l = i_l + 1
   end do
   res_ = depth
   return
end function subcatch_getDepth

! subcatch.c:820
recursive function subcatch_getWtdOutflow(j_l, f_l) result(res_)
   integer(int32), value :: j_l
   real(dp), value :: f_l
   real(dp) :: res_
   res_ = 0.0_dp
   if (Subcatch(j_l)%area == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   res_ = ((1.0_dp - f_l) * Subcatch(j_l)%oldRunoff) + (f_l * Subcatch(j_l)%newRunoff)
   return
end function subcatch_getWtdOutflow

! subcatch.c:834
recursive subroutine subcatch_getResults(j_l, f_l, x_l)
   integer(int32), value :: j_l
   real(dp), value :: f_l
   real(sp), pointer, intent(in) :: x_l(:)
   integer(int32) :: p_l
   integer(int32) :: k_l
   real(dp) :: f1
   real(dp) :: z_l
   real(dp) :: runoff
   type(TGroundwater), pointer :: gw_l
   p_l = 0
   k_l = 0
   f1 = 1.0_dp - f_l
   z_l = 0.0_dp
   runoff = 0.0_dp
   nullify(gw_l)
   k_l = Subcatch(j_l)%gage
   if (k_l >= 0) then
      x_l(SUBCATCH_RAINFALL) = real(Gage(k_l)%reportRainfall, sp)
   else
      x_l(SUBCATCH_RAINFALL) = 0.0_sp
   end if
   z_l = ((f1 * Subcatch(j_l)%oldSnowDepth) + (f_l * Subcatch(j_l)%newSnowDepth)) * UCF(RAINDEPTH)
   x_l(SUBCATCH_SNOWDEPTH) = real(z_l, sp)
   x_l(SUBCATCH_EVAP) = real(Subcatch(j_l)%evapLoss * UCF(EVAPRATE), sp)
   x_l(SUBCATCH_INFIL) = real(Subcatch(j_l)%infilLoss * UCF(RAINFALL), sp)
   runoff = (f1 * Subcatch(j_l)%oldRunoff) + (f_l * Subcatch(j_l)%newRunoff)
   if (Subcatch(j_l)%lidArea > 0.0_dp) then
      runoff = runoff + ((f1 * lid_getDrainFlow(j_l, PREVIOUS)) + (f_l * lid_getDrainFlow(j_l, CURRENT)))
   end if
   if (runoff < (2.31481e-08_dp * Subcatch(j_l)%area)) then
      runoff = 0.0_dp
   end if
   x_l(SUBCATCH_RUNOFF) = real(runoff * UCF(FLOW), sp)
   gw_l => Subcatch(j_l)%groundwater
   if (associated(gw_l)) then
      z_l = (((f1 * gw_l%oldFlow) + (f_l * gw_l%newFlow)) * Subcatch(j_l)%area) * UCF(FLOW)
      x_l(SUBCATCH_GW_FLOW) = real(z_l, sp)
      z_l = (gw_l%bottomElev + gw_l%lowerDepth) * UCF(LENGTH)
      x_l(SUBCATCH_GW_ELEV) = real(z_l, sp)
      z_l = gw_l%theta
      x_l(SUBCATCH_SOIL_MOIST) = real(z_l, sp)
   else
      x_l(SUBCATCH_GW_FLOW) = 0.0_sp
      x_l(SUBCATCH_GW_ELEV) = 0.0_sp
      x_l(SUBCATCH_SOIL_MOIST) = 0.0_sp
   end if
   if (.not. (IgnoreQuality /= 0)) then
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         if (runoff == 0.0_dp) then
            z_l = 0.0_dp
         else
            z_l = (f1 * Subcatch(j_l)%oldQual(p_l)) + (f_l * Subcatch(j_l)%newQual(p_l))
         end if
         x_l(SUBCATCH_WASHOFF + p_l) = real(z_l, sp)
         p_l = p_l + 1
      end do
   end if
end subroutine subcatch_getResults

! subcatch.c:907
recursive function getSubareaRunoff(j_l, i_l, area_l, precip, evap_l, tStep) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: i_l
   real(dp), value :: area_l
   real(dp), value :: precip
   real(dp), value :: evap_l
   real(dp), value :: tStep
   real(dp) :: res_
   real(dp), target :: tRunoff
   real(dp) :: surfMoisture
   real(dp) :: surfEvap
   real(dp) :: infil_l
   real(dp) :: runoff
   type(TSubarea), pointer :: subarea
   res_ = 0.0_dp
   tRunoff = 0.0_dp
   surfMoisture = 0.0_dp
   surfEvap = 0.0_dp
   infil_l = 0.0_dp
   runoff = 0.0_dp
   nullify(subarea)
   if (area_l == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   subarea => Subcatch(j_l)%subArea(i_l)
   tRunoff = tStep
   surfMoisture = subarea%depth / tStep
   surfEvap = merge(surfMoisture, evap_l, (surfMoisture) <= (evap_l))
   if (i_l == PERV) then
      infil_l = getSubareaInfil(j_l, subarea, precip, tStep)
   end if
   subarea%inflow = subarea%inflow + precip
   surfMoisture = surfMoisture + subarea%inflow
   Vinflow = Vinflow + ((precip * area_l) * tStep)
   Vevap = Vevap + ((surfEvap * area_l) * tStep)
   if (i_l == PERV) then
      Vpevap = Vpevap + Vevap
   end if
   Vinfil = Vinfil + ((infil_l * area_l) * tStep)
   Alpha = subarea%alpha
   Dstore = subarea%dStore
   call adjustSubareaParams(i_l, j_l)
   if ((surfEvap + infil_l) >= surfMoisture) then
      subarea%depth = 0.0_dp
   else
      subarea%inflow = subarea%inflow - (surfEvap + infil_l)
      call updatePondedDepth(subarea, tRunoff)
   end if
   runoff = findSubareaRunoff(subarea, tRunoff)
   Voutflow = Voutflow + (((subarea%fOutlet * runoff) * area_l) * tStep)
   res_ = runoff
   return
end function getSubareaRunoff

! subcatch.c:985
recursive function getSubareaInfil(j_l, subarea, precip, tStep) result(res_)
   integer(int32), value :: j_l
   type(TSubarea), pointer, intent(in) :: subarea
   real(dp), value :: precip
   real(dp), value :: tStep
   real(dp) :: res_
   real(dp) :: infil_l
   logical :: b1_
   real(dp) :: v2_
   res_ = 0.0_dp
   infil_l = 0.0_dp
   infil_l = infil_getInfil(j_l, tStep, precip, subarea%inflow, subarea%depth)
   b1_ = .not. (IgnoreGwater /= 0)
   if (b1_) then
      b1_ = associated(Subcatch(j_l)%groundwater)
   end if
   if (b1_) then
      if ((infil_l) <= (Subcatch(j_l)%groundwater%maxInfilVol / tStep)) then
         v2_ = infil_l
      else
         v2_ = Subcatch(j_l)%groundwater%maxInfilVol / tStep
      end if
      infil_l = v2_
   end if
   res_ = infil_l
   return
end function getSubareaInfil

! subcatch.c:1013
recursive function findSubareaRunoff(subarea, tRunoff) result(res_)
   type(TSubarea), pointer, intent(in) :: subarea
   real(dp), value :: tRunoff
   real(dp) :: res_
   real(dp) :: xDepth
   real(dp) :: runoff
   res_ = 0.0_dp
   xDepth = subarea%depth - Dstore
   runoff = 0.0_dp
   if (xDepth > 1.0e-10_dp) then
      if (subarea%N > 0.0_dp) then
         runoff = Alpha * (xDepth ** MEXP)
      else
         runoff = xDepth / tRunoff
         subarea%depth = Dstore
      end if
   else
      runoff = 0.0_dp
   end if
   res_ = runoff
   return
end function findSubareaRunoff

! subcatch.c:1048
recursive subroutine updatePondedDepth(subarea, dt_l)
   type(TSubarea), pointer, intent(in) :: subarea
   real(dp), intent(inout), target :: dt_l
   real(dp) :: ix
   real(dp) :: dx
   real(dp) :: tx
   real(dp), target :: a1_(0:0)
   integer(int32) :: dum2_
   ix = subarea%inflow
   dx = 0.0_dp
   tx = dt_l
   if ((subarea%depth + (ix * tx)) <= Dstore) then
      subarea%depth = subarea%depth + (ix * tx)
   else
      dx = Dstore - subarea%depth
      if ((dx > 0.0_dp) .and. (ix > 0.0_dp)) then
         tx = tx - (dx / ix)
         subarea%depth = Dstore
      end if
      if ((Alpha > 0.0_dp) .and. (tx > 0.0_dp)) then
         theSubarea => subarea
         a1_(0) = subarea%depth
         dum2_ = odesolve_integrate(a1_, 1, 0.0_dp, tx, ODETOL, tx, getDdDt)
         subarea%depth = a1_(0)
      else
         if (tx < 0.0_dp) then
            tx = 0.0_dp
         end if
         subarea%depth = subarea%depth + (ix * tx)
      end if
   end if
   if (subarea%depth < 0.0_dp) then
      subarea%depth = 0.0_dp
   end if
   dt_l = tx
end subroutine updatePondedDepth

! subcatch.c:1101
recursive subroutine getDdDt(t_l, d_l, dddt)
   real(dp), value :: t_l
   real(dp), pointer, intent(in) :: d_l(:)
   real(dp), pointer, intent(in) :: dddt(:)
   real(dp) :: ix
   real(dp) :: rx
   ix = theSubarea%inflow
   rx = d_l(0) - Dstore
   if (rx < 0.0_dp) then
      rx = 0.0_dp
   else
      rx = Alpha * (rx ** MEXP)
   end if
   dddt(0) = ix - rx
end subroutine getDdDt

! subcatch.c:1125
recursive subroutine adjustSubareaParams(i_l, j_l)
   integer(int32), value :: i_l
   integer(int32), value :: j_l
   integer(int32) :: p_l
   integer(int32) :: m_l
   real(dp) :: f_l
   logical :: b1_
   logical :: b2_
   p_l = 0
   m_l = 0
   f_l = 0.0_dp
   if (i_l == PERV) then
      p_l = Subcatch(j_l)%dStorePattern
      b1_ = p_l >= 0
      if (b1_) then
         b1_ = Pattern(p_l)%type == MONTHLY_PATTERN
      end if
      if (b1_) then
         m_l = datetime_monthOfYear(getDateTime(OldRunoffTime)) - 1
         f_l = Pattern(p_l)%factor(m_l)
         if (f_l >= 0.0_dp) then
            Dstore = Dstore * f_l
         end if
      end if
      p_l = Subcatch(j_l)%nPervPattern
      b2_ = p_l >= 0
      if (b2_) then
         b2_ = Pattern(p_l)%type == MONTHLY_PATTERN
      end if
      if (b2_) then
         m_l = datetime_monthOfYear(getDateTime(OldRunoffTime)) - 1
         f_l = Pattern(p_l)%factor(m_l)
         if (f_l <= 0.0_dp) then
            Alpha = 0.0_dp
         else
            Alpha = Alpha / f_l
         end if
      end if
   end if
end subroutine adjustSubareaParams

! surfqual.c:65
recursive subroutine surfqual_initState(j_l)
   integer(int32), value :: j_l
   integer(int32) :: p_l
   p_l = 0
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      Subcatch(j_l)%oldQual(p_l) = 0.0_dp
      Subcatch(j_l)%newQual(p_l) = 0.0_dp
      Subcatch(j_l)%pondedQual(p_l) = 0.0_dp
      p_l = p_l + 1
   end do
   call landuse_getInitBuildup(Subcatch(j_l)%landFactor, Subcatch(j_l)%initBuildup, Subcatch(j_l)%area, Subcatch(j_l)%curbLength)
end subroutine surfqual_initState

! surfqual.c:89
recursive subroutine surfqual_getBuildup(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   integer(int32) :: i_l
   integer(int32) :: p_l
   real(dp) :: f_l
   real(dp) :: area_l
   real(dp) :: curb
   real(dp) :: oldBuildup
   real(dp) :: newBuildup
   logical :: b1_
   i_l = 0
   p_l = 0
   f_l = 0.0_dp
   area_l = 0.0_dp
   curb = 0.0_dp
   oldBuildup = 0.0_dp
   newBuildup = 0.0_dp
   i_l = 0
   do while (i_l < Nobjects(LANDUSE_c))
      f_l = Subcatch(j_l)%landFactor(i_l)%fraction
      if (f_l == 0.0_dp) then
         goto 100
      end if
      area_l = (f_l * Subcatch(j_l)%area) * UCF(LANDAREA)
      curb = f_l * Subcatch(j_l)%curbLength
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         b1_ = Pollut(p_l)%snowOnly /= 0
         if (b1_) then
            b1_ = Subcatch(j_l)%newSnowDepth < (0.001_dp / 12.0_dp)
         end if
         if (b1_) then
            goto 101
         end if
         oldBuildup = Subcatch(j_l)%landFactor(i_l)%buildup(p_l)
         newBuildup = landuse_getBuildup(i_l, p_l, area_l, curb, oldBuildup, tStep)
         newBuildup = merge(newBuildup, oldBuildup, (newBuildup) >= (oldBuildup))
         Subcatch(j_l)%landFactor(i_l)%buildup(p_l) = newBuildup
         call massbal_updateLoadingTotals(BUILDUP_LOAD, p_l, newBuildup - oldBuildup)
         101 continue
         p_l = p_l + 1
      end do
      100 continue
      i_l = i_l + 1
   end do
end subroutine surfqual_getBuildup

! surfqual.c:137
recursive subroutine surfqual_sweepBuildup(j_l, aDate)
   integer(int32), value :: j_l
   real(dp), value :: aDate
   integer(int32) :: i_l
   integer(int32) :: p_l
   real(dp) :: oldBuildup
   real(dp) :: newBuildup
   logical :: b1_
   i_l = 0
   p_l = 0
   oldBuildup = 0.0_dp
   newBuildup = 0.0_dp
   b1_ = .not. (.not. associated(Subcatch(j_l)%snowpack))
   if (b1_) then
      b1_ = Subcatch(j_l)%snowpack%wsnow(IMPERV0) > 0.004167_dp
   end if
   if (b1_) then
      return
   end if
   i_l = 0
   do while (i_l < Nobjects(LANDUSE_c))
      if (Subcatch(j_l)%landFactor(i_l)%fraction == 0.0_dp) then
         goto 100
      end if
      if (Landuse(i_l)%sweepInterval == 0.0_dp) then
         goto 100
      end if
      if ((aDate - Subcatch(j_l)%landFactor(i_l)%lastSwept) >= Landuse(i_l)%sweepInterval) then
         Subcatch(j_l)%landFactor(i_l)%lastSwept = aDate
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            oldBuildup = Subcatch(j_l)%landFactor(i_l)%buildup(p_l)
            newBuildup = oldBuildup * (1.0_dp - (Landuse(i_l)%sweepRemoval * Landuse(i_l)%washoffFunc(p_l)%sweepEffic))
            newBuildup = merge(oldBuildup, newBuildup, (oldBuildup) <= (newBuildup))
            newBuildup = merge(0.0_dp, newBuildup, (0.0_dp) >= (newBuildup))
            Subcatch(j_l)%landFactor(i_l)%buildup(p_l) = newBuildup
            call massbal_updateLoadingTotals(SWEEPING_LOAD, p_l, oldBuildup - newBuildup)
            p_l = p_l + 1
         end do
      end if
      100 continue
      i_l = i_l + 1
   end do
end subroutine surfqual_sweepBuildup

! surfqual.c:192
recursive subroutine surfqual_getWashoff(j_l, runoff, tStep)
   integer(int32), value :: j_l
   real(dp), value :: runoff
   real(dp), value :: tStep
   integer(int32) :: p_l
   integer(int32) :: hasOutflow
   real(dp) :: cOut
   real(dp) :: massLoad
   real(dp) :: vLidRain
   real(dp) :: vLidRunon
   real(dp) :: vSurfOut
   real(dp) :: vOut1
   real(dp) :: vOut2
   real(dp) :: area_l
   logical :: b1_
   p_l = 0
   hasOutflow = 0
   cOut = 0.0_dp
   massLoad = 0.0_dp
   vLidRain = 0.0_dp
   vLidRunon = 0.0_dp
   vSurfOut = 0.0_dp
   vOut1 = 0.0_dp
   vOut2 = 0.0_dp
   area_l = 0.0_dp
   area_l = Subcatch(j_l)%area
   if ((Nobjects(POLLUT_c) == 0) .or. (area_l == 0.0_dp)) then
      return
   end if
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      OutflowLoad(p_l) = 0.0_dp
      p_l = p_l + 1
   end do
   call findWashoffLoads(j_l, runoff)
   call findPondedLoads(j_l, tStep)
   call findLidLoads(j_l, tStep)
   vLidRain = (Subcatch(j_l)%rainfall * Subcatch(j_l)%lidArea) * tStep
   vLidRunon = 0.0_dp
   if (area_l == Subcatch(j_l)%lidArea) then
      vLidRunon = (Subcatch(j_l)%runon * area_l) * tStep
   end if
   vOut1 = (Voutflow + vLidRain) + vLidRunon
   vSurfOut = Subcatch(j_l)%newRunoff * tStep
   vOut2 = vSurfOut + VlidDrain
   hasOutflow = merge(1, 0, vOut2 > ((2.31481e-08_dp * area_l) * tStep))
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      cOut = 0.0_dp
      if ((vOut1 > 0.0_dp) .and. (hasOutflow /= 0)) then
         cOut = OutflowLoad(p_l) / vOut1
      end if
      if (Subcatch(j_l)%lidArea > 0.0_dp) then
         massLoad = (cOut * (vOut1 - vOut2)) * Pollut(p_l)%mcf
         if (massLoad > 0.0_dp) then
            call massbal_updateLoadingTotals(BMP_REMOVAL_LOAD, p_l, massLoad)
         end if
      end if
      massLoad = (cOut * vOut2) * Pollut(p_l)%mcf
      Subcatch(j_l)%totalLoad(p_l) = Subcatch(j_l)%totalLoad(p_l) + massLoad
      b1_ = Subcatch(j_l)%outNode >= 0
      if (.not. b1_) then
         b1_ = Subcatch(j_l)%outSubcatch == j_l
      end if
      if (b1_) then
         massLoad = (cOut * vSurfOut) * Pollut(p_l)%mcf
         call massbal_updateLoadingTotals(RUNOFF_LOAD, p_l, massLoad)
      end if
      Subcatch(j_l)%newQual(p_l) = cOut / 28.317_dp
      p_l = p_l + 1
   end do
   if (Subcatch(j_l)%lidArea > 0.0_dp) then
      call lid_addDrainLoads(j_l, Subcatch(j_l)%newQual, tStep)
   end if
end subroutine surfqual_getWashoff

! surfqual.c:298
recursive function surfqual_getWtdWashoff(j_l, p_l, f_l) result(res_)
   integer(int32), value :: j_l
   integer(int32), value :: p_l
   real(dp), value :: f_l
   real(dp) :: res_
   res_ = 0.0_dp
   res_ = (((1.0_dp - f_l) * Subcatch(j_l)%oldRunoff) * Subcatch(j_l)%oldQual(p_l)) + ((f_l * Subcatch(j_l)%newRunoff) * Subcatch(j_l)%newQual(p_l))
   return
end function surfqual_getWtdWashoff

! surfqual.c:313
recursive subroutine findPondedLoads(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   integer(int32) :: p_l
   real(dp) :: cPonded
   real(dp) :: wPonded
   real(dp) :: bmpRemoval
   real(dp) :: vRain
   real(dp) :: wRain
   real(dp) :: wRunon
   real(dp) :: wInfil
   real(dp) :: wOutflow
   real(dp) :: fullArea
   real(dp) :: nonLidArea
   p_l = 0
   cPonded = 0.0_dp
   wPonded = 0.0_dp
   bmpRemoval = 0.0_dp
   vRain = 0.0_dp
   wRain = 0.0_dp
   wRunon = 0.0_dp
   wInfil = 0.0_dp
   wOutflow = 0.0_dp
   fullArea = 0.0_dp
   nonLidArea = 0.0_dp
   if (Subcatch(j_l)%area == Subcatch(j_l)%lidArea) then
      return
   end if
   fullArea = Subcatch(j_l)%area
   nonLidArea = fullArea - Subcatch(j_l)%lidArea
   vRain = (Subcatch(j_l)%rainfall * nonLidArea) * tStep
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      wRain = (Pollut(p_l)%pptConcen * 28.317_dp) * vRain
      call massbal_updateLoadingTotals(DEPOSITION_LOAD, p_l, wRain * Pollut(p_l)%mcf)
      if (Vinflow == 0.0_dp) then
         call massbal_updateLoadingTotals(FINAL_LOAD, p_l, Subcatch(j_l)%pondedQual(p_l) * Pollut(p_l)%mcf)
         Subcatch(j_l)%pondedQual(p_l) = 0.0_dp
      else
         wRunon = Subcatch(j_l)%newQual(p_l) * tStep
         wPonded = (Subcatch(j_l)%pondedQual(p_l) + wRain) + wRunon
         cPonded = wPonded / Vinflow
         wInfil = cPonded * Vinfil
         wInfil = merge(wInfil, wPonded, (wInfil) <= (wPonded))
         call massbal_updateLoadingTotals(INFIL_LOAD, p_l, wInfil * Pollut(p_l)%mcf)
         wPonded = wPonded - wInfil
         wOutflow = cPonded * Voutflow
         wOutflow = merge(wOutflow, wPonded, (wOutflow) <= (wPonded))
         wPonded = wPonded - wOutflow
         bmpRemoval = landuse_getAvgBmpEffic(j_l, p_l) * wOutflow
         call massbal_updateLoadingTotals(BMP_REMOVAL_LOAD, p_l, bmpRemoval * Pollut(p_l)%mcf)
         wOutflow = wOutflow - bmpRemoval
         Subcatch(j_l)%pondedQual(p_l) = (cPonded * subcatch_getDepth(j_l)) * nonLidArea
         OutflowLoad(p_l) = OutflowLoad(p_l) + wOutflow
      end if
      p_l = p_l + 1
   end do
end subroutine findPondedLoads

! surfqual.c:390
recursive subroutine findWashoffLoads(j_l, runoff)
   integer(int32), value :: j_l
   real(dp), value :: runoff
   integer(int32) :: i_l
   integer(int32) :: p_l
   integer(int32) :: k_l
   real(dp) :: w_l
   real(dp) :: area_l
   i_l = 0
   p_l = 0
   k_l = 0
   w_l = 0.0_dp
   area_l = Subcatch(j_l)%area
   if (runoff < 2.31481e-08_dp) then
      return
   end if
   i_l = 0
   do while (i_l < Nobjects(LANDUSE_c))
      if (Subcatch(j_l)%landFactor(i_l)%fraction > 0.0_dp) then
         p_l = 0
         do while (p_l < Nobjects(POLLUT_c))
            OutflowLoad(p_l) = OutflowLoad(p_l) + landuse_getWashoffLoad(i_l, p_l, area_l, Subcatch(j_l)%landFactor, runoff, Voutflow)
            p_l = p_l + 1
         end do
      end if
      i_l = i_l + 1
   end do
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      k_l = Pollut(p_l)%coPollut
      if (k_l >= 0) then
         w_l = Pollut(p_l)%coFraction * OutflowLoad(k_l)
         call massbal_updateLoadingTotals(BUILDUP_LOAD, p_l, w_l * Pollut(p_l)%mcf)
         OutflowLoad(p_l) = OutflowLoad(p_l) + w_l
      end if
      p_l = p_l + 1
   end do
end subroutine findWashoffLoads

! surfqual.c:443
recursive subroutine findLidLoads(j_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: tStep
   integer(int32) :: p_l
   integer(int32) :: useRunon
   real(dp) :: lidArea
   real(dp) :: vLidRain
   real(dp) :: wLidRain
   real(dp) :: wLidRunon
   p_l = 0
   useRunon = 0
   lidArea = 0.0_dp
   vLidRain = 0.0_dp
   wLidRain = 0.0_dp
   wLidRunon = 0.0_dp
   lidArea = Subcatch(j_l)%lidArea
   if (lidArea == 0.0_dp) then
      return
   end if
   vLidRain = (Subcatch(j_l)%rainfall * lidArea) * tStep
   useRunon = merge(1, 0, lidArea == Subcatch(j_l)%area)
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      wLidRain = (Pollut(p_l)%pptConcen * vLidRain) * 28.317_dp
      call massbal_updateLoadingTotals(DEPOSITION_LOAD, p_l, wLidRain * Pollut(p_l)%mcf)
      if (useRunon /= 0) then
         wLidRunon = Subcatch(j_l)%newQual(p_l) * tStep
      else
         wLidRunon = 0.0_dp
      end if
      OutflowLoad(p_l) = OutflowLoad(p_l) + (wLidRain + wLidRunon)
      p_l = p_l + 1
   end do
end subroutine findLidLoads

! swmm5.c:186
recursive function swmm_run(f1, f2, f3) result(res_)
   type(CPtr), value :: f1
   type(CPtr), value :: f2
   type(CPtr), value :: f3
   integer(int32) :: res_
   integer(int64) :: newHour
   integer(int64) :: oldHour
   integer(int64) :: theDay
   integer(int64) :: theHour
   real(dp), target :: elapsedTime_l
   integer(int32) :: dum1_
   res_ = 0
   newHour = 0_int64
   oldHour = 0_int64
   theDay = 0_int64
   theHour = 0_int64
   elapsedTime_l = 0.0_dp
   IsOpenFlag = 0
   IsStartedFlag = 0
   SaveResultsFlag = 1
   ErrorCode = 0
   call writecon(lit_642)
   dum1_ = swmm_open(f1, f2, f3)
   if (.not. (ErrorCode /= 0)) then
      dum1_ = swmm_start(1)
      if (.not. (ErrorCode /= 0)) then
         call writecon(lit_643)
         do
            dum1_ = swmm_step(elapsedTime_l)
            newHour = d2l(elapsedTime_l * 24.0_dp)
            if (newHour > oldHour) then
               theDay = d2l(elapsedTime_l)
               theHour = d2l((elapsedTime_l - cfloor(elapsedTime_l)) * 24.0_dp)
               call writecon(lit_644)
               dum1_ = c_snprintf(cview(Msg), 1024_int64, lit_645, theDay, theHour)
               call writecon(cview(Msg))
               oldHour = newHour
            end if
            if (.not. ((elapsedTime_l > 0.0_dp) .and. (.not. (ErrorCode /= 0)))) exit
         end do
         call writecon(lit_646)
         call writecon(lit_647)
      end if
      dum1_ = swmm_end()
   end if
   if ((.not. (ErrorCode /= 0)) .and. (Fout%mode == SCRATCH_FILE)) then
      call writecon(lit_648)
      dum1_ = swmm_report()
   end if
   dum1_ = swmm_close()
   res_ = ErrorCode
   return
end function swmm_run

