! swmm5.c:314
recursive function swmm_start(saveResults_l) result(res_)
   integer(int32), value :: saveResults_l
   integer(int32) :: res_
   integer(int32) :: dum1_
   res_ = 0
   if (ErrorCode /= 0) then
      res_ = ErrorCode
      return
   end if
   if (.not. (IsOpenFlag /= 0)) then
      ErrorCode = ERR_API_NOT_OPEN
      res_ = ErrorCode
      return
   end if
   if (IsStartedFlag /= 0) then
      ErrorCode = ERR_API_NOT_ENDED
      res_ = ErrorCode
      return
   end if
   if (.not. (RptFlags%disabled /= 0)) then
      if (RptFlags%input /= 0) then
         call inputrpt_writeInput()
      end if
      call report_writeOptions()
   end if
   SaveResultsFlag = saveResults_l
   ExceptionCount = 0
   ElapsedTime = 0.0_dp
   RoutingDuration = TotalDuration
   NewRunoffTime = 0.0_dp
   NewRoutingTime = 0.0_dp
   ReportTime = 1000.0_dp * real(ReportStep, dp)
   TotalStepCount = 0_int64
   ReportStepCount = 0_int64
   NonConvergeCount = 0_int64
   IsStartedFlag = 1
   RunoffError = 0.0_dp
   GwaterError = 0.0_dp
   FlowError = 0.0_dp
   QualError = 0.0_dp
   if (.not. (IgnoreRainfall /= 0)) then
      call rain_open()
   end if
   if (ErrorCode /= 0) then
      res_ = ErrorCode
      return
   end if
   dum1_ = project_init()
   if (Nobjects(SUBCATCH_c) > 0) then
      DoRunoff = 1
   else
      DoRunoff = 0
   end if
   if ((Nobjects(NODE_c) > 0) .and. (.not. (IgnoreRouting /= 0))) then
      DoRouting = 1
   else
      DoRouting = 0
   end if
   dum1_ = output_open()
   if (DoRunoff /= 0) then
      dum1_ = runoff_open()
   end if
   if (.not. (hotstart_open() /= 0)) then
      res_ = ErrorCode
      return
   end if
   if (DoRouting /= 0) then
      dum1_ = routing_open()
   end if
   dum1_ = massbal_open()
   dum1_ = stats_open()
   if ((.not. (RptFlags%disabled /= 0)) .and. (RptFlags%controls /= 0)) then
      call report_writeControlActionsHeading()
   end if
   res_ = ErrorCode
   return
end function swmm_start

! swmm5.c:410
recursive function swmm_step(elapsedTime_l) result(res_)
   real(dp), intent(inout), target :: elapsedTime_l
   integer(int32) :: res_
   res_ = 0
   elapsedTime_l = 0.0_dp
   if (ErrorCode /= 0) then
      res_ = ErrorCode
      return
   end if
   if (.not. (IsOpenFlag /= 0)) then
      ErrorCode = ERR_API_NOT_OPEN
      res_ = ErrorCode
      return
   end if
   if (.not. (IsStartedFlag /= 0)) then
      ErrorCode = ERR_API_NOT_STARTED
      res_ = ErrorCode
      return
   end if
   if (NewRoutingTime < RoutingDuration) then
      call execRouting()
   end if
   if (SaveResultsFlag /= 0) then
      call saveResults()
   end if
   if (NewRoutingTime < RoutingDuration) then
      ElapsedTime = NewRoutingTime / 86400000.0_dp
   else
      ElapsedTime = 0.0_dp
   end if
   elapsedTime_l = ElapsedTime
   res_ = ErrorCode
   return
end function swmm_step

! swmm5.c:466
recursive function swmm_stride(strideStep, elapsedTime_l) result(res_)
   integer(int32), value :: strideStep
   real(dp), intent(inout), target :: elapsedTime_l
   integer(int32) :: res_
   real(dp) :: realRouteStep
   integer(int32) :: dum1_
   res_ = 0
   realRouteStep = RouteStep
   elapsedTime_l = 0.0_dp
   if (ErrorCode /= 0) then
      res_ = ErrorCode
      return
   end if
   if (.not. (IsOpenFlag /= 0)) then
      ErrorCode = ERR_API_NOT_OPEN
      res_ = ErrorCode
      return
   end if
   if (.not. (IsStartedFlag /= 0)) then
      ErrorCode = ERR_API_NOT_STARTED
      res_ = ErrorCode
      return
   end if
   RoutingDuration = NewRoutingTime + (1000.0_dp * real(strideStep, dp))
   RoutingDuration = merge(TotalDuration, RoutingDuration, (TotalDuration) <= (RoutingDuration))
   if (real(strideStep, dp) < RouteStep) then
      RouteStep = real(strideStep, dp)
   end if
   do
      dum1_ = swmm_step(elapsedTime_l)
      if (.not. ((elapsedTime_l > 0.0_dp) .and. (.not. (ErrorCode /= 0)))) exit
   end do
   RouteStep = realRouteStep
   RoutingDuration = TotalDuration
   if (NewRoutingTime < TotalDuration) then
      ElapsedTime = NewRoutingTime / 86400000.0_dp
   else
      ElapsedTime = 0.0_dp
   end if
   elapsedTime_l = ElapsedTime
   res_ = ErrorCode
   return
end function swmm_stride

! swmm5.c:514
recursive subroutine execRouting()
   real(dp) :: nextRoutingTime
   real(dp) :: routingStep
   nextRoutingTime = 0.0_dp
   routingStep = 0.0_dp
   TotalStepCount = TotalStepCount + 1_int64
   if (.not. (DoRouting /= 0)) then
      routingStep = real(merge(WetStep, ReportStep, (WetStep) <= (ReportStep)), dp)
   else
      routingStep = routing_getRoutingStep(RouteModel, RouteStep)
   end if
   if (routingStep <= 0.0_dp) then
      ErrorCode = ERR_TIMESTEP
      return
   end if
   nextRoutingTime = NewRoutingTime + (1000.0_dp * routingStep)
   if (nextRoutingTime > RoutingDuration) then
      routingStep = (RoutingDuration - NewRoutingTime) / 1000.0_dp
      routingStep = merge(routingStep, 1.0_dp / 1000.0_dp, (routingStep) >= (1.0_dp / 1000.0_dp))
      nextRoutingTime = RoutingDuration
   end if
   if (DoRunoff /= 0) then
      do while (NewRunoffTime < nextRoutingTime)
         call runoff_execute()
         if (ErrorCode /= 0) then
            return
         end if
      end do
   else
      call climate_setState(getDateTime(NewRoutingTime))
   end if
   if (DoRouting /= 0) then
      call routing_execute(RouteModel, routingStep)
   else
      NewRoutingTime = nextRoutingTime
   end if
end subroutine execRouting

! swmm5.c:579
recursive subroutine saveResults()
   if (NewRoutingTime >= ReportTime) then
      if (RptFlags%averages /= 0) then
         if (NewRoutingTime == ReportTime) then
            call output_updateAvgResults()
         end if
         call output_saveResults(ReportTime)
         if (NewRoutingTime > ReportTime) then
            call output_updateAvgResults()
         end if
      else
         call output_saveResults(ReportTime)
      end if
      ReportTime = ReportTime + (1000.0_dp * real(ReportStep, dp))
   else if (RptFlags%averages /= 0) then
      call output_updateAvgResults()
   end if
end subroutine saveResults

! swmm5.c:618
recursive function swmm_end() result(res_)
   integer(int32) :: res_
   res_ = 0
   if (.not. (IsOpenFlag /= 0)) then
      ErrorCode = ERR_API_NOT_OPEN
      res_ = ErrorCode
      return
   end if
   if (IsStartedFlag /= 0) then
      if (associated(Fout%file)) then
         call output_end()
      end if
      if ((.not. (ErrorCode /= 0)) .and. (RptFlags%disabled == 0)) then
         call massbal_report()
         call stats_report()
      end if
      call stats_close()
      call massbal_close()
      if (.not. (IgnoreRainfall /= 0)) then
         call rain_close()
      end if
      if (DoRunoff /= 0) then
         call runoff_close()
      end if
      if (DoRouting /= 0) then
         call routing_close(RouteModel)
      end if
      call hotstart_close()
      IsStartedFlag = 0
   end if
   res_ = ErrorCode
   return
end function swmm_end

