   end if
   call report_writeSysTime()
   if (.not. (.not. associated(Finp%file))) then
      dum1_ = c_fclose(Finp%file)
   end if
   if (.not. (.not. associated(Frpt%file))) then
      dum1_ = c_fclose(Frpt%file)
