   if (.not. (.not. associated(Fout%file))) then
      dum1_ = c_fclose(Fout%file)
      if (Fout%mode == SCRATCH_FILE) then
         dum1_ = c_remove(cview(Fout%name))
      end if
   end if
   IsOpenFlag = 0
   IsStartedFlag = 0
   res_ = 0
   return
end function swmm_close

