! swmm5.c:867
recursive subroutine swmm_setValue(property, index_l, value_l)
   integer(int32), value :: property
   integer(int32), value :: index_l
   real(dp), value :: value_l
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   if (.not. (IsOpenFlag /= 0)) then
      return
   end if
   select case (property)
   case (100)
      b1_ = index_l < 0
      if (.not. b1_) then
         b1_ = index_l >= Nobjects(GAGE_c)
      end if
      if (b1_) then
         return
      end if
      if (value_l >= 0.0_dp) then
         Gage(index_l)%apiRainfall = value_l
      end if
      return
   case (206)
      b2_ = (.not. (IsStartedFlag /= 0)) .and. (index_l >= 0)
      if (b2_) then
         b2_ = index_l < Nobjects(SUBCATCH_c)
      end if
      if (b2_) then
         Subcatch(index_l)%rptFlag = merge(1, 0, value_l > 0.0_dp)
      end if
      return
   case (306)
      call setNodeLatFlow(index_l, value_l)
      return
   case (304)
      call setOutfallStage(index_l, value_l)
      return
   case (309)
      b3_ = (.not. (IsStartedFlag /= 0)) .and. (index_l >= 0)
      if (b3_) then
         b3_ = index_l < Nobjects(NODE_c)
      end if
      if (b3_) then
         Node(index_l)%rptFlag = merge(1, 0, value_l > 0.0_dp)
      end if
      return
   case (407)
      call setLinkSetting(index_l, value_l)
      return
   case (414)
      b4_ = (.not. (IsStartedFlag /= 0)) .and. (index_l >= 0)
      if (b4_) then
         b4_ = index_l < Nobjects(LINK_c)
      end if
      if (b4_) then
         Link(index_l)%rptFlag = merge(1, 0, value_l > 0.0_dp)
      end if
      return
   case (3)
      call setRoutingStep(value_l)
      return
   case (5)
      if ((.not. (IsStartedFlag /= 0)) .and. (value_l > 0.0_dp)) then
         ReportStep = d2i(value_l)
      end if
      return
   case (7)
      if (.not. (IsStartedFlag /= 0)) then
         RptFlags%disabled = merge(1, 0, value_l > 0.0_dp)
      end if
      return
   end select
end subroutine swmm_setValue

! swmm5.c:922
recursive function swmm_getSavedValue(property, index_l, period) result(res_)
   integer(int32), value :: property
   integer(int32), value :: index_l
   integer(int32), value :: period
   real(dp) :: res_
   res_ = 0.0_dp
   if (.not. (IsOpenFlag /= 0)) then
      res_ = 0.0_dp
      return
   end if
   if (IsStartedFlag /= 0) then
      res_ = 0.0_dp
      return
   end if
   if ((period < 1) .or. (int(period, int64) > Nperiods)) then
      res_ = 0.0_dp
      return
   end if
   if (property == swmm_CURRENTDATE) then
      res_ = getSavedDate(period)
      return
   end if
   if ((property >= 200) .and. (property < 300)) then
      res_ = getSavedSubcatchValue(property, index_l, period)
      return
   end if
   if (property < 400) then
      res_ = getSavedNodeValue(property, index_l, period)
      return
   end if
   if (property < 500) then
      res_ = getSavedLinkValue(property, index_l, period)
      return
   end if
   res_ = 0.0_dp
   return
end function swmm_getSavedValue

