! swmm5.c:982
recursive function getSubcatchValue(property, index_l) result(res_)
   integer(int32), value :: property
   integer(int32), value :: index_l
   real(dp) :: res_
   type(TSubcatch), pointer :: subcatch_l
   logical :: b1_
   res_ = 0.0_dp
   nullify(subcatch_l)
   b1_ = index_l < 0
   if (.not. b1_) then
      b1_ = index_l >= Nobjects(SUBCATCH_c)
   end if
   if (b1_) then
      res_ = 0.0_dp
      return
   end if
   subcatch_l => Subcatch(index_l)
   select case (property)
   case (200)
      res_ = subcatch_l%area * UCF(LANDAREA)
      return
   case (201)
      res_ = real(subcatch_l%gage, dp)
      return
   case (202)
      if (subcatch_l%gage >= 0) then
         res_ = Gage(subcatch_l%gage)%reportRainfall
         return
      else
         res_ = 0.0_dp
         return
      end if
   case (203)
      res_ = subcatch_l%evapLoss * UCF(EVAPRATE)
      return
   case (204)
      res_ = subcatch_l%infilLoss * UCF(RAINFALL)
      return
   case (205)
      res_ = subcatch_l%newRunoff * UCF(FLOW)
      return
   case (206)
      res_ = merge(1.0_dp, 0.0_dp, subcatch_l%rptFlag > 0)
      return
   case default
      res_ = 0.0_dp
      return
   end select
end function getSubcatchValue

