! swmm5.c:1059
recursive function getLinkValue(property, index_l) result(res_)
   integer(int32), value :: property
   integer(int32), value :: index_l
   real(dp) :: res_
   type(TLink), pointer :: link_l
   logical :: b1_
   res_ = 0.0_dp
   nullify(link_l)
   b1_ = index_l < 0
   if (.not. b1_) then
      b1_ = index_l >= Nobjects(LINK_c)
   end if
   if (b1_) then
      res_ = 0.0_dp
      return
   end if
   link_l => Link(index_l)
   select case (property)
   case (400)
      res_ = real(link_l%type, dp)
      return
   case (401)
      res_ = real(link_l%node1, dp)
      return
   case (402)
      res_ = real(link_l%node2, dp)
      return
   case (403)
      if (link_l%type == CONDUIT_c) then
         res_ = Conduit(link_l%subIndex)%length * UCF(LENGTH)
         return
      else
         res_ = 0.0_dp
         return
      end if
   case (404)
      if (link_l%type == CONDUIT_c) then
         res_ = Conduit(link_l%subIndex)%slope
         return
      else
         res_ = 0.0_dp
         return
      end if
   case (405)
      res_ = link_l%xsect%yFull * UCF(LENGTH)
      return
   case (406)
      res_ = link_l%qFull * UCF(FLOW)
      return
   case (410)
      res_ = (link_l%newFlow * UCF(FLOW)) * real(link_l%direction, dp)
      return
   case (412)
      res_ = link_getVelocity(index_l, abs(link_l%newFlow), link_l%newDepth) * UCF(LENGTH)
      return
   case (411)
      res_ = link_l%newDepth * UCF(LENGTH)
      return
   case (413)
      if (link_l%type == CONDUIT_c) then
         res_ = xsect_getWofY(link_l%xsect, link_l%newDepth) * UCF(LENGTH)
         return
      else
         res_ = 0.0_dp
         return
      end if
   case (407)
      res_ = link_l%setting
      return
   case (408)
      if (link_l%setting > 0.0_dp) then
         res_ = (getDateTime(NewRoutingTime) - link_l%timeLastSet) * 24.0_dp
         return
      else
         res_ = 0.0_dp
         return
      end if
   case (409)
      if (link_l%setting == 0.0_dp) then
         res_ = (getDateTime(NewRoutingTime) - link_l%timeLastSet) * 24.0_dp
         return
      else
         res_ = 0.0_dp
         return
      end if
   case (414)
      res_ = merge(1.0_dp, 0.0_dp, link_l%rptFlag > 0)
      return
   case default
      res_ = 0.0_dp
      return
   end select
end function getLinkValue

