   logical :: b1_
   logical :: b2_
   nullify(link_l)
   b1_ = index_l < 0
   if (.not. b1_) then
      b1_ = index_l >= Nobjects(LINK_c)
   end if
   if (b1_) then
      return
   end if
   link_l => Link(index_l)
   b2_ = value_l < 0.0_dp
   if (.not. b2_) then
      b2_ = link_l%type == CONDUIT_c
   end if
   if (b2_) then
      return
   end if
   if ((link_l%type /= PUMP_c) .and. (value_l > 1.0_dp)) then
      value_l = 1.0_dp
   end if
   if (link_l%targetSetting == value_l) then
