   link_l%targetSetting = value_l
   if ((link_l%targetSetting * link_l%setting) == 0.0_dp) then
      link_l%timeLastSet = StartDateTime + ElapsedTime
   end if
   call link_setSetting(index_l, 0.0_dp)
