recursive function getMaxRouteStep() result(res_)
   real(dp) :: res_
   real(dp) :: tmpCourantFactor
   real(dp) :: result_l
   res_ = 0.0_dp
   tmpCourantFactor = CourantFactor
   result_l = RouteStep
   if ((.not. (IsStartedFlag /= 0)) .or. (RouteModel /= DW)) then
      res_ = result_l
      return
   end if
   CourantFactor = 1.0_dp
   result_l = routing_getRoutingStep(RouteModel, MinRouteStep)
   CourantFactor = tmpCourantFactor
   res_ = result_l
   return
end function getMaxRouteStep

