! swmm5.c:1453
recursive function strcomp(s1, s2) result(res_)
   type(CPtr), value :: s1
   type(CPtr), value :: s2
   integer(int32) :: res_
   integer(int32) :: i_l
   logical :: b1_
   integer(int32) :: v2_
   logical :: b3_
   integer(int32) :: v4_
   logical :: b5_
   res_ = 0
   i_l = 0
   i_l = 0
   do
      b1_ = (cget(s1, i_l)) >= 97
      if (b1_) then
         b1_ = (cget(s1, i_l)) <= 122
      end if
      if (b1_) then
         v2_ = iand(cget(s1, i_l), not(32))
      else
         v2_ = cget(s1, i_l)
      end if
      b3_ = (cget(s2, i_l)) >= 97
      if (b3_) then
         b3_ = (cget(s2, i_l)) <= 122
      end if
      if (b3_) then
         v4_ = iand(cget(s2, i_l), not(32))
      else
         v4_ = cget(s2, i_l)
      end if
      if (.not. ((v2_) == (v4_))) exit
      b5_ = .not. (cget(s1, i_l + 1) /= 0)
      if (b5_) then
         b5_ = .not. (cget(s2, i_l + 1) /= 0)
      end if
      if (b5_) then
         res_ = 1
         return
      end if
      i_l = i_l + 1
   end do
   res_ = 0
   return
end function strcomp

