recursive subroutine getElapsedTime(aDate, days_l, hrs, mins)
   real(dp), value :: aDate
   integer(int32), intent(inout), target :: days_l
   integer(int32), intent(inout), target :: hrs
   integer(int32), intent(inout), target :: mins
   real(dp) :: x_l
   integer(int32), target :: secs_l
   x_l = 0.0_dp
   secs_l = 0
   x_l = aDate - ReportStart
   if (x_l <= 0.0_dp) then
      days_l = 0
      hrs = 0
      mins = 0
   else
      days_l = d2i(x_l)
      call datetime_decodeTime(x_l, hrs, mins, secs_l)
   end if
end subroutine getElapsedTime

