recursive function isRelativePath(fname) result(res_)
   type(CPtr), value :: fname
   integer(int32) :: res_
   res_ = 0
   if (.not. cisnull(c_strchr(fname, 58))) then
      res_ = 0
      return
   end if
   if (cget(fname, 0) == 92) then
      res_ = 0
      return
   end if
   if (cget(fname, 0) == 47) then
      res_ = 0
      return
   end if
   res_ = 1
   return
end function isRelativePath

