   type(CPtr) :: res_
   integer(int64) :: n_l
   integer(int8), target :: buffer(0:258)
   integer(int64) :: dum1_
   res_ = cnull()
   n_l = 0_int64
   buffer = 0_int8
   if (isRelativePath(fname) /= 0) then
      n_l = int(c_snprintf(cview(buffer), 259_int64, lit_649, cview(InpDir), fname), int64)
      if (n_l > 0_int64) then
         dum1_ = sstrncpy(fname, cview(buffer), 259_int64)
      end if
   end if
   res_ = fname
