! table.c:51
recursive function table_interpolate(x_l, x1, y1, x2, y2) result(res_)
   real(dp), value :: x_l
   real(dp), value :: x1
   real(dp), value :: y1
   real(dp), value :: x2
   real(dp), value :: y2
   real(dp) :: res_
   real(dp) :: dx
   res_ = 0.0_dp
   dx = x2 - x1
   if (abs(dx) < 1.0e-20_dp) then
      res_ = (y1 + y2) / 2.0_dp
      return
   end if
   res_ = y1 + (((x_l - x1) * (y2 - y1)) / dx)
   return
end function table_interpolate

! table.c:67
recursive function table_readCurve(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: m_l
   integer(int32) :: k_l
   integer(int32) :: k1
   real(dp), target :: x_l
   real(dp), target :: y_l
   integer(int32) :: dum1_
   res_ = 0
   j_l = 0
   m_l = 0
   k_l = 0
   k1 = 1
   x_l = 0.0_dp
   y_l = 0.0_dp
   if (ntoks < 2) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(CURVE_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   if (cisnull(Curve(j_l)%ID)) then
      Curve(j_l)%ID = project_findID(CURVE_c, tok_l(0))
      m_l = findmatch(tok_l(1), CurveTypeWords)
      if (m_l < 0) then
         res_ = error_setInpError(ERR_KEYWORD, tok_l(1))
         return
      end if
      Curve(j_l)%curveType = m_l
      if (ntoks == 2) then
         res_ = 0
         return
      end if
      k1 = 2
   end if
   k_l = k1
   do while (k_l < ntoks)
      if ((k_l + 1) >= ntoks) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      if (.not. (getDouble(tok_l(k_l), x_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(k_l))
         return
      end if
      if (.not. (getDouble(tok_l(k_l + 1), y_l) /= 0)) then
         res_ = error_setInpError(ERR_NUMBER, tok_l(k_l + 1))
         return
      end if
      dum1_ = table_addEntry(Curve(j_l), x_l, y_l)
      k_l = k_l + 2
   end do
   res_ = 0
   return
end function table_readCurve

! table.c:113
recursive function table_readTimeseries(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: state
   real(dp) :: x_l
   real(dp), target :: y_l
   real(dp), target :: d_l
   real(dp), target :: t_l
   integer(int8), target :: fname(0:259)
   integer(int64) :: dum1_
   integer(int32) :: dum2_
   res_ = 0
   j_l = 0
   k_l = 0
   state = 0
   x_l = 0.0_dp
   y_l = 0.0_dp
   d_l = 0.0_dp
   t_l = 0.0_dp
   fname = 0_int8
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(TSERIES_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   if (cisnull(Tseries(j_l)%ID)) then
      Tseries(j_l)%ID = project_findID(TSERIES_c, tok_l(0))
   end if
   if (strcomp(tok_l(1), lit_1) /= 0) then
      dum1_ = sstrncpy(cview(fname), tok_l(2), 259_int64)
      dum1_ = sstrncpy(cview(Tseries(j_l)%file%name), addAbsolutePath(cview(fname)), 259_int64)
      Tseries(j_l)%file%mode = USE_FILE
      res_ = 0
      return
   end if
   x_l = 0.0_dp
   k_l = 1
   state = 1
   do while (k_l < ntoks)
      select case (state)
      case (1)
         if (datetime_strToDate(tok_l(k_l), d_l) /= 0) then
            Tseries(j_l)%lastDate = d_l
            k_l = k_l + 1
         end if
         state = 2
      case (2)
         if (k_l >= ntoks) then
            res_ = error_setInpError(ERR_ITEMS, lit_0)
            return
         end if
         if (getDouble(tok_l(k_l), t_l) /= 0) then
            t_l = t_l / 24.0_dp
         else if (.not. (datetime_strToTime(tok_l(k_l), t_l) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(k_l))
            return
         end if
         x_l = Tseries(j_l)%lastDate + t_l
         k_l = k_l + 1
         state = 3
      case (3)
         if (k_l >= ntoks) then
            res_ = error_setInpError(ERR_ITEMS, lit_0)
            return
         end if
         if (.not. (getDouble(tok_l(k_l), y_l) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(k_l))
            return
         end if
         dum2_ = table_addEntry(Tseries(j_l), x_l, y_l)
         k_l = k_l + 1
         state = 1
      end select
   end do
   res_ = 0
   return
end function table_readTimeseries

! table.c:208
recursive function table_addEntry(table, x_l, y_l) result(res_)
   type(TTable), pointer, intent(in) :: table
   real(dp), value :: x_l
   real(dp), value :: y_l
   integer(int32) :: res_
   type(TTableEntry), pointer :: entry_l
