      t_l = t_l / 24.0_dp
   else if (.not. (datetime_strToTime(tStr, t_l) /= 0)) then
      res_ = 0
      return
   end if
   if (.not. (getDouble(yStr, yy) /= 0)) then
      res_ = 0
      return
   end if
   x_l = d_l + t_l
   y_l = yy
   res_ = 1
   return
end function table_parseFileLine

! toposort.c:57
recursive subroutine toposort_sortLinks(sortedLinks_l)
   integer(int32), pointer, intent(in) :: sortedLinks_l(:)
   integer(int32) :: i_l
   integer(int32) :: n_l
   logical :: b1_
   i_l = 0
   n_l = 0
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      sortedLinks_l(i_l) = i_l
      i_l = i_l + 1
   end do
   if (RouteModel == DW) then
      call checkDummyLinks()
      if (ErrorCode /= 0) then
         return
      end if
      i_l = 0
      do while (i_l < Nobjects(NODE_c))
         Node(i_l)%degree = 0
         i_l = i_l + 1
      end do
      i_l = 0
      do while (i_l < Nobjects(LINK_c))
         n_l = Link(i_l)%node1
         if (Link(i_l)%direction < 0) then
            n_l = Link(i_l)%node2
         end if
         if (Node(n_l)%type == OUTFALL_c) then
            if (Link(i_l)%direction < 0) then
               n_l = Link(i_l)%node1
            else
               n_l = Link(i_l)%node2
            end if
            Node(n_l)%degree = Node(n_l)%degree + 1
         else
            Node(n_l)%degree = Node(n_l)%degree + 1
         end if
         i_l = i_l + 1
      end do
      return
   end if
   if (ErrorCode /= 0) then
      return
   end if
   allocate(InDegree(0:(int(Nobjects(NODE_c), int64)) - 1))
   InDegree = 0
   allocate(StartPos(0:(int(Nobjects(NODE_c), int64)) - 1))
   StartPos = 0
   allocate(AdjList(0:(int(Nobjects(LINK_c), int64)) - 1))
   AdjList = 0
   allocate(Stack(0:(int(Nobjects(NODE_c), int64)) - 1))
   Stack = 0
   if ((((.not. associated(InDegree)) .or. (.not. associated(StartPos))) .or. (.not. associated(AdjList))) .or. (.not. associated(Stack))) then
      call report_writeErrorMsg(ERR_MEMORY, lit_0)
   else
      call createAdjList(DIRECTED)
      call adjustAdjList()
      i_l = 0
      do while (i_l < Nobjects(NODE_c))
         InDegree(i_l) = 0
         i_l = i_l + 1
      end do
      i_l = 0
      do while (i_l < Nobjects(LINK_c))
         InDegree(Link(i_l)%node2) = InDegree(Link(i_l)%node2) + 1
         i_l = i_l + 1
      end do
      n_l = topoSort(sortedLinks_l)
   end if
   if (associated(InDegree)) then
      ! 
      nullify(InDegree)
   end if
   if (associated(StartPos)) then
      ! 
      nullify(StartPos)
   end if
   if (associated(AdjList)) then
      ! 
      nullify(AdjList)
   end if
   if (associated(Stack)) then
      ! 
      nullify(Stack)
   end if
   b1_ = .not. (ErrorCode /= 0)
   if (b1_) then
      b1_ = n_l /= Nobjects(LINK_c)
   end if
   if (b1_) then
      call report_writeErrorMsg(ERR_LOOP, lit_0)
      call findCycles()
   end if
end subroutine toposort_sortLinks

! toposort.c:142
recursive subroutine createAdjList(listType)
   integer(int32), value :: listType
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   i_l = 0
   j_l = 0
   k_l = 0
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      Node(i_l)%degree = 0
      i_l = i_l + 1
   end do
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      Node(Link(j_l)%node1)%degree = Node(Link(j_l)%node1)%degree + 1
      if (listType == UNDIRECTED) then
         Node(Link(j_l)%node2)%degree = Node(Link(j_l)%node2)%degree + 1
      end if
      j_l = j_l + 1
   end do
   StartPos(0) = 0
   i_l = 0
   do while (i_l < (Nobjects(NODE_c) - 1))
      StartPos(i_l + 1) = StartPos(i_l) + Node(i_l)%degree
      Node(i_l)%degree = 0
      i_l = i_l + 1
   end do
   Node(Nobjects(NODE_c) - 1)%degree = 0
   j_l = 0
   do while (j_l < Nobjects(LINK_c))
      i_l = Link(j_l)%node1
      k_l = StartPos(i_l) + Node(i_l)%degree
      AdjList(k_l) = j_l
      Node(i_l)%degree = Node(i_l)%degree + 1
      if (listType == UNDIRECTED) then
         i_l = Link(j_l)%node2
         k_l = StartPos(i_l) + Node(i_l)%degree
         AdjList(k_l) = j_l
         Node(i_l)%degree = Node(i_l)%degree + 1
      end if
      j_l = j_l + 1
   end do
end subroutine createAdjList

! toposort.c:193
recursive subroutine adjustAdjList()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   i_l = 0
   j_l = 0
   k_l = 0
   m_l = 0
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (Node(i_l)%type /= DIVIDER_c) then
         goto 100
      end if
      if (Node(i_l)%degree /= 2) then
         goto 100
      end if
      k_l = Node(i_l)%subIndex
      m_l = StartPos(i_l)
      j_l = AdjList(m_l)
      if (j_l == Divider(k_l)%link) then
         AdjList(m_l) = AdjList(m_l + 1)
         AdjList(m_l + 1) = j_l
      end if
      100 continue
      i_l = i_l + 1
   end do
end subroutine adjustAdjList

! toposort.c:225
recursive function topoSort(sortedLinks_l) result(res_)
   integer(int32), pointer, intent(in) :: sortedLinks_l(:)
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: n_l
   integer(int32) :: i1_l
   integer(int32) :: i2
   integer(int32) :: k1
   integer(int32) :: k2
   res_ = 0
   i_l = 0
   j_l = 0
   k_l = 0
   n_l = 0
   i1_l = 0
   i2 = 0
   k1 = 0
   k2 = 0
   First = 0
   Last_c = -1
   i_l = 0
   do while (i_l < Nobjects(NODE_c))
      if (InDegree(i_l) == 0) then
         Last_c = Last_c + 1
         Stack(Last_c) = i_l
      end if
      i_l = i_l + 1
   end do
   n_l = 0
   do while (First <= Last_c)
      i1_l = Stack(First)
      k1 = StartPos(i1_l)
      k2 = k1 + Node(i1_l)%degree
      k_l = k1
      do while (k_l < k2)
         j_l = AdjList(k_l)
         sortedLinks_l(n_l) = j_l
         n_l = n_l + 1
         i2 = Link(j_l)%node2
         InDegree(i2) = InDegree(i2) - 1
         if (InDegree(i2) == 0) then
            Last_c = Last_c + 1
            Stack(Last_c) = i2
         end if
         k_l = k_l + 1
      end do
      First = First + 1
   end do
   res_ = n_l
   return
end function topoSort

! toposort.c:284
recursive subroutine findCycles()
   integer(int32) :: i_l
   i_l = 0
   allocate(AdjList(0:(2_int64 * int(Nobjects(LINK_c), int64)) - 1))
   AdjList = 0
   allocate(StartPos(0:(int(Nobjects(NODE_c), int64)) - 1))
   StartPos = 0
   allocate(Stack(0:(int(Nobjects(NODE_c), int64)) - 1))
   Stack = 0
   Examined = cbuf(int(Nobjects(NODE_c), int64))
   InTree = cbuf(int(Nobjects(LINK_c), int64))
   allocate(LoopLinks(0:(int(Nobjects(LINK_c), int64)) - 1))
   LoopLinks = 0
   if (((((associated(StartPos) .and. associated(AdjList)) .and. associated(Stack)) .and. (.not. cisnull(Examined))) .and. (.not. cisnull(InTree))) .and. associated(LoopLinks)) then
      call createAdjList(UNDIRECTED)
      i_l = 0
      do while (i_l < Nobjects(NODE_c))
         call cset(Examined, i_l, 0)
         i_l = i_l + 1
      end do
      i_l = 0
      do while (i_l < Nobjects(LINK_c))
         call cset(InTree, i_l, 0)
         i_l = i_l + 1
      end do
      i_l = 0
      do while (i_l < Nobjects(NODE_c))
         if (cget(Examined, i_l) /= 0) then
            goto 102
         end if
         Last_c = -1
         call findSpanningTree(i_l)
         102 continue
         i_l = i_l + 1
      end do
   end if
   if (associated(StartPos)) then
      ! 
      nullify(StartPos)
   end if
   if (associated(AdjList)) then
      ! 
      nullify(AdjList)
   end if
   if (associated(Stack)) then
      ! 
      nullify(Stack)
   end if
   if (.not. cisnull(Examined)) then
      ! 
      Examined = cnull()
   end if
   if (.not. cisnull(InTree)) then
      ! 
      InTree = cnull()
   end if
   if (associated(LoopLinks)) then
      ! 
      nullify(LoopLinks)
   end if
end subroutine findCycles

! toposort.c:330
recursive subroutine findSpanningTree(startNode)
   integer(int32), value :: startNode
   integer(int32) :: nextNode
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   nextNode = 0
   j_l = 0
   k_l = 0
   m_l = 0
   m_l = StartPos(startNode)
   do while (m_l < (StartPos(startNode) + Node(startNode)%degree))
      k_l = AdjList(m_l)
      if (Link(k_l)%node1 == startNode) then
         j_l = Link(k_l)%node2
      else
         j_l = Link(k_l)%node1
      end if
      if (cget(InTree, k_l) == 0) then
         if (cget(Examined, j_l) /= 0) then
            call cset(InTree, k_l, 2)
            call evalLoop(k_l)
         else
            call cset(Examined, j_l, 1)
            Last_c = Last_c + 1
            Stack(Last_c) = j_l
            call cset(InTree, k_l, 1)
         end if
      end if
      m_l = m_l + 1
   end do
   if (Last_c >= 0) then
      nextNode = Stack(Last_c)
      Last_c = Last_c - 1
      call findSpanningTree(nextNode)
   end if
end subroutine findSpanningTree

! toposort.c:385
recursive subroutine evalLoop(startLink)
   integer(int32), value :: startLink
   integer(int32) :: i_l
   integer(int32) :: i1_l
   integer(int32) :: i2
   integer(int32) :: j_l
   integer(int32) :: kount
   integer(int32) :: isCycle
   i_l = 0
   i1_l = 0
   i2 = 0
   j_l = 0
   kount = 0
   isCycle = 0
   LoopLinksLast = 0
   LoopLinks(0) = startLink
   i1_l = Link(startLink)%node1
   i2 = Link(startLink)%node2
   if (.not. (traceLoop(i1_l, i2, startLink) /= 0)) then
      return
   end if
   isCycle = 1
   j_l = LoopLinks(0)
   i2 = Link(j_l)%node2
   i_l = 1
   do while (i_l <= LoopLinksLast)
      j_l = LoopLinks(i_l)
      i1_l = Link(j_l)%node1
      if (i1_l == i2) then
         i2 = Link(j_l)%node2
      else
         isCycle = 0
         exit
      end if
      i_l = i_l + 1
   end do
   if (isCycle /= 0) then
      kount = 0
      i_l = 0
      do while (i_l <= LoopLinksLast)
         if (mod(kount, 5) == 0) then
            call c_fprintf(Frpt%file, lit_276)
         end if
         kount = kount + 1
         call c_fprintf(Frpt%file, lit_651, Link(LoopLinks(i_l))%ID)
         if (i_l < LoopLinksLast) then
            call c_fprintf(Frpt%file, lit_652)
         end if
         i_l = i_l + 1
      end do
   end if
end subroutine evalLoop

! toposort.c:440
recursive function traceLoop(i1_l, i2, k1) result(res_)
   integer(int32), value :: i1_l
   integer(int32), value :: i2
   integer(int32), value :: k1
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: m_l
   logical :: b1_
   res_ = 0
   j_l = 0
   k_l = 0
   m_l = 0
   if (i1_l == i2) then
      res_ = 1
      return
   end if
   m_l = StartPos(i1_l)
   do while (m_l < (StartPos(i1_l) + Node(i1_l)%degree))
      k_l = AdjList(m_l)
      b1_ = k_l == k1
      if (.not. b1_) then
         b1_ = cget(InTree, k_l) /= 1
      end if
      if (b1_) then
         goto 100
      end if
      if (Link(k_l)%node1 == i1_l) then
         j_l = Link(k_l)%node2
      else
         j_l = Link(k_l)%node1
      end if
      if (traceLoop(j_l, i2, k_l) /= 0) then
         LoopLinksLast = LoopLinksLast + 1
         LoopLinks(LoopLinksLast) = k_l
         res_ = 1
         return
      end if
      100 continue
      m_l = m_l + 1
   end do
   res_ = 0
   return
end function traceLoop

! toposort.c:482
recursive subroutine checkDummyLinks()
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32), pointer :: marked(:)
   logical :: b1_
   logical :: b2_
   logical :: b3_
   logical :: b4_
   logical :: b5_
   logical :: b6_
   i_l = 0
   j_l = 0
   nullify(marked)
   allocate(marked(0:(int(Nobjects(NODE_c), int64)) - 1))
   marked = 0
   if (.not. associated(marked)) then
      call report_writeErrorMsg(ERR_MEMORY, lit_0)
      return
   end if
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      j_l = Link(i_l)%node2
      if (Link(i_l)%direction < 0) then
         j_l = Link(i_l)%node1
      end if
      b1_ = Link(i_l)%type == CONDUIT_c
      if (b1_) then
         b1_ = Link(i_l)%xsect%type == DUMMY
      end if
      b3_ = b1_
      if (.not. b3_) then
         b2_ = Link(i_l)%type == PUMP_c
         if (b2_) then
            b2_ = Pump(Link(i_l)%subIndex)%type == IDEAL_PUMP
         end if
         b3_ = b2_
      end if
      if (b3_) then
         if (marked(j_l) == 0) then
            marked(j_l) = 1
         end if
      else
         marked(j_l) = -1
      end if
      i_l = i_l + 1
   end do
   i_l = 0
   do while (i_l < Nobjects(LINK_c))
      b4_ = Link(i_l)%type == CONDUIT_c
      if (b4_) then
         b4_ = Link(i_l)%xsect%type == DUMMY
      end if
      b6_ = b4_
      if (.not. b6_) then
         b5_ = Link(i_l)%type == PUMP_c
         if (b5_) then
            b5_ = Pump(Link(i_l)%subIndex)%type == IDEAL_PUMP
         end if
         b6_ = b5_
      end if
      if (b6_) then
         j_l = Link(i_l)%node1
         if (marked(j_l) > 0) then
            call report_writeErrorMsg(ERR_DUMMY_LINK, Node(j_l)%ID)
         end if
      end if
      i_l = i_l + 1
   end do
   if (associated(marked)) then
      ! 
      nullify(marked)
   end if
end subroutine checkDummyLinks

! transect.c:70
