! transect.c:104
recursive function transect_readParams(count_l, tok_l, ntoks) result(res_)
   integer(int32), intent(inout), target :: count_l
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int32) :: i_l
   integer(int32) :: k_l
   integer(int32) :: index_l
   integer(int32) :: errcode_l
   real(dp), target :: x_l(0:9)
   type(CPtr) :: id
   res_ = 0
   i_l = 0
   k_l = 0
   index_l = count_l
   errcode_l = 0
   x_l = 0.0_dp
   id = cnull()
   k_l = findmatch(tok_l(0), TransectKeyWords)
   if (k_l < 0) then
      res_ = error_setInpError(ERR_KEYWORD, tok_l(0))
      return
   end if
   select case (k_l)
   case (0)
      call transect_validate(index_l - 1)
      if (ntoks < 4) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 1
      do while (i_l <= 3)
         if (.not. (getDouble(tok_l(i_l), x_l(i_l)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         i_l = i_l + 1
      end do
      res_ = setManning(x_l)
      return
   case (1)
      if (ntoks < 10) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      id = project_findID(TRANSECT_c, tok_l(1))
      if (cisnull(id)) then
         res_ = error_setInpError(ERR_NAME, tok_l(1))
         return
      end if
      i_l = 2
      do while (i_l < 10)
         if (.not. (getDouble(tok_l(i_l), x_l(i_l)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         i_l = i_l + 1
      end do
      count_l = index_l + 1
      res_ = setParams(index_l, id, x_l)
      return
   case (2)
      if (mod(ntoks - 1, 2) > 0) then
         res_ = error_setInpError(ERR_ITEMS, lit_0)
         return
      end if
      i_l = 1
      do while (i_l < ntoks)
         if (.not. (getDouble(tok_l(i_l), x_l(1)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l))
            return
         end if
         if (.not. (getDouble(tok_l(i_l + 1), x_l(2)) /= 0)) then
            res_ = error_setInpError(ERR_NUMBER, tok_l(i_l + 1))
            return
         end if
         errcode_l = addStation(x_l(1), x_l(2))
         if (errcode_l /= 0) then
            res_ = errcode_l
            return
         end if
         i_l = i_l + 2
      end do
      res_ = 0
      return
   end select
   res_ = 0
   return
end function transect_readParams

! transect.c:194
recursive subroutine transect_validate(j_l)
   integer(int32), value :: j_l
   integer(int32) :: i_l
   real(dp) :: ymin
   real(dp) :: ymax
   real(dp) :: oldNchannel
   real(dp) :: v1_
   real(dp) :: v2_
   i_l = 0
   ymin = 0.0_dp
   ymax = 0.0_dp
   oldNchannel = Nchannel
   if ((j_l < 0) .or. (j_l >= Ntransects)) then
      return
   end if
   if (Nstations < 2) then
      call report_writeErrorMsg(ERR_TRANSECT_TOO_FEW, Transect(j_l)%ID)
      return
   end if
   if (Nstations >= 1500) then
      call report_writeErrorMsg(ERR_TRANSECT_TOO_MANY, Transect(j_l)%ID)
      return
   end if
   if (Nchannel <= 0.0_dp) then
      call report_writeErrorMsg(ERR_TRANSECT_MANNING, Transect(j_l)%ID)
      return
   end if
   if (Xleftbank > Xrightbank) then
      call report_writeErrorMsg(ERR_TRANSECT_OVERBANK, Transect(j_l)%ID)
      return
   end if
   Nchannel = Nchannel * sqrt(Lfactor)
   Transect(j_l)%lengthFactor = Lfactor
   ymax = Elev(1)
   ymin = Elev(1)
   i_l = 2
   do while (i_l <= Nstations)
      if ((Elev(i_l)) >= (ymax)) then
         v1_ = Elev(i_l)
      else
         v1_ = ymax
      end if
      ymax = v1_
      if ((Elev(i_l)) <= (ymin)) then
         v2_ = Elev(i_l)
      else
         v2_ = ymin
      end if
      ymin = v2_
      i_l = i_l + 1
   end do
   if (ymin >= ymax) then
      call report_writeErrorMsg(ERR_TRANSECT_NO_DEPTH, Transect(j_l)%ID)
      return
   end if
   Station(0) = Station(1)
   Elev(0) = ymax
   Nstations = Nstations + 1
   Station(Nstations) = Station(Nstations - 1)
   Elev(Nstations) = Elev(0)
   Transect(j_l)%nTbl = 51
   call createTables(Transect(j_l), ymin, ymax)
   Transect(j_l)%roughness = oldNchannel
end subroutine transect_validate

! transect.c:264
recursive subroutine createTables(transect_l, ymin, ymax)
   type(TTransect), pointer, intent(in) :: transect_l
   real(dp), value :: ymin
   real(dp), value :: ymax
   integer(int32) :: i_l
   integer(int32) :: nLast
   real(dp) :: dy
   real(dp) :: y_l
   i_l = 0
   nLast = 0
   dy = 0.0_dp
   y_l = 0.0_dp
   transect_l%yFull = ymax - ymin
   transect_l%wMax = 0.0_dp
   transect_l%areaTbl(0) = 0.0_dp
   transect_l%hradTbl(0) = 0.0_dp
   transect_l%widthTbl(0) = 0.0_dp
   dy = (ymax - ymin) / (real(transect_l%nTbl, dp) - 1.0_dp)
   y_l = ymin
   i_l = 1
   do while (i_l < transect_l%nTbl)
      y_l = y_l + dy
      transect_l%areaTbl(i_l) = 0.0_dp
      transect_l%hradTbl(i_l) = 0.0_dp
      transect_l%widthTbl(i_l) = 0.0_dp
      call getGeometry(transect_l, i_l, y_l)
      i_l = i_l + 1
   end do
   call setMaxSectionFactor(transect_l)
   nLast = transect_l%nTbl - 1
   transect_l%aFull = transect_l%areaTbl(nLast)
   transect_l%rFull = transect_l%hradTbl(nLast)
   transect_l%wMax = transect_l%widthTbl(nLast)
   i_l = 1
   do while (i_l <= nLast)
      transect_l%areaTbl(i_l) = transect_l%areaTbl(i_l) / transect_l%aFull
      transect_l%hradTbl(i_l) = transect_l%hradTbl(i_l) / transect_l%rFull
      transect_l%widthTbl(i_l) = transect_l%widthTbl(i_l) / transect_l%wMax
      i_l = i_l + 1
   end do
   transect_l%widthTbl(0) = transect_l%widthTbl(1)
end subroutine createTables

! transect.c:312
recursive function setManning(n_l) result(res_)
   real(dp), pointer, intent(in) :: n_l(:)
   integer(int32) :: res_
   integer(int32) :: i_l
   res_ = 0
   i_l = 0
   i_l = 1
   do while (i_l <= 3)
      if (n_l(i_l) < 0.0_dp) then
         res_ = ERR_NUMBER
         return
      end if
      i_l = i_l + 1
   end do
   if (n_l(1) > 0.0_dp) then
      Nleft = n_l(1)
   end if
   if (n_l(2) > 0.0_dp) then
      Nright = n_l(2)
   end if
   if (n_l(3) > 0.0_dp) then
      Nchannel = n_l(3)
   end if
   if (Nleft == 0.0_dp) then
      Nleft = Nchannel
   end if
   if (Nright == 0.0_dp) then
      Nright = Nchannel
   end if
   res_ = 0
   return
end function setManning

! transect.c:334
recursive function setParams(j_l, id, x_l) result(res_)
   integer(int32), value :: j_l
   type(CPtr), value :: id
   real(dp), pointer, intent(in) :: x_l(:)
   integer(int32) :: res_
   res_ = 0
   if ((j_l < 0) .or. (j_l >= Ntransects)) then
      res_ = ERR_NUMBER
      return
   end if
   Transect(j_l)%ID = id
   Xleftbank = x_l(3) / UCF(LENGTH)
   Xrightbank = x_l(4) / UCF(LENGTH)
   Lfactor = x_l(7)
   if (Lfactor == 0.0_dp) then
      Lfactor = 1.0_dp
   end if
   Xfactor = x_l(8)
   if (Xfactor == 0.0_dp) then
      Xfactor = 1.0_dp
   end if
   Xleftbank = Xleftbank * Xfactor
   Xrightbank = Xrightbank * Xfactor
   Yfactor = x_l(9) / UCF(LENGTH)
   Nstations = 0
   res_ = 0
   return
end function setParams

! transect.c:360
recursive function addStation(y_l, x_l) result(res_)
   real(dp), value :: y_l
   real(dp), value :: x_l
   integer(int32) :: res_
   logical :: b1_
   res_ = 0
   if (Nstations < 0) then
      res_ = ERR_TRANSECT_UNKNOWN
      return
   end if
   Nstations = Nstations + 1
   if (Nstations >= 1500) then
      res_ = 0
      return
   end if
   Station(Nstations) = (x_l * Xfactor) / UCF(LENGTH)
   Elev(Nstations) = (y_l + Yfactor) / UCF(LENGTH)
   b1_ = Nstations > 1
   if (b1_) then
      b1_ = Station(Nstations) < Station(Nstations - 1)
   end if
   if (b1_) then
      res_ = ERR_TRANSECT_SEQUENCE
      return
   end if
   res_ = 0
   return
end function addStation

! transect.c:388
recursive subroutine getGeometry(transect_l, i_l, y_l)
   type(TTransect), pointer, intent(in) :: transect_l
   integer(int32), value :: i_l
   real(dp), value :: y_l
   integer(int32) :: k_l
   real(dp) :: ylo
   real(dp) :: yhi
   real(dp), target :: w_l
   real(dp), target :: wp
   real(dp) :: wpSum
   real(dp), target :: a_l
   real(dp) :: aSum
   real(dp) :: q_l
   real(dp) :: qSum
   integer(int32) :: findFlow
   k_l = 0
   ylo = 0.0_dp
   yhi = 0.0_dp
   w_l = 0.0_dp
   wp = 0.0_dp
   wpSum = 0.0_dp
   a_l = 0.0_dp
   aSum = 0.0_dp
   q_l = 0.0_dp
   qSum = 0.0_dp
   findFlow = 0
   wpSum = 0.0_dp
   aSum = 0.0_dp
   qSum = 0.0_dp
   k_l = 1
   do while (k_l <= Nstations)
      if (Elev(k_l - 1) >= Elev(k_l)) then
         yhi = Elev(k_l - 1)
         ylo = Elev(k_l)
      else
         yhi = Elev(k_l)
         ylo = Elev(k_l - 1)
      end if
      if (ylo >= y_l) then
         goto 100
      end if
      call getSliceGeom(k_l, y_l, ylo, yhi, w_l, a_l, wp)
      wpSum = wpSum + wp
      aSum = aSum + a_l
      transect_l%areaTbl(i_l) = transect_l%areaTbl(i_l) + a_l
      transect_l%widthTbl(i_l) = transect_l%widthTbl(i_l) + w_l
      if (Elev(k_l) >= y_l) then
         findFlow = 1
      else
         findFlow = 0
      end if
      q_l = getFlow(k_l, aSum, wpSum, findFlow)
      if (q_l > 0.0_dp) then
         qSum = qSum + q_l
         aSum = 0.0_dp
         wpSum = 0.0_dp
      end if
      100 continue
      k_l = k_l + 1
   end do
   aSum = transect_l%areaTbl(i_l)
   if (aSum == 0.0_dp) then
      transect_l%hradTbl(i_l) = transect_l%hradTbl(i_l - 1)
   else
      transect_l%hradTbl(i_l) = (((qSum * Nchannel) / 1.49_dp) / aSum) ** 1.5_dp
   end if
end subroutine getGeometry

! transect.c:468
recursive subroutine getSliceGeom(k_l, y_l, ylo, yhi, w_l, a_l, wp)
   integer(int32), value :: k_l
   real(dp), value :: y_l
   real(dp), value :: ylo
   real(dp), value :: yhi
   real(dp), intent(inout), target :: w_l
   real(dp), intent(inout), target :: a_l
   real(dp), intent(inout), target :: wp
   real(dp) :: width_l
   real(dp) :: ratio
   width_l = 0.0_dp
   ratio = 0.0_dp
   width_l = abs(Station(k_l) - Station(k_l - 1))
   w_l = width_l
   wp = sqrt((width_l * width_l) + ((yhi - ylo) * (yhi - ylo)))
   a_l = 0.0_dp
   if (y_l > yhi) then
      a_l = (width_l * ((y_l - yhi) + (y_l - ylo))) / 2.0_dp
   else if (yhi > ylo) then
      ratio = (y_l - ylo) / (yhi - ylo)
      a_l = (((width_l * (yhi - ylo)) / 2.0_dp) * ratio) * ratio
      w_l = w_l * ratio
      wp = wp * ratio
   end if
end subroutine getSliceGeom

! transect.c:519
recursive function getFlow(k_l, a_l, wp, findFlow) result(res_)
   integer(int32), value :: k_l
   real(dp), value :: a_l
   real(dp), value :: wp
   integer(int32), value :: findFlow
   real(dp) :: res_
   real(dp) :: n_l
   logical :: b1_
   logical :: b2_
   res_ = 0.0_dp
   n_l = 0.0_dp
   if (findFlow == 0) then
      if (k_l == (Nstations - 1)) then
         findFlow = 1
      else if (Station(k_l) == Xleftbank) then
         b1_ = Nleft /= Nchannel
         if (b1_) then
            b1_ = Station(k_l) /= Station(k_l - 1)
         end if
         if (b1_) then
            findFlow = 1
         end if
      else if (Station(k_l) == Xrightbank) then
         b2_ = Nright /= Nchannel
         if (b2_) then
            b2_ = Station(k_l) /= Station(k_l + 1)
         end if
         if (b2_) then
            findFlow = 1
         end if
      end if
   end if
   if (findFlow /= 0) then
      n_l = Nchannel
      if (Station(k_l - 1) < Xleftbank) then
         n_l = Nleft
      end if
      if (Station(k_l) > Xrightbank) then
         n_l = Nright
      end if
      res_ = ((1.486_dp / n_l) * a_l) * ((a_l / wp) ** (2.0_dp / 3.0_dp))
      return
   end if
   res_ = 0.0_dp
   return
end function getFlow

! transect.c:570
recursive subroutine setMaxSectionFactor(transect_l)
   type(TTransect), pointer, intent(in) :: transect_l
   integer(int32) :: i_l
   real(dp) :: sf_l
   i_l = 0
   sf_l = 0.0_dp
   transect_l%aMax = 0.0_dp
   transect_l%sMax = 0.0_dp
   i_l = 1
   do while (i_l < transect_l%nTbl)
      sf_l = transect_l%areaTbl(i_l) * (transect_l%hradTbl(i_l) ** (2.0_dp / 3.0_dp))
      if (sf_l > transect_l%sMax) then
         transect_l%sMax = sf_l
         transect_l%aMax = transect_l%areaTbl(i_l)
      end if
      i_l = i_l + 1
   end do
end subroutine setMaxSectionFactor

! transect.c:596
recursive subroutine transect_createStreetTransect(street_l)
   type(TStreet), pointer, intent(in) :: street_l
   real(dp) :: ymin
   real(dp) :: ymax
   real(dp) :: y1
   real(dp) :: y3
   real(dp) :: y4
   real(dp) :: w1
   real(dp) :: w2
   real(dp) :: w3
   real(dp) :: w4
   ymin = 0.0_dp
   ymax = 0.0_dp
   y1 = 0.0_dp
   y3 = 0.0_dp
   y4 = 0.0_dp
   w1 = 0.0_dp
   w2 = 0.0_dp
   w3 = 0.0_dp
   w4 = 0.0_dp
   ymin = 0.0_dp
   w1 = street_l%backWidth
   w2 = street_l%gutterWidth
   w3 = street_l%width
   w4 = w3 - w2
   y3 = street_l%gutterDepression + (street_l%slope * w2)
   y1 = street_l%curbHeight + street_l%gutterDepression
   ymax = (street_l%backSlope * street_l%backWidth) + y1
   y4 = y3 + (street_l%slope * w4)
   ymax = merge(ymax, y4, (ymax) >= (y4))
   Station(0) = 0.0_dp
   Elev(0) = ymax
   Station(1) = w1
   Elev(1) = y1
   Station(2) = w1
   Elev(2) = 0.0_dp
   Station(3) = w1 + w2
   Elev(3) = y3
   Station(4) = w1 + w3
   Elev(4) = y4
   if (street_l%sides == 1) then
      Station(5) = Station(4)
      Elev(5) = ymax
      Nstations = 5
      street_l%transect%nTbl = 51
   else
      Station(5) = Station(4) + w4
      Elev(5) = y3
      Station(6) = Station(5) + w2
      Elev(6) = 0.0_dp
      Station(7) = Station(6)
      Elev(7) = y1
      Station(8) = Station(7) + w1
      Elev(8) = ymax
      Nstations = 8
      street_l%transect%nTbl = 51
   end if
   Nchannel = street_l%roughness
   if (street_l%backWidth == 0.0_dp) then
      Nleft = Nchannel
      Nright = Nchannel
      Xleftbank = Station(0)
      Xrightbank = Station(Nstations)
   else
      Nleft = street_l%backRoughness
      Nright = Nleft
      Xleftbank = Station(1)
      if (street_l%sides == 2) then
         Xrightbank = Station(Nstations - 1)
      else
         Xrightbank = Station(Nstations)
      end if
   end if
   call createTables(street_l%transect, ymin, ymax)
   street_l%transect%roughness = street_l%roughness
end subroutine transect_createStreetTransect

