! treatmnt.c:103
recursive function treatmnt_readExpression(tok_l, ntoks) result(res_)
   type(CPtr), pointer, intent(in) :: tok_l(:)
   integer(int32), value :: ntoks
   integer(int32) :: res_
   integer(int8), target :: s_l(0:1024)
   type(CPtr) :: expr
   integer(int32) :: i_l
   integer(int32) :: j_l
   integer(int32) :: k_l
   integer(int32) :: p_l
   type(MathExpr), pointer :: equation
   integer(int64) :: dum1_
   logical :: b2_
   integer(int32) :: v3_
   logical :: b4_
   integer(int32) :: v5_
   logical :: b6_
   integer(int32) :: v7_
   res_ = 0
   s_l = 0_int8
   expr = cnull()
   i_l = 0
   j_l = 0
   k_l = 0
   p_l = 0
   nullify(equation)
   if (ntoks < 3) then
      res_ = error_setInpError(ERR_ITEMS, lit_0)
      return
   end if
   j_l = project_findObject(NODE_c, tok_l(0))
   if (j_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(0))
      return
   end if
   p_l = project_findObject(POLLUT_c, tok_l(1))
   if (p_l < 0) then
      res_ = error_setInpError(ERR_NAME, tok_l(1))
      return
   end if
   dum1_ = sstrncpy(cview(s_l), tok_l(2), 1024_int64)
   i_l = 3
   do while (i_l < ntoks)
      dum1_ = sstrcat(cview(s_l), lit_33, 1024_int64)
      dum1_ = sstrcat(cview(s_l), tok_l(i_l), 1024_int64)
      i_l = i_l + 1
   end do
   b2_ = (int(s_l(0), int32)) >= 97
   if (b2_) then
      b2_ = (int(s_l(0), int32)) <= 122
   end if
   if (b2_) then
      v3_ = iand(int(s_l(0), int32), not(32))
   else
      v3_ = int(s_l(0), int32)
   end if
   if ((v3_) == 82) then
      k_l = 0
   else
      b6_ = (int(s_l(0), int32)) >= 97
      if (b6_) then
         b6_ = (int(s_l(0), int32)) <= 122
      end if
      if (b6_) then
         v7_ = iand(int(s_l(0), int32), not(32))
      else
         v7_ = int(s_l(0), int32)
      end if
      if ((v7_) == 67) then
         k_l = 1
      else
         res_ = error_setInpError(ERR_KEYWORD, tok_l(2))
         return
      end if
   end if
   expr = c_strchr(cview(s_l), 61)
   if (cisnull(expr)) then
      res_ = error_setInpError(ERR_KEYWORD, lit_0)
      return
   else
      expr%o = expr%o + 1
   end if
   if (.not. associated(Node(j_l)%treatment)) then
      if (.not. (createTreatment(j_l) /= 0)) then
         res_ = error_setInpError(ERR_MEMORY, lit_0)
         return
      end if
   end if
   equation => mathexpr_create(expr, treatmnt_getVariableIndex)
   if (.not. associated(equation)) then
      res_ = error_setInpError(ERR_MATH_EXPR, lit_0)
      return
   end if
   if (.not. (.not. associated(Node(j_l)%treatment))) then
      Node(j_l)%treatment(p_l)%treatType = k_l
      Node(j_l)%treatment(p_l)%equation => equation
   end if
   res_ = 0
   return
end function treatmnt_readExpression

