! treatmnt.c:202
recursive subroutine treatmnt_treat(j_l, q_l, v_l, tStep)
   integer(int32), value :: j_l
   real(dp), value :: q_l
   real(dp), value :: v_l
   real(dp), value :: tStep
   integer(int32) :: p_l
   real(dp) :: cOut
   real(dp) :: massLost
   type(TTreatment), pointer :: treatment
   real(dp) :: dum1_
   real(dp) :: v2_
   p_l = 0
   cOut = 0.0_dp
   massLost = 0.0_dp
   nullify(treatment)
   if (.not. associated(Node(j_l)%treatment)) then
      return
   end if
   ErrCode = 0
   J_c = j_l
   Dt = tStep
   Q_c = q_l
   V_c = v_l
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      R_c(p_l) = -1.0_dp
      p_l = p_l + 1
   end do
   p_l = 0
   do while (p_l < Nobjects(POLLUT_c))
      treatment => Node(j_l)%treatment(p_l)
      if (.not. associated(treatment%equation)) then
         R_c(p_l) = 0.0_dp
      else if ((treatment%treatType == REMOVAL) .and. (q_l <= 1.0e-10_dp)) then
         R_c(p_l) = 0.0_dp
      else
         dum1_ = getRemoval(p_l)
      end if
      p_l = p_l + 1
   end do
   if (ErrCode == ERR_CYCLIC_TREATMENT) then
      call report_writeErrorMsg(ERR_CYCLIC_TREATMENT, Node(J_c)%ID)
   else
      p_l = 0
      do while (p_l < Nobjects(POLLUT_c))
         if (R_c(p_l) == 0.0_dp) then
            goto 102
         end if
         treatment => Node(j_l)%treatment(p_l)
         if (treatment%treatType == REMOVAL) then
            if (Cin(p_l) == 0.0_dp) then
               cOut = Node(j_l)%newQual(p_l)
            else
               cOut = (1.0_dp - R_c(p_l)) * Cin(p_l)
            end if
            if ((cOut) <= (Node(j_l)%newQual(p_l))) then
               v2_ = cOut
            else
               v2_ = Node(j_l)%newQual(p_l)
            end if
            cOut = v2_
         else
            cOut = (1.0_dp - R_c(p_l)) * Node(j_l)%newQual(p_l)
         end if
         massLost = ((((Cin(p_l) * q_l) * tStep) + (Node(j_l)%oldQual(p_l) * Node(j_l)%oldVolume)) - (cOut * ((q_l * tStep) + Node(j_l)%oldVolume))) / tStep
         massLost = merge(0.0_dp, massLost, (0.0_dp) >= (massLost))
         call massbal_addReactedMass(p_l, massLost)
         Node(j_l)%newQual(p_l) = cOut
         102 continue
         p_l = p_l + 1
      end do
   end if
end subroutine treatmnt_treat

