end function createTreatment

! treatmnt.c:311
recursive function treatmnt_getVariableIndex(s_l) result(res_)
   type(CPtr), value :: s_l
   integer(int32) :: res_
   integer(int32) :: k_l
   integer(int32) :: m_l
   logical :: b1_
   integer(int32) :: v2_
   logical :: b3_
   res_ = 0
   k_l = 0
   m_l = PVMAX
   k_l = findmatch(s_l, ProcessVarWords)
   if (k_l >= 0) then
      res_ = k_l
      return
   end if
   k_l = project_findObject(POLLUT_c, s_l)
   if (k_l >= 0) then
      res_ = k_l + m_l
      return
   end if
   b1_ = (cget(s_l, 0)) >= 97
   if (b1_) then
      b1_ = (cget(s_l, 0)) <= 122
