      xsect_l%sFull = xsect_l%aFull * (xsect_l%rFull ** (2.0_dp / 3.0_dp))
      xsect_l%sMax = xsect_l%sFull
   case (12)
      if (p_l(1) == 0.0_dp) then
         p_l(2) = p_l(0)
      end if
      if (p_l(2) > 0.0_dp) then
         index_l = d2i(cfloor(p_l(2))) - 1
         if ((index_l < 0) .or. (index_l >= NumCodesEllipse)) then
            res_ = 0
            return
         end if
         xsect_l%yFull = MinorAxis_Ellipse(index_l) / 12.0_dp
         xsect_l%wMax = MajorAxis_Ellipse(index_l) / 12.0_dp
         xsect_l%aFull = Afull_Ellipse(index_l)
         xsect_l%rFull = Rfull_Ellipse(index_l)
      else
         xsect_l%yFull = p_l(0) / ucf_l
         if (p_l(1) < 0.0_dp) then
            res_ = 0
            return
         end if
         xsect_l%wMax = p_l(1) / ucf_l
         xsect_l%aFull = (1.2692_dp * xsect_l%yFull) * xsect_l%yFull
         xsect_l%rFull = 0.3061_dp * xsect_l%yFull
      end if
      xsect_l%sFull = xsect_l%aFull * (xsect_l%rFull ** (2.0_dp / 3.0_dp))
      xsect_l%sMax = xsect_l%sFull
      xsect_l%ywMax = 0.48_dp * xsect_l%yFull
   case (13)
      if (p_l(1) == 0.0_dp) then
         p_l(2) = p_l(0)
      end if
      if (p_l(2) > 0.0_dp) then
         index_l = d2i(cfloor(p_l(2))) - 1
         if ((index_l < 0) .or. (index_l >= NumCodesEllipse)) then
            res_ = 0
            return
         end if
         xsect_l%yFull = MajorAxis_Ellipse(index_l) / 12.0_dp
         xsect_l%wMax = MinorAxis_Ellipse(index_l) / 12.0_dp
         xsect_l%aFull = Afull_Ellipse(index_l)
         xsect_l%rFull = Rfull_Ellipse(index_l)
      else
         if (p_l(1) < 0.0_dp) then
            res_ = 0
            return
         end if
         xsect_l%yFull = p_l(0) / ucf_l
         xsect_l%wMax = p_l(1) / ucf_l
         xsect_l%aFull = (1.2692_dp * xsect_l%wMax) * xsect_l%wMax
         xsect_l%rFull = 0.3061_dp * xsect_l%wMax
      end if
      xsect_l%sFull = xsect_l%aFull * (xsect_l%rFull ** (2.0_dp / 3.0_dp))
      xsect_l%sMax = xsect_l%sFull
      xsect_l%ywMax = 0.48_dp * xsect_l%yFull
   case (14)
      if (p_l(1) == 0.0_dp) then
         p_l(2) = p_l(0)
      end if
      if (p_l(2) > 0.0_dp) then
         index_l = d2i(cfloor(p_l(2))) - 1
         if ((index_l < 0) .or. (index_l >= NumCodesArch)) then
            res_ = 0
            return
         end if
         xsect_l%yFull = Yfull_Arch(index_l) / 12.0_dp
         xsect_l%wMax = Wmax_Arch(index_l) / 12.0_dp
         xsect_l%aFull = Afull_Arch(index_l)
         xsect_l%rFull = Rfull_Arch(index_l)
      else
         if (p_l(1) < 0.0_dp) then
            res_ = 0
            return
         end if
         xsect_l%yFull = p_l(0) / ucf_l
         xsect_l%wMax = p_l(1) / ucf_l
         xsect_l%aFull = (0.7879_dp * xsect_l%yFull) * xsect_l%wMax
         xsect_l%rFull = 0.2991_dp * xsect_l%yFull
      end if
      xsect_l%sFull = xsect_l%aFull * (xsect_l%rFull ** (2.0_dp / 3.0_dp))
      xsect_l%sMax = xsect_l%sFull
      xsect_l%ywMax = 0.28_dp * xsect_l%yFull
   end select
   res_ = 1
   return
end function xsect_setParams

