! xsect.c:664
recursive subroutine xsect_setCustomXsectParams(xsect_l)
   type(TXsect), pointer, intent(in) :: xsect_l
   integer(int32) :: index_l
   real(dp) :: yFull
   integer(int32) :: i_l
   integer(int32) :: iMax
   real(dp) :: wMax
   real(dp), pointer :: wTbl(:)
   index_l = Curve(xsect_l%transect)%refersTo
   yFull = xsect_l%yFull
   i_l = 0
   iMax = 0
   wMax = 0.0_dp
   wTbl => Shape_c(index_l)%widthTbl
   xsect_l%wMax = Shape_c(index_l)%wMax * yFull
   xsect_l%aFull = (Shape_c(index_l)%aFull * yFull) * yFull
   xsect_l%rFull = Shape_c(index_l)%rFull * yFull
   xsect_l%sFull = xsect_l%aFull * (xsect_l%rFull ** (2.0_dp / 3.0_dp))
   xsect_l%sMax = ((Shape_c(index_l)%sMax * yFull) * yFull) * (yFull ** (2.0_dp / 3.0_dp))
   xsect_l%aBot = (Shape_c(index_l)%aMax * yFull) * yFull
   iMax = 0
   wMax = wTbl(0)
   i_l = 1
   do while (i_l < 51)
      if (wTbl(i_l) < wMax) then
         exit
      end if
      wMax = wTbl(i_l)
      iMax = i_l
      i_l = i_l + 1
   end do
   xsect_l%ywMax = (yFull * real(iMax, dp)) / real(51 - 1, dp)
end subroutine xsect_setCustomXsectParams

! xsect.c:700
recursive function xsect_getAmax(xsect_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp) :: res_
   res_ = 0.0_dp
   if (xsect_l%type == IRREGULAR) then
      res_ = xsect_l%aBot
      return
   else if (xsect_l%type == CUSTOM) then
      res_ = xsect_l%aBot
      return
   else
      res_ = Amax(xsect_l%type) * xsect_l%aFull
      return
   end if
end function xsect_getAmax

! xsect.c:714
recursive function xsect_getSofA(xsect_l, a_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: a_l
   real(dp) :: res_
   real(dp) :: alpha_l
   real(dp) :: r_l
   res_ = 0.0_dp
   alpha_l = a_l / xsect_l%aFull
   r_l = 0.0_dp
   select case (xsect_l%type)
   case (24, 1)
      res_ = circ_getSofA(xsect_l, a_l)
      return
   case (15)
      res_ = xsect_l%sFull * lookup(alpha_l, S_Egg, N_S_Egg)
      return
   case (16)
      res_ = xsect_l%sFull * lookup(alpha_l, S_Horseshoe, N_S_Horseshoe)
      return
   case (17)
      res_ = xsect_l%sFull * lookup(alpha_l, S_Gothic, N_S_Gothic)
      return
   case (18)
      res_ = xsect_l%sFull * lookup(alpha_l, S_Catenary, N_S_Catenary)
      return
   case (19)
      res_ = xsect_l%sFull * lookup(alpha_l, S_SemiEllip, N_S_SemiEllip)
      return
   case (20)
      res_ = xsect_l%sFull * lookup(alpha_l, S_BasketHandle, N_S_BasketHandle)
      return
   case (21)
      res_ = xsect_l%sFull * lookup(alpha_l, S_SemiCirc, N_S_SemiCirc)
      return
   case (3)
      res_ = rect_closed_getSofA(xsect_l, a_l)
      return
   case (4)
      res_ = rect_open_getSofA(xsect_l, a_l)
      return
   case (9)
      res_ = rect_triang_getSofA(xsect_l, a_l)
      return
   case (10)
      res_ = rect_round_getSofA(xsect_l, a_l)
      return
   case default
      if (a_l == 0.0_dp) then
         res_ = 0.0_dp
         return
      end if
      r_l = xsect_getRofA(xsect_l, a_l)
      if (r_l < 1.0e-06_dp) then
         res_ = 0.0_dp
         return
      end if
      res_ = a_l * (r_l ** (2.0_dp / 3.0_dp))
      return
   end select
end function xsect_getSofA

