! xsect.c:1100
recursive function xsect_getRofA(xsect_l, a_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: a_l
   real(dp) :: res_
   real(dp) :: cathy
   res_ = 0.0_dp
   cathy = 0.0_dp
   if (a_l <= 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   select case (xsect_l%type)
   case (12, 13, 14, 22, 2, 23, 25)
      res_ = xsect_getRofY(xsect_l, xsect_getYofA(xsect_l, a_l))
      return
   case (3)
      res_ = rect_closed_getRofA(xsect_l, a_l)
      return
