recursive function xsect_getYcrit(xsect_l, q_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: q_l
   real(dp) :: res_
   real(dp) :: q2g
   real(dp) :: y_l
   real(dp) :: r_l
   real(dp) :: v1_
   res_ = 0.0_dp
   q2g = ((q_l) * (q_l)) / 32.2_dp
   y_l = 0.0_dp
   r_l = 0.0_dp
   if (q2g == 0.0_dp) then
      res_ = 0.0_dp
      return
   end if
   select case (xsect_l%type)
   case (0)
      res_ = 0.0_dp
      return
   case (4, 3)
