   case (8)
      y_l = 1.0_dp / ((2.0_dp * xsect_l%sBot) + 3.0_dp)
      y_l = ((q2g * (xsect_l%sBot + 1.0_dp)) / ((xsect_l%rBot) * (xsect_l%rBot))) ** y_l
   case default
      y_l = 1.01_dp * ((q2g / xsect_l%yFull) ** (1.0_dp / 4.0_dp))
