end function generic_getdSdA

! xsect.c:1474
recursive function lookup(x_l, table, nItems) result(res_)
   real(dp), value :: x_l
   real(dp), pointer, intent(in) :: table(:)
   integer(int32), value :: nItems
   real(dp) :: res_
   real(dp) :: delta
   real(dp) :: x0
   real(dp) :: x1
   real(dp) :: y_l
   real(dp) :: y2
   integer(int32) :: i_l
   res_ = 0.0_dp
   delta = 0.0_dp
   x0 = 0.0_dp
   x1 = 0.0_dp
   y_l = 0.0_dp
   y2 = 0.0_dp
   i_l = 0
   delta = 1.0_dp / (real(nItems, dp) - 1.0_dp)
   i_l = d2i(x_l / delta)
   if (i_l >= (nItems - 1)) then
      res_ = table(nItems - 1)
      return
   end if
   x0 = real(i_l, dp) * delta
   x1 = (real(i_l, dp) + 1.0_dp) * delta
   y_l = table(i_l) + (((x_l - x0) * (table(i_l + 1) - table(i_l))) / delta)
   if (i_l < 2) then
      y2 = y_l + ((((x_l - x0) * (x_l - x1)) / (delta * delta)) * (((table(i_l) / 2.0_dp) - table(i_l + 1)) + (table(i_l + 2) / 2.0_dp)))
      if (y2 > 0.0_dp) then
         y_l = y2
      end if
   end if
   if (y_l < 0.0_dp) then
      y_l = 0.0_dp
   end if
   res_ = y_l
   return
end function lookup

! xsect.c:1511
recursive function invLookup(y_l, table, nItems) result(res_)
   real(dp), value :: y_l
   real(dp), pointer, intent(in) :: table(:)
   integer(int32), value :: nItems
   real(dp) :: res_
   real(dp) :: dx
   real(dp) :: x_l
   real(dp) :: x0
   real(dp) :: dy
   integer(int32) :: n_l
   integer(int32) :: i_l
   logical :: b1_
   res_ = 0.0_dp
   dx = 0.0_dp
   x_l = 0.0_dp
   x0 = 0.0_dp
   dy = 0.0_dp
   n_l = 0
   i_l = 0
   dx = 1.0_dp / (real(nItems, dp) - 1.0_dp)
   n_l = nItems
   if (table(n_l - 3) > table(n_l - 1)) then
      n_l = n_l - 2
   end if
   b1_ = n_l < nItems
   if (b1_) then
      b1_ = y_l > table(nItems - 1)
   end if
   if (b1_) then
      if (y_l >= table(nItems - 3)) then
         res_ = (real(n_l, dp) - 1.0_dp) * dx
         return
      end if
      if (y_l <= table(nItems - 2)) then
         i_l = nItems - 2
      else
         i_l = nItems - 3
      end if
   else
      i_l = locate(y_l, table, n_l - 1)
   end if
   if (i_l >= (n_l - 1)) then
      res_ = (real(n_l, dp) - 1.0_dp) * dx
      return
   end if
   x0 = real(i_l, dp) * dx
   dy = table(i_l + 1) - table(i_l)
   if (dy == 0.0_dp) then
      x_l = x0
   else
      x_l = x0 + (((y_l - table(i_l)) * dx) / dy)
   end if
   if (x_l < 0.0_dp) then
      x_l = 0.0_dp
   end if
   if (x_l > 1.0_dp) then
      x_l = 1.0_dp
   end if
   res_ = x_l
   return
end function invLookup

! xsect.c:1571
recursive function locate(y_l, table, jLast) result(res_)
   real(dp), value :: y_l
   real(dp), pointer, intent(in) :: table(:)
   integer(int32), value :: jLast
   integer(int32) :: res_
   integer(int32) :: j_l
   integer(int32) :: j1
   integer(int32) :: j2
   res_ = 0
   j_l = 0
   j1 = 0
   j2 = jLast
   if (y_l <= table(0)) then
      res_ = 0
      return
   end if
   if (y_l >= table(jLast)) then
      res_ = jLast
      return
   end if
   do while ((j2 - j1) > 1)
      j_l = shifta(j1 + j2, 1)
      if (y_l >= table(j_l)) then
         j1 = j_l
      else
         j2 = j_l
      end if
   end do
   res_ = j1
   return
end function locate

! xsect.c:1612
recursive function getQcritical(yc, p_l) result(res_)
   real(dp), value :: yc
   type(c_ptr), value :: p_l
   real(dp) :: res_
   real(dp) :: a_l
   real(dp) :: w_l
   real(dp) :: qc
   type(TXsectStar), pointer :: xsectStar
   type(TXsectStar), pointer :: p1_
   res_ = 0.0_dp
   a_l = 0.0_dp
   w_l = 0.0_dp
   qc = 0.0_dp
   nullify(xsectStar)
   call c_f_pointer(p_l, p1_)
   xsectStar => p1_
   a_l = xsect_getAofY(xsectStar%xsect, yc)
   w_l = xsect_getWofY(xsectStar%xsect, yc)
   qc = -xsectStar%qc
   if (w_l > 0.0_dp) then
      qc = (a_l * sqrt((32.2_dp * a_l) / w_l)) - xsectStar%qc
   end if
   res_ = qc
   return
end function getQcritical

! xsect.c:1634
recursive function getYcritEnum(xsect_l, q_l, y0_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: q_l
   real(dp), value :: y0_l
   real(dp) :: res_
   real(dp) :: q0
   real(dp) :: dy
   real(dp) :: qc
   real(dp) :: yc
   integer(int32) :: i1_l
   integer(int32) :: i_l
   type(TXsectStar), target :: xsectStar
   res_ = 0.0_dp
   q0 = 0.0_dp
   dy = 0.0_dp
   qc = 0.0_dp
   yc = 0.0_dp
   i1_l = 0
   i_l = 0
   xsectStar = zero_TXsectStar
   dy = xsect_l%yFull / 25.0_dp
   i1_l = d2i(y0_l / dy)
   xsectStar%xsect => xsect_l
   xsectStar%qc = 0.0_dp
   q0 = getQcritical(real(i1_l, dp) * dy, c_loc(xsectStar))
   if (q0 < q_l) then
      yc = xsect_l%yFull
      i_l = i1_l + 1
      do while (i_l <= 25)
         qc = getQcritical(real(i_l, dp) * dy, c_loc(xsectStar))
         if (qc >= q_l) then
            yc = (((q_l - q0) / (qc - q0)) + (real(i_l, dp) - 1.0_dp)) * dy
            exit
         end if
         q0 = qc
         i_l = i_l + 1
      end do
   else
      yc = 0.0_dp
      i_l = i1_l - 1
      do while (i_l >= 0)
         qc = getQcritical(real(i_l, dp) * dy, c_loc(xsectStar))
         if (qc < q_l) then
            yc = (((q_l - qc) / (q0 - qc)) + real(i_l, dp)) * dy
            exit
         end if
         q0 = qc
         i_l = i_l - 1
      end do
   end if
   res_ = yc
   return
end function getYcritEnum

! xsect.c:1700
recursive function getYcritRidder(xsect_l, q_l, y0_l) result(res_)
   type(TXsect), pointer, intent(in) :: xsect_l
   real(dp), value :: q_l
   real(dp), value :: y0_l
   real(dp) :: res_
   real(dp) :: y1
   real(dp) :: y2
   real(dp) :: yc
   real(dp) :: q0
   real(dp) :: q1
