   y2 = 0.99_dp * xsect_l%yFull
   yc = 0.0_dp
   q0 = 0.0_dp
   q1 = 0.0_dp
   q2 = 0.0_dp
   xsectStar = zero_TXsectStar
   xsectStar%xsect => xsect_l
   xsectStar%qc = 0.0_dp
   q2 = getQcritical(y2, c_loc(xsectStar))
   if (q2 < q_l) then
      res_ = xsect_l%yFull
      return
   end if
   q0 = getQcritical(y0_l, c_loc(xsectStar))
   q1 = getQcritical(0.5_dp * xsect_l%yFull, c_loc(xsectStar))
   if (q0 > q_l) then
      y2 = y0_l
      if (q1 < q_l) then
         y1 = 0.5_dp * xsect_l%yFull
      end if
   else
      y1 = y0_l
      if (q1 > q_l) then
         y2 = 0.5_dp * xsect_l%yFull
      end if
   end if
   xsectStar%qc = q_l
   yc = findroot_Ridder(y1, y2, 0.001_dp, getQcritical, c_loc(xsectStar))
   res_ = yc
   return
end function getYcritRidder

! xsect.c:1755
recursive function rect_closed_getSofA(xsect_l, a_l) result(res_)
