      theta_l = 3.14_dp + ((1.03_dp * (psi - 0.5_dp)) / 0.4_dp)
   else if (psi > 0.015_dp) then
      theta_l = 1.2_dp + ((1.94_dp * (psi - 0.015_dp)) / 0.485_dp)
   else
      theta_l = (0.12103_dp - (55.5075_dp * psi)) + (15.62254_dp * sqrt(psi))
   end if
   theta1 = theta_l
   ap = (2.0_dp * 3.141592654_dp) * psi
   k_l = 1
   do while (k_l <= 40)
      theta_l = abs(theta_l)
      tt = theta_l - sin(theta_l)
      tt23 = tt ** (2.0_dp / 3.0_dp)
      t3 = theta_l ** (1.0_dp / 3.0_dp)
      d_l = ((ap * theta_l) / t3) - (tt * tt23)
      d_l = d_l / (((ap * (2.0_dp / 3.0_dp)) / t3) - (((5.0_dp / 3.0_dp) * tt23) * (1.0_dp - cos(theta_l))))
      theta_l = theta_l - d_l
      if (abs(d_l) <= 0.0001_dp) then
         res_ = theta_l
         return
      end if
      k_l = k_l + 1
   end do
   res_ = theta1
   return
end function getThetaOfPsi

end module swmm5_engine
